/**
 * Bible Book 13: 1 நாளாகமம் (1 Chronicles)
 */
if (typeof window.registerBibleBook === 'function') {
  window.registerBibleBook(13, {"id": 13, "testament": "OT", "code": "1CH", "name_en": "1 Chronicles", "name_ta": "1 நாளாகமம்", "category": "History", "category_ta": "சரித்திரம்", "total_chapters": 29, "chapters": {"1": {"chapter": 1, "duration": 480.21, "audio_url": "audio_ot/OT13_01.mp3", "total_verses": 54, "verses": [{"verse": 1, "start": 4.8, "end": 7.59, "ta": "ஆதாம், சேத், ஏனோஸ்,", "en": "Adam, Sheth, Enosh,"}, {"verse": 2, "start": 7.59, "end": 10.79, "ta": "கேனான், மகலாலெயேல், யாரேத்", "en": "Kenan, Mahalaleel, Jered,"}, {"verse": 3, "start": 10.79, "end": 14.58, "ta": "ஏனோக்கு, மெத்தூசலா, லாமேக்கு,", "en": "Henoch, Methuselah, Lamech,"}, {"verse": 4, "start": 14.58, "end": 18.47, "ta": "நோவா, சேம், காம், யாப்பேத்,", "en": "Noah, Shem, Ham, and Japheth."}, {"verse": 5, "start": 18.47, "end": 30.44, "ta": "யாப்பேத்தின் குமாரர், கோமேர், மாகோகு, மாதாய், யாவான், தூபால், மேசேக்கு, தீராஸ் என்பவர்கள்.", "en": "The sons of Japheth; Gomer, and Magog, and Madai, and Javan, and Tubal, and Meshech, and Tiras."}, {"verse": 6, "start": 30.44, "end": 38.12, "ta": "கோமரின் குமாரர், அஸ்கினாஸ், ரீப்பாத்து, தொகர்மா என்பவர்கள்.", "en": "And the sons of Gomer; Ashchenaz, and Riphath, and Togarmah."}, {"verse": 7, "start": 38.12, "end": 42.31, "ta": "யாவானின் குமாரர், எலிசா, தர்ஷீஸ்,", "en": "And the sons of Javan; Elishah, and Tarshish, Kittim, and Dodanim."}, {"verse": 8, "start": 42.31, "end": 54.49, "ta": "கித்தீம், தொதானீம் என்பவர்கள். காமின் குமாரர், கூஷ், மிஸ்ராயீம், பூத், கானான் என்பவர்கள்.", "en": "The sons of Ham; Cush, and Mizraim, Put, and Canaan."}, {"verse": 9, "start": 54.49, "end": 68.35, "ta": "கூஷின் குமாரர், சேபா, விலா, சப்தா, ராமா, சப்திகா என்பவர்கள்; ராமாவின் குமாரர், சேபா, திதான் என்பவர்கள்.", "en": "And the sons of Cush; Seba, and Havilah, and Sabta, and Raamah, and Sabtecha. And the sons of Raamah; Sheba, and Dedan."}, {"verse": 10, "start": 68.35, "end": 75.84, "ta": "கூஷ் நிம்ரோதைப் பெற்றான்; இவன் பூமியிலே பராக்கிரமசாலியானான்.", "en": "And Cush begat Nimrod: he began to be mighty upon the earth."}, {"verse": 11, "start": 75.84, "end": 84.12, "ta": "மிஸ்ராயீம் லுூதீமியரையும், ஆனாமியரையும், லெகாபியரையும், நப்தூகியரையும்,", "en": "And Mizraim begat Ludim, and Anamim, and Lehabim, and Naphtuhim,"}, {"verse": 12, "start": 84.12, "end": 93.1, "ta": "பத்ரூசியரையும், பெலிஸ்தரைப் பெற்ற கஸ்லுூகியரையும், கப்தோரியரையும் பெற்றான்.", "en": "And Pathrusim, and Casluhim, (of whom came the Philistines,) and Caphthorim."}, {"verse": 13, "start": 93.1, "end": 98.38, "ta": "கானான் தன் மூத்தமகனாகிய சீதோனையும், கேத்தையும்,", "en": "And Canaan begat Zidon his firstborn, and Heth,"}, {"verse": 14, "start": 98.38, "end": 103.47, "ta": "எபூசியரையும், மோரியாயும், கிர்காசியரையும்,", "en": "The Jebusite also, and the Amorite, and the Girgashite,"}, {"verse": 15, "start": 103.47, "end": 108.16, "ta": "ஏவியரையும், அர்கீயரையும், சீநியரையும்,", "en": "And the Hivite, and the Arkite, and the Sinite,"}, {"verse": 16, "start": 108.16, "end": 115.15, "ta": "அர்வாதியரையும், செமரியரையும், காமாத்தியரையும் பெற்றான்.", "en": "And the Arvadite, and the Zemarite, and the Hamathite."}, {"verse": 17, "start": 115.15, "end": 128.32, "ta": "சேமின் குமாரர், ஏலாம், அசூர், அர்பக்சாத், லுூத், ஆராம், ஊத்ஸ், கூல், கேத்தெர், மேசக் என்பவர்கள்.", "en": "The sons of Shem; Elam, and Asshur, and Arphaxad, and Lud, and Aram, and Uz, and Hul, and Gether, and Meshech."}, {"verse": 18, "start": 128.32, "end": 135.0, "ta": "அர்பக்சாத் சாலாவைப் பெற்றான்; சாலா ஏபேரைப் பெற்றான்.", "en": "And Arphaxad begat Shelah, and Shelah begat Eber."}, {"verse": 19, "start": 135.0, "end": 150.37, "ta": "ஏபேருக்கு இரண்டு குமாரர் பிறந்தார்கள்; ஒருவன் பேர் பேலேகு, ஏனெனில் அவன் நாட்களில் பூமி பகுக்கப்பட்டது; அவன் சகோதரன் பேர் யொக்தான்.", "en": "And unto Eber were born two sons: the name of the one was Peleg; because in his days the earth was divided: and his brother’s name was Joktan."}, {"verse": 20, "start": 150.37, "end": 158.25, "ta": "யொக்தான் அல்மோதாதையும், சாலேப்பையும், ஆசர்மாவேத்தையும், யேராகையும்,", "en": "And Joktan begat Almodad, and Sheleph, and Hazarmaveth, and Jerah,"}, {"verse": 21, "start": 158.25, "end": 162.84, "ta": "அதோராமையும், ஊசாலையும், திக்லாவையும்,", "en": "Hadoram also, and Uzal, and Diklah,"}, {"verse": 22, "start": 162.84, "end": 167.43, "ta": "ஓபாலையும், அபிமாவேலையும், சேபாவையும்,", "en": "And Ebal, and Abimael, and Sheba,"}, {"verse": 23, "start": 167.43, "end": 177.9, "ta": "ஓப்பீரையும், ஆவிலாவையும், யோபாபையும் பெற்றான்; இவர்கள் எல்லாரும் யொக்தானின் குமாரர்.", "en": "And Ophir, and Havilah, and Jobab. All these were the sons of Joktan."}, {"verse": 24, "start": 177.9, "end": 181.09, "ta": "சேம், அர்பக்சாத், சாலா,", "en": "Shem, Arphaxad, Shelah,"}, {"verse": 25, "start": 181.09, "end": 183.99, "ta": "ஏபேர், பேலேகு, ரெகூ,", "en": "Eber, Peleg, Reu,"}, {"verse": 26, "start": 183.99, "end": 187.18, "ta": "செரூகு, நாகோர், தேராகு,", "en": "Serug, Nahor, Terah,"}, {"verse": 27, "start": 187.18, "end": 189.48, "ta": "ஆபிராமாகிய ஆபிரகாம்,", "en": "Abram; the same is Abraham."}, {"verse": 28, "start": 189.48, "end": 195.86, "ta": "ஆபிரகாமின் குமாரர், ஈசாக்கு, இஸ்மவேல் என்பவர்கள்.", "en": "The sons of Abraham; Isaac, and Ishmael."}, {"verse": 29, "start": 195.86, "end": 206.04, "ta": "இவர்களுடைய சந்ததிகளாவன: இஸ்மவேலின் மூத்த குமாரனாகிய நெபாயோத், கேதார், அத்பியேல், மிப்சாம்,", "en": "These are their generations: The firstborn of Ishmael, Nebaioth; then Kedar, and Adbeel, and Mibsam,"}, {"verse": 30, "start": 206.04, "end": 210.73, "ta": "மிஷ்மா, தூமா, மாசா, ஆதாத், தேமா,", "en": "Mishma, and Dumah, Massa, Hadad, and Tema,"}, {"verse": 31, "start": 210.73, "end": 219.21, "ta": "யெத்தூர், நாபீஸ், கேத்மா என்பவர்கள்; இவர்கள் இஸ்மவேலின் குமாரர்.", "en": "Jetur, Naphish, and Kedemah. These are the sons of Ishmael."}, {"verse": 32, "start": 219.21, "end": 239.16, "ta": "ஆபிரகாமின் மறுமனையாட்டியாகிய கேத்தூராள் பெற்ற குமாரர், சிம்ரான், யக்ஷான், மேதான், மீதியான், இஸ்பாக், சூவா என்பவர்கள்; யக்ஷானின் குமாரர், சேபா, தேதான் என்பவர்கள்.", "en": "Now the sons of Keturah, Abraham’s concubine: she bare Zimran, and Jokshan, and Medan, and Midian, and Ishbak, and Shuah. And the sons of Jokshan; Sheba, and Dedan."}, {"verse": 33, "start": 239.16, "end": 253.23, "ta": "மீதியானின் குமாரர், ஏப்பா, ஏப்பேர், ஆனோக்கு, அபீதா, எல்தாகா என்பவர்கள்; இவர்கள் எல்லாரும் கேத்துராளின் குமாரர்.", "en": "And the sons of Midian; Ephah, and Epher, and Henoch, and Abida, and Eldaah. All these are the sons of Keturah."}, {"verse": 34, "start": 253.23, "end": 262.21, "ta": "ஆபிரகாம் ஈசாக்கைப் பெற்றான்; ஈசாக்கின் குமாரர், ஏசா இஸ்ரவேல் என்பவர்கள்.", "en": "And Abraham begat Isaac. The sons of Isaac; Esau and Israel."}, {"verse": 35, "start": 262.21, "end": 271.69, "ta": "ஏசாவின் குமாரர், எலீப்பாஸ், ரெகுவேல், எயூஷ், யாலாம், கோராகு என்பவர்கள்.", "en": "The sons of Esau; Eliphaz, Reuel, and Jeush, and Jaalam, and Korah."}, {"verse": 36, "start": 271.69, "end": 283.56, "ta": "எலிப்பாசின் குமாரர், தேமான், ஓமார், செப்பி, கத்தாம், கேனாஸ், திம்னா, அமலேக்கு என்பவர்கள்.", "en": "The sons of Eliphaz; Teman, and Omar, Zephi, and Gatam, Kenaz, and Timna, and Amalek."}, {"verse": 37, "start": 283.56, "end": 291.44, "ta": "ரெகுவேலின் குமாரர், நகாத், சேராகு, சம்மா, மீசா என்பவர்கள்.", "en": "The sons of Reuel; Nahath, Zerah, Shammah, and Mizzah."}, {"verse": 38, "start": 291.44, "end": 303.01, "ta": "சேயீரின் குமாரர், லோத்தான், சோபால், சிபியோன், ஆனா, தீசோன், எத்சேர், தீசான் என்பவர்கள்.", "en": "And the sons of Seir; Lotan, and Shobal, and Zibeon, and Anah, and Dishon, and Ezer, and Dishan."}, {"verse": 39, "start": 303.01, "end": 313.19, "ta": "லோத்தானின் குமாரர், ஓரி, ஓமாம் என்பவர்கள்; லோத்தானின் சகோதரி திம்னாள் என்பவர்கள்.", "en": "And the sons of Lotan; Hori, and Homam: and Timna was Lotan’s sister."}, {"verse": 40, "start": 313.19, "end": 327.86, "ta": "சோபாலின் குமாரர், அல்வான், மானகாத், ஏபால், செப்போ, ஓனாம் என்பவர்கள்; சிபியோனின் குமாரர், அயா, ஆனாகு என்பவர்கள்.", "en": "The sons of Shobal; Alian, and Manahath, and Ebal, Shephi, and Onam. And the sons of Zibeon; Aiah, and Anah."}, {"verse": 41, "start": 327.86, "end": 340.63, "ta": "ஆனாகின் குமாரரில் ஒருவன் திஷோன் என்பவன்; திஷோனின் குமாரர், அம்ராம், எஸ்பான் இத்தரான், கெரான் என்பவர்கள்.", "en": "The sons of Anah; Dishon. And the sons of Dishon; Amram, and Eshban, and Ithran, and Cheran."}, {"verse": 42, "start": 340.63, "end": 353.6, "ta": "ஏத்சேரின் குமாரர், பில்கான், சகவான், யாக்கான் என்பவர்கள்; திஷானின் குமாரர், ஊத்ஸ், அரான் என்பவர்கள்.", "en": "The sons of Ezer; Bilhan, and Zavan, and Jakan. The sons of Dishan; Uz, and Aran."}, {"verse": 43, "start": 353.6, "end": 370.06, "ta": "இஸ்ரவேல் புத்திரரை ஒரு ராஜா ஆளாததற்கு முன்னே, ஏதோம் தேசத்தில் அரசாண்ட ராஜாக்களானவர்கள் பயோரின குமாரன் பேலா என்பவன்; இவன் பட்டணத்தின் பேர் தின்காபா.", "en": "Now these are the kings that reigned in the land of Edom before any king reigned over the children of Israel; Bela the son of Beor: and the name of his city was Dinhabah."}, {"verse": 44, "start": 370.06, "end": 379.34, "ta": "பேலா மரித்தபின் போஸ்ரா ஊரானாகிய சேராகின் குமாரன் யோபாப் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And when Bela was dead, Jobab the son of Zerah of Bozrah reigned in his stead."}, {"verse": 45, "start": 379.34, "end": 388.32, "ta": "யோபாப் மரித்தபின், தேமானியரின் தேசத்தானாகிய ஊசாம் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And when Jobab was dead, Husham of the land of the Temanites reigned in his stead."}, {"verse": 46, "start": 388.32, "end": 405.28, "ta": "ஊசாம் மரித்தபின், பேதாதின் குமாரன் ஆதாத் அவன் ஸ்தானத்தில் ராஜாவானான், இவன் மீதியானியரை மோவாபின் நாட்டிலே முறிய அடித்தவன்; இவன் பட்டணத்தின்பேர் ஆவீத்.", "en": "And when Husham was dead, Hadad the son of Bedad, which smote Midian in the field of Moab, reigned in his stead: and the name of his city was Avith."}, {"verse": 47, "start": 405.28, "end": 413.56, "ta": "ஆதாத் மரித்தபின், மஸ்ரேக்கா ஊரானாகிய சம்லா அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And when Hadad was dead, Samlah of Masrekah reigned in his stead."}, {"verse": 48, "start": 413.56, "end": 422.54, "ta": "சம்லா மரித்தபின், நதியோரமான ரேகோபோத்தானாகிய சவுல் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And when Samlah was dead, Shaul of Rehoboth by the river reigned in his stead."}, {"verse": 49, "start": 422.54, "end": 431.22, "ta": "சவுல் மரித்தபின், அக்போரின் குமாரன் பாகாலானான் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And when Shaul was dead, Baal-hanan the son of Achbor reigned in his stead."}, {"verse": 50, "start": 431.22, "end": 450.38, "ta": "பாகாலானான் மரித்தபின், ஆதாத், அவன் ஸ்தானத்தில் ராஜாவானான்; இவன் பட்டணத்தின்பேர் பாகி; மேசகாபின் குமாரத்தியாகிய மாத்திரேத்தின் குமாரனான அவன் மனைவியின் பேர் மெகேதபேல்.", "en": "And when Baal-hanan was dead, Hadad reigned in his stead: and the name of his city was Pai; and his wife’s name was Mehetabel, the daughter of Matred, the daughter of Mezahab."}, {"verse": 51, "start": 450.38, "end": 461.35, "ta": "ஆதாத் மரித்தபின், ஏதோமில் ஏற்பட்ட பிரபுக்களானவர்கள்; திம்னா பிரபு, அல்யா பிரபு, எதேத் பிரபு,", "en": "Hadad died also. And the dukes of Edom were; duke Timnah, duke Aliah, duke Jetheth,"}, {"verse": 52, "start": 461.35, "end": 466.34, "ta": "அகோலிபாமா பிரபு, ஏலா பிரபு, பினோன் பிரபு,", "en": "Duke Aholibamah, duke Elah, duke Pinon,"}, {"verse": 53, "start": 466.34, "end": 471.53, "ta": "கேனாஸ் பிரபு, தேமான் பிரபு, மிப்சார் பிரபு,", "en": "Duke Kenaz, duke Teman, duke Mibzar,"}, {"verse": 54, "start": 471.53, "end": 478.71, "ta": "மக்தியேல் பிரபு, ஈராம் பிரபு, இவர்களே ஏதோமின் பிரபுக்கள்.", "en": "Duke Magdiel, duke Iram. These are the dukes of Edom."}]}, "2": {"chapter": 2, "duration": 539.52, "audio_url": "audio_ot/OT13_02.mp3", "total_verses": 55, "verses": [{"verse": 1, "start": 3.8, "end": 11.83, "ta": "இஸ்ரவேலின் குமாரர், ரூபன், சிமியோன், லேவி, யூதா, இசக்கார், செபுலோன்,", "en": "These are the sons of Israel; Reuben, Simeon, Levi, and Judah, Issachar, and Zebulun,"}, {"verse": 2, "start": 11.83, "end": 19.23, "ta": "தாண், யோசேப்பு, பென்யமீன், நப்தலி, காத், ஆசேர் என்பவர்கள்.", "en": "Dan, Joseph, and Benjamin, Naphtali, Gad, and Asher."}, {"verse": 3, "start": 19.23, "end": 43.31, "ta": "யூதாவின் குமாரர், ஏர், ஓனான், சேலா என்பவர்கள்; இந்த மூன்று குமாரர் சூவாவின் மகளான கானான் ஸ்திரீயினிடத்தில் அவனுக்குப் பிறந்தவர்கள்; ஏர் என்னும் யூதாவின் மூத்த குமாரன் கர்த்தரின் பார்வைக்குப் பொல்லாதவனானபடியால் அவர் அவனைக் கொன்றுபோட்டார்.", "en": "The sons of Judah; Er, and Onan, and Shelah: which three were born unto him of the daughter of Shua the Canaanitess. And Er, the firstborn of Judah, was evil in the sight of the LORD ; and he slew him."}, {"verse": 4, "start": 43.31, "end": 53.78, "ta": "அவன் மருமகளாகிய தாமார் அவனுக்கு பாரேசையும் சேராவையும் பெற்றாள்; யூதாவின் குமாரர் எல்லாரும் ஐந்துபேர்.", "en": "And Tamar his daughter in law bare him Pharez and Zerah. All the sons of Judah were five."}, {"verse": 5, "start": 53.78, "end": 59.1, "ta": "பாரேசின் குமாரர், எஸ்ரோன், ஆமூல் என்பவர்கள்.", "en": "The sons of Pharez; Hezron, and Hamul."}, {"verse": 6, "start": 59.1, "end": 68.84, "ta": "சேராவின் குமாரர் எல்லாரும், சிம்ரி, ஏத்தான், ஏமான், கல்கோல், தாரா என்னும் ஐந்துபேர்.", "en": "And the sons of Zerah; Zimri, and Ethan, and Heman, and Calcol, and Dara: five of them in all."}, {"verse": 7, "start": 68.84, "end": 78.94, "ta": "சாபத்தீடான விஷயத்திலே துரோகம்பண்ணி இஸ்ரவேலைக் கலங்கப்பண்ணின ஆகார் என்பவன், கர்மீ புத்திரரில் ஒருவன்.", "en": "And the sons of Carmi; Achar, the troubler of Israel, who transgressed in the thing accursed."}, {"verse": 8, "start": 78.94, "end": 83.18, "ta": "ஏத்தானின் குமாரர் அசரியா முதலானவர்கள்.", "en": "And the sons of Ethan; Azariah."}, {"verse": 9, "start": 83.18, "end": 90.67, "ta": "எஸ்ரோனுககுப் பிறந்த குமாரர், யெர்மெயேல், ராம், கெலுபா என்பவர்கள்.", "en": "The sons also of Hezron, that were born unto him; Jerahmeel, and Ram, and Chelubai."}, {"verse": 10, "start": 90.67, "end": 99.69, "ta": "ராம் அம்மினதாபைப் பெற்றான்; அம்மினதாப் யூதா புத்திரரின் பிரபுவாகிய நகசோனைப் பெற்றான்.", "en": "And Ram begat Amminadab; and Amminadab begat Nahshon, prince of the children of Judah;"}, {"verse": 11, "start": 99.69, "end": 105.65, "ta": "நகசோன் சல்மாவைப் பெற்றான்; சல்மா போவாசைப் பெற்றான்.", "en": "And Nahshon begat Salma, and Salma begat Boaz,"}, {"verse": 12, "start": 105.65, "end": 111.33, "ta": "போவாஸ் ஓபேதைப் பெற்றான்; ஓபேத் ஈசாயைப் பெற்றான்.", "en": "And Boaz begat Obed, and Obed begat Jesse,"}, {"verse": 13, "start": 111.33, "end": 122.24, "ta": "ஈசாய் தன் மூத்த குமாரன் எலியாபையும், அபினதாப் என்னும் இரண்டாம் குமாரனையும், சிம்மா என்னும் மூன்றாம் குமாரனையும்,", "en": "And Jesse begat his firstborn Eliab, and Abinadab the second, and Shimma the third,"}, {"verse": 14, "start": 122.24, "end": 129.19, "ta": "நெதனயேல் என்னும் நாலாம் குமாரனையும், ரதாயி என்னும் ஐந்தாம் குமாரனையும்,", "en": "Nethaneel the fourth, Raddai the fifth,"}, {"verse": 15, "start": 129.19, "end": 137.22, "ta": "ஓத்சேம் என்னும் ஆறாம் குமாரனையும், தாவீது என்னும் ஏழாம் குமாரனையும் பெற்றான்.", "en": "Ozem the sixth, David the seventh:"}, {"verse": 16, "start": 137.22, "end": 149.85, "ta": "அவர்கள் சகோதரிகள் செருயாள், அபிகாயில் என்பவர்கள்; செருயாளின் குமாரர், அபிசாய், யோவாப், ஆசகேல் என்னும் மூன்றுபேர்.", "en": "Whose sisters were Zeruiah, and Abigail. And the sons of Zeruiah; Abishai, and Joab, and Asahel, three."}, {"verse": 17, "start": 149.85, "end": 158.42, "ta": "அபிகாயில் அமாசாவைப் பெற்றாள்; அமாசாவின் தகப்பன் இஸ்மவேலியனாகிய யெத்தேர் என்பவன்.", "en": "And Abigail bare Amasa: and the father of Amasa was Jether the Ishmeelite."}, {"verse": 18, "start": 158.42, "end": 170.96, "ta": "எஸ்ரோனின் குமாரன் காலேப் எரீயோத் என்னப்பட்ட தன் பெண்ஜாதியாகிய அசுபாளாலே பெற்ற குமாரர், ஏசேர், சோபாப், அர்தோன் என்பவர்கள்.", "en": "And Caleb the son of Hezron begat children of Azubah his wife, and of Jerioth: her sons are these; Jesher, and Shobab, and Ardon."}, {"verse": 19, "start": 170.96, "end": 180.07, "ta": "அசுபாள் சென்றுபோனபின் காலேப் எப்ராத்தை விவாகம்பண்ணினான்; இவள் அவனுக்கு ஊரைப் பெற்றாள்.", "en": "And when Azubah was dead, Caleb took unto him Ephrath, which bare him Hur."}, {"verse": 20, "start": 180.07, "end": 185.66, "ta": "ஊர் ஊரியைப் பெற்றான்; ஊரி பெசலெயேலைப் பெற்றான்.", "en": "And Hur begat Uri, and Uri begat Bezaleel."}, {"verse": 21, "start": 185.66, "end": 201.54, "ta": "பிற்பாடு, எஸ்ரோன் அறுபது வயதானபோது கிலெயாத்தின் தகப்பனாகிய மாகீரின் குமாரத்தியை விவாகம்பண்ணி, அவளிடத்தில் பிரவேசித்தான்; இவள் அவனுக்குச் செகூபைப் பெற்றாள்.", "en": "And afterward Hezron went in to the daughter of Machir the father of Gilead, whom he married when he was threescore years old; and she bare him Segub."}, {"verse": 22, "start": 201.54, "end": 210.74, "ta": "செகூப் யாவீரைப் பெற்றான்; இவனுக்குக் கீலேயாத் தேசத்தில் இருபத்துமூன்று ஊர்கள் இருந்தது.", "en": "And Segub begat Jair, who had three and twenty cities in the land of Gilead."}, {"verse": 23, "start": 210.74, "end": 228.69, "ta": "கேசூரையும் ஆராமையும் யாவீரின் கிராமங்களையும், கேனாத்திலுள்ள கிராமங்களாகிய அறுபது ஊர்களையும் அவர்கள் கையிலே வாங்கினார்கள்; இவர்கள் எல்லாரும் கிலெயாத்தின் தகப்பனாகிய மாகீரின் குமாரர்.", "en": "And he took Geshur, and Aram, with the towns of Jair, from them, with Kenath, and the towns thereof, even threescore cities. All these belonged to the sons of Machir the father of Gilead."}, {"verse": 24, "start": 228.69, "end": 241.95, "ta": "காலேபின் ஊரான எப்ராத்தாவில் எஸ்ரோன் இறந்துபோனபின், எஸ்ரோனின் பெண்ஜாதியாகிய அபியாள் அவனுக்குத் தெக்கொவாவின் தகப்பனாகிய அசூரைப் பெற்றாள்.", "en": "And after that Hezron was dead in Caleb-ephratah, then Abiah Hezron’s wife bare him Ashur the father of Tekoa."}, {"verse": 25, "start": 241.95, "end": 254.22, "ta": "எஸ்ரோனுக்கு முதற்பிறந்த யெர்மெயேலின் குமாரர், ராம் என்னும் மூத்தவனும், பூனா, ஓரென், ஓத்சேம், அகியா என்பவர்களுமே.", "en": "And the sons of Jerahmeel the firstborn of Hezron were, Ram the firstborn, and Bunah, and Oren, and Ozem, and Ahijah."}, {"verse": 26, "start": 254.22, "end": 263.42, "ta": "அத்தாராள் என்னும் பேருள்ள வேறொரு மனைவியும் யெர்மெயேலுக்கு இருந்தாள்; இவள் ஓனாமின் தாய்.", "en": "Jerahmeel had also another wife, whose name was Atarah; she was the mother of Onam."}, {"verse": 27, "start": 263.42, "end": 271.9, "ta": "யெர்மெயேலுக்கு முதற்பிறந்த ராமின் குமாரர், மாஸ், யாமின், எக்கேர் என்பவர்கள்.", "en": "And the sons of Ram the firstborn of Jerahmeel were, Maaz, and Jamin, and Eker."}, {"verse": 28, "start": 271.9, "end": 282.37, "ta": "ஓனாமின் குமாரர், சம்மாய், யாதா என்பவர்கள்; சம்மாயின் குமாரர், நாதாப், அபிசூர் என்பவர்கள்.", "en": "And the sons of Onam were, Shammai, and Jada. And the sons of Shammai; Nadab, and Abishur."}, {"verse": 29, "start": 282.37, "end": 291.21, "ta": "அபிசூருடைய மனைவியின் பேர் அபியாயேல்; அவள் அவனுக்கு அக்பானையும் மோளிதையும் பெற்றாள்.", "en": "And the name of the wife of Abishur was Abihail, and she bare him Ahban, and Molid."}, {"verse": 30, "start": 291.21, "end": 300.5, "ta": "நாதாபின் குமாரர், சேலேத், அப்பாயிம் என்பவர்கள்; சேலேத் புத்திரரில்லாமல் மரித்தான்.", "en": "And the sons of Nadab; Seled, and Appaim: but Seled died without children."}, {"verse": 31, "start": 300.5, "end": 311.59, "ta": "அப்பாயிமின் குமாரர் இஷி முதலானவர்கள்; இஷியின் குமாரர் சேசான் முதலானவர்கள்; சேசானின் குமாரத்தி அக்லாய்.", "en": "And the sons of Appaim; Ishi. And the sons of Ishi; Sheshan. And the children of Sheshan; Ahlai."}, {"verse": 32, "start": 311.59, "end": 322.96, "ta": "சம்மாயின் சகோதரனாகிய யாதாவின் குமாரர், யெத்தெர், யோனத்தான் என்பவர்கள்; யெத்தெர் குமாரரில்லாமல் மரித்தான்.", "en": "And the sons of Jada the brother of Shammai; Jether, and Jonathan: and Jether died without children."}, {"verse": 33, "start": 322.96, "end": 331.35, "ta": "யோனத்தானின் குமாரர், பேலேத்சாசா என்பவர்கள்; இவர்கள் யெர்மெயேலின் புத்திரர்.", "en": "And the sons of Jonathan; Peleth, and Zaza. These were the sons of Jerahmeel."}, {"verse": 34, "start": 331.35, "end": 343.53, "ta": "சேசானுக்குக் குமாரத்திகளேயன்றி குமாரர்கள் இல்லை; சேசானுக்கு யர்கா என்னும் பேருள்ள எகிப்திய வேலைக்காரன் ஒருவன் இருந்தான்.", "en": "Now Sheshan had no sons, but daughters. And Sheshan had a servant, an Egyptian, whose name was Jarha."}, {"verse": 35, "start": 343.53, "end": 354.26, "ta": "சேசான் தன் குமாரத்தியைத் தன் வேலைக்காரனாகிய யாகாவுக்குக் கொடுத்தான்; அவள் அவனுக்கு அத்தாயியைப் பெற்றாள்.", "en": "And Sheshan gave his daughter to Jarha his servant to wife; and she bare him Attai."}, {"verse": 36, "start": 354.26, "end": 360.58, "ta": "அத்தாயி நாதானைப் பெற்றான். நாதான் சாபாதைப் பெற்றான்.", "en": "And Attai begat Nathan, and Nathan begat Zabad,"}, {"verse": 37, "start": 360.58, "end": 366.62, "ta": "சாபாத் எப்லாலைப் பெற்றான்; எப்லால் ஒபேதைப் பெற்றான்.", "en": "And Zabad begat Ephlal, and Ephlal begat Obed,"}, {"verse": 38, "start": 366.62, "end": 372.31, "ta": "ஓபேத் ஏகூவைப் பெற்றான்; ஏகூ அசரியாவைப் பெற்றான்.", "en": "And Obed begat Jehu, and Jehu begat Azariah,"}, {"verse": 39, "start": 372.31, "end": 378.71, "ta": "அசரியா ஏலேத்சைப் பெற்றான்; ஏலேத்ஸ் எலெயாசாவைப் பெற்றான்.", "en": "And Azariah begat Helez, and Helez begat Eleasah,"}, {"verse": 40, "start": 378.71, "end": 385.3, "ta": "எலெயாசா சிஸ்மாயைப் பெற்றான்; சிஸ்மாய் சல்லுூமைப் பெற்றான்.", "en": "And Eleasah begat Sisamai, and Sisamai begat Shallum,"}, {"verse": 41, "start": 385.3, "end": 392.24, "ta": "சல்லுூம் எக்கமியாவைப் பெற்றான்; எக்கமியா எலிசாமாவைப் பெற்றான்.", "en": "And Shallum begat Jekamiah, and Jekamiah begat Elishama."}, {"verse": 42, "start": 392.24, "end": 405.41, "ta": "யெர்மெயேலின் சகோதரனாகிய காலேபின் குமாரர், சீப்பின் தகப்பனாகிய மேசா என்னும் முதற்பிறந்தவனும் எப்ரோனின் தகப்பனாகிய மெரோசாவின் குமாரருமே.", "en": "Now the sons of Caleb the brother of Jerahmeel were , Mesha his firstborn, which was the father of Ziph; and the sons of Mareshah the father of Hebron."}, {"verse": 43, "start": 405.41, "end": 412.54, "ta": "எப்ரோனின் குமாரர், கோராகு, தப்புவா, ரெக்கேம் செமா என்பவர்கள்.", "en": "And the sons of Hebron; Korah, and Tappuah, and Rekem, and Shema."}, {"verse": 44, "start": 412.54, "end": 421.11, "ta": "செமா யோர்க்கேயாமின் தகப்பனாகிய ரெக்கேமைப் பெற்றான்; ரெக்கேம் சம்மாயைப் பெற்றான்.", "en": "And Shema begat Raham, the father of Jorkoam: and Rekem begat Shammai."}, {"verse": 45, "start": 421.11, "end": 427.15, "ta": "சம்மாயின் குமாரன் மாகோன்; மாகோன் பெத்சூரின் தகப்பன்.", "en": "And the son of Shammai was Maon: and Maon was the father of Beth-zur."}, {"verse": 46, "start": 427.15, "end": 437.98, "ta": "காலேபின் மறுமனையாட்டியாகிய எப்பாள் ஆரானையும் மோசாவையும், காசேசையும் பெற்றாள்; ஆரான் காசேசைப் பெற்றான்.", "en": "And Ephah, Caleb’s concubine, bare Haran, and Moza, and Gazez: and Haran begat Gazez."}, {"verse": 47, "start": 437.98, "end": 447.18, "ta": "யாதாயின் குமாரர், ரேகேம், யோதாம், கேசாம், பேலேத், எப்பா, சாகாப் என்பவர்கள்.", "en": "And the sons of Jahdai; Regem, and Jotham, and Geshan, and Pelet, and Ephah, and Shaaph."}, {"verse": 48, "start": 447.18, "end": 454.22, "ta": "காலேபின் மறுமனையாட்டியாகிய மாகாள் சேபேரையும் திர்கானாவையும் பெற்றாள்.", "en": "Maachah, Caleb’s concubine, bare Sheber, and Tirhanah."}, {"verse": 49, "start": 454.22, "end": 468.38, "ta": "அவள் மத்மன்னாவின் தகப்பனாகிய சாகாபையும், மக்பேனாவுக்கும் கீபேயாவுக்கும் தகப்பனாகிய சேவாவையும் பெற்றாள்; காலேபின் குமாரத்தி அக்சாள் என்பவள்.", "en": "She bare also Shaaph the father of Madmannah, Sheva the father of Machbenah, and the father of Gibea: and the daughter of Caleb was Achsah."}, {"verse": 50, "start": 468.38, "end": 478.12, "ta": "எப்ராத்தாளிடத்தில் முதற்பிறந்த ஊருடைய குமாரனாகிய காலேபின் குமாரர், கீரியாத்யாரீமின் மூப்பனான சோபாலும்,", "en": "These were the sons of Caleb the son of Hur, the firstborn of Ephratah; Shobal the father of Kirjath-jearim,"}, {"verse": 51, "start": 478.12, "end": 485.07, "ta": "பெத்லெகேமின் மூப்பனான சல்மாவும், பெத்காதேரின் மூப்பனான ஆரேப்புமே.", "en": "Salma the father of Beth-lehem, Hareph the father of Beth-gader."}, {"verse": 52, "start": 485.07, "end": 493.46, "ta": "கீரியாத்யாரிமின் மூப்பனான சோபாலின் குமாரர், ஆரோவே, ஆசியம் மெனுகோத் என்பவர்கள்.", "en": "And Shobal the father of Kirjath-jearim had sons; Haroeh, and half of the Manahethites."}, {"verse": 53, "start": 493.46, "end": 508.16, "ta": "கீரியாத்யாரிமிலிருந்த வம்சங்கள், எத்திரியரும் பூகியரும் சுமாத்தியரும் மிஸ்ராவியருமே; இவர்களிடத்தில் சோராத்தியரும், எஸ்தவோலியரும் பிறந்தார்கள்.", "en": "And the families of Kirjath-jearim; the Ithrites, and the Puhites, and the Shumathites, and the Mishraites; of them came the Zareathites, and the Eshtaulites."}, {"verse": 54, "start": 508.16, "end": 522.32, "ta": "சல்மாவின் சந்ததிகள், பெத்லெகேமியரும், நேத்தோப்பாத்தியரும், பெத்யோவாப் என்னும் அதரோத் ஊராரும், மானாத்தியரிலும் சோரியரிலும் பாதிஜனங்களுமே.", "en": "The sons of Salma; Beth-lehem, and the Netophathites, Ataroth, the house of Joab, and half of the Manahethites, the Zorites."}, {"verse": 55, "start": 522.32, "end": 538.02, "ta": "யாபேசில் குடியிருந்த கணக்கரின் வம்சங்கள், திராத்தியரும் சிமாத்தியரும் சுக்காத்தியருமே; ரேகாப் வீட்டாரின் தகப்பனாகிய அம்மாத்தின் சந்ததியாரான கேனியர் இவர்களே.", "en": "And the families of the scribes which dwelt at Jabez; the Tirathites, the Shimeathites, and Suchathites. These are the Kenites that came of Hemath, the father of the house of Rechab."}]}, "3": {"chapter": 3, "duration": 258.38, "audio_url": "audio_ot/OT13_03.mp3", "total_verses": 24, "verses": [{"verse": 1, "start": 3.8, "end": 21.31, "ta": "தாவீதுக்கு எப்ரோனிலே பிறந்த குமாரர்: யெஸ்ரெயேல் ஊராளான அகினோவாமிடத்தில் பிறந்த அம்னோன் முதற்பேறானவன்; கர்மேலின் ஊராளான அபிகாயேலிடத்தில் பிறந்த தானியேல் இரண்டாம் குமாரன்.", "en": "Now these were the sons of David, which were born unto him in Hebron; the firstborn Amnon, of Ahinoam the Jezreelitess; the second Daniel, of Abigail the Carmelitess:"}, {"verse": 2, "start": 21.31, "end": 33.77, "ta": "கேசூரின் ராஜாவாகிய தல்மாயின் குமாரத்தி மாக்காள் பெற்ற அப்சலோம் மூன்றாம் குமாரன்; ஆகீத் பெற்ற அதோனியா நாலாம் குமாரன்.", "en": "The third, Absalom the son of Maachah the daughter of Talmai king of Geshur: the fourth, Adonijah the son of Haggith:"}, {"verse": 3, "start": 33.77, "end": 44.9, "ta": "அபித்தாள் பெற்ற செப்பத்தியா ஐந்தாம் குமாரன்; அவன் பெண்ஜாதியாகிய எக்லாள் பெற்ற இத்ரேயாம் ஆறாம் குமாரன்.", "en": "The fifth, Shephatiah of Abital: the sixth, Ithream by Eglah his wife."}, {"verse": 4, "start": 44.9, "end": 59.84, "ta": "இந்த ஆறு குமாரர் அவனுக்கு எப்ரோனிலே பிறந்தார்கள்; அங்கே ஏழுவருஷமும் ஆறுமாதமும் அரசாண்டான்; எருசலேமிலோ முப்பத்துமூன்று வருஷம் அரசாண்டான்.", "en": "These six were born unto him in Hebron; and there he reigned seven years and six months: and in Jerusalem he reigned thirty and three years."}, {"verse": 5, "start": 59.84, "end": 73.73, "ta": "எருசலேமில் அவனுக்குப் பிறந்தவர்கள்: அம்மியேலின் குமாரத்தியாகிய பத்சுவாளிடத்தில் சிமீயா, சோபாப், நாத்தான், சாலொமோன் என்னும் நாலுபேரும்,", "en": "And these were born unto him in Jerusalem; Shimea, and Shobab, and Nathan, and Solomon, four, of Bath-shua the daughter of Ammiel:"}, {"verse": 6, "start": 73.73, "end": 77.44, "ta": "இப்கார், எலிசாமா, எலிப்பெலேத்,", "en": "Ibhar also, and Elishama, and Eliphelet,"}, {"verse": 7, "start": 77.44, "end": 80.39, "ta": "நோகா, நேபேக், யப்பியா,", "en": "And Nogah, and Nepheg, and Japhia,"}, {"verse": 8, "start": 80.39, "end": 86.48, "ta": "எலிசாமா, எலியாதா, எலிபேலேத் என்னும் ஒன்பதுபேருமே.", "en": "And Elishama, and Eliada, and Eliphelet, nine."}, {"verse": 9, "start": 86.48, "end": 97.14, "ta": "மறுமனையாட்டிகளின் குமாரரையும் இவர்கள் சகோதரியாகிய தாமாரையும் தவிர, இவர்களெல்லாரும் தாவீதின் குமாரர்.", "en": "These were all the sons of David, beside the sons of the concubines, and Tamar their sister."}, {"verse": 10, "start": 97.14, "end": 109.12, "ta": "சாலொமோனின் குமாரன் ரெகொபெயாம்; இவனுடைய குமாரன் அபியா; இவனுடைய குமாரன் ஆசா; இவனுடைய குமாரன் யோசபாத்.", "en": "And Solomon’s son was Rehoboam, Abia his son, Asa his son, Jehoshaphat his son,"}, {"verse": 11, "start": 109.12, "end": 117.88, "ta": "இவனுடைய குமாரன் யோராம்; இவனுடைய குமாரன் அகசியா; இவனுடைய குமாரன் யோவாஸ்.", "en": "Joram his son, Ahaziah his son, Joash his son,"}, {"verse": 12, "start": 117.88, "end": 126.82, "ta": "இவனுடைய குமாரன் அமத்சியா; இவனுடைய குமாரன் அசரியா; இவனுடைய குமாரன் யோதாம்.", "en": "Amaziah his son, Azariah his son, Jotham his son,"}, {"verse": 13, "start": 126.82, "end": 135.67, "ta": "இவனுடைய குமாரன் ஆகாஸ்; இவனுடைய குமாரன் எசேக்கியா; இவனுடைய குமாரன் மனாசே.", "en": "Ahaz his son, Hezekiah his son, Manasseh his son,"}, {"verse": 14, "start": 135.67, "end": 141.47, "ta": "இவனுடைய குமாரன் ஆமோன்; இவனுடைய குமாரன் யோசியா.", "en": "Amon his son, Josiah his son."}, {"verse": 15, "start": 141.47, "end": 158.31, "ta": "யோசியாவின் குமாரர், முதல் பிறந்த யோகனானும், யோயாக்கீம் என்னும் இரண்டாம் குமாரனும், சிதேக்கியா என்னும் மூன்றாம் குமாரனும், சல்லுூம் என்னும் நாலாம் குமாரனுமே.", "en": "And the sons of Josiah were , the firstborn Johanan, the second Jehoiakim, the third Zedekiah, the fourth Shallum."}, {"verse": 16, "start": 158.31, "end": 166.97, "ta": "யோயாக்கீமின் குமாரர், எகொனியா முதலானவர்கள்; இவனுக்கு மகனானவன் சிதேக்கியா.", "en": "And the sons of Jehoiakim: Jeconiah his son, Zedekiah his son."}, {"verse": 17, "start": 166.97, "end": 171.16, "ta": "கட்டுண்ட எகொனியாவின் குமாரர் சலாத்தியேல்,", "en": "And the sons of Jeconiah; Assir, Salathiel his son,"}, {"verse": 18, "start": 171.16, "end": 179.53, "ta": "மல்கீராம், பெதாயா, சேனாசார், யெகமியா, ஒசாமா, நெதபியா என்பவர்கள்.", "en": "Malchiram also, and Pedaiah, and Shenazar, Jecamiah, Hoshama, and Nedabiah."}, {"verse": 19, "start": 179.53, "end": 195.61, "ta": "பெதாயாவின் குமாரர், செருபாபேல், சிமேயி என்பவர்கள்; செருபாபேலின் குமாரர், மெசுல்லாம், அனனியா என்பவர்கள்; இவர்கள் சகோதரி செலோமீத் என்பவள்.", "en": "And the sons of Pedaiah were , Zerubbabel, and Shimei: and the sons of Zerubbabel; Meshullam, and Hananiah, and Shelomith their sister:"}, {"verse": 20, "start": 195.61, "end": 203.41, "ta": "அசூபா, ஒகேல், பெரகியா, அசதியா, ஊசாபேசேத் என்னும் ஐந்துபேருமே.", "en": "And Hashubah, and Ohel, and Berechiah, and Hasadiah, Jushab-hesed, five."}, {"verse": 21, "start": 203.41, "end": 221.3, "ta": "அனனியாவின் குமாரர், பெலேத்தியா, எசாயா என்பவர்கள்; இவனுடைய குமாரன் ரெபாயா; இவனுடைய குமாரன் அர்னான்; இவனுடைய குமாரன் ஒபதியா; இவனுடைய குமாரன் செக்கனியா.", "en": "And the sons of Hananiah; Pelatiah, and Jesaiah: the sons of Rephaiah, the sons of Arnan, the sons of Obadiah, the sons of Shechaniah."}, {"verse": 22, "start": 221.3, "end": 236.33, "ta": "செக்கனியாவின் குமாரர், செமாயா முதலானவர்கள்; செமாயாவின் குமாரர், அத்தூஸ், எகெயால், பாரியா, நெயாரியா, செப்பாத் என்னும் ஆறுபேர்.", "en": "And the sons of Shechaniah; Shemaiah: and the sons of Shemaiah; Hattush, and Igeal, and Bariah, and Neariah, and Shaphat, six."}, {"verse": 23, "start": 236.33, "end": 244.99, "ta": "நெயாரியாவின் குமாரர், எலியோய், எசேக்கியா, அஸ்ரீக்காம் என்னும் மூன்றுபேர்.", "en": "And the sons of Neariah; Elioenai, and Hezekiah, and Azrikam, three."}, {"verse": 24, "start": 244.99, "end": 256.88, "ta": "எலியோனாயின் குமாரர், ஒதாயா, எலியாசிப், பெலாயா, அக்கூப், யோகனான், தெலாயா, ஆனானி என்னும் ஏழுபேர்.", "en": "And the sons of Elioenai were , Hodaiah, and Eliashib, and Pelaiah, and Akkub, and Johanan, and Dalaiah, and Anani, seven."}]}, "4": {"chapter": 4, "duration": 497.19, "audio_url": "audio_ot/OT13_04.mp3", "total_verses": 43, "verses": [{"verse": 1, "start": 3.8, "end": 11.59, "ta": "யூதாவின் குமாரர், பாரேஸ், எஸ்ரோன், கர்மீ, ஊர், சோபால் என்பவர்கள்.", "en": "The sons of Judah; Pharez, Hezron, and Carmi, and Hur, and Shobal."}, {"verse": 2, "start": 11.59, "end": 23.58, "ta": "சோபாலின் குமாரன் ராயா யாகாத்தைப் பெற்றான்; யாகாத் அகுமாயியையும் லாகாதையும் பெற்றான்; சோராத்தியரின் வம்சங்கள் இவைகளே.", "en": "And Reaiah the son of Shobal begat Jahath; and Jahath begat Ahumai, and Lahad. These are the families of the Zorathites."}, {"verse": 3, "start": 23.58, "end": 35.57, "ta": "ஏதாம் என்னும் மூப்பனின் சந்ததியார், யெஸ்ரெயேல், இஷ்மா, இத்பாஸ் என்பவர்கள்; இவர்களுடைய சகோதரியின் பேர் அத்செலெல்போனி;", "en": "And these were of the father of Etam; Jezreel, and Ishma, and Idbash: and the name of their sister was Hazelelponi:"}, {"verse": 4, "start": 35.57, "end": 49.48, "ta": "கேதோருக்கு மூப்பனான பெனுவெல், உஷாவுக்கு மூப்பனான எசேர் என்பவர்கள்; இவர்கள் பெத்லெகேமுக்கு மூப்பனான எப்ராத்தாவுக்கு முதற்பிறந்த ஊரின் குமாரர்.", "en": "And Penuel the father of Gedor, and Ezer the father of Hushah. These are the sons of Hur, the firstborn of Ephratah, the father of Beth-lehem."}, {"verse": 5, "start": 49.48, "end": 58.23, "ta": "தெக்கோவாவுக்கு மூப்பனான அசூருக்கு ஏலாள், நாராள் என்னும் இரண்டு பெண்ஜாதிகள் இருந்தார்கள்.", "en": "And Ashur the father of Tekoa had two wives, Helah and Naarah."}, {"verse": 6, "start": 58.23, "end": 69.78, "ta": "நாராள் அவனுக்கு அகுசாமையும், எப்பேரையும், தெமனியையும, ஆகாஸ்தாரியையும் பெற்றாள்; நாராளின் குமாரர்கள் இவர்களே.", "en": "And Naarah bare him Ahuzam, and Hepher, and Temeni, and Haahashtari. These were the sons of Naarah."}, {"verse": 7, "start": 69.78, "end": 76.17, "ta": "ஏலாளின் குமாரர், சேரேத், எத்சோகார், எத்னான் என்பவர்கள்.", "en": "And the sons of Helah were , Zereth, and Jezoar, and Ethnan."}, {"verse": 8, "start": 76.17, "end": 85.45, "ta": "கோஸ் என்பவன் அனூபையும், சோபேபாகையும், ஆருமின் குமாரனாகிய அகர்கேலின் வம்சங்களையும் பெற்றான்.", "en": "And Coz begat Anub, and Zobebah, and the families of Aharhel the son of Harum."}, {"verse": 9, "start": 85.45, "end": 99.89, "ta": "யாபேஸ் தன் சகோதரரைப்பார்க்கிலும் கனம்பெற்றவனாயிருந்தான். அவன் தாய்: நான் துக்கத்தோடே அவனைப் பெற்றேன் என்று சொல்லி அவனுக்கு யாபேஸ் என்று பேரிட்டாள்.", "en": "And Jabez was more honourable than his brethren: and his mother called his name Jabez, saying, Because I bare him with sorrow."}, {"verse": 10, "start": 99.89, "end": 123.43, "ta": "யாபேஸ் இஸ்ரவேலின் தேவனை நோக்கி: தேவரீர் என்னை ஆசிர்வதித்து, என் எல்லையைப் பெரிதாக்கி, உமது கரம் என்னோடிருந்து, தீங்கு என்னைத் துக்கப்படுத்தாதபடிக்கு அதற்கு என்னை விலக்கிக் காத்தருளும் என்று வேண்டிக்கொண்டான்; அவன் வேண்டிக்கொண்டதை தேவன் அருளினார்.", "en": "And Jabez called on the God of Israel, saying, Oh that thou wouldest bless me indeed, and enlarge my coast, and that thine hand might be with me, and that thou wouldest keep me from evil, that it may not grieve me! And God granted him that which he requested."}, {"verse": 11, "start": 123.43, "end": 130.86, "ta": "சூகாவின் சகோதரனாகிய கேலுூப் மேகீரைப் பெற்றான்; இவன் எஸ்தோனின் தகப்பன்.", "en": "And Chelub the brother of Shuah begat Mehir, which was the father of Eshton."}, {"verse": 12, "start": 130.86, "end": 142.06, "ta": "எஸ்தோன் பெத்ராபாவையும், பசேயாகையும், இர்நாகாஷின் தகப்பனாகிய தெகினாகையும் பெற்றான்; இவர்கள் ரேகாவூர் மனுஷர்.", "en": "And Eshton begat Beth-rapha, and Paseah, and Tehinnah the father of Ir-nahash. These are the men of Rechah."}, {"verse": 13, "start": 142.06, "end": 151.34, "ta": "கேனாசின் குமாரர், ஒத்னியேல், செராயா என்பவர்கள்; ஒத்னியேலின் குமாரரில் ஒருவன் ஆத்தாத்.", "en": "And the sons of Kenaz; Othniel, and Seraiah: and the sons of Othniel; Hathath."}, {"verse": 14, "start": 151.34, "end": 164.38, "ta": "மெயோனத்தாய் ஒபிராவைப் பெற்றான்; செராயா கராஷீமன் பள்ளத்தாக்குக்கு மூப்பனாகிய யோவாபைப் பெற்றான்; அவர்கள் தொழிலாளிகளாயிருந்தார்கள்.", "en": "And Meonothai begat Ophrah: and Seraiah begat Joab, the father of the valley of Charashim; for they were craftsmen."}, {"verse": 15, "start": 164.38, "end": 174.62, "ta": "எப்புன்னேயின் குமாரனாகிய காலேபின் குமாரர், ஈரு, ஏலா, நாகாம்; ஏலாவின் குமாரரில் ஒருவன் கேனாஸ்.", "en": "And the sons of Caleb the son of Jephunneh; Iru, Elah, and Naam: and the sons of Elah, even Kenaz."}, {"verse": 16, "start": 174.62, "end": 181.01, "ta": "எகலெலேலின் குமாரர், சீப், சீப்பா, திரியா, அசாரெயேல்.", "en": "And the sons of Jehaleleel; Ziph, and Ziphah, Tiria, and Asareel."}, {"verse": 17, "start": 181.01, "end": 197.11, "ta": "எஸ்றாவின் குமாரர், யெத்தேர், மேரேத், ஏப்பேர், யாலோன்; மேரேத்தின் பெண்ஜாதி மிரியாமையும், சம்மாயியையும், எஸ்தெமோவா ஊருக்கு மூப்பனான இஸ்பாவையும் பெற்றாள்.", "en": "And the sons of Ezra were , Jether, and Mered, and Epher, and Jalon: and she bare Miriam, and Shammai, and Ishbah the father of Eshtemoa."}, {"verse": 18, "start": 197.11, "end": 218.37, "ta": "அவன் பெண்ஜாதியாகிய எகுதியாள், கேதோரின் தகப்பனாகிய யாரேதையும், சோக்கோவின் தகப்பனாகிய ஏபேரையும, சனோவாவின் தகப்பனாகிய எக்குகதியேலையும் பெற்றாள்; மேரேத் விவாகம் பண்ணின பார்வோனின் குமாரத்தியாகிய பித்தியாளின் குமாரர் இவர்களே.", "en": "And his wife Jehudijah bare Jered the father of Gedor, and Heber the father of Socho, and Jekuthiel the father of Zanoah. And these are the sons of Bithiah the daughter of Pharaoh, which Mered took."}, {"verse": 19, "start": 218.37, "end": 229.05, "ta": "நாகாமின் சகோதரியாகிய ஒதியாவினுடைய பெண்ஜாதியின் குமாரர் கர்மியனாகிய ஆபிகேயிலாவும், மாகாத்தினாகிய எஸ்தேமோவாவுமே.", "en": "And the sons of his wife Hodiah the sister of Naham, the father of Keilah the Garmite, and Eshtemoa the Maachathite."}, {"verse": 20, "start": 229.05, "end": 240.6, "ta": "ஷீமோனின் குமாரர், அம்னோன், ரின்னா, பென்கானான், தீலோன் என்பவர்கள், இஷியின் குமாரர், சோகேதும் பென்சோகேதுமே.", "en": "And the sons of Shimon were , Amnon, and Rinnah, Ben-hanan, and Tilon. And the sons of Ishi were , Zoheth, and Ben-zoheth."}, {"verse": 21, "start": 240.6, "end": 253.29, "ta": "யூதாவின் குமாரனாகிய சேலாகின் புத்திரர்: லேக்காவூர் மூப்பனான ஏரும் மரேசார் மூப்பனான லாதாகும், மெல்லிய புடவை நெய்த அஸ்பெயா வீட்டுவம்சங்களும்,", "en": "The sons of Shelah the son of Judah were , Er the father of Lecah, and Laadah the father of Mareshah, and the families of the house of them that wrought fine linen, of the house of Ashbea,"}, {"verse": 22, "start": 253.29, "end": 266.68, "ta": "யோயாக்கீமும், கோசேபாவின் மனுஷரும், மோவாபியரை ஆண்ட யோவாஸ், சாராப் என்பவர்களும், யசுபிலெகேமுமே; இவைகள் பூர்வகாலத்தின் செய்திகள்.", "en": "And Jokim, and the men of Chozeba, and Joash, and Saraph, who had the dominion in Moab, and Jashubi-lehem. And these are ancient things."}, {"verse": 23, "start": 266.68, "end": 278.23, "ta": "இவர்கள் குயவராயிருந்து நெத்தாயிமிலும் கெதேராவிலும் குடியிருந்தார்கள்; ராஜாவின் வேலையை விசாரிக்கிறதற்கு அங்கே வாசம்பண்ணினார்கள்", "en": "These were the potters, and those that dwelt among plants and hedges: there they dwelt with the king for his work."}, {"verse": 24, "start": 278.23, "end": 286.28, "ta": "சிமியோனின் குமாரர், நெமுவேல்,யாமின், யாரீப், சேரா, சவுல் என்பவர்கள்.", "en": "The sons of Simeon were , Nemuel, and Jamin, Jarib, Zerah, and Shaul:"}, {"verse": 25, "start": 286.28, "end": 293.89, "ta": "இவன் குமாரன் சல்லுூம்; இவன் குமாரன் மிப்சாம்; இவன் குமாரன் மிஸ்மா.", "en": "Shallum his son, Mibsam his son, Mishma his son."}, {"verse": 26, "start": 293.89, "end": 302.82, "ta": "மிஸ்மாவின் குமாரரில் ஒருவன் அம்முவேல்; இவன் குமாரன் சக்கூர்; இவன் குமாரன் சீமேயி.", "en": "And the sons of Mishma; Hamuel his son, Zacchur his son, Shimei his son."}, {"verse": 27, "start": 302.82, "end": 319.53, "ta": "சீமேயிக்குப் பதினாறு குமாரரும் குமாரத்திகளும் இருந்தார்கள்; அவன் சகோதரருக்கு அநேகம் பிள்ளைகள் இருந்ததில்லை; அவர்கள் வம்சமெல்லாம் யூதாவின் புத்திரைப்போலப் பெருகினதுமில்லை.", "en": "And Shimei had sixteen sons and six daughters; but his brethren had not many children, neither did all their family multiply, like to the children of Judah."}, {"verse": 28, "start": 319.53, "end": 325.31, "ta": "அவர்கள் பெயெர்செபாவிலும், மொலாதாவிலும், ஆதசார்குவாவிலும்,", "en": "And they dwelt at Beer-sheba, and Moladah, and Hazar-shual,"}, {"verse": 29, "start": 325.31, "end": 329.42, "ta": "பில்லாவிலும், ஏத்சாமிலும், தோலாதிலும்,", "en": "And at Bilhah, and at Ezem, and at Tolad,"}, {"verse": 30, "start": 329.42, "end": 333.89, "ta": "பெத்தூவேலிலும், ஓர்மாவிலும், சிக்லாகிலும்,", "en": "And at Bethuel, and at Hormah, and at Ziklag,"}, {"verse": 31, "start": 333.89, "end": 348.85, "ta": "பெத்மார்காபோத்திலும், ஆத்சார்சூசிமிலும், பெத்பிரியிலும், சாராயிமிலும் குடியிருந்தார்கள்; தாவீது ராஜாவாகுமட்டும் இவைகள் அவர்கள் பட்டணங்களாயிருந்தது.", "en": "And at Beth-marcaboth, and Hazar-susim, and at Beth-birei, and at Shaaraim. These were their cities unto the reign of David."}, {"verse": 32, "start": 348.85, "end": 358.56, "ta": "அவர்களுடைய பேட்டைகள், ஏத்தாம், ஆயின், ரிம்மோன், தோகேன், ஆசான் என்னும் ஐந்து பட்டணங்கள்.", "en": "And their villages were , Etam, and Ain, Rimmon, and Tochen, and Ashan, five cities:"}, {"verse": 33, "start": 358.56, "end": 372.3, "ta": "அந்த பட்டணங்களைச் சுற்றிலும், பாகால்மட்முள்ள அவர்களுடைய எல்லாப் பேட்டைகளும், அவர்களுடைய வாசஸ்தலங்களும், அவர்களுடைய வம்ச அட்டவணையும் இவைகளே.", "en": "And all their villages that were round about the same cities, unto Baal. These were their habitations, and their genealogy."}, {"verse": 34, "start": 372.3, "end": 377.64, "ta": "மசோபாபும், யம்லேகும், அமத்சியாவின் குமாரன் யோஷாவும்,", "en": "And Meshobab, and Jamlech, and Joshah the son of Amaziah,"}, {"verse": 35, "start": 377.64, "end": 384.82, "ta": "யோவேலும், ஆசியேலின் மகன் செராயாவுக்குப் பிறந்த யோசிபியாவின் குமாரன் ஏகூவும்,", "en": "And Joel, and Jehu the son of Josibiah, the son of Seraiah, the son of Asiel,"}, {"verse": 36, "start": 384.82, "end": 394.0, "ta": "எலியோனாயும், யாக்கோபாவும், யெசொகாயாவும், அசாயாவும், ஆதியேலும், யெசிமியேலும் பெனாயாவும்,", "en": "And Elioenai, and Jaakobah, and Jeshohaiah, and Asaiah, and Adiel, and Jesimiel, and Benaiah,"}, {"verse": 37, "start": 394.0, "end": 403.72, "ta": "செமாயா பெற்ற சிம்ரியின் மகன் யெதாயாவுக்குப் பிறந்த அல்லோனின் புத்திரனாகிய சீப்பியின் குமாரன் சீசாவும் என்று,", "en": "And Ziza the son of Shiphi, the son of Allon, the son of Jedaiah, the son of Shimri, the son of Shemaiah;"}, {"verse": 38, "start": 403.72, "end": 415.71, "ta": "பேர்பேராய் எழுதியிருக்கிற இவர்கள் வம்சங்களில் பிரபுக்களாயிருந்தார்கள், இவர்கள் பிதாக்களின் வீட்டார் ஏராளமாய்ப் பரம்பினார்கள்.", "en": "These mentioned by their names were princes in their families: and the house of their fathers increased greatly."}, {"verse": 39, "start": 415.71, "end": 424.81, "ta": "தங்கள் ஆடுகளுக்கு மேய்ச்சலைத் தேடும்படிக்கு தேதோரின் எல்லையாகிய பள்ளத்தாக்கின் கீழ்ப்புறமட்டும் போய்,", "en": "And they went to the entrance of Gedor, even unto the east side of the valley, to seek pasture for their flocks."}, {"verse": 40, "start": 424.81, "end": 439.95, "ta": "நல்ல செழிப்பான மேய்ச்சலையும், அமரிக்கையும், சுகமுமுள்ள விஸ்தாரமான தேசத்தையும் கண்டுபிடித்தார்கள்; பூர்வத்திலே காமின் சந்ததியார் அங்கே குடியிருந்தார்கள்.", "en": "And they found fat pasture and good, and the land was wide, and quiet, and peaceable; for they of Ham had dwelt there of old."}, {"verse": 41, "start": 439.95, "end": 468.47, "ta": "பேர்பேராய் எழுதியிருக்கிற இவர்கள் யூதாவின் ராஜாவாகிய எசேக்கியாவின் நாட்களிலே அங்கே போய், அங்கே, கண்டுபிடித்தவர்களின் கூடாரங்களையும், தாபரங்களையும் அழித்து, இந்நாளிலே இருக்கிறதுபோல, அவர்களைச் சங்காரம்பண்ணி, அங்கே தங்கள் ஆடுகளுக்குமேய்ச்சல் இருந்தபடியினால், அவர்கள் அந்த ஸ்தலத்திலே குடியேறினார்கள்.", "en": "And these written by name came in the days of Hezekiah king of Judah, and smote their tents, and the habitations that were found there, and destroyed them utterly unto this day, and dwelt in their rooms: because there was pasture there for their flocks."}, {"verse": 42, "start": 468.47, "end": 485.54, "ta": "சிமியோனின் புத்திரராகிய இவர்களில் ஐந்நூறு மனுஷரும், அவர்கள் தலைமைக்காரராகிய இஷியின் குமாரரான பெலத்தியாவும், நெகரியாவும், ரெப்பாயாவும், ஊசியேலும், சேயீர் மலைத்தேசத்திற்குப் போய்,", "en": "And some of them, even of the sons of Simeon, five hundred men, went to mount Seir, having for their captains Pelatiah, and Neariah, and Rephaiah, and Uzziel, the sons of Ishi."}, {"verse": 43, "start": 485.54, "end": 495.69, "ta": "அமலேக்கியரில் தப்பி மீதியாயிருந்தவர்களை மடங்கடித்து, இந்நாள்வரைக்கும் இருக்கிறபடி அங்கே குடியேறினார்கள்.", "en": "And they smote the rest of the Amalekites that were escaped, and dwelt there unto this day."}]}, "5": {"chapter": 5, "duration": 352.78, "audio_url": "audio_ot/OT13_05.mp3", "total_verses": 26, "verses": [{"verse": 1, "start": 3.8, "end": 27.25, "ta": "ரூபன் இஸ்ரவேலுக்கு முதற்பிறந்த சேஷ்டபுத்திரன்; ஆனாலும் அவன் தன் தகப்பனுடைய மஞ்சத்தைத் தீட்டுப்படுத்தினபடியினால், கோத்திரத்து அட்டவணையிலே அவன் முதற் பிறந்தவனாக எண்ணப்படாமல், அவனுடைய சேஷ்டபுத்திர சுதந்தரம் இஸ்ரவேலின் குமாரனாகிய யோசேப்பின் குமாரருக்குக் கொடுக்கப்பட்டது.", "en": "Now the sons of Reuben the firstborn of Israel, (for he was the firstborn; but, forasmuch as he defiled his father’s bed, his birthright was given unto the sons of Joseph the son of Israel: and the genealogy is not to be reckoned after the birthright."}, {"verse": 2, "start": 27.25, "end": 38.32, "ta": "யூதா தன் சகோதரரிலே பலத்ததினால் ராஜாதிபத்தியம் அவன் சந்ததியிலுண்டானது; ஆகிலும் சேஷ்டபுத்திர சுதந்தரம் யோசேப்புடையதாயிற்று.", "en": "For Judah prevailed above his brethren, and of him came the chief ruler; but the birthright was Joseph’s:)"}, {"verse": 3, "start": 38.32, "end": 46.38, "ta": "இஸ்ரவேலின் முதற்பேறான ரூபனின் குமாரன் ஆனோக்கு, பல்லுூ, எஸ்ரோன், ஊர்மீ என்பவர்கள்.", "en": "The sons, I say , of Reuben the firstborn of Israel were , Hanoch, and Pallu, Hezron, and Carmi."}, {"verse": 4, "start": 46.38, "end": 54.03, "ta": "யோவேலின் குமாரரில் ஒருவன் செமாயா; இவன் குமாரன் கோக்; இவன் குமாரன் சிமேய்.", "en": "The sons of Joel; Shemaiah his son, Gog his son, Shimei his son,"}, {"verse": 5, "start": 54.03, "end": 60.46, "ta": "இவன் குமாரன் மீகா; இவன் குமாரன் ராயா; இவன் குமாரன் பாகால்.", "en": "Micah his son, Reaia his son, Baal his son,"}, {"verse": 6, "start": 60.46, "end": 69.91, "ta": "இவன் குமாரன் பேரா; ரூபனியரின் பிரபுவான இவனை அசீரியா ராஜாவாகிய தில்காத்பில்நேசர் சிறைபிடித்துப்போனான்.", "en": "Beerah his son, whom Tilgath-pilneser king of Assyria carried away captive: he was prince of the Reubenites."}, {"verse": 7, "start": 69.91, "end": 78.7, "ta": "தங்கள் சந்ததிகளின்படியே தங்கள் வம்ச அட்டவணைகளில் எழுதப்பட்ட அவன் சகோதரரில் தலைவர் ஏயேலும், சகரியாவும்,", "en": "And his brethren by their families, when the genealogy of their generations was reckoned, were the chief, Jeiel, and Zechariah,"}, {"verse": 8, "start": 78.7, "end": 92.22, "ta": "யோவேலின் மகனாகிய சேமாவுக்குப் பிறந்த ஆசாசின் குமாரன் பேலாவும்; இவன் சந்ததியார் ஆரோவேரிலும்; நேபோமட்டும், பாகால்மயோன்மட்டும் வாசம்பண்ணினார்கள்.", "en": "And Bela the son of Azaz, the son of Shema, the son of Joel, who dwelt in Aroer, even unto Nebo and Baal-meon:"}, {"verse": 9, "start": 92.22, "end": 104.43, "ta": "கிழக்கே ஐபிராத்து நதிதொடங்கி வனாந்தரத்தின் எல்லைமட்டும் அவர்கள் வாசம்பண்ணினார்கள்; அவர்கள் ஆடுமாடுகள் கீலேயாத்தேசத்தில் மிகுதியாயிற்று.", "en": "And eastward he inhabited unto the entering in of the wilderness from the river Euphrates: because their cattle were multiplied in the land of Gilead."}, {"verse": 10, "start": 104.43, "end": 118.19, "ta": "சவுலின் நாட்களில் ஆகாரியரோடு அவர்கள் யுத்தம்பண்ணி, தங்கள் கையால் அவர்கள் விழுந்தபின், அவர்கள் கூடாரங்களிலே கீலேயாத்தின் கீழ்ப்புறமெல்லாம் குடியேறினார்கள்.", "en": "And in the days of Saul they made war with the Hagarites, who fell by their hand: and they dwelt in their tents throughout all the east land of Gilead."}, {"verse": 11, "start": 118.19, "end": 125.76, "ta": "காத்தின் புத்திரர் அவர்களுக்கு எதிரே பாசான்தேசத்திலே சல்காமட்டும் வாசம்பண்ணினார்கள்.", "en": "And the children of Gad dwelt over against them, in the land of Bashan unto Salchah:"}, {"verse": 12, "start": 125.76, "end": 136.51, "ta": "அவர்களில் யோவேல் தலைவனும், சாப்பானும் அவனுக்கு இரண்டாவதுமாயிருந்தான்; யானாயும் சாப்பாத்தும் பாசானில் இருந்தார்கள்.", "en": "Joel the chief, and Shapham the next, and Jaanai, and Shaphat in Bashan."}, {"verse": 13, "start": 136.51, "end": 148.96, "ta": "அவர்கள் பிதாக்களின் வீட்டாராகிய அவர்கள் சகோதரர், மிகாவேல், மெசுல்லாம், சேபா, யோராயி, யாக்கான், சீகா, ஏபேர் என்னும் ஏழுபேர்.", "en": "And their brethren of the house of their fathers were , Michael, and Meshullam, and Sheba, and Jorai, and Jachan, and Zia, and Heber, seven."}, {"verse": 14, "start": 148.96, "end": 168.1, "ta": "இவர்கள் ஊரிக்குப் பிறந்த அபியேலின் குமாரர்; ஊரி என்பவன் யெரொவாவுக்கும், யெரொவா கீலேயாத்துக்கும், கீலேயாத் மிகாவேலுக்கும், மிகாவேல் எசிசாயிக்கும், எசிசாயி யாதோவுக்கும், யாதோ பூசுக்கும் குமாரராயிருந்தவர்கள்.", "en": "These are the children of Abihail the son of Huri, the son of Jaroah, the son of Gilead, the son of Michael, the son of Jeshishai, the son of Jahdo, the son of Buz;"}, {"verse": 15, "start": 168.1, "end": 176.24, "ta": "கூனியின் குமாரனாகிய அப்தியேலின் மகன் அகி, அவர்கள் பிதாக்களின் வீட்டுத் தலைவனாயிருந்தான்.", "en": "Ahi the son of Abdiel, the son of Guni, chief of the house of their fathers."}, {"verse": 16, "start": 176.24, "end": 188.86, "ta": "அவர்கள் கீலேயாத்திலிருக்கிற பாசானிலும் அதின் வெளிநிலங்களிலும், சாரோனின் எல்லாப் பேட்டைகளிலும் அவைகளின் கடையாந்தரங்கள்மட்டும் வாசம்பண்ணினார்கள்.", "en": "And they dwelt in Gilead in Bashan, and in her towns, and in all the suburbs of Sharon, upon their borders."}, {"verse": 17, "start": 188.86, "end": 203.02, "ta": "இவர்களெல்லாரும் யூதாவின் ராஜாவாகிய யெரொபெயாமின் நாட்களிலும், இஸ்ரவேலின் ராஜாவாகிய யெரொபெயாமின் நாட்களிலும் தங்கள் வம்சத்து அட்டவணைப்படி தொகை, ஏற்றப்பட்டார்கள்.", "en": "All these were reckoned by genealogies in the days of Jotham king of Judah, and in the days of Jeroboam king of Israel."}, {"verse": 18, "start": 203.02, "end": 222.81, "ta": "ரூபன் புத்திரரிலும், காத்தியரிலும், மனாசேயின் பாதிக்கோத்திரத்தாரிலும் கேடகமும் பட்டயமும் எடுத்து, வில்லெய்து, யுத்தத்திற்குப் பழகி, படைக்குப் போகத்தக்க, சேவகர் நாற்பத்து நாலாயிரத்து எழுநூற்று அறுபதுபேராயிருந்தார்கள்.", "en": "The sons of Reuben, and the Gadites, and half the tribe of Manasseh, of valiant men, men able to bear buckler and sword, and to shoot with bow, and skilful in war, were four and forty thousand seven hundred and threescore, that went out to the war."}, {"verse": 19, "start": 222.81, "end": 229.97, "ta": "அவர்கள் ஆகாரியரோடும், யெத்தூர் நாப்பீஸ் நோதாப் என்பவர்களோடும் யுத்தம்பண்ணுகிறபோது,", "en": "And they made war with the Hagarites, with Jetur, and Nephish, and Nodab."}, {"verse": 20, "start": 229.97, "end": 251.06, "ta": "அவர்களோடே எதிர்க்கத் துணைபெற்றபடியினால், ஆகாரியரும் இவர்களோடிருக்கிற யாவரும் அவர்கள் கையில் ஒப்புக்கொடுக்கப்பட்டார்கள்; அவர்கள் யுத்தத்திலே தேவனை நோக்கிக் கூப்பிட்டு, அவர்மேல் நம்பிக்கை வைத்தபடியினால் அவர்கள் விண்ணப்பத்தைக் கேட்டருளினார்.", "en": "And they were helped against them, and the Hagarites were delivered into their hand, and all that were with them: for they cried to God in the battle, and he was intreated of them; because they put their trust in him."}, {"verse": 21, "start": 251.06, "end": 267.34, "ta": "அவர்கள் இவர்களுக்கு இருந்த மிருகஜீவன்களாகிய ஐம்பதினாயிரம் ஒட்டகங்களையும், இரண்டுலட்சத்து ஐம்பதினாயிரம் ஆடுகளையும், இரண்டாயிரம் கழுதைகளையும், மனுஷரில் லட்சம்பேர்களையும் பிடித்தார்கள்.", "en": "And they took away their cattle; of their camels fifty thousand, and of sheep two hundred and fifty thousand, and of asses two thousand, and of men an hundred thousand."}, {"verse": 22, "start": 267.34, "end": 279.72, "ta": "யுத்தம் தேவனால் நடந்தபடியினால் அநேகர் வெட்டுண்டு விழுந்தார்கள்; தாங்கள் சிறைப்பட்டுப்போகுமட்டும் இவர்களுடைய ஸ்தலத்திலே குடியிருந்தார்கள்.", "en": "For there fell down many slain, because the war was of God. And they dwelt in their steads until the captivity."}, {"verse": 23, "start": 279.72, "end": 294.7, "ta": "மனாசேயின் பாதிக்கோத்திரத்துப் புத்திரரும் அந்த தேசத்தில் குடியிருந்து, பாசான்தொடங்கிப் பாகால் எர்மோன்மட்டும், செனீர்மட்டும், எர்மோன் பர்வதமட்டும் பெருகியிருந்தார்கள்.", "en": "And the children of the half tribe of Manasseh dwelt in the land: they increased from Bashan unto Baal-hermon and Senir, and unto mount Hermon."}, {"verse": 24, "start": 294.7, "end": 311.14, "ta": "அவர்கள் தங்கள் பிதாக்களின் வீட்டுத் தலைவராகிய ஏப்பேர், இஷி, ஏலியேல், அஸரியேல், எரேமியா, ஒதாவியா, யாதியேல் என்பவர்கள் பராக்கிரம வீரரான மனுஷரும் பேர்பெற்ற தலைவருமாயிருந்தார்கள்.", "en": "And these were the heads of the house of their fathers, even Epher, and Ishi, and Eliel, and Azriel, and Jeremiah, and Hodaviah, and Jahdiel, mighty men of valour, famous men, and heads of the house of their fathers."}, {"verse": 25, "start": 311.14, "end": 323.84, "ta": "அவர்கள் தங்கள் பிதாக்களின் தேவனுக்குத் துரோகம்பண்ணி, தேவன் அவர்களுக்கு முன்பாக அழித்திருந்த தேச ஜனங்களின் தேவர்களைப் பின்பற்றிச் சோரம்போனார்கள்.", "en": "And they transgressed against the God of their fathers, and went a whoring after the gods of the people of the land, whom God destroyed before them."}, {"verse": 26, "start": 323.84, "end": 351.28, "ta": "ஆகையால் இஸ்ரவேலின் தேவன் அசீரியா ராஜாவாகிய பூலின் ஆவியையும், அசீரியா ராஜாவாகிய தில்காத்பில்நேசரின் ஆவியையும் எழுப்பினதினாலே, அவன் ரூபனியரும், காத்தியரும் மனாசேயின் பாதிக்கோத்திரத்தாருமாகிய அவர்களைச் சிறைபிடித்து இந்நாள்வரைக்கும் இருக்கிறதுபோல, ஆலாவுக்கும் ஆபோருக்கும் ஆராவுக்கும் கோசான் ஆற்றங்கரைக்கும் கொண்டுபோனான்.", "en": "And the God of Israel stirred up the spirit of Pul king of Assyria, and the spirit of Tilgath-pilneser king of Assyria, and he carried them away, even the Reubenites, and the Gadites, and the half tribe of Manasseh, and brought them unto Halah, and Habor, and Hara, and to the river Gozan, unto this day."}]}, "6": {"chapter": 6, "duration": 725.21, "audio_url": "audio_ot/OT13_06.mp3", "total_verses": 81, "verses": [{"verse": 1, "start": 3.8, "end": 9.55, "ta": "லேவியின் குமாரர், கெர்சோன், கோகாத், மெராரி என்பவர்கள்.", "en": "The sons of Levi; Gershon, Kohath, and Merari."}, {"verse": 2, "start": 9.55, "end": 16.5, "ta": "கோகாத்தின் குமாரர், அம்ராம், இத்சார், எப்ரோன், ஊசியேல் என்பவர்கள்.", "en": "And the sons of Kohath; Amram, Izhar, and Hebron, and Uzziel."}, {"verse": 3, "start": 16.5, "end": 28.81, "ta": "அம்ராமின் பிள்ளைகள், ஆரோன், மோசே, மிரியாம் என்பவர்கள்; ஆரோனின் குமாரர், நாதாப், அபியூ, எலெயாசர், இத்தாமார் என்பவர்கள்.", "en": "And the children of Amram; Aaron, and Moses, and Miriam. The sons also of Aaron; Nadab, and Abihu, Eleazar, and Ithamar."}, {"verse": 4, "start": 28.81, "end": 34.88, "ta": "எலெயாசார் பினெகாசைப் பெற்றான்; பினெகாஸ் அபிசுவாவைப் பெற்றான்.", "en": "Eleazar begat Phinehas, Phinehas begat Abishua,"}, {"verse": 5, "start": 34.88, "end": 40.07, "ta": "அபிசுவா புக்கியைப் பெற்றான், புக்கி ஊசியைப் பெற்றான்.", "en": "And Abishua begat Bukki, and Bukki begat Uzzi,"}, {"verse": 6, "start": 40.07, "end": 45.66, "ta": "ஊசி செராகியாவைப் பெற்றான்; செரகியா மெராயோதைப் பெற்றான்.", "en": "And Uzzi begat Zerahiah, and Zerahiah begat Meraioth,"}, {"verse": 7, "start": 45.66, "end": 51.26, "ta": "மெரயோத் அமரியாவைப் பெற்றான்; அமரியா அகிதூபைப் பெற்றான்.", "en": "Meraioth begat Amariah, and Amariah begat Ahitub,"}, {"verse": 8, "start": 51.26, "end": 56.85, "ta": "அகிதூப் சாதோக்கைப் பெற்றான்; சாதோக் அகிமாசைப் பெற்றான்.", "en": "And Ahitub begat Zadok, and Zadok begat Ahimaaz,"}, {"verse": 9, "start": 56.85, "end": 62.44, "ta": "அகிமாஸ் அசரியாவைப் பெற்றான்; அசரியா யோகனானைப் பெற்றான்.", "en": "And Ahimaaz begat Azariah, and Azariah begat Johanan,"}, {"verse": 10, "start": 62.44, "end": 71.87, "ta": "யோகனான் அசரியாவைப் பெற்றான்; சாலொமோன் எருசலேமில் கட்டின ஆலயத்திலே ஆசாரிய பணிவிடையைச் செய்தவன் இவன்தான்.", "en": "And Johanan begat Azariah, (he it is that executed the priest’s office in the temple that Solomon built in Jerusalem:)"}, {"verse": 11, "start": 71.87, "end": 77.38, "ta": "அசரியா அமரியாவைப் பெற்றான்; அமரியா அகிதூபைப் பெற்றான்.", "en": "And Azariah begat Amariah, and Amariah begat Ahitub,"}, {"verse": 12, "start": 77.38, "end": 83.05, "ta": "அகிதூப் சாதோக்கைப் பெற்றான்; சாதோக் சல்லுூமைப் பெற்றான்.", "en": "And Ahitub begat Zadok, and Zadok begat Shallum,"}, {"verse": 13, "start": 83.05, "end": 89.28, "ta": "சல்லுூம் இல்க்கியாவைப் பெற்றான்; இல்க்கியா அசரியாவைப் பெற்றான்.", "en": "And Shallum begat Hilkiah, and Hilkiah begat Azariah,"}, {"verse": 14, "start": 89.28, "end": 94.96, "ta": "அசரியா செராயாவைப் பெற்றான்; செராயா யோசதாக்கைப் பெற்றான்.", "en": "And Azariah begat Seraiah, and Seraiah begat Jehozadak,"}, {"verse": 15, "start": 94.96, "end": 106.46, "ta": "கர்த்தர் நேபுகாத்நேச்சாரைக்கொண்டு யூதா ஜனங்களையும் எருசலேமியரையும் சிறைபிடித்துக்கொண்டுபோகச் செய்தபோது யோசதாக்கும் சிறைப்பட்டுப்போனான்.", "en": "And Jehozadak went into captivity , when the LORD carried away Judah and Jerusalem by the hand of Nebuchadnezzar."}, {"verse": 16, "start": 106.46, "end": 112.21, "ta": "லேவியின் குமாரர், கெர்சோம், கோகாத், மெராரி என்பவர்களே.", "en": "The sons of Levi; Gershom, Kohath, and Merari."}, {"verse": 17, "start": 112.21, "end": 117.97, "ta": "கெர்சோமுடைய குமாரரின் நாமங்கள், லிப்னி, சிமேயி என்பவைகள்.", "en": "And these be the names of the sons of Gershom; Libni, and Shimei."}, {"verse": 18, "start": 117.97, "end": 124.92, "ta": "கோகாத்தின் குமாரர், அம்ராம், இத்சார், எப்ரோன், ஊசியேல் என்பவர்கள்.", "en": "And the sons of Kohath were , Amram, and Izhar, and Hebron, and Uzziel."}, {"verse": 19, "start": 124.92, "end": 134.02, "ta": "மெராரியின் குமாரர், மகேலி, மூசி என்பவர்கள். லேவியருக்கு அவர்கள் பிதாக்கள் வழியாய் உண்டான வம்சங்கள்:", "en": "The sons of Merari; Mahli, and Mushi. And these are the families of the Levites according to their fathers."}, {"verse": 20, "start": 134.02, "end": 141.13, "ta": "கெர்சோமின் குமாரன் லிப்னி; இவன் குமாரன் யாகாத்; இவன் குமாரன் சிம்மா.", "en": "Of Gershom; Libni his son, Jahath his son, Zimmah his son,"}, {"verse": 21, "start": 141.13, "end": 149.84, "ta": "இவன் குமாரன் யோவா; இவன் குமாரன் இத்தோ; இவன் குமாரன் சேரா; இவன் குமாரன் யாத்திராயி.", "en": "Joah his son, Iddo his son, Zerah his son, Jeaterai his son."}, {"verse": 22, "start": 149.84, "end": 157.43, "ta": "கோகாத்தின் குமாரரில் ஒருவன் அம்மினதாப், இவன் குமாரன் கோராகு, இவன் குமாரன் ஆசீர்.", "en": "The sons of Kohath; Amminadab his son, Korah his son, Assir his son,"}, {"verse": 23, "start": 157.43, "end": 164.46, "ta": "இவன் குமாரன் இல்க்கானா; இவன் குமாரன் அபியாசாப்; இவன் குமாரன் ஆசீர்.", "en": "Elkanah his son, and Ebiasaph his son, and Assir his son,"}, {"verse": 24, "start": 164.46, "end": 173.41, "ta": "இவன் குமாரன் எல்க்கானா; இவன் குமாரன் ஊரியேல்; இவன் குமாரன் ஊசியா; இவன் குமாரன் சவுல்.", "en": "Tahath his son, Uriel his son, Uzziah his son, and Shaul his son."}, {"verse": 25, "start": 173.41, "end": 178.36, "ta": "எல்க்கானாவின் குமாரர், அமாசாயி ஆகிமோத் என்பவர்கள்.", "en": "And the sons of Elkanah; Amasai, and Ahimoth."}, {"verse": 26, "start": 178.36, "end": 184.04, "ta": "எல்க்கானாவின் குமாரரில் ஒருவன் சோபாய், இவன் குமாரன் நாகாத்.", "en": "As for Elkanah: the sons of Elkanah; Zophai his son, and Nahath his son,"}, {"verse": 27, "start": 184.04, "end": 191.07, "ta": "இவன் குமாரன் எலியாப்; இவன் குமாரன் எரோகாம்; இவன் குமாரன் எல்க்கானா.", "en": "Eliab his son, Jeroham his son, Elkanah his son."}, {"verse": 28, "start": 191.07, "end": 196.98, "ta": "சாமுவேலின் குமாரர், அவனுடைய முதற்பேறான வஷ்னீ அபியா என்பவர்கள்.", "en": "And the sons of Samuel; the firstborn Vashni, and Abiah."}, {"verse": 29, "start": 196.98, "end": 206.65, "ta": "மெராரியின் குமாரரில் ஒருவன் மகேலி; இவன் குமாரன் லிப்னி; இவன் குமாரன் சிமேயி; இவன் குமாரன் ஊசா.", "en": "The sons of Merari; Mahli, Libni his son, Shimei his son, Uzza his son,"}, {"verse": 30, "start": 206.65, "end": 213.12, "ta": "இவன் குமாரன் சிமெயா; இவன் குமாரன் அகியா; இவன் குமாரன் அசாயா.", "en": "Shimea his son, Haggiah his son, Asaiah his son."}, {"verse": 31, "start": 213.12, "end": 222.39, "ta": "கர்த்தருடைய பெட்டி நிலைபெற்றபோது, தாவீது கர்த்தருடைய ஆலயத்தில் சங்கீத சேவையை நடத்துகிறதற்கு ஸ்தாபித்தவர்களும்,", "en": "And these are they whom David set over the service of song in the house of the LORD , after that the ark had rest."}, {"verse": 32, "start": 222.39, "end": 239.72, "ta": "சாலொமோன் எருசலேமிலே கர்த்தருடைய ஆலயத்தைக் கட்டித் தீருமட்டும் ஆசரிப்புக் கூடார வாசஸ்தலத்திற்கு முன்பாக சங்கீத சேவனையுடன் தங்கள் முறைமையின்படியே பணிவிடை செய்துவந்தவர்களுமாகிய மனுஷரும் அவர்கள் குமாரருமானவர்கள்.", "en": "And they ministered before the dwelling place of the tabernacle of the congregation with singing, until Solomon had built the house of the LORD in Jerusalem: and then they waited on their office according to their order."}, {"verse": 33, "start": 239.72, "end": 248.83, "ta": "கோகாத்தியரின் குமாரரில் ஏமான் என்னும் பாடகன்; இவன் யோவேலின் குமாரன்; இவன் சாமுவேலின் குமாரன்.", "en": "And these are they that waited with their children. Of the sons of the Kohathites: Heman a singer, the son of Joel, the son of Shemuel,"}, {"verse": 34, "start": 248.83, "end": 258.9, "ta": "இவன் எல்க்கானாவின் குமாரன்; இவன் யெரொகாமின் குமாரன்; இவன் எலியேலின் குமாரன்; இவன் தோவாகின் குமாரன்.", "en": "The son of Elkanah, the son of Jeroham, the son of Eliel, the son of Toah,"}, {"verse": 35, "start": 258.9, "end": 268.96, "ta": "இவன் சூப்பின் குமாரன்; இவன் இல்க்கானாவின் குமாரன்; இவன் மாகாத்தின் குமாரன்; இவன் அமாசாயின் குமாரன்.", "en": "The son of Zuph, the son of Elkanah, the son of Mahath, the son of Amasai,"}, {"verse": 36, "start": 268.96, "end": 279.35, "ta": "இவன் எல்க்கானாவின் குமாரன்; இவன் யோவேலின் குமாரன்; இவன் அசரியாவின் குமாரன்; இவன் செப்பனியாவின் குமாரன்.", "en": "The son of Elkanah, the son of Joel, the son of Azariah, the son of Zephaniah,"}, {"verse": 37, "start": 279.35, "end": 288.86, "ta": "இவன் தாகாதின் குமாரன்; இவன் ஆசீரின் குமாரன்; இவன் எபியாசாப்பின் குமாரன், இவன் கோராகின் குமாரன்.", "en": "The son of Tahath, the son of Assir, the son of Ebiasaph, the son of Korah,"}, {"verse": 38, "start": 288.86, "end": 297.96, "ta": "இவன் இத்சாரின் குமாரன்; இவன் கோகாத்தின் குமாரன்; இவன் இஸ்ரவேலின் குமாரனாகிய லேவியின் குமாரன்.", "en": "The son of Izhar, the son of Kohath, the son of Levi, the son of Israel."}, {"verse": 39, "start": 297.96, "end": 307.63, "ta": "இவன் சகோதரனாகிய ஆசாப் இவன் வலதுபக்கத்திலே நிற்பான், ஆசாப் பெரகியாவின் குமாரன்; இவன் சிமேயாவின் குமாரன்.", "en": "And his brother Asaph, who stood on his right hand, even Asaph the son of Berachiah, the son of Shimea,"}, {"verse": 40, "start": 307.63, "end": 315.3, "ta": "இவன் மிகாவேலின் குமாரன்; இவன் பாசெயாவின் குமாரன்; இவன் மல்கியாவின் குமாரன்.", "en": "The son of Michael, the son of Baaseiah, the son of Malchiah,"}, {"verse": 41, "start": 315.3, "end": 322.57, "ta": "இவன் எத்னியின் குமாரன்; இவன் சேராவின் குமாரன்; இவன் அதாயாவின் குமாரன்.", "en": "The son of Ethni, the son of Zerah, the son of Adaiah,"}, {"verse": 42, "start": 322.57, "end": 329.92, "ta": "இவன் ஏத்தானின் குமாரன்; இவன் சிம்மாவின் குமாரன்; இவன் சீமேயின் குமாரன்.", "en": "The son of Ethan, the son of Zimmah, the son of Shimei,"}, {"verse": 43, "start": 329.92, "end": 337.19, "ta": "இவன் யாகாதின் குமாரன்; இவன் கெர்சோமின் குமாரன்; இவன் லேவியின் குமாரன்.", "en": "The son of Jahath, the son of Gershom, the son of Levi."}, {"verse": 44, "start": 337.19, "end": 351.73, "ta": "மெராரியின் புத்திரராகிய இவர்களுடைய சகோதரர் இடதுபக்கத்திலே நிற்பார்கள்; அவர்களில் ஏதான் என்பவன் கிஷியின் குமாரன், இவன் அப்தியின் குமாரன்; இவன் மல்கின் குமாரன்.", "en": "And their brethren the sons of Merari stood on the left hand: Ethan the son of Kishi, the son of Abdi, the son of Malluch,"}, {"verse": 45, "start": 351.73, "end": 359.08, "ta": "இவன் அபியாவின் குமாரன் இவன் அமத்சியாவின் குமாரன்; இவன் இல்க்கியாவின் குமாரன்.", "en": "The son of Hashabiah, the son of Amaziah, the son of Hilkiah,"}, {"verse": 46, "start": 359.08, "end": 366.27, "ta": "இவன் அம்சியின் குமாரன்; இவன் பானியின் குமாரன்; இவன் சாமேரின் குமாரன்.", "en": "The son of Amzi, the son of Bani, the son of Shamer,"}, {"verse": 47, "start": 366.27, "end": 375.94, "ta": "இவன் மகேலியின் குமாரன்; இவன் மூசியின் குமாரன்; இவன் மெராரியின் குமாரன்; இவன் லேவியின் குமாரன்.", "en": "The son of Mahli, the son of Mushi, the son of Merari, the son of Levi."}, {"verse": 48, "start": 375.94, "end": 385.13, "ta": "அவர்கள் சகோதரராகிய மற்ற லேவியர் தேவனுடைய ஆலயமாகிய வாசஸ்தலத்தின் பணிவிடைக்கெல்லாம் வைக்கப்பட்டிருந்தார்கள்.", "en": "Their brethren also the Levites were appointed unto all manner of service of the tabernacle of the house of God."}, {"verse": 49, "start": 385.13, "end": 407.34, "ta": "ஆரோனும் அவன் குமாரரும் சர்வாங்க தகனபலிபீடத்தின்மேல் பலியிட்டுத் தூபங்காட்டும் பீடத்தின்மேல் தூபங்காட்டி, மகா பரிசுத்த ஸ்தலத்தின் எல்லாவேலைக்கும், தேவனுடைய தாசனாகிய மோசே கற்பித்தபடியெல்லாம் இஸ்ரவேலுக்காகப் பாவநிவிர்த்தியுண்டாக்குகிறதற்கும் வைக்கப்பட்டிருந்தார்கள்.", "en": "But Aaron and his sons offered upon the altar of the burnt offering, and on the altar of incense, and were appointed for all the work of the place most holy, and to make an atonement for Israel, according to all that Moses the servant of God had commanded."}, {"verse": 50, "start": 407.34, "end": 414.69, "ta": "ஆரோனின் குமாரரில் எலெயாசர் என்பவனுடைய குமாரன் பினேகாஸ்; இவன் குமாரன் அபிசுவா.", "en": "And these are the sons of Aaron; Eleazar his son, Phinehas his son, Abishua his son,"}, {"verse": 51, "start": 414.69, "end": 421.0, "ta": "இவன் குமாரன் புக்கி; இவன் குமாரன் ஊசி, இவன் குமாரன் செராகியா.", "en": "Bukki his son, Uzzi his son, Zerahiah his son,"}, {"verse": 52, "start": 421.0, "end": 428.03, "ta": "இவன் குமாரன் மெராயோத்; இவன் குமாரன் அமரியா; இவன் குமாரன் அகித்தூப்.", "en": "Meraioth his son, Amariah his son, Ahitub his son,"}, {"verse": 53, "start": 428.03, "end": 432.58, "ta": "இவன் குமாரன் சாதோக்; இவன் குமாரன் அகிமாஸ்.", "en": "Zadok his son, Ahimaaz his son."}, {"verse": 54, "start": 432.58, "end": 443.85, "ta": "அவர்கள் பேட்டைகளின்படியே அவர்கள் எல்லைக்குள்ளான அவர்கள் வாசஸ்தலங்களாவன: கோகாத்தியரின் வம்சமான ஆரோனின் புத்திரருக்கு விழுந்த சீட்டின்படியே,", "en": "Now these are their dwelling places throughout their castles in their coasts, of the sons of Aaron, of the families of the Kohathites: for theirs was the lot."}, {"verse": 55, "start": 443.85, "end": 451.44, "ta": "யூதாதேசத்திலிருக்கிற எப்ரோனையும் அதைச் சுற்றியிருக்கிற வெளிநிலங்களையும் கொடுத்தார்கள்.", "en": "And they gave them Hebron in the land of Judah, and the suburbs thereof round about it."}, {"verse": 56, "start": 451.44, "end": 460.3, "ta": "அந்தப் பட்டணத்தின் வயல்களையும் அதின் பட்டிகளையும் எப்புன்னேயின் குமாரனாகிய காலேபுக்குக் கொடுத்தார்கள்.", "en": "But the fields of the city, and the villages thereof, they gave to Caleb the son of Jephunneh."}, {"verse": 57, "start": 460.3, "end": 474.69, "ta": "இப்படியே ஆரோனின் புத்திரருக்கு எப்ரோன் என்னும் அடைக்கலப்பட்டணங்களில் ஒன்றையும், லிப்னாவையும் அதின் வெளிநிலங்களையும், யாத்தீரையும் எஸ்தமோவாவையும் அவற்றின் வெளிநிலங்களையும்,", "en": "And to the sons of Aaron they gave the cities of Judah, namely , Hebron, the city of refuge, and Libnah with her suburbs, and Jattir, and Eshtemoa, with their suburbs,"}, {"verse": 58, "start": 474.69, "end": 480.6, "ta": "ஈலேனையும் அதின் வெளிநிலங்களையும், தெபீரையும் அதின் வெளிநிலங்களையும்,", "en": "And Hilen with her suburbs, Debir with her suburbs,"}, {"verse": 59, "start": 480.6, "end": 486.83, "ta": "ஆசானையும் அதின் வெளிநிலங்களையும், பெத்சேமேசையும் அதின் வெளிநிலங்களையும்,", "en": "And Ashan with her suburbs, and Beth-shemesh with her suburbs:"}, {"verse": 60, "start": 486.83, "end": 505.84, "ta": "பென்யமீன் கோத்திரத்திலே கேபாவையும் அதின் வெளிநிலங்களையும், அலெமேத்தையும் அதின் வெளிநிலங்களையும், ஆனதோத்தையும் அதின் வெளிநிலங்களையும் கொடுத்தார்கள்; இவர்கள் வம்சங்களுக்குக் கொடுத்த இவர்கள் பட்டணங்களெல்லாம் பதின்மூன்று.", "en": "And out of the tribe of Benjamin; Geba with her suburbs, and Alemeth with her suburbs, and Anathoth with her suburbs. All their cities throughout their families were thirteen cities."}, {"verse": 61, "start": 505.84, "end": 518.87, "ta": "கோகாத்தின் மற்றப் புத்திரருக்கு வேறொரு கோத்திர வம்சத்திலும், பாதிக்கோத்திரமாகிய மனாசேயின் பாதியிலும் விழுந்த சீட்டின்படியே பத்துப் பட்டணங்கள் இருந்தது.", "en": "And unto the sons of Kohath, which were left of the family of that tribe, were cities given out of the half tribe, namely, out of the half tribe of Manasseh, by lot, ten cities."}, {"verse": 62, "start": 518.87, "end": 536.04, "ta": "கெர்சோமின் புத்திரருக்கு அவர்கள் வம்சங்களின்படியே, இசக்கார் கோத்திரத்திலும், ஆசேர் கோத்திரத்திலும், நப்தலி கோத்திரத்திலும், பாசானிலிருக்கிற மனாசே கோத்திரத்திலும் பதின்மூன்று பட்டணங்கள் இருந்தது.", "en": "And to the sons of Gershom throughout their families out of the tribe of Issachar, and out of the tribe of Asher, and out of the tribe of Naphtali, and out of the tribe of Manasseh in Bashan, thirteen cities."}, {"verse": 63, "start": 536.04, "end": 550.9, "ta": "மெராரியின் புத்திரருக்கு அவர்கள் வம்சங்களின்படியே ரூபன் கோத்திரத்திலும், காத் கோத்திரத்திலும், செபுலோன் கோத்திரத்திலும் விழுந்த சீட்டின்படி பன்னிரண்டு பட்டணங்கள் இருந்தது.", "en": "Unto the sons of Merari were given by lot, throughout their families, out of the tribe of Reuben, and out of the tribe of Gad, and out of the tribe of Zebulun, twelve cities."}, {"verse": 64, "start": 550.9, "end": 559.13, "ta": "அப்படியே இஸ்ரவேல் புத்திரர் லேவியருக்குக் கொடுத்த பட்டணங்களும் அவைகளின் வெளிநிலங்களும் என்னவென்றால்,", "en": "And the children of Israel gave to the Levites these cities with their suburbs."}, {"verse": 65, "start": 559.13, "end": 576.39, "ta": "சீட்டுப்போட்டு, சிலருக்கு தாண் புத்திரரின் கோத்திரத்திலும், சிமியோன் புத்திரரின் கோத்திரத்திலும், பென்யமீன் புத்திரரின் கோத்திரத்திலும், பேர்பேராகச் சொல்லப்பட்ட அந்தப் பட்டணங்களைக் கொடுத்தார்கள்.", "en": "And they gave by lot out of the tribe of the children of Judah, and out of the tribe of the children of Simeon, and out of the tribe of the children of Benjamin, these cities, which are called by their names."}, {"verse": 66, "start": 576.39, "end": 586.14, "ta": "கோகாத் புத்திரரில் மற்ற வம்சங்களுக்கு அவர்கள் எல்லையான பட்டணங்கள் அவர்களுக்கு எப்பிராயீம் கோத்திரத்திலே இருந்தது.", "en": "And the residue of the families of the sons of Kohath had cities of their coasts out of the tribe of Ephraim."}, {"verse": 67, "start": 586.14, "end": 598.68, "ta": "எவையெனில், அடைக்கலப்பட்டணங்களில் அவர்களுக்கு எப்பிராயீம் மலைத்தேசத்திலிருக்கிற சீகேமையும் அதின் வெளிநிலங்களையும், கேசேரையும் அதின் வெளிநிலங்களையும்,", "en": "And they gave unto them, of the cities of refuge, Shechem in mount Ephraim with her suburbs; they gave also Gezer with her suburbs,"}, {"verse": 68, "start": 598.68, "end": 605.23, "ta": "யோக்மேயாமையும் அதின் வெளிநிலங்களையும், பேத்ஓரோனையும் அதின் வெளிநிலங்களையும்,", "en": "And Jokmeam with her suburbs, and Beth-horon with her suburbs,"}, {"verse": 69, "start": 605.23, "end": 611.7, "ta": "ஆயலோனையும் அதின் வெளிநிலங்களையும், காத்ரிம்மோனையும் அதின் வெளிநிலங்களையும்,", "en": "And Aijalon with her suburbs, and Gath-rimmon with her suburbs:"}, {"verse": 70, "start": 611.7, "end": 626.88, "ta": "மனாசேயின் பாதிக்கோத்திரத்திலே ஆனேரையும் அதின் வெளிநிலங்களையும், பீலியாமையும் அதின் வெளிநிலங்களையும் கொடுத்தார்கள்; இவைகள் காகாத் புத்திரரிலுள்ள மற்ற வம்சங்களுக்கு இருந்தது.", "en": "And out of the half tribe of Manasseh; Aner with her suburbs, and Bileam with her suburbs, for the family of the remnant of the sons of Kohath."}, {"verse": 71, "start": 626.88, "end": 638.46, "ta": "கெர்சோம் புத்திரருக்கு மனாசேயின் பாதிக்கோத்திர வம்சத்திலே பாசானிலிருக்கிற கோலானும் அதின் வெளிநிலங்களும், அஸ்தரோத்தும் அதின் வெளிநிலங்களும்,", "en": "Unto the sons of Gershom were given out of the family of the half tribe of Manasseh, Golan in Bashan with her suburbs, and Ashtaroth with her suburbs:"}, {"verse": 72, "start": 638.46, "end": 645.97, "ta": "இசக்கார் கோத்திரத்திலே கேதேசும் அதின் வெளிநிலங்களும், தாபிராத்தும் அதின் வெளிநிலங்களும்,", "en": "And out of the tribe of Issachar; Kedesh with her suburbs, Daberath with her suburbs,"}, {"verse": 73, "start": 645.97, "end": 651.41, "ta": "ராமோத்தும் அதின் வெளிநிலங்களும், ஆனேமும் அதின் εெளிநிலங்கγும்,", "en": "And Ramoth with her suburbs, and Anem with her suburbs:"}, {"verse": 74, "start": 651.41, "end": 658.44, "ta": "ஆசேர் கோத்திரத்திலே மாஷாலும் அதின் வெளிநிலங்களும், அப்தோனும் அதின் வெளிநிலங்களும்,", "en": "And out of the tribe of Asher; Mashal with her suburbs, and Abdon with her suburbs,"}, {"verse": 75, "start": 658.44, "end": 664.51, "ta": "உக்கோக்கும் அதின் வெளிநிலங்களும், ரேகோபும் அதின் வெளிநிலங்களும்.", "en": "And Hukok with her suburbs, and Rehob with her suburbs:"}, {"verse": 76, "start": 664.51, "end": 677.69, "ta": "நப்தலி கோத்திரத்திலே கலிலேயாவிலிருக்கிற கேதேசும் அதின் வெளிநிலங்களும், அம்மோனும் அதின் வெளிநிலங்களும், கிரியாத்தாயிமும் அதின் வெளிநிலங்களும் இருந்தது.", "en": "And out of the tribe of Naphtali; Kedesh in Galilee with her suburbs, and Hammon with her suburbs, and Kirjathaim with her suburbs."}, {"verse": 77, "start": 677.69, "end": 687.6, "ta": "மெராரியின் மற்றப் புத்திரருக்கு செபுலோன் கோத்திரத்திலே ரிம்மோனும் அதின் வெளிநிலங்களும், தாபோரும் அதின் வெளிநிலங்களும்,", "en": "Unto the rest of the children of Merari were given out of the tribe of Zebulun, Rimmon with her suburbs, Tabor with her suburbs:"}, {"verse": 78, "start": 687.6, "end": 702.54, "ta": "எரிகோவுக்கு அப்புறமாயிருக்கிற யோர்தானுக்கு அப்பாலே யோர்தானுக்குக் கிழக்கே இருக்கிற ரூபன் கோத்திரத்திலே வனாந்தரத்திலுள்ள பேசேரும் அதன் வெளிநிலங்களும், யாத்சாவும் அதன் வெளிநிலங்களும்,", "en": "And on the other side Jordan by Jericho, on the east side of Jordan, were given them out of the tribe of Reuben, Bezer in the wilderness with her suburbs, and Jahzah with her suburbs,"}, {"verse": 79, "start": 702.54, "end": 708.53, "ta": "கேதேமோத்தும் அதின் வெளிநிலங்களும், மேப்பாத்தும் அதின் வெளிநிலங்களும்,", "en": "Kedemoth also with her suburbs, and Mephaath with her suburbs:"}, {"verse": 80, "start": 708.53, "end": 717.08, "ta": "காத் கோத்திரத்திலே கீலேயாத்திலுள்ள ராமோத்தும் அதின் வெளிநிலங்களும், மக்னாயீமும் அதின் வெளிநிலங்களும்,", "en": "And out of the tribe of Gad; Ramoth in Gilead with her suburbs, and Mahanaim with her suburbs,"}, {"verse": 81, "start": 717.08, "end": 723.71, "ta": "எஸ்போனும் அதின் வெளிநிலங்களும், யாசேரும் அதின் வெளிநிலங்களும் இருந்தது.", "en": "And Heshbon with her suburbs, and Jazer with her suburbs."}]}, "7": {"chapter": 7, "duration": 504.23, "audio_url": "audio_ot/OT13_07.mp3", "total_verses": 40, "verses": [{"verse": 1, "start": 3.8, "end": 11.5, "ta": "இசக்காருடைய குமாரர், தோலா, பூவா, யசுப், சிம்ரோன் என்னும் நாலுபேர்.", "en": "Now the sons of Issachar were , Tola, and Puah, Jashub, and Shimron, four."}, {"verse": 2, "start": 11.5, "end": 38.22, "ta": "தோலாவின் குமாரர், ஊசி, ரெப்பாயா, யெரியேல், யக்மாயி, இப்சாம், சாமுவேல் என்பவர்கள்; தோலாவுக்குப் பிறந்த இவர்கள் தங்கள் பிதாக்கள் வம்சத்தலைவரும் தங்கள் சந்ததிகளிலே பராக்கிரமசாலிகளுமாயிருந்தார்கள்; தாவீதின் நாட்களில் அவர்கள் தொகை இருபதினாயிரத்து அறுநூறுபேராயிருந்தது.", "en": "And the sons of Tola; Uzzi, and Rephaiah, and Jeriel, and Jahmai, and Jibsam, and Shemuel, heads of their father’s house, to wit , of Tola: they were valiant men of might in their generations; whose number was in the days of David two and twenty thousand and six hundred."}, {"verse": 3, "start": 38.22, "end": 53.62, "ta": "ஊசியின் குமாரரில் ஒருவன் இஸ்ரகியா; இஸ்ரகியாவின் குமாரர், மிகாயேல், ஒபதியா, யோவேல், இஷியா என்பவர்கள்; இவர்கள் ஐந்துபேரும் தலைவராயிருந்தார்கள்.", "en": "And the sons of Uzzi; Izrahiah: and the sons of Izrahiah; Michael, and Obadiah, and Joel, Ishiah, five: all of them chief men."}, {"verse": 4, "start": 53.62, "end": 70.26, "ta": "அவர்கள் பிதாக்கள் வம்சத்தாரானவர்கள் சந்ததிகளில் யுத்தமனுஷரான கூட்டங்கள் முப்பத்தாறாயிரம்பேர் அவர்களோடிருந்தார்கள்; அவர்களுக்கு அநேகம் பெண்ஜாதிகளும் பிள்ளைகளும் இருந்தார்கள்.", "en": "And with them, by their generations, after the house of their fathers, were bands of soldiers for war, six and thirty thousand men: for they had many wives and sons."}, {"verse": 5, "start": 70.26, "end": 83.98, "ta": "இசக்காருடைய மற்ற எல்லா வம்சங்களிலும் அவர்களுக்குச் சகோதரரான பராக்கிரமசாலிகள் தங்கள் வம்ச அட்டவணைகளின்படியெல்லாம் எண்பத்தேழாயிரம்பேராயிருந்தார்கள்.", "en": "And their brethren among all the families of Issachar were valiant men of might, reckoned in all by their genealogies fourscore and seven thousand."}, {"verse": 6, "start": 83.98, "end": 91.14, "ta": "பென்யமீன் குமாரர், பேலா, பெகேர், யெதியாயேல் என்னும் மூன்றுபேர்.", "en": "The sons of Benjamin; Bela, and Becher, and Jediael, three."}, {"verse": 7, "start": 91.14, "end": 113.98, "ta": "பேலாவின் குமாரர், எஸ்போன், ஊசி, ஊசியேல், யெரிமோத், இரி என்பவர்கள்; இவர்கள் தங்கள் பிதாக்களின் வம்சத்தில் பராக்கிரமசாலிகளான ஐந்து தலைவராயிருந்தார்கள்; இவர்கள் வம்ச அட்டவணைக்குள்ளானவர்கள் இருபத்தீராயிரத்து முப்பத்துநாலுபேர்.", "en": "And the sons of Bela; Ezbon, and Uzzi, and Uzziel, and Jerimoth, and Iri, five; heads of the house of their fathers, mighty men of valour; and were reckoned by their genealogies twenty and two thousand and thirty and four."}, {"verse": 8, "start": 113.98, "end": 130.17, "ta": "பெகேரின் குமாரர், செமிரா, யோவாஸ், எலியேசர், எலியோனாய், உம்ரி, யெரிமோத், அபியா, ஆனதோத், அலமேத் என்பவர்கள்; இவர்கள் எல்லாரும் பெகேரின் குமாரர்.", "en": "And the sons of Becher; Zemira, and Joash, and Eliezer, and Elioenai, and Omri, and Jerimoth, and Abiah, and Anathoth, and Alameth. All these are the sons of Becher."}, {"verse": 9, "start": 130.17, "end": 141.23, "ta": "தங்கள் பிதாக்களின் வம்சத்தலைவராகிய அவர்கள் சந்ததிகளின் அட்டவணைக்குள்ளான பராக்கிரமாலிகள் இருபதினாயிரத்து இருநூறுபேர்.", "en": "And the number of them, after their genealogy by their generations, heads of the house of their fathers, mighty men of valour, was twenty thousand and two hundred."}, {"verse": 10, "start": 141.23, "end": 156.19, "ta": "யெதியாயேலின் குமாரரில் ஒருவன் பில்கான்; பில்கானின் குமாரர், ஏயூஷ், பென்யமீன், ஏகூத், கெனானா, சேத்தான், தர்ஷீஸ், அகிஷாகார் என்பவர்கள்.", "en": "The sons also of Jediael; Bilhan: and the sons of Bilhan; Jeush, and Benjamin, and Ehud, and Chenaanah, and Zethan, and Tharshish, and Ahishahar."}, {"verse": 11, "start": 156.19, "end": 173.53, "ta": "யெதியாயேலின் குமாரராகிய இவர்கள் எல்லாரும் தங்கள் பிதாக்கள் வம்சத்தாரில் தலைவராயிருந்தார்கள்; இவர்களில் யுத்தத்திற்குப் போகத்தக்க சேவகரான பராக்கிரமசாலிகள் பதினேழாயிரத்து இருநூறுபேர்.", "en": "All these the sons of Jediael, by the heads of their fathers, mighty men of valour, were seventeen thousand and two hundred soldiers , fit to go out for war and battle."}, {"verse": 12, "start": 173.53, "end": 180.88, "ta": "சுப்பீமும், உப்பீமும் ஈரின் குமாரர், ஊசிம் ஆகேரின் குமாரரில் ஒருவன்.", "en": "Shuppim also, and Huppim, the children of Ir, and Hushim, the sons of Aher."}, {"verse": 13, "start": 180.88, "end": 190.43, "ta": "நப்தலியின் குமாரரான பில்காளின் பேரன்மார், யாத்சியேல், கூனி, எத்சோ, சல்லுூம் என்பவர்கள்.", "en": "The sons of Naphtali; Jahziel, and Guni, and Jezer, and Shallum, the sons of Bilhah."}, {"verse": 14, "start": 190.43, "end": 205.66, "ta": "மனாசேயின் புத்திரரில் ஒருவன் குலஸ்திரீயினிடத்தில் பிறந்த அஸ்ரியேல்; அவன் மறுமனையாட்டியாகிய அராமிய ஸ்திரீயினிடத்தில் கீலேயாத்தின் தகப்பனாகிய மாகீர் பிறந்தான்.", "en": "The sons of Manasseh; Ashriel, whom she bare: ( but his concubine the Aramitess bare Machir the father of Gilead:"}, {"verse": 15, "start": 205.66, "end": 223.0, "ta": "மாகீர் மாக்காள் என்னும் பேருள்ள உப்பீம் சுப்பீம் என்பவர்களின் சகோதரியை விவாகம்பண்ணினான்; மனாசேயின் இரண்டாம் குமாரன் செலோப்பியாத்; செலோப்பியாத்திற்குக் குமாரத்திகளிருந்தார்கள்.", "en": "And Machir took to wife the sister of Huppim and Shuppim, whose sister’s name was Maachah;) and the name of the second was Zelophehad: and Zelophehad had daughters."}, {"verse": 16, "start": 223.0, "end": 239.28, "ta": "மாகீரின் பெண்ஜாதியாகிய மாக்காள் ஒரு குமாரனைப் பெற்று, அவனுக்குப் பேரேஸ் என்று பேரிட்டாள்; இவன் சகோதரன் பேர் சேரேஸ்; இவனுடைய குமாரர் ஊலாம், ரேகேம் என்பவர்கள்.", "en": "And Maachah the wife of Machir bare a son, and she called his name Peresh; and the name of his brother was Sheresh; and his sons were Ulam and Rakem."}, {"verse": 17, "start": 239.28, "end": 249.55, "ta": "ஊலாமின் குமாரரில் ஒருவன் பேதான்; இவர்கள் மனாசேயின் குமாரனாகிய மாகீருக்குப் பிறந்த கீலேயாத் புத்திரர்.", "en": "And the sons of Ulam; Bedan. These were the sons of Gilead, the son of Machir, the son of Manasseh."}, {"verse": 18, "start": 249.55, "end": 256.98, "ta": "இவன் சகோதரியாகிய அம்மொளெகேத் இஸ்கோதையும் அபியேசரையும் மாகலாவையும் பெற்றாள்.", "en": "And his sister Hammoleketh bare Ishod, and Abiezer, and Mahalah."}, {"verse": 19, "start": 256.98, "end": 264.5, "ta": "செமிதாவின் குமாரர், அகியான், சேகேம், லிக்கே, அனியாம் என்பவர்கள்.", "en": "And the sons of Shemida were, Ahian, and Shechem, and Likhi, and Aniam."}, {"verse": 20, "start": 264.5, "end": 279.55, "ta": "எப்பிராயீமின் குமாரரில் ஒருவன் சுத்தெலாக்; இவனுடைய குமாரன் பேரேத்; இவனுடைய குமாரன் தாகாத்; இவனுடைய குமாரன் எலாதா; இவனுடைய குமாரன் தாகாத்.", "en": "And the sons of Ephraim; Shuthelah, and Bered his son, and Tahath his son, and Eladah his son, and Tahath his son,"}, {"verse": 21, "start": 279.55, "end": 297.6, "ta": "இவனுடைய குமாரன் சாபாத்; இவனுடைய குமாரர் கத்தெலாக், எத்சேர், எலியாத்; இவர்கள் தேசத்தில் பிறந்த காத்தூராருடைய ஆடுமாடுகளைப் பிடிக்கப்போனபடியால் அவர்கள் இவர்களைக் கொன்றுபோட்டார்கள்.", "en": "And Zabad his son, and Shuthelah his son, and Ezer, and Elead, whom the men of Gath that were born in that land slew, because they came down to take away their cattle."}, {"verse": 22, "start": 297.6, "end": 308.22, "ta": "அவர்கள் தகப்பனாகிய எப்பிராயீம் அநேகநாள் துக்கங்கொண்டாடுகையில், அவன் சகோதரர் அவனுக்கு ஆறுதல் சொல்லவந்தார்கள்.", "en": "And Ephraim their father mourned many days, and his brethren came to comfort him."}, {"verse": 23, "start": 308.22, "end": 326.54, "ta": "பின்பு அவன் தன் பெண்ஜாதியினிடத்தில் பிரவேசித்ததினால், அவள் கர்ப்பந்தரித்து ஒரு குமாரனைப் பெற்றாள்; அவன், தன் குடும்பத்துக்குத் தீங்கு உண்டானதினால், இவனுக்குப் பெரீயா என்று பேரிட்டான்.", "en": "And when he went in to his wife, she conceived, and bare a son, and he called his name Beriah, because it went evil with his house."}, {"verse": 24, "start": 326.54, "end": 336.36, "ta": "இவனுடைய குமாரத்தியாகிய சேராள் கீழ்ப்புறமும் மேற்புறமுமான பெத்தோரோனையும், ஊசேன்சேராவையும் கட்டினவள்.", "en": "(And his daughter was Sherah, who built Beth-horon the nether, and the upper, and Uzzen-sherah.)"}, {"verse": 25, "start": 336.36, "end": 346.98, "ta": "அவனுடைய குமாரர், ரேப்பாக், ரேசேப் என்பவர்கள்; இவனுடைய குமாரன் தேலாக்; இவனுடைய குமாரன் தாகான்.", "en": "And Rephah was his son, also Resheph, and Telah his son, and Tahan his son,"}, {"verse": 26, "start": 346.98, "end": 355.21, "ta": "இவனுடைய குமாரன் லாதான், இவனுடைய குமாரன் அம்மியூத்; இவனுடைய குமாரன் எலிஷாமா.", "en": "Laadan his son, Ammihud his son, Elishama his son,"}, {"verse": 27, "start": 355.21, "end": 359.99, "ta": "இவனுடைய குமாரன் நூன்: இவனுடைய குமாரன் யோசுவா.", "en": "Non his son, Jehoshua his son."}, {"verse": 28, "start": 359.99, "end": 380.52, "ta": "அவர்களுடைய காணியாட்சியும், வாசஸ்தலங்களும், கிழக்கேயிருக்கிற நாரானும், மேற்கேயிருக்கிற கேசேரும் அதின் கிராமங்களும், பெத்தேலும் அதன் கிராமங்களும், சீகேமும் அதின் கிராமங்களும், காசாமட்டுக்குமுள்ள அதன் கிராமங்களும்,", "en": "And their possessions and habitations were , Beth-el and the towns thereof, and eastward Naaran, and westward Gezer, with the towns thereof; Shechem also and the towns thereof, unto Gaza and the towns thereof:"}, {"verse": 29, "start": 380.52, "end": 402.47, "ta": "மனாசே புத்திரரின் பக்கத்திலே பெத்செயானும் அதின் கிராமங்களும், தானாகும் அதின் கிராமங்களும், மெகிதோவும் அதின் கிராமங்களும், தோரும் அதின் கிராமங்களுமே; இவ்விடங்களில் இஸ்ரவேலின் குமாரனாகிய யோசேப்பின் புத்திரர் குடியிருந்தார்கள்.", "en": "And by the borders of the children of Manasseh, Beth-shean and her towns, Taanach and her towns, Megiddo and her towns, Dor and her towns. In these dwelt the children of Joseph the son of Israel."}, {"verse": 30, "start": 402.47, "end": 411.85, "ta": "ஆசேரின் குமாரர், இம்னா, இஸ்வா, இஸ்வி, பெரீயு என்பவர்கள்; இவர்கள் சகோதரி சேராள்.", "en": "The sons of Asher; Imnah, and Isuah, and Ishuai, and Beriah, and Serah their sister."}, {"verse": 31, "start": 411.85, "end": 420.52, "ta": "பெரீயாவின் குமாரர், ஏபேர், மல்கியேல் என்பவர்கள்; இவன் பிர்சாவீத்தின் தகப்பன்.", "en": "And the sons of Beriah; Heber, and Malchiel, who is the father of Birzavith."}, {"verse": 32, "start": 420.52, "end": 429.72, "ta": "ஏபேர் யப்லேத்தையும், சோமேரையும், ஒத்தாமையும், இவர்கள் சகோதரியாகிய சூகாளையும் பெற்றான்.", "en": "And Heber begat Japhlet, and Shomer, and Hotham, and Shua their sister."}, {"verse": 33, "start": 429.72, "end": 439.19, "ta": "யப்லேத்தின் குமாரர் பாராக், பிம்மால், ஆஸ்வாத் என்பவர்கள்; இவர்களே யப்லேத்தின் குமாரர்.", "en": "And the sons of Japhlet; Pasach, and Bimhal, and Ashvath. These are the children of Japhlet."}, {"verse": 34, "start": 439.19, "end": 445.39, "ta": "சோமேரின் குமாரர் அகி, ரோகா, எகூபா, ஆராம் என்பவர்கள்.", "en": "And the sons of Shamer; Ahi, and Rohgah, Jehubbah, and Aram."}, {"verse": 35, "start": 445.39, "end": 453.7, "ta": "அவன் சகோதரனாகிய ஏலேமின் குமாரர், சோபாக், இம்னா, சேலேஸ், ஆமால் என்பவர்கள்.", "en": "And the sons of his brother Helem; Zophah, and Imna, and Shelesh, and Amal."}, {"verse": 36, "start": 453.7, "end": 460.61, "ta": "சோபாக்கின் குமாரர், சூவாக், அர்னெப்பர், சூகால், பேரி, இம்ரா,", "en": "The sons of Zophah; Suah, and Harnepher, and Shual, and Beri, and Imrah,"}, {"verse": 37, "start": 460.61, "end": 467.42, "ta": "பேசேர், ஓத், சம்மா, சில்சா, இத்ரான், பேரா என்பவர்கள்.", "en": "Bezer, and Hod, and Shamma, and Shilshah, and Ithran, and Beera."}, {"verse": 38, "start": 467.42, "end": 473.44, "ta": "யெத்தேரின் குமாரர், எப்புன்னே பிஸ்பா, ஆரா என்பவர்கள்.", "en": "And the sons of Jether; Jephunneh, and Pispah, and Ara."}, {"verse": 39, "start": 473.44, "end": 480.08, "ta": "உல்லாவின் குமாரர், ஆராக், அன்னியேல், ரித்சியா என்பவர்கள்.", "en": "And the sons of Ulla; Arah, and Haniel, and Rezia."}, {"verse": 40, "start": 480.08, "end": 502.73, "ta": "ஆசேரின் புத்திரராகிய இவர்கள் எல்லாரும் தங்கள் பிதாக்களின் வம்சத்தலைவரும் தெரிந்துகொள்ளப்பட்ட பராக்கிரமசாலிகளும், பிரபுக்களின் தலைவருமாயிருந்தார்கள்; அவர்கள் வம்ச அட்டவணைகளில் யுத்தத்திற்குப் போகத்தக்க சேவகரின் இலக்கம் இருபத்தாறாயிரம்பேர்.", "en": "All these were the children of Asher, heads of their father’s house, choice and mighty men of valour, chief of the princes. And the number throughout the genealogy of them that were apt to the war and to battle was twenty and six thousand men."}]}, "8": {"chapter": 8, "duration": 318.83, "audio_url": "audio_ot/OT13_08.mp3", "total_verses": 40, "verses": [{"verse": 1, "start": 3.8, "end": 15.81, "ta": "பென்யமீன், பேலா என்னும் தன் மூத்த குமாரனையும், அஸ்பால் என்னும் இரண்டாம் குமாரனையும், அகராக் என்னும் மூன்றாம் குமாரனையும்,", "en": "Now Benjamin begat Bela his firstborn, Ashbel the second, and Aharah the third,"}, {"verse": 2, "start": 15.81, "end": 23.75, "ta": "நேகா என்னும் நாலாம் குமாரனையும், ரப்பா என்னும் ஐந்தாம் குமாரனையும் பெற்றான்.", "en": "Nohah the fourth, and Rapha the fifth."}, {"verse": 3, "start": 23.75, "end": 30.34, "ta": "பேலாவுக்கு இருந்த குமாரர் ஆதார், கேரா, அபியூத் என்பவர்கள்.", "en": "And the sons of Bela were, Addar, and Gera, and Abihud,"}, {"verse": 4, "start": 30.34, "end": 33.23, "ta": "அபிசுவா, நாமான், அகோவா,", "en": "And Abishua, and Naaman, and Ahoah,"}, {"verse": 5, "start": 33.23, "end": 39.37, "ta": "கேரா, செப்புப்பான், ஊராம் என்பவர்கள் எகூதின் குமாரர்.", "en": "And Gera, and Shephuphan, and Huram."}, {"verse": 6, "start": 39.37, "end": 52.46, "ta": "கேபாவின் குடிகளுக்கு மூப்பான தலைவராயிருந்து, இவர்களை மனாகாத்திற்கு அழைத்துக்கொண்டுபோனவர்கள், நாமான், அகியா, கேரா என்பவர்களே.", "en": "And these are the sons of Ehud: these are the heads of the fathers of the inhabitants of Geba, and they removed them to Manahath:"}, {"verse": 7, "start": 52.46, "end": 60.76, "ta": "கேரா அவர்களை அங்கே அழைத்துக்கொண்டுபோனபின்பு, ஊசாவையும், அகியூதையும் பெற்றான்.", "en": "And Naaman, and Ahiah, and Gera, he removed them, and begat Uzza, and Ahihud."}, {"verse": 8, "start": 60.76, "end": 71.96, "ta": "அவர்களை அனுப்பிவிட்டபின், சகராயீம் மோவாப் தேசத்திலே ஊகிம் பாராள் என்னும் தன் பெண்ஜாதிகளிடத்திலே பெற்ற பிள்ளைகளைத்தவிர,", "en": "And Shaharaim begat children in the country of Moab, after he had sent them away; Hushim and Baara were his wives."}, {"verse": 9, "start": 71.96, "end": 79.9, "ta": "தன் பெண்ஜாதியாகிய ஓதேசாலே யோவாபையும், சீபீயாவையும், மேசாவையும், மல்காமையும்,", "en": "And he begat of Hodesh his wife, Jobab, and Zibia, and Mesha, and Malcham,"}, {"verse": 10, "start": 79.9, "end": 90.47, "ta": "எயூசையும், சாகியாவையும், மிர்மாமவையும் பெற்றான். பிதாக்களின் தலைவரான இவர்கள் அவனுடைய குமாரர்.", "en": "And Jeuz, and Shachia, and Mirma. These were his sons, heads of the fathers."}, {"verse": 11, "start": 90.47, "end": 95.97, "ta": "ஊசிம் வழியாய் அவன் அபிதூபையும் எல்பாலையும் பெற்றான்.", "en": "And of Hushim he begat Abitub, and Elpaal."}, {"verse": 12, "start": 95.97, "end": 107.26, "ta": "எல்பாலின் குமாரர், ஏபேர், மீஷாம், சாமேத்; இவன் ஓனோவையும் லோதையும் அதின் கிராமங்களையும் உண்டாக்கினவன்.", "en": "The sons of Elpaal; Eber, and Misham, and Shamed, who built Ono, and Lod, with the towns thereof:"}, {"verse": 13, "start": 107.26, "end": 117.91, "ta": "பெரீயாவும் சேமாவும் ஆயலோன் குடிகளுடைய பிதாக்களிலே தலைவராயிருந்தார்கள்; இவர்கள் காத்தின் குடிகளை ஓட்டிவிட்டார்கள்", "en": "Beriah also, and Shema, who were heads of the fathers of the inhabitants of Aijalon, who drove away the inhabitants of Gath:"}, {"verse": 14, "start": 117.91, "end": 120.8, "ta": "அகியோ, சாஷாக், எரேமோத்,", "en": "And Ahio, Shashak, and Jeremoth,"}, {"verse": 15, "start": 120.8, "end": 123.6, "ta": "செபதியா, ஆராத், ஆதேர்,", "en": "And Zebadiah, and Arad, and Ader,"}, {"verse": 16, "start": 123.6, "end": 129.46, "ta": "காயேல், இஸ்பா, யோகா என்பவர்கள் பெரீயாவின் குமாரர்.", "en": "And Michael, and Ispah, and Joha, the sons of Beriah;"}, {"verse": 17, "start": 129.46, "end": 133.62, "ta": "செபதியா, மெசுல்லாம், இஸ்கி, ஏபேர்,", "en": "And Zebadiah, and Meshullam, and Hezeki, and Heber,"}, {"verse": 18, "start": 133.62, "end": 140.03, "ta": "இஸ்மெராயி, இஸ்லியா, யோபாப் என்பவர்கள் எல்பாலின் குமாரர்.", "en": "Ishmerai also, and Jezliah, and Jobab, the sons of Elpaal;"}, {"verse": 19, "start": 140.03, "end": 143.01, "ta": "யாக்கிம், சிக்ரி, சப்தி,", "en": "And Jakim, and Zichri, and Zabdi,"}, {"verse": 20, "start": 143.01, "end": 146.44, "ta": "எலியேனாய், சில்தாய், எலியேல்,", "en": "And Elienai, and Zilthai, and Eliel,"}, {"verse": 21, "start": 146.44, "end": 152.49, "ta": "அதாயா, பெராயா, சிம்ராத் என்பவர்கள் சிமியின் குமாரர்.", "en": "And Adaiah, and Beraiah, and Shimrath, the sons of Shimhi;"}, {"verse": 22, "start": 152.49, "end": 155.46, "ta": "இஸ்பான், ஏபேர், ஏலியேல்,", "en": "And Ishpan, and Heber, and Eliel,"}, {"verse": 23, "start": 155.46, "end": 158.35, "ta": "அப்தோன், சிக்ரி, ஆனான்,", "en": "And Abdon, and Zichri, and Hanan,"}, {"verse": 24, "start": 158.35, "end": 161.42, "ta": "அனனியா, ஏலாம், அந்தோதியா,", "en": "And Hananiah, and Elam, and Antothijah,"}, {"verse": 25, "start": 161.42, "end": 166.57, "ta": "இபிதியா, பெயேல் என்பவர்கள் ஆஷாக்கின் குமாரர்.", "en": "And Iphedeiah, and Penuel, the sons of Shashak;"}, {"verse": 26, "start": 166.57, "end": 170.09, "ta": "சம்சேராய், செகரியா, அத்தாலியா,", "en": "And Shamsherai, and Shehariah, and Athaliah,"}, {"verse": 27, "start": 170.09, "end": 176.14, "ta": "யரெஷியா, எலியா, சிக்ரி என்பவர்கள் எராகாமின் குமாரர்.", "en": "And Jaresiah, and Eliah, and Zichri, the sons of Jeroham."}, {"verse": 28, "start": 176.14, "end": 184.8, "ta": "இவர்கள் தங்கள் சந்ததிகளின் பிதாக்களிலே தலைவராயிருந்து, எருசலேமிலே குடியிருந்தார்கள்.", "en": "These were heads of the fathers, by their generations, chief men . These dwelt in Jerusalem."}, {"verse": 29, "start": 184.8, "end": 193.47, "ta": "கிபியோனிலே குடியிருந்தவன், கிபியோனின் மூப்பன்; அவன் பெண்ஜாதியின்பேர் மாக்காள்.", "en": "And at Gibeon dwelt the father of Gibeon; whose wife’s name was Maachah:"}, {"verse": 30, "start": 193.47, "end": 201.78, "ta": "அவன் மூத்த குமாரன் அப்தோன் என்பவன்; மற்றவர்கள் சூர், கீஸ், பாகால், நாதாப்,", "en": "And his firstborn son Abdon, and Zur, and Kish, and Baal, and Nadab,"}, {"verse": 31, "start": 201.78, "end": 206.11, "ta": "கேதோர், அகியோ, சேகேர் என்பவர்கள்.", "en": "And Gedor, and Ahio, and Zacher."}, {"verse": 32, "start": 206.11, "end": 218.57, "ta": "மிக்லோத் சிமியாவைப் பெற்றான்; இவர்களும் தங்கள் சகோதரரோடுங்கூட எருசலேமிலே தங்கள் சகோதரருக்குச் சமீபத்தில் குடியிருந்தார்கள்.", "en": "And Mikloth begat Shimeah. And these also dwelt with their brethren in Jerusalem, over against them."}, {"verse": 33, "start": 218.57, "end": 231.93, "ta": "நேர் கீசைப் பெற்றான்; கீஸ் சவுலைப் பெற்றான்; சவுல் யோனத்தானையும், மல்கிசூவாவையும், அபினதாபையும், எஸ்பாலையும் பெற்றான்.", "en": "And Ner begat Kish, and Kish begat Saul, and Saul begat Jonathan, and Malchi-shua, and Abinadab, and Esh-baal."}, {"verse": 34, "start": 231.93, "end": 238.43, "ta": "யோனத்தானின் குமாரன் மேரிபால்; மேரிபால் மீகாவைப் பெற்றான்.", "en": "And the son of Jonathan was Merib-baal; and Merib-baal begat Micah."}, {"verse": 35, "start": 238.43, "end": 245.74, "ta": "மீகாவின் குமாரர், பித்தோன், மேலேக், தரேயா, ஆகாஸ் என்பவர்கள்.", "en": "And the sons of Micah were , Pithon, and Melech, and Tarea, and Ahaz."}, {"verse": 36, "start": 245.74, "end": 258.2, "ta": "ஆகாஸ் யோகதாவைப் பெற்றான்; யோகதா அலமேத்தையும், அஸ்மாவேத்தையும், சிம்ரியையும் பெற்றான்; சிம்ரி மோசாவைப் பெற்றான்.", "en": "And Ahaz begat Jehoadah; and Jehoadah begat Alemeth, and Azmaveth, and Zimri; and Zimri begat Moza,"}, {"verse": 37, "start": 258.2, "end": 268.4, "ta": "மோசா பினியாவைப் பெற்றான், இவன் குமாரன் ரப்பா; இவன் குமாரன் எலியாசா; இவன் குமாரன் ஆத்சேல்.", "en": "And Moza begat Binea: Rapha was his son, Eleasah his son, Azel his son:"}, {"verse": 38, "start": 268.4, "end": 285.46, "ta": "ஆத்சேலுக்கு ஆறுகுமாரர் இருந்தார்கள்; அவர்கள் நாமங்களாவன, அஸ்ரீக்காம், பொக்குரு, இஸ்மவேல், செகரியா, ஒபதியா, ஆனான்; இவர்கள் எல்லாரும் ஆத்சேலின் குமாரர்.", "en": "And Azel had six sons, whose names are these, Azrikam, Bocheru, and Ishmael, and Sheariah, and Obadiah, and Hanan. All these were the sons of Azel."}, {"verse": 39, "start": 285.46, "end": 298.46, "ta": "அவன் சகோதரனாகிய எசேக்கின் குமாரர், ஊலாம் என்னும் மூத்தகுமாரனும், ஏகூஸ் என்னும் இரண்டாம் குமாரனும், எலிபேலேத் என்னும் மூன்றாம் குமாரனுமே", "en": "And the sons of Eshek his brother were , Ulam his firstborn, Jehush the second, and Eliphelet the third."}, {"verse": 40, "start": 298.46, "end": 317.33, "ta": "ஊலாமின் குமாரர் பராக்கிரமசாலிகளான வில்வீரராய் இருந்தார்கள்; அவர்களுக்கு அநேகம் புத்திரர் பெளத்திரர் இருந்தார்கள்; அவர்கள் தொகை நூற்றைம்பதுபேர்; இவர்கள் எல்லாரும் பென்யமீன் புத்திரர்.", "en": "And the sons of Ulam were mighty men of valour, archers, and had many sons, and sons’ sons, an hundred and fifty. All these are of the sons of Benjamin."}]}, "9": {"chapter": 9, "duration": 513.57, "audio_url": "audio_ot/OT13_09.mp3", "total_verses": 44, "verses": [{"verse": 1, "start": 3.8, "end": 25.05, "ta": "இஸ்ரவேலர் எல்லாரும் தங்கள் வம்ச வரலாற்றின்படி எண்ணப்பட்டார்கள்; இவர்கள் நாமங்கள் இஸ்ரவேல் ராஜாக்களின் புஸ்தகத்தில் எழுதியிருக்கிறது, யூதா கோத்திரத்தார் தங்கள் துரோகத்தினிமித்தம், பாபிலோனுக்குச் சிறைபிடித்துக்கொண்டுபோகப்பட்டார்கள்.", "en": "So all Israel were reckoned by genealogies; and, behold, they were written in the book of the kings of Israel and Judah, who were carried away to Babylon for their transgression."}, {"verse": 2, "start": 25.05, "end": 35.64, "ta": "தங்கள் காணியாட்சியிலும் தங்கள் பட்டணங்களிலும் முன் குடியிருந்தவர்கள் இஸ்ரவேலரும் ஆசாரியரும் லேவியரும் நிதினீமியருமே.", "en": "Now the first inhabitants that dwelt in their possessions in their cities were , the Israelites, the priests, Levites, and the Nethinims."}, {"verse": 3, "start": 35.64, "end": 47.74, "ta": "யூதா புத்திரரிலும், பென்யமீன் புத்திரரிலும், எப்பிராயீம் மனாசே என்பவர்களின் புத்திரரிலும், எருசலேமில் குடியிருந்தவர்கள் யாரென்றால்,", "en": "And in Jerusalem dwelt of the children of Judah, and of the children of Benjamin, and of the children of Ephraim, and Manasseh;"}, {"verse": 4, "start": 47.74, "end": 59.09, "ta": "யூதாவின் புத்திரனாகிய பேரேசின் சந்ததியில் பானியின் குமாரனாகிய இம்ரியின் மகனான உம்ரிΕ்குப் பிறந்த அம்மியூதிɠύ குமாரன் Ίத்தாய்.", "en": "Uthai the son of Ammihud, the son of Omri, the son of Imri, the son of Bani, of the children of Pharez the son of Judah."}, {"verse": 5, "start": 59.09, "end": 64.59, "ta": "சேலாவின͠சந்ததியில் மூத்தவனாகிய அசாயாவும், அவன் பிள்ளைகளும்,", "en": "And of the Shilonites; Asaiah the firstborn, and his sons."}, {"verse": 6, "start": 64.59, "end": 71.87, "ta": "சேராவின் சந்ததியில் யெகுவேலும், அவன் சகோதரராகிய அறுநூற்றுத்தொண்ணூறுபேருமே.", "en": "And of the sons of Zerah; Jeuel, and their brethren, six hundred and ninety."}, {"verse": 7, "start": 71.87, "end": 80.43, "ta": "பென்யமீன் புத்திரரில் அசெனூவாவின் குமாரனாகிய ஓதாவியாவுக்குப் பிறந்த மெசுல்லாமின் மகன் சல்லு.", "en": "And of the sons of Benjamin; Sallu the son of Meshullam, the son of Hodaviah, the son of Hasenuah,"}, {"verse": 8, "start": 80.43, "end": 95.07, "ta": "எரோகாமின் குமாரன் இப்னெயா; மிக்கிரியின் குமாரனாகிய ஊசியின் மகன் ஏலா; இப்னியாவின் குமாரனாகிய ரேகுவேலுக்குப் பிறந்த செபதியாவின் மகன் மெசுல்லாம் என்பவர்களும்;", "en": "And Ibneiah the son of Jeroham, and Elah the son of Uzzi, the son of Michri, and Meshullam the son of Shephathiah, the son of Reuel, the son of Ibnijah;"}, {"verse": 9, "start": 95.07, "end": 110.4, "ta": "தங்கள் சந்ததிகளின்படி இருந்த இவர்கள் சகோதரராகிய தொளாயிரத்து ஐம்பத்தாறுபேருமே; இந்த மனுஷர் எல்லாரும், தங்கள் பிதாக்களின் வம்சத்திலே பிதாக்களின் தலைவராயிருந்தார்கள்.", "en": "And their brethren, according to their generations, nine hundred and fifty and six. All these men were chief of the fathers in the house of their fathers."}, {"verse": 10, "start": 110.4, "end": 114.97, "ta": "ஆசாரியர்களில் யெதாயா, யோயாரிப், யாகின்.", "en": "And of the priests; Jedaiah, and Jehoiarib, and Jachin,"}, {"verse": 11, "start": 114.97, "end": 128.18, "ta": "அகிதூபின் குமாரனாகிய மெராயோதின் மகன் சாதோக்குக்குப் பிறந்த மெசுல்லாவின் குமாரனாகிய இல்க்கியாவின் மகன் அசரியா என்பவன் தேவாலயத்து விசாரணைக் கர்த்தன்.", "en": "And Azariah the son of Hilkiah, the son of Meshullam, the son of Zadok, the son of Meraioth, the son of Ahitub, the ruler of the house of God;"}, {"verse": 12, "start": 128.18, "end": 145.03, "ta": "மல்கியாவின் குமாரனாகிய பஸ்கூருக்குப் பிறந்த எரோகாமின் மகன் அதாயா; இம்மெரின் குமாரனாகிய மெசில்லேமித்தின் மகன் மெசுல்லாமுக்குப் பிறந்த யாசெராவின் குமாரனாகிய ஆதியேலின் மகன் மாசாய் என்பவர்களும்,", "en": "And Adaiah the son of Jeroham, the son of Pashur, the son of Malchijah, and Maasiai the son of Adiel, the son of Jahzerah, the son of Meshullam, the son of Meshillemith, the son of Immer;"}, {"verse": 13, "start": 145.03, "end": 158.24, "ta": "அவர்கள் சகோதரரும், தங்கள் பிதாக்களின் வம்சத்தலைவரான ஆயிரத்துஎழுநூற்று அறுபதுபேர் தேவாலயத்துக்கடுத்த பணிவிடைக்குத் திறமையுள்ளவர்களாயிருந்தார்கள்.", "en": "And their brethren, heads of the house of their fathers, a thousand and seven hundred and threescore; very able men for the work of the service of the house of God."}, {"verse": 14, "start": 158.24, "end": 166.62, "ta": "லேவியரில் மெராரியின் சந்ததியான அசபியாவின் குமாரனாகிய அஸ்ரீகாமுக்குப் பிறந்த அசூபின் மகன் செமாயா,", "en": "And of the Levites; Shemaiah the son of Hasshub, the son of Azrikam, the son of Hashabiah, of the sons of Merari;"}, {"verse": 15, "start": 166.62, "end": 175.17, "ta": "பக்பக்கார், ஏரேஸ், காலால், ஆசாபின் குமாரனாகிய சிக்ரிக்குப் பிறந்த மிகாவின் மகன் மத்தனியா,", "en": "And Bakbakkar, Heresh, and Galal, and Mattaniah the son of Micah, the son of Zichri, the son of Asaph;"}, {"verse": 16, "start": 175.17, "end": 189.14, "ta": "எதுத்தூனின் குமாரனாகிய காலாலுக்குப் பிறந்த செமாயாவின் மகன் ஒபதியா; நெத்தோபாத்தியரின் கிராமங்களில் குடியிருந்த எல்க்கானாவின் குமாரனாகிய ஆசாவின் மகன் பெரகியா,", "en": "And Obadiah the son of Shemaiah, the son of Galal, the son of Jeduthun, and Berechiah the son of Asa, the son of Elkanah, that dwelt in the villages of the Netophathites."}, {"verse": 17, "start": 189.14, "end": 200.99, "ta": "வாசல் காவலாளிகளாகிய சல்லுூம், அக்கூப், தல்மோன், அகிமான் என்பவர்களும், இவர்கள் சகோதரருமே; இவர்கள் தலைவன் சல்லுூம்.", "en": "And the porters were , Shallum, and Akkub, and Talmon, and Ahiman, and their brethren: Shallum was the chief;"}, {"verse": 18, "start": 200.99, "end": 208.53, "ta": "லேவிபுத்திரரின் சேனைகளில் இவர்கள் கிழக்கேயிருக்கிற ராஜாவின் வாசலைக் காவல்காத்துவந்தார்கள்", "en": "Who hitherto waited in the king’s gate eastward: they were porters in the companies of the children of Levi."}, {"verse": 19, "start": 208.53, "end": 233.85, "ta": "கோராகின் குமாரனாகிய எபியாசாபுக்குப் பிறந்த கோரேயின் மகன் சல்லுூமும், அவன் பிதாவின் வம்சத்தாராகிய அவனுடைய சகோதரருமான கோராகியர் பணிவிடைவேலையை விசாரித்து, அவர்கள் பிதாக்கள் கர்த்தருடைய பாளயத்திலே வாசஸ்தலத்திற்குப்போகிற வழியைக் காவல்காத்ததுபோல, வாசஸ்தலத்து வாசல்களைக் காத்துவந்தார்கள்.", "en": "And Shallum the son of Kore, the son of Ebiasaph, the son of Korah, and his brethren, of the house of his father, the Korahites, were over the work of the service, keepers of the gates of the tabernacle: and their fathers, being over the host of the LORD , were keepers of the entry."}, {"verse": 20, "start": 233.85, "end": 244.77, "ta": "எலெயாசாரின் குமாரனாகிய பினெகாசுடனே கர்த்தர் இருந்தபடியினால், அவன் முற்காலத்திலே அவர்கள்மேல் விசாரணைக்காரனாயிருந்தான்.", "en": "And Phinehas the son of Eleazar was the ruler over them in time past, and the LORD was with him."}, {"verse": 21, "start": 244.77, "end": 251.97, "ta": "மெசெல்மியாவின் குமாரனாகிய சகரியா ஆசரிப்புக் கூடாரவாசல் காவல்காரனாயிருந்தான்.", "en": "And Zechariah the son of Meshelemiah was porter of the door of the tabernacle of the congregation."}, {"verse": 22, "start": 251.97, "end": 275.42, "ta": "வாசல்களைக் காக்கிறதற்குத் தெரிந்துகொள்ளப்பட்ட இவர்களெல்லாரும் இருநூற்றுப் பன்னிரண்டுபேராயிருந்து, தங்கள் கிராமங்களின்படியே தங்கள் வம்சத்து அட்டவணைகளில் எழுதப்பட்டார்கள்; தாவீதும், ஞானதிருஷ்டிக்காரனாகிய சாமுவேலும், அவர்களைத் தங்கள் வேலைகளில் வைத்தார்கள்.", "en": "All these which were chosen to be porters in the gates were two hundred and twelve. These were reckoned by their genealogy in their villages, whom David and Samuel the seer did ordain in their set office."}, {"verse": 23, "start": 275.42, "end": 287.53, "ta": "அப்படியே அவர்களும், அவர்கள் குமாரரும் கர்த்தருடைய ஆலயமாகிய வாசஸ்தலத்து வாசல்களைக் காக்கிறவர்களை முறைமுறையாய் விசாரித்து வந்தார்கள்.", "en": "So they and their children had the oversight of the gates of the house of the LORD , namely , the house of the tabernacle, by wards."}, {"verse": 24, "start": 287.53, "end": 296.59, "ta": "வாசல்களைக் காக்கிறவர்கள் நாலுதிசைகளாகிய கிழக்கிலும் மேற்கிலும் வடக்கிலும் தெற்கிலும் இருந்தார்கள்.", "en": "In four quarters were the porters, toward the east, west, north, and south."}, {"verse": 25, "start": 296.59, "end": 305.9, "ta": "அவர்கள் சகோதரர் தங்கள் கிராமங்களிலிருந்து, ஏழுநாளுக்கு ஒருவிசை மாறிமாறி அவர்களோடிருக்க வருவார்கள்.", "en": "And their brethren, which were in their villages, were to come after seven days from time to time with them."}, {"verse": 26, "start": 305.9, "end": 318.35, "ta": "தேவாலயத்தின் பண்டகசாலைகள் மேலும் பொக்கிஷசாலைகள்மேலுமுள்ள விசாரணை உத்தியோகம் லேவியரான அந்த நாலு பிரதான காவலாளர்வசத்தில் ஒப்புவிக்கப்பட்டது.", "en": "For these Levites, the four chief porters, were in their set office, and were over the chambers and treasuries of the house of God."}, {"verse": 27, "start": 318.35, "end": 330.28, "ta": "காவல் அவர்களுக்கு ஒப்புவித்திருந்தபடியால் அவர்கள் தேவாலயத்தைச் சுற்றிலும் இராத்தங்கியிருந்து, காலமே கதவுகளைத் திறந்துவிடுவார்கள்.", "en": "And they lodged round about the house of God, because the charge was upon them, and the opening thereof every morning pertained to them."}, {"verse": 28, "start": 330.28, "end": 342.99, "ta": "அவர்களில் சிலரிடத்தில் ஆராதனை பணிமுட்டுகள் ஒப்புவித்திருந்தது; அவர்கள் அவைகளை எண்ணி உள்ளே கொண்டுபோய், எண்ணி வெளியே கொண்டுவருவார்கள்.", "en": "And certain of them had the charge of the ministering vessels, that they should bring them in and out by tale."}, {"verse": 29, "start": 342.99, "end": 360.26, "ta": "அவர்களில் சிலர் மற்றப் பணிமுட்டுகளின் பரிசுத்த பாத்திரங்கள் எல்லாவற்றின்மேலும், மெல்லிய மா, திராட்சரசம், எண்ணெய், சாம்பிராணி, சுகந்தவர்க்கங்களின்மேலும் விசாரணைக்காரராயிருந்தார்கள்.", "en": "Some of them also were appointed to oversee the vessels, and all the instruments of the sanctuary, and the fine flour, and the wine, and the oil, and the frankincense, and the spices."}, {"verse": 30, "start": 360.26, "end": 367.03, "ta": "ஆசாரியரின் குமாரரில் சிலர் சுகந்தவர்க்கத்தால் பரிமளதைலம் இறக்குவார்கள்.", "en": "And some of the sons of the priests made the ointment of the spices."}, {"verse": 31, "start": 367.03, "end": 378.29, "ta": "லேவியரில் கோராகியனான சல்லுூமின் மூத்த குமாரனாகிய மத்தித்தியாவுக்குப் பலகாரம் சுடுகிற வேலையின் விசாரிப்பு ஒப்புவித்திருந்தது.", "en": "And Mattithiah, one of the Levites, who was the firstborn of Shallum the Korahite, had the set office over the things that were made in the pans."}, {"verse": 32, "start": 378.29, "end": 389.13, "ta": "அவர்கள் சகோதரராகிய கோகாத்தியரின் புத்திரரில் சிலருக்கு ஓய்வுநாள் தோறும் அப்பங்களை ஆயத்தப்படுத்தும் விசாரிப்பு இருந்தது.", "en": "And other of their brethren, of the sons of the Kohathites, were over the shewbread, to prepare it every sabbath."}, {"verse": 33, "start": 389.13, "end": 404.2, "ta": "இவர்களில் லேவியருடைய பிதாக்களிள் தலைவராகிய சங்கீதக்காரர் இரவும்பகலும் தங்கள் வேலையை நடத்தவேண்டியிருந்தபடியால், மற்ற வேலைக்கு நீங்கலாய்த் தங்கள் அறைகளில் இருந்தார்கள்.", "en": "And these are the singers, chief of the fathers of the Levites, who remaining in the chambers were free: for they were employed in that work day and night."}, {"verse": 34, "start": 404.2, "end": 415.29, "ta": "லேவியரில் பிதாக்களின் தலைவராகிய இவர்கள் தங்கள் சந்ததிகளுக்குத் தலைமையானவர்கள்; இவர்கள் எருசலேமிலே குடியிருந்தார்கள்.", "en": "These chief fathers of the Levites were chief throughout their generations; these dwelt at Jerusalem."}, {"verse": 35, "start": 415.29, "end": 425.37, "ta": "கிபியோனிலே குடியிருந்தவர்கள் யாரென்றால், கிபியோனின் மூப்பனாகிய யெகியேல், இவன் பெண்ஜாதியின்பேர் மாக்காள்.", "en": "And in Gibeon dwelt the father of Gibeon, Jehiel, whose wife’s name was Maachah:"}, {"verse": 36, "start": 425.37, "end": 432.48, "ta": "அவன் மூத்த குமாரனாகிய அப்தோனும், சூர், கீஸ், பாகால், நேர், நாதாப்,", "en": "And his firstborn son Abdon, then Zur, and Kish, and Baal, and Ner, and Nadab,"}, {"verse": 37, "start": 432.48, "end": 437.81, "ta": "கேதோர், அகியோ, சகரியா, மிக்லோத் என்பவர்களுமே.", "en": "And Gedor, and Ahio, and Zechariah, and Mikloth."}, {"verse": 38, "start": 437.81, "end": 450.09, "ta": "மிக்லோத் சீமியாமைப் பெற்றான்; இவர்களும் தங்கள் சகோதரரோடுங்கூட எருசலேமிலிருக்கிற தங்கள் சகோதரருக்குச் சமீபத்தில் குடியிருந்தார்கள்.", "en": "And Mikloth begat Shimeam. And they also dwelt with their brethren at Jerusalem, over against their brethren."}, {"verse": 39, "start": 450.09, "end": 462.62, "ta": "நேர் கீசைப் பெற்றான்; கீஸ் சவுலைப் பெற்றான்; சவுல் யோனத்தானையும், மல்கிசூவாவையும், அபினதாபையும், எஸ்பாலையும் பெற்றான்.", "en": "And Ner begat Kish; and Kish begat Saul; and Saul begat Jonathan, and Malchi-shua, and Abinadab, and Esh-baal."}, {"verse": 40, "start": 462.62, "end": 468.72, "ta": "யோனத்தானின் குமாரன் மெரிபால்; மெரிபால் மீகாவைப் பெற்றான்.", "en": "And the son of Jonathan was Merib-baal: and Merib-baal begat Micah."}, {"verse": 41, "start": 468.72, "end": 475.58, "ta": "மீகாவின் குமாரர், பித்தோன், மேலேக், தரேயா, ஆகாஸ் என்பவர்கள்.", "en": "And the sons of Micah were , Pithon, and Melech, and Tahrea, and Ahaz ."}, {"verse": 42, "start": 475.58, "end": 487.35, "ta": "ஆகாஸ் யாராகைப் பெற்றான்; யாராக் அலெமேத்தையும், அஸ்மாவேத்தையும், சிம்ரியையும் பெற்றான்; சிம்ரி மோசாவைப் பெற்றான்.", "en": "And Ahaz begat Jarah; and Jarah begat Alemeth, and Azmaveth, and Zimri; and Zimri begat Moza;"}, {"verse": 43, "start": 487.35, "end": 497.34, "ta": "மோசா பினியாவைப் பெற்றான்; இவன் குமாரன் ரப்பாயா; இவன் குமாரன் எலியாசா; இவன் குமாரன் ஆத்சேல்.", "en": "And Moza begat Binea; and Rephaiah his son, Eleasah his son, Azel his son."}, {"verse": 44, "start": 497.34, "end": 512.07, "ta": "ஆத்சேலுக்கு ஆறு குமாரர் இருந்தார்கள்; அவர்கள் நாமங்களாவன, அரீக்காம், பொக்குரு, இஸ்மவேல், சேராயா, ஒபதியா, ஆனான், இவர்கள் ஆத்சேலின் குமாரர்.", "en": "And Azel had six sons, whose names are these, Azrikam, Bocheru, and Ishmael, and Sheariah, and Obadiah, and Hanan: these were the sons of Azel."}]}, "10": {"chapter": 10, "duration": 182.3, "audio_url": "audio_ot/OT13_10.mp3", "total_verses": 14, "verses": [{"verse": 1, "start": 3.8, "end": 14.88, "ta": "பெலிஸ்தர் இஸ்ரவேலரோடே யுத்தபண்ணினார்கள்; இஸ்ரவேல் பெலிஸ்தருக்கு முன்பாக முறிந்தோடி, கில்போவா மலையிலே வெட்டுண்டு விழுந்தார்கள்.", "en": "Now the Philistines fought against Israel; and the men of Israel fled from before the Philistines, and fell down slain in mount Gilboa."}, {"verse": 2, "start": 14.88, "end": 26.66, "ta": "பெலிஸ்தர் சவுலையும் அவன் குமாரரையும் நெருங்கித் தொடர்ந்து, சவுலின் குமாரராகிய யோனத்தானையும் அபினதாபையும் மல்கிசூவாவையும் வெட்டிப்போட்டார்கள்.", "en": "And the Philistines followed hard after Saul, and after his sons; and the Philistines slew Jonathan, and Abinadab, and Malchi-shua, the sons of Saul."}, {"verse": 3, "start": 26.66, "end": 37.35, "ta": "சவுலுக்கு விரோதமாய் யுத்தம் பலத்தது; வில்வீரர் அவனைக்கண்டு நெருங்கினார்கள்; அப்பொழுது சவுல் வில்வீரருக்கு மிகவும் பயப்பட்டு,", "en": "And the battle went sore against Saul, and the archers hit him, and he was wounded of the archers."}, {"verse": 4, "start": 37.35, "end": 60.36, "ta": "தன் ஆயுததாரியை நோக்கி: அந்த விருத்தசேதனம் இல்லாதவர்கள் வந்து என்னை அவமானப்படுத்தாதபடிக்கு, நீ உன் பட்டயத்தை உருவி, என்னைக் குத்திப்போடு என்றான்; அவனுடைய ஆயுததாரி மிகவும் பயப்பட்டதினால் அப்படிச்செய்யமாட்டேன் என்றான். அப்பொழுது சவுல் பட்டயத்தை நட்டு அதின்மேல் விழுந்தான்.", "en": "Then said Saul to his armourbearer, Draw thy sword, and thrust me through therewith; lest these uncircumcised come and abuse me. But his armourbearer would not; for he was sore afraid. So Saul took a sword, and fell upon it."}, {"verse": 5, "start": 60.36, "end": 68.29, "ta": "சவுல் செத்துப்போனதை அவன் ஆயுததாரி கண்டபோது, அவனும் பட்டயத்தின்மேல் விழுந்து செத்துப்போனான்.", "en": "And when his armourbearer saw that Saul was dead, he fell likewise on the sword, and died."}, {"verse": 6, "start": 68.29, "end": 76.45, "ta": "அப்படியே சவுலும், அவன் மூன்றுகுமாரரும், அவன் வீட்டு மனுஷர் அனைவரும்கூடச் செத்துப்போனார்கள்.", "en": "So Saul died, and his three sons, and all his house died together."}, {"verse": 7, "start": 76.45, "end": 93.69, "ta": "ஜனங்கள் முறிந்தோடினதையும், சவுலும் அவன் குமாரரும் செத்துப்போனதையும், பள்ளத்தாக்கிலுள்ள இஸ்ரவேலர் எல்லரும் கண்டபோது தங்கள் பட்டணங்களை விட்டு ஓடிப்போனார்கள்; அப்பொழுது பெலிஸ்தர் வந்து, அவைகளில் குடியிருந்தார்கள்", "en": "And when all the men of Israel that were in the valley saw that they fled, and that Saul and his sons were dead, then they forsook their cities, and fled: and the Philistines came and dwelt in them."}, {"verse": 8, "start": 93.69, "end": 105.69, "ta": "வெட்டுண்டவர்களின் வஸ்திரங்களை உரிந்துகொள்ளப் பெலிஸ்தர் மறுநாளில் வந்தபோது, அவர்கள் சவுலையும் அவன் குமாரரையும் கில்போவா மலையிலே விழுந்துகிடக்கக் கண்டு,", "en": "And it came to pass on the morrow, when the Philistines came to strip the slain, that they found Saul and his sons fallen in mount Gilboa."}, {"verse": 9, "start": 105.69, "end": 121.47, "ta": "அவன் வஸ்திரங்களை உரிந்து, அவன் தலையையும் அவன் ஆயுதங்களையும் எடுத்துக்கொண்டு, தங்கள் விக்கிரகங்களுக்கும் ஜனங்களுக்கும் அதைப் பிரசித்தப்படுத்தும்படி பெலிஸ்தருடைய தேசத்திலே சுற்றிலும் செய்தி அனுப்பி,", "en": "And when they had stripped him, they took his head, and his armour, and sent into the land of the Philistines round about, to carry tidings unto their idols, and to the people."}, {"verse": 10, "start": 121.47, "end": 130.01, "ta": "அவன் ஆயுதங்களைத் தங்கள் தேவர்களின் கோவிலிலே வைத்து, அவன் தலையைத் தாகோன் கோவிலிலே தூக்கிவைத்தார்கள்.", "en": "And they put his armour in the house of their gods, and fastened his head in the temple of Dagon."}, {"verse": 11, "start": 130.01, "end": 137.7, "ta": "பெலிஸ்தர் சவுலுக்குச் செய்த எல்லாவற்றையுங் கீலேயாத் தேசத்து யாபேஸ் பட்டணத்தார் யாவரும் கேட்டபோது,", "en": "And when all Jabesh-gilead heard all that the Philistines had done to Saul,"}, {"verse": 12, "start": 137.7, "end": 156.25, "ta": "பராக்கிரமசாலிகள் எல்லாரும் எழுந்துபோய், சவுலின் உடலையும் அவன் குமாரரின் உடல்களையும் எடுத்து, யாபேசுக்குக் கொண்டுவந்து, அவர்கள் எலும்புகளை யாபேசிலிருக்கிற ஒரு கர்வாலிமரத்தின்கீழ் அடக்கம்பண்ணி, ஏழுநாள் உபவாசம்பண்ணினார்கள்.", "en": "They arose, all the valiant men, and took away the body of Saul, and the bodies of his sons, and brought them to Jabesh, and buried their bones under the oak in Jabesh, and fasted seven days."}, {"verse": 13, "start": 156.25, "end": 173.1, "ta": "அப்படியே சவுல் கர்த்தருடைய வார்த்தையைக் கைக்கொள்ளாமல், கர்த்தருக்குச் செய்த தன் துரோகத்தினிமித்தமும், அவன் கர்த்தரைத் தேடாமல் அஞ்சனம் பார்க்கிறவர்களைக் கேட்கும்படிக்குத் தேடினதினிமித்தமும் செத்துப்போனான்.", "en": "So Saul died for his transgression which he committed against the LORD , even against the word of the LORD , which he kept not, and also for asking counsel of one that had a familiar spirit, to enquire of it;"}, {"verse": 14, "start": 173.1, "end": 180.8, "ta": "அதற்காக அவர் அவனைக் கொன்று, ராஜ்யபாரத்தை ஈசாயின் குமாரனாகிய தாவீது வசமாகக் திருப்பினார்.", "en": "And enquired not of the LORD : therefore he slew him, and turned the kingdom unto David the son of Jesse."}]}, "11": {"chapter": 11, "duration": 530.13, "audio_url": "audio_ot/OT13_11.mp3", "total_verses": 47, "verses": [{"verse": 1, "start": 3.8, "end": 15.46, "ta": "இஸ்ரவேலர் எல்லாரும் எப்ரோனிலிருக்கிற தாவீதினிடத்தில் கூடிவந்து: இதோ, நாங்கள் உம்முடைய எலும்பும் உம்முடைய மாம்சமுமானவர்கள்.", "en": "Then all Israel gathered themselves to David unto Hebron, saying, Behold, we are thy bone and thy flesh."}, {"verse": 2, "start": 15.46, "end": 38.86, "ta": "சவுல் இன்னும் ராஜாவாயிருக்கும்போதே, நீர் இஸ்ரவேலை நடத்திக்கொண்டுபோய் நடத்திக்கொண்டுவருவீர்; என் ஜனமாகிய இஸ்ரவேலை நீர் மேய்த்து, என் ஜனமாகிய இஸ்ரவேலின்மேல் தலைவனாயிருப்பீர் என்று உம்முடைய தேவனாகிய கர்த்தர் உமக்குச் சொல்லியும் இருக்கிறார் என்றார்கள்.", "en": "And moreover in time past, even when Saul was king, thou wast he that leddest out and broughtest in Israel: and the LORD thy God said unto thee, Thou shalt feed my people Israel, and thou shalt be ruler over my people Israel."}, {"verse": 3, "start": 38.86, "end": 63.31, "ta": "அப்படியே இஸ்ரவேலின் மூப்பரெல்லாரும் எப்ரோனிலே ராஜாவினிடத்தில் வந்தார்கள்; தாவீது எப்ரோனிலே கர்த்தருக்கு முன்பாக அவர்களோடு உடன்படிக்கை பண்ணிக்கொண்டபின்பு, கர்த்தர் சாமுவேலைக்கொண்டு சொன்ன வார்த்தையின்படியே அவர்கள் தாவீதை இஸ்ரவேலின்மேல் ராஜாவாக அபிஷேகம்பண்ணினார்கள்.", "en": "Therefore came all the elders of Israel to the king to Hebron; and David made a covenant with them in Hebron before the LORD ; and they anointed David king over Israel, according to the word of the LORD by Samuel."}, {"verse": 4, "start": 63.31, "end": 74.45, "ta": "பின்பு தாவீது இஸ்ரவேல் அனைத்தோடுங்கூட எபூசாகிய எருசலேமுக்குப் போனான்; எபூசியர் அத்தேசத்தின் குடிகளாயிருந்தார்கள்.", "en": "And David and all Israel went to Jerusalem, which is Jebus; where the Jebusites were , the inhabitants of the land."}, {"verse": 5, "start": 74.45, "end": 89.5, "ta": "அப்பொழுது எபூசின் குடிகள் தாவீதை நோக்கி: நீ இதற்குள் பிரவேசிப்பதில்லை என்றார்கள்; ஆனாலும் தாவீது சீயோன் கோட்டையைப் பிடித்தான்; அது தாவீதின் நகரமாயிற்று.", "en": "And the inhabitants of Jebus said to David, Thou shalt not come hither. Nevertheless David took the castle of Zion, which is the city of David."}, {"verse": 6, "start": 89.5, "end": 106.29, "ta": "எபூசியரை முறிய அடிக்கிறதில் எவன் முந்தினவனாயிருக்கிறானோ, அவன் தலைவனும் சேனாபதியுமாயிருப்பானென்று தாவீது சொல்லியிருந்தான்; செருயாவின் குமாரனாகிய யோவாப் முந்தி ஏறித் தலைவனானான்.", "en": "And David said, Whosoever smiteth the Jebusites first shall be chief and captain. So Joab the son of Zeruiah went first up, and was chief."}, {"verse": 7, "start": 106.29, "end": 114.21, "ta": "தாவீது அந்தக் கோட்டையில் வாசம்பண்ணினபடியினால், அது தாவீதின் நகரம் என்னப்பட்டது.", "en": "And David dwelt in the castle; therefore they called it the city of David."}, {"verse": 8, "start": 114.21, "end": 125.0, "ta": "பிற்பாடு அவன் நகரத்தை மில்லோ தொடங்கிச் சுற்றிலும் கட்டினான்; யோவாப் நகரத்தின் மற்ற இடங்களைப் பழுதுபார்த்தான்.", "en": "And he built the city round about, even from Millo round about: and Joab repaired the rest of the city."}, {"verse": 9, "start": 125.0, "end": 133.18, "ta": "தாவீது நாளுக்குநாள் விருத்தியடைந்தான்; சேனைகளுடைய கர்த்தர் அவனோடேகூட இருந்தார்.", "en": "So David waxed greater and greater: for the LORD of hosts was with him."}, {"verse": 10, "start": 133.18, "end": 151.71, "ta": "கர்த்தர் இஸ்ரவேலுக்காகச் சொன்ன வார்த்தையின்படியே, தாவீதை ராஜாவாக்கும்படி அவன் வசமாயிருந்து ராஜ்யபாரம்பண்ணுகிற அவனிடத்திலும், சகல இஸ்ரவேலரிடத்திலும், வீரதத்துவத்தைப் பாராட்டின பிரதான பராக்கிரமசாலிகளும்,", "en": "These also are the chief of the mighty men whom David had, who strengthened themselves with him in his kingdom, and with all Israel, to make him king, according to the word of the LORD concerning Israel."}, {"verse": 11, "start": 151.71, "end": 170.59, "ta": "தாவீதுக்கு இருந்த அந்தப் பராக்கிரமசாலிகளின் இலக்கமுமாவது: அக்மோனியின் குமாரனாகிய யாஷோபியாம் என்னும் சேர்வைக்காரரின் தலைவன்; இவன் முந்நூறுபேர்களின்மேல் தன் ஈட்டியை ஓங்கி அவர்களை ஒருமிக்கக்கொன்றுபோட்டான்.", "en": "And this is the number of the mighty men whom David had; Jashobeam, an Hachmonite, the chief of the captains: he lifted up his spear against three hundred slain by him at one time."}, {"verse": 12, "start": 170.59, "end": 180.69, "ta": "இவனுக்கு இரண்டாவது அகோயின் குமாரனாகிய தோதோவின் மகன் எலெயாசார்; இவன் மூன்று பராக்கிரமசாலிகளில் ஒருவன்.", "en": "And after him was Eleazar the son of Dodo, the Ahohite, who was one of the three mighties."}, {"verse": 13, "start": 180.69, "end": 195.13, "ta": "பெலிஸ்தர் பாஸ்தம்மீமிலிருக்கிற வாற்கோதுமை நிறைந்த வயல்நிலத்தில் யுத்தத்திற்குக் கூடிவந்தபோது ஜனம் பெலிஸ்தரைக் கண்டு ஓடினபோதும் இவன் தாவீதோடே அங்கே இருந்தான்.", "en": "He was with David at Pas-dammim, and there the Philistines were gathered together to battle, where was a parcel of ground full of barley; and the people fled from before the Philistines."}, {"verse": 14, "start": 195.13, "end": 208.96, "ta": "அப்பொழுது அவர்கள் அந்த நிலத்தின் நடுவிலே நின்று அதைக் காப்பாற்றிப் பெலிஸ்தரை மடங்கடித்தார்கள். அதினாலே கர்த்தர் பெரிய ரட்சிப்பை நடப்பித்தார்.", "en": "And they set themselves in the midst of that parcel, and delivered it, and slew the Philistines; and the LORD saved them by a great deliverance."}, {"verse": 15, "start": 208.96, "end": 223.58, "ta": "முப்பது தலைவரில் மூன்றுபேர் அதுல்லாம் என்னும் கன்மலைக் கெபியிலிருக்கிற தாவீதினிடத்தில் போயிருந்தார்கள்; பெலிஸ்தரின் பாளயம் ரெப்பா பள்ளத்தாக்கில் இறங்குகிறபோது,", "en": "Now three of the thirty captains went down to the rock to David, into the cave of Adullam; and the host of the Philistines encamped in the valley of Rephaim."}, {"verse": 16, "start": 223.58, "end": 232.37, "ta": "தாவீது அரணான ஒரு இடத்திலிருந்தான்; அப்பொழுது பெலிஸ்தரின் தாணையம் பெத்லகேமில் இருந்தது.", "en": "And David was then in the hold, and the Philistines’ garrison was then at Beth-lehem."}, {"verse": 17, "start": 232.37, "end": 245.33, "ta": "தாவீது பெத்லகேமின் ஒலிமுகவாசலிலிருக்கிற கிணற்றின் தண்ணீர்மேல் ஆவல்கொண்டு, என் தாகத்திற்குக் கொஞ்சம் தண்ணீர் கொண்டுவருகிறவன் யார் என்றான்.", "en": "And David longed, and said, Oh that one would give me drink of the water of the well of Beth-lehem, that is at the gate!"}, {"verse": 18, "start": 245.33, "end": 267.35, "ta": "அப்பொழுது அந்த மூன்றுபேர் பெலிஸ்தரின் பாளயத்திற்குள் துணிந்து புகுந்துபோய், பெத்லகேமின் ஒலிமுகவாசலிலிருக்கிற கிணற்றிலே தண்ணீர் மொண்டு தாவீதினிடத்தில் கொண்டுவந்தார்கள்; ஆனாலும் அவன் அதைக் குடிக்க மனதில்லாமல் அதைக் கர்த்தருக்கென்று ஊற்றிப்போட்டு:", "en": "And the three brake through the host of the Philistines, and drew water out of the well of Beth-lehem, that was by the gate, and took it , and brought it to David: but David would not drink of it, but poured it out to the LORD ,"}, {"verse": 19, "start": 267.35, "end": 290.84, "ta": "நான் இதைச் செய்யாதபடிக்கு, என் தேவன் என்னைக் காத்துக்கொள்ளக்கடவர்; தங்கள் பிராணனை எண்ணாமல் போய் அதைக் கொண்டுவந்த இந்த மனுஷரின் ரத்தத்தைக் குடிப்பேனோ என்று சொல்லி அதைக் குடிக்கமாட்டேன் என்றான். இப்படி இந்த மூன்று பராக்கிரமசாலிகளும் செய்தார்கள்.", "en": "And said, My God forbid it me, that I should do this thing: shall I drink the blood of these men that have put their lives in jeopardy? for with the jeopardy of their lives they brought it. Therefore he would not drink it. These things did these three mightiest."}, {"verse": 20, "start": 290.84, "end": 305.37, "ta": "யோவாபின் சகோதரனாகிய அபிசாய் அந்த மூன்றுபேரில் பிரதானமானவன்; அவன் தன் ஈட்டியை ஓங்கி, முந்நூறுபேரை மடங்கடித்ததினால் இந்த மூன்றுபேரில் பேர்பெற்றவனானான்.", "en": "And Abishai the brother of Joab, he was chief of the three: for lifting up his spear against three hundred, he slew them , and had a name among the three."}, {"verse": 21, "start": 305.37, "end": 319.29, "ta": "இந்த மூன்றுபேரில் அவன் மற்ற இரண்டுபேரிலும் மேன்மையுள்ளவனானதினால், அவர்களில் தலைவனானான்; ஆனாலும் அந்த முந்தின மூன்றுபேருக்கு அவன் சமானமானவனல்ல.", "en": "Of the three, he was more honourable than the two; for he was their captain: howbeit he attained not to the first three."}, {"verse": 22, "start": 319.29, "end": 343.3, "ta": "பராக்கிரமசாலியாகிய யோய்தாவின் குமாரனும், கப்சேயேல் ஊரானுமாகிய பெனாயாவும் செய்கைகளில் வல்லவனாயிருந்தான்; அவன் மோவாப் தேசத்தின் இரண்டு வலுமையான சிங்கங்களைக் கொன்றதுமல்லாமல் உறைந்த மழைபெய்த நாளில் அவன் ஒரு கெபிக்குள்ளே இறங்கிப்போய், ஒரு சிங்கத்தைக் கொன்றான்.", "en": "Benaiah the son of Jehoiada, the son of a valiant man of Kabzeel, who had done many acts; he slew two lionlike men of Moab: also he went down and slew a lion in a pit in a snowy day."}, {"verse": 23, "start": 343.3, "end": 369.06, "ta": "ஐந்துமுழ உயரமான ஒரு எகிப்தியனையும் அவன் கொன்றுபோட்டான்; அந்த எகிப்தியன் கையில் நெய்கிறவர்களின் படைமரக் கனதியான ஒரு ஈட்டி, இருக்கையில், இவன் ஒரு தடியைப் பிடித்து, அவனிடத்தில் போய், அந்த எகிப்தியன் கையிலிருந்த ஈட்டியைப் பறித்து, அவன் ஈட்டியினாலே அவனைக் கொன்றுபோட்டான்.", "en": "And he slew an Egyptian, a man of great stature, five cubits high; and in the Egyptian’s hand was a spear like a weaver’s beam; and he went down to him with a staff, and plucked the spear out of the Egyptian’s hand, and slew him with his own spear."}, {"verse": 24, "start": 369.06, "end": 379.41, "ta": "இவைகளை யோய்தாவின் குமாரனான பெனாயா செய்தபடியினால், மூன்று பராக்கிரமசாலிகளுக்குள்ளே பேர்பெற்றவனாய் இருந்தான்.", "en": "These things did Benaiah the son of Jehoiada, and had the name among the three mighties."}, {"verse": 25, "start": 379.41, "end": 394.12, "ta": "முப்பதுபேரிலும் இவன் மேன்மையுள்ளவன்; ஆனாலும் அந்த முந்தின மூன்றுபேருக்கும் இவன் சமானமானவனல்ல; அவனைத் தாவீது தன் மெய்க்காவலருக்குத் தலைவனாக வைத்தான்.", "en": "Behold, he was honourable among the thirty, but attained not to the first three: and David set him over his guard."}, {"verse": 26, "start": 394.12, "end": 404.56, "ta": "இராணுவத்திலிருந்த மற்றப் பராக்கிரமசாலிகள்: யோவாபின் தம்பி ஆசகேல், பெத்லகேம் ஊரானாகிய தோதோவின் குமாரன் எல்க்கானான்,", "en": "Also the valiant men of the armies were , Asahel the brother of Joab, Elhanan the son of Dodo of Beth-lehem,"}, {"verse": 27, "start": 404.56, "end": 408.56, "ta": "ஆரோதியனாகிய சம்மோத், பெலோனியனாகிய ஏலெஸ்,", "en": "Shammoth the Harorite, Helez the Pelonite,"}, {"verse": 28, "start": 408.56, "end": 414.48, "ta": "தெக்கோவியனாகிய இக்கேசின் குமாரன் ஈரா, ஆனதோத்தியனாகிய அபியேசர்,", "en": "Ira the son of Ikkesh the Tekoite, Abi-ezer the Antothite,"}, {"verse": 29, "start": 414.48, "end": 418.83, "ta": "ஊசாத்தியனாகிய சிபெக்காய், அகோகியனாகிய ஈலாய்,", "en": "Sibbecai the Hushathite, Ilai the Ahohite,"}, {"verse": 30, "start": 418.83, "end": 425.35, "ta": "நெத்தோபாத்தியனாகிய மகராயி, நெத்தோபாத்தியனாகிய பானாவின் குமாரன் ஏலேத்,", "en": "Maharai the Netophathite, Heled the son of Baanah the Netophathite,"}, {"verse": 31, "start": 425.35, "end": 433.44, "ta": "பென்யமீன் புத்திரரின் கிபேயா ஊரானாகிய ரிபாயின் குமாரன் இத்தாயி, பிரத்தோனியனாகிய பெனாயா,", "en": "Ithai the son of Ribai of Gibeah, that pertained to the children of Benjamin, Benaiah the Pirathonite,"}, {"verse": 32, "start": 433.44, "end": 439.19, "ta": "காகாஸ் நீரோடைத் தேசத்தானாகிய ஊராயி, அர்பாத்தியனாகிய அபியேல்,", "en": "Hurai of the brooks of Gaash, Abiel the Arbathite,"}, {"verse": 33, "start": 439.19, "end": 443.8, "ta": "பகரூமியனாகிய அஸ்மாவேத், சால்போனியனாகிய எலியாபா,", "en": "Azmaveth the Baharumite, Eliahba the Shaalbonite,"}, {"verse": 34, "start": 443.8, "end": 450.5, "ta": "கீசோனியனாகிய ஆசேமின் குமாரர் ஆராரியனாகிய சாகியின் குமாரன் யோனத்தான்.", "en": "The sons of Hashem the Gizonite, Jonathan the son of Shage the Hararite,"}, {"verse": 35, "start": 450.5, "end": 456.41, "ta": "ஆராரியனாகிய சாக்காரின் குமாரன் அகியாம், ஊரின் குமாரன் எலிபால்,", "en": "Ahiam the son of Sacar the Hararite, Eliphal the son of Ur,"}, {"verse": 36, "start": 456.41, "end": 460.76, "ta": "மெகராத்தியனாகிய ஏப்பேர், பெலோனியனாகிய அகியா,", "en": "Hepher the Mecherathite, Ahijah the Pelonite,"}, {"verse": 37, "start": 460.76, "end": 465.29, "ta": "கர்மேலியனாகிய எஸ்ரோ, எஸ்பாயின் குமாரன் நாராயி,", "en": "Hezro the Carmelite, Naarai the son of Ezbai,"}, {"verse": 38, "start": 465.29, "end": 470.42, "ta": "நாத்தானின் சகோதரன் யோவேல், அகரியின் குமாரன் மிப்கார்,", "en": "Joel the brother of Nathan, Mibhar the son of Haggeri,"}, {"verse": 39, "start": 470.42, "end": 478.51, "ta": "அம்மோனியனாகிய சேலேக், செருயாவின் குமாரனாகிய யோவாபின் ஆயுததாரியான பெரோத்தியனாகிய நாராயி,", "en": "Zelek the Ammonite, Naharai the Berothite, the armourbearer of Joab the son of Zeruiah,"}, {"verse": 40, "start": 478.51, "end": 482.34, "ta": "இத்தரியனாகிய ஈரா, இத்தரியனாகிய காரெப்,", "en": "Ira the Ithrite, Gareb the Ithrite,"}, {"verse": 41, "start": 482.34, "end": 486.69, "ta": "ஏத்தியனாகிய உரியா, அக்லாயின் குமாரன் சாபாத்,", "en": "Uriah the Hittite, Zabad the son of Ahlai,"}, {"verse": 42, "start": 486.69, "end": 496.18, "ta": "ரூபனியரின் தலைவனாகிய சீசாவின் குமாரன் அதினா என்னும் ரூபனியன்; அவனோடே முப்பதுபேர் இருந்தார்கள்.", "en": "Adina the son of Shiza the Reubenite, a captain of the Reubenites, and thirty with him,"}, {"verse": 43, "start": 496.18, "end": 500.61, "ta": "மாகாவின் குமாரன் ஆனான், மிதினியனாகிய யோசபாத்,", "en": "Hanan the son of Maachah, and Joshaphat the Mithnite,"}, {"verse": 44, "start": 500.61, "end": 508.01, "ta": "அஸ்தரேத்தியனாகிய உசியா, ஆரோவேரியனாகிய ஓத்தாமின் குமாரர் சமாவும், யேகியேலும்,", "en": "Uzzia the Ashterathite, Shama and Jehiel the sons of Hothan the Aroerite,"}, {"verse": 45, "start": 508.01, "end": 513.84, "ta": "சிம்ரியின் குமாரன் எதியாயேல், தித்சியனாகிய அவன் சகோதரன் யோகா,", "en": "Jediael the son of Shimri, and Joha his brother, the Tizite,"}, {"verse": 46, "start": 513.84, "end": 523.06, "ta": "மாகாவியரின் புத்திரன் எலியேல், எல்நாமின் குமாரர் எரிபாயும், யொசவியாவும், மோவாபியனான இத்மாவும்,", "en": "Eliel the Mahavite, and Jeribai, and Joshaviah, the sons of Elnaam, and Ithmah the Moabite,"}, {"verse": 47, "start": 523.06, "end": 528.63, "ta": "மெசோபாயா ஊராராகிய எலியேலும், ஓபேதும், யாசியேலுமே.", "en": "Eliel, and Obed, and Jasiel the Mesobaite."}]}, "12": {"chapter": 12, "duration": 496.25, "audio_url": "audio_ot/OT13_12.mp3", "total_verses": 40, "verses": [{"verse": 1, "start": 3.8, "end": 12.73, "ta": "தாவீது கீசின் குமாரனாகிய சவுலினிமித்தம் இன்னும் மறைவாயிருக்கையில், சிக்லாகிலிருக்கிற அவனிடத்திற்கு வந்து,", "en": "Now these are they that came to David to Ziklag, while he yet kept himself close because of Saul the son of Kish: and they were among the mighty men, helpers of the war."}, {"verse": 2, "start": 12.73, "end": 28.73, "ta": "யுத்தத்திற்கு ஒத்தாசை செய்த வில்வீரரும், கவண்கல் எறிகிறதற்கும் வில்லினால் அம்பு எய்கிறதற்கும் வலது இடது கைவாட்டமான பராக்கிரமசாலிகளான மற்ற மனுஷருமாவன: சவுலின் சகோதரராகிய பென்யமீன் கோத்திரத்தில்,", "en": "They were armed with bows, and could use both the right hand and the left in hurling stones and shooting arrows out of a bow, even of Saul’s brethren of Benjamin."}, {"verse": 3, "start": 28.73, "end": 42.89, "ta": "கிபேயா ஊரானாகிய சேமாவின் குமாரர் அகியேசர் என்னும் தலைவனும், யோவாசும், அஸ்மாவேத்தின் குமாரராகிய எசியேலும், பேலேத்தும், பெராக்கா, ஆனதோத்தியனான ஏகூ என்பவர்களும்,", "en": "The chief was Ahiezer, then Joash, the sons of Shemaah the Gibeathite; and Jeziel, and Pelet, the sons of Azmaveth; and Berachah, and Jehu the Antothite,"}, {"verse": 4, "start": 42.89, "end": 55.2, "ta": "முப்பதுபேரில் பராக்கிரமனும் முப்பதுபேருக்குப் பெரியவனுமான இஸ்மாயா என்னும் கிபியோனியனும், எரேமியா, யகாசியேல், யோகனான், கெதேரூரானான யோசபாத்,", "en": "And Ismaiah the Gibeonite, a mighty man among the thirty, and over the thirty; and Jeremiah, and Jahaziel, and Johanan, and Josabad the Gederathite,"}, {"verse": 5, "start": 55.2, "end": 61.07, "ta": "எலுசாயி, எரிமோத், பிகலியா, அரியா, அருப்பியனான செப்பத்தியா,", "en": "Eluzai, and Jerimoth, and Bealiah, and Shemariah, and Shephatiah the Haruphite,"}, {"verse": 6, "start": 61.07, "end": 67.82, "ta": "எல்க்கானா, எஷியா, அசாரியேல், யொவேசேர், யசொபெயாம் என்னும் கோரேகியரும்,", "en": "Elkanah, and Jesiah, and Azareel, and Joezer, and Jashobeam, the Korhites,"}, {"verse": 7, "start": 67.82, "end": 73.45, "ta": "யொவேலா, செபதியா என்னும் கேதோர் ஊரானான ஏரோகாமின் குமாரருமே.", "en": "And Joelah, and Zebadiah, the sons of Jeroham of Gedor."}, {"verse": 8, "start": 73.45, "end": 94.28, "ta": "காத்தியரில் பரிசையும் ஈட்டியும் பிடித்து, சிங்கமுகம் போன்ற முகமும், மலைகளிலிருக்கிற வெளிமான் வேகம்போன்ற வேகமுமுள்ளவர்களாயிருந்து, யுத்தசேவகரான பராக்கிரமசாலிகள் சிலரும் வனாந்தரத்திலுள்ள அரணான இடத்தில் இருக்கிற தாவீது பட்சமாய்ச் சேர்ந்தார்கள்.", "en": "And of the Gadites there separated themselves unto David into the hold to the wilderness men of might, and men of war fit for the battle, that could handle shield and buckler, whose faces were like the faces of lions, and were as swift as the roes upon the mountains;"}, {"verse": 9, "start": 94.28, "end": 102.01, "ta": "யாரென்றால், எத்சேர் என்னும் தலைவன், அவனுக்கு இரண்டாவது ஒபதியா; மூன்றாவது எலியாப்,", "en": "Ezer the first, Obadiah the second, Eliab the third,"}, {"verse": 10, "start": 102.01, "end": 105.38, "ta": "நாலாவது மிஸ்மன்னா, ஐந்தாவது எரேமியா,", "en": "Mishmannah the fourth, Jeremiah the fifth,"}, {"verse": 11, "start": 105.38, "end": 108.36, "ta": "ஆறாவது அத்தாயி, ஏழாவது எலியேல்,", "en": "Attai the sixth, Eliel the seventh,"}, {"verse": 12, "start": 108.36, "end": 111.82, "ta": "எட்டாவது யோகனான், ஒன்பதாவது எல்சபாத்,", "en": "Johanan the eighth, Elzabad the ninth,"}, {"verse": 13, "start": 111.82, "end": 115.68, "ta": "பத்தாவது எரேமியா, பதினோரவது மக்பன்னாயி;", "en": "Jeremiah the tenth, Machbanai the eleventh."}, {"verse": 14, "start": 115.68, "end": 128.15, "ta": "காத் புத்திரரான இவர்கள் இராணுவத்தலைவராயிருந்தார்கள்; அவர்களில் சிறியவன் நூறுபேருக்கும் பெரியவன் ஆயிரம்பேருக்கும் சேர்வைக்காரராயிருந்தார்கள்.", "en": "These were of the sons of Gad, captains of the host: one of the least was over an hundred, and the greatest over a thousand."}, {"verse": 15, "start": 128.15, "end": 141.18, "ta": "யோர்தான் கரைபுரண்டுபோயிருக்கிற முதலாம் மாதத்தில் அதைக் கடந்து, கிழக்கேயும் மேற்கேயும் பள்ளத்தாக்குகளில் இருக்கிற யாவரையும் துரத்திவிட்டவர்கள் இவர்களே.", "en": "These are they that went over Jordan in the first month, when it had overflown all his banks; and they put to flight all them of the valleys, both toward the east, and toward the west."}, {"verse": 16, "start": 141.18, "end": 150.75, "ta": "பின்னும் பென்யமீன் புத்திரரிலும் யூதாபுத்திரரிலும் சிலர் அரணான ஸ்தலத்தில் இருக்கிற தாவீதினிடத்தில் வந்தார்கள்.", "en": "And there came of the children of Benjamin and Judah to the hold unto David."}, {"verse": 17, "start": 150.75, "end": 180.59, "ta": "தாவீது புறப்பட்டு, அவர்களுக்கு எதிர்கொண்டுபோய், அவர்களுக்கு உத்தரவுகொடுத்து: நீங்கள் எனக்கு உதவிசெய்ய சமாதானமாய் என்னிடத்தில் வந்தீர்களானால், என் இருதயம் உங்களோடு இசைந்திருக்கும்; என் கைகளில் கொடுமை இல்லாதிருக்க, என்னை என் சத்துருக்களுக்குக் காட்டிக்கொடுக்க வந்தீர்களேயாகில், நம்முடைய பிதாக்களின் தேவன் அதைப் பார்த்துக் கண்டிப்பாராக என்றான்.", "en": "And David went out to meet them, and answered and said unto them, If ye be come peaceably unto me to help me, mine heart shall be knit unto you: but if ye be come to betray me to mine enemies, seeing there is no wrong in mine hands, the God of our fathers look thereon , and rebuke it ."}, {"verse": 18, "start": 180.59, "end": 212.44, "ta": "அப்பொழுது அதிபதிகளுக்குத் தலைவனான அமாசாயின்மேல் ஆவி இறங்கினதினால், அவன்: தாவீதே, நாங்கள் உம்முடையவர்கள்; ஈசாயின் குமாரனே உமது பட்சமாயிருப்போம்; உமக்குச் சமாதானம், சமாதானம்; உமக்கு உதவிசெய்கிறவர்களுக்கும் சமாதானம்; உம்முடைய தேவன் உமக்குத் துணை நிற்கிறார் என்றான்; அப்பொழுது தாவீது அவர்களைச் சேர்த்துக்கொண்டு, அவர்களைத் தண்டுக்குத் தலைவராக்கினான்.", "en": "Then the spirit came upon Amasai, who was chief of the captains, and he said , Thine are we , David, and on thy side, thou son of Jesse: peace, peace be unto thee, and peace be to thine helpers; for thy God helpeth thee. Then David received them, and made them captains of the band."}, {"verse": 19, "start": 212.44, "end": 238.42, "ta": "சவுலின்மேல் யுத்தம்பண்ணப்போகிற பெலிஸ்தருடனேகூடத் தாவீது வருகிறபோது, மனாசேயிலும் சிலர் அவன் பட்சமாய்ச் சேர்ந்தார்கள்; பெலிஸ்தரின் பிரபுக்கள் யோசனைபண்ணி, அவன் நம்முடைய தலைகளுக்கு மோசமாய்த் தன் ஆண்டவனாகிய சவுலின் பட்சமாய்ப் போவான் என்று அவனை அனுப்பிவிட்டார்கள்: அதனால் அவர்கள் இவர்களுக்கு உதவிசெய்யவில்லை.", "en": "And there fell some of Manasseh to David, when he came with the Philistines against Saul to battle: but they helped them not: for the lords of the Philistines upon advisement sent him away, saying, He will fall to his master Saul to the jeopardy of our heads."}, {"verse": 20, "start": 238.42, "end": 257.32, "ta": "அப்படியே அவன் சிக்லாகுக்குத் திரும்பிப்போகையில், மனாசேயில் அத்னாக், யோசபாத், எதியாவேல், மிகாயேல், யோசபாத், எலிகூ, சில்த்தாயி என்னும் மனாசே கோத்திரத்தாரின் ஆயிரத்துச் சேர்வைக்காரர் அவன் பட்சமாய் வந்தார்கள்.", "en": "As he went to Ziklag, there fell to him of Manasseh, Adnah, and Jozabad, and Jediael, and Michael, and Jozabad, and Elihu, and Zilthai, captains of the thousands that were of Manasseh."}, {"verse": 21, "start": 257.32, "end": 269.78, "ta": "அந்தத் தண்டுக்கு விரோதமாய் இவர்கள் தாவீதுக்கு உதவிசெய்தார்கள்; இவர்களெல்லாரும் பராக்கிரமசாலிகளும் இராணுவத்தில் சேர்வைக்காரருமாயிருந்தார்கள்.", "en": "And they helped David against the band of the rovers: for they were all mighty men of valour, and were captains in the host."}, {"verse": 22, "start": 269.78, "end": 281.37, "ta": "அக்காலத்திலே நாளுக்குநாள் தாவீதுக்கு உதவிசெய்யும் மனுஷர் அவனிடத்தில் வந்து சேர்ந்தபடியால், அவர்கள் தேவசேனையைப்போல மகா சேனையானார்கள்.", "en": "For at that time day by day there came to David to help him, until it was a great host, like the host of God."}, {"verse": 23, "start": 281.37, "end": 293.67, "ta": "கர்த்தருடைய வாக்கின்படியே, சவுலின் ராஜ்யபாரத்தைத் தாவீதினிடமாய்த் திருப்ப, எப்ரோனிலிருக்கிற அவனிடத்துக்கு வந்த யுத்த சன்னத்தரான தலைவரின் இலக்கமாவன:", "en": "And these are the numbers of the bands that were ready armed to the war, and came to David to Hebron, to turn the kingdom of Saul to him, according to the word of the LORD ."}, {"verse": 24, "start": 293.67, "end": 301.96, "ta": "யூதாபுத்திரரில் பரிசையும் ஈட்டியும் பிடித்து, யுத்தசன்னத்தரானவர்கள் ஆறாயிரத்து எண்ணூறுபேர்.", "en": "The children of Judah that bare shield and spear were six thousand and eight hundred, ready armed to the war."}, {"verse": 25, "start": 301.96, "end": 308.47, "ta": "சிமியோன் புத்திரரில் பராக்கிரமசாலிகளாகிய யுத்தவீரர் ஏழாயிரத்து நூறுபேர்.", "en": "Of the children of Simeon, mighty men of valour for the war, seven thousand and one hundred."}, {"verse": 26, "start": 308.47, "end": 312.49, "ta": "லேவி புத்திரரில் நாலாயிரத்து அறுநூறுபேர்.", "en": "Of the children of Levi four thousand and six hundred."}, {"verse": 27, "start": 312.49, "end": 319.97, "ta": "ஆரோன் சந்ததியாரின் அதிபதியாகிய யோயதாவும், அவனோடிருந்த மூவாயிரத்து; எழுநூறுபேரும்,", "en": "And Jehoiada was the leader of the Aaronites, and with him were three thousand and seven hundred;"}, {"verse": 28, "start": 319.97, "end": 328.26, "ta": "பராக்கிரமசாலியான சாதோக் என்னும் வாலிபனும், அவன் தகப்பன் வம்சத்தாரான இருபத்திரண்டு தலைவருமே.", "en": "And Zadok, a young man mighty of valour, and of his father’s house twenty and two captains."}, {"verse": 29, "start": 328.26, "end": 340.72, "ta": "பென்யமீன் புத்திரரான சவுலின் சகோதரரில் மூவாயிரம்பேர்; அதுவரைக்கும் அவர்களில் மிச்சமானவர்கள் சவுலின் குடும்பத்தைக் காப்பாற்றப் பார்த்தார்கள்.", "en": "And of the children of Benjamin, the kindred of Saul, three thousand: for hitherto the greatest part of them had kept the ward of the house of Saul."}, {"verse": 30, "start": 340.72, "end": 350.94, "ta": "எப்பிராயீம் புத்திரரில் தங்கள் பிதாக்களின் வம்சத்தில் பேர் பெற்ற மனுஷரான பராக்கிரமசாலிகள் இருபதினாயிரத்து எண்ணூறுபேர்.", "en": "And of the children of Ephraim twenty thousand and eight hundred, mighty men of valour, famous throughout the house of their fathers."}, {"verse": 31, "start": 350.94, "end": 361.32, "ta": "மனாசேயின் பாதிக்கோத்திரத்தில் தாவீதை ராஜாவாக்குகிறதற்கு வரும்படி, பேர்பேராகக் குறிக்கப்பட்டவர்கள் பதினெண்ணாயிரம்பேர்.", "en": "And of the half tribe of Manasseh eighteen thousand, which were expressed by name, to come and make David king."}, {"verse": 32, "start": 361.32, "end": 378.37, "ta": "இசக்கார் புத்திரரில், இஸ்ரவேலர் செய்யவேண்டியது இன்னதென்று அறிந்து காலாகாலங்களுக்குத் தகுந்த யோசனை சொல்லத்தக்க தலைவர்கள் இருநூறுபேரும், இவர்கள் வாக்குக்குச் செவிகொடுத்த இவர்களுடைய எல்லாச் சகோதரருமே.", "en": "And of the children of Issachar, which were men that had understanding of the times, to know what Israel ought to do; the heads of them were two hundred; and all their brethren were at their commandment."}, {"verse": 33, "start": 378.37, "end": 394.05, "ta": "செபுலோன் புத்திரரில் சகலவித யுத்த ஆயுதங்களாலும் யுத்தம் செய்கிறதற்கும், தங்கள் அணியைக் காத்துநிற்கிறதற்கும் பழகி, வஞ்சனைசெய்யாமல் யுத்தத்திற்குப் போகத்தக்கவர்கள் ஐம்பதினாயிரம்பேர்.", "en": "Of Zebulun, such as went forth to battle, expert in war, with all instruments of war, fifty thousand, which could keep rank: they were not of double heart."}, {"verse": 34, "start": 394.05, "end": 403.7, "ta": "நப்தலி புத்திரரில் ஆயிரம் தலைவர்கள் பரிசையும் ஈட்டியும் பிடித்த அவர்களோடேகூட இருந்தவர்கள் முப்பத்தேழாயிரம்பேர்.", "en": "And of Naphtali a thousand captains, and with them with shield and spear thirty and seven thousand."}, {"verse": 35, "start": 403.7, "end": 410.78, "ta": "தாண் புத்திரரில் யுத்தத்திற்குத் தேறினவர்கள் இருபத்து எண்ணாயிரத்து அறுநூறுபேர்.", "en": "And of the Danites expert in war twenty and eight thousand and six hundred."}, {"verse": 36, "start": 410.78, "end": 419.14, "ta": "ஆசேர் புத்திரரில் யுத்தத்திற்குத் தேறினவர்களாய் சேவகம்பண்ணப்போகத்தக்கவர்கள் நாற்பதினாயிரம்பேர்.", "en": "And of Asher, such as went forth to battle, expert in war, forty thousand."}, {"verse": 37, "start": 419.14, "end": 433.14, "ta": "யோர்தானுக்கு அக்கரையான ரூபனியரிலும், காத்தியரிலும், மனாசேயின் பாதிக்கோத்திரத்தாரிலும், யுத்தம்பண்ண சகலவித ஆயுதங்களையும் தரித்தவர்கள் நூற்றிருபதினாயிரம்பேர்.", "en": "And on the other side of Jordan, of the Reubenites, and the Gadites, and of the half tribe of Manasseh, with all manner of instruments of war for the battle, an hundred and twenty thousand."}, {"verse": 38, "start": 433.14, "end": 452.28, "ta": "தாவீதை இஸ்ரவேலின்மேல் ராஜாவாக்குகிறதற்கு, இந்த யுத்தமனுஷர் எல்லாரும் அணி அணியாய் வைக்கப்பட்டவர்களாக, உத்தம இருதயத்தோடே எப்ரோனுக்கு வந்தார்கள்; இஸ்ரவேலில் மற்ற யாவரும் தாவீதை ராஜாவாக்குகிறதற்கு ஒருமனப்பட்டிருந்தார்கள்.", "en": "All these men of war, that could keep rank, came with a perfect heart to Hebron, to make David king over all Israel: and all the rest also of Israel were of one heart to make David king."}, {"verse": 39, "start": 452.28, "end": 464.83, "ta": "அவர்கள் அங்கே தாவீதோடேகூட மூன்றுநாள் இருந்து, போஜனபானம்பண்ணினார்கள்; அவர்கள் சகோதரர் அவர்களுக்காகச் சகலத்தையும் ஆயத்தம்பண்ணியிருந்தார்கள்.", "en": "And there they were with David three days, eating and drinking: for their brethren had prepared for them."}, {"verse": 40, "start": 464.83, "end": 494.75, "ta": "இசக்கார், செபுலோன், நப்தலியின் எல்லைமட்டும் அவர்களுக்குச் சமீபமாயிருந்தவர்களும், கழுதைகள்மேலும் ஒட்டகங்கள்மேலும் கோவேறு கழுதைகள்மேலும் மாடுகள்மேலும், தின்பண்டங்களாகிய மா, அத்திப்பழ அடைகள், வற்றலான திராட்சப்பழங்கள், திராட்சரசம், எண்ணெய் ஆடுமாடுகள் ஆகிய இவைகளை வேண்டிய மட்டும் ஏற்றிக்கொண்டுவந்தார்கள்; இஸ்ரவேலிலே மகிழ்ச்சியுண்டாயிற்று.", "en": "Moreover they that were nigh them, even unto Issachar and Zebulun and Naphtali, brought bread on asses, and on camels, and on mules, and on oxen, and meat, meal, cakes of figs, and bunches of raisins, and wine, and oil, and oxen, and sheep abundantly: for there was joy in Israel."}]}, "13": {"chapter": 13, "duration": 182.54, "audio_url": "audio_ot/OT13_13.mp3", "total_verses": 14, "verses": [{"verse": 1, "start": 3.8, "end": 11.3, "ta": "தாவீது ஆயிரம்பேருக்குத் தலைவரோடும் நூறுபேருக்குத் தலைவரோடும் சகல அதிபதிகளோடும் ஆலோசனைபண்ணி,", "en": "And David consulted with the captains of thousands and hundreds, and with every leader."}, {"verse": 2, "start": 11.3, "end": 35.97, "ta": "இஸ்ரவேல் சபையையெல்லாம் நோக்கி: உங்களுக்குச் சம்மதியும் நம்முடைய தேவனாகிய கர்த்தருக்குச் சித்தமுமாயிருந்தால், இஸ்ரவேலின் தேசங்களிலெல்லாம் இருக்கிற நம்முடைய மற்றச் சகோதரரும், அவர்களோடே தங்கள் வெளிநிலங்களில் இருக்கிற ஆசாரியரும் லேவியரும் நம்மோடே கூடும்படிக்கு நாம் சீக்கிரமாய் அவர்களிடத்துக்கு ஆளனுப்பி,", "en": "And David said unto all the congregation of Israel, If it seem good unto you, and that it be of the LORD our God, let us send abroad unto our brethren every where, that are left in all the land of Israel, and with them also to the priests and Levites which are in their cities and suburbs, that they may gather themselves unto us:"}, {"verse": 3, "start": 35.97, "end": 46.03, "ta": "நமது தேவனுடைய பெட்டியைத் திரும்ப நம்மிடத்துக்குக் கொண்டுவருவோமாக; சவுலின் நாட்களில் அதைத் தேடாதேபோனோம் என்றான்.", "en": "And let us bring again the ark of our God to us: for we enquired not at it in the days of Saul."}, {"verse": 4, "start": 46.03, "end": 55.93, "ta": "இந்தக் காரியம் சகல ஜனத்தின் பார்வைக்கும் செம்மையாயிருந்தபடியால், சபையார் எல்லாரும் அப்படியே செய்வோம் என்றார்கள்.", "en": "And all the congregation said that they would do so: for the thing was right in the eyes of all the people."}, {"verse": 5, "start": 55.93, "end": 68.95, "ta": "அப்படியே தேவனுடைய பெட்டியைக் கீரியாத்யாரீமிலிருந்து கொண்டுவரும்படி, தாவீது எகிப்தைச்சேர்ந்த கோர் நதிதுவக்கி ஆமாத்தின் எல்லைமட்டுமுள்ள இஸ்ரவேலையெல்லாங்கூட்டி,", "en": "So David gathered all Israel together, from Shihor of Egypt even unto the entering of Hemath, to bring the ark of God from Kirjath-jearim."}, {"verse": 6, "start": 68.95, "end": 87.79, "ta": "கேருபீன்களின் நடுவே வாசம்பண்ணுகிற கர்த்தராகிய தேவனுடைய நாமம் தொழுதுகொள்ளப்படுகிற அவருடைய பெட்டியை யூதாவிலிருக்கிற கீரியாத்யாரீமுக்கடுத்த பாலாவிலிருந்து கொண்டுவரும்படிக்கு, அவனும் இஸ்ரவேலர் அனைவரும் அவ்விடத்திற்குப்போனார்கள்.", "en": "And David went up, and all Israel, to Baalah, that is , to Kirjath-jearim, which belonged to Judah, to bring up thence the ark of God the LORD , that dwelleth between the cherubims, whose name is called on it ."}, {"verse": 7, "start": 87.79, "end": 100.0, "ta": "அவர்கள் தேவனுடைய பெட்டியை அபினதாபின் வீட்டிலிருந்து ஒரு புதுரதத்தின்மேல் ஏற்றிக்கொண்டு வந்தார்கள்; ஊசாவும் அகியோவும் ரதத்தை நடத்தினார்கள்.", "en": "And they carried the ark of God in a new cart out of the house of Abinadab: and Uzza and Ahio drave the cart."}, {"verse": 8, "start": 100.0, "end": 115.57, "ta": "தாவீதும் சகல இஸ்ரவேலரும் தங்கள் முழுப் பலத்தோடும் தேவனுக்குமுன்பாகச் சுரமண்டலங்களையும் தம்புருகளையும் மேளங்களையும் கைத்தாளங்களையும் பூரிகைகளையும் சேவித்து மகிழ்ச்சியாய் ஆடிப்பாடினார்கள்.", "en": "And David and all Israel played before God with all their might, and with singing, and with harps, and with psalteries, and with timbrels, and with cymbals, and with trumpets."}, {"verse": 9, "start": 115.57, "end": 125.15, "ta": "அவர்கள் கீதோனின் களமட்டும்வந்தபோது, மாடுகள் இடறினபடியினால், ஊசா பெட்டியைப் பிடிக்கத் தன் கையை நீட்டினான்.", "en": "And when they came unto the threshingfloor of Chidon, Uzza put forth his hand to hold the ark; for the oxen stumbled."}, {"verse": 10, "start": 125.15, "end": 138.33, "ta": "அப்பொழுது கர்த்தர் ஊசாவின்மேல் கோபம் மூண்டவராகி, அவன் தன்கையை பெட்டியண்டைக்கு நீட்டினதினிமித்தம் அவனை அடித்தார்; அங்கே அவன் தேவசமுகத்தில் செத்தான்.", "en": "And the anger of the LORD was kindled against Uzza, and he smote him, because he put his hand to the ark: and there he died before God."}, {"verse": 11, "start": 138.33, "end": 149.66, "ta": "அப்பொழுது கர்த்தர் ஊசாவை அடித்ததினிமித்தம் தாவீது விசனப்பட்டு, அந்த ஸ்தலத்திற்கு இந்நாள்மட்டும் வழங்கிவருகிற பேரேஸ்ஊசா என்னும் பேரிட்டு,", "en": "And David was displeased, because the LORD had made a breach upon Uzza: wherefore that place is called Perez-uzza to this day."}, {"verse": 12, "start": 149.66, "end": 158.21, "ta": "அன்றையதினம் தேவனுக்குப்பயந்து: தேவனுடைய பெட்டியை நான் என்னிடத்துக்குக் கொண்டுவருவது எப்படியென்று சொல்லி,", "en": "And David was afraid of God that day, saying, How shall I bring the ark of God home to me?"}, {"verse": 13, "start": 158.21, "end": 167.79, "ta": "பெட்டியைத் தன்னிடத்தில் தாவீதின் நகரத்திலே கொண்டுவராமல், அதைக் கித்தியனாகிய ஓபேத்ஏதோமின்வீட்டிலே சேர்த்தான்.", "en": "So David brought not the ark home to himself to the city of David, but carried it aside into the house of Obed-edom the Gittite."}, {"verse": 14, "start": 167.79, "end": 181.04, "ta": "தேவனுடைய பெட்டி ஓபேத்ஏதோமின் வீட்டிலே அவனிடத்தில் மூன்றுமாதம் இருக்கையில், கர்த்தர் ஓபேத்ஏதோமின் வீட்டையும் அவனுக்கு உண்டான எல்லாவற்றையும் ஆசீர்வதித்தார்.", "en": "And the ark of God remained with the family of Obed-edom in his house three months. And the LORD blessed the house of Obed-edom, and all that he had."}]}, "14": {"chapter": 14, "duration": 191.19, "audio_url": "audio_ot/OT13_14.mp3", "total_verses": 17, "verses": [{"verse": 1, "start": 3.8, "end": 17.82, "ta": "தீருவின் ராஜாவாகிய ஈராம் தாவீதினிடத்தில் ஸ்தானாபதிகளையும், அவனுக்கு ஒரு வீட்டைக் கட்டுகிறதற்குக் கேதுருமரங்களையும், தச்சரையும், கல்தச்சரையும் அனுப்பினான்.", "en": "Now Hiram king of Tyre sent messengers to David, and timber of cedars, with masons and carpenters, to build him an house."}, {"verse": 2, "start": 17.82, "end": 32.09, "ta": "கர்த்தர் தன்னை இஸ்ரவேலின்மேல் ராஜாவாகத் திடப்படுத்தி, இஸ்ரவேலென்னும் தம்முடைய ஜனத்தினிமித்தம் தன்னுடைய ராஜ்யத்தை மிகவும் உயர்த்தினார் என்று தாவீது அறிந்துகொண்டான்.", "en": "And David perceived that the LORD had confirmed him king over Israel, for his kingdom was lifted up on high, because of his people Israel."}, {"verse": 3, "start": 32.09, "end": 41.47, "ta": "எருசலேமிலே தாவீது பின்னும் அநேக ஸ்திரீகளை விவாகம்பண்ணி, பின்னும் குமாரரையும் குமாரத்திகளையும் பெற்றான்.", "en": "And David took more wives at Jerusalem: and David begat more sons and daughters."}, {"verse": 4, "start": 41.47, "end": 49.54, "ta": "எருசலேமிலே அவனுக்குப் பிறந்த குமாரரின் நாமங்களாவன: சம்முவா, சோபாப், நாத்தான், சாலொமோன்,", "en": "Now these are the names of his children which he had in Jerusalem; Shammua, and Shobab, Nathan, and Solomon,"}, {"verse": 5, "start": 49.54, "end": 52.39, "ta": "இப்கார், எலிவா, எல்பெலேத்,", "en": "And Ibhar, and Elishua, and Elpalet,"}, {"verse": 6, "start": 52.39, "end": 55.08, "ta": "நோகா, நெப்பேக், யப்பியா,", "en": "And Nogah, and Nepheg, and Japhia,"}, {"verse": 7, "start": 55.08, "end": 59.65, "ta": "எலிஷாமா, பெலியாதா, எலிப்பெலேத் என்பவைகள்.", "en": "And Elishama, and Beeliada, and Eliphalet."}, {"verse": 8, "start": 59.65, "end": 77.18, "ta": "தாவீது சமஸ்த இஸ்ரவேலின்மேலும் ராஜாவாக அபிஷேகம்பண்ணப்பட்டதைப் பெலிஸ்தர் கேள்விப்பட்டபோது, பெலிஸ்தர் எல்லாரும் தாவீதைத் தேடும்படி வந்தார்கள்; அதை தாவீது கேட்டபோது அவர்களுக்கு விரோதமாகப் புறப்பட்டான்.", "en": "And when the Philistines heard that David was anointed king over all Israel, all the Philistines went up to seek David. And David heard of it , and went out against them."}, {"verse": 9, "start": 77.18, "end": 82.8, "ta": "பெலிஸ்தர் வந்து ரெப்பாயீம் பள்ளத்தாக்கிலே பரவியிருந்தார்கள்.", "en": "And the Philistines came and spread themselves in the valley of Rephaim."}, {"verse": 10, "start": 82.8, "end": 97.4, "ta": "பெலிஸ்தருக்கு விரோதமாகப் போகலாமா, அவர்களை என் கையில் ஒப்புக்கொடுப்பீரா என்று தாவீது தேவனைக் கேட்டபோது, கர்த்தர் போ, அவர்களை உன் கையில் ஒப்புக்கொடுப்பேன் என்றார்.", "en": "And David enquired of God, saying, Shall I go up against the Philistines? and wilt thou deliver them into mine hand? And the LORD said unto him, Go up; for I will deliver them into thine hand."}, {"verse": 11, "start": 97.4, "end": 118.11, "ta": "அவர்கள் பாகால்பிராசீமுக்கு வந்தபோது, தாவீது அங்கே அவர்களை முறியடித்து தண்ணீர்கள் உடைந்தோடுகிறதுபோல, தேவன் என் கையினால் என் சத்துருக்களை உடைந்தோடப்பண்ணினாரென்றான்; அதினிமித்தம் அந்த ஸ்தலத்திற்குப் பாகால்பிராசீம் என்னும் பேரிட்டார்கள்.", "en": "So they came up to Baal-perazim; and David smote them there. Then David said, God hath broken in upon mine enemies by mine hand like the breaking forth of waters: therefore they called the name of that place Baal-perazim."}, {"verse": 12, "start": 118.11, "end": 128.38, "ta": "அங்கே அவர்கள் தங்கள் தெய்வங்களைவிட்டு ஓடிப்போனார்கள்; தாவீது கற்பித்தபடி அவைகள் அக்கினியாலே சுட்டெரிக்கப்பட்டன.", "en": "And when they had left their gods there, David gave a commandment, and they were burned with fire."}, {"verse": 13, "start": 128.38, "end": 134.25, "ta": "பெலிஸ்தர் மறுபடியும் வந்து அந்தப் பள்ளத்தாக்கிலே இறங்கினார்கள்.", "en": "And the Philistines yet again spread themselves abroad in the valley."}, {"verse": 14, "start": 134.25, "end": 150.96, "ta": "அப்பொழுது தாவீது திரும்ப தேவனிடத்தில் விசாரித்ததற்கு, தேவன் நீ அவர்களுக்குப் பின்னாலே போகாமல், அவர்களுக்குப் பக்கமாய்ச் சுற்றி, முசுக்கட்டைச் செடிகளுக்கு எதிரேயிருந்து, அவர்கள்மேல் பாய்ந்து,", "en": "Therefore David enquired again of God; and God said unto him, Go not up after them; turn away from them, and come upon them over against the mulberry trees."}, {"verse": 15, "start": 150.96, "end": 166.86, "ta": "முசுக்கட்டைச் செடிகளின் நுனிகளிலே செல்லுகிற இரைச்சலை நீ கேட்கும்போது, யுத்தத்திற்குப் புறப்படு; பெலிஸ்தரின் பாளயத்தை முறிய அடிக்க தேவன் உனக்கு முன்னே புறப்பட்டிருப்பார் என்றார்.", "en": "And it shall be, when thou shalt hear a sound of going in the tops of the mulberry trees, that then thou shalt go out to battle: for God is gone forth before thee to smite the host of the Philistines."}, {"verse": 16, "start": 166.86, "end": 177.95, "ta": "தேவன் தனக்குக் கற்பித்தபடியே தாவீது செய்தபோது, பெலிஸ்தரின் இராணுவத்தைக் கிபியோன் துவக்கிக் காசேர்மட்டும் முறிய அடித்தார்கள்.", "en": "David therefore did as God commanded him: and they smote the host of the Philistines from Gibeon even to Gazer."}, {"verse": 17, "start": 177.95, "end": 189.69, "ta": "அப்படியே தாவீதின் கீர்த்தி சகல தேசங்களிலும் பிரசித்தமாகி, அவனுக்குப் பயப்படுகிற பயத்தைக் கர்த்தர் சகல ஜாதிகளின்மேலும் வரப்பண்ணினார்.", "en": "And the fame of David went out into all lands; and the LORD brought the fear of him upon all nations."}]}, "15": {"chapter": 15, "duration": 360.77, "audio_url": "audio_ot/OT13_15.mp3", "total_verses": 29, "verses": [{"verse": 1, "start": 3.8, "end": 15.31, "ta": "அவன் தனக்குத் தாவீதின் நகரத்தில் வீடுகளை உண்டாக்கி, தேவனுடைய பெட்டிக்கு ஒரு ஸ்தலத்தை ஆயத்தப்படுத்தி, அதற்கு ஒரு கூடாரத்தைப்போட்டான்.", "en": "And David made him houses in the city of David, and prepared a place for the ark of God, and pitched for it a tent."}, {"verse": 2, "start": 15.31, "end": 31.91, "ta": "பிற்பாடு தாவீது: லேவியர் ஒழிய, வேறொருவரும் தேவனுடைய பெட்டியை எடுக்கலாகாது; தேவனுடைய பெட்டியை எடுக்கவும், என்றைக்கும் அவருக்குப் பணிவிடைசெய்யவும், அவர்களை கர்த்தர் தெரிந்துகொண்டார் என்றான்.", "en": "Then David said, None ought to carry the ark of God but the Levites: for them hath the LORD chosen to carry the ark of God, and to minister unto him for ever."}, {"verse": 3, "start": 31.91, "end": 43.98, "ta": "அப்படி கர்த்தருடைய பெட்டிக்குத் தான் ஆயத்தப்படுத்தின அதின் ஸ்தலத்திற்கு அதைக் கொண்டுவரும்படி தாவீது இஸ்ரவேலையெல்லாம் எருசலேமிலே கூடிவரச்செய்தான்.", "en": "And David gathered all Israel together to Jerusalem, to bring up the ark of the LORD unto his place, which he had prepared for it."}, {"verse": 4, "start": 43.98, "end": 45.93, "ta": "ஆரோனின் புத்திரரையும்,", "en": "And David assembled the children of Aaron, and the Levites:"}, {"verse": 5, "start": 45.93, "end": 53.14, "ta": "லேவியராகிய கோகாத் புத்திரரில் பிரபுவாகிய ஊரியேலையும் அவன் சகோதரராகிய நூற்றிருபதுபேரையும்,", "en": "Of the sons of Kohath; Uriel the chief, and his brethren an hundred and twenty:"}, {"verse": 6, "start": 53.14, "end": 60.34, "ta": "மெராரியின் புத்திரரில் பிரபுவாகிய அசாயாவையும், அவன் சகோதரராகிய இருநூற்றிருபதுபேரையும்,", "en": "Of the sons of Merari; Asaiah the chief, and his brethren two hundred and twenty:"}, {"verse": 7, "start": 60.34, "end": 67.23, "ta": "கெர்சோன் புத்திரரில் பிரபுவாகிய யோவேலையும், அவன் சகோதரராகிய நூற்றுமுப்பதுபேரையும்,", "en": "Of the sons of Gershom; Joel the chief, and his brethren an hundred and thirty:"}, {"verse": 8, "start": 67.23, "end": 74.05, "ta": "எலிசாப்பான் புத்திரரில் பிரபுவாகிய செமாயாவையும், அவன் சகோதரராகிய இருநூறுபேரையும்,", "en": "Of the sons of Elizaphan; Shemaiah the chief, and his brethren two hundred:"}, {"verse": 9, "start": 74.05, "end": 80.55, "ta": "எப்ரோன் புத்திரரில் பிரபுவாகிய, எலியேலைம், அவன் சகோதரராகிய எண்பதுபேரையும்,", "en": "Of the sons of Hebron; Eliel the chief, and his brethren fourscore:"}, {"verse": 10, "start": 80.55, "end": 90.49, "ta": "ஊசியேல் புத்திரரில் பிரபுவாகிய அம்மினதாபையும், அவன் சகோதரராகிய நூற்றுப்பன்னிரண்டுபேரையும் தாவீது கூடிவரப்பண்ணினான்.", "en": "Of the sons of Uzziel; Amminadab the chief, and his brethren an hundred and twelve."}, {"verse": 11, "start": 90.49, "end": 103.49, "ta": "பின்பு தாவீது ஆசாரியராகிய சாதோக்கையும், அபியத்தாரையும், லேவியராகிய ஊரியேல், அசாயா, யோவேல், செமாயா, எலியேல், அம்மினதாப் என்பவர்களையும் அழைத்து,", "en": "And David called for Zadok and Abiathar the priests, and for the Levites, for Uriel, Asaiah, and Joel, Shemaiah, and Eliel, and Amminadab,"}, {"verse": 12, "start": 103.49, "end": 122.76, "ta": "அவர்களை நோக்கி: லேவியரில் நீங்கள் பிதாக்களுடைய சந்ததிகளின் தலைவர், நீங்கள் இஸ்ரவேலின் தேவனாகிய கர்த்தரின் பெட்டியை அதற்கு நான் ஆயத்தம்பண்ணின ஸ்தலத்திற்குக் கொண்டுவரும்படி, உங்களையும் உங்கள் சகோதரரையும் பரிசுத்தம்பண்ணிக்கொள்ளுங்கள்.", "en": "And said unto them, Ye are the chief of the fathers of the Levites: sanctify yourselves, both ye and your brethren, that ye may bring up the ark of the LORD God of Israel unto the place that I have prepared for it."}, {"verse": 13, "start": 122.76, "end": 135.92, "ta": "முதலில் நீங்கள் அதைச் சுமக்காதபடியினாலும், நாம் நம்முடைய தேவனாகிய கர்த்தரை நியாயமானபடியே தேடாதேபோனபடியினாலும், அவர் நமக்குள்ளே அடிவிழப்பண்ணினார் என்றான்.", "en": "For because ye did it not at the first, the LORD our God made a breach upon us, for that we sought him not after the due order."}, {"verse": 14, "start": 135.92, "end": 145.86, "ta": "அப்படியே ஆசாரியரும் லேவியரும் இஸ்ரவேலின் தேவனாகிய கர்த்தரின் பெட்டியைக் கொண்டுவரத் தங்களைச் சுத்தம்பண்ணிக்கொண்டார்கள்.", "en": "So the priests and the Levites sanctified themselves to bring up the ark of the LORD God of Israel."}, {"verse": 15, "start": 145.86, "end": 158.86, "ta": "பின்பு லேவி புத்திரர் கர்த்தருடைய வார்த்தையின்படியே, மோசே கற்பித்தபிரகாரம் தேவனுடைய பெட்டியை அதின் தண்டுகளினாலே தங்கள் தோள்மேல் எடுத்துக்கொண்டுவந்தார்கள்.", "en": "And the children of the Levites bare the ark of God upon their shoulders with the staves thereon, as Moses commanded according to the word of the LORD ."}, {"verse": 16, "start": 158.86, "end": 176.33, "ta": "தாவீது லேவியரின் பிரபுக்களை நோக்கி: நீங்கள் உங்கள் சகோதரராகிய பாடகரைத் தம்புரு சுரமண்டலம் கைத்தாளம் முதலிய கீதவாத்தியங்கள் முழங்க தங்கள் சத்தத்தை உயர்த்தி, சந்தோஷமுண்டாகப் பாடும்படி நிறுத்தவேண்டுமென்று சொன்னான்.", "en": "And David spake to the chief of the Levites to appoint their brethren to be the singers with instruments of musick, psalteries and harps and cymbals, sounding, by lifting up the voice with joy."}, {"verse": 17, "start": 176.33, "end": 190.5, "ta": "அப்படியே லேவியர் யோவேலின் குமாரனாகிய ஏமானையும், அவன் சகோதரரில் பெரகியாவின் குமாரனாகிய ஆசாப்பையும், மெராரியின் புத்திரரான தங்கள் சகோதரரில் குஷாயாவின் குமாரனாகிய ஏத்தானையும்,", "en": "So the Levites appointed Heman the son of Joel; and of his brethren, Asaph the son of Berechiah; and of the sons of Merari their brethren, Ethan the son of Kushaiah;"}, {"verse": 18, "start": 190.5, "end": 212.12, "ta": "இவர்களோடுங்கூட இரண்டாவது வரிசையாகத் தங்கள் சகோதரராகிய சகரியா, பேன், யாசியேல், செமிரமோத், யெகியேல், உன்னி, எலியாப், பெனாயா, மாசெயா, மத்தித்தியா, எலிப்பெலேகு, மிக்னேயா, ஒபேத்ஏதோம், ஏயெல் என்னும் வாசல் காவலாளரையும் நிறுத்தினார்கள்.", "en": "And with them their brethren of the second degree , Zechariah, Ben, and Jaaziel, and Shemiramoth, and Jehiel, and Unni, Eliab, and Benaiah, and Maaseiah, and Mattithiah, and Elipheleh, and Mikneiah, and Obed-edom, and Jeiel, the porters."}, {"verse": 19, "start": 212.12, "end": 220.97, "ta": "பாடகராகிய ஏமானும், ஆசாப்பும், ஏத்தானும், பஞ்சலோகக் கைத்தாளங்களைத் தொனிக்கப்பண்ணிப் பாடினார்கள்.", "en": "So the singers, Heman, Asaph, and Ethan, were appointed to sound with cymbals of brass;"}, {"verse": 20, "start": 220.97, "end": 234.12, "ta": "சகரியா, ஆசியேல், செமிரமோத், யெகியேல், உன்னி, எலியாப், மாசெயா, பெனாயா என்பவர்கள் அல்மோத் என்னும் இசையில் பாடி, தம்புருகளை வாசித்தார்கள்.", "en": "And Zechariah, and Aziel, and Shemiramoth, and Jehiel, and Unni, and Eliab, and Maaseiah, and Benaiah, with psalteries on Alamoth;"}, {"verse": 21, "start": 234.12, "end": 247.52, "ta": "மத்தித்தியா, எலிப்பெலேகு, மிக்னேயா, ஓபேத்ஏதோம், ஏயெல், அசசியா என்பவர்கள் செமனீத் என்னும் இசையில் பாடி, சுரமண்டலங்களை நேர்த்தியாய் வாசித்தார்கள்.", "en": "And Mattithiah, and Elipheleh, and Mikneiah, and Obed-edom, and Jeiel, and Azaziah, with harps on the Sheminith to excel."}, {"verse": 22, "start": 247.52, "end": 257.46, "ta": "லேவியருக்குள்ளே கெனானியா என்பவன் சங்கீதத்தலைவனாயிருந்தான்; அவன் நிபுணனானபடியால், கீதவித்தையைப் படிப்பித்தான்.", "en": "And Chenaniah, chief of the Levites, was for song: he instructed about the song, because he was skilful."}, {"verse": 23, "start": 257.46, "end": 263.57, "ta": "பெரகியாவும் எல்க்கானாவும் பெட்டிக்கு முன்பாகக் காவல்காத்துவந்தார்கள்.", "en": "And Berechiah and Elkanah were doorkeepers for the ark."}, {"verse": 24, "start": 263.57, "end": 281.74, "ta": "செபனியா, யோசபாத், நெதனெயேல், அமாசாயி, சகரியா, பெனாயா, எலியேசர் என்னும் ஆசாரியர் தேவனுடைய பெட்டிக்கு முன்பாகப் பூரிகைகளை ஊதினார்கள்; ஓபேத் ஏதோமும், எகியாவும் பெட்டிக்கு வாசல் காவலாளராயிருந்தார்கள்.", "en": "And Shebaniah, and Jehoshaphat, and Nethaneel, and Amasai, and Zechariah, and Benaiah, and Eliezer, the priests, did blow with the trumpets before the ark of God: and Obed-edom and Jehiah were doorkeepers for the ark."}, {"verse": 25, "start": 281.74, "end": 295.84, "ta": "இப்படித் தாவீதும், இஸ்ரவேலின் மூப்பரும், ஆயிரத்துச் சேர்வைக்காரரும் கர்த்தருடைய உடன்படிக்கைப் பெட்டியை ஓபேத்ஏதோமின் வீட்டிலிருந்து மகிழ்ச்சியோடே கொண்டுவரப்போனார்கள்.", "en": "So David, and the elders of Israel, and the captains over thousands, went to bring up the ark of the covenant of the LORD out of the house of Obed-edom with joy."}, {"verse": 26, "start": 295.84, "end": 308.68, "ta": "கர்த்தருடைய உடன்படிக்கைப்பெட்டியைச் சுமக்கிற லேவியருக்கு தேவன் அநுக்கிரகம்பண்ணினபடியால், அவர்கள் ஏழு காளைகளையும் ஏழு ஆட்டுக்கடாக்களையும் பலியிட்டார்கள்.", "en": "And it came to pass, when God helped the Levites that bare the ark of the covenant of the LORD , that they offered seven bullocks and seven rams."}, {"verse": 27, "start": 308.68, "end": 326.3, "ta": "தாவீதும், பெட்டியைச் சுமக்கிற சகல லேவியரும், பாடகரும், பாடகரின் வேலையை விசாரிக்கிற தலைவனாகிய கெனானியாவும், மெல்லிய புடவையான சால்வைகளைத் தரித்திருந்தார்கள்; தாவீது சணல்நூல் ஏபோத்தைத் தரித்திருந்தான்.", "en": "And David was clothed with a robe of fine linen, and all the Levites that bare the ark, and the singers, and Chenaniah the master of the song with the singers: David also had upon him an ephod of linen."}, {"verse": 28, "start": 326.3, "end": 342.9, "ta": "அப்படியே இஸ்ரவேலனைத்தும் கர்த்தருடைய உடன்படிக்கைப் பெட்டியைக் கெம்பீரத்தோடும், எக்காளங்கள் பூரிகைகள் கைத்தாளங்களின் தொனியோடும் தம்புருகளையும் சுரமண்டலங்களையும் வாசிக்கிற சத்தத்தோடும் கொண்டுவந்தார்கள்.", "en": "Thus all Israel brought up the ark of the covenant of the LORD with shouting, and with sound of the cornet, and with trumpets, and with cymbals, making a noise with psalteries and harps."}, {"verse": 29, "start": 342.9, "end": 359.27, "ta": "கர்த்தருடைய உடன்படிக்கைப்பெட்டி தாவீதின் நகரமட்டும் வந்தபோது, சவுலின் குமாரத்தியாகிய மீகாள் பலகணிவழியாய்ப் பார்த்து, தாவீதுராஜா ஆடிப்பாடி வருகிறதைக் கண்டு, அவனைத் தன் இருதயத்திலே அவமதித்தாள்.", "en": "And it came to pass, as the ark of the covenant of the LORD came to the city of David, that Michal the daughter of Saul looking out at a window saw king David dancing and playing: and she despised him in her heart."}]}, "16": {"chapter": 16, "duration": 423.53, "audio_url": "audio_ot/OT13_16.mp3", "total_verses": 43, "verses": [{"verse": 1, "start": 3.8, "end": 18.5, "ta": "அவர்கள் தேவனுடைய பெட்டியை உள்ளே கொண்டுவந்தபோது, தாவீது அதற்குப் போட்ட கூடாரத்தின் நடுவே அவர்கள் அதை வைத்து, தேவனுடைய சந்நிதியில் சர்வாங்க தகனபலிகளையும் சமாதானபலிகளையும் செலுத்தினார்கள்.", "en": "So they brought the ark of God, and set it in the midst of the tent that David had pitched for it: and they offered burnt sacrifices and peace offerings before God."}, {"verse": 2, "start": 18.5, "end": 27.91, "ta": "தாவீது சர்வாங்க தகனபலிகளையும் சமாதானபலிகளையும் செலுத்தித் தீர்ந்தபின்பு, அவன் ஜனத்தைக் கர்த்தருடைய நாமத்திலே ஆசிர்வதித்து,", "en": "And when David had made an end of offering the burnt offerings and the peace offerings, he blessed the people in the name of the LORD ."}, {"verse": 3, "start": 27.91, "end": 41.8, "ta": "புருஷர் தொடங்கி ஸ்திரீகள்மட்டும், இஸ்ரவேலராகிய அனைவருக்கும் அவரவருக்கு ஒவ்வொரு அப்பத்தையும் ஒவ்வொரு இறைச்சித் துண்டையும், ஒவ்வொருபடி திராட்சரசத்தையும் பங்கிட்டுக் கொடுத்தான்.", "en": "And he dealt to every one of Israel, both man and woman, to every one a loaf of bread, and a good piece of flesh, and a flagon of wine ."}, {"verse": 4, "start": 41.8, "end": 53.41, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தரைப் பிரஸ்தாபம்பண்ணித் துதித்துப் புகழுகிறதற்கு கர்த்தருடைய பெட்டிக்கு முன்பாகச் சேவிக்கத்தக்க லேவியரில் சிலரை நியமித்தான்.", "en": "And he appointed certain of the Levites to minister before the ark of the LORD , and to record, and to thank and praise the LORD God of Israel:"}, {"verse": 5, "start": 53.41, "end": 73.63, "ta": "அவர்களில் ஆசாப் தலைவனும், சகரியா அவனுக்கு இரண்டாவதுமாயிருந்தான்; ஏயெல், செமிரமோத், யெகியேல், மத்தித்தியா, எலியாப், பெனாயா, ஓபேத்ஏதோம், ஏயெல் என்பவர்கள் தம்புரு சுரமண்டலம் என்னும் கீதவாத்தியங்களை வாசிக்கவும், ஆசாப் கைத்தாளங்களைக் கொட்டவும்,", "en": "Asaph the chief, and next to him Zechariah, Jeiel, and Shemiramoth, and Jehiel, and Mattithiah, and Eliab, and Benaiah, and Obed-edom: and Jeiel with psalteries and with harps; but Asaph made a sound with cymbals;"}, {"verse": 6, "start": 73.63, "end": 83.92, "ta": "பெனாயா, யாகாசியேல் என்னும் ஆசாரியர் எப்போதும் தேவனுடைய உடன்படிக்கைப் பெட்டிக்கு முன்பாகப் பூரிகைகளை ஊதவும் நியமிக்கப்பட்டார்கள்.", "en": "Benaiah also and Jahaziel the priests with trumpets continually before the ark of the covenant of God."}, {"verse": 7, "start": 83.92, "end": 93.62, "ta": "அப்படி ஆரம்பித்த அந்நாளிலேதானே கர்த்தருக்குத் துதியாகப் பாடும்படி தாவீது ஆசாப்பிடத்திலும் அவன் சகோதரரிடத்திலும் கொடுத்த சங்கீதமாவது:", "en": "Then on that day David delivered first this psalm to thank the LORD into the hand of Asaph and his brethren."}, {"verse": 8, "start": 93.62, "end": 103.54, "ta": "கர்த்தரைத் துதித்து, அவருடைய நாமத்தைப் பிரஸ்தாபமாக்குங்கள்; அவருடைய செய்கைகளை ஜனங்களுக்குள்ளே பிரசித்தப்படுத்துங்கள்.", "en": "Give thanks unto the LORD , call upon his name, make known his deeds among the people."}, {"verse": 9, "start": 103.54, "end": 110.75, "ta": "அவரைப் பாடி, அவரைக் கீர்த்தனம்பண்ணி அவருடைய அதிசயங்களையெல்லாம் தியானித்துப் பேசுங்கள்.", "en": "Sing unto him, sing psalms unto him, talk ye of all his wondrous works."}, {"verse": 10, "start": 110.75, "end": 119.27, "ta": "அவருடைய பரிசுத்த நாமத்தைக்குறித்து மேன்மைபாராட்டுங்கள்; கர்த்தரைத் தேடுகிறவர்களின் இருதயம் மகிழ்வதாக.", "en": "Glory ye in his holy name: let the heart of them rejoice that seek the LORD ."}, {"verse": 11, "start": 119.27, "end": 125.96, "ta": "கர்த்தரையும் அவர் வல்லமையையும் நாடுங்கள்; அவர் சமுகத்தை நித்தமும் தேடுங்கள்.", "en": "Seek the LORD and his strength, seek his face continually."}, {"verse": 12, "start": 125.96, "end": 132.94, "ta": "அவருடைய தாசனாகிய இஸ்ரவேலின் சந்ததியே! அவரால் தெரிந்துகொள்ளப்பட்டவர்களாகிய யாக்கோபின் புத்திரரே!", "en": "Remember his marvellous works that he hath done, his wonders, and the judgments of his mouth;"}, {"verse": 13, "start": 132.94, "end": 140.88, "ta": "அவர் செய்த அதிசயங்களையும் அற்புதங்களையும், அவர் வாக்கின் நியாயத்தீர்ப்புகளையும் நினைவுகூருங்கள்.", "en": "O ye seed of Israel his servant, ye children of Jacob, his chosen ones."}, {"verse": 14, "start": 140.88, "end": 148.09, "ta": "அவரே நம்முடைய தேவனாகிய கர்த்தர்; அவருடைய நியாயத்தீர்ப்புகள் பூமியெங்கும் விளங்கும்.", "en": "He is the LORD our God; his judgments are in all the earth."}, {"verse": 15, "start": 148.09, "end": 155.29, "ta": "ஆயிரந்தலைமுறைக்கென்று அவர் கட்டளையிட்ட வாக்கையும், ஆபிரகாமோடே அவர் பண்ணின உடன்படிக்கையையும்,", "en": "Be ye mindful always of his covenant; the word which he commanded to a thousand generations;"}, {"verse": 16, "start": 155.29, "end": 160.65, "ta": "அவர் ஈசாக்குக்கு இட்ட ஆணையையும் என்றென்றைக்கும் நினைத்திருங்கள்.", "en": "Even of the covenant which he made with Abraham, and of his oath unto Isaac;"}, {"verse": 17, "start": 160.65, "end": 167.42, "ta": "அதை யாக்கோபுக்குப் பிரமாணமாகவும், இஸ்ரவேலுக்கு நித்திய உடன்படிக்கையாகவும் உறுதிப்படுத்தி:", "en": "And hath confirmed the same to Jacob for a law, and to Israel for an everlasting covenant,"}, {"verse": 18, "start": 167.42, "end": 172.56, "ta": "உங்கள் சுதந்தரபாகமாக கானான் தேசத்தை உனக்குத் தருவேன் என்றார்.", "en": "Saying, Unto thee will I give the land of Canaan, the lot of your inheritance;"}, {"verse": 19, "start": 172.56, "end": 179.32, "ta": "அக்காலத்தில் அவர்கள் கொஞ்சத்தொகைக்குட்பட்ட சொற்பஜனங்களும் பரதேசிகளுமாயிருந்தார்கள்.", "en": "When ye were but few, even a few, and strangers in it."}, {"verse": 20, "start": 179.32, "end": 187.63, "ta": "அவர்கள் ஒரு ஜனத்தை விட்டு மறு ஜனத்தண்டைக்கும், ஒரு ராஜ்யத்தை விட்டு மறு தேசத்தாரண்டைக்கும் போனார்கள்.", "en": "And when they went from nation to nation, and from one kingdom to another people;"}, {"verse": 21, "start": 187.63, "end": 194.47, "ta": "அவர்களை யொடுக்கும்படி ஒருவருக்கும் இடங்கொடாமல், அவர்கள் நிமித்தம் ராஜாக்களை கடிந்துகொண்டு:", "en": "He suffered no man to do them wrong: yea, he reproved kings for their sakes,"}, {"verse": 22, "start": 194.47, "end": 203.51, "ta": "நான் அபிஷேகம்பண்ணினவர்களை நீங்கள் தொடாமலும், என்னுடைய தீர்க்கதரிசிகளுக்குத் தீங்குசெய்யாமலும் இருங்கள் என்றார்.", "en": "Saying , Touch not mine anointed, and do my prophets no harm."}, {"verse": 23, "start": 203.51, "end": 211.67, "ta": "பூமியின் சகல குடிகளே, கர்த்தரைப்பாடி, நாளுக்குநாள் அவருடைய ரட்சிப்பைச் சுவிசேஷமாய் அறிவியுங்கள்.", "en": "Sing unto the LORD , all the earth; shew forth from day to day his salvation."}, {"verse": 24, "start": 211.67, "end": 220.41, "ta": "ஜாதிகளுக்குள்ளும் அவருடைய மகிமையையும், சகல ஜனங்களுக்குள்ளும் அவருடைய அதிசயங்களையும் விவரித்துச்சொல்லுங்கள்.", "en": "Declare his glory among the heathen; his marvellous works among all nations."}, {"verse": 25, "start": 220.41, "end": 229.16, "ta": "கர்த்தர் பெரியவரும் மிகவும் துதிக்கப்படத்தக்கவருமாயிருக்கிறார்; எல்லா தேவர்களிலும் பயப்படத்தக்கவர் அவரே.", "en": "For great is the LORD , and greatly to be praised: he also is to be feared above all gods."}, {"verse": 26, "start": 229.16, "end": 235.92, "ta": "சகல ஜனங்களுடைய தேவர்களும் விக்கிரகங்கள்தானே; கர்த்தரோ வானங்களை உண்டாக்கினவர்.", "en": "For all the gods of the people are idols: but the LORD made the heavens."}, {"verse": 27, "start": 235.92, "end": 244.15, "ta": "மகிமையும் கனமும் அவர் சமுகத்தில் இருக்கிறது; வல்லமையும் மகிழ்ச்சியும் அவர் ஸ்தலத்தில் இருக்கிறது.", "en": "Glory and honour are in his presence; strength and gladness are in his place."}, {"verse": 28, "start": 244.15, "end": 253.34, "ta": "ஜனங்களின் வம்சங்களே, கர்த்தருக்கு மகிமையையும் வல்லமையையும் செலுத்துங்கள்; கர்த்தருக்கே அதைச் செலுத்துங்கள்.", "en": "Give unto the LORD , ye kindreds of the people, give unto the LORD glory and strength."}, {"verse": 29, "start": 253.34, "end": 267.53, "ta": "கர்த்தருக்கு அவருடைய நாமத்திற்குரிய மகிமையைச் செலுத்தி, காணிக்கைகளைக் கொண்டுவந்து, அவருடைய சந்நிதியில் பிரவேசியுங்கள்; பரிசுத்த அலங்காரத்துடனே கர்த்தரைத் தொழுதுகொள்ளுங்கள்.", "en": "Give unto the LORD the glory due unto his name: bring an offering, and come before him: worship the LORD in the beauty of holiness."}, {"verse": 30, "start": 267.53, "end": 277.23, "ta": "பூலோகத்தாரே, நீங்கள் யாவரும் அவருக்கு முன்பாக நடுங்குங்கள்; அவர் பூச்சக்கரத்தை அசையாதபடிக்கு உறுதிப்படுத்துகிறவர்.", "en": "Fear before him, all the earth: the world also shall be stable, that it be not moved."}, {"verse": 31, "start": 277.23, "end": 286.12, "ta": "வானங்கள் மகிழ்ந்து, பூமி பூரிப்பதாக; கர்த்தர் ராஜரிகம்பண்ணுகிறார் என்று ஜாதிகளுக்குள்ளே சொல்லப்படுவதாக.", "en": "Let the heavens be glad, and let the earth rejoice: and let men say among the nations, The LORD reigneth."}, {"verse": 32, "start": 286.12, "end": 292.3, "ta": "சமுத்திரமும் அதின் நிறைவும் முழங்கி, நாடும் அதிலுள்ள யாவும் களிகூருவதாக.", "en": "Let the sea roar, and the fulness thereof: let the fields rejoice, and all that is therein."}, {"verse": 33, "start": 292.3, "end": 301.27, "ta": "அப்பொழுது கர்த்தருக்கு முன்பாகக் காட்டுவிருட்சங்களும் கெம்பீரிக்கும்; அவர் பூமியை நியாயந்தீர்க்க வருகிறார்.", "en": "Then shall the trees of the wood sing out at the presence of the LORD , because he cometh to judge the earth."}, {"verse": 34, "start": 301.27, "end": 307.0, "ta": "கர்த்தரைத் துதியுங்கள், அவர் நல்லவர், அவர் கிருபை என்றுமுள்ளது.", "en": "O give thanks unto the LORD ; for he is good; for his mercy endureth for ever."}, {"verse": 35, "start": 307.0, "end": 324.49, "ta": "எங்கள் ரட்சிப்பின் தேவனே, நாங்கள் உமது பரிசுத்த நாமத்தைப் போற்றி, உம்மைத் துதிக்கிறதினால் மேன்மைபாராட்டும்படிக்கு, எங்களை ரட்சித்து, எங்களைச் சேர்த்துக்கொண்டு, ஜாதிகளுக்கு எங்களை நீங்கலாக்கியருளுமென்று சொல்லுங்கள்.", "en": "And say ye, Save us, O God of our salvation, and gather us together, and deliver us from the heathen, that we may give thanks to thy holy name, and glory in thy praise."}, {"verse": 36, "start": 324.49, "end": 335.59, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தருக்கு சதாகாலங்களிலும் ஸ்தோத்திரமுண்டாவதாக, அதற்கு ஜனங்களெல்லாரும் ஆமென் என்று சொல்லிக் கர்த்தரைத் துதித்தார்கள்.", "en": "Blessed be the LORD God of Israel for ever and ever. And all the people said, Amen, and praised the LORD ."}, {"verse": 37, "start": 335.59, "end": 353.08, "ta": "பின்பு பெட்டிக்கு முன்பாக நித்தம் அன்றாடக முறையாய்ச் சேவிக்கும்படி, அவன் அங்கே கர்த்தருடைய உடன்படிக்கைப் பெட்டிக்கு முன்பாக ஆசாப்பையும், அவன் சகோதரரையும், ஓபேத்ஏதோமையும், அவர்களுடைய சகோதரராகிய அறுபத்தெட்டுப்பேரையும் வைத்து,", "en": "So he left there before the ark of the covenant of the LORD Asaph and his brethren, to minister before the ark continually, as every day’s work required:"}, {"verse": 38, "start": 353.08, "end": 359.77, "ta": "எதித்தூனின் குமாரனாகிய இந்த ஓபேத்ஏதோமையும் ஓசாவையும் வாசல்காக்கிறவர்களாக வைத்தான்.", "en": "And Obed-edom with their brethren, threescore and eight; Obed-edom also the son of Jeduthun and Hosah to be porters:"}, {"verse": 39, "start": 359.77, "end": 379.55, "ta": "கிபியோனிலுள்ள மேட்டின் மேலிருக்கிற கர்த்தருடைய வாசஸ்தலத்திற்கு முன்பாக இருக்கிற சர்வாங்க தகனபலிபீடத்தின்மேல் சர்வாங்க தகனங்களை நித்தமும், அந்திசந்தியில் கர்த்தர் இஸ்ரவேலுக்குக் கற்பித்த நியாயப்பிரமாணத்தில் எழுதியிருக்கிறபடியெல்லாம் கர்த்தருக்குச் செலுத்துவதற்காக,", "en": "And Zadok the priest, and his brethren the priests, before the tabernacle of the LORD in the high place that was at Gibeon,"}, {"verse": 40, "start": 379.55, "end": 385.35, "ta": "அங்கே அவன் ஆசாரியனாகிய சாதோக்கையும், அவன் சகோதரராகிய ஆசாரியரையும் வைத்து,", "en": "To offer burnt offerings unto the LORD upon the altar of the burnt offering continually morning and evening, and to do according to all that is written in the law of the LORD , which he commanded Israel;"}, {"verse": 41, "start": 385.35, "end": 397.63, "ta": "இவர்களோடுங்கூட ஏமானையும், எதித்தூனையும், பேர்பேராகக் குறித்துத் தெரிந்துகொள்ளப்பட்ட மற்றச் சிலரையும் கர்த்தருடைய கிருபை என்றுமுள்ளது என்று அவரைத் துதிக்கவும்,", "en": "And with them Heman and Jeduthun, and the rest that were chosen, who were expressed by name, to give thanks to the LORD , because his mercy endureth for ever;"}, {"verse": 42, "start": 397.63, "end": 412.77, "ta": "பூரிகைகளையும் கைத்தாளங்களையும் தேவனைப் பாடுகிறதற்குரிய கீதவாத்தியங்களையும் தொனிக்கச்செய்யவும் அவர்களுடன் ஏமானையும் எதித்தூனையும் வைத்து, எதித்தூனின் குமாரரை வாசல்காக்கிறவர்களாகக் கட்டளையிட்டான்.", "en": "And with them Heman and Jeduthun with trumpets and cymbals for those that should make a sound, and with musical instruments of God. And the sons of Jeduthun were porters."}, {"verse": 43, "start": 412.77, "end": 422.03, "ta": "பின்பு ஜனங்கள் எல்லாரும் அவரவர் தங்கள் வீட்டிற்குப் போனார்கள்; தாவீதும் தன் வீட்டாரை ஆசீர்வதிக்கத்திரும்பினான்.", "en": "And all the people departed every man to his house: and David returned to bless his house."}]}, "17": {"chapter": 17, "duration": 360.19, "audio_url": "audio_ot/OT13_17.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 19.8, "ta": "தாவீது தன் வீட்டிலே வாசமாயிருக்கிறபோது, அவன் தீர்க்கதரிசியாகிய நாத்தானை நோக்கி: பாரும், நான் கேதுருமரவீட்டிலே வாசம்பண்ணுகிறேன்; கர்த்தருடைய உடன்படிக்கைப் பெட்டியோ திரைகளின்கீழ் இருக்கிறது என்றான்.", "en": "Now it came to pass, as David sat in his house, that David said to Nathan the prophet, Lo, I dwell in an house of cedars, but the ark of the covenant of the LORD remaineth under curtains."}, {"verse": 2, "start": 19.8, "end": 29.6, "ta": "அப்பொழுது நாத்தான் தாவீதை நோக்கி: உம்முடைய இருதயத்தில் இருக்கிறதையெல்லாம் செய்யும்; தேவன் உம்மோடு இருக்கிறார் என்றான்.", "en": "Then Nathan said unto David, Do all that is in thine heart; for God is with thee."}, {"verse": 3, "start": 29.6, "end": 34.84, "ta": "அன்று ராத்திரியிலே, தேவனுடைய வார்த்தை நாத்தானுக்கு உண்டாகி, அவர்:", "en": "And it came to pass the same night, that the word of God came to Nathan, saying,"}, {"verse": 4, "start": 34.84, "end": 44.79, "ta": "நீ போய், என் தாசனாகிய தாவீதை நோக்கி: கர்த்தர் சொல்லுகிறது என்னவென்றால்: நான் வாசமாயிருக்க நீ எனக்கு ஆலயத்தைக் கட்டவேண்டாம்.", "en": "Go and tell David my servant, Thus saith the LORD , Thou shalt not build me an house to dwell in:"}, {"verse": 5, "start": 44.79, "end": 59.75, "ta": "நான் இஸ்ரவேலை வரப்பண்ணின நாள்முதற்கொண்டு இந்நாள்வரைக்கும் நான் ஒரு ஆலயத்திலே வாசம்பண்ணாமல், ஒரு கூடாரத்திலிருந்து மறு கூடாரத்துக்கும், ஒரு வாசஸ்தலத்திலிருந்து மறு வாசஸ்தலத்துக்கும் போனேன்.", "en": "For I have not dwelt in an house since the day that I brought up Israel unto this day; but have gone from tent to tent, and from one tabernacle to another ."}, {"verse": 6, "start": 59.75, "end": 78.77, "ta": "நான் சகல இஸ்ரவேலோடும் உலாவி வந்த எவ்விடத்திலாகிலும், நான் என் ஜனத்தை மேய்க்கக் கற்பித்த இஸ்ரவேலின் நியாயாதிபதிகளில் யாதொருவனை நோக்கி: நீங்கள் எனக்குக் கேதுருமரத்தால் செய்யப்பட்ட ஆலயத்தைக் கட்டாதிருக்கிறது என்ன என்று யாதொரு வார்த்தை சொன்னது உண்டோ?", "en": "Wheresoever I have walked with all Israel, spake I a word to any of the judges of Israel, whom I commanded to feed my people, saying, Why have ye not built me an house of cedars?"}, {"verse": 7, "start": 78.77, "end": 93.89, "ta": "இப்போதும், நீ என் தாசனாகிய தாவீதை நோக்கி: சேனைகளின் கர்த்தர் சொல்லுகிறது என்னவென்றால்: நீ என் ஜனமாகிய இஸ்ரவேலின்மேல் அதிபதியாயிருக்கும்படி, ஆடுகளின் பின்னே நடந்த உன்னை ஆட்டுமந்தையை விட்டு எடுத்து,", "en": "Now therefore thus shalt thou say unto my servant David, Thus saith the LORD of hosts, I took thee from the sheepcote, even from following the sheep, that thou shouldest be ruler over my people Israel:"}, {"verse": 8, "start": 93.89, "end": 107.23, "ta": "நீ போன இடமெல்லாம் உன்னோடே இருந்து, உன் சத்துருக்களையெல்லாம் உனக்கு முன்பாக நிர்மூலமாக்கி, பூமியிலிருக்கிற பெரியோர்களின் நாமத்திற்கு ஒத்த நாமத்தை உனக்கு உண்டாக்கினேன்.", "en": "And I have been with thee whithersoever thou hast walked, and have cut off all thine enemies from before thee, and have made thee a name like the name of the great men that are in the earth."}, {"verse": 9, "start": 107.23, "end": 131.19, "ta": "நான் என் ஜனமாகிய இஸ்ரவேலுக்கு ஒரு இடத்தையும் ஏற்படுத்தி, அவர்கள் தங்கள் ஸ்தானத்திலே குடியிருக்கவும், இனி அவர்கள் அலையாமலும், முன்போலும், நான் என் ஜனமாகிய இஸ்ரவேலின்மேல் நியாயாதிபதிகளைக் கட்டளையிட்ட நாள்முதல் நடந்ததுபோலும், நியாயக்கேட்டின் மக்களால் இனிச் சிறுமைப்படாமலும் இருக்கவும் அவர்களை நாட்டினேன்.", "en": "Also I will ordain a place for my people Israel, and will plant them, and they shall dwell in their place, and shall be moved no more; neither shall the children of wickedness waste them any more, as at the beginning,"}, {"verse": 10, "start": 131.19, "end": 141.44, "ta": "உன் சத்துருக்களையெல்லாம் கீழ்ப்படுத்தினேன். இப்போதும் கர்த்தர் உனக்கு ஒரு வீட்டைக் கட்டுவார் என்பதை உனக்கு அறிவிக்கிறேன்.", "en": "And since the time that I commanded judges to be over my people Israel. Moreover I will subdue all thine enemies. Furthermore I tell thee that the LORD will build thee an house."}, {"verse": 11, "start": 141.44, "end": 154.85, "ta": "நீ உன் பிதாக்களிடத்திலே போக, உன் நாட்கள் நிறைவேறும்போது, நான் உனக்குப்பின்பு உன் புத்திரரில் ஒருவனாகிய உன் சந்ததியை எழும்பப்பண்ணி, அவன் ராஜ்யத்தை நிலைப்படுத்துவேன்.", "en": "And it shall come to pass, when thy days be expired that thou must go to be with thy fathers, that I will raise up thy seed after thee, which shall be of thy sons; and I will establish his kingdom."}, {"verse": 12, "start": 154.85, "end": 162.3, "ta": "அவன் எனக்கு ஒரு ஆலயத்தைக் கட்டுவான்; அவன் சிங்காசனத்தை என்றைக்கும் நிலைக்கப்பண்ணுவேன்.", "en": "He shall build me an house, and I will stablish his throne for ever."}, {"verse": 13, "start": 162.3, "end": 175.2, "ta": "நான் அவனுக்குப் பிதாவாயிருப்பேன், அவன் எனக்குக் குமாரனாயிருப்பான்; உனக்கு முன் இருந்தவனை விட்டு என் கிருபையை நான் விலகப்பண்ணினதுபோல, அவனை விட்டு விலகப்பண்ணாமல்,", "en": "I will be his father, and he shall be my son: and I will not take my mercy away from him, as I took it from him that was before thee:"}, {"verse": 14, "start": 175.2, "end": 187.07, "ta": "அவனை என் ஆலயத்திலும் என் ராஜ்யத்திலும் என்றென்றைக்கும் நிலைக்கப்பண்ணுவேன்; அவனுடைய ராஜாசனம் என்றென்றைக்கும் நிலைபெற்றிருக்கும் என்று சொல் என்றார்.", "en": "But I will settle him in mine house and in my kingdom for ever: and his throne shall be established for evermore."}, {"verse": 15, "start": 187.07, "end": 194.74, "ta": "நாத்தான் இந்த எல்லா வார்த்தைகளின்படியும் இந்த எல்லாத் தரிசனத்தின்படியும் தாவீதுக்குச் சொன்னான்.", "en": "According to all these words, and according to all this vision, so did Nathan speak unto David."}, {"verse": 16, "start": 194.74, "end": 209.26, "ta": "அப்பொழுது தாவீதுராஜா உட்பிரவேசித்து, கர்த்தருடைய சமுகத்திலிருந்து: தேவனாகிய கர்த்தாவே, தேவரீர் என்னை இதுவரைக்கும் கொண்டுவந்ததற்கு நான் எம்மாத்திரம்? என் வீடும் எம்மாத்திரம்?", "en": "And David the king came and sat before the LORD , and said, Who am I, O LORD God, and what is mine house, that thou hast brought me hitherto?"}, {"verse": 17, "start": 209.26, "end": 227.98, "ta": "தேவனே, இது இன்னும் உம்முடைய பார்வைக்குக் கொஞ்சக்காரியமாயிருக்கிறது என்று தேவனான கர்த்தராயிருக்கிற நீர் உமது அடியானுடைய வீட்டைக்குறித்து வெகுதூரமாயிருக்கும் காலத்துச் செய்தியையும் சொல்லி, என்னை மகா மேன்மையான சந்ததியின் மனுஷனாகப் பார்த்தீர்.", "en": "And yet this was a small thing in thine eyes, O God; for thou hast also spoken of thy servant’s house for a great while to come, and hast regarded me according to the estate of a man of high degree, O LORD God."}, {"verse": 18, "start": 227.98, "end": 237.57, "ta": "உமது அடியானுக்கு உண்டாகும் கனத்தைப்பற்றி, தாவீது அப்புறம் உம்மோடே சொல்வது என்ன? தேவரீர் உமது அடியானை அறிவீர்.", "en": "What can David speak more to thee for the honour of thy servant? for thou knowest thy servant."}, {"verse": 19, "start": 237.57, "end": 250.76, "ta": "கர்த்தாவே, உமது அடியானின் நிமித்தமும், உமது இருதயத்தின்படியும், இந்தப் பெரிய காரியங்களையெல்லாம் அறியப்பண்ணும்படிக்கு, இந்தப் பெரிய காரியத்தையெல்லாம் செய்தீர்.", "en": "O LORD , for thy servant’s sake, and according to thine own heart, hast thou done all this greatness, in making known all these great things."}, {"verse": 20, "start": 250.76, "end": 261.08, "ta": "கர்த்தாவே, நாங்கள் எங்கள் காதுகளால் கேட்ட எல்லாவற்றின்படியும் தேவரீருக்கு நிகரானவர் இல்லை; உம்மைத்தவிர வேறே தேவனும் இல்லை.", "en": "O LORD , there is none like thee, neither is there any God beside thee, according to all that we have heard with our ears."}, {"verse": 21, "start": 261.08, "end": 281.06, "ta": "உமது ஜனமாகிய இஸ்ரவேலுக்கு நிகரான ஜனமும் உண்டோ? பூலோகத்தில் இந்த ஒரே ஜாதியை தேவனாகிய நீர் உமக்கு ஜனமாக மீட்கும்படி, பயங்கரமான பெரிய காரியங்களினால் உமக்குக் கீர்த்தியை உண்டாக்கி, நீர் எகிப்திற்கு நீங்கலாக்கி மீட்ட உமது ஜனத்திற்குமுன்பாக ஜாதிகளைத் துரத்தி,", "en": "And what one nation in the earth is like thy people Israel, whom God went to redeem to be his own people, to make thee a name of greatness and terribleness, by driving out nations from before thy people, whom thou hast redeemed out of Egypt?"}, {"verse": 22, "start": 281.06, "end": 291.01, "ta": "உமது ஜனமாகிய இஸ்ரவேலர் என்றைக்கும் உமது ஜனமாயிருப்பதற்கு அவர்களை நிலைப்படுத்தி, கர்த்தராகிய நீர்தாமே அவர்களுக்கு தேவனானீர்.", "en": "For thy people Israel didst thou make thine own people for ever; and thou, LORD , becamest their God."}, {"verse": 23, "start": 291.01, "end": 303.62, "ta": "இப்போதும் கர்த்தாவே, தேவரீர் அடியானையும் அவன் வீட்டையும் குறித்துச் சொன்ன வார்த்தை என்றென்றைக்கும் நிலைவரப்பட்டிருப்பதாக; தேவரீர் சொன்னபடியே செய்தருளும்.", "en": "Therefore now, LORD , let the thing that thou hast spoken concerning thy servant and concerning his house be established for ever, and do as thou hast said."}, {"verse": 24, "start": 303.62, "end": 321.46, "ta": "ஆம், அது நிலைவரப்பட்டிருக்கவும், இஸ்ரவேலின் தேவனாகிய சேனைகளின் கர்த்தர் இஸ்ரவேலுக்கு தேவன் என்றும் உமது அடியானாகிய தாவீதின் வீடு உமக்கு முன்பாக, திடமானதென்றும் சொல்லப்படுவதினால், உமது நாமம் என்றைக்கும் மகிமைப்படவும்கடவது.", "en": "Let it even be established, that thy name may be magnified for ever, saying, The LORD of hosts is the God of Israel, even a God to Israel: and let the house of David thy servant be established before thee."}, {"verse": 25, "start": 321.46, "end": 334.66, "ta": "உனக்கு வீடு கட்டுவேன் என்று என் தேவனாகிய நீர் உமது அடியான் செவிகேட்க வெளிப்படுத்தினீர்; ஆகையால் உமக்கு முன்பாக விண்ணப்பம்பண்ண, அடியானுக்கு மனத்தைரியம் கிடைத்தது.", "en": "For thou, O my God, hast told thy servant that thou wilt build him an house: therefore thy servant hath found in his heart to pray before thee."}, {"verse": 26, "start": 334.66, "end": 342.77, "ta": "இப்போதும் கர்த்தாவே, நீரே தேவன்; நீர் உமது அடியானைக்குறித்து இந்த நல்ல விசேஷத்தைச் சொன்னீர்.", "en": "And now, LORD , thou art God, and hast promised this goodness unto thy servant:"}, {"verse": 27, "start": 342.77, "end": 358.69, "ta": "இப்போதும் உமது அடியானின் வீடு என்றைக்கும் உமக்கு முன்பாக இருக்கும்படிக்கு, அதை ஆசிர்வதித்தருளினீர்; கர்த்தராகிய தேவரீர் அதை ஆர்வதித்தபடியினால், அது என்றைக்கும் ஆசீர்வதிக்கப்பட்டிருக்கும் என்றான்.", "en": "Now therefore let it please thee to bless the house of thy servant, that it may be before thee for ever: for thou blessest, O LORD , and it shall be blessed for ever."}]}, "18": {"chapter": 18, "duration": 216.73, "audio_url": "audio_ot/OT13_18.mp3", "total_verses": 17, "verses": [{"verse": 1, "start": 3.8, "end": 17.11, "ta": "இதற்குப்பின்பு, தாவீது பெலிஸ்தரை முறிய அடித்து, அவர்களைக் கீழ்ப்படுத்தி, காத்பட்டணத்தையும் அதின் கிராமங்களையும் பெலிஸ்தரின் கையிலிருந்து பிடித்துக்கொண்டான்.", "en": "Now after this it came to pass, that David smote the Philistines, and subdued them, and took Gath and her towns out of the hand of the Philistines."}, {"verse": 2, "start": 17.11, "end": 26.14, "ta": "அவன் மோவாபியரையும் முறியடித்ததினால், மோவாபியர் தாவீதைச் சேவித்து அவனுக்குக் காணிக்கைகளைச் செலுத்தினார்கள்.", "en": "And he smote Moab; and the Moabites became David’s servants, and brought gifts."}, {"verse": 3, "start": 26.14, "end": 37.24, "ta": "சோபாவின் ராஜாவாகிய ஆதாரேசர் ஐபிராத் நதியண்டையில் தன் இராணுவத்தை நிறுத்தப்போகிறபோது, தாவீது அவனையும் ஆமாத்தின் கிட்டே முறிய அடித்தான்.", "en": "And David smote Hadarezer king of Zobah unto Hamath, as he went to stablish his dominion by the river Euphrates."}, {"verse": 4, "start": 37.24, "end": 51.86, "ta": "அவனுக்கு இருந்த ஆயிரம் இரதங்களையும் ஆயிரம் குதிரைவீரரையும் பதினாயிரம் காலாட்களையும் பிடித்து, இரதங்களில் நூறு இரதங்களையும் வைத்துக்கொண்டு, மற்றவைகளையெல்லாம் துண்டாடிப்போட்டான்.", "en": "And David took from him a thousand chariots, and seven thousand horsemen, and twenty thousand footmen: David also houghed all the chariot horses , but reserved of them an hundred chariots."}, {"verse": 5, "start": 51.86, "end": 62.87, "ta": "சோபாவின் ராஜாவாகிய ஆதாரேசருக்கு உதவிசெய்ய தமஸ்குபட்டணத்தாராகிய சீரியர் வந்தார்கள்; தாவீது சீரியரில் இருபத்தீராயிரம்பேரை வெட்டிப்போட்டு,", "en": "And when the Syrians of Damascus came to help Hadarezer king of Zobah, David slew of the Syrians two and twenty thousand men."}, {"verse": 6, "start": 62.87, "end": 77.8, "ta": "தமஸ்குவுக்கடுத்த சீரியாவிலே தாணையங்களை வைத்தான்; சீரியர் தாவீதைச் சேவித்து அவனுக்குக் காணிக்கைகளைச் செலுத்தினார்கள்; தாவீது போன இடத்திலெல்லாம் கர்த்தர் அவனைக் காப்பாற்றினார்.", "en": "Then David put garrisons in Syria-damascus; and the Syrians became David’s servants, and brought gifts. Thus the LORD preserved David whithersoever he went."}, {"verse": 7, "start": 77.8, "end": 86.14, "ta": "ஆதாரேசரின் சேவகருக்கு இருந்த பொன் பரிசைகளைத் தாவீது எடுத்து, அவைகளை எருசலேமுக்குக் கொண்டுவந்தான்.", "en": "And David took the shields of gold that were on the servants of Hadarezer, and brought them to Jerusalem."}, {"verse": 8, "start": 86.14, "end": 103.35, "ta": "ஆதாரேசரின் பட்டணங்களாகிய திப்காத்திலும் கூனிலுமிருந்து தாவீது வெகு திரளான வெண்கலத்தையும் எடுத்துக்கொண்டுவந்தான்; அதினாலே சாலொமோன் வெண்கலக் கடல்தொட்டியையும் தூண்களையும் வெண்கலத் தட்டுமுட்டுகளையும் உண்டாக்கினான்.", "en": "Likewise from Tibhath, and from Chun, cities of Hadarezer, brought David very much brass, wherewith Solomon made the brasen sea, and the pillars, and the vessels of brass."}, {"verse": 9, "start": 103.35, "end": 112.23, "ta": "தாவீது சோபாவின் ராஜாவாகிய ஆதாரேசரின் இராணுவத்தையெல்லாம் முறிய அடித்த செய்தியை ஆமாத்தின் ராஜாவாகிய தோயூ கேட்டபோது,", "en": "Now when Tou king of Hamath heard how David had smitten all the host of Hadarezer king of Zobah;"}, {"verse": 10, "start": 112.23, "end": 137.33, "ta": "அவன் தாவீது ராஜாவின் சுகசெய்தியை விசாரிக்கவும், அவன் ஆதாரேசரோடு யுத்தம்பண்ணி, அவனை முறிய அடித்ததற்காக அவனுக்கு வினவுதல் சொல்லவும், தன் குமாரனாகிய அதோராமையும், பொன்னும் வெள்ளியும் வெண்கலமுமான சகலவிதத் தட்டுமுட்டுகளையும், அவனிடத்Τுக்கு அனுப்பினான்; ஆதாரேசர் தோயூவின்மேல் யுத்தம்பண்ணுகிறவனாயிருந்தான்.", "en": "He sent Hadoram his son to king David, to enquire of his welfare, and to congratulate him, because he had fought against Hadarezer, and smitten him; (for Hadarezer had war with Tou;) and with him all manner of vessels of gold and silver and brass."}, {"verse": 11, "start": 137.33, "end": 156.38, "ta": "அந்தத் தட்டுமுட்டுகளையும், தான் ஏதோமியர், மோவாபியர், அம்மோன் புத்திரர், பெலிஸ்தர், அமலேக்கியர் என்னும் சகல ஜாதிகளின் கையிலும் வாங்கின வெள்ளியையும், பொன்னையும்கூடத் தாவீதுராஜா கர்த்தருக்குப் பரிசுத்தமென்று நேர்ந்துகொண்டான்.", "en": "Them also king David dedicated unto the LORD , with the silver and the gold that he brought from all these nations; from Edom, and from Moab, and from the children of Ammon, and from the Philistines, and from Amalek."}, {"verse": 12, "start": 156.38, "end": 163.96, "ta": "செருயாவின் குமாரன் அபிசாயி உப்புப் பள்ளத்தாக்கிலே பதினெண்ணாயிரம் ஏதோமியரை முறிய அடித்தான்.", "en": "Moreover Abishai the son of Zeruiah slew of the Edomites in the valley of salt eighteen thousand."}, {"verse": 13, "start": 163.96, "end": 176.89, "ta": "ஆகையால் தாவீது ஏதோமிலே தாணையம் போட்டான்; ஏதோமியர் எல்லாரும் அவனைச் சேவிக்கிறவர்களானார்கள்; தாவீது போன இடத்திலெல்லாம் கர்த்தர் அவனைக் காப்பாற்றினார்.", "en": "And he put garrisons in Edom; and all the Edomites became David’s servants. Thus the LORD preserved David whithersoever he went."}, {"verse": 14, "start": 176.89, "end": 184.32, "ta": "தாவீது இஸ்ரவேலையெல்லாம் ஆண்டு, தன்னுடைய ஜனத்திற்கெல்லாம் நியாயமும் நீதியும் செய்தான்.", "en": "So David reigned over all Israel, and executed judgment and justice among all his people."}, {"verse": 15, "start": 184.32, "end": 193.27, "ta": "செருயாவின் குமாரன் யோவாப் இராணுவத்தலைவனாயிருந்தான்; ஆகிலுூதின் குமாரனாகிய யோசபாத் மந்திரியாயிருந்தான்.", "en": "And Joab the son of Zeruiah was over the host; and Jehoshaphat the son of Ahilud, recorder."}, {"verse": 16, "start": 193.27, "end": 203.45, "ta": "அகிதூபின் குமாரன் சாதோக்கும், அபியத்தாரின் குமாரன் அபிமெலேக்கும் ஆசாரியராயிருந்தார்கள்; சவிஷா சம்பிரதியாயிருந்தான்.", "en": "And Zadok the son of Ahitub, and Abimelech the son of Abiathar, were the priests; and Shavsha was scribe;"}, {"verse": 17, "start": 203.45, "end": 215.23, "ta": "யோய்தாவின் குமாரன் பெனாயா கிரேத்தியருக்கும் பிலேத்தியருக்கும் தலைவனாயிருந்தான்; தாவீதின் புத்திரர் ராஜாவினிடத்தில் பிரதானிகளாயிருந்தார்கள்.", "en": "And Benaiah the son of Jehoiada was over the Cherethites and the Pelethites; and the sons of David were chief about the king."}]}, "19": {"chapter": 19, "duration": 283.88, "audio_url": "audio_ot/OT13_19.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 11.99, "ta": "அதன்பின்பு, அம்மோன் புத்திரரின் ராஜாவாகிய நாகாஸ் மரித்து, அவன் குமாரன் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "Now it came to pass after this, that Nahash the king of the children of Ammon died, and his son reigned in his stead."}, {"verse": 2, "start": 11.99, "end": 33.04, "ta": "அப்பொழுது தாவீது: ஆனூனின் தகப்பனாகிய நாகாஸ் எனக்குத் தயவுசெய்ததுபோல, நானும் அவன் குமாரனாகிய இவனுக்குத் தயவுசெய்வேன் என்று சொல்லி, அவன் தகப்பனுக்காக அவனுக்கு ஆறுதல்சொல்ல ஸ்தானாபதிகளை அனுப்பினான்; தாவீதின் ஊழியக்காரர் ஆனூனுக்கு ஆறுதல் சொல்ல அம்மோன் புத்திரரின் தேசத்திலே வந்தபோது,", "en": "And David said, I will shew kindness unto Hanun the son of Nahash, because his father shewed kindness to me. And David sent messengers to comfort him concerning his father. So the servants of David came into the land of the children of Ammon to Hanun, to comfort him."}, {"verse": 3, "start": 33.04, "end": 55.95, "ta": "அம்மோன் புத்திரரின் பிரபுக்கள் ஆனூனைப் பார்த்து: தாவீது ஆறுதல் சொல்லுகிறவர்களை உம்மிடத்தில் அனுப்பினது, உம்முடைய தகப்பனைக் கனம்பண்ணுகிறதாய் உமக்குத் தோன்றுகிறதோ? தேசத்தை ஆராயவும், அதைக் கவிழ்த்துப்போடவும், உளவுபார்க்கவும் அல்லவோ, அவன் ஊழியக்காரர் உம்மிடத்தில் வந்தார்கள் என்று சொன்னார்கள்.", "en": "But the princes of the children of Ammon said to Hanun, Thinkest thou that David doth honour thy father, that he hath sent comforters unto thee? are not his servants come unto thee for to search, and to overthrow, and to spy out the land?"}, {"verse": 4, "start": 55.95, "end": 71.11, "ta": "அப்பொழுது ஆனூன்: தாவீதின் ஊழியக்காரரைப் பிடித்து, அவர்கள் தாடியைச் சிரைத்து, அவர்களுடைய வஸ்திரங்களை இருப்பிடமட்டும் வைத்துவிட்டு, மற்றப் பாதியைக் கத்தரித்துப்போட்டு, அவர்களை அனுப்பிவிட்டான்.", "en": "Wherefore Hanun took David’s servants, and shaved them, and cut off their garments in the midst hard by their buttocks, and sent them away."}, {"verse": 5, "start": 71.11, "end": 90.43, "ta": "அந்த மனுஷர் வருகையில், அவர்கள் செய்தி தாவீதுக்கு அறிவிக்கப்பட்டது; அப்பொழுது அந்த மனுஷர் மிகவும் வெட்கப்பட்டபடியினால், அவர்களுக்கு எதிராக ராஜா ஆட்களை அனுப்பி: உங்கள் தாடி வளருமட்டும் நீங்கள் எரிகோவிலிருந்து பிற்பாடு வாருங்கள் என்று சொல்லச்சொன்னான்.", "en": "Then there went certain , and told David how the men were served. And he sent to meet them: for the men were greatly ashamed. And the king said, Tarry at Jericho until your beards be grown, and then return."}, {"verse": 6, "start": 90.43, "end": 108.9, "ta": "அம்மோன் புத்திரர் தாங்கள் தாவீதுக்கு அருவருப்பானதைக் கண்டபோது, ஆனூனும் அம்மோன் புத்திரரும் மெசொப்பொத்தாமியாவிலும் மாக்கா சோபா என்னும் சீரியரின் தேசத்திலுமிருந்து தங்களுக்கு இரதங்களும் குதிரைவீரரும் கூலிக்கு வரும்படி ஆயிரம்தாலந்து வெள்ளியையும் அனுப்பி,", "en": "And when the children of Ammon saw that they had made themselves odious to David, Hanun and the children of Ammon sent a thousand talents of silver to hire them chariots and horsemen out of Mesopotamia, and out of Syria-maachah, and out of Zobah."}, {"verse": 7, "start": 108.9, "end": 128.44, "ta": "முப்பத்தீராயிரம் இரதங்களையும், மாக்காவின் ராஜாவையும், அவன் ஜனத்தையும் கூலிப்படையாக அழைப்பித்தான்; இவர்கள் வந்து, மேதேபாவுக்கு முன்புறத்திலே பாளயமிறங்கினார்கள்; அம்மோன் புத்திரரும் தங்கள் பட்டணங்களிலிருந்து கூடிக்கொண்டு யுத்தம்பண்ண வந்தார்கள்.", "en": "So they hired thirty and two thousand chariots, and the king of Maachah and his people; who came and pitched before Medeba. And the children of Ammon gathered themselves together from their cities, and came to battle."}, {"verse": 8, "start": 128.44, "end": 135.04, "ta": "அதைத் தாவீது கேட்டபோது, யோவாபையும் பலசாலிகளின் இராணுவம் முழுவதையும் அனுப்பினான்.", "en": "And when David heard of it , he sent Joab, and all the host of the mighty men."}, {"verse": 9, "start": 135.04, "end": 146.25, "ta": "அம்மோன் புத்திரர் புறப்பட்டுவந்து, பட்டணத்து வாசலண்டையில் அணிவகுத்தார்கள்; வந்த ராஜாக்கள் தனித்து வெளியிலே போருக்கு ஆயத்தமாய் நின்றார்கள்.", "en": "And the children of Ammon came out, and put the battle in array before the gate of the city: and the kings that were come were by themselves in the field."}, {"verse": 10, "start": 146.25, "end": 160.47, "ta": "யுத்த இராணுவங்களின் முகப்புத் தனக்கு முன்னும் பின்னும் இருக்கிறதை யோவாப் கண்டு, அவன் இஸ்ரவேலிலே தெரிந்துகொள்ளப்பட்ட அனைவரிலும் ஒரு பங்கைப் பிரித்தெடுத்து, அதைச் சீரியருக்கு எதிராக நிறுத்தி,", "en": "Now when Joab saw that the battle was set against him before and behind, he chose out of all the choice of Israel, and put them in array against the Syrians."}, {"verse": 11, "start": 160.47, "end": 169.53, "ta": "மற்ற ஜனத்தை அம்மோன் புத்திரருக்கு எதிராகப் போருக்கு ஆயத்தப்படுத்தி, தன் சகோதரனாகிய அபிசாயிக்கு ஒப்புவித்து, அவனை நோக்கி:", "en": "And the rest of the people he delivered unto the hand of Abishai his brother, and they set themselves in array against the children of Ammon."}, {"verse": 12, "start": 169.53, "end": 180.73, "ta": "என்னைப்பார்க்கிலும் சீரியர் பலங்கொண்டால் நீ எனக்குத் துணைநில்; உன்னைப்பார்க்கிலும் அம்மோன் புத்திரர் பலங்கொண்டால் நான் உனக்குத் துணைநிற்பேன்.", "en": "And he said, If the Syrians be too strong for me, then thou shalt help me: but if the children of Ammon be too strong for thee, then I will help thee."}, {"verse": 13, "start": 180.73, "end": 193.73, "ta": "தைரியமாயிரு; நாம் நம்முடைய ஜனத்திற்காகவும், நமது தேவனுடைய பட்டணங்களுக்காகவும் திடன்கொண்டிருக்கக்கடவோம்; கர்த்தர் தமது பார்வைக்கு நலமானதைச் செய்வாராக என்றான்.", "en": "Be of good courage, and let us behave ourselves valiantly for our people, and for the cities of our God: and let the LORD do that which is good in his sight."}, {"verse": 14, "start": 193.73, "end": 203.22, "ta": "பின்பு யோவாபும் அவனோடிருந்த ஜனமும் சீரியரோடு யுத்தம்பண்ணச் சேர்ந்தார்கள்; அவர்கள் அவனுக்கு முன்பாக முறிந்தோடினார்கள்.", "en": "So Joab and the people that were with him drew nigh before the Syrians unto the battle; and they fled before him."}, {"verse": 15, "start": 203.22, "end": 217.15, "ta": "சீரியர் முறிந்தோடுகிறதை அம்மோன் புத்திரர் கண்டபோது, அவர்களும் அவன் சகோதரனாகிய அபிசாயிக்கு முன்பாக முறிந்தோடிப் பட்டணத்திற்கு உட்பட்டார்கள்; யோவாப் திரும்ப எருசலேமுக்கு வந்தான்.", "en": "And when the children of Ammon saw that the Syrians were fled, they likewise fled before Abishai his brother, and entered into the city. Then Joab came to Jerusalem."}, {"verse": 16, "start": 217.15, "end": 232.17, "ta": "தாங்கள் இஸ்ரவேலுக்கு முன்பாக முறிய அடிக்கப்பட்டதைக் கண்டபோது, அவர்கள் நதிக்கு அப்புறத்திலிருக்கிற சீரியரை வரவழைத்தார்கள்; ஆதாரேசரின் படைத்தலைவனாகிய சோப்பாக் அவர்களுக்கு முன்னாலே நடந்துபோனான்.", "en": "And when the Syrians saw that they were put to the worse before Israel, they sent messengers, and drew forth the Syrians that were beyond the river: and Shophach the captain of the host of Hadarezer went before them."}, {"verse": 17, "start": 232.17, "end": 252.86, "ta": "அது தாவீதுக்கு அறிவிக்கப்பட்டது, அவன் இஸ்ரவேலைக் கூட்டிக்கொண்டு, யோர்தானைக் கடந்து, அவர்களுக்குச் சமீபமாய் வந்தபோது, அவர்களுக்கு எதிராக இராணுவங்களை நிறுத்தினார்கள்; தாவீது சீரியருக்கு எதிராக இராணுவங்களைப் போருக்கு ஆயத்தப்படுத்தினபின் அவனோடு யுத்தம்பண்ணினார்கள்.", "en": "And it was told David; and he gathered all Israel, and passed over Jordan, and came upon them, and set the battle in array against them. So when David had put the battle in array against the Syrians, they fought with him."}, {"verse": 18, "start": 252.86, "end": 266.65, "ta": "சீரியர் இஸ்ரவேலுக்கு முன்பாக முறிந்தோடினார்கள்; தாவீது சீரியரிலே ஆயிரம் இரதங்களின் மனுஷரையும், நாற்பதினாயிரம் காலாட்களையும் கொன்று, படைத்தலைவனாகிய சோப்பாக்கையும் கொன்றான்.", "en": "But the Syrians fled before Israel; and David slew of the Syrians seven thousand men which fought in chariots, and forty thousand footmen, and killed Shophach the captain of the host."}, {"verse": 19, "start": 266.65, "end": 282.38, "ta": "தாங்கள் இஸ்ரவேலுக்கு முன்பாகமுறிய அடிக்கப்பட்டதை ஆதாரேசரின் சேவகர் கண்டபோது அவர்கள் தாவீதோடே சமாதானம்பண்ணி, அவனைச் சேவித்தார்கள்; அப்புறம் அம்மோன் புத்திரருக்கு உதவிசெய்ய சீரியர் மனதில்லாதிருந்தார்கள்.", "en": "And when the servants of Hadarezer saw that they were put to the worse before Israel, they made peace with David, and became his servants: neither would the Syrians help the children of Ammon any more."}]}, "20": {"chapter": 20, "duration": 131.32, "audio_url": "audio_ot/OT13_20.mp3", "total_verses": 8, "verses": [{"verse": 1, "start": 3.8, "end": 26.36, "ta": "மறுவருஷம், ராஜாக்கள் யுத்தத்திற்குப் புறப்படும் காலம் வந்தபோது, யோவாப் இராணுவபலத்தைக் கூட்டிக்கொண்டுபோய், அம்மோன் புத்திரரின்தேசத்தைப் பாழ்க்கடித்து ரப்பாவுக்குவந்து அதை முற்றிக்கைபோட்டான்; தாவீதோ எருசலேமில் இருந்துவிட்டான்; யோவாப் ரப்பாவை அடித்துச் சங்கரித்தான்.", "en": "And it came to pass, that after the year was expired, at the time that kings go out to battle , Joab led forth the power of the army, and wasted the country of the children of Ammon, and came and besieged Rabbah. But David tarried at Jerusalem. And Joab smote Rabbah, and destroyed it."}, {"verse": 2, "start": 26.36, "end": 45.99, "ta": "தாவீது வந்து, அவர்கள் ராஜாவுடைய தலையின்மேல் இருந்த கிரீடத்தை எடுத்துக்கொண்டான்; அது ஒரு தாலந்து நிறையும் ரத்தினங்கள் பதித்ததுமாயிருந்தது; அது தாவீதின்தலையில் வைக்கப்பட்டது; பட்டணத்திலிருந்து ஏராளமான கொள்ளையையும் கொண்டுபோனான்.", "en": "And David took the crown of their king from off his head, and found it to weigh a talent of gold, and there were precious stones in it; and it was set upon David’s head: and he brought also exceeding much spoil out of the city."}, {"verse": 3, "start": 45.99, "end": 66.16, "ta": "பின்பு அதிலிருந்த ஜனங்களை அவன் வெளியே கொண்டுபோய், அவர்களை வாள்களுக்கும், இருப்புப்பாரைகளுக்கும், கோடரிகளுக்கும் உட்படுத்தி; இப்படி அம்மோன் புத்திரரின் பட்டணங்களுக்கெல்லாம் தாவீது செய்து, எல்லா ஜனத்தோடுங்கூட எருசலேமுக்குத் திரும்பினான்.", "en": "And he brought out the people that were in it, and cut them with saws, and with harrows of iron, and with axes. Even so dealt David with all the cities of the children of Ammon. And David and all the people returned to Jerusalem."}, {"verse": 4, "start": 66.16, "end": 82.17, "ta": "அதற்குப்பின்பு கேசேரிலே பெலிஸ்தரோடு யுத்தம் உண்டாயிற்று; அப்பொழுது சாத்தியனாகிய சிபெக்காய் இராட்சத புத்திரரில் ஒருவனான சிப்பாயி என்பவனைக் கொன்றான்; அதினால் அவர்கள் வசப்படுத்தப்பட்டார்கள்.", "en": "And it came to pass after this, that there arose war at Gezer with the Philistines; at which time Sibbechai the Hushathite slew Sippai, that was of the children of the giant: and they were subdued."}, {"verse": 5, "start": 82.17, "end": 98.87, "ta": "திரும்பப் பெலிஸ்தரோடு யுத்தமுண்டாகிறபோது, யாவீரின் குமாரனாகிய எல்க்கானான் காத்தூரானாகிய கோலியாத்தின் சகோதரனான லாகேமியைக் கொன்றான்; அவன் ஈட்டித் தாங்கு நெய்கிறவர்களின் படைமரம் அவ்வளவு பெரிதாயிருந்தது.", "en": "And there was war again with the Philistines; and Elhanan the son of Jair slew Lahmi the brother of Goliath the Gittite, whose spear staff was like a weaver’s beam."}, {"verse": 6, "start": 98.87, "end": 113.11, "ta": "மறுபடியும் ஒரு யுத்தம் காத்திலே நடந்தபோது, அங்கே நெட்டையனான ஒரு மனுஷன் இருந்தான்; அவனுக்கு அவ்வாறு விரலாக இருபத்துநாலு விரல்கள் இருந்தது, அவனும் இராட்சத சந்ததியாயிருந்து,", "en": "And yet again there was war at Gath, where was a man of great stature, whose fingers and toes were four and twenty, six on each hand , and six on each foot: and he also was the son of the giant."}, {"verse": 7, "start": 113.11, "end": 121.04, "ta": "இஸ்ரவேலை நிந்தித்தான்; தாவீதின் சகோதரனாகிய சிமேயாவின் குமாரன் யோனத்தான் அவனைக் கொன்றான்.", "en": "But when he defied Israel, Jonathan the son of Shimea David’s brother slew him."}, {"verse": 8, "start": 121.04, "end": 129.82, "ta": "காத்தூரிலிருந்த இராட்சதனுக்குப் பிறந்த இவர்கள் தாவீதின் கையினாலும் அவன் சேவகரின் கையினாலும் மடிந்தார்கள்.", "en": "These were born unto the giant in Gath; and they fell by the hand of David, and by the hand of his servants."}]}, "21": {"chapter": 21, "duration": 412.58, "audio_url": "audio_ot/OT13_21.mp3", "total_verses": 30, "verses": [{"verse": 1, "start": 3.8, "end": 11.14, "ta": "சாத்தான் இஸ்ரவேலுக்கு விரோதமாய் எழும்பி, இஸ்ரவேலைத் தொகையிடுகிறதற்குத் தாவீதை ஏவிவிட்டது.", "en": "And Satan stood up against Israel, and provoked David to number Israel."}, {"verse": 2, "start": 11.14, "end": 27.94, "ta": "அப்படியே தாவீது யோவாபையும், ஜனத்தின் சேர்வைக்காரரையும் நோக்கி: நீங்கள் போய், பெயெர்செபாதொடங்கித் தாண்மட்டும் இருக்கிற இஸ்ரவேலை எண்ணி, அவர்கள் இலக்கத்தை நான் அறியும்படிக்கு, என்னிடத்தில் கொண்டுவாருங்கள் என்றான்.", "en": "And David said to Joab and to the rulers of the people, Go, number Israel from Beer-sheba even to Dan; and bring the number of them to me, that I may know it ."}, {"verse": 3, "start": 27.94, "end": 50.7, "ta": "அப்பொழுது யோவாப் கர்த்தருடைய ஜனங்கள் இப்போது இருக்கிறதைப்பார்க்கிலும் நூறத்தனையாய் அவர் வர்த்திக்கப்பண்ணுவாராக; ஆனாலும் ராஜாவாகிய என் ஆண்டவனே, அவர்களெல்லாரும் என் ஆண்டவனின் சேவகரல்லவா? என் ஆண்டவன் இதை விசாரிப்பானேன்? இஸ்ரவேலின்மேல் குற்றமுண்டாக இது நடக்கவேண்டியது என்ன என்றான்.", "en": "And Joab answered, The LORD make his people an hundred times so many more as they be: but, my lord the king, are they not all my lord’s servants? why then doth my lord require this thing? why will he be a cause of trespass to Israel?"}, {"verse": 4, "start": 50.7, "end": 61.46, "ta": "யோவாப் அப்படிச் சொல்லியும், ராஜாவின் வார்த்தை மேலிட்டபடியினால், யோவாப் புறப்பட்டு, இஸ்ரவேல் எங்கும் சுற்றித்திரிந்து எருசலேமுக்கு வந்து,", "en": "Nevertheless the king’s word prevailed against Joab. Wherefore Joab departed, and went throughout all Israel, and came to Jerusalem."}, {"verse": 5, "start": 61.46, "end": 77.68, "ta": "ஜனத்தை இலக்கம்பார்த்து, தொகையைத் தாவீதிடத்தில் கொடுத்தான்; இஸ்ரவேலிலெல்லாம் பட்டயம் உருவத்தக்கவர்கள் பதினொருலட்சம்பேரும், யூதாவில் பட்டயம் உருவத்தக்கவர்கள் நாலுலட்சத்து எழுபதினாயிரம்பேரும் இருந்தார்கள்.", "en": "And Joab gave the sum of the number of the people unto David. And all they of Israel were a thousand thousand and an hundred thousand men that drew sword: and Judah was four hundred threescore and ten thousand men that drew sword."}, {"verse": 6, "start": 77.68, "end": 89.17, "ta": "ஆனாலும் ராஜாவின் வார்த்தை யோவாபுக்கு அருவருப்பாயிருந்தபடியினால், லேவி பென்யமீன் கோத்திங்களிலுள்ளவர்களை அவர்களுடைய இலக்கத்திற்குட்பட எண்ணாதேபோனான்.", "en": "But Levi and Benjamin counted he not among them: for the king’s word was abominable to Joab."}, {"verse": 7, "start": 89.17, "end": 95.42, "ta": "இந்தக் காரியம் தேவனுடைய பார்வைக்கு ஆகாததானபடியினால் அவர் இஸ்ரவேலை வாதித்தார்.", "en": "And God was displeased with this thing; therefore he smote Israel. concerning this thing"}, {"verse": 8, "start": 95.42, "end": 109.53, "ta": "தாவீது தேவனை நோக்கி: நான் இந்தக் காரியத்தைச் செய்ததினால் மிகவும் பாவஞ்செய்தேன்; இப்போதும் உம்முடைய அடியேனின் அக்கிரமத்தை நீக்கிவிடும்; வெகு புத்தியீனமாய்ச் செய்தேன் என்றான்.", "en": "And David said unto God, I have sinned greatly, because I have done this thing: but now, I beseech thee, do away the iniquity of thy servant; for I have done very foolishly."}, {"verse": 9, "start": 109.53, "end": 114.76, "ta": "அப்பொழுது கர்த்தர், தாவீதின் ஞானதிருஷ்டிக்காரனாகிய காத்துடனே பேசி,", "en": "And the LORD spake unto Gad, David’s seer, saying,"}, {"verse": 10, "start": 114.76, "end": 129.38, "ta": "நீ தாவீதினிடத்தில் போய் மூன்று காரியங்களை உனக்கு முன்பாக வைக்கிறேன்; அவைகளில் ஒரு காரியத்தைத் தெரிந்துகொள்; அதை நான் உனக்குச்செய்வேன் என்று கர்த்தர் உரைக்கிறார் என்று சொல் என்றார்.", "en": "Go and tell David, saying, Thus saith the LORD , I offer thee three things: choose thee one of them, that I may do it unto thee."}, {"verse": 11, "start": 129.38, "end": 133.16, "ta": "அப்படியே காத் தாவீதினிடத்தில் வந்து, அவனை நோக்கி:", "en": "So Gad came to David, and said unto him, Thus saith the LORD , Choose thee"}, {"verse": 12, "start": 133.16, "end": 169.37, "ta": "மூன்று வருஷத்துப் பஞ்சமோ? அல்லது உன் பகைஞரின் பட்டயம் உன்னைப் பின்தொடர நீ உன் சத்துருக்களுக்கு முன்பாக முறிந்தோடிப்போகச் செய்யும் மூன்று மாதச் சங்காரமோ? அல்லது மூன்றுநாள் கர்த்தருடைய தூதன் இஸ்ரவேலுடைய எல்லையெங்கும் சங்காரம் உண்டாகும்படி தேசத்தில் நிற்கும் கர்த்தருடைய பட்டயமாகிய கொள்ளை நோயோ? இவைகளில் ஒன்றைத் தெரிந்துகொள் என்று கர்த்தர் உரைக்கிறார். இப்போதும் என்னை அனுப்பினவருக்கு நான் என்ன மறுஉத்தரவு கொண்டுபோகவேண்டும் என்பதை யோசித்துப்பாரும் என்றான்.", "en": "Either three years’ famine; or three months to be destroyed before thy foes, while that the sword of thine enemies overtaketh thee; or else three days the sword of the LORD , even the pestilence, in the land, and the angel of the LORD destroying throughout all the coasts of Israel. Now therefore advise thyself what word I shall bring again to him that sent me."}, {"verse": 13, "start": 169.37, "end": 184.79, "ta": "அப்பொழுது தாவீது கர்த்தரை நோக்கி: கொடிய இடுக்கணில் அகப்பட்டிருக்கிறேன்; இப்போது நான் கர்த்தருடைய கையிலே விழுவேனாக; அவருடைய இரக்கங்கள் மகா பெரியது; மனுஷர் கையிலே விழாதிருப்பேனாக என்றான்.", "en": "And David said unto Gad, I am in a great strait: let me fall now into the hand of the LORD ; for very great are his mercies: but let me not fall into the hand of man."}, {"verse": 14, "start": 184.79, "end": 193.22, "ta": "ஆகையால் கர்த்தர் இஸ்ரவேலிலே கொள்ளைநோயை வரப்பண்ணினார், அதினால் இஸ்ரவேலில் எழுபதினாயிரம்பேர் மடிந்தார்கள்.", "en": "So the LORD sent pestilence upon Israel: and there fell of Israel seventy thousand men."}, {"verse": 15, "start": 193.22, "end": 214.6, "ta": "எருசலேமையும் அழிக்க தேவன் ஒரு தூதனை அனுப்பினான்; ஆனாலும் ஒருவன் அழிக்கையில் கர்த்தர் பார்த்து, அந்தத் தீங்குக்கு மனஸ்தாபப்பட்டு, சங்கரிக்கிற தூதனை நோக்கி: போதும்; இப்போது உன் கையை நிறுத்து என்றார்; கர்த்தருடைய தூதன் எபூசியனாகிய ஒர்னானின் களத்தண்டையிலே நின்றான்.", "en": "And God sent an angel unto Jerusalem to destroy it: and as he was destroying, the LORD beheld, and he repented him of the evil, and said to the angel that destroyed, It is enough, stay now thine hand. And the angel of the LORD stood by the threshingfloor of Ornan the Jebusite."}, {"verse": 16, "start": 214.6, "end": 234.67, "ta": "தாவீது தன் கண்களை ஏறெடுத்து, பூமிக்கும் வானத்திற்கும் நடுவே நிற்கிற கர்த்தருடைய தூதன் உருவின பட்டயத்தைத் தன் கையில் பிடித்து, அதை எருசலேமின்மேல் நீட்டியிருக்கக் கண்டான்; அப்பொழுது தாவீதும் மூப்பர்களும் இரட்டுப் போர்த்துக்கொண்டு முகங்குப்புற விழுந்தார்கள்.", "en": "And David lifted up his eyes, and saw the angel of the LORD stand between the earth and the heaven, having a drawn sword in his hand stretched out over Jerusalem. Then David and the elders of Israel, who were clothed in sackcloth, fell upon their faces."}, {"verse": 17, "start": 234.67, "end": 258.3, "ta": "தாவீது தேவனை நோக்கி: ஜனத்தை எண்ணச் சொன்னவன் நான் அல்லவோ? நான்தான் பாவஞ்செய்தேன்; பொல்லாப͠Ϊு நடப்பிĠύதேன்; இந்த ஆடுகள் என்ன செய்ĠΤு? என் தேவனாகிய கர்த்தாவே, வாதிக்கும்படி உம்முடைய கரம் உம்முடைய ஜனத்திற்கு விரோதமாயிராமல், எனக்கும் என் தகப்பன் வீட்டிற்கும் விரோதமாயிருப்பதாக என்றான்.", "en": "And David said unto God, Is it not I that commanded the people to be numbered? even I it is that have sinned and done evil indeed; but as for these sheep, what have they done? let thine hand, I pray thee, O LORD my God, be on me, and on my father’s house; but not on thy people, that they should be plagued."}, {"verse": 18, "start": 258.3, "end": 272.56, "ta": "அப்பொழுது எபூசியனாகிய ஒர்னானின் களத்திலே கர்த்தருக்கு ஒரு பலிபீடத்தை உண்டாக்கும்படி, தாவீது அங்கே போகவேண்டுமென்று தாவீதுக்குச் சொல் என்று கர்த்தருடைய தூதன் காத்துக்குக் கட்டளையிட்டான்.", "en": "Then the angel of the LORD commanded Gad to say to David, that David should go up, and set up an altar unto the LORD in the threshingfloor of Ornan the Jebusite."}, {"verse": 19, "start": 272.56, "end": 278.52, "ta": "அப்படியே தாவீது கர்த்தரின் நாமத்திலே காத் சொன்ன வார்த்தையின்படியே போனான்.", "en": "And David went up at the saying of Gad, which he spake in the name of the LORD ."}, {"verse": 20, "start": 278.52, "end": 291.1, "ta": "ஒர்னான் திரும்பிப்பார்த்தான்; அவனும் அவனோடிருக்கிற அவனுடைய நாலு குமாரரும் அந்த தேவதூதனைக் கண்டு ஒளித்துக்கொண்டார்கள்; ஒர்னான் போரடித்துக்கொண்டிருந்தான்.", "en": "And Ornan turned back, and saw the angel; and his four sons with him hid themselves. Now Ornan was threshing wheat."}, {"verse": 21, "start": 291.1, "end": 302.66, "ta": "தாவீது ஒர்னானிடத்தில் வந்தபோது ஒர்னான் கவனித்துத் தாவீதைப் பார்த்து, அவன் களத்திலிருந்து புறப்பட்டுவந்து, தரைமட்டும் குனிந்து தாவீதை வணங்கினான்.", "en": "And as David came to Ornan, Ornan looked and saw David, and went out of the threshingfloor, and bowed himself to David with his face to the ground."}, {"verse": 22, "start": 302.66, "end": 318.37, "ta": "அப்பொழுது தாவீது ஒர்னானை நோக்கி: இந்தக் களத்தின் நிலத்திலே நான் கர்த்தருக்கு ஒரு பலிபீடத்தைக் கட்டும்படிக்கு அதை எனக்குக் கொடு; ஜனத்தைவிட்டு நிறுத்தப்பட, எனக்கு அதைப் பெறும் விலைக்குக் கொடு என்றான்.", "en": "Then David said to Ornan, Grant me the place of this threshingfloor, that I may build an altar therein unto the LORD : thou shalt grant it me for the full price: that the plague may be stayed from the people."}, {"verse": 23, "start": 318.37, "end": 337.56, "ta": "ஒர்னான் தாவீதை நோக்கி: ராஜாவாகிய என் ஆண்டவன் அதை வாங்கிக்கொண்டு, தம்முடைய பார்வைக்கு நலமானபடி செய்வாராக; இதோ, சர்வாங்கதகனங்களுக்கு மாடுகளும், விறகுக்குப் போரடிக்கிற உருளைகளும், போஜனபலிக்குக் கோதுமையும் ஆகிய யாவையும் கொடுக்கிறேன் என்றான்.", "en": "And Ornan said unto David, Take it to thee, and let my lord the king do that which is good in his eyes: lo, I give thee the oxen also for burnt offerings, and the threshing instruments for wood, and the wheat for the meat offering; I give it all."}, {"verse": 24, "start": 337.56, "end": 350.87, "ta": "அதற்குத் தாவீதுராஜா ஒர்னானை நோக்கி: அப்படியல்ல, நான் உன்னுடையதை இலவசமாய் வாங்கி, கர்த்தருக்குச் சர்வாங்க தகனத்தைப் பலியிடாமல், அதை பெறும் விலைக்கு வாங்குவேன் என்று சொல்லி,", "en": "And king David said to Ornan, Nay; but I will verily buy it for the full price: for I will not take that which is thine for the LORD , nor offer burnt offerings without cost."}, {"verse": 25, "start": 350.87, "end": 356.76, "ta": "தாவீது அந்த நிலத்திற்கு அறுநூறு சேக்கல் நிறைபொன்னை ஒர்னானுக்குக்குக் கொடுத்து,", "en": "So David gave to Ornan for the place six hundred shekels of gold by weight."}, {"verse": 26, "start": 356.76, "end": 375.96, "ta": "அங்கே கர்த்தருக்கு ஒரு பலிபீடத்தைக் கட்டி, சர்வாங்க தகனபலிகளையும் சமாதான பலிகளையும் செலுத்தி, கர்த்தரை நோக்கி விண்ணப்பம்பண்ணினான்; அப்பொழுது அவர் வானத்திலிருந்து சர்வாங்க தகனபலிபீடத்தின்மேல் இறங்கின அக்கினியில் அவனுக்கு மறுஉத்தரவு கொடுத்ததுமல்லாமல்,", "en": "And David built there an altar unto the LORD , and offered burnt offerings and peace offerings, and called upon the LORD ; and he answered him from heaven by fire upon the altar of burnt offering."}, {"verse": 27, "start": 375.96, "end": 383.38, "ta": "தேவதூதன் தன்னுடைய பட்டயத்தை உறையிலே திரும்பப் போடவேண்டும் என்று கர்த்தர் அவனுக்குச் சொன்னார்.", "en": "And the LORD commanded the angel; and he put up his sword again into the sheath thereof."}, {"verse": 28, "start": 383.38, "end": 392.61, "ta": "எபூசியனாகிய ஒர்னானின் களத்திலே கர்த்தர் தனக்கு உத்தரவு அருளினதைத் தாவீது அக்காலத்திலே, கண்டு அங்கேதானே பலியிட்டான்.", "en": "At that time when David saw that the LORD had answered him in the threshingfloor of Ornan the Jebusite, then he sacrificed there."}, {"verse": 29, "start": 392.61, "end": 401.92, "ta": "மோசே வனாந்தரத்தில் உண்டாக்கின கர்த்தருடைய வாசஸ்தலமும் சர்வாங்க தகனபலிபீடமும் அக்காலத்திலே கிபியோனின் மேட்டில் இருந்தது.", "en": "For the tabernacle of the LORD , which Moses made in the wilderness, and the altar of the burnt offering, were at that season in the high place at Gibeon."}, {"verse": 30, "start": 401.92, "end": 411.08, "ta": "தாவீது கர்த்தருடைய தூதனின் பட்டயத்திற்குப் பயந்திருந்தபடியால், அவன் தேவசந்நிதியில் போய் விசாரிக்கக் கூடாதிருந்தது.", "en": "But David could not go before it to enquire of God: for he was afraid because of the sword of the angel of the LORD ."}]}, "22": {"chapter": 22, "duration": 288.17, "audio_url": "audio_ot/OT13_22.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 15.39, "ta": "அப்பொழுது தாவீது: தேவனாகிய கர்த்தருடைய ஆலயம் இருக்கும் ஸ்தலம் இதுவே; இஸ்ரவேல் பலியிடும் சர்வாங்கதகனபலிபீடம் இருக்கும் ஸ்தலமும் இதுவே என்றான்.", "en": "Then David said, This is the house of the LORD God, and this is the altar of the burnt offering for Israel."}, {"verse": 2, "start": 15.39, "end": 28.54, "ta": "பின்பு தாவீது இஸ்ரவேல் தேசத்திலிருக்கிற அந்நியஜாதியாரைக் கூடிவரச்செய்து, தேவனுடைய ஆலயத்தைக் கட்டுகிறதற்கான கல்லுகளை வெட்டிப் பணிப்படுத்தும் கல்தச்சரை ஏற்படுத்தினான்.", "en": "And David commanded to gather together the strangers that were in the land of Israel; and he set masons to hew wrought stones to build the house of God."}, {"verse": 3, "start": 28.54, "end": 38.49, "ta": "தாவீது வாசல்களின் கதவுகளுக்கு வேண்டிய ஆணிகளுக்கும் கீல்களுக்கும் மிகுதியான இரும்பையும், நிறுத்து முடியாத ஏராளமான வெண்கலத்தையும்,", "en": "And David prepared iron in abundance for the nails for the doors of the gates, and for the joinings; and brass in abundance without weight;"}, {"verse": 4, "start": 38.49, "end": 48.37, "ta": "எண்ணிறந்த கேதுருமரங்களையும் சம்பாதித்தான்; சீதோனியரும் தீரியரும் தாவீதுக்குத் திரளான கேதுருமரங்களைக் கொண்டுவந்தார்கள்.", "en": "Also cedar trees in abundance: for the Zidonians and they of Tyre brought much cedar wood to David."}, {"verse": 5, "start": 48.37, "end": 73.7, "ta": "தாவீது: என் குமாரனாகிய சாலொமோன் வாலிபனும் இளைஞனுமாயிருக்கிறான்; கர்த்தருக்குக் கட்டப்படும் ஆலயம் சகல தேசங்களிலும் கீர்த்தியும் மகிமையும் உடையதாய் விளங்கும்படி மகா பெரியதாயிருக்கவேண்டும்; ஆகையால் அதற்காக வேண்டியவைகளை இப்பொழுதே சேகரம்பண்ணவேண்டும் என்று சொல்லி, தாவீது தன் மரணத்திற்கு முன்னே திரளாய்ச் சவதரித்துவைத்தான்.", "en": "And David said, Solomon my son is young and tender, and the house that is to be builded for the LORD must be exceeding magnifical, of fame and of glory throughout all countries: I will therefore now make preparation for it. So David prepared abundantly before his death."}, {"verse": 6, "start": 73.7, "end": 83.06, "ta": "அவன் தன் குமாரனாகிய சாலொமோனை அழைத்து, இஸ்ரவேலின் தேவனாகிய கர்த்தருக்கு ஆலயத்தைக் கட்டுகிறதற்காக அவனுக்கு கட்டளைகொடுத்து,", "en": "Then he called for Solomon his son, and charged him to build an house for the LORD God of Israel."}, {"verse": 7, "start": 83.06, "end": 93.09, "ta": "சாலொமோனை நோக்கி: என் குமாரனே, நான் என் தேவனாகிய கர்த்தரின் நாமத்திற்கு ஒரு ஆலயத்தைக் கட்ட என் இருதயத்தில் நினைத்திருந்தேன்.", "en": "And David said to Solomon, My son, as for me, it was in my mind to build an house unto the name of the LORD my God:"}, {"verse": 8, "start": 93.09, "end": 110.25, "ta": "ஆனாலும் கர்த்தருடைய வார்த்தை எனக்கு உண்டாகி: நீ திரளான இரத்தத்தைச் சிந்தி, பெரிய யுத்தங்களைப் பண்ணினாய்; என் நாமத்திற்கு ஆலயத்தைக் கட்டவேண்டாம்; எனக்கு முன்பாக மிகுதியான இரத்தத்தைத் தரையிலே சிந்தப்பண்ணினாய்.", "en": "But the word of the LORD came to me, saying, Thou hast shed blood abundantly, and hast made great wars: thou shalt not build an house unto my name, because thou hast shed much blood upon the earth in my sight."}, {"verse": 9, "start": 110.25, "end": 131.49, "ta": "இதோ, உனக்குப் பிறக்கப்போகிற குமாரன் அமைதியுள்ள புருஷனாயிருப்பான்; சுற்றிலுமிருக்கும் அவன் சத்துருக்களையெல்லாம் விலக்கி அவனை அமர்ந்திருக்கச் செய்வேன்; ஆகையால் அவன்பேர் சாலொமோன் என்னப்படும், அவன் நாட்களில் இஸ்ரவேலின்மேல் சமாதானத்தையும் அமரிக்கையையும் அருளுவான்.", "en": "Behold, a son shall be born to thee, who shall be a man of rest; and I will give him rest from all his enemies round about: for his name shall be Solomon, and I will give peace and quietness unto Israel in his days."}, {"verse": 10, "start": 131.49, "end": 148.21, "ta": "அவன் என் நாமத்திற்கு ஆலயத்தைக் கட்டுவான்; அவன் எனக்குக் குமாரனாயிருப்பான், நான் அவனுக்குப் பிதாவாயிருப்பேன்; இஸ்ரவேலை ஆளும் அவனுடைய ராஜாங்கத்தின் சிங்காசனத்தை என்றென்றைக்கும் நிலைப்படுத்துவேன் என்றார்.", "en": "He shall build an house for my name; and he shall be my son, and I will be his father; and I will establish the throne of his kingdom over Israel for ever."}, {"verse": 11, "start": 148.21, "end": 161.43, "ta": "இப்போதும் என் குமாரனே, நீ பாக்கியவானாயிருந்து, கர்த்தர் உன்னைக் குறித்துச் சொன்னபடியே உன் தேவனாகிய கர்த்தரின் ஆலயத்தைக் கட்டும்படி, அவர் உன்னுடனேகூட இருப்பாராக.", "en": "Now, my son, the LORD be with thee; and prosper thou, and build the house of the LORD thy God, as he hath said of thee."}, {"verse": 12, "start": 161.43, "end": 173.91, "ta": "கர்த்தர் உனக்கு ஞானத்தையும் உணர்வையும் அருளிச்செய்து, உன் தேவனாகிய கர்த்தரின் நியாயப்பிரமாணத்தைக் கைக்கொண்டு, இஸ்ரவேலை ஆளும்படி உனக்குக் கட்டளையிடுவாராக.", "en": "Only the LORD give thee wisdom and understanding, and give thee charge concerning Israel, that thou mayest keep the law of the LORD thy God."}, {"verse": 13, "start": 173.91, "end": 188.32, "ta": "கர்த்தர் இஸ்ரவேலுக்காக மோசேக்குக் கற்பித்த நியமங்களையும் நியாயங்களையும் செய்ய நீ கவனமாயிருந்தால் பாக்கியவானாயிருப்பாய்; நீ பலங்கொண்டு தைரியமாயிரு, பயப்படாமலும் கலங்காமலும் இரு.", "en": "Then shalt thou prosper, if thou takest heed to fulfil the statutes and judgments which the LORD charged Moses with concerning Israel: be strong, and of good courage; dread not, nor be dismayed."}, {"verse": 14, "start": 188.32, "end": 209.79, "ta": "இதோ, நான் என் சிறுமையிலே கர்த்தருடைய ஆலயத்திற்காக ஒரு லட்சம் தாலந்து பொன்னையும், பத்துலட்சம் தாலந்து வெள்ளியையும் நிறுத்து முடியாத திரளான வெண்கலத்தையும் இரும்பையும் சவதரித்தும், மரங்களையும் கற்களையும் சவதரித்தும் வைத்தேன், நீ இன்னும் அவைகளுக்கு அதிகமாய்ச் சவதரிப்பாய்.", "en": "Now, behold, in my trouble I have prepared for the house of the LORD an hundred thousand talents of gold, and a thousand thousand talents of silver; and of brass and iron without weight; for it is in abundance: timber also and stone have I prepared; and thou mayest add thereto."}, {"verse": 15, "start": 209.79, "end": 219.22, "ta": "வேலைசெய்யத்தக்க திரளான சிற்பாசாரிகளும், தச்சரும் கல்தச்சரும் எந்த வேலையிலும் நிபுணரானவர்களும் உன்னோடிருக்கிறார்கள்.", "en": "Moreover there are workmen with thee in abundance, hewers and workers of stone and timber, and all manner of cunning men for every manner of work."}, {"verse": 16, "start": 219.22, "end": 231.77, "ta": "பொன்னுக்கும், வெள்ளிக்கும், வெண்கலத்துக்கும், இரும்புக்கும் கணக்கில்லை; நீ எழும்பிக் காரியத்தை நடப்பி; கர்த்தர் உன்னோடே இருப்பாராக என்றான்.", "en": "Of the gold, the silver, and the brass, and the iron, there is no number. Arise therefore , and be doing, and the LORD be with thee."}, {"verse": 17, "start": 231.77, "end": 240.17, "ta": "தன் குமாரனாகிய சாலொமோனுக்கு உதவிசெய்ய, தாவீது இஸ்ரவேலின் பிரபுக்கள் அனைவருக்கும் கற்பித்துச் சொன்னது.", "en": "David also commanded all the princes of Israel to help Solomon his son, saying ,"}, {"verse": 18, "start": 240.17, "end": 259.41, "ta": "உங்கள் தேவனாகிய கர்த்தர் உங்களோடிருந்து நான்கு திசையிலும் உங்களுக்கு இளைப்பாறுதலைத் தந்தார் அல்லவா? தேசத்தின் குடிகளை என் கையில் ஒப்புக்கொடுத்தார்; கர்த்தருக்கு முன்பாகவும், அவருடைய ஜனத்திற்கு முன்பாகவும் தேசம் கீழ்ப்பட்டிருக்கிறது.", "en": "Is not the LORD your God with you? and hath he not given you rest on every side? for he hath given the inhabitants of the land into mine hand; and the land is subdued before the LORD , and before his people."}, {"verse": 19, "start": 259.41, "end": 286.67, "ta": "இப்போதும் நீங்கள் உங்கள் இருதயத்தையும், உங்கள் ஆத்துமத்தையும், உங்கள் தேவனாகிய கர்த்தரைத் தேடுகிறதற்கு நேராக்கி, கர்த்தருடைய உடன்படிக்கைப் பெட்டியையும் தேவனுடைய பரிசுத்தப் பணிமுட்டுகளையும், கர்த்தருடைய நாமத்திற்குக் கட்டப்படும் அந்த ஆலயத்திற்குள் கொண்டுபோகும்படிக்கு நீங்கள் எழும்பி, தேவனாகிய கர்த்தரின் பரிசுத்த ஸ்தலத்தைக் கட்டுங்கள் என்றான்.", "en": "Now set your heart and your soul to seek the LORD your God; arise therefore, and build ye the sanctuary of the LORD God, to bring the ark of the covenant of the LORD , and the holy vessels of God, into the house that is to be built to the name of the LORD ."}]}, "23": {"chapter": 23, "duration": 342.98, "audio_url": "audio_ot/OT13_23.mp3", "total_verses": 32, "verses": [{"verse": 1, "start": 3.8, "end": 11.87, "ta": "தாவீது கிழவனும் பூரண வயதுள்ளவனுமானபோது, தன் குமாரனாகிய சாலொமோனை இஸ்ரவேலின்மேல் ராஜாவாக்கினான்.", "en": "So when David was old and full of days, he made Solomon his son king over Israel."}, {"verse": 2, "start": 11.87, "end": 19.34, "ta": "இஸ்ரவேலின் எல்லாப் பிரபுக்களையும், ஆசாரியரையும், லேவியரையும் கூடிவரும்படி செய்தான்.", "en": "And he gathered together all the princes of Israel, with the priests and the Levites."}, {"verse": 3, "start": 19.34, "end": 30.84, "ta": "அப்பொழுது முப்பது வயதுமுதல் அதற்கு மேற்பட்ட லேவியர் பேர்பேராக எண்ணப்பட்டார்கள், தலைதலையாக எண்ணப்பட்ட அவர்களுடைய இலக்கம் முப்பத்தெண்ணாயிரம்.", "en": "Now the Levites were numbered from the age of thirty years and upward: and their number by their polls, man by man, was thirty and eight thousand."}, {"verse": 4, "start": 30.84, "end": 41.89, "ta": "அவர்களில் இருபத்துநாலாயிரம்பேர் கர்த்தருடைய ஆலயத்தின் வேலையை விசாரிக்கிறவர்களும், ஆறாயிரம்பேர் தலைவரும் மணியகாரருமாயிருக்கவேண்டும் என்றும்,", "en": "Of which, twenty and four thousand were to set forward the work of the house of the LORD ; and six thousand were officers and judges:"}, {"verse": 5, "start": 41.89, "end": 56.74, "ta": "நாலாயிரம்பேர் வாசல் காக்கிறவர்களாயிருக்கவேண்டும் என்றும், துதிசெய்கிறதற்குத் தான் பண்ணுவித்த கீதவாத்தியங்களால் நாலாயிரம்பேர் கர்த்தரைத் துதிக்கிறவர்களாயிருக்கவேண்டும் என்றும் தாவீது சொல்லி,", "en": "Moreover four thousand were porters; and four thousand praised the LORD with the instruments which I made, said David , to praise therewith ."}, {"verse": 6, "start": 56.74, "end": 64.97, "ta": "அவர்களை லேவியின் குமாரராகிய கெர்சோன், கோகாத், மெராரி என்பவர்களுடைய வகுப்புகளின்படி வகுத்தான்.", "en": "And David divided them into courses among the sons of Levi, namely , Gershon, Kohath, and Merari."}, {"verse": 7, "start": 64.97, "end": 69.69, "ta": "கெர்சோனியரில், லாதானும், சிமேயும் இருந்தார்கள்.", "en": "Of the Gershonites were , Laadan, and Shimei."}, {"verse": 8, "start": 69.69, "end": 79.44, "ta": "லாதானின் குமாரர், யெகியேல், சேத்தாம், யோவேல் என்னும் மூன்றுபேர்; இவர்களில் முந்தினவன் தலைமையாயிருந்தான்.", "en": "The sons of Laadan; the chief was Jehiel, and Zetham, and Joel, three."}, {"verse": 9, "start": 79.44, "end": 90.26, "ta": "சிமேயின் குமாரர், செலோமித், ஆசியேல், ஆரான் என்னும் மூன்றுபேர்; இவர்கள் லாதான் வம்சப் பிதாக்களில் தலைமையாயிருந்தார்கள்.", "en": "The sons of Shimei; Shelomith, and Haziel, and Haran, three. These were the chief of the fathers of Laadan."}, {"verse": 10, "start": 90.26, "end": 97.42, "ta": "யகாத், சீனா, எயூஷ், பெரீயா என்னும் நாலுபேரும் சிமேயின் குமாரராயிருந்தார்கள்.", "en": "And the sons of Shimei were , Jahath, Zina, and Jeush, and Beriah. These four were the sons of Shimei."}, {"verse": 11, "start": 97.42, "end": 113.03, "ta": "யாகாத் தலைமையாயிருந்தான்; சீனா இரண்டாம் குமாரனாயிருந்தான்; எயூஷுக்கும் பெரீயாவுக்கும் அநேகம் குமாரர் இராதபடியினால், அவர்கள் பிதாக்களின் குடும்பத்தாரில் ஒரே வம்சமாக எண்ணப்பட்டார்கள்.", "en": "And Jahath was the chief, and Zizah the second: but Jeush and Beriah had not many sons; therefore they were in one reckoning, according to their father’s house."}, {"verse": 12, "start": 113.03, "end": 119.81, "ta": "கோகாத்தின் குமாரர் அம்ராம், இத்சார், எப்ரோன், ஊசியேல் என்னும் நாலுபேர்.", "en": "The sons of Kohath; Amram, Izhar, Hebron, and Uzziel, four."}, {"verse": 13, "start": 119.81, "end": 145.41, "ta": "அம்ராமின் குமாரர், ஆரோன், மோசே என்பவர்கள்; ஆரோனும் அவன் குமாரரும் பரிசுத்தத்திற்குப் பரிசுத்தமான ஸ்தலத்தை என்றைக்கும் பரிசுத்தமாய்க் காக்கிறதற்கும், என்றைக்கும் கர்த்தருக்கு முன்பாக தூபங்காட்டுகிறதற்கும், அவருக்கு ஆராதனை செய்கிறதற்கும், அவர் நாமத்திலே ஆசீர்வாதம் கொடுக்கிறதற்கும் பிரித்துவைக்கப்பட்டார்கள்.", "en": "The sons of Amram; Aaron and Moses: and Aaron was separated, that he should sanctify the most holy things, he and his sons for ever, to burn incense before the LORD , to minister unto him, and to bless in his name for ever."}, {"verse": 14, "start": 145.41, "end": 152.72, "ta": "தேவனுடைய மனுஷனாகிய மோசேயின் குமாரரோவெனில், லேவிகோத்திரத்தாருக்குள் எண்ணப்பட்டார்கள்.", "en": "Now concerning Moses the man of God, his sons were named of the tribe of Levi."}, {"verse": 15, "start": 152.72, "end": 157.29, "ta": "மோசேயின் குமாரர், கெர்சோம், யேசர் என்பவர்கள்.", "en": "The sons of Moses were , Gershom, and Eliezer."}, {"verse": 16, "start": 157.29, "end": 161.63, "ta": "கெர்சோமின் குமாரரில் செபுவேல் தலைமையாயிருந்தான்.", "en": "Of the sons of Gershom, Shebuel was the chief."}, {"verse": 17, "start": 161.63, "end": 173.44, "ta": "எலியேசருடைய குமாரரில் ரெகபியா என்னும் அவன் குமாரன் தலைமையாயிருந்தான்: எலியேசருக்கு வேறே குமாரர் இல்லை, ரெகபியாவின் குமாரர் அநேகராயிருந்தார்கள்.", "en": "And the sons of Eliezer were , Rehabiah the chief. And Eliezer had none other sons; but the sons of Rehabiah were very many."}, {"verse": 18, "start": 173.44, "end": 177.71, "ta": "இத்சேரின் குமாரரில் செலோமித் தலைமையாயிருந்தான்.", "en": "Of the sons of Izhar; Shelomith the chief."}, {"verse": 19, "start": 177.71, "end": 187.61, "ta": "எப்ரோனின் குமாரரில் எரியா என்பவன் தலைமையாயிருந்தான்; இரண்டாவது அமரியா, மூன்றாவது யாகாசியேல் நாலாவது எக்காமியாம்.", "en": "Of the sons of Hebron; Jeriah the first, Amariah the second, Jahaziel the third, and Jekameam the fourth."}, {"verse": 20, "start": 187.61, "end": 193.93, "ta": "ஊசியேலின் குமாரரில் மீகா என்பவன் தலைமையாயிருந்தான்; இரண்டாவது இஷியா.", "en": "Of the sons of Uzziel; Michah the first, and Jesiah the second."}, {"verse": 21, "start": 193.93, "end": 202.84, "ta": "மெராரியின் குமாரர், மகேலி, மூசி என்பவர்கள்; மகேலியின் குமாரர், எலெயாசார், கீஸ் என்பவர்கள்.", "en": "The sons of Merari; Mahli, and Mushi. The sons of Mahli; Eleazar, and Kish."}, {"verse": 22, "start": 202.84, "end": 214.5, "ta": "எயொசார் மரிக்கிறபோது, அவனுக்குக் குமாரத்திகளே அல்லாமல் குமாரர் இல்லை; கீசின் குமாரராகிய இவர்களுடைய சகோதரர் இவர்களை விவாகம்பண்ணினார்கள்.", "en": "And Eleazar died, and had no sons, but daughters: and their brethren the sons of Kish took them."}, {"verse": 23, "start": 214.5, "end": 220.29, "ta": "மூசியின் குமாரர், மகலி, ஏதேர், எரேமோக் என்னும் மூன்றுபேர்.", "en": "The sons of Mushi; Mahli, and Eder, and Jeremoth, three."}, {"verse": 24, "start": 220.29, "end": 238.64, "ta": "தங்கள் பிதாக்களுடைய குடும்பங்களின்படியே, பிதாக்களில் தலைமையாயிருந்த லேவி புத்திரரின் பேர்டாப்பின்படியே, தலைதலையாக எண்ணப்பட்ட இருபது வயதுமுதல் அதற்கு மேற்பட்ட இவர்களுடைய சந்ததியார் கர்த்தருடைய ஆலயத்துப் பணிவிடையைச் செய்தார்கள்.", "en": "These were the sons of Levi after the house of their fathers; even the chief of the fathers, as they were counted by number of names by their polls, that did the work for the service of the house of the LORD , from the age of twenty years and upward."}, {"verse": 25, "start": 238.64, "end": 248.7, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தர் தமது ஜனத்தை இளைப்பாறியிருக்கப்பண்ணினார்; அவர் என்றென்றைக்கும் எருசலேமில் வாசம்பண்ணுவாரென்றும்,", "en": "For David said, The LORD God of Israel hath given rest unto his people, that they may dwell in Jerusalem for ever:"}, {"verse": 26, "start": 248.7, "end": 257.69, "ta": "இனி லேவியர் வாசஸ்தலத்தையாகிலும் அதின் ஊழியத்திற்கடுத்த அதின் பணிமுட்டுகளில் எதையாகிலும் சுமக்கத்தேவையில்லை என்றும்,", "en": "And also unto the Levites; they shall no more carry the tabernacle, nor any vessels of it for the service thereof."}, {"verse": 27, "start": 257.69, "end": 269.88, "ta": "தாவீது அவர்களைக் குறித்துச்சொன்ன கடைசி வார்த்தைகளின்படியே, லேவி புத்திரரில் தொகைக்குட்பட்டவர்கள் இருபதுவயதுமுதல் அதற்கு மேற்பட்டவர்களாயிருந்தார்கள்.", "en": "For by the last words of David the Levites were numbered from twenty years old and above:"}, {"verse": 28, "start": 269.88, "end": 286.94, "ta": "அவர்கள் ஆரோனுடைய குமாரரின் கீழ்க் கர்த்தருடைய ஆலயத்தின் ஊழியமாய் நின்று, பிராகாரங்களையும், அறைகளையும், சகல பரிசுத்த பணிமுட்டுகளின் சுத்திகரிப்பையும், தேவனுடைய ஆலயத்தின் ஆராதனைக்கடுத்த வேலையையும் விசாரிப்பதும்,", "en": "Because their office was to wait on the sons of Aaron for the service of the house of the LORD , in the courts, and in the chambers, and in the purifying of all holy things, and the work of the service of the house of God;"}, {"verse": 29, "start": 286.94, "end": 300.88, "ta": "சமுகத்தப்பங்களையும், போஜனபலிக்கு மெல்லிய மாவையும், புளிப்பில்லாத அதிரசங்களையும், சட்டிகளிலே செய்கிறதையும் சுடுகிறதையும், திட்டமான சகல நிறையையும் அளவையும் விசாரிப்பதும்,", "en": "Both for the shewbread, and for the fine flour for meat offering, and for the unleavened cakes, and for that which is baked in the pan, and for that which is fried, and for all manner of measure and size;"}, {"verse": 30, "start": 300.88, "end": 315.66, "ta": "நாள்தோறும் காலையிலும் மாலையிலும் கர்த்தரைப் போற்றித் துதித்து, ஓய்வுநாட்களிலும், அமாவாசைகளிலும், பண்டிகைகளிலும், கர்த்தருக்குச் சர்வாங்க தகனபலிகள் செலுத்தப்படுகிற சகல வேளைகளிலும்,", "en": "And to stand every morning to thank and praise the LORD , and likewise at even;"}, {"verse": 31, "start": 315.66, "end": 326.17, "ta": "இலக்கத்திற்குள்ளான அவர்கள் தங்களுக்கு நியமிக்கப்பட்டபடியே, எப்பொழுதும் அந்தப் பிரகாரமாய்ச் செய்ய, கர்த்தருக்கு முன்பாக நிற்பதும்,", "en": "And to offer all burnt sacrifices unto the LORD in the sabbaths, in the new moons, and on the set feasts, by number, according to the order commanded unto them, continually before the LORD :"}, {"verse": 32, "start": 326.17, "end": 341.48, "ta": "ஆசரிப்புக் கூடாரத்தின் காவலையும் பரிசுத்த ஸ்தலத்தின் காவலையும் தங்கள் சகோதரராகிய ஆரோனுடைய குமாரரின் காவலையும் காப்பதும், கர்த்தருடைய ஆலயத்தின் பணிவிடையைச் செய்வதும் அவர்கள் வேலையாயிருந்தது.", "en": "And that they should keep the charge of the tabernacle of the congregation, and the charge of the holy place , and the charge of the sons of Aaron their brethren, in the service of the house of the LORD ."}]}, "24": {"chapter": 24, "duration": 309.62, "audio_url": "audio_ot/OT13_24.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 13.09, "ta": "ஆரோன் புத்திரரின் வகுப்புகளாவன: ஆரோனின் குமாரர், நாதாப், அபியூ, எலெயாசார், இத்தாமார் என்பவர்கள்.", "en": "Now these are the divisions of the sons of Aaron. The sons of Aaron; Nadab, and Abihu, Eleazar, and Ithamar."}, {"verse": 2, "start": 13.09, "end": 24.28, "ta": "நாதாபும் அபியூவும் குமாரர் இல்லாமல் தங்கள் தகப்பனுக்கு முன்னே மரித்தபடியினால், எலெயாசாரும் இத்தாமாரும் ஆசாரிய ஊழியம் செய்தார்கள்.", "en": "But Nadab and Abihu died before their father, and had no children: therefore Eleazar and Ithamar executed the priest’s office."}, {"verse": 3, "start": 24.28, "end": 37.85, "ta": "தாவீது சாதோக்கைக்கொண்டு எலெயாசாரின் புத்திரரையும், அகிமெலேக்கைக்கொண்டு இத்தாமாரின் புத்திரரையும் அவர்கள் செய்யவேண்டிய ஊழியத்துக்கு முறைப்படி அவர்களை வகுத்தான்.", "en": "And David distributed them, both Zadok of the sons of Eleazar, and Ahimelech of the sons of Ithamar, according to their offices in their service."}, {"verse": 4, "start": 37.85, "end": 63.97, "ta": "அவர்களை வகுக்கிறபோது, இத்தாமாரின் புத்திரரைப்பார்க்கிலும் எலெயாசாரின் புத்திரருக்குள்ளே தலைமையானவர்கள் அதிகமானபேர் காணப்பட்டபடியினால், எலெயாசாரின் புத்திரரில் பதினாறுபேர் தங்கள் பிதாக்களுடைய குடும்பத்துக்கும், இத்தாமாரின் புத்திரரில் எட்டுப்பேர் தங்கள் பிதாக்களுடைய குடும்பத்துக்கும் தலைமையாக வைக்கப்பட்டார்கள்.", "en": "And there were more chief men found of the sons of Eleazar than of the sons of Ithamar; and thus were they divided. Among the sons of Eleazar there were sixteen chief men of the house of their fathers, and eight among the sons of Ithamar according to the house of their fathers."}, {"verse": 5, "start": 63.97, "end": 83.09, "ta": "எலெயாசாரின் புத்திரரிலும் இத்தாமாரின் புத்திரரிலும், பரிசுத்த ஸ்தலத்துக்கும், தேவனுக்கு அடுத்த காரியங்களில் பிரபுக்களாயிருக்கும்படிக்கும், இவர்களுக்கும் அவர்களுக்கும் வித்தியாசம்பண்ணாமல் சீட்டுப்போட்டு அவர்களை வகுத்தார்கள்.", "en": "Thus were they divided by lot, one sort with another; for the governors of the sanctuary, and governors of the house of God, were of the sons of Eleazar, and of the sons of Ithamar."}, {"verse": 6, "start": 83.09, "end": 112.07, "ta": "லேவியரில் சம்பிரதியாகிய செமாயா என்னும் நெதனெயேலின் குமாரன், ராஜாவுக்கும் பிரபுக்களுக்கும் ஆசாரியனாகிய சாதோக்குக்கும் அபியத்தாரின் குமாரனாகிய அகிமெலேக்குக்கும் ஆசாரியரும் லேவியருமான பிதாக்களின் தலைவருக்கும் முன்பாக அவர்கள் நாமங்களை எழுதினான்; ஒரு பிதாவின் வீட்டுச் சீட்டு எலெயாசாருக்கு விழுந்தது; பின்பு அந்தப்படியே இத்தாமாருக்கும் விழுந்தது.", "en": "And Shemaiah the son of Nethaneel the scribe, one of the Levites, wrote them before the king, and the princes, and Zadok the priest, and Ahimelech the son of Abiathar, and before the chief of the fathers of the priests and Levites: one principal household being taken for Eleazar, and one taken for Ithamar."}, {"verse": 7, "start": 112.07, "end": 118.65, "ta": "முதலாவது சீட்டு யோயாரிபின் பேர்வழிக்கும், இரண்டாவது யெதாயாவின் பேர்வழிக்கும்,", "en": "Now the first lot came forth to Jehoiarib, the second to Jedaiah,"}, {"verse": 8, "start": 118.65, "end": 124.53, "ta": "மூன்றாவது ஆரிமின் பேர்வழிக்கும், நான்காவது செயோரீமின் பேர்வழிக்கும்,", "en": "The third to Harim, the fourth to Seorim,"}, {"verse": 9, "start": 124.53, "end": 130.4, "ta": "ஐந்தாவது மல்கியாவின் பேர்வழிக்கும், ஆறாவது மியாமீனின் பேர்வழிக்கும்,", "en": "The fifth to Malchijah, the sixth to Mijamin,"}, {"verse": 10, "start": 130.4, "end": 136.2, "ta": "ஏழாவது அக்கோத்சின் பேர்வழிக்கும், எட்டாவது அபியாவின் பேர்வழிக்கும்,", "en": "The seventh to Hakkoz, the eighth to Abijah,"}, {"verse": 11, "start": 136.2, "end": 142.47, "ta": "ஒன்பதாவது யெசுவாவின் பேர்வழிக்கும், பத்தாவது செக்கனியாவின் பேர்வழிக்கும்,", "en": "The ninth to Jeshua, the tenth to Shecaniah,"}, {"verse": 12, "start": 142.47, "end": 148.98, "ta": "பதினோராவது எலியாசீபின் பேர்வழிக்கும், பன்னிரண்டாவது யாக்கீமின்பேர்வழிக்கும்,", "en": "The eleventh to Eliashib, the twelfth to Jakim,"}, {"verse": 13, "start": 148.98, "end": 155.72, "ta": "பதின்மூன்றாவது உப்பாவின் பேர்வழிக்கும், பதினான்காவது எசெபெயாபின் பேர்வழிக்கும்,", "en": "The thirteenth to Huppah, the fourteenth to Jeshebeab,"}, {"verse": 14, "start": 155.72, "end": 162.07, "ta": "பதினைந்தாவது பில்காவின் பேர்வழிக்கும், பதினாறாவது இம்மேரின் பேர்வழிக்கும்,", "en": "The fifteenth to Bilgah, the sixteenth to Immer,"}, {"verse": 15, "start": 162.07, "end": 168.18, "ta": "பதினேழாவது ஏசீரின் பேர்வழிக்கும், பதினெட்டாவது அப்சேசின் பேர்வழிக்கும்,", "en": "The seventeenth to Hezir, the eighteenth to Aphses,"}, {"verse": 16, "start": 168.18, "end": 175.25, "ta": "பத்தொன்பதாவது பெத்தகியாவின் பேர்வழிக்கும், இருபதாவது எகெசெக்கியேலின் பேர்வழிக்கும்,", "en": "The nineteenth to Pethahiah, the twentieth to Jehezekel,"}, {"verse": 17, "start": 175.25, "end": 182.07, "ta": "இருபத்தோராவது யாகினின் பேர்வழிக்கும், இருபத்திரண்டாவது காமுவேலின் பேர்வழிக்கும்,", "en": "The one and twentieth to Jachin, the two and twentieth to Gamul,"}, {"verse": 18, "start": 182.07, "end": 190.73, "ta": "இருபத்துமூன்றாவது தெலாயாவின் பேர்வழிக்கும், இருபத்துநான்காவது மாசியாவின் பேர்வழிக்கும் விழுந்தது.", "en": "The three and twentieth to Delaiah, the four and twentieth to Maaziah."}, {"verse": 19, "start": 190.73, "end": 210.01, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தர் அவர்கள் தகப்பனாகிய ஆரோனுக்குக் கற்பித்தபடியே, அவர்கள் அவனுடைய கட்டளையின் பிரகாரம், தங்கள் முறைவரிகளில் கர்த்தருடைய ஆலயத்திற்குள் பிரவேசிக்கும் அவர்களுடைய ஊழியத்திற்காகப் பண்ணப்பட்ட வகுப்புகள் இவைகளே.", "en": "These were the orderings of them in their service to come into the house of the LORD , according to their manner, under Aaron their father, as the LORD God of Israel had commanded him."}, {"verse": 20, "start": 210.01, "end": 219.06, "ta": "லேவியின் மற்றப் புத்திரருக்குள்ளே இருக்கிற அம்ராமின் புத்திரரில் சூபவேலும், சூபவேலின் குமாரரில் எகேதியாவும்,", "en": "And the rest of the sons of Levi were these: Of the sons of Amram; Shubael: of the sons of Shubael; Jehdeiah."}, {"verse": 21, "start": 219.06, "end": 222.79, "ta": "ரெகபியாவின் குமாரரில் மூத்தவனாகிய இஷியாவும்,", "en": "Concerning Rehabiah: of the sons of Rehabiah, the first was Isshiah."}, {"verse": 22, "start": 222.79, "end": 228.11, "ta": "இத்சாரியரில் செலெமோத்தும், செலெமோத்தின் குமாரரில் யாகாத்தும்,", "en": "Of the Izharites; Shelomoth: of the sons of Shelomoth; Jahath."}, {"verse": 23, "start": 228.11, "end": 240.41, "ta": "எப்ரோனின் குமாரரில் மூத்தவனாகிய எரியாவும், இரண்டாம் குமாரனாகிய அமரியாவும், மூன்றாம் குமாரனாகிய யாகாசியேலும், நான்காம் குமாரனாகிய எக்காமியாமும்,", "en": "And the sons of Hebron; Jeriah the first , Amariah the second, Jahaziel the third, Jekameam the fourth."}, {"verse": 24, "start": 240.41, "end": 245.49, "ta": "ஊசியேலின் குமாரரில் மீகாவும், மீகாவின் குமாரரில் சாமீரும்,", "en": "Of the sons of Uzziel; Michah: of the sons of Michah; Shamir."}, {"verse": 25, "start": 245.49, "end": 250.81, "ta": "மீகாவின் சகோதரனாகிய இஷியாவும், இஷியாவின குமாரரில் சகரியாவும்,", "en": "The brother of Michah was Isshiah: of the sons of Isshiah; Zechariah."}, {"verse": 26, "start": 250.81, "end": 257.4, "ta": "மெராரியின் குமாரராகிய மகேலிமூசி என்பவர்களும், யாசியாவின் குமாரனாகிய பேனோவும்,", "en": "The sons of Merari were Mahli and Mushi: the sons of Jaaziah; Beno."}, {"verse": 27, "start": 257.4, "end": 265.02, "ta": "மெராரியின் குமாரனாகிய யாசியாவின் குமாரரான பேனோ, ரோகாம், சக்கூர், இப்ரி என்பவர்களும்,", "en": "The sons of Merari by Jaaziah; Beno, and Shoham, and Zaccur, and Ibri."}, {"verse": 28, "start": 265.02, "end": 268.99, "ta": "மகேலியின் குமாரரில் புத்திரனில்லாத எலெயாசாரும்,", "en": "Of Mahli came Eleazar, who had no sons."}, {"verse": 29, "start": 268.99, "end": 271.77, "ta": "கீசின் புத்திரரில் யெராமியேலும்,", "en": "Concerning Kish: the son of Kish was Jerahmeel."}, {"verse": 30, "start": 271.77, "end": 283.04, "ta": "மூசியின் குமாரரான மகேலி, ஏதேர் எரிமோத் என்பவர்களுமாகிய இவர்கள் தங்கள் பிதாக்களுடைய குடும்பங்களின்படியே லேவியரின் புத்திரரானவர்கள்.", "en": "The sons also of Mushi; Mahli, and Eder, and Jerimoth. These were the sons of the Levites after the house of their fathers."}, {"verse": 31, "start": 283.04, "end": 308.12, "ta": "இவர்களும் ராஜாவாகிய தாவீதுக்கும் சாதோக்குக்கும் அகிமெலேக்குக்கும் ஆசாரியரிலும் லேவியரிலும் பிதாக்களாயிருக்கிற தலைவருக்கும் முன்பாக, தங்கள் சகோதரராகிய ஆரோனின் புத்திரர் செய்ததுபோல, தங்களிலிருக்கிற பிதாக்களான தலைவருக்கும், அவர்களுடைய சிறிய சகோதரருக்கும், சரிசமானமாய்ச் சீட்டுப்போட்டுக்கொண்டார்கள்.", "en": "These likewise cast lots over against their brethren the sons of Aaron in the presence of David the king, and Zadok, and Ahimelech, and the chief of the fathers of the priests and Levites, even the principal fathers over against their younger brethren."}]}, "25": {"chapter": 25, "duration": 292.59, "audio_url": "audio_ot/OT13_25.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 27.11, "ta": "மேலும் சுரமண்டலங்களாலும் தம்புருகளாலும் கைத்தாளங்களாலும், தீர்க்கதரிசனம் சொல்லுகிற ஆசாப், ஏமான், எதுத்தூன் என்பவர்களின் குமாரரில் சிலரை, தாவீதும் தேவாலயச் சேனைகளின் பிரபுக்களும் ஊழியத்திற்கென்று பிரித்துவைத்தார்கள்; தங்கள் ஊழியத்தின் கிரியைக்குக் குறித்துவைக்கப்பட்ட மனுஷர்களின் தொகையாவது:", "en": "Moreover David and the captains of the host separated to the service of the sons of Asaph, and of Heman, and of Jeduthun, who should prophesy with harps, with psalteries, and with cymbals: and the number of the workmen according to their service was:"}, {"verse": 2, "start": 27.11, "end": 39.86, "ta": "ராஜாவுடைய கட்டளைப்பிரமாணமாய்த் தீர்க்கதரிசனம் சொல்லுகிற ஆசாப்பின் வசத்திலிருக்கிற, ஆசாப்பின் குமாரரில் சக்கூர், யோசேப்பு, நெதானியா, அஷாரேலா என்பவர்களும்,", "en": "Of the sons of Asaph; Zaccur, and Joseph, and Nethaniah, and Asarelah, the sons of Asaph under the hands of Asaph, which prophesied according to the order of the king."}, {"verse": 3, "start": 39.86, "end": 56.49, "ta": "கர்த்தரைப் போற்றித் துதித்துத் தீர்க்கதரிசனம் சொல்லுகிற தங்கள் தகப்பனாகிய எதுத்தூனின் வசத்திலே சுரமண்டலங்களை வாசிக்க, எதுத்தூனின் குமாரராகிய கெதலியா, சேரீ, எஷாயா, அஷபியா, மத்தித்தியா என்னும் ஆறுபேரும்,", "en": "Of Jeduthun: the sons of Jeduthun; Gedaliah, and Zeri, and Jeshaiah, Hashabiah, and Mattithiah, six, under the hands of their father Jeduthun, who prophesied with a harp, to give thanks and to praise the LORD ."}, {"verse": 4, "start": 56.49, "end": 78.36, "ta": "கொம்பைத் தொனிக்கப்பண்ண, தேவவிஷயத்தில் ராஜாவுக்கு ஞானதிருஷ்டிக்காரனாகிய ஏமானின் குமாரர் புக்கியா, மத்தனியா, ஊசியேல், செபுவேல், எரிமோத், அனனியா, அனானி, எலியாத்தா, கிதல்தி, ரொமந்தியேசர், யோஸ்பெகாஷா, மலோத்தி, ஒத்திர், மகாசியோத் என்பவர்களுமே.", "en": "Of Heman: the sons of Heman; Bukkiah, Mattaniah, Uzziel, Shebuel, and Jerimoth, Hananiah, Hanani, Eliathah, Giddalti, and Romamti-ezer, Joshbekashah, Mallothi, Hothir, and Mahazioth:"}, {"verse": 5, "start": 78.36, "end": 88.53, "ta": "இவர்களெல்லாரும் ஏமானின் குமாரராயிருந்தார்கள்; தேவன் ஏமானுக்குப் பதினாலு குமாரரையும் மூன்று குமாரத்திகளையும் கொடுத்தார்.", "en": "All these were the sons of Heman the king’s seer in the words of God, to lift up the horn. And God gave to Heman fourteen sons and three daughters."}, {"verse": 6, "start": 88.53, "end": 108.5, "ta": "இவர்கள் அனைவரும் ராஜாவுடைய கட்டளைப்பிரமாணமாய்க் கர்த்தருடைய ஆலயத்தில் தாளங்கள் தம்புருகள் சுரமண்டலங்களாகிய கீதவாத்தியம் வாசிக்க, தேவனுடைய ஆலயத்தின் ஊழியமாக அவரவர் தங்கள் தங்கள் தகப்பன்மாராகிய ஆசாப் எதுத்தூன், ஏமான் என்பவர்கள் வசத்தில் இருந்தார்கள்.", "en": "All these were under the hands of their father for song in the house of the LORD , with cymbals, psalteries, and harps, for the service of the house of God, according to the king’s order to Asaph, Jeduthun, and Heman."}, {"verse": 7, "start": 108.5, "end": 119.89, "ta": "கர்த்தரைப் பாடும் பாட்டுகளைக் கற்றுக்கொண்டு, நிபுணரான தங்கள் சகோதரரோடுங்கூட அவர்கள் இலக்கத்திற்கு இருநூற்றெண்பத்தெட்டுப்பேராயிருந்தார்கள்.", "en": "So the number of them, with their brethren that were instructed in the songs of the LORD , even all that were cunning, was two hundred fourscore and eight."}, {"verse": 8, "start": 119.89, "end": 129.45, "ta": "அவர்களில் சிறியவனும் பெரியவனும், ஆசானும் மாணாக்கனும், சரிசமானமாய் முறைவரிசைக்காகச் சீட்டுப்போட்டுக்கொண்டார்கள்.", "en": "And they cast lots, ward against ward , as well the small as the great, the teacher as the scholar."}, {"verse": 9, "start": 129.45, "end": 140.46, "ta": "முதலாவது சீட்டு ஆசாப் வம்சமான யோசேப்பின் பேர்வழிக்கும், இரண்டாவது கெதலியா, அவன் சகோதரர், அவன் குமாரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "Now the first lot came forth for Asaph to Joseph: the second to Gedaliah, who with his brethren and sons were twelve:"}, {"verse": 10, "start": 140.46, "end": 146.99, "ta": "மூன்றாவது சக்கூர், அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் வழிக்கும்,", "en": "The third to Zaccur, he , his sons, and his brethren, were twelve:"}, {"verse": 11, "start": 146.99, "end": 153.37, "ta": "நான்காவது இஸ்ரி, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் வழிக்கும்,", "en": "The fourth to Izri, he , his sons, and his brethren, were twelve:"}, {"verse": 12, "start": 153.37, "end": 159.97, "ta": "ஐந்தாவது நெத்தனியா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The fifth to Nethaniah, he , his sons, and his brethren, were twelve:"}, {"verse": 13, "start": 159.97, "end": 166.35, "ta": "ஆறாவது புக்கியா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The sixth to Bukkiah, he , his sons, and his brethren, were twelve:"}, {"verse": 14, "start": 166.35, "end": 172.5, "ta": "ஏழாவது எசரேலோ, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர்வழிக்கும்,", "en": "The seventh to Jesharelah, he , his sons, and his brethren, were twelve:"}, {"verse": 15, "start": 172.5, "end": 178.8, "ta": "எட்டாவது எஷாயா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The eighth to Jeshaiah, he , his sons, and his brethren, were twelve:"}, {"verse": 16, "start": 178.8, "end": 184.95, "ta": "ஒன்பதாவது மத்தனீயா, அவன் குமாரர், அவன் சகோதரர் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The ninth to Mattaniah, he , his sons, and his brethren, were twelve:"}, {"verse": 17, "start": 184.95, "end": 191.33, "ta": "பத்தாவது சிமேயா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The tenth to Shimei, he , his sons, and his brethren, were twelve:"}, {"verse": 18, "start": 191.33, "end": 198.01, "ta": "பதினோராவது அசாரியேல், அவன்குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The eleventh to Azareel, he , his sons, and his brethren, were twelve:"}, {"verse": 19, "start": 198.01, "end": 204.84, "ta": "பன்னிரண்டாவது அஷாபியா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The twelfth to Hashabiah, he , his sons, and his brethren, were twelve:"}, {"verse": 20, "start": 204.84, "end": 211.75, "ta": "பதின்மூன்றாவது சுபவேல், அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The thirteenth to Shubael, he , his sons, and his brethren, were twelve:"}, {"verse": 21, "start": 211.75, "end": 219.12, "ta": "பதினான்காவது மத்தித்தியா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The fourteenth to Mattithiah, he , his sons, and his brethren, were twelve:"}, {"verse": 22, "start": 219.12, "end": 224.89, "ta": "பதினைந்தாவது எரேமோத், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The fifteenth to Jeremoth, he , his sons, and his brethren, were twelve:"}, {"verse": 23, "start": 224.89, "end": 231.72, "ta": "பதினாறாவது அனனியா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The sixteenth to Hananiah, he , his sons, and his brethren, were twelve:"}, {"verse": 24, "start": 231.72, "end": 238.7, "ta": "பதினேழாவது யோஸ்பேக்காஷா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The seventeenth to Joshbekashah, he , his sons, and his brethren, were twelve:"}, {"verse": 25, "start": 238.7, "end": 245.61, "ta": "பதினெட்டாவது ஆனானி, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The eighteenth to Hanani, he , his sons, and his brethren, were twelve:"}, {"verse": 26, "start": 245.61, "end": 253.05, "ta": "பத்தொன்பதாவது, மலோத்தி, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The nineteenth to Mallothi, he , his sons, and his brethren, were twelve:"}, {"verse": 27, "start": 253.05, "end": 259.96, "ta": "ருபதாவது எலியாத்தா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The twentieth to Eliathah, he , his sons, and his brethren, were twelve:"}, {"verse": 28, "start": 259.96, "end": 267.1, "ta": "இருபத்தோராவது ஒத்திர், அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The one and twentieth to Hothir, he , his sons, and his brethren, were twelve:"}, {"verse": 29, "start": 267.1, "end": 274.46, "ta": "இருபத்திரண்டாவது கிதல்தி, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The two and twentieth to Giddalti, he , his sons, and his brethren, were twelve:"}, {"verse": 30, "start": 274.46, "end": 282.06, "ta": "இருபத்துமூன்றாவது மகாசியோத், அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The three and twentieth to Mahazioth, he , his sons, and his brethren, were twelve:"}, {"verse": 31, "start": 282.06, "end": 291.09, "ta": "இருபத்துநான்காவது ரொமந்தியேசர், அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும் விழுந்தது.", "en": "The four and twentieth to Romamti-ezer, he , his sons, and his brethren, were twelve."}]}, "26": {"chapter": 26, "duration": 383.18, "audio_url": "audio_ot/OT13_26.mp3", "total_verses": 32, "verses": [{"verse": 1, "start": 3.8, "end": 12.89, "ta": "வாசல்காக்கிறவர்களின் வகுப்புகளாவன: கோராகியர் சந்ததியான ஆசாபின் புத்திரரிலே கோரேயின் குமாரன் மெஷெலேமியா என்பவன்,", "en": "Concerning the divisions of the porters: Of the Korhites was Meshelemiah the son of Kore, of the sons of Asaph."}, {"verse": 2, "start": 12.89, "end": 17.11, "ta": "மெஷெலேமியாவின் குமாரர், மூத்தவனாகிய சகரியாவும்,", "en": "And the sons of Meshelemiah were , Zechariah the firstborn, Jediael the second, Zebadiah the third, Jathniel the fourth,"}, {"verse": 3, "start": 17.11, "end": 28.43, "ta": "எதியாயேல், செபதியா, யதனியேல், ஏலாம், யோகனான், எலியோனாய் என்னும் இரண்டாம் மூன்றாம் நான்காம் ஐந்தாம் ஆறாம் ஏழாம் குமாரரும்;", "en": "Elam the fifth, Jehohanan the sixth, Elioenai the seventh."}, {"verse": 4, "start": 28.43, "end": 32.58, "ta": "ஒபேத் ஏதோமின் குமாரர், மூத்தவனாகிய செமாயாவும்,", "en": "Moreover the sons of Obed-edom were , Shemaiah the firstborn, Jehozabad the second, Joah the third, and Sacar the fourth, and Nethaneel the fifth,"}, {"verse": 5, "start": 32.58, "end": 48.92, "ta": "யோசபாத், யோவாக், சாக்கார், நெனெயேல், அம்மியேல், இசக்கார், பெயுள்தாயி என்னும் இரண்டாம் மூன்றாம் நான்காம் ஐந்தாம் ஆறாம் ஏழாம் எட்டாம் குமாரருமே, தேவன் அவனை ஆசீர்வதித்திருந்தார்.", "en": "Ammiel the sixth, Issachar the seventh, Peulthai the eighth: for God blessed him."}, {"verse": 6, "start": 48.92, "end": 59.84, "ta": "அவன் குமாரனாகிய செமாயாவுக்கும் குமாரர் பிறந்து, அவர்கள் பராக்கிரமசாலிகளாயிருந்து, தங்கள் தகப்பன் குடும்பத்தாரை ஆண்டார்கள்.", "en": "Also unto Shemaiah his son were sons born, that ruled throughout the house of their father: for they were mighty men of valour."}, {"verse": 7, "start": 59.84, "end": 71.56, "ta": "செமாயாவுக்கு இருந்த குமாரர் ஒத்னியும், பலசாலிகளாகிய ரெப்பாயேல், ஓபேத், எல்சாபாத என்னும் அவன் சகோதரரும், எலிகூவும் செமகியாவுமே.", "en": "The sons of Shemaiah; Othni, and Rephael, and Obed, Elzabad, whose brethren were strong men, Elihu, and Semachiah."}, {"verse": 8, "start": 71.56, "end": 83.2, "ta": "ஓபேத்ஏதோமின் புத்திரரும் அவர்கள் குமாரரும் அவர்கள் சகோதரருமாகிய ஊழியத்திற்குப் பலத்த பராக்கிரமசாலிகளான அவர்களெல்லாரும் அறுபத்திரண்டுபேர்.", "en": "All these of the sons of Obed-edom: they and their sons and their brethren, able men for strength for the service, were threescore and two of Obed-edom."}, {"verse": 9, "start": 83.2, "end": 89.42, "ta": "மெஷெலேமியாவின் குமாரரும் சகோதரருமான பராக்கிரமசாலிகள் பதினெட்டுப்பேர்.", "en": "And Meshelemiah had sons and brethren, strong men, eighteen."}, {"verse": 10, "start": 89.42, "end": 102.02, "ta": "மெராரியின் புத்திரரில் ஓசா என்பவனுடைய குமாரர்கள்: சிம்ரி என்னும் தலைமையானவன்; இவன் மூத்தவனாயிராவிட்டாலும் இவன் தகப்பன் இவனைத் தலைவனாக வைத்தான்.", "en": "Also Hosah, of the children of Merari, had sons; Simri the chief, (for though he was not the firstborn, yet his father made him the chief;)"}, {"verse": 11, "start": 102.02, "end": 114.37, "ta": "இல்க்கியா, தெபலியா, சகரியா என்னும் இரண்டாம், மூன்றாம் நான்காம் குமாரரானவர்கள்; ஓசாவின் குமாரரும் சகோதரரும் எல்லாம் பதின்மூன்றுபேர்.", "en": "Hilkiah the second, Tebaliah the third, Zechariah the fourth: all the sons and brethren of Hosah were thirteen."}, {"verse": 12, "start": 114.37, "end": 125.77, "ta": "காவல்காரரான தலைவரின் கீழ்த் தங்கள் சகோதரருக்கு ஒத்த முறையாய், கர்த்தருடைய ஆலயத்தில் வாசல்காக்கிறவர்களாய்ச் சேவிக்க இவர்கள் வகுக்கப்பட்டு,", "en": "Among these were the divisions of the porters, even among the chief men, having wards one against another, to minister in the house of the LORD ."}, {"verse": 13, "start": 125.77, "end": 136.14, "ta": "தங்கள் பிதாக்களின் குடும்பத்தாராகிய சிறியவர்களும் பெரியவர்களுமாய் இன்ன வாசலுக்கு இன்னாரென்று சீட்டுப்போட்டுக்கொண்டார்கள்.", "en": "And they cast lots, as well the small as the great, according to the house of their fathers, for every gate."}, {"verse": 14, "start": 136.14, "end": 151.6, "ta": "கீழ்ப்புறத்திற்குச் செலேமியாவுக்குச் சீட்டு விழுந்தது; விவேகமுள்ள யோசனைக்காரனாகிய சகரியா என்னும் அவன் குமாரனுக்குச் சீட்டுப் போட்டபோது, அவன் சீட்டு வடபுறத்திற்கென்று விழுந்தது.", "en": "And the lot eastward fell to Shelemiah. Then for Zechariah his son, a wise counsellor, they cast lots; and his lot came out northward."}, {"verse": 15, "start": 151.6, "end": 158.14, "ta": "ஓபேத்ஏதேமுக்குத் தென்புறத்திற்கும், அவன் குமாரருக்கு அசுப்பீம் வீட்டிற்கும்,", "en": "To Obed-edom southward; and to his sons the house of Asuppim."}, {"verse": 16, "start": 158.14, "end": 169.62, "ta": "சூப்பீமுக்கும், ஓசாவுக்கும் மண்போட்டு உயர்த்தப்பட்ட வழியும் காவலுக்கு எதிர்காவலும் இருக்கிற மேற்புறமான வாசலுக்கும் சீட்டு விழுந்தது.", "en": "To Shuppim and Hosah the lot came forth westward, with the gate Shallecheth, by the causeway of the going up, ward against ward."}, {"verse": 17, "start": 169.62, "end": 180.78, "ta": "கிழக்கே லேவியரான ஆறுபேரும், வடக்கே பகலிலே நாலுபேரும், தெற்கே பகலிலே நாலுபேரும், அசுப்பீம் வீட்டண்டையில் இரண்டிரண்டுபேரும்.", "en": "Eastward were six Levites, northward four a day, southward four a day, and toward Asuppim two and two."}, {"verse": 18, "start": 180.78, "end": 191.7, "ta": "வெளிப்புறமான வாசல் அண்டையில் மேற்கே இருக்கிற உயர்ந்த வழிக்கு நாலுபேரும், வெளிப்புறமான வழியிலே இரண்டுபேரும் வைக்கப்பட்டார்கள்.", "en": "At Parbar westward, four at the causeway, and two at Parbar."}, {"verse": 19, "start": 191.7, "end": 200.95, "ta": "கோராகின் புத்திரருக்குள்ளும், மெராரியின் புத்திரருக்குள்ளும், வாசல்காக்கிறவர்களின் வகுப்புகள் இவைகளே.", "en": "These are the divisions of the porters among the sons of Kore, and among the sons of Merari."}, {"verse": 20, "start": 200.95, "end": 213.07, "ta": "மற்ற லேவியரில் அகியா என்பவன் தேவனுடைய ஆலயத்துப் பொக்கிஷங்களையும், பிரதிஷ்டையாக்கப்படட பொருள்களின் பொக்கிஷங்களையும் விசாரிக்கிறவனாயிருந்தான்.", "en": "And of the Levites, Ahijah was over the treasures of the house of God, and over the treasures of the dedicated things."}, {"verse": 21, "start": 213.07, "end": 221.12, "ta": "லாதானின் குமாரர் யாரென்றால் கெர்சோனியனான அவனுடைய குமாரரில் தலைமையான பிதாக்களாயிருந்த யெகியேலியும்,", "en": "As concerning the sons of Laadan; the sons of the Gershonite Laadan, chief fathers, even of Laadan the Gershonite, were Jehieli."}, {"verse": 22, "start": 221.12, "end": 233.4, "ta": "யெகியேலியின் குமாரராகிய சேத்தாமும், அவன் சகோதரனாகிய யோவேலுமே; இவர்கள் கர்த்தருடைய ஆலயத்துப் பொக்கிஷங்களை விசாரிக்கிறவர்களாயிருந்தார்கள்.", "en": "The sons of Jehieli; Zetham, and Joel his brother, which were over the treasures of the house of the LORD ."}, {"verse": 23, "start": 233.4, "end": 244.32, "ta": "அம்ராமியரிலும், இத்சேயாரியரிலும், எப்ரோனியரிலும், ஊசியேரியரிலும், சிலர், அப்படியே விசாரிக்கிறவர்களாயிருந்தார்கள்.", "en": "Of the Amramites, and the Izharites, the Hebronites, and the Uzzielites:"}, {"verse": 24, "start": 244.32, "end": 251.34, "ta": "மோசேயின் குமாரனாகிய கெர்சோமின் சந்ததியான செபுவேல் பொக்கிஷப்பிரதானியாயிருந்தான்.", "en": "And Shebuel the son of Gershom, the son of Moses, was ruler of the treasures."}, {"verse": 25, "start": 251.34, "end": 267.2, "ta": "ஏலியேசர் மூலமாய் அவனுக்கு இருந்த சகோதரரானவர்கள், இவன் குமாரன் ரெகபியாவும், இவன் குமாரன் எஷாயாவும், இவன் குமாரன் யோராமும், இவன் குமாரன் சிக்கிரியும், இவன் குமாரன் செலோமித்துமே.", "en": "And his brethren by Eliezer; Rehabiah his son, and Jeshaiah his son, and Joram his son, and Zichri his son, and Shelomith his son."}, {"verse": 26, "start": 267.2, "end": 279.64, "ta": "ராஜாவாகிய தாவீதும், ஆயிரம்பேருக்கு அதிபதிகளும், நூறுபேருக்கு அதிகமான பிதாக்களின் தலைவரும், அதிபதிகளும் யுத்தத்தில் அகப்பட்ட கொள்ளைகளில் எடுத்து,", "en": "Which Shelomith and his brethren were over all the treasures of the dedicated things, which David the king, and the chief fathers, the captains over thousands and hundreds, and the captains of the host, had dedicated."}, {"verse": 27, "start": 279.64, "end": 293.35, "ta": "கர்த்தருடைய ஆலயத்தைப் பரிபாலிக்கும்படிக்குப் பரிசுத்தம் என்று நேர்ந்துகொண்ட பொருள்களின் பொக்கிஷங்களையெல்லாம் அந்தச் செலோமித்தும் அவனுடைய சகோதரரும் விசாரித்தார்கள்.", "en": "Out of the spoils won in battles did they dedicate to maintain the house of the LORD ."}, {"verse": 28, "start": 293.35, "end": 311.05, "ta": "ஞானதிருஷ்டிக்காரனாகிய சாமுவேலும், நேரின் குமாரனாகிய அப்னேரும், செருயாவின் குமாரராகிய யோவாபும், அவரவர் பரிசுத்தம் என்று நேர்ந்துகொண்ட அனைத்தும் செலோமித்தின் கையின்கீழும் அவன் சகோதரர் கையின்கீழும் இருந்தது.", "en": "And all that Samuel the seer, and Saul the son of Kish, and Abner the son of Ner, and Joab the son of Zeruiah, had dedicated; and whosoever had dedicated any thing, it was under the hand of Shelomith, and of his brethren."}, {"verse": 29, "start": 311.05, "end": 323.72, "ta": "இத்சேயாரியரில் கெனானியாவும் அவன் குமாரரும் தேசகாரியங்களைப் பார்க்கும்படி வைக்கப்பட்டு, இஸ்ரவேலின்மேல் விசாரிப்புக்காரரும் மணியகாரருமாயிருந்தார்கள்.", "en": "Of the Izharites, Chenaniah and his sons were for the outward business over Israel, for officers and judges."}, {"verse": 30, "start": 323.72, "end": 340.46, "ta": "எப்ரோனியரில் அசபியாவும் அவன் சகோதரருமாகிய ஆயிரத்து எழுநூறுபராக்கிரமசாலிகள் யோர்தானுக்கு இப்பாலே, மேற்கே இருக்கிற இஸ்ரவேலின் கர்த்தருடைய எல்லா ஊழியத்திற்கும் ராஜாவின் வேலைக்கும், கீழ்ப்பட்டார்கள்.", "en": "And of the Hebronites, Hashabiah and his brethren, men of valour, a thousand and seven hundred, were officers among them of Israel on this side Jordan westward in all the business of the LORD , and in the service of the king."}, {"verse": 31, "start": 340.46, "end": 359.84, "ta": "எப்ரோனியரில் எரியாவும் இருந்தான்; அவன் தன் பிதாக்களின் வம்சங்களான எப்ரோனியரில் தலைமையானவன்; தாவீது அரசாண்ட நாற்பதாம் வருஷத்திலே அவர்கள் தேடப்பட்டபோது அவர்களுக்குள்ளே கீலேயாத்தேசத்து ஏசேரிலே பராக்கிரம வீரர் காணப்பட்டார்கள்.", "en": "Among the Hebronites was Jerijah the chief, even among the Hebronites, according to the generations of his fathers. In the fortieth year of the reign of David they were sought for, and there were found among them mighty men of valour at Jazer of Gilead."}, {"verse": 32, "start": 359.84, "end": 381.68, "ta": "பலசாலிகளாகிய அவர்களுடைய சகோதரர் இரண்டாயிரத்து எழுநூறு பிரதான தலைவராயிருந்தார்கள்; அவர்களைத் தாவீது ராஜா தேவனுக்கடுத்த சகல காரியத்திற்காகவும், ராஜாவின் காரியத்கிற்காகவும், ரூபனியர்மேலும், காதியர்மேலும், மனாசேயின் பாதிக்கோத்திரத்தின்மேலும் வைத்தான்.", "en": "And his brethren, men of valour, were two thousand and seven hundred chief fathers, whom king David made rulers over the Reubenites, the Gadites, and the half tribe of Manasseh, for every matter pertaining to God, and affairs of the king."}]}, "27": {"chapter": 27, "duration": 406.37, "audio_url": "audio_ot/OT13_27.mp3", "total_verses": 34, "verses": [{"verse": 1, "start": 3.8, "end": 36.23, "ta": "தங்கள் இலக்கத்தின்படி இருக்கிற இஸ்ரவேல் புத்திரருக்கு வம்சங்களின் தலைவரும், ஆரயித்துக்குச் சேர்வைக்காரரும், நூற்றிற்குச் சேர்வைக்காரரும், இவர்களுடைய தலைவரும் வைக்கப்பட்டிருந்தார்கள்; இவர்கள் வருஷத்திலுண்டான மாதங்களிலெல்லாம் மாதத்திற்கு மாதம் ராஜாவைச் சேவிக்கிறதற்கு வகுக்கப்பட்ட வரிசைகளின்படியெல்லாம் மாறிமாறி வருவார்கள்; ஒவ்வொரு வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "Now the children of Israel after their number, to wit , the chief fathers and captains of thousands and hundreds, and their officers that served the king in any matter of the courses, which came in and went out month by month throughout all the months of the year, of every course were twenty and four thousand."}, {"verse": 2, "start": 36.23, "end": 48.0, "ta": "முதலாவது மாதத்துக்கு முதல் வகுப்பின்மேல் சப்தியேலின் குமாரன் யஷொபெயாம் இருந்தான்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "Over the first course for the first month was Jashobeam the son of Zabdiel: and in his course were twenty and four thousand."}, {"verse": 3, "start": 48.0, "end": 55.45, "ta": "அவன் பேரேசின் சந்ததியாரில் சகல சேனாபதிகளின் தலைவனாயிருந்து முதல் மாதம் விசாரித்தான்.", "en": "Of the children of Perez was the chief of all the captains of the host for the first month."}, {"verse": 4, "start": 55.45, "end": 69.14, "ta": "இரண்டாவது மாதத்தின் வகுப்பின்மேல் அகோகியனான தோதாயி இருந்தான்; அவன் வகுப்பிலே மிக்லோத் தளகர்த்தனாயிருந்தான்; அவன் வகுப்பிலே நாலாயிரம்பேர் இருந்தார்கள்.", "en": "And over the course of the second month was Dodai an Ahohite, and of his course was Mikloth also the ruler: in his course likewise were twenty and four thousand."}, {"verse": 5, "start": 69.14, "end": 80.75, "ta": "மூன்றாவது மாதத்தின் மூன்றாம் சேனாபதி யோய்தாவின் குமாரனாகிய பெனாயா என்னும் தலைமையான பிரதானி வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The third captain of the host for the third month was Benaiah the son of Jehoiada, a chief priest: and in his course were twenty and four thousand."}, {"verse": 6, "start": 80.75, "end": 94.12, "ta": "இந்தப் பெனாயா அந்த முப்பது பராக்கிரமசாலிகளில் ஒருவனும் அந்த முப்பது பேர்களின் தலைவனுமாயிருந்தான்; அவனுடைய வகுப்பை அவன் குமாரனாகிய அமிசபாத் விசாரித்தான்.", "en": "This is that Benaiah, who was mighty among the thirty, and above the thirty: and in his course was Ammizabad his son."}, {"verse": 7, "start": 94.12, "end": 108.13, "ta": "நாலாவது மாதத்தின் நாலாம் சேனாபதி யோவாபின் சகோதரனாகிய ஆசகேலும், அவனுக்குப்பின்பு அவன் குமாரன் செப்தியாவுமே; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The fourth captain for the fourth month was Asahel the brother of Joab, and Zebadiah his son after him: and in his course were twenty and four thousand."}, {"verse": 8, "start": 108.13, "end": 118.46, "ta": "ஐந்தாவது மாதத்தின் ஐந்தாம் சேனாபதி இஸ்ராகியனான சம்கூத் என்பவன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The fifth captain for the fifth month was Shamhuth the Izrahite: and in his course were twenty and four thousand."}, {"verse": 9, "start": 118.46, "end": 129.59, "ta": "ஆறாவது மாதத்தின் ஆறாம் சேனாபதி இக்கேசின் குமாரன் ஈரா என்னும் தெக்கோவியன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The sixth captain for the sixth month was Ira the son of Ikkesh the Tekoite: and in his course were twenty and four thousand."}, {"verse": 10, "start": 129.59, "end": 141.92, "ta": "ஏழாவது மாத்தின் ஏழாம் சேனாபதி எப்பிராயீம் புத்திரரில் ஒருவனாகிய ஏலேஸ் என்னும் பெலோனியன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The seventh captain for the seventh month was Helez the Pelonite, of the children of Ephraim: and in his course were twenty and four thousand."}, {"verse": 11, "start": 141.92, "end": 154.01, "ta": "எட்டாவது மாதத்தின் எட்டாம் சேனாபதி சாரியரில் ஒருவனாகிய சிபெக்காயி என்னும் ஊஷாத்தியன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The eighth captain for the eighth month was Sibbecai the Hushathite, of the Zarhites: and in his course were twenty and four thousand."}, {"verse": 12, "start": 154.01, "end": 165.54, "ta": "ஒன்பதாவது மாதத்தின் ஒன்பதாம் சேனாபதி பென்யமீனரில் அபியேசர் என்னும் ஆனதோத்தான்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The ninth captain for the ninth month was Abi-ezer the Anetothite, of the Benjamites: and in his course were twenty and four thousand."}, {"verse": 13, "start": 165.54, "end": 177.79, "ta": "பத்தாவது மாதத்தின் பத்தாம் சேனாபதி சாரியரில் ஒருவனாகிய மக்ராயி என்னும் நெத்தோபாத்தியன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The tenth captain for the tenth month was Maharai the Netophathite, of the Zarhites: and in his course were twenty and four thousand."}, {"verse": 14, "start": 177.79, "end": 190.36, "ta": "பதினோராவது மாதத்தின் பதினோராம் சேனாபதி எப்பிராயீம் புத்திரரில் பெனாயா என்னும் பிரத்தோனியன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The eleventh captain for the eleventh month was Benaiah the Pirathonite, of the children of Ephraim: and in his course were twenty and four thousand."}, {"verse": 15, "start": 190.36, "end": 203.41, "ta": "பன்னிரண்டாவது மாதத்தின் பன்னிரண்டாம் சேனாபதி ஒத்னியேல் சந்ததியான எல்தாயி என்னும் நெத்தோபாத்தியன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The twelfth captain for the twelfth month was Heldai the Netophathite, of Othniel: and in his course were twenty and four thousand."}, {"verse": 16, "start": 203.41, "end": 216.07, "ta": "இஸ்ரவேல் கோத்திரங்களுக்குத் தலைவர்கள்; ரூபனியருக்குத் தலைவன் சிக்ரியின் குமாரன் எலியேசர்; சிமியோனியருக்கு மாக்காவின் குமாரன் செப்பத்தியா.", "en": "Furthermore over the tribes of Israel: the ruler of the Reubenites was Eliezer the son of Zichri: of the Simeonites, Shephatiah the son of Maachah:"}, {"verse": 17, "start": 216.07, "end": 222.55, "ta": "லேவியருக்கு கேமுவேலின் குமாரன் அஷாபியா; ஆரோன் சந்ததிக்குச் சாதோக்.", "en": "Of the Levites, Hashabiah the son of Kemuel: of the Aaronites, Zadok:"}, {"verse": 18, "start": 222.55, "end": 230.72, "ta": "யூதாவுக்குத் தாவீதின் சகோதரரில் ஒருவனாகிய எலிகூ; இசக்காருக்கு மிகாவேலின் குமாரன் ஒம்ரி.", "en": "Of Judah, Elihu, one of the brethren of David: of Issachar, Omri the son of Michael:"}, {"verse": 19, "start": 230.72, "end": 238.4, "ta": "செபுலோனுக்கு ஒப்தியாவின் குமாரன் இஸ்மாயா; நப்தலிக்கு அஸ்ரியேலின் குமாரன் எரிமோத்.", "en": "Of Zebulun, Ishmaiah the son of Obadiah: of Naphtali, Jerimoth the son of Azriel:"}, {"verse": 20, "start": 238.4, "end": 248.57, "ta": "எப்பிராயீம் புத்திரருக்கு அசசியாவின் குமாரன் ஓசெயா; மனாசேயின் பாதிக்கோத்திரத்திற்குப் பெதாயாவின் குமாரன் யோவேல்.", "en": "Of the children of Ephraim, Hoshea the son of Azaziah: of the half tribe of Manasseh, Joel the son of Pedaiah:"}, {"verse": 21, "start": 248.57, "end": 259.14, "ta": "கிலேயாத்திலுள்ள மனாசேயின் பாதிக்கோத்திரத்திற்குச் சகரியாவின் குமாரன் இத்தோ; பென்யமீனுக்கு அப்னேரின் குமாரன் யாசியேல்.", "en": "Of the half tribe of Manasseh in Gilead, Iddo the son of Zechariah: of Benjamin, Jaasiel the son of Abner:"}, {"verse": 22, "start": 259.14, "end": 267.87, "ta": "தாணுக்கு எரோகாமின் குமாரன் அசாரியேல்; இவர்கள் இஸ்ரவேல் கோத்திரங்களுக்குத் தலைவராயிருந்தார்கள்.", "en": "Of Dan, Azareel the son of Jeroham. These were the princes of the tribes of Israel."}, {"verse": 23, "start": 267.87, "end": 283.32, "ta": "இஸ்ரவேலை வானத்தின் நட்சத்திரங்கள் அத்தனையாய்ப் பெருகப்பண்ணுவேன் என்று கர்த்தர் சொல்லியிருந்தபடியால்; தாவீது இருபது வயதுமுதல் அதற்கு கீழ்ப்பட்டவர்களின் இலக்கத்தைத்தொகையேற்றவில்லை.", "en": "But David took not the number of them from twenty years old and under: because the LORD had said he would increase Israel like to the stars of the heavens."}, {"verse": 24, "start": 283.32, "end": 298.14, "ta": "செருயாவின் குமாரன் யோவாப் எண்ணத்துவக்கியும் முடிக்காதேபோனான்; அதற்காக இஸ்ரவேலின்மேல் கடுங்கோபம் வந்தது; ஆதலால் அந்தத்தொகை தாவீது ராஜாவின் நாளாகமக்கணக்கிலே ஏறவில்லை.", "en": "Joab the son of Zeruiah began to number, but he finished not, because there fell wrath for it against Israel; neither was the number put in the account of the chronicles of king David."}, {"verse": 25, "start": 298.14, "end": 312.87, "ta": "ராஜாவுடைய பொக்கிஷங்களின்மேல் ஆதியேலின் குமாரன் அஸ்மாவேத்தும், பட்டணங்களிலும் கிராமங்களிலும் துருக்கங்களிலுமுள்ள நிலத்தின் வருமான பண்டகசாலைகளின்மேல் உசியாவின் குமாரன் யோனத்தானும்,", "en": "And over the king’s treasures was Azmaveth the son of Adiel: and over the storehouses in the fields, in the cities, and in the villages, and in the castles, was Jehonathan the son of Uzziah:"}, {"verse": 26, "start": 312.87, "end": 319.76, "ta": "நிலத்தைப் பயிரிட வயல்வெளியின் வேலைசெய்கிறவர்களின்மேல் கேலுூப்பின்குமாரன் எஸ்ரியும்,", "en": "And over them that did the work of the field for tillage of the ground was Ezri the son of Chelub:"}, {"verse": 27, "start": 319.76, "end": 331.37, "ta": "திராட்சத்தோட்டங்களின்மேல் ராமாத்தியனான சீமேயும், திராட்சத்தோட்டங்களின் வரத்தாகிய திராட்சரசம் வைக்கும் இடங்களின்மேல் சிப்மியனாகிய சப்தியும்,", "en": "And over the vineyards was Shimei the Ramathite: over the increase of the vineyards for the wine cellars was Zabdi the Shiphmite:"}, {"verse": 28, "start": 331.37, "end": 342.42, "ta": "பள்ளத்தாக்குகளிலுள்ள ஒலிவமரங்களின்மேலும் முசுக்கட்டை விருட்சங்கனின்மேலும் கெதேரியனான பால்கானானும், எண்ணெய்கிடங்குகளின்மேல் யோவாசும்,", "en": "And over the olive trees and the sycomore trees that were in the low plains was Baal-hanan the Gederite: and over the cellars of oil was Joash:"}, {"verse": 29, "start": 342.42, "end": 352.5, "ta": "சாரோனில் மேய்கிற மாடுகளின்மேல் சாரோனியனான சித்ராயும், பள்ளத்தாக்குகளிலுள்ள மாடுகளின்மேல் அத்லாயின் குமாரன் சாப்பாத்தும்,", "en": "And over the herds that fed in Sharon was Shitrai the Sharonite: and over the herds that were in the valleys was Shaphat the son of Adlai:"}, {"verse": 30, "start": 352.5, "end": 359.71, "ta": "ஒட்டகங்களின்மேல் இஸ்மவேலியனாகிய ஓபிலும், கழுதைகளின்மேல் மெரோனோத்தினாகிய எகெதியாவும்,", "en": "Over the camels also was Obil the Ishmaelite: and over the asses was Jehdeiah the Meronothite:"}, {"verse": 31, "start": 359.71, "end": 372.12, "ta": "ஆடுகளின்மேல் ஆகாரியனான யாசிசும் விசாரிப்புக்காரராயிருந்தார்கள்; இவர்களெல்லாரும் தாவீது ராஜாவின்பொருள்களுக்கு விசாரிப்புக்காரராயிருந்தார்கள்.", "en": "And over the flocks was Jaziz the Hagerite. All these were the rulers of the substance which was king David’s."}, {"verse": 32, "start": 372.12, "end": 385.73, "ta": "தாவீதின் சிறிய தகப்பனாகிய யோனத்தான் என்னும் புத்தியும் படிப்புமுள்ள மனுஷன் ஆலோசனைக்காரனாயிருந்தன்; அக்மோனியின் குமாரன் யெகியேல் ராஜாவின் குமாரரோடிருந்தான்.", "en": "Also Jonathan David’s uncle was a counsellor, a wise man, and a scribe: and Jehiel the son of Hachmoni was with the king’s sons:"}, {"verse": 33, "start": 385.73, "end": 394.22, "ta": "அகித்தோப்பேல் ராஜாவுக்கு ஆலோசனைக்காரனாயிருந்தான்; அர்கியனான ஊஷாயி ராஜாவின் தோழனாயிருந்தான்.", "en": "And Ahithophel was the king’s counsellor: and Hushai the Archite was the king’s companion:"}, {"verse": 34, "start": 394.22, "end": 404.87, "ta": "பெனாயாவின் குமாரன் யோய்தாவும் அபியத்தாரும் அகித்தோப்பேலுக் உதவியாயிருந்தார்கள்; யோவாப் ராஜாவின் படைத்தலைவனாயிருந்தான்.", "en": "And after Ahithophel was Jehoiada the son of Benaiah, and Abiathar: and the general of the king’s army was Joab."}]}, "28": {"chapter": 28, "duration": 389.76, "audio_url": "audio_ot/OT13_28.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 32.17, "ta": "கோத்திரங்களின் தலைவரும், ராஜாவைச் சேவிக்கிற வகுப்புகளின் தலைவரும், ஆயிரம்பேருக்கு அதிபதிகளும், நூறுபேருக்கு அதிபதிகளும் ராஜாவுக்கும் ராஜகுமாரருக்கும் உண்டான எல்லா ஆஸ்தியையும் மிருகஜீவன்களையும் விசாரிக்கிற தலைவருமாகிய இஸ்ரவேலின் சகல பிரபுக்களையும், பிரதானிகளையும், பலசாலிகளையும், சகல பராக்கிரமசாலிகளையும் தாவீது எருசலேமிலே கூடிவரச்செய்தான்.", "en": "And David assembled all the princes of Israel, the princes of the tribes, and the captains of the companies that ministered to the king by course, and the captains over the thousands, and captains over the hundreds, and the stewards over all the substance and possession of the king, and of his sons, with the officers, and with the mighty men, and with all the valiant men, unto Jerusalem."}, {"verse": 2, "start": 32.17, "end": 54.34, "ta": "அப்பொழுது ராஜாவாகிய தாவீது: எழுந்திருந்து காலுூன்றி நின்று: என் சகோதரரே, என் ஜனமே, நான் சொல்வதைக் கேளுங்கள்; கர்த்தருடைய உடன்படிக்கைப் பெட்டியும் நமது தேவனுடைய பாதபடியும் தங்குவதற்கு ஒரு ஆலயத்தைக் கட்ட நான் என் மனதிலே நினைத்து, கட்டுகிறதற்கு ஆயத்தமும் பண்ணினேன்.", "en": "Then David the king stood up upon his feet, and said, Hear me, my brethren, and my people: As for me , I had in mine heart to build an house of rest for the ark of the covenant of the LORD , and for the footstool of our God, and had made ready for the building:"}, {"verse": 3, "start": 54.34, "end": 64.41, "ta": "ஆனாலும் தேவன் நீ என் நாமத்திற்கு ஆலயத்தைக் கட்டவேண்டாம்; நீ யுத்த மனுஷனாயிருந்து, ரத்தத்தைச் சிந்தினாய் என்றார்.", "en": "But God said unto me, Thou shalt not build an house for my name, because thou hast been a man of war, and hast shed blood."}, {"verse": 4, "start": 64.41, "end": 92.32, "ta": "இப்போதும் இஸ்ரவேல் அனைத்தின்மேலும் என்றைக்கும் ராஜாவாயிருக்க, இஸ்ரவேலின் தேவனாகிய கர்த்தர் அவன் தகப்பனுடைய வீட்டாரில் எல்லாம் என்னைத் தெரிந்துகொண்டார்; அவர் யூதாவையும் யூதாவின் வம்சத்தில் அவன் தகப்பன் குடும்பத்தையும் தலைமையாக தெரிந்துகொண்டு, என்னை எல்லா இஸ்ரவேலின்மேலும் ராஜாவாக்க, என் தகப்பனுடைய குமாரருக்குள் என்மேல் பிரியம் வைத்தார்.", "en": "Howbeit the LORD God of Israel chose me before all the house of my father to be king over Israel for ever: for he hath chosen Judah to be the ruler; and of the house of Judah, the house of my father; and among the sons of my father he liked me to make me king over all Israel:"}, {"verse": 5, "start": 92.32, "end": 109.06, "ta": "கர்த்தர் எனக்கு அநேகம் குமாரரைத் தந்தருளினார்; ஆனாலும் இஸ்ரவேலை ஆளும் கர்த்தருடைய ராஜ்யபாரத்தின் சிங்காசனத்தின்மேல் உட்காருகிறதற்கு அவர் என்னுடைய எல்லாக் குமாரரிலும் என் குமாரனாகிய சாலொமோனைத் தெரிந்துகொண்டு,", "en": "And of all my sons, (for the LORD hath given me many sons,) he hath chosen Solomon my son to sit upon the throne of the kingdom of the LORD over Israel."}, {"verse": 6, "start": 109.06, "end": 123.71, "ta": "அவர் என்னை நோக்கி: உன் குமாரனாகிய சாலொமோனே என் ஆலயத்தையும் என் பிரகாரங்களையும் கட்டக்கடவன்; அவனை எனக்குக் குமாரனாகத் தெரிந்துகொண்டேன்; நான் அவனுக்குப் பிதாவாயிருப்பேன்.", "en": "And he said unto me, Solomon thy son, he shall build my house and my courts: for I have chosen him to be my son, and I will be his father."}, {"verse": 7, "start": 123.71, "end": 137.28, "ta": "இந்நாளில் நடக்கிறபடியே அவன் என் கற்பனைகளின்படியும் என் நியாயங்களின்படியும் செய்ய உறுதியாயிருப்பானானால், அவன் ராஜ்யபாரத்தை என்றென்றைக்கும் திடப்படுத்துவேன் என்றார்.", "en": "Moreover I will establish his kingdom for ever, if he be constant to do my commandments and my judgments, as at this day."}, {"verse": 8, "start": 137.28, "end": 166.96, "ta": "இப்போதும் நீங்கள் என்றென்றைக்கும் இந்த நல்ல தேசத்தைச் சுதந்தரமாய் அநுபவித்து, உங்களுக்குப்பிறகு அதை உங்கள் பிள்ளைகளுக்குச் சுதந்தமாய்ப் பின்வைக்கும்பொருட்டாக, நீங்கள் உங்கள் தேவனாகிய கர்த்தரின் கற்பனைகளையெல்லாம் கைக்கொண்டு விசாரியுங்கள் என்று கர்த்தரின் சபையாகிய இஸ்ரவேல் அனைத்தின் கண்களுக்குமுன்பாகவும், நமது தேவனுடைய செவிகேட்கவும் உங்களுக்குப் புத்திசொல்லுகிறேன்.", "en": "Now therefore in the sight of all Israel the congregation of the LORD , and in the audience of our God, keep and seek for all the commandments of the LORD your God: that ye may possess this good land, and leave it for an inheritance for your children after you for ever."}, {"verse": 9, "start": 166.96, "end": 191.77, "ta": "என் குமாரனாகிய சாலொமோனே, நீ என் பிதாவின் தேவனை அறிந்து, அவரை உத்தம இருதயத்தோடும் உற்சாக மனதோடும் சேவி; கர்த்தர் எல்லா இருதயங்களையும் ஆராய்ந்து, நினைவுகளின் தோற்றங்களையெல்லாம் அறிகிறார்; நீ அவரைத் தேடினால் உனக்குத் தென்படுவார்; நீ அவரை விட்டுவிட்டால் அவர் உன்னை என்றைக்கும் கைவிடுவார்.", "en": "And thou, Solomon my son, know thou the God of thy father, and serve him with a perfect heart and with a willing mind: for the LORD searcheth all hearts, and understandeth all the imaginations of the thoughts: if thou seek him, he will be found of thee; but if thou forsake him, he will cast thee off for ever."}, {"verse": 10, "start": 191.77, "end": 204.87, "ta": "இப்போதும் எச்சரிக்கையாயிரு; பரிசுத்த ஸ்தலமாக ஒரு ஆலயத்தைக்கட்டுவதற்குக் கர்த்தர் உன்னைத் தெரிந்துகொண்டார்; நீ திடன்கொண்டு அதை நடப்பி என்று சொன்னான்.", "en": "Take heed now; for the LORD hath chosen thee to build an house for the sanctuary: be strong, and do it ."}, {"verse": 11, "start": 204.87, "end": 219.44, "ta": "தாவீது தன் குமாரனாகிய சாலொமோனுக்கு மண்டபமும், அதின் அறைகளும், அதின் பொக்கிஷசாலைகளும், அதின் மேல்வீடுகளும், அதின் உள்ளறைகளும், கிருபாசன ஸ்தானம் இருக்கவேண்டிய மாதிரியையும்,", "en": "Then David gave to Solomon his son the pattern of the porch, and of the houses thereof, and of the treasuries thereof, and of the upper chambers thereof, and of the inner parlours thereof, and of the place of the mercy seat,"}, {"verse": 12, "start": 219.44, "end": 238.97, "ta": "ஆவியினால் தனக்குக் கட்டளையிடப்பட்டபடியெல்லாம் அவன் செய்யவேண்டிய கர்த்தருடைய ஆலயப்பிராகாரங்களும், தேவனுடைய ஆலயத்துப் பொக்கிஷங்களையும், பரிசுத்தமாக நேர்ந்துகொள்ளப்பட்டவைகளின் பொக்கிஷங்களையும் வைக்கும் சகல சுற்றறைகளும் இருக்கவேண்டிய மாதிரியையும்,", "en": "And the pattern of all that he had by the spirit, of the courts of the house of the LORD , and of all the chambers round about, of the treasuries of the house of God, and of the treasuries of the dedicated things:"}, {"verse": 13, "start": 238.97, "end": 254.09, "ta": "ஆசாரியரையும் லேவியரையும் வரிசைகளாக வகுக்கிறதற்கும், கர்த்தருடைய ஆலயப்பணிவிடை வேலை அனைத்திற்கும், கர்த்தருடைய ஆலயத்து வேலையின் பணிமுட்டுகள் அனைத்திற்குமுரிய கட்டளையையும் கொடுத்தான்.", "en": "Also for the courses of the priests and the Levites, and for all the work of the service of the house of the LORD , and for all the vessels of service in the house of the LORD ."}, {"verse": 14, "start": 254.09, "end": 266.88, "ta": "அவன் பற்பல வேலைக்கு வேண்டிய சகல பொற்பாத்திரங்களுக்காக நிறையின்படி பொன்னையும், பற்பல வேலைக்குவேண்டிய சகல வெள்ளிப்பாத்திரங்களுக்காக, நிறையின்படி வெள்ளியையும்,", "en": "He gave of gold by weight for things of gold, for all instruments of all manner of service; silver also for all instruments of silver by weight, for all instruments of every kind of service:"}, {"verse": 15, "start": 266.88, "end": 287.49, "ta": "பொன் விளக்குத்தண்டுகளுக்கும் அவைகளின் பொன் விளக்குகளுக்கும், ஒவ்வொரு விளக்குத்தண்டுக்கும் அதின் விளக்குகளுக்கும் நிறையின்படி வேண்டிய பொன்னையும், வெள்ளி விளக்குத்தண்டுகளில் ஒவ்வொரு விளக்குத்தண்டுக்கும் அதின் விளக்குகளுக்கும் நிறையின்படி வேண்டிய வெள்ளியையும்,", "en": "Even the weight for the candlesticks of gold, and for their lamps of gold, by weight for every candlestick, and for the lamps thereof: and for the candlesticks of silver by weight, both for the candlestick, and also for the lamps thereof, according to the use of every candlestick."}, {"verse": 16, "start": 287.49, "end": 296.95, "ta": "சமுகத்தப்பங்களை வைக்கும் ஒவ்வொரு மேஜைக்கும் நிறையின்படி வேண்டிய பொன்னையும், வெள்ளி மேைஐகளுக்கு வேண்டிய வெள்ளியையும்,", "en": "And by weight he gave gold for the tables of shewbread, for every table; and likewise silver for the tables of silver:"}, {"verse": 17, "start": 296.95, "end": 313.54, "ta": "முள்குறடுகளுக்கும் கலங்களுக்கும் தட்டுகளுக்கும் வேண்டிய பசும்பொன்னையும், பொன் கிண்ணிகளில் ஒவ்வொரு கிண்ணிக்கும் நிறையின்படி வேண்டியதையும், வெள்ளிக்கிண்ணிகளில் ஒவ்வொரு கிண்ணிக்கும் நிறையின்படி வேண்டியதையும்,", "en": "Also pure gold for the fleshhooks, and the bowls, and the cups: and for the golden basons he gave gold by weight for every bason; and likewise silver by weight for every bason of silver:"}, {"verse": 18, "start": 313.54, "end": 328.96, "ta": "தூபங்காட்டும் பீடத்திற்கு நிறையின்படி வேண்டிய புடமிடப்பட்ட பொன்னையும் கொடுத்து, செட்டைகளை விரித்துக் கர்த்தருடைய உடன்படிக்கைப்பெட்டியை மூடும் பொன் கேருபீன்களான வாகனத்தின் மாதிரியையும் கொடுத்து,", "en": "And for the altar of incense refined gold by weight; and gold for the pattern of the chariot of the cherubims, that spread out their wings , and covered the ark of the covenant of the LORD ."}, {"verse": 19, "start": 328.96, "end": 339.97, "ta": "இந்த மாதிரியின்படி சகல வேலைகளும் எனக்குத் தெரியப்படுத்த, இவையெல்லாம் கர்த்தருடைய கரத்தினால் எனக்கு எழுதிக்கொடுக்கப்பட்டது என்றான்.", "en": "All this, said David , the LORD made me understand in writing by his hand upon me, even all the works of this pattern."}, {"verse": 20, "start": 339.97, "end": 366.94, "ta": "தாவீது தன் குமாரனாகிய சாலொமோனை நோக்கி: நீ பலங்கொண்டு தைரியமாயிருந்து, இதை நடப்பி; நீ பயப்படாமலும் கலங்காமலும் இரு; தேவனாகிய கர்த்தர் என்னும் என் தேவன் உன்னோடே இருப்பார்; கர்த்தருடைய ஆலயத்தைக் கட்டுகிறதற்கடுத்த சகல கிரியைகளையும் நீ முடித்துத் தீருமட்டும், அவர் உன்னைவிட்டு விலகவுமாட்டார், உன்னைக் கைவிடவுமாட்டார்.", "en": "And David said to Solomon his son, Be strong and of good courage, and do it: fear not, nor be dismayed: for the LORD God, even my God, will be with thee; he will not fail thee, nor forsake thee, until thou hast finished all the work for the service of the house of the LORD ."}, {"verse": 21, "start": 366.94, "end": 388.26, "ta": "இதோ, தேவனுடைய ஆலயத்துவேலைக்கெல்லாம் ஆசாரியர் அவருடைய வகுப்புகள் இருக்கிறது; அந்த எல்லாக் கிரியைக்கும் சகலவித வேலையிலும் நிபுணரான மனப்பூர்வமுள்ள சகல மனுஷரும், உன் சொற்படியெல்லாம் கேட்கும் பிரபுக்களும், சகல ஜனங்களும் என்னிடத்தில் இருக்கிறார்கள் என்றான்.", "en": "And, behold, the courses of the priests and the Levites, even they shall be with thee for all the service of the house of God: and there shall be with thee for all manner of workmanship every willing skilful man, for any manner of service: also the princes and all the people will be wholly at thy commandment."}]}, "29": {"chapter": 29, "duration": 471.27, "audio_url": "audio_ot/OT13_29.mp3", "total_verses": 30, "verses": [{"verse": 1, "start": 3.8, "end": 22.4, "ta": "பின்பு தாவீதுராஜா சபையார் எல்லாரையும் நோக்கி: தேவன் தெரிந்துகொண்ட என் குமாரனாகிய சாலொமோன் இன்னும் வாலிபனும் இளைஞனுமாயிருக்கிறான்; செய்யவேண்டிய வேலையோ பெரியது; அது ஒரு மனுஷனுக்கு அல்ல, தேவனாகிய கர்த்தருக்குக் கட்டும் அரமனை.", "en": "Furthermore David the king said unto all the congregation, Solomon my son, whom alone God hath chosen, is yet young and tender, and the work is great: for the palace is not for man, but for the LORD God."}, {"verse": 2, "start": 22.4, "end": 52.79, "ta": "நான் என்னாலே இயன்றமட்டும் என் தேவனுடைய ஆலயத்துக்கென்று பொன்வேலைக்குப் பொன்னையும், வெள்ளிவேலைக்கு வெள்ளியையும், வெண்கலவேலைக்கு வெண்கலத்தையும், இரும்புவேலைக்கு இரும்பையும், மரவேலைக்கு மரத்தையும், பதிக்கப்படத்தக்க, அந்தியுள்ள கற்களையும், பலவருணக் கற்களையும், விலையேறப்பெற்ற சகலவித ரத்தினங்களையும், வெண்கற்பாளங்களையும், கோமேதக முதலிய கற்களையும் ஏராளமாகச் சவதரித்தேன்.", "en": "Now I have prepared with all my might for the house of my God the gold for things to be made of gold, and the silver for things of silver, and the brass for things of brass, the iron for things of iron, and wood for things of wood; onyx stones, and stones to be set, glistering stones, and of divers colours, and all manner of precious stones, and marble stones in abundance."}, {"verse": 3, "start": 52.79, "end": 69.49, "ta": "இன்னும் என் தேவனுடைய ஆலயத்தின்மேல் நான் வைத்திருக்கிற வாஞ்சையினால், பரிசுத்த ஆலயத்துக்காக நான் சவதரித்த அனைத்தையும் தவிர, எனக்குச் சொந்தமான பொன்னையும் வெள்ளியையும் என் தேவனுடைய ஆலயத்துக்கென்று கொடுக்கிறேன்.", "en": "Moreover, because I have set my affection to the house of my God, I have of mine own proper good, of gold and silver, which I have given to the house of my God, over and above all that I have prepared for the holy house,"}, {"verse": 4, "start": 69.49, "end": 91.26, "ta": "அறைகளின் சுவர்களை மூடுவதற்காகவும், பொன்வேலைக்குப் பொன்னும், வெள்ளிவேலைக்கு வெள்ளியும் உண்டாயிருக்கிறதற்காகவும், கம்மாளர் செய்யும்வேலை அனைத்திற்காகவும, ஓப்பீரின் தங்கமாகிய மூவாயிரம் தாலந்து தங்கத்தையும், சுத்த வெள்ளியாகிய ஏழாயிரம் தாலந்து வெள்ளியையும் கொடுக்கிறேன்.", "en": "Even three thousand talents of gold, of the gold of Ophir, and seven thousand talents of refined silver, to overlay the walls of the houses withal:"}, {"verse": 5, "start": 91.26, "end": 100.11, "ta": "இப்போதும் உங்களில் இன்றையதினம் கர்த்தருக்குத் தன் கைக்காணிக்கைகளைச் செலுத்த மனப்பூர்வமானவர்கள் யார் என்றான்.", "en": "The gold for things of gold, and the silver for things of silver, and for all manner of work to be made by the hands of artificers. And who then is willing to consecrate his service this day unto the LORD ?"}, {"verse": 6, "start": 100.11, "end": 114.77, "ta": "அப்பொழுது வம்சங்களின் பிரபுக்களும், இஸ்ரவேல் கோத்திரங்களின் பிரபுக்களும், ஆயிரம்பேருக்கு அதிபதிகளும், நூறுபேருக்கு அதிபதிகளும், ராஜாவின் வேலைக்காரராகிய பிரபுக்களும் மனப்பூர்வமாய்,", "en": "Then the chief of the fathers and princes of the tribes of Israel, and the captains of thousands and of hundreds, with the rulers of the king’s work, offered willingly,"}, {"verse": 7, "start": 114.77, "end": 131.1, "ta": "தேவனுடைய ஆலயத்து வேலைக்கு ஐயாயிரம் தாலந்து பொன்னையும், பதினாயிரம் தங்கக்காசையும், பதினாயிரம் தாலந்து வெள்ளியையும், பதினெண்ணாயிரம் தாலந்து வெண்கலத்தையும், லட்சம் தாலந்து இரும்பையும் கொடுத்தார்கள்.", "en": "And gave for the service of the house of God of gold five thousand talents and ten thousand drams, and of silver ten thousand talents, and of brass eighteen thousand talents, and one hundred thousand talents of iron."}, {"verse": 8, "start": 131.1, "end": 142.59, "ta": "யார் கையில் ரத்தினங்கள் இருந்ததோ, அவர்கள் அவைகளையும் கர்த்தருடைய ஆலயத்துப் பொக்கிஷத்திற்கென்று கெர்சோனியனான யெகியேலின் கையிலே கொடுத்தார்கள்.", "en": "And they with whom precious stones were found gave them to the treasure of the house of the LORD , by the hand of Jehiel the Gershonite."}, {"verse": 9, "start": 142.59, "end": 156.73, "ta": "இப்படி மனப்பூர்வமாய்க் கொடுத்ததற்காக ஜனங்கள் சந்தோஷப்பட்டார்கள்; உத்தம இருதயத்தோடே உற்சாகமாய்க் கர்த்தருக்குக் கொடுத்தார்கள்; தாவீது ராஜாவும் மிகவும் சந்தோஷப்பட்டான்.", "en": "Then the people rejoiced, for that they offered willingly, because with perfect heart they offered willingly to the LORD : and David the king also rejoiced with great joy."}, {"verse": 10, "start": 156.73, "end": 172.38, "ta": "ஆகையால் தாவீது சபை அனைத்தின் கண்களுக்கு முன்பாகவும் கர்த்தருக்கு ஸ்தோத்திரம் செலுத்திச் சொன்னது எங்கள் தகப்பனாகிய இஸ்ரவேலின் தேவனாகிய கர்த்தாவே, சதாகாலங்களிலும் தேவரீருக்கு ஸ்தோத்திரம் உண்டாவதாக.", "en": "Wherefore David blessed the LORD before all the congregation: and David said, Blessed be thou, LORD God of Israel our father, for ever and ever."}, {"verse": 11, "start": 172.38, "end": 191.28, "ta": "கர்த்தாவே, மாட்சிமையும் வல்லமையும் மகிமையும் ஜெயமும் மகத்துவமும் உம்முடையவைகள்; வானத்திலும் பூமியிலும் உள்ளவைகளெல்லாம் உம்முடையவைகள்; கர்த்தாவே, ராஜ்யமும் உம்முடையது; தேவரீர் எல்லாருக்கும் தலைவராய் உயர்ந்திருக்கிறீர்.", "en": "Thine, O LORD , is the greatness, and the power, and the glory, and the victory, and the majesty: for all that is in the heaven and in the earth is thine; thine is the kingdom, O LORD , and thou art exalted as head above all."}, {"verse": 12, "start": 191.28, "end": 207.45, "ta": "ஐசுவரியமும் கனமும் உம்மாலே வருகிறது; தேவரீர் எல்லாவற்றையும் ஆளுகிறவர்; உம்முடைய கரத்திலே சத்துவமும் வல்லமையும் உண்டு; எவரையும் மேன்மைப்படுத்தவும் பலப்படுத்தவும் உம்முடைய கரத்தினால் ஆகும்.", "en": "Both riches and honour come of thee, and thou reignest over all; and in thine hand is power and might; and in thine hand it is to make great, and to give strength unto all."}, {"verse": 13, "start": 207.45, "end": 216.15, "ta": "இப்போதும் எங்கள் தேவனே, நாங்கள் உமக்கு ஸ்தோத்திரம் செலுத்தி, உமது மகிமையுள்ள நாமத்தைத் துதிக்கிறோம்.", "en": "Now therefore, our God, we thank thee, and praise thy glorious name."}, {"verse": 14, "start": 216.15, "end": 231.12, "ta": "இப்படி மனப்பூர்வமாய்க் கொடுக்கும் திராணி உண்டாவதற்கு நான் எம்மாத்திரம்? என் ஜனங்கள் எம்மாத்திரம்? எல்லாம் உம்மால் உண்டானது; உமது கரத்திலே வாங்கி உமக்குக் கொடுத்தோம்.", "en": "But who am I, and what is my people, that we should be able to offer so willingly after this sort? for all things come of thee, and of thine own have we given thee."}, {"verse": 15, "start": 231.12, "end": 247.22, "ta": "உமக்கு முன்பாக நாங்கள் எங்களுடைய பிதாக்கள் எல்லாரைப்போலும் அரதேசிகளும் பரதேசிகளுமாயிருக்கிறோம்; பூமியின்மேல் எங்கள் நாட்கள் ஒரு நிழலைப்போல இருக்கிறது; நிலைத்திருப்போம் என்னும் நம்பிக்கையில்லை.", "en": "For we are strangers before thee, and sojourners, as were all our fathers: our days on the earth are as a shadow, and there is none abiding."}, {"verse": 16, "start": 247.22, "end": 263.39, "ta": "எங்கள் தேவனாகிய கர்த்தாவே, உம்முடைய பரிசுத்த நாமத்திற்கென்று உமக்கு ஒரு ஆலயத்தைக் கட்டுகிறதற்கு, நாங்கள் சவதரித்திருக்கிற இந்தப்பொருள்கள் எல்லாம் உமது கரத்திலிருந்து வந்தது; எல்லாம் உம்முடையது.", "en": "O LORD our God, all this store that we have prepared to build thee an house for thine holy name cometh of thine hand, and is all thine own."}, {"verse": 17, "start": 263.39, "end": 284.41, "ta": "என் தேவனே, நீர் இருதயத்தைச் சோதித்து, உத்தம குணத்தில் பிரியமாயிருக்கிறீர் என்பதை அறிவேன்; இவையெல்லாம் நான் உத்தம இருதயத்தோடே மனப்பூர்வமாய்க் கொடுத்தேன்; இப்பொழுது இங்கேயிருக்கிற உம்முடைய ஜனமும் உமக்கு மனப்பூர்வமாய்க் கொடுக்கிறதைக் கண்டு சந்தோஷித்தேன்.", "en": "I know also, my God, that thou triest the heart, and hast pleasure in uprightness. As for me, in the uprightness of mine heart I have willingly offered all these things: and now have I seen with joy thy people, which are present here, to offer willingly unto thee."}, {"verse": 18, "start": 284.41, "end": 300.51, "ta": "ஆபிரகாம் ஈசாக்கு இஸ்ரவேல் என்னும் எங்கள் பிதாக்களின் தேவனாகிய கர்த்தாவே, உமது ஜனத்தின் இருதயத்தில் உண்டான இந்தச் சிந்தையையும் நினைவையும் என்றைக்கும் காத்து, அவர்கள் இருதயத்தை உமக்கு நேராக்கியருளும்.", "en": "O LORD God of Abraham, Isaac, and of Israel, our fathers, keep this for ever in the imagination of the thoughts of the heart of thy people, and prepare their heart unto thee:"}, {"verse": 19, "start": 300.51, "end": 320.24, "ta": "என் குமாரனாகிய சாலொமோன் உம்முடைய கற்பனைகளையும் உம்முடைய சாட்சிகளையும் உம்முடைய கட்டளைகளையும் கைக்கொள்ளும்படிக்கும், இவைகள் எல்லாவற்றையும் செய்து, நான் ஆயத்தம்பண்ணின இந்த அரமனையைக்கட்டும்படிக்கும், அவனுக்கு உத்தம இருதயத்தைத் தந்தருளும் என்றான்.", "en": "And give unto Solomon my son a perfect heart, to keep thy commandments, thy testimonies, and thy statutes, and to do all these things , and to build the palace, for the which I have made provision."}, {"verse": 20, "start": 320.24, "end": 338.91, "ta": "அதின்பின்பு தாவீது சபை அனைத்தையும் நோக்கி: இப்போது உங்கள் தேவனாகிய கர்த்தரை ஸ்தோத்திரியுங்கள் என்றான்; அப்பொழுது சபையார் எல்லாரும் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரை ஸ்தோத்திரித்து, தலை குனிந்து கர்த்தரையும் ராஜாவையும் பணிந்துகொண்டு,", "en": "And David said to all the congregation, Now bless the LORD your God. And all the congregation blessed the LORD God of their fathers, and bowed down their heads, and worshipped the LORD , and the king."}, {"verse": 21, "start": 338.91, "end": 357.06, "ta": "கர்த்தருக்குப் பலியிட்டு, மறுநாளிலே சர்வாங்க தகனபலிகளாக ஆயிரம் காளைகளையும், ஆயிரம் ஆட்டுக்கடாக்களையும், ஆயிரம் ஆட்டுக்குட்டிகளையும், அவைகளுக்கடுத்த பானபலிகளையும் இஸ்ரவேல் அனைத்திற்காகவும் கர்த்தருக்குச் செலுத்தினார்கள்.", "en": "And they sacrificed sacrifices unto the LORD , and offered burnt offerings unto the LORD , on the morrow after that day, even a thousand bullocks, a thousand rams, and a thousand lambs, with their drink offerings, and sacrifices in abundance for all Israel:"}, {"verse": 22, "start": 357.06, "end": 374.97, "ta": "அவர்கள் அன்றையதினம் மிகுந்த சந்தோஷத்தோடு கர்த்தருக்கு முன்பாகப் போஜனபானம்பண்ணி, தாவீதின் குமாரனாகிய சாலொமோனை இரண்டாம்விசை ராஜாவாக்கி, கர்த்தருக்கு முன்பாக அவனை அதிபதியாகவும், சாதோக்கை ஆசாரியனாகவும் அபிஷேகம்பண்ணினார்கள்.", "en": "And did eat and drink before the LORD on that day with great gladness. And they made Solomon the son of David king the second time, and anointed him unto the LORD to be the chief governor, and Zadok to be priest."}, {"verse": 23, "start": 374.97, "end": 390.32, "ta": "அப்படியே சாலொமோன் தன் தகப்பனாகிய தாவீதின் ஸ்தானத்திலே, கர்த்தருடைய சிங்காசனத்தில் ராஜாவாய் வீற்றிருந்து பாக்கியசாலியாயிருந்தான்; இஸ்ரவேலர் எல்லாரும் அவனுக்குக் கீழ்ப்படிந்திருந்தார்கள்.", "en": "Then Solomon sat on the throne of the LORD as king instead of David his father, and prospered; and all Israel obeyed him."}, {"verse": 24, "start": 390.32, "end": 399.69, "ta": "சகல பிரபுக்களும் பராக்கிரமசாலிகளும் தாவீது ராஜாவினுடைய சகல குமாரருங்கூட ராஜாவாகிய சாலொமோனுக்கு அடங்கியிருந்தார்கள்.", "en": "And all the princes, and the mighty men, and all the sons likewise of king David, submitted themselves unto Solomon the king."}, {"verse": 25, "start": 399.69, "end": 413.6, "ta": "இஸ்ரவேலர் எல்லாரும் காணக் கர்த்தர் சாலொமோனை மிகவும் பெரியவனாக்கி, அவனுக்கு முன்னே இஸ்ரவேலில் ராஜாவான ஒருவனுக்கும் இல்லாதிருந்த ராஜரிக மகத்துவத்தை அவனுக்குக் கட்டளையிட்டார்.", "en": "And the LORD magnified Solomon exceedingly in the sight of all Israel, and bestowed upon him such royal majesty as had not been on any king before him in Israel."}, {"verse": 26, "start": 413.6, "end": 420.1, "ta": "இவ்விதமாய் ஈசாயின் குமாரனாகிய தாவீது இஸ்ரவேல் அனைத்துக்கும் ராஜாவாயிருந்தான்.", "en": "Thus David the son of Jesse reigned over all Israel."}, {"verse": 27, "start": 420.1, "end": 430.61, "ta": "அவன் இஸ்ரவேலை அரசாண்ட நாட்கள் நாற்பதுவருஷம்; எப்ரோனிலே ஏழுவருஷமும், எருசலேமிலே முப்பத்துமூன்று வருஷமும் ராஜாவாயிருந்தான்.", "en": "And the time that he reigned over Israel was forty years; seven years reigned he in Hebron, and thirty and three years reigned he in Jerusalem."}, {"verse": 28, "start": 430.61, "end": 441.8, "ta": "அவன் தீர்க்காயுசும் ஐசுவரியமும் மகிமையுமுள்ளவனாய் நல்ல முதிர்வயதிலே மரணமடைந்தபின், அவன் குமாரனாகிய சாலொமோன் அவன் ஸ்தானத்திலே அரசாண்டான்.", "en": "And he died in a good old age, full of days, riches, and honour: and Solomon his son reigned in his stead."}, {"verse": 29, "start": 441.8, "end": 456.54, "ta": "தாவீது ராஜாவினுடைய ஆதியோடந்தமான நடபடிகளும், அவன் அரசாண்ட விபரமும், அவனுடைய வல்லமையும், அவனுக்கும் இஸ்ரவேலுக்கும், அந்தந்த தேசங்களின் ராஜ்யங்கள் அனைத்துக்கும் நடந்த காலசம்பவங்களும்,", "en": "Now the acts of David the king, first and last, behold, they are written in the book of Samuel the seer, and in the book of Nathan the prophet, and in the book of Gad the seer,"}, {"verse": 30, "start": 456.54, "end": 469.77, "ta": "ஞானதிருஷ்டிக்காரனாகிய சாமுவேலின் பிரபந்தத்திலும், தீர்க்கதரிசியாகிய நாத்தானின் பிரபந்தத்திலும், ஞானதிருஷ்டிக்காரனாகிய காத்தின் பிரபந்தத்திலும் எழுதியிருக்கிறது.", "en": "With all his reign and his might, and the times that went over him, and over Israel, and over all the kingdoms of the countries."}]}}});
} else {
  window.BIBLE_CACHE = window.BIBLE_CACHE || {};
  window.BIBLE_CACHE['13'] = {"id": 13, "testament": "OT", "code": "1CH", "name_en": "1 Chronicles", "name_ta": "1 நாளாகமம்", "category": "History", "category_ta": "சரித்திரம்", "total_chapters": 29, "chapters": {"1": {"chapter": 1, "duration": 480.21, "audio_url": "audio_ot/OT13_01.mp3", "total_verses": 54, "verses": [{"verse": 1, "start": 4.8, "end": 7.59, "ta": "ஆதாம், சேத், ஏனோஸ்,", "en": "Adam, Sheth, Enosh,"}, {"verse": 2, "start": 7.59, "end": 10.79, "ta": "கேனான், மகலாலெயேல், யாரேத்", "en": "Kenan, Mahalaleel, Jered,"}, {"verse": 3, "start": 10.79, "end": 14.58, "ta": "ஏனோக்கு, மெத்தூசலா, லாமேக்கு,", "en": "Henoch, Methuselah, Lamech,"}, {"verse": 4, "start": 14.58, "end": 18.47, "ta": "நோவா, சேம், காம், யாப்பேத்,", "en": "Noah, Shem, Ham, and Japheth."}, {"verse": 5, "start": 18.47, "end": 30.44, "ta": "யாப்பேத்தின் குமாரர், கோமேர், மாகோகு, மாதாய், யாவான், தூபால், மேசேக்கு, தீராஸ் என்பவர்கள்.", "en": "The sons of Japheth; Gomer, and Magog, and Madai, and Javan, and Tubal, and Meshech, and Tiras."}, {"verse": 6, "start": 30.44, "end": 38.12, "ta": "கோமரின் குமாரர், அஸ்கினாஸ், ரீப்பாத்து, தொகர்மா என்பவர்கள்.", "en": "And the sons of Gomer; Ashchenaz, and Riphath, and Togarmah."}, {"verse": 7, "start": 38.12, "end": 42.31, "ta": "யாவானின் குமாரர், எலிசா, தர்ஷீஸ்,", "en": "And the sons of Javan; Elishah, and Tarshish, Kittim, and Dodanim."}, {"verse": 8, "start": 42.31, "end": 54.49, "ta": "கித்தீம், தொதானீம் என்பவர்கள். காமின் குமாரர், கூஷ், மிஸ்ராயீம், பூத், கானான் என்பவர்கள்.", "en": "The sons of Ham; Cush, and Mizraim, Put, and Canaan."}, {"verse": 9, "start": 54.49, "end": 68.35, "ta": "கூஷின் குமாரர், சேபா, விலா, சப்தா, ராமா, சப்திகா என்பவர்கள்; ராமாவின் குமாரர், சேபா, திதான் என்பவர்கள்.", "en": "And the sons of Cush; Seba, and Havilah, and Sabta, and Raamah, and Sabtecha. And the sons of Raamah; Sheba, and Dedan."}, {"verse": 10, "start": 68.35, "end": 75.84, "ta": "கூஷ் நிம்ரோதைப் பெற்றான்; இவன் பூமியிலே பராக்கிரமசாலியானான்.", "en": "And Cush begat Nimrod: he began to be mighty upon the earth."}, {"verse": 11, "start": 75.84, "end": 84.12, "ta": "மிஸ்ராயீம் லுூதீமியரையும், ஆனாமியரையும், லெகாபியரையும், நப்தூகியரையும்,", "en": "And Mizraim begat Ludim, and Anamim, and Lehabim, and Naphtuhim,"}, {"verse": 12, "start": 84.12, "end": 93.1, "ta": "பத்ரூசியரையும், பெலிஸ்தரைப் பெற்ற கஸ்லுூகியரையும், கப்தோரியரையும் பெற்றான்.", "en": "And Pathrusim, and Casluhim, (of whom came the Philistines,) and Caphthorim."}, {"verse": 13, "start": 93.1, "end": 98.38, "ta": "கானான் தன் மூத்தமகனாகிய சீதோனையும், கேத்தையும்,", "en": "And Canaan begat Zidon his firstborn, and Heth,"}, {"verse": 14, "start": 98.38, "end": 103.47, "ta": "எபூசியரையும், மோரியாயும், கிர்காசியரையும்,", "en": "The Jebusite also, and the Amorite, and the Girgashite,"}, {"verse": 15, "start": 103.47, "end": 108.16, "ta": "ஏவியரையும், அர்கீயரையும், சீநியரையும்,", "en": "And the Hivite, and the Arkite, and the Sinite,"}, {"verse": 16, "start": 108.16, "end": 115.15, "ta": "அர்வாதியரையும், செமரியரையும், காமாத்தியரையும் பெற்றான்.", "en": "And the Arvadite, and the Zemarite, and the Hamathite."}, {"verse": 17, "start": 115.15, "end": 128.32, "ta": "சேமின் குமாரர், ஏலாம், அசூர், அர்பக்சாத், லுூத், ஆராம், ஊத்ஸ், கூல், கேத்தெர், மேசக் என்பவர்கள்.", "en": "The sons of Shem; Elam, and Asshur, and Arphaxad, and Lud, and Aram, and Uz, and Hul, and Gether, and Meshech."}, {"verse": 18, "start": 128.32, "end": 135.0, "ta": "அர்பக்சாத் சாலாவைப் பெற்றான்; சாலா ஏபேரைப் பெற்றான்.", "en": "And Arphaxad begat Shelah, and Shelah begat Eber."}, {"verse": 19, "start": 135.0, "end": 150.37, "ta": "ஏபேருக்கு இரண்டு குமாரர் பிறந்தார்கள்; ஒருவன் பேர் பேலேகு, ஏனெனில் அவன் நாட்களில் பூமி பகுக்கப்பட்டது; அவன் சகோதரன் பேர் யொக்தான்.", "en": "And unto Eber were born two sons: the name of the one was Peleg; because in his days the earth was divided: and his brother’s name was Joktan."}, {"verse": 20, "start": 150.37, "end": 158.25, "ta": "யொக்தான் அல்மோதாதையும், சாலேப்பையும், ஆசர்மாவேத்தையும், யேராகையும்,", "en": "And Joktan begat Almodad, and Sheleph, and Hazarmaveth, and Jerah,"}, {"verse": 21, "start": 158.25, "end": 162.84, "ta": "அதோராமையும், ஊசாலையும், திக்லாவையும்,", "en": "Hadoram also, and Uzal, and Diklah,"}, {"verse": 22, "start": 162.84, "end": 167.43, "ta": "ஓபாலையும், அபிமாவேலையும், சேபாவையும்,", "en": "And Ebal, and Abimael, and Sheba,"}, {"verse": 23, "start": 167.43, "end": 177.9, "ta": "ஓப்பீரையும், ஆவிலாவையும், யோபாபையும் பெற்றான்; இவர்கள் எல்லாரும் யொக்தானின் குமாரர்.", "en": "And Ophir, and Havilah, and Jobab. All these were the sons of Joktan."}, {"verse": 24, "start": 177.9, "end": 181.09, "ta": "சேம், அர்பக்சாத், சாலா,", "en": "Shem, Arphaxad, Shelah,"}, {"verse": 25, "start": 181.09, "end": 183.99, "ta": "ஏபேர், பேலேகு, ரெகூ,", "en": "Eber, Peleg, Reu,"}, {"verse": 26, "start": 183.99, "end": 187.18, "ta": "செரூகு, நாகோர், தேராகு,", "en": "Serug, Nahor, Terah,"}, {"verse": 27, "start": 187.18, "end": 189.48, "ta": "ஆபிராமாகிய ஆபிரகாம்,", "en": "Abram; the same is Abraham."}, {"verse": 28, "start": 189.48, "end": 195.86, "ta": "ஆபிரகாமின் குமாரர், ஈசாக்கு, இஸ்மவேல் என்பவர்கள்.", "en": "The sons of Abraham; Isaac, and Ishmael."}, {"verse": 29, "start": 195.86, "end": 206.04, "ta": "இவர்களுடைய சந்ததிகளாவன: இஸ்மவேலின் மூத்த குமாரனாகிய நெபாயோத், கேதார், அத்பியேல், மிப்சாம்,", "en": "These are their generations: The firstborn of Ishmael, Nebaioth; then Kedar, and Adbeel, and Mibsam,"}, {"verse": 30, "start": 206.04, "end": 210.73, "ta": "மிஷ்மா, தூமா, மாசா, ஆதாத், தேமா,", "en": "Mishma, and Dumah, Massa, Hadad, and Tema,"}, {"verse": 31, "start": 210.73, "end": 219.21, "ta": "யெத்தூர், நாபீஸ், கேத்மா என்பவர்கள்; இவர்கள் இஸ்மவேலின் குமாரர்.", "en": "Jetur, Naphish, and Kedemah. These are the sons of Ishmael."}, {"verse": 32, "start": 219.21, "end": 239.16, "ta": "ஆபிரகாமின் மறுமனையாட்டியாகிய கேத்தூராள் பெற்ற குமாரர், சிம்ரான், யக்ஷான், மேதான், மீதியான், இஸ்பாக், சூவா என்பவர்கள்; யக்ஷானின் குமாரர், சேபா, தேதான் என்பவர்கள்.", "en": "Now the sons of Keturah, Abraham’s concubine: she bare Zimran, and Jokshan, and Medan, and Midian, and Ishbak, and Shuah. And the sons of Jokshan; Sheba, and Dedan."}, {"verse": 33, "start": 239.16, "end": 253.23, "ta": "மீதியானின் குமாரர், ஏப்பா, ஏப்பேர், ஆனோக்கு, அபீதா, எல்தாகா என்பவர்கள்; இவர்கள் எல்லாரும் கேத்துராளின் குமாரர்.", "en": "And the sons of Midian; Ephah, and Epher, and Henoch, and Abida, and Eldaah. All these are the sons of Keturah."}, {"verse": 34, "start": 253.23, "end": 262.21, "ta": "ஆபிரகாம் ஈசாக்கைப் பெற்றான்; ஈசாக்கின் குமாரர், ஏசா இஸ்ரவேல் என்பவர்கள்.", "en": "And Abraham begat Isaac. The sons of Isaac; Esau and Israel."}, {"verse": 35, "start": 262.21, "end": 271.69, "ta": "ஏசாவின் குமாரர், எலீப்பாஸ், ரெகுவேல், எயூஷ், யாலாம், கோராகு என்பவர்கள்.", "en": "The sons of Esau; Eliphaz, Reuel, and Jeush, and Jaalam, and Korah."}, {"verse": 36, "start": 271.69, "end": 283.56, "ta": "எலிப்பாசின் குமாரர், தேமான், ஓமார், செப்பி, கத்தாம், கேனாஸ், திம்னா, அமலேக்கு என்பவர்கள்.", "en": "The sons of Eliphaz; Teman, and Omar, Zephi, and Gatam, Kenaz, and Timna, and Amalek."}, {"verse": 37, "start": 283.56, "end": 291.44, "ta": "ரெகுவேலின் குமாரர், நகாத், சேராகு, சம்மா, மீசா என்பவர்கள்.", "en": "The sons of Reuel; Nahath, Zerah, Shammah, and Mizzah."}, {"verse": 38, "start": 291.44, "end": 303.01, "ta": "சேயீரின் குமாரர், லோத்தான், சோபால், சிபியோன், ஆனா, தீசோன், எத்சேர், தீசான் என்பவர்கள்.", "en": "And the sons of Seir; Lotan, and Shobal, and Zibeon, and Anah, and Dishon, and Ezer, and Dishan."}, {"verse": 39, "start": 303.01, "end": 313.19, "ta": "லோத்தானின் குமாரர், ஓரி, ஓமாம் என்பவர்கள்; லோத்தானின் சகோதரி திம்னாள் என்பவர்கள்.", "en": "And the sons of Lotan; Hori, and Homam: and Timna was Lotan’s sister."}, {"verse": 40, "start": 313.19, "end": 327.86, "ta": "சோபாலின் குமாரர், அல்வான், மானகாத், ஏபால், செப்போ, ஓனாம் என்பவர்கள்; சிபியோனின் குமாரர், அயா, ஆனாகு என்பவர்கள்.", "en": "The sons of Shobal; Alian, and Manahath, and Ebal, Shephi, and Onam. And the sons of Zibeon; Aiah, and Anah."}, {"verse": 41, "start": 327.86, "end": 340.63, "ta": "ஆனாகின் குமாரரில் ஒருவன் திஷோன் என்பவன்; திஷோனின் குமாரர், அம்ராம், எஸ்பான் இத்தரான், கெரான் என்பவர்கள்.", "en": "The sons of Anah; Dishon. And the sons of Dishon; Amram, and Eshban, and Ithran, and Cheran."}, {"verse": 42, "start": 340.63, "end": 353.6, "ta": "ஏத்சேரின் குமாரர், பில்கான், சகவான், யாக்கான் என்பவர்கள்; திஷானின் குமாரர், ஊத்ஸ், அரான் என்பவர்கள்.", "en": "The sons of Ezer; Bilhan, and Zavan, and Jakan. The sons of Dishan; Uz, and Aran."}, {"verse": 43, "start": 353.6, "end": 370.06, "ta": "இஸ்ரவேல் புத்திரரை ஒரு ராஜா ஆளாததற்கு முன்னே, ஏதோம் தேசத்தில் அரசாண்ட ராஜாக்களானவர்கள் பயோரின குமாரன் பேலா என்பவன்; இவன் பட்டணத்தின் பேர் தின்காபா.", "en": "Now these are the kings that reigned in the land of Edom before any king reigned over the children of Israel; Bela the son of Beor: and the name of his city was Dinhabah."}, {"verse": 44, "start": 370.06, "end": 379.34, "ta": "பேலா மரித்தபின் போஸ்ரா ஊரானாகிய சேராகின் குமாரன் யோபாப் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And when Bela was dead, Jobab the son of Zerah of Bozrah reigned in his stead."}, {"verse": 45, "start": 379.34, "end": 388.32, "ta": "யோபாப் மரித்தபின், தேமானியரின் தேசத்தானாகிய ஊசாம் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And when Jobab was dead, Husham of the land of the Temanites reigned in his stead."}, {"verse": 46, "start": 388.32, "end": 405.28, "ta": "ஊசாம் மரித்தபின், பேதாதின் குமாரன் ஆதாத் அவன் ஸ்தானத்தில் ராஜாவானான், இவன் மீதியானியரை மோவாபின் நாட்டிலே முறிய அடித்தவன்; இவன் பட்டணத்தின்பேர் ஆவீத்.", "en": "And when Husham was dead, Hadad the son of Bedad, which smote Midian in the field of Moab, reigned in his stead: and the name of his city was Avith."}, {"verse": 47, "start": 405.28, "end": 413.56, "ta": "ஆதாத் மரித்தபின், மஸ்ரேக்கா ஊரானாகிய சம்லா அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And when Hadad was dead, Samlah of Masrekah reigned in his stead."}, {"verse": 48, "start": 413.56, "end": 422.54, "ta": "சம்லா மரித்தபின், நதியோரமான ரேகோபோத்தானாகிய சவுல் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And when Samlah was dead, Shaul of Rehoboth by the river reigned in his stead."}, {"verse": 49, "start": 422.54, "end": 431.22, "ta": "சவுல் மரித்தபின், அக்போரின் குமாரன் பாகாலானான் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "And when Shaul was dead, Baal-hanan the son of Achbor reigned in his stead."}, {"verse": 50, "start": 431.22, "end": 450.38, "ta": "பாகாலானான் மரித்தபின், ஆதாத், அவன் ஸ்தானத்தில் ராஜாவானான்; இவன் பட்டணத்தின்பேர் பாகி; மேசகாபின் குமாரத்தியாகிய மாத்திரேத்தின் குமாரனான அவன் மனைவியின் பேர் மெகேதபேல்.", "en": "And when Baal-hanan was dead, Hadad reigned in his stead: and the name of his city was Pai; and his wife’s name was Mehetabel, the daughter of Matred, the daughter of Mezahab."}, {"verse": 51, "start": 450.38, "end": 461.35, "ta": "ஆதாத் மரித்தபின், ஏதோமில் ஏற்பட்ட பிரபுக்களானவர்கள்; திம்னா பிரபு, அல்யா பிரபு, எதேத் பிரபு,", "en": "Hadad died also. And the dukes of Edom were; duke Timnah, duke Aliah, duke Jetheth,"}, {"verse": 52, "start": 461.35, "end": 466.34, "ta": "அகோலிபாமா பிரபு, ஏலா பிரபு, பினோன் பிரபு,", "en": "Duke Aholibamah, duke Elah, duke Pinon,"}, {"verse": 53, "start": 466.34, "end": 471.53, "ta": "கேனாஸ் பிரபு, தேமான் பிரபு, மிப்சார் பிரபு,", "en": "Duke Kenaz, duke Teman, duke Mibzar,"}, {"verse": 54, "start": 471.53, "end": 478.71, "ta": "மக்தியேல் பிரபு, ஈராம் பிரபு, இவர்களே ஏதோமின் பிரபுக்கள்.", "en": "Duke Magdiel, duke Iram. These are the dukes of Edom."}]}, "2": {"chapter": 2, "duration": 539.52, "audio_url": "audio_ot/OT13_02.mp3", "total_verses": 55, "verses": [{"verse": 1, "start": 3.8, "end": 11.83, "ta": "இஸ்ரவேலின் குமாரர், ரூபன், சிமியோன், லேவி, யூதா, இசக்கார், செபுலோன்,", "en": "These are the sons of Israel; Reuben, Simeon, Levi, and Judah, Issachar, and Zebulun,"}, {"verse": 2, "start": 11.83, "end": 19.23, "ta": "தாண், யோசேப்பு, பென்யமீன், நப்தலி, காத், ஆசேர் என்பவர்கள்.", "en": "Dan, Joseph, and Benjamin, Naphtali, Gad, and Asher."}, {"verse": 3, "start": 19.23, "end": 43.31, "ta": "யூதாவின் குமாரர், ஏர், ஓனான், சேலா என்பவர்கள்; இந்த மூன்று குமாரர் சூவாவின் மகளான கானான் ஸ்திரீயினிடத்தில் அவனுக்குப் பிறந்தவர்கள்; ஏர் என்னும் யூதாவின் மூத்த குமாரன் கர்த்தரின் பார்வைக்குப் பொல்லாதவனானபடியால் அவர் அவனைக் கொன்றுபோட்டார்.", "en": "The sons of Judah; Er, and Onan, and Shelah: which three were born unto him of the daughter of Shua the Canaanitess. And Er, the firstborn of Judah, was evil in the sight of the LORD ; and he slew him."}, {"verse": 4, "start": 43.31, "end": 53.78, "ta": "அவன் மருமகளாகிய தாமார் அவனுக்கு பாரேசையும் சேராவையும் பெற்றாள்; யூதாவின் குமாரர் எல்லாரும் ஐந்துபேர்.", "en": "And Tamar his daughter in law bare him Pharez and Zerah. All the sons of Judah were five."}, {"verse": 5, "start": 53.78, "end": 59.1, "ta": "பாரேசின் குமாரர், எஸ்ரோன், ஆமூல் என்பவர்கள்.", "en": "The sons of Pharez; Hezron, and Hamul."}, {"verse": 6, "start": 59.1, "end": 68.84, "ta": "சேராவின் குமாரர் எல்லாரும், சிம்ரி, ஏத்தான், ஏமான், கல்கோல், தாரா என்னும் ஐந்துபேர்.", "en": "And the sons of Zerah; Zimri, and Ethan, and Heman, and Calcol, and Dara: five of them in all."}, {"verse": 7, "start": 68.84, "end": 78.94, "ta": "சாபத்தீடான விஷயத்திலே துரோகம்பண்ணி இஸ்ரவேலைக் கலங்கப்பண்ணின ஆகார் என்பவன், கர்மீ புத்திரரில் ஒருவன்.", "en": "And the sons of Carmi; Achar, the troubler of Israel, who transgressed in the thing accursed."}, {"verse": 8, "start": 78.94, "end": 83.18, "ta": "ஏத்தானின் குமாரர் அசரியா முதலானவர்கள்.", "en": "And the sons of Ethan; Azariah."}, {"verse": 9, "start": 83.18, "end": 90.67, "ta": "எஸ்ரோனுககுப் பிறந்த குமாரர், யெர்மெயேல், ராம், கெலுபா என்பவர்கள்.", "en": "The sons also of Hezron, that were born unto him; Jerahmeel, and Ram, and Chelubai."}, {"verse": 10, "start": 90.67, "end": 99.69, "ta": "ராம் அம்மினதாபைப் பெற்றான்; அம்மினதாப் யூதா புத்திரரின் பிரபுவாகிய நகசோனைப் பெற்றான்.", "en": "And Ram begat Amminadab; and Amminadab begat Nahshon, prince of the children of Judah;"}, {"verse": 11, "start": 99.69, "end": 105.65, "ta": "நகசோன் சல்மாவைப் பெற்றான்; சல்மா போவாசைப் பெற்றான்.", "en": "And Nahshon begat Salma, and Salma begat Boaz,"}, {"verse": 12, "start": 105.65, "end": 111.33, "ta": "போவாஸ் ஓபேதைப் பெற்றான்; ஓபேத் ஈசாயைப் பெற்றான்.", "en": "And Boaz begat Obed, and Obed begat Jesse,"}, {"verse": 13, "start": 111.33, "end": 122.24, "ta": "ஈசாய் தன் மூத்த குமாரன் எலியாபையும், அபினதாப் என்னும் இரண்டாம் குமாரனையும், சிம்மா என்னும் மூன்றாம் குமாரனையும்,", "en": "And Jesse begat his firstborn Eliab, and Abinadab the second, and Shimma the third,"}, {"verse": 14, "start": 122.24, "end": 129.19, "ta": "நெதனயேல் என்னும் நாலாம் குமாரனையும், ரதாயி என்னும் ஐந்தாம் குமாரனையும்,", "en": "Nethaneel the fourth, Raddai the fifth,"}, {"verse": 15, "start": 129.19, "end": 137.22, "ta": "ஓத்சேம் என்னும் ஆறாம் குமாரனையும், தாவீது என்னும் ஏழாம் குமாரனையும் பெற்றான்.", "en": "Ozem the sixth, David the seventh:"}, {"verse": 16, "start": 137.22, "end": 149.85, "ta": "அவர்கள் சகோதரிகள் செருயாள், அபிகாயில் என்பவர்கள்; செருயாளின் குமாரர், அபிசாய், யோவாப், ஆசகேல் என்னும் மூன்றுபேர்.", "en": "Whose sisters were Zeruiah, and Abigail. And the sons of Zeruiah; Abishai, and Joab, and Asahel, three."}, {"verse": 17, "start": 149.85, "end": 158.42, "ta": "அபிகாயில் அமாசாவைப் பெற்றாள்; அமாசாவின் தகப்பன் இஸ்மவேலியனாகிய யெத்தேர் என்பவன்.", "en": "And Abigail bare Amasa: and the father of Amasa was Jether the Ishmeelite."}, {"verse": 18, "start": 158.42, "end": 170.96, "ta": "எஸ்ரோனின் குமாரன் காலேப் எரீயோத் என்னப்பட்ட தன் பெண்ஜாதியாகிய அசுபாளாலே பெற்ற குமாரர், ஏசேர், சோபாப், அர்தோன் என்பவர்கள்.", "en": "And Caleb the son of Hezron begat children of Azubah his wife, and of Jerioth: her sons are these; Jesher, and Shobab, and Ardon."}, {"verse": 19, "start": 170.96, "end": 180.07, "ta": "அசுபாள் சென்றுபோனபின் காலேப் எப்ராத்தை விவாகம்பண்ணினான்; இவள் அவனுக்கு ஊரைப் பெற்றாள்.", "en": "And when Azubah was dead, Caleb took unto him Ephrath, which bare him Hur."}, {"verse": 20, "start": 180.07, "end": 185.66, "ta": "ஊர் ஊரியைப் பெற்றான்; ஊரி பெசலெயேலைப் பெற்றான்.", "en": "And Hur begat Uri, and Uri begat Bezaleel."}, {"verse": 21, "start": 185.66, "end": 201.54, "ta": "பிற்பாடு, எஸ்ரோன் அறுபது வயதானபோது கிலெயாத்தின் தகப்பனாகிய மாகீரின் குமாரத்தியை விவாகம்பண்ணி, அவளிடத்தில் பிரவேசித்தான்; இவள் அவனுக்குச் செகூபைப் பெற்றாள்.", "en": "And afterward Hezron went in to the daughter of Machir the father of Gilead, whom he married when he was threescore years old; and she bare him Segub."}, {"verse": 22, "start": 201.54, "end": 210.74, "ta": "செகூப் யாவீரைப் பெற்றான்; இவனுக்குக் கீலேயாத் தேசத்தில் இருபத்துமூன்று ஊர்கள் இருந்தது.", "en": "And Segub begat Jair, who had three and twenty cities in the land of Gilead."}, {"verse": 23, "start": 210.74, "end": 228.69, "ta": "கேசூரையும் ஆராமையும் யாவீரின் கிராமங்களையும், கேனாத்திலுள்ள கிராமங்களாகிய அறுபது ஊர்களையும் அவர்கள் கையிலே வாங்கினார்கள்; இவர்கள் எல்லாரும் கிலெயாத்தின் தகப்பனாகிய மாகீரின் குமாரர்.", "en": "And he took Geshur, and Aram, with the towns of Jair, from them, with Kenath, and the towns thereof, even threescore cities. All these belonged to the sons of Machir the father of Gilead."}, {"verse": 24, "start": 228.69, "end": 241.95, "ta": "காலேபின் ஊரான எப்ராத்தாவில் எஸ்ரோன் இறந்துபோனபின், எஸ்ரோனின் பெண்ஜாதியாகிய அபியாள் அவனுக்குத் தெக்கொவாவின் தகப்பனாகிய அசூரைப் பெற்றாள்.", "en": "And after that Hezron was dead in Caleb-ephratah, then Abiah Hezron’s wife bare him Ashur the father of Tekoa."}, {"verse": 25, "start": 241.95, "end": 254.22, "ta": "எஸ்ரோனுக்கு முதற்பிறந்த யெர்மெயேலின் குமாரர், ராம் என்னும் மூத்தவனும், பூனா, ஓரென், ஓத்சேம், அகியா என்பவர்களுமே.", "en": "And the sons of Jerahmeel the firstborn of Hezron were, Ram the firstborn, and Bunah, and Oren, and Ozem, and Ahijah."}, {"verse": 26, "start": 254.22, "end": 263.42, "ta": "அத்தாராள் என்னும் பேருள்ள வேறொரு மனைவியும் யெர்மெயேலுக்கு இருந்தாள்; இவள் ஓனாமின் தாய்.", "en": "Jerahmeel had also another wife, whose name was Atarah; she was the mother of Onam."}, {"verse": 27, "start": 263.42, "end": 271.9, "ta": "யெர்மெயேலுக்கு முதற்பிறந்த ராமின் குமாரர், மாஸ், யாமின், எக்கேர் என்பவர்கள்.", "en": "And the sons of Ram the firstborn of Jerahmeel were, Maaz, and Jamin, and Eker."}, {"verse": 28, "start": 271.9, "end": 282.37, "ta": "ஓனாமின் குமாரர், சம்மாய், யாதா என்பவர்கள்; சம்மாயின் குமாரர், நாதாப், அபிசூர் என்பவர்கள்.", "en": "And the sons of Onam were, Shammai, and Jada. And the sons of Shammai; Nadab, and Abishur."}, {"verse": 29, "start": 282.37, "end": 291.21, "ta": "அபிசூருடைய மனைவியின் பேர் அபியாயேல்; அவள் அவனுக்கு அக்பானையும் மோளிதையும் பெற்றாள்.", "en": "And the name of the wife of Abishur was Abihail, and she bare him Ahban, and Molid."}, {"verse": 30, "start": 291.21, "end": 300.5, "ta": "நாதாபின் குமாரர், சேலேத், அப்பாயிம் என்பவர்கள்; சேலேத் புத்திரரில்லாமல் மரித்தான்.", "en": "And the sons of Nadab; Seled, and Appaim: but Seled died without children."}, {"verse": 31, "start": 300.5, "end": 311.59, "ta": "அப்பாயிமின் குமாரர் இஷி முதலானவர்கள்; இஷியின் குமாரர் சேசான் முதலானவர்கள்; சேசானின் குமாரத்தி அக்லாய்.", "en": "And the sons of Appaim; Ishi. And the sons of Ishi; Sheshan. And the children of Sheshan; Ahlai."}, {"verse": 32, "start": 311.59, "end": 322.96, "ta": "சம்மாயின் சகோதரனாகிய யாதாவின் குமாரர், யெத்தெர், யோனத்தான் என்பவர்கள்; யெத்தெர் குமாரரில்லாமல் மரித்தான்.", "en": "And the sons of Jada the brother of Shammai; Jether, and Jonathan: and Jether died without children."}, {"verse": 33, "start": 322.96, "end": 331.35, "ta": "யோனத்தானின் குமாரர், பேலேத்சாசா என்பவர்கள்; இவர்கள் யெர்மெயேலின் புத்திரர்.", "en": "And the sons of Jonathan; Peleth, and Zaza. These were the sons of Jerahmeel."}, {"verse": 34, "start": 331.35, "end": 343.53, "ta": "சேசானுக்குக் குமாரத்திகளேயன்றி குமாரர்கள் இல்லை; சேசானுக்கு யர்கா என்னும் பேருள்ள எகிப்திய வேலைக்காரன் ஒருவன் இருந்தான்.", "en": "Now Sheshan had no sons, but daughters. And Sheshan had a servant, an Egyptian, whose name was Jarha."}, {"verse": 35, "start": 343.53, "end": 354.26, "ta": "சேசான் தன் குமாரத்தியைத் தன் வேலைக்காரனாகிய யாகாவுக்குக் கொடுத்தான்; அவள் அவனுக்கு அத்தாயியைப் பெற்றாள்.", "en": "And Sheshan gave his daughter to Jarha his servant to wife; and she bare him Attai."}, {"verse": 36, "start": 354.26, "end": 360.58, "ta": "அத்தாயி நாதானைப் பெற்றான். நாதான் சாபாதைப் பெற்றான்.", "en": "And Attai begat Nathan, and Nathan begat Zabad,"}, {"verse": 37, "start": 360.58, "end": 366.62, "ta": "சாபாத் எப்லாலைப் பெற்றான்; எப்லால் ஒபேதைப் பெற்றான்.", "en": "And Zabad begat Ephlal, and Ephlal begat Obed,"}, {"verse": 38, "start": 366.62, "end": 372.31, "ta": "ஓபேத் ஏகூவைப் பெற்றான்; ஏகூ அசரியாவைப் பெற்றான்.", "en": "And Obed begat Jehu, and Jehu begat Azariah,"}, {"verse": 39, "start": 372.31, "end": 378.71, "ta": "அசரியா ஏலேத்சைப் பெற்றான்; ஏலேத்ஸ் எலெயாசாவைப் பெற்றான்.", "en": "And Azariah begat Helez, and Helez begat Eleasah,"}, {"verse": 40, "start": 378.71, "end": 385.3, "ta": "எலெயாசா சிஸ்மாயைப் பெற்றான்; சிஸ்மாய் சல்லுூமைப் பெற்றான்.", "en": "And Eleasah begat Sisamai, and Sisamai begat Shallum,"}, {"verse": 41, "start": 385.3, "end": 392.24, "ta": "சல்லுூம் எக்கமியாவைப் பெற்றான்; எக்கமியா எலிசாமாவைப் பெற்றான்.", "en": "And Shallum begat Jekamiah, and Jekamiah begat Elishama."}, {"verse": 42, "start": 392.24, "end": 405.41, "ta": "யெர்மெயேலின் சகோதரனாகிய காலேபின் குமாரர், சீப்பின் தகப்பனாகிய மேசா என்னும் முதற்பிறந்தவனும் எப்ரோனின் தகப்பனாகிய மெரோசாவின் குமாரருமே.", "en": "Now the sons of Caleb the brother of Jerahmeel were , Mesha his firstborn, which was the father of Ziph; and the sons of Mareshah the father of Hebron."}, {"verse": 43, "start": 405.41, "end": 412.54, "ta": "எப்ரோனின் குமாரர், கோராகு, தப்புவா, ரெக்கேம் செமா என்பவர்கள்.", "en": "And the sons of Hebron; Korah, and Tappuah, and Rekem, and Shema."}, {"verse": 44, "start": 412.54, "end": 421.11, "ta": "செமா யோர்க்கேயாமின் தகப்பனாகிய ரெக்கேமைப் பெற்றான்; ரெக்கேம் சம்மாயைப் பெற்றான்.", "en": "And Shema begat Raham, the father of Jorkoam: and Rekem begat Shammai."}, {"verse": 45, "start": 421.11, "end": 427.15, "ta": "சம்மாயின் குமாரன் மாகோன்; மாகோன் பெத்சூரின் தகப்பன்.", "en": "And the son of Shammai was Maon: and Maon was the father of Beth-zur."}, {"verse": 46, "start": 427.15, "end": 437.98, "ta": "காலேபின் மறுமனையாட்டியாகிய எப்பாள் ஆரானையும் மோசாவையும், காசேசையும் பெற்றாள்; ஆரான் காசேசைப் பெற்றான்.", "en": "And Ephah, Caleb’s concubine, bare Haran, and Moza, and Gazez: and Haran begat Gazez."}, {"verse": 47, "start": 437.98, "end": 447.18, "ta": "யாதாயின் குமாரர், ரேகேம், யோதாம், கேசாம், பேலேத், எப்பா, சாகாப் என்பவர்கள்.", "en": "And the sons of Jahdai; Regem, and Jotham, and Geshan, and Pelet, and Ephah, and Shaaph."}, {"verse": 48, "start": 447.18, "end": 454.22, "ta": "காலேபின் மறுமனையாட்டியாகிய மாகாள் சேபேரையும் திர்கானாவையும் பெற்றாள்.", "en": "Maachah, Caleb’s concubine, bare Sheber, and Tirhanah."}, {"verse": 49, "start": 454.22, "end": 468.38, "ta": "அவள் மத்மன்னாவின் தகப்பனாகிய சாகாபையும், மக்பேனாவுக்கும் கீபேயாவுக்கும் தகப்பனாகிய சேவாவையும் பெற்றாள்; காலேபின் குமாரத்தி அக்சாள் என்பவள்.", "en": "She bare also Shaaph the father of Madmannah, Sheva the father of Machbenah, and the father of Gibea: and the daughter of Caleb was Achsah."}, {"verse": 50, "start": 468.38, "end": 478.12, "ta": "எப்ராத்தாளிடத்தில் முதற்பிறந்த ஊருடைய குமாரனாகிய காலேபின் குமாரர், கீரியாத்யாரீமின் மூப்பனான சோபாலும்,", "en": "These were the sons of Caleb the son of Hur, the firstborn of Ephratah; Shobal the father of Kirjath-jearim,"}, {"verse": 51, "start": 478.12, "end": 485.07, "ta": "பெத்லெகேமின் மூப்பனான சல்மாவும், பெத்காதேரின் மூப்பனான ஆரேப்புமே.", "en": "Salma the father of Beth-lehem, Hareph the father of Beth-gader."}, {"verse": 52, "start": 485.07, "end": 493.46, "ta": "கீரியாத்யாரிமின் மூப்பனான சோபாலின் குமாரர், ஆரோவே, ஆசியம் மெனுகோத் என்பவர்கள்.", "en": "And Shobal the father of Kirjath-jearim had sons; Haroeh, and half of the Manahethites."}, {"verse": 53, "start": 493.46, "end": 508.16, "ta": "கீரியாத்யாரிமிலிருந்த வம்சங்கள், எத்திரியரும் பூகியரும் சுமாத்தியரும் மிஸ்ராவியருமே; இவர்களிடத்தில் சோராத்தியரும், எஸ்தவோலியரும் பிறந்தார்கள்.", "en": "And the families of Kirjath-jearim; the Ithrites, and the Puhites, and the Shumathites, and the Mishraites; of them came the Zareathites, and the Eshtaulites."}, {"verse": 54, "start": 508.16, "end": 522.32, "ta": "சல்மாவின் சந்ததிகள், பெத்லெகேமியரும், நேத்தோப்பாத்தியரும், பெத்யோவாப் என்னும் அதரோத் ஊராரும், மானாத்தியரிலும் சோரியரிலும் பாதிஜனங்களுமே.", "en": "The sons of Salma; Beth-lehem, and the Netophathites, Ataroth, the house of Joab, and half of the Manahethites, the Zorites."}, {"verse": 55, "start": 522.32, "end": 538.02, "ta": "யாபேசில் குடியிருந்த கணக்கரின் வம்சங்கள், திராத்தியரும் சிமாத்தியரும் சுக்காத்தியருமே; ரேகாப் வீட்டாரின் தகப்பனாகிய அம்மாத்தின் சந்ததியாரான கேனியர் இவர்களே.", "en": "And the families of the scribes which dwelt at Jabez; the Tirathites, the Shimeathites, and Suchathites. These are the Kenites that came of Hemath, the father of the house of Rechab."}]}, "3": {"chapter": 3, "duration": 258.38, "audio_url": "audio_ot/OT13_03.mp3", "total_verses": 24, "verses": [{"verse": 1, "start": 3.8, "end": 21.31, "ta": "தாவீதுக்கு எப்ரோனிலே பிறந்த குமாரர்: யெஸ்ரெயேல் ஊராளான அகினோவாமிடத்தில் பிறந்த அம்னோன் முதற்பேறானவன்; கர்மேலின் ஊராளான அபிகாயேலிடத்தில் பிறந்த தானியேல் இரண்டாம் குமாரன்.", "en": "Now these were the sons of David, which were born unto him in Hebron; the firstborn Amnon, of Ahinoam the Jezreelitess; the second Daniel, of Abigail the Carmelitess:"}, {"verse": 2, "start": 21.31, "end": 33.77, "ta": "கேசூரின் ராஜாவாகிய தல்மாயின் குமாரத்தி மாக்காள் பெற்ற அப்சலோம் மூன்றாம் குமாரன்; ஆகீத் பெற்ற அதோனியா நாலாம் குமாரன்.", "en": "The third, Absalom the son of Maachah the daughter of Talmai king of Geshur: the fourth, Adonijah the son of Haggith:"}, {"verse": 3, "start": 33.77, "end": 44.9, "ta": "அபித்தாள் பெற்ற செப்பத்தியா ஐந்தாம் குமாரன்; அவன் பெண்ஜாதியாகிய எக்லாள் பெற்ற இத்ரேயாம் ஆறாம் குமாரன்.", "en": "The fifth, Shephatiah of Abital: the sixth, Ithream by Eglah his wife."}, {"verse": 4, "start": 44.9, "end": 59.84, "ta": "இந்த ஆறு குமாரர் அவனுக்கு எப்ரோனிலே பிறந்தார்கள்; அங்கே ஏழுவருஷமும் ஆறுமாதமும் அரசாண்டான்; எருசலேமிலோ முப்பத்துமூன்று வருஷம் அரசாண்டான்.", "en": "These six were born unto him in Hebron; and there he reigned seven years and six months: and in Jerusalem he reigned thirty and three years."}, {"verse": 5, "start": 59.84, "end": 73.73, "ta": "எருசலேமில் அவனுக்குப் பிறந்தவர்கள்: அம்மியேலின் குமாரத்தியாகிய பத்சுவாளிடத்தில் சிமீயா, சோபாப், நாத்தான், சாலொமோன் என்னும் நாலுபேரும்,", "en": "And these were born unto him in Jerusalem; Shimea, and Shobab, and Nathan, and Solomon, four, of Bath-shua the daughter of Ammiel:"}, {"verse": 6, "start": 73.73, "end": 77.44, "ta": "இப்கார், எலிசாமா, எலிப்பெலேத்,", "en": "Ibhar also, and Elishama, and Eliphelet,"}, {"verse": 7, "start": 77.44, "end": 80.39, "ta": "நோகா, நேபேக், யப்பியா,", "en": "And Nogah, and Nepheg, and Japhia,"}, {"verse": 8, "start": 80.39, "end": 86.48, "ta": "எலிசாமா, எலியாதா, எலிபேலேத் என்னும் ஒன்பதுபேருமே.", "en": "And Elishama, and Eliada, and Eliphelet, nine."}, {"verse": 9, "start": 86.48, "end": 97.14, "ta": "மறுமனையாட்டிகளின் குமாரரையும் இவர்கள் சகோதரியாகிய தாமாரையும் தவிர, இவர்களெல்லாரும் தாவீதின் குமாரர்.", "en": "These were all the sons of David, beside the sons of the concubines, and Tamar their sister."}, {"verse": 10, "start": 97.14, "end": 109.12, "ta": "சாலொமோனின் குமாரன் ரெகொபெயாம்; இவனுடைய குமாரன் அபியா; இவனுடைய குமாரன் ஆசா; இவனுடைய குமாரன் யோசபாத்.", "en": "And Solomon’s son was Rehoboam, Abia his son, Asa his son, Jehoshaphat his son,"}, {"verse": 11, "start": 109.12, "end": 117.88, "ta": "இவனுடைய குமாரன் யோராம்; இவனுடைய குமாரன் அகசியா; இவனுடைய குமாரன் யோவாஸ்.", "en": "Joram his son, Ahaziah his son, Joash his son,"}, {"verse": 12, "start": 117.88, "end": 126.82, "ta": "இவனுடைய குமாரன் அமத்சியா; இவனுடைய குமாரன் அசரியா; இவனுடைய குமாரன் யோதாம்.", "en": "Amaziah his son, Azariah his son, Jotham his son,"}, {"verse": 13, "start": 126.82, "end": 135.67, "ta": "இவனுடைய குமாரன் ஆகாஸ்; இவனுடைய குமாரன் எசேக்கியா; இவனுடைய குமாரன் மனாசே.", "en": "Ahaz his son, Hezekiah his son, Manasseh his son,"}, {"verse": 14, "start": 135.67, "end": 141.47, "ta": "இவனுடைய குமாரன் ஆமோன்; இவனுடைய குமாரன் யோசியா.", "en": "Amon his son, Josiah his son."}, {"verse": 15, "start": 141.47, "end": 158.31, "ta": "யோசியாவின் குமாரர், முதல் பிறந்த யோகனானும், யோயாக்கீம் என்னும் இரண்டாம் குமாரனும், சிதேக்கியா என்னும் மூன்றாம் குமாரனும், சல்லுூம் என்னும் நாலாம் குமாரனுமே.", "en": "And the sons of Josiah were , the firstborn Johanan, the second Jehoiakim, the third Zedekiah, the fourth Shallum."}, {"verse": 16, "start": 158.31, "end": 166.97, "ta": "யோயாக்கீமின் குமாரர், எகொனியா முதலானவர்கள்; இவனுக்கு மகனானவன் சிதேக்கியா.", "en": "And the sons of Jehoiakim: Jeconiah his son, Zedekiah his son."}, {"verse": 17, "start": 166.97, "end": 171.16, "ta": "கட்டுண்ட எகொனியாவின் குமாரர் சலாத்தியேல்,", "en": "And the sons of Jeconiah; Assir, Salathiel his son,"}, {"verse": 18, "start": 171.16, "end": 179.53, "ta": "மல்கீராம், பெதாயா, சேனாசார், யெகமியா, ஒசாமா, நெதபியா என்பவர்கள்.", "en": "Malchiram also, and Pedaiah, and Shenazar, Jecamiah, Hoshama, and Nedabiah."}, {"verse": 19, "start": 179.53, "end": 195.61, "ta": "பெதாயாவின் குமாரர், செருபாபேல், சிமேயி என்பவர்கள்; செருபாபேலின் குமாரர், மெசுல்லாம், அனனியா என்பவர்கள்; இவர்கள் சகோதரி செலோமீத் என்பவள்.", "en": "And the sons of Pedaiah were , Zerubbabel, and Shimei: and the sons of Zerubbabel; Meshullam, and Hananiah, and Shelomith their sister:"}, {"verse": 20, "start": 195.61, "end": 203.41, "ta": "அசூபா, ஒகேல், பெரகியா, அசதியா, ஊசாபேசேத் என்னும் ஐந்துபேருமே.", "en": "And Hashubah, and Ohel, and Berechiah, and Hasadiah, Jushab-hesed, five."}, {"verse": 21, "start": 203.41, "end": 221.3, "ta": "அனனியாவின் குமாரர், பெலேத்தியா, எசாயா என்பவர்கள்; இவனுடைய குமாரன் ரெபாயா; இவனுடைய குமாரன் அர்னான்; இவனுடைய குமாரன் ஒபதியா; இவனுடைய குமாரன் செக்கனியா.", "en": "And the sons of Hananiah; Pelatiah, and Jesaiah: the sons of Rephaiah, the sons of Arnan, the sons of Obadiah, the sons of Shechaniah."}, {"verse": 22, "start": 221.3, "end": 236.33, "ta": "செக்கனியாவின் குமாரர், செமாயா முதலானவர்கள்; செமாயாவின் குமாரர், அத்தூஸ், எகெயால், பாரியா, நெயாரியா, செப்பாத் என்னும் ஆறுபேர்.", "en": "And the sons of Shechaniah; Shemaiah: and the sons of Shemaiah; Hattush, and Igeal, and Bariah, and Neariah, and Shaphat, six."}, {"verse": 23, "start": 236.33, "end": 244.99, "ta": "நெயாரியாவின் குமாரர், எலியோய், எசேக்கியா, அஸ்ரீக்காம் என்னும் மூன்றுபேர்.", "en": "And the sons of Neariah; Elioenai, and Hezekiah, and Azrikam, three."}, {"verse": 24, "start": 244.99, "end": 256.88, "ta": "எலியோனாயின் குமாரர், ஒதாயா, எலியாசிப், பெலாயா, அக்கூப், யோகனான், தெலாயா, ஆனானி என்னும் ஏழுபேர்.", "en": "And the sons of Elioenai were , Hodaiah, and Eliashib, and Pelaiah, and Akkub, and Johanan, and Dalaiah, and Anani, seven."}]}, "4": {"chapter": 4, "duration": 497.19, "audio_url": "audio_ot/OT13_04.mp3", "total_verses": 43, "verses": [{"verse": 1, "start": 3.8, "end": 11.59, "ta": "யூதாவின் குமாரர், பாரேஸ், எஸ்ரோன், கர்மீ, ஊர், சோபால் என்பவர்கள்.", "en": "The sons of Judah; Pharez, Hezron, and Carmi, and Hur, and Shobal."}, {"verse": 2, "start": 11.59, "end": 23.58, "ta": "சோபாலின் குமாரன் ராயா யாகாத்தைப் பெற்றான்; யாகாத் அகுமாயியையும் லாகாதையும் பெற்றான்; சோராத்தியரின் வம்சங்கள் இவைகளே.", "en": "And Reaiah the son of Shobal begat Jahath; and Jahath begat Ahumai, and Lahad. These are the families of the Zorathites."}, {"verse": 3, "start": 23.58, "end": 35.57, "ta": "ஏதாம் என்னும் மூப்பனின் சந்ததியார், யெஸ்ரெயேல், இஷ்மா, இத்பாஸ் என்பவர்கள்; இவர்களுடைய சகோதரியின் பேர் அத்செலெல்போனி;", "en": "And these were of the father of Etam; Jezreel, and Ishma, and Idbash: and the name of their sister was Hazelelponi:"}, {"verse": 4, "start": 35.57, "end": 49.48, "ta": "கேதோருக்கு மூப்பனான பெனுவெல், உஷாவுக்கு மூப்பனான எசேர் என்பவர்கள்; இவர்கள் பெத்லெகேமுக்கு மூப்பனான எப்ராத்தாவுக்கு முதற்பிறந்த ஊரின் குமாரர்.", "en": "And Penuel the father of Gedor, and Ezer the father of Hushah. These are the sons of Hur, the firstborn of Ephratah, the father of Beth-lehem."}, {"verse": 5, "start": 49.48, "end": 58.23, "ta": "தெக்கோவாவுக்கு மூப்பனான அசூருக்கு ஏலாள், நாராள் என்னும் இரண்டு பெண்ஜாதிகள் இருந்தார்கள்.", "en": "And Ashur the father of Tekoa had two wives, Helah and Naarah."}, {"verse": 6, "start": 58.23, "end": 69.78, "ta": "நாராள் அவனுக்கு அகுசாமையும், எப்பேரையும், தெமனியையும, ஆகாஸ்தாரியையும் பெற்றாள்; நாராளின் குமாரர்கள் இவர்களே.", "en": "And Naarah bare him Ahuzam, and Hepher, and Temeni, and Haahashtari. These were the sons of Naarah."}, {"verse": 7, "start": 69.78, "end": 76.17, "ta": "ஏலாளின் குமாரர், சேரேத், எத்சோகார், எத்னான் என்பவர்கள்.", "en": "And the sons of Helah were , Zereth, and Jezoar, and Ethnan."}, {"verse": 8, "start": 76.17, "end": 85.45, "ta": "கோஸ் என்பவன் அனூபையும், சோபேபாகையும், ஆருமின் குமாரனாகிய அகர்கேலின் வம்சங்களையும் பெற்றான்.", "en": "And Coz begat Anub, and Zobebah, and the families of Aharhel the son of Harum."}, {"verse": 9, "start": 85.45, "end": 99.89, "ta": "யாபேஸ் தன் சகோதரரைப்பார்க்கிலும் கனம்பெற்றவனாயிருந்தான். அவன் தாய்: நான் துக்கத்தோடே அவனைப் பெற்றேன் என்று சொல்லி அவனுக்கு யாபேஸ் என்று பேரிட்டாள்.", "en": "And Jabez was more honourable than his brethren: and his mother called his name Jabez, saying, Because I bare him with sorrow."}, {"verse": 10, "start": 99.89, "end": 123.43, "ta": "யாபேஸ் இஸ்ரவேலின் தேவனை நோக்கி: தேவரீர் என்னை ஆசிர்வதித்து, என் எல்லையைப் பெரிதாக்கி, உமது கரம் என்னோடிருந்து, தீங்கு என்னைத் துக்கப்படுத்தாதபடிக்கு அதற்கு என்னை விலக்கிக் காத்தருளும் என்று வேண்டிக்கொண்டான்; அவன் வேண்டிக்கொண்டதை தேவன் அருளினார்.", "en": "And Jabez called on the God of Israel, saying, Oh that thou wouldest bless me indeed, and enlarge my coast, and that thine hand might be with me, and that thou wouldest keep me from evil, that it may not grieve me! And God granted him that which he requested."}, {"verse": 11, "start": 123.43, "end": 130.86, "ta": "சூகாவின் சகோதரனாகிய கேலுூப் மேகீரைப் பெற்றான்; இவன் எஸ்தோனின் தகப்பன்.", "en": "And Chelub the brother of Shuah begat Mehir, which was the father of Eshton."}, {"verse": 12, "start": 130.86, "end": 142.06, "ta": "எஸ்தோன் பெத்ராபாவையும், பசேயாகையும், இர்நாகாஷின் தகப்பனாகிய தெகினாகையும் பெற்றான்; இவர்கள் ரேகாவூர் மனுஷர்.", "en": "And Eshton begat Beth-rapha, and Paseah, and Tehinnah the father of Ir-nahash. These are the men of Rechah."}, {"verse": 13, "start": 142.06, "end": 151.34, "ta": "கேனாசின் குமாரர், ஒத்னியேல், செராயா என்பவர்கள்; ஒத்னியேலின் குமாரரில் ஒருவன் ஆத்தாத்.", "en": "And the sons of Kenaz; Othniel, and Seraiah: and the sons of Othniel; Hathath."}, {"verse": 14, "start": 151.34, "end": 164.38, "ta": "மெயோனத்தாய் ஒபிராவைப் பெற்றான்; செராயா கராஷீமன் பள்ளத்தாக்குக்கு மூப்பனாகிய யோவாபைப் பெற்றான்; அவர்கள் தொழிலாளிகளாயிருந்தார்கள்.", "en": "And Meonothai begat Ophrah: and Seraiah begat Joab, the father of the valley of Charashim; for they were craftsmen."}, {"verse": 15, "start": 164.38, "end": 174.62, "ta": "எப்புன்னேயின் குமாரனாகிய காலேபின் குமாரர், ஈரு, ஏலா, நாகாம்; ஏலாவின் குமாரரில் ஒருவன் கேனாஸ்.", "en": "And the sons of Caleb the son of Jephunneh; Iru, Elah, and Naam: and the sons of Elah, even Kenaz."}, {"verse": 16, "start": 174.62, "end": 181.01, "ta": "எகலெலேலின் குமாரர், சீப், சீப்பா, திரியா, அசாரெயேல்.", "en": "And the sons of Jehaleleel; Ziph, and Ziphah, Tiria, and Asareel."}, {"verse": 17, "start": 181.01, "end": 197.11, "ta": "எஸ்றாவின் குமாரர், யெத்தேர், மேரேத், ஏப்பேர், யாலோன்; மேரேத்தின் பெண்ஜாதி மிரியாமையும், சம்மாயியையும், எஸ்தெமோவா ஊருக்கு மூப்பனான இஸ்பாவையும் பெற்றாள்.", "en": "And the sons of Ezra were , Jether, and Mered, and Epher, and Jalon: and she bare Miriam, and Shammai, and Ishbah the father of Eshtemoa."}, {"verse": 18, "start": 197.11, "end": 218.37, "ta": "அவன் பெண்ஜாதியாகிய எகுதியாள், கேதோரின் தகப்பனாகிய யாரேதையும், சோக்கோவின் தகப்பனாகிய ஏபேரையும, சனோவாவின் தகப்பனாகிய எக்குகதியேலையும் பெற்றாள்; மேரேத் விவாகம் பண்ணின பார்வோனின் குமாரத்தியாகிய பித்தியாளின் குமாரர் இவர்களே.", "en": "And his wife Jehudijah bare Jered the father of Gedor, and Heber the father of Socho, and Jekuthiel the father of Zanoah. And these are the sons of Bithiah the daughter of Pharaoh, which Mered took."}, {"verse": 19, "start": 218.37, "end": 229.05, "ta": "நாகாமின் சகோதரியாகிய ஒதியாவினுடைய பெண்ஜாதியின் குமாரர் கர்மியனாகிய ஆபிகேயிலாவும், மாகாத்தினாகிய எஸ்தேமோவாவுமே.", "en": "And the sons of his wife Hodiah the sister of Naham, the father of Keilah the Garmite, and Eshtemoa the Maachathite."}, {"verse": 20, "start": 229.05, "end": 240.6, "ta": "ஷீமோனின் குமாரர், அம்னோன், ரின்னா, பென்கானான், தீலோன் என்பவர்கள், இஷியின் குமாரர், சோகேதும் பென்சோகேதுமே.", "en": "And the sons of Shimon were , Amnon, and Rinnah, Ben-hanan, and Tilon. And the sons of Ishi were , Zoheth, and Ben-zoheth."}, {"verse": 21, "start": 240.6, "end": 253.29, "ta": "யூதாவின் குமாரனாகிய சேலாகின் புத்திரர்: லேக்காவூர் மூப்பனான ஏரும் மரேசார் மூப்பனான லாதாகும், மெல்லிய புடவை நெய்த அஸ்பெயா வீட்டுவம்சங்களும்,", "en": "The sons of Shelah the son of Judah were , Er the father of Lecah, and Laadah the father of Mareshah, and the families of the house of them that wrought fine linen, of the house of Ashbea,"}, {"verse": 22, "start": 253.29, "end": 266.68, "ta": "யோயாக்கீமும், கோசேபாவின் மனுஷரும், மோவாபியரை ஆண்ட யோவாஸ், சாராப் என்பவர்களும், யசுபிலெகேமுமே; இவைகள் பூர்வகாலத்தின் செய்திகள்.", "en": "And Jokim, and the men of Chozeba, and Joash, and Saraph, who had the dominion in Moab, and Jashubi-lehem. And these are ancient things."}, {"verse": 23, "start": 266.68, "end": 278.23, "ta": "இவர்கள் குயவராயிருந்து நெத்தாயிமிலும் கெதேராவிலும் குடியிருந்தார்கள்; ராஜாவின் வேலையை விசாரிக்கிறதற்கு அங்கே வாசம்பண்ணினார்கள்", "en": "These were the potters, and those that dwelt among plants and hedges: there they dwelt with the king for his work."}, {"verse": 24, "start": 278.23, "end": 286.28, "ta": "சிமியோனின் குமாரர், நெமுவேல்,யாமின், யாரீப், சேரா, சவுல் என்பவர்கள்.", "en": "The sons of Simeon were , Nemuel, and Jamin, Jarib, Zerah, and Shaul:"}, {"verse": 25, "start": 286.28, "end": 293.89, "ta": "இவன் குமாரன் சல்லுூம்; இவன் குமாரன் மிப்சாம்; இவன் குமாரன் மிஸ்மா.", "en": "Shallum his son, Mibsam his son, Mishma his son."}, {"verse": 26, "start": 293.89, "end": 302.82, "ta": "மிஸ்மாவின் குமாரரில் ஒருவன் அம்முவேல்; இவன் குமாரன் சக்கூர்; இவன் குமாரன் சீமேயி.", "en": "And the sons of Mishma; Hamuel his son, Zacchur his son, Shimei his son."}, {"verse": 27, "start": 302.82, "end": 319.53, "ta": "சீமேயிக்குப் பதினாறு குமாரரும் குமாரத்திகளும் இருந்தார்கள்; அவன் சகோதரருக்கு அநேகம் பிள்ளைகள் இருந்ததில்லை; அவர்கள் வம்சமெல்லாம் யூதாவின் புத்திரைப்போலப் பெருகினதுமில்லை.", "en": "And Shimei had sixteen sons and six daughters; but his brethren had not many children, neither did all their family multiply, like to the children of Judah."}, {"verse": 28, "start": 319.53, "end": 325.31, "ta": "அவர்கள் பெயெர்செபாவிலும், மொலாதாவிலும், ஆதசார்குவாவிலும்,", "en": "And they dwelt at Beer-sheba, and Moladah, and Hazar-shual,"}, {"verse": 29, "start": 325.31, "end": 329.42, "ta": "பில்லாவிலும், ஏத்சாமிலும், தோலாதிலும்,", "en": "And at Bilhah, and at Ezem, and at Tolad,"}, {"verse": 30, "start": 329.42, "end": 333.89, "ta": "பெத்தூவேலிலும், ஓர்மாவிலும், சிக்லாகிலும்,", "en": "And at Bethuel, and at Hormah, and at Ziklag,"}, {"verse": 31, "start": 333.89, "end": 348.85, "ta": "பெத்மார்காபோத்திலும், ஆத்சார்சூசிமிலும், பெத்பிரியிலும், சாராயிமிலும் குடியிருந்தார்கள்; தாவீது ராஜாவாகுமட்டும் இவைகள் அவர்கள் பட்டணங்களாயிருந்தது.", "en": "And at Beth-marcaboth, and Hazar-susim, and at Beth-birei, and at Shaaraim. These were their cities unto the reign of David."}, {"verse": 32, "start": 348.85, "end": 358.56, "ta": "அவர்களுடைய பேட்டைகள், ஏத்தாம், ஆயின், ரிம்மோன், தோகேன், ஆசான் என்னும் ஐந்து பட்டணங்கள்.", "en": "And their villages were , Etam, and Ain, Rimmon, and Tochen, and Ashan, five cities:"}, {"verse": 33, "start": 358.56, "end": 372.3, "ta": "அந்த பட்டணங்களைச் சுற்றிலும், பாகால்மட்முள்ள அவர்களுடைய எல்லாப் பேட்டைகளும், அவர்களுடைய வாசஸ்தலங்களும், அவர்களுடைய வம்ச அட்டவணையும் இவைகளே.", "en": "And all their villages that were round about the same cities, unto Baal. These were their habitations, and their genealogy."}, {"verse": 34, "start": 372.3, "end": 377.64, "ta": "மசோபாபும், யம்லேகும், அமத்சியாவின் குமாரன் யோஷாவும்,", "en": "And Meshobab, and Jamlech, and Joshah the son of Amaziah,"}, {"verse": 35, "start": 377.64, "end": 384.82, "ta": "யோவேலும், ஆசியேலின் மகன் செராயாவுக்குப் பிறந்த யோசிபியாவின் குமாரன் ஏகூவும்,", "en": "And Joel, and Jehu the son of Josibiah, the son of Seraiah, the son of Asiel,"}, {"verse": 36, "start": 384.82, "end": 394.0, "ta": "எலியோனாயும், யாக்கோபாவும், யெசொகாயாவும், அசாயாவும், ஆதியேலும், யெசிமியேலும் பெனாயாவும்,", "en": "And Elioenai, and Jaakobah, and Jeshohaiah, and Asaiah, and Adiel, and Jesimiel, and Benaiah,"}, {"verse": 37, "start": 394.0, "end": 403.72, "ta": "செமாயா பெற்ற சிம்ரியின் மகன் யெதாயாவுக்குப் பிறந்த அல்லோனின் புத்திரனாகிய சீப்பியின் குமாரன் சீசாவும் என்று,", "en": "And Ziza the son of Shiphi, the son of Allon, the son of Jedaiah, the son of Shimri, the son of Shemaiah;"}, {"verse": 38, "start": 403.72, "end": 415.71, "ta": "பேர்பேராய் எழுதியிருக்கிற இவர்கள் வம்சங்களில் பிரபுக்களாயிருந்தார்கள், இவர்கள் பிதாக்களின் வீட்டார் ஏராளமாய்ப் பரம்பினார்கள்.", "en": "These mentioned by their names were princes in their families: and the house of their fathers increased greatly."}, {"verse": 39, "start": 415.71, "end": 424.81, "ta": "தங்கள் ஆடுகளுக்கு மேய்ச்சலைத் தேடும்படிக்கு தேதோரின் எல்லையாகிய பள்ளத்தாக்கின் கீழ்ப்புறமட்டும் போய்,", "en": "And they went to the entrance of Gedor, even unto the east side of the valley, to seek pasture for their flocks."}, {"verse": 40, "start": 424.81, "end": 439.95, "ta": "நல்ல செழிப்பான மேய்ச்சலையும், அமரிக்கையும், சுகமுமுள்ள விஸ்தாரமான தேசத்தையும் கண்டுபிடித்தார்கள்; பூர்வத்திலே காமின் சந்ததியார் அங்கே குடியிருந்தார்கள்.", "en": "And they found fat pasture and good, and the land was wide, and quiet, and peaceable; for they of Ham had dwelt there of old."}, {"verse": 41, "start": 439.95, "end": 468.47, "ta": "பேர்பேராய் எழுதியிருக்கிற இவர்கள் யூதாவின் ராஜாவாகிய எசேக்கியாவின் நாட்களிலே அங்கே போய், அங்கே, கண்டுபிடித்தவர்களின் கூடாரங்களையும், தாபரங்களையும் அழித்து, இந்நாளிலே இருக்கிறதுபோல, அவர்களைச் சங்காரம்பண்ணி, அங்கே தங்கள் ஆடுகளுக்குமேய்ச்சல் இருந்தபடியினால், அவர்கள் அந்த ஸ்தலத்திலே குடியேறினார்கள்.", "en": "And these written by name came in the days of Hezekiah king of Judah, and smote their tents, and the habitations that were found there, and destroyed them utterly unto this day, and dwelt in their rooms: because there was pasture there for their flocks."}, {"verse": 42, "start": 468.47, "end": 485.54, "ta": "சிமியோனின் புத்திரராகிய இவர்களில் ஐந்நூறு மனுஷரும், அவர்கள் தலைமைக்காரராகிய இஷியின் குமாரரான பெலத்தியாவும், நெகரியாவும், ரெப்பாயாவும், ஊசியேலும், சேயீர் மலைத்தேசத்திற்குப் போய்,", "en": "And some of them, even of the sons of Simeon, five hundred men, went to mount Seir, having for their captains Pelatiah, and Neariah, and Rephaiah, and Uzziel, the sons of Ishi."}, {"verse": 43, "start": 485.54, "end": 495.69, "ta": "அமலேக்கியரில் தப்பி மீதியாயிருந்தவர்களை மடங்கடித்து, இந்நாள்வரைக்கும் இருக்கிறபடி அங்கே குடியேறினார்கள்.", "en": "And they smote the rest of the Amalekites that were escaped, and dwelt there unto this day."}]}, "5": {"chapter": 5, "duration": 352.78, "audio_url": "audio_ot/OT13_05.mp3", "total_verses": 26, "verses": [{"verse": 1, "start": 3.8, "end": 27.25, "ta": "ரூபன் இஸ்ரவேலுக்கு முதற்பிறந்த சேஷ்டபுத்திரன்; ஆனாலும் அவன் தன் தகப்பனுடைய மஞ்சத்தைத் தீட்டுப்படுத்தினபடியினால், கோத்திரத்து அட்டவணையிலே அவன் முதற் பிறந்தவனாக எண்ணப்படாமல், அவனுடைய சேஷ்டபுத்திர சுதந்தரம் இஸ்ரவேலின் குமாரனாகிய யோசேப்பின் குமாரருக்குக் கொடுக்கப்பட்டது.", "en": "Now the sons of Reuben the firstborn of Israel, (for he was the firstborn; but, forasmuch as he defiled his father’s bed, his birthright was given unto the sons of Joseph the son of Israel: and the genealogy is not to be reckoned after the birthright."}, {"verse": 2, "start": 27.25, "end": 38.32, "ta": "யூதா தன் சகோதரரிலே பலத்ததினால் ராஜாதிபத்தியம் அவன் சந்ததியிலுண்டானது; ஆகிலும் சேஷ்டபுத்திர சுதந்தரம் யோசேப்புடையதாயிற்று.", "en": "For Judah prevailed above his brethren, and of him came the chief ruler; but the birthright was Joseph’s:)"}, {"verse": 3, "start": 38.32, "end": 46.38, "ta": "இஸ்ரவேலின் முதற்பேறான ரூபனின் குமாரன் ஆனோக்கு, பல்லுூ, எஸ்ரோன், ஊர்மீ என்பவர்கள்.", "en": "The sons, I say , of Reuben the firstborn of Israel were , Hanoch, and Pallu, Hezron, and Carmi."}, {"verse": 4, "start": 46.38, "end": 54.03, "ta": "யோவேலின் குமாரரில் ஒருவன் செமாயா; இவன் குமாரன் கோக்; இவன் குமாரன் சிமேய்.", "en": "The sons of Joel; Shemaiah his son, Gog his son, Shimei his son,"}, {"verse": 5, "start": 54.03, "end": 60.46, "ta": "இவன் குமாரன் மீகா; இவன் குமாரன் ராயா; இவன் குமாரன் பாகால்.", "en": "Micah his son, Reaia his son, Baal his son,"}, {"verse": 6, "start": 60.46, "end": 69.91, "ta": "இவன் குமாரன் பேரா; ரூபனியரின் பிரபுவான இவனை அசீரியா ராஜாவாகிய தில்காத்பில்நேசர் சிறைபிடித்துப்போனான்.", "en": "Beerah his son, whom Tilgath-pilneser king of Assyria carried away captive: he was prince of the Reubenites."}, {"verse": 7, "start": 69.91, "end": 78.7, "ta": "தங்கள் சந்ததிகளின்படியே தங்கள் வம்ச அட்டவணைகளில் எழுதப்பட்ட அவன் சகோதரரில் தலைவர் ஏயேலும், சகரியாவும்,", "en": "And his brethren by their families, when the genealogy of their generations was reckoned, were the chief, Jeiel, and Zechariah,"}, {"verse": 8, "start": 78.7, "end": 92.22, "ta": "யோவேலின் மகனாகிய சேமாவுக்குப் பிறந்த ஆசாசின் குமாரன் பேலாவும்; இவன் சந்ததியார் ஆரோவேரிலும்; நேபோமட்டும், பாகால்மயோன்மட்டும் வாசம்பண்ணினார்கள்.", "en": "And Bela the son of Azaz, the son of Shema, the son of Joel, who dwelt in Aroer, even unto Nebo and Baal-meon:"}, {"verse": 9, "start": 92.22, "end": 104.43, "ta": "கிழக்கே ஐபிராத்து நதிதொடங்கி வனாந்தரத்தின் எல்லைமட்டும் அவர்கள் வாசம்பண்ணினார்கள்; அவர்கள் ஆடுமாடுகள் கீலேயாத்தேசத்தில் மிகுதியாயிற்று.", "en": "And eastward he inhabited unto the entering in of the wilderness from the river Euphrates: because their cattle were multiplied in the land of Gilead."}, {"verse": 10, "start": 104.43, "end": 118.19, "ta": "சவுலின் நாட்களில் ஆகாரியரோடு அவர்கள் யுத்தம்பண்ணி, தங்கள் கையால் அவர்கள் விழுந்தபின், அவர்கள் கூடாரங்களிலே கீலேயாத்தின் கீழ்ப்புறமெல்லாம் குடியேறினார்கள்.", "en": "And in the days of Saul they made war with the Hagarites, who fell by their hand: and they dwelt in their tents throughout all the east land of Gilead."}, {"verse": 11, "start": 118.19, "end": 125.76, "ta": "காத்தின் புத்திரர் அவர்களுக்கு எதிரே பாசான்தேசத்திலே சல்காமட்டும் வாசம்பண்ணினார்கள்.", "en": "And the children of Gad dwelt over against them, in the land of Bashan unto Salchah:"}, {"verse": 12, "start": 125.76, "end": 136.51, "ta": "அவர்களில் யோவேல் தலைவனும், சாப்பானும் அவனுக்கு இரண்டாவதுமாயிருந்தான்; யானாயும் சாப்பாத்தும் பாசானில் இருந்தார்கள்.", "en": "Joel the chief, and Shapham the next, and Jaanai, and Shaphat in Bashan."}, {"verse": 13, "start": 136.51, "end": 148.96, "ta": "அவர்கள் பிதாக்களின் வீட்டாராகிய அவர்கள் சகோதரர், மிகாவேல், மெசுல்லாம், சேபா, யோராயி, யாக்கான், சீகா, ஏபேர் என்னும் ஏழுபேர்.", "en": "And their brethren of the house of their fathers were , Michael, and Meshullam, and Sheba, and Jorai, and Jachan, and Zia, and Heber, seven."}, {"verse": 14, "start": 148.96, "end": 168.1, "ta": "இவர்கள் ஊரிக்குப் பிறந்த அபியேலின் குமாரர்; ஊரி என்பவன் யெரொவாவுக்கும், யெரொவா கீலேயாத்துக்கும், கீலேயாத் மிகாவேலுக்கும், மிகாவேல் எசிசாயிக்கும், எசிசாயி யாதோவுக்கும், யாதோ பூசுக்கும் குமாரராயிருந்தவர்கள்.", "en": "These are the children of Abihail the son of Huri, the son of Jaroah, the son of Gilead, the son of Michael, the son of Jeshishai, the son of Jahdo, the son of Buz;"}, {"verse": 15, "start": 168.1, "end": 176.24, "ta": "கூனியின் குமாரனாகிய அப்தியேலின் மகன் அகி, அவர்கள் பிதாக்களின் வீட்டுத் தலைவனாயிருந்தான்.", "en": "Ahi the son of Abdiel, the son of Guni, chief of the house of their fathers."}, {"verse": 16, "start": 176.24, "end": 188.86, "ta": "அவர்கள் கீலேயாத்திலிருக்கிற பாசானிலும் அதின் வெளிநிலங்களிலும், சாரோனின் எல்லாப் பேட்டைகளிலும் அவைகளின் கடையாந்தரங்கள்மட்டும் வாசம்பண்ணினார்கள்.", "en": "And they dwelt in Gilead in Bashan, and in her towns, and in all the suburbs of Sharon, upon their borders."}, {"verse": 17, "start": 188.86, "end": 203.02, "ta": "இவர்களெல்லாரும் யூதாவின் ராஜாவாகிய யெரொபெயாமின் நாட்களிலும், இஸ்ரவேலின் ராஜாவாகிய யெரொபெயாமின் நாட்களிலும் தங்கள் வம்சத்து அட்டவணைப்படி தொகை, ஏற்றப்பட்டார்கள்.", "en": "All these were reckoned by genealogies in the days of Jotham king of Judah, and in the days of Jeroboam king of Israel."}, {"verse": 18, "start": 203.02, "end": 222.81, "ta": "ரூபன் புத்திரரிலும், காத்தியரிலும், மனாசேயின் பாதிக்கோத்திரத்தாரிலும் கேடகமும் பட்டயமும் எடுத்து, வில்லெய்து, யுத்தத்திற்குப் பழகி, படைக்குப் போகத்தக்க, சேவகர் நாற்பத்து நாலாயிரத்து எழுநூற்று அறுபதுபேராயிருந்தார்கள்.", "en": "The sons of Reuben, and the Gadites, and half the tribe of Manasseh, of valiant men, men able to bear buckler and sword, and to shoot with bow, and skilful in war, were four and forty thousand seven hundred and threescore, that went out to the war."}, {"verse": 19, "start": 222.81, "end": 229.97, "ta": "அவர்கள் ஆகாரியரோடும், யெத்தூர் நாப்பீஸ் நோதாப் என்பவர்களோடும் யுத்தம்பண்ணுகிறபோது,", "en": "And they made war with the Hagarites, with Jetur, and Nephish, and Nodab."}, {"verse": 20, "start": 229.97, "end": 251.06, "ta": "அவர்களோடே எதிர்க்கத் துணைபெற்றபடியினால், ஆகாரியரும் இவர்களோடிருக்கிற யாவரும் அவர்கள் கையில் ஒப்புக்கொடுக்கப்பட்டார்கள்; அவர்கள் யுத்தத்திலே தேவனை நோக்கிக் கூப்பிட்டு, அவர்மேல் நம்பிக்கை வைத்தபடியினால் அவர்கள் விண்ணப்பத்தைக் கேட்டருளினார்.", "en": "And they were helped against them, and the Hagarites were delivered into their hand, and all that were with them: for they cried to God in the battle, and he was intreated of them; because they put their trust in him."}, {"verse": 21, "start": 251.06, "end": 267.34, "ta": "அவர்கள் இவர்களுக்கு இருந்த மிருகஜீவன்களாகிய ஐம்பதினாயிரம் ஒட்டகங்களையும், இரண்டுலட்சத்து ஐம்பதினாயிரம் ஆடுகளையும், இரண்டாயிரம் கழுதைகளையும், மனுஷரில் லட்சம்பேர்களையும் பிடித்தார்கள்.", "en": "And they took away their cattle; of their camels fifty thousand, and of sheep two hundred and fifty thousand, and of asses two thousand, and of men an hundred thousand."}, {"verse": 22, "start": 267.34, "end": 279.72, "ta": "யுத்தம் தேவனால் நடந்தபடியினால் அநேகர் வெட்டுண்டு விழுந்தார்கள்; தாங்கள் சிறைப்பட்டுப்போகுமட்டும் இவர்களுடைய ஸ்தலத்திலே குடியிருந்தார்கள்.", "en": "For there fell down many slain, because the war was of God. And they dwelt in their steads until the captivity."}, {"verse": 23, "start": 279.72, "end": 294.7, "ta": "மனாசேயின் பாதிக்கோத்திரத்துப் புத்திரரும் அந்த தேசத்தில் குடியிருந்து, பாசான்தொடங்கிப் பாகால் எர்மோன்மட்டும், செனீர்மட்டும், எர்மோன் பர்வதமட்டும் பெருகியிருந்தார்கள்.", "en": "And the children of the half tribe of Manasseh dwelt in the land: they increased from Bashan unto Baal-hermon and Senir, and unto mount Hermon."}, {"verse": 24, "start": 294.7, "end": 311.14, "ta": "அவர்கள் தங்கள் பிதாக்களின் வீட்டுத் தலைவராகிய ஏப்பேர், இஷி, ஏலியேல், அஸரியேல், எரேமியா, ஒதாவியா, யாதியேல் என்பவர்கள் பராக்கிரம வீரரான மனுஷரும் பேர்பெற்ற தலைவருமாயிருந்தார்கள்.", "en": "And these were the heads of the house of their fathers, even Epher, and Ishi, and Eliel, and Azriel, and Jeremiah, and Hodaviah, and Jahdiel, mighty men of valour, famous men, and heads of the house of their fathers."}, {"verse": 25, "start": 311.14, "end": 323.84, "ta": "அவர்கள் தங்கள் பிதாக்களின் தேவனுக்குத் துரோகம்பண்ணி, தேவன் அவர்களுக்கு முன்பாக அழித்திருந்த தேச ஜனங்களின் தேவர்களைப் பின்பற்றிச் சோரம்போனார்கள்.", "en": "And they transgressed against the God of their fathers, and went a whoring after the gods of the people of the land, whom God destroyed before them."}, {"verse": 26, "start": 323.84, "end": 351.28, "ta": "ஆகையால் இஸ்ரவேலின் தேவன் அசீரியா ராஜாவாகிய பூலின் ஆவியையும், அசீரியா ராஜாவாகிய தில்காத்பில்நேசரின் ஆவியையும் எழுப்பினதினாலே, அவன் ரூபனியரும், காத்தியரும் மனாசேயின் பாதிக்கோத்திரத்தாருமாகிய அவர்களைச் சிறைபிடித்து இந்நாள்வரைக்கும் இருக்கிறதுபோல, ஆலாவுக்கும் ஆபோருக்கும் ஆராவுக்கும் கோசான் ஆற்றங்கரைக்கும் கொண்டுபோனான்.", "en": "And the God of Israel stirred up the spirit of Pul king of Assyria, and the spirit of Tilgath-pilneser king of Assyria, and he carried them away, even the Reubenites, and the Gadites, and the half tribe of Manasseh, and brought them unto Halah, and Habor, and Hara, and to the river Gozan, unto this day."}]}, "6": {"chapter": 6, "duration": 725.21, "audio_url": "audio_ot/OT13_06.mp3", "total_verses": 81, "verses": [{"verse": 1, "start": 3.8, "end": 9.55, "ta": "லேவியின் குமாரர், கெர்சோன், கோகாத், மெராரி என்பவர்கள்.", "en": "The sons of Levi; Gershon, Kohath, and Merari."}, {"verse": 2, "start": 9.55, "end": 16.5, "ta": "கோகாத்தின் குமாரர், அம்ராம், இத்சார், எப்ரோன், ஊசியேல் என்பவர்கள்.", "en": "And the sons of Kohath; Amram, Izhar, and Hebron, and Uzziel."}, {"verse": 3, "start": 16.5, "end": 28.81, "ta": "அம்ராமின் பிள்ளைகள், ஆரோன், மோசே, மிரியாம் என்பவர்கள்; ஆரோனின் குமாரர், நாதாப், அபியூ, எலெயாசர், இத்தாமார் என்பவர்கள்.", "en": "And the children of Amram; Aaron, and Moses, and Miriam. The sons also of Aaron; Nadab, and Abihu, Eleazar, and Ithamar."}, {"verse": 4, "start": 28.81, "end": 34.88, "ta": "எலெயாசார் பினெகாசைப் பெற்றான்; பினெகாஸ் அபிசுவாவைப் பெற்றான்.", "en": "Eleazar begat Phinehas, Phinehas begat Abishua,"}, {"verse": 5, "start": 34.88, "end": 40.07, "ta": "அபிசுவா புக்கியைப் பெற்றான், புக்கி ஊசியைப் பெற்றான்.", "en": "And Abishua begat Bukki, and Bukki begat Uzzi,"}, {"verse": 6, "start": 40.07, "end": 45.66, "ta": "ஊசி செராகியாவைப் பெற்றான்; செரகியா மெராயோதைப் பெற்றான்.", "en": "And Uzzi begat Zerahiah, and Zerahiah begat Meraioth,"}, {"verse": 7, "start": 45.66, "end": 51.26, "ta": "மெரயோத் அமரியாவைப் பெற்றான்; அமரியா அகிதூபைப் பெற்றான்.", "en": "Meraioth begat Amariah, and Amariah begat Ahitub,"}, {"verse": 8, "start": 51.26, "end": 56.85, "ta": "அகிதூப் சாதோக்கைப் பெற்றான்; சாதோக் அகிமாசைப் பெற்றான்.", "en": "And Ahitub begat Zadok, and Zadok begat Ahimaaz,"}, {"verse": 9, "start": 56.85, "end": 62.44, "ta": "அகிமாஸ் அசரியாவைப் பெற்றான்; அசரியா யோகனானைப் பெற்றான்.", "en": "And Ahimaaz begat Azariah, and Azariah begat Johanan,"}, {"verse": 10, "start": 62.44, "end": 71.87, "ta": "யோகனான் அசரியாவைப் பெற்றான்; சாலொமோன் எருசலேமில் கட்டின ஆலயத்திலே ஆசாரிய பணிவிடையைச் செய்தவன் இவன்தான்.", "en": "And Johanan begat Azariah, (he it is that executed the priest’s office in the temple that Solomon built in Jerusalem:)"}, {"verse": 11, "start": 71.87, "end": 77.38, "ta": "அசரியா அமரியாவைப் பெற்றான்; அமரியா அகிதூபைப் பெற்றான்.", "en": "And Azariah begat Amariah, and Amariah begat Ahitub,"}, {"verse": 12, "start": 77.38, "end": 83.05, "ta": "அகிதூப் சாதோக்கைப் பெற்றான்; சாதோக் சல்லுூமைப் பெற்றான்.", "en": "And Ahitub begat Zadok, and Zadok begat Shallum,"}, {"verse": 13, "start": 83.05, "end": 89.28, "ta": "சல்லுூம் இல்க்கியாவைப் பெற்றான்; இல்க்கியா அசரியாவைப் பெற்றான்.", "en": "And Shallum begat Hilkiah, and Hilkiah begat Azariah,"}, {"verse": 14, "start": 89.28, "end": 94.96, "ta": "அசரியா செராயாவைப் பெற்றான்; செராயா யோசதாக்கைப் பெற்றான்.", "en": "And Azariah begat Seraiah, and Seraiah begat Jehozadak,"}, {"verse": 15, "start": 94.96, "end": 106.46, "ta": "கர்த்தர் நேபுகாத்நேச்சாரைக்கொண்டு யூதா ஜனங்களையும் எருசலேமியரையும் சிறைபிடித்துக்கொண்டுபோகச் செய்தபோது யோசதாக்கும் சிறைப்பட்டுப்போனான்.", "en": "And Jehozadak went into captivity , when the LORD carried away Judah and Jerusalem by the hand of Nebuchadnezzar."}, {"verse": 16, "start": 106.46, "end": 112.21, "ta": "லேவியின் குமாரர், கெர்சோம், கோகாத், மெராரி என்பவர்களே.", "en": "The sons of Levi; Gershom, Kohath, and Merari."}, {"verse": 17, "start": 112.21, "end": 117.97, "ta": "கெர்சோமுடைய குமாரரின் நாமங்கள், லிப்னி, சிமேயி என்பவைகள்.", "en": "And these be the names of the sons of Gershom; Libni, and Shimei."}, {"verse": 18, "start": 117.97, "end": 124.92, "ta": "கோகாத்தின் குமாரர், அம்ராம், இத்சார், எப்ரோன், ஊசியேல் என்பவர்கள்.", "en": "And the sons of Kohath were , Amram, and Izhar, and Hebron, and Uzziel."}, {"verse": 19, "start": 124.92, "end": 134.02, "ta": "மெராரியின் குமாரர், மகேலி, மூசி என்பவர்கள். லேவியருக்கு அவர்கள் பிதாக்கள் வழியாய் உண்டான வம்சங்கள்:", "en": "The sons of Merari; Mahli, and Mushi. And these are the families of the Levites according to their fathers."}, {"verse": 20, "start": 134.02, "end": 141.13, "ta": "கெர்சோமின் குமாரன் லிப்னி; இவன் குமாரன் யாகாத்; இவன் குமாரன் சிம்மா.", "en": "Of Gershom; Libni his son, Jahath his son, Zimmah his son,"}, {"verse": 21, "start": 141.13, "end": 149.84, "ta": "இவன் குமாரன் யோவா; இவன் குமாரன் இத்தோ; இவன் குமாரன் சேரா; இவன் குமாரன் யாத்திராயி.", "en": "Joah his son, Iddo his son, Zerah his son, Jeaterai his son."}, {"verse": 22, "start": 149.84, "end": 157.43, "ta": "கோகாத்தின் குமாரரில் ஒருவன் அம்மினதாப், இவன் குமாரன் கோராகு, இவன் குமாரன் ஆசீர்.", "en": "The sons of Kohath; Amminadab his son, Korah his son, Assir his son,"}, {"verse": 23, "start": 157.43, "end": 164.46, "ta": "இவன் குமாரன் இல்க்கானா; இவன் குமாரன் அபியாசாப்; இவன் குமாரன் ஆசீர்.", "en": "Elkanah his son, and Ebiasaph his son, and Assir his son,"}, {"verse": 24, "start": 164.46, "end": 173.41, "ta": "இவன் குமாரன் எல்க்கானா; இவன் குமாரன் ஊரியேல்; இவன் குமாரன் ஊசியா; இவன் குமாரன் சவுல்.", "en": "Tahath his son, Uriel his son, Uzziah his son, and Shaul his son."}, {"verse": 25, "start": 173.41, "end": 178.36, "ta": "எல்க்கானாவின் குமாரர், அமாசாயி ஆகிமோத் என்பவர்கள்.", "en": "And the sons of Elkanah; Amasai, and Ahimoth."}, {"verse": 26, "start": 178.36, "end": 184.04, "ta": "எல்க்கானாவின் குமாரரில் ஒருவன் சோபாய், இவன் குமாரன் நாகாத்.", "en": "As for Elkanah: the sons of Elkanah; Zophai his son, and Nahath his son,"}, {"verse": 27, "start": 184.04, "end": 191.07, "ta": "இவன் குமாரன் எலியாப்; இவன் குமாரன் எரோகாம்; இவன் குமாரன் எல்க்கானா.", "en": "Eliab his son, Jeroham his son, Elkanah his son."}, {"verse": 28, "start": 191.07, "end": 196.98, "ta": "சாமுவேலின் குமாரர், அவனுடைய முதற்பேறான வஷ்னீ அபியா என்பவர்கள்.", "en": "And the sons of Samuel; the firstborn Vashni, and Abiah."}, {"verse": 29, "start": 196.98, "end": 206.65, "ta": "மெராரியின் குமாரரில் ஒருவன் மகேலி; இவன் குமாரன் லிப்னி; இவன் குமாரன் சிமேயி; இவன் குமாரன் ஊசா.", "en": "The sons of Merari; Mahli, Libni his son, Shimei his son, Uzza his son,"}, {"verse": 30, "start": 206.65, "end": 213.12, "ta": "இவன் குமாரன் சிமெயா; இவன் குமாரன் அகியா; இவன் குமாரன் அசாயா.", "en": "Shimea his son, Haggiah his son, Asaiah his son."}, {"verse": 31, "start": 213.12, "end": 222.39, "ta": "கர்த்தருடைய பெட்டி நிலைபெற்றபோது, தாவீது கர்த்தருடைய ஆலயத்தில் சங்கீத சேவையை நடத்துகிறதற்கு ஸ்தாபித்தவர்களும்,", "en": "And these are they whom David set over the service of song in the house of the LORD , after that the ark had rest."}, {"verse": 32, "start": 222.39, "end": 239.72, "ta": "சாலொமோன் எருசலேமிலே கர்த்தருடைய ஆலயத்தைக் கட்டித் தீருமட்டும் ஆசரிப்புக் கூடார வாசஸ்தலத்திற்கு முன்பாக சங்கீத சேவனையுடன் தங்கள் முறைமையின்படியே பணிவிடை செய்துவந்தவர்களுமாகிய மனுஷரும் அவர்கள் குமாரருமானவர்கள்.", "en": "And they ministered before the dwelling place of the tabernacle of the congregation with singing, until Solomon had built the house of the LORD in Jerusalem: and then they waited on their office according to their order."}, {"verse": 33, "start": 239.72, "end": 248.83, "ta": "கோகாத்தியரின் குமாரரில் ஏமான் என்னும் பாடகன்; இவன் யோவேலின் குமாரன்; இவன் சாமுவேலின் குமாரன்.", "en": "And these are they that waited with their children. Of the sons of the Kohathites: Heman a singer, the son of Joel, the son of Shemuel,"}, {"verse": 34, "start": 248.83, "end": 258.9, "ta": "இவன் எல்க்கானாவின் குமாரன்; இவன் யெரொகாமின் குமாரன்; இவன் எலியேலின் குமாரன்; இவன் தோவாகின் குமாரன்.", "en": "The son of Elkanah, the son of Jeroham, the son of Eliel, the son of Toah,"}, {"verse": 35, "start": 258.9, "end": 268.96, "ta": "இவன் சூப்பின் குமாரன்; இவன் இல்க்கானாவின் குமாரன்; இவன் மாகாத்தின் குமாரன்; இவன் அமாசாயின் குமாரன்.", "en": "The son of Zuph, the son of Elkanah, the son of Mahath, the son of Amasai,"}, {"verse": 36, "start": 268.96, "end": 279.35, "ta": "இவன் எல்க்கானாவின் குமாரன்; இவன் யோவேலின் குமாரன்; இவன் அசரியாவின் குமாரன்; இவன் செப்பனியாவின் குமாரன்.", "en": "The son of Elkanah, the son of Joel, the son of Azariah, the son of Zephaniah,"}, {"verse": 37, "start": 279.35, "end": 288.86, "ta": "இவன் தாகாதின் குமாரன்; இவன் ஆசீரின் குமாரன்; இவன் எபியாசாப்பின் குமாரன், இவன் கோராகின் குமாரன்.", "en": "The son of Tahath, the son of Assir, the son of Ebiasaph, the son of Korah,"}, {"verse": 38, "start": 288.86, "end": 297.96, "ta": "இவன் இத்சாரின் குமாரன்; இவன் கோகாத்தின் குமாரன்; இவன் இஸ்ரவேலின் குமாரனாகிய லேவியின் குமாரன்.", "en": "The son of Izhar, the son of Kohath, the son of Levi, the son of Israel."}, {"verse": 39, "start": 297.96, "end": 307.63, "ta": "இவன் சகோதரனாகிய ஆசாப் இவன் வலதுபக்கத்திலே நிற்பான், ஆசாப் பெரகியாவின் குமாரன்; இவன் சிமேயாவின் குமாரன்.", "en": "And his brother Asaph, who stood on his right hand, even Asaph the son of Berachiah, the son of Shimea,"}, {"verse": 40, "start": 307.63, "end": 315.3, "ta": "இவன் மிகாவேலின் குமாரன்; இவன் பாசெயாவின் குமாரன்; இவன் மல்கியாவின் குமாரன்.", "en": "The son of Michael, the son of Baaseiah, the son of Malchiah,"}, {"verse": 41, "start": 315.3, "end": 322.57, "ta": "இவன் எத்னியின் குமாரன்; இவன் சேராவின் குமாரன்; இவன் அதாயாவின் குமாரன்.", "en": "The son of Ethni, the son of Zerah, the son of Adaiah,"}, {"verse": 42, "start": 322.57, "end": 329.92, "ta": "இவன் ஏத்தானின் குமாரன்; இவன் சிம்மாவின் குமாரன்; இவன் சீமேயின் குமாரன்.", "en": "The son of Ethan, the son of Zimmah, the son of Shimei,"}, {"verse": 43, "start": 329.92, "end": 337.19, "ta": "இவன் யாகாதின் குமாரன்; இவன் கெர்சோமின் குமாரன்; இவன் லேவியின் குமாரன்.", "en": "The son of Jahath, the son of Gershom, the son of Levi."}, {"verse": 44, "start": 337.19, "end": 351.73, "ta": "மெராரியின் புத்திரராகிய இவர்களுடைய சகோதரர் இடதுபக்கத்திலே நிற்பார்கள்; அவர்களில் ஏதான் என்பவன் கிஷியின் குமாரன், இவன் அப்தியின் குமாரன்; இவன் மல்கின் குமாரன்.", "en": "And their brethren the sons of Merari stood on the left hand: Ethan the son of Kishi, the son of Abdi, the son of Malluch,"}, {"verse": 45, "start": 351.73, "end": 359.08, "ta": "இவன் அபியாவின் குமாரன் இவன் அமத்சியாவின் குமாரன்; இவன் இல்க்கியாவின் குமாரன்.", "en": "The son of Hashabiah, the son of Amaziah, the son of Hilkiah,"}, {"verse": 46, "start": 359.08, "end": 366.27, "ta": "இவன் அம்சியின் குமாரன்; இவன் பானியின் குமாரன்; இவன் சாமேரின் குமாரன்.", "en": "The son of Amzi, the son of Bani, the son of Shamer,"}, {"verse": 47, "start": 366.27, "end": 375.94, "ta": "இவன் மகேலியின் குமாரன்; இவன் மூசியின் குமாரன்; இவன் மெராரியின் குமாரன்; இவன் லேவியின் குமாரன்.", "en": "The son of Mahli, the son of Mushi, the son of Merari, the son of Levi."}, {"verse": 48, "start": 375.94, "end": 385.13, "ta": "அவர்கள் சகோதரராகிய மற்ற லேவியர் தேவனுடைய ஆலயமாகிய வாசஸ்தலத்தின் பணிவிடைக்கெல்லாம் வைக்கப்பட்டிருந்தார்கள்.", "en": "Their brethren also the Levites were appointed unto all manner of service of the tabernacle of the house of God."}, {"verse": 49, "start": 385.13, "end": 407.34, "ta": "ஆரோனும் அவன் குமாரரும் சர்வாங்க தகனபலிபீடத்தின்மேல் பலியிட்டுத் தூபங்காட்டும் பீடத்தின்மேல் தூபங்காட்டி, மகா பரிசுத்த ஸ்தலத்தின் எல்லாவேலைக்கும், தேவனுடைய தாசனாகிய மோசே கற்பித்தபடியெல்லாம் இஸ்ரவேலுக்காகப் பாவநிவிர்த்தியுண்டாக்குகிறதற்கும் வைக்கப்பட்டிருந்தார்கள்.", "en": "But Aaron and his sons offered upon the altar of the burnt offering, and on the altar of incense, and were appointed for all the work of the place most holy, and to make an atonement for Israel, according to all that Moses the servant of God had commanded."}, {"verse": 50, "start": 407.34, "end": 414.69, "ta": "ஆரோனின் குமாரரில் எலெயாசர் என்பவனுடைய குமாரன் பினேகாஸ்; இவன் குமாரன் அபிசுவா.", "en": "And these are the sons of Aaron; Eleazar his son, Phinehas his son, Abishua his son,"}, {"verse": 51, "start": 414.69, "end": 421.0, "ta": "இவன் குமாரன் புக்கி; இவன் குமாரன் ஊசி, இவன் குமாரன் செராகியா.", "en": "Bukki his son, Uzzi his son, Zerahiah his son,"}, {"verse": 52, "start": 421.0, "end": 428.03, "ta": "இவன் குமாரன் மெராயோத்; இவன் குமாரன் அமரியா; இவன் குமாரன் அகித்தூப்.", "en": "Meraioth his son, Amariah his son, Ahitub his son,"}, {"verse": 53, "start": 428.03, "end": 432.58, "ta": "இவன் குமாரன் சாதோக்; இவன் குமாரன் அகிமாஸ்.", "en": "Zadok his son, Ahimaaz his son."}, {"verse": 54, "start": 432.58, "end": 443.85, "ta": "அவர்கள் பேட்டைகளின்படியே அவர்கள் எல்லைக்குள்ளான அவர்கள் வாசஸ்தலங்களாவன: கோகாத்தியரின் வம்சமான ஆரோனின் புத்திரருக்கு விழுந்த சீட்டின்படியே,", "en": "Now these are their dwelling places throughout their castles in their coasts, of the sons of Aaron, of the families of the Kohathites: for theirs was the lot."}, {"verse": 55, "start": 443.85, "end": 451.44, "ta": "யூதாதேசத்திலிருக்கிற எப்ரோனையும் அதைச் சுற்றியிருக்கிற வெளிநிலங்களையும் கொடுத்தார்கள்.", "en": "And they gave them Hebron in the land of Judah, and the suburbs thereof round about it."}, {"verse": 56, "start": 451.44, "end": 460.3, "ta": "அந்தப் பட்டணத்தின் வயல்களையும் அதின் பட்டிகளையும் எப்புன்னேயின் குமாரனாகிய காலேபுக்குக் கொடுத்தார்கள்.", "en": "But the fields of the city, and the villages thereof, they gave to Caleb the son of Jephunneh."}, {"verse": 57, "start": 460.3, "end": 474.69, "ta": "இப்படியே ஆரோனின் புத்திரருக்கு எப்ரோன் என்னும் அடைக்கலப்பட்டணங்களில் ஒன்றையும், லிப்னாவையும் அதின் வெளிநிலங்களையும், யாத்தீரையும் எஸ்தமோவாவையும் அவற்றின் வெளிநிலங்களையும்,", "en": "And to the sons of Aaron they gave the cities of Judah, namely , Hebron, the city of refuge, and Libnah with her suburbs, and Jattir, and Eshtemoa, with their suburbs,"}, {"verse": 58, "start": 474.69, "end": 480.6, "ta": "ஈலேனையும் அதின் வெளிநிலங்களையும், தெபீரையும் அதின் வெளிநிலங்களையும்,", "en": "And Hilen with her suburbs, Debir with her suburbs,"}, {"verse": 59, "start": 480.6, "end": 486.83, "ta": "ஆசானையும் அதின் வெளிநிலங்களையும், பெத்சேமேசையும் அதின் வெளிநிலங்களையும்,", "en": "And Ashan with her suburbs, and Beth-shemesh with her suburbs:"}, {"verse": 60, "start": 486.83, "end": 505.84, "ta": "பென்யமீன் கோத்திரத்திலே கேபாவையும் அதின் வெளிநிலங்களையும், அலெமேத்தையும் அதின் வெளிநிலங்களையும், ஆனதோத்தையும் அதின் வெளிநிலங்களையும் கொடுத்தார்கள்; இவர்கள் வம்சங்களுக்குக் கொடுத்த இவர்கள் பட்டணங்களெல்லாம் பதின்மூன்று.", "en": "And out of the tribe of Benjamin; Geba with her suburbs, and Alemeth with her suburbs, and Anathoth with her suburbs. All their cities throughout their families were thirteen cities."}, {"verse": 61, "start": 505.84, "end": 518.87, "ta": "கோகாத்தின் மற்றப் புத்திரருக்கு வேறொரு கோத்திர வம்சத்திலும், பாதிக்கோத்திரமாகிய மனாசேயின் பாதியிலும் விழுந்த சீட்டின்படியே பத்துப் பட்டணங்கள் இருந்தது.", "en": "And unto the sons of Kohath, which were left of the family of that tribe, were cities given out of the half tribe, namely, out of the half tribe of Manasseh, by lot, ten cities."}, {"verse": 62, "start": 518.87, "end": 536.04, "ta": "கெர்சோமின் புத்திரருக்கு அவர்கள் வம்சங்களின்படியே, இசக்கார் கோத்திரத்திலும், ஆசேர் கோத்திரத்திலும், நப்தலி கோத்திரத்திலும், பாசானிலிருக்கிற மனாசே கோத்திரத்திலும் பதின்மூன்று பட்டணங்கள் இருந்தது.", "en": "And to the sons of Gershom throughout their families out of the tribe of Issachar, and out of the tribe of Asher, and out of the tribe of Naphtali, and out of the tribe of Manasseh in Bashan, thirteen cities."}, {"verse": 63, "start": 536.04, "end": 550.9, "ta": "மெராரியின் புத்திரருக்கு அவர்கள் வம்சங்களின்படியே ரூபன் கோத்திரத்திலும், காத் கோத்திரத்திலும், செபுலோன் கோத்திரத்திலும் விழுந்த சீட்டின்படி பன்னிரண்டு பட்டணங்கள் இருந்தது.", "en": "Unto the sons of Merari were given by lot, throughout their families, out of the tribe of Reuben, and out of the tribe of Gad, and out of the tribe of Zebulun, twelve cities."}, {"verse": 64, "start": 550.9, "end": 559.13, "ta": "அப்படியே இஸ்ரவேல் புத்திரர் லேவியருக்குக் கொடுத்த பட்டணங்களும் அவைகளின் வெளிநிலங்களும் என்னவென்றால்,", "en": "And the children of Israel gave to the Levites these cities with their suburbs."}, {"verse": 65, "start": 559.13, "end": 576.39, "ta": "சீட்டுப்போட்டு, சிலருக்கு தாண் புத்திரரின் கோத்திரத்திலும், சிமியோன் புத்திரரின் கோத்திரத்திலும், பென்யமீன் புத்திரரின் கோத்திரத்திலும், பேர்பேராகச் சொல்லப்பட்ட அந்தப் பட்டணங்களைக் கொடுத்தார்கள்.", "en": "And they gave by lot out of the tribe of the children of Judah, and out of the tribe of the children of Simeon, and out of the tribe of the children of Benjamin, these cities, which are called by their names."}, {"verse": 66, "start": 576.39, "end": 586.14, "ta": "கோகாத் புத்திரரில் மற்ற வம்சங்களுக்கு அவர்கள் எல்லையான பட்டணங்கள் அவர்களுக்கு எப்பிராயீம் கோத்திரத்திலே இருந்தது.", "en": "And the residue of the families of the sons of Kohath had cities of their coasts out of the tribe of Ephraim."}, {"verse": 67, "start": 586.14, "end": 598.68, "ta": "எவையெனில், அடைக்கலப்பட்டணங்களில் அவர்களுக்கு எப்பிராயீம் மலைத்தேசத்திலிருக்கிற சீகேமையும் அதின் வெளிநிலங்களையும், கேசேரையும் அதின் வெளிநிலங்களையும்,", "en": "And they gave unto them, of the cities of refuge, Shechem in mount Ephraim with her suburbs; they gave also Gezer with her suburbs,"}, {"verse": 68, "start": 598.68, "end": 605.23, "ta": "யோக்மேயாமையும் அதின் வெளிநிலங்களையும், பேத்ஓரோனையும் அதின் வெளிநிலங்களையும்,", "en": "And Jokmeam with her suburbs, and Beth-horon with her suburbs,"}, {"verse": 69, "start": 605.23, "end": 611.7, "ta": "ஆயலோனையும் அதின் வெளிநிலங்களையும், காத்ரிம்மோனையும் அதின் வெளிநிலங்களையும்,", "en": "And Aijalon with her suburbs, and Gath-rimmon with her suburbs:"}, {"verse": 70, "start": 611.7, "end": 626.88, "ta": "மனாசேயின் பாதிக்கோத்திரத்திலே ஆனேரையும் அதின் வெளிநிலங்களையும், பீலியாமையும் அதின் வெளிநிலங்களையும் கொடுத்தார்கள்; இவைகள் காகாத் புத்திரரிலுள்ள மற்ற வம்சங்களுக்கு இருந்தது.", "en": "And out of the half tribe of Manasseh; Aner with her suburbs, and Bileam with her suburbs, for the family of the remnant of the sons of Kohath."}, {"verse": 71, "start": 626.88, "end": 638.46, "ta": "கெர்சோம் புத்திரருக்கு மனாசேயின் பாதிக்கோத்திர வம்சத்திலே பாசானிலிருக்கிற கோலானும் அதின் வெளிநிலங்களும், அஸ்தரோத்தும் அதின் வெளிநிலங்களும்,", "en": "Unto the sons of Gershom were given out of the family of the half tribe of Manasseh, Golan in Bashan with her suburbs, and Ashtaroth with her suburbs:"}, {"verse": 72, "start": 638.46, "end": 645.97, "ta": "இசக்கார் கோத்திரத்திலே கேதேசும் அதின் வெளிநிலங்களும், தாபிராத்தும் அதின் வெளிநிலங்களும்,", "en": "And out of the tribe of Issachar; Kedesh with her suburbs, Daberath with her suburbs,"}, {"verse": 73, "start": 645.97, "end": 651.41, "ta": "ராமோத்தும் அதின் வெளிநிலங்களும், ஆனேமும் அதின் εெளிநிலங்கγும்,", "en": "And Ramoth with her suburbs, and Anem with her suburbs:"}, {"verse": 74, "start": 651.41, "end": 658.44, "ta": "ஆசேர் கோத்திரத்திலே மாஷாலும் அதின் வெளிநிலங்களும், அப்தோனும் அதின் வெளிநிலங்களும்,", "en": "And out of the tribe of Asher; Mashal with her suburbs, and Abdon with her suburbs,"}, {"verse": 75, "start": 658.44, "end": 664.51, "ta": "உக்கோக்கும் அதின் வெளிநிலங்களும், ரேகோபும் அதின் வெளிநிலங்களும்.", "en": "And Hukok with her suburbs, and Rehob with her suburbs:"}, {"verse": 76, "start": 664.51, "end": 677.69, "ta": "நப்தலி கோத்திரத்திலே கலிலேயாவிலிருக்கிற கேதேசும் அதின் வெளிநிலங்களும், அம்மோனும் அதின் வெளிநிலங்களும், கிரியாத்தாயிமும் அதின் வெளிநிலங்களும் இருந்தது.", "en": "And out of the tribe of Naphtali; Kedesh in Galilee with her suburbs, and Hammon with her suburbs, and Kirjathaim with her suburbs."}, {"verse": 77, "start": 677.69, "end": 687.6, "ta": "மெராரியின் மற்றப் புத்திரருக்கு செபுலோன் கோத்திரத்திலே ரிம்மோனும் அதின் வெளிநிலங்களும், தாபோரும் அதின் வெளிநிலங்களும்,", "en": "Unto the rest of the children of Merari were given out of the tribe of Zebulun, Rimmon with her suburbs, Tabor with her suburbs:"}, {"verse": 78, "start": 687.6, "end": 702.54, "ta": "எரிகோவுக்கு அப்புறமாயிருக்கிற யோர்தானுக்கு அப்பாலே யோர்தானுக்குக் கிழக்கே இருக்கிற ரூபன் கோத்திரத்திலே வனாந்தரத்திலுள்ள பேசேரும் அதன் வெளிநிலங்களும், யாத்சாவும் அதன் வெளிநிலங்களும்,", "en": "And on the other side Jordan by Jericho, on the east side of Jordan, were given them out of the tribe of Reuben, Bezer in the wilderness with her suburbs, and Jahzah with her suburbs,"}, {"verse": 79, "start": 702.54, "end": 708.53, "ta": "கேதேமோத்தும் அதின் வெளிநிலங்களும், மேப்பாத்தும் அதின் வெளிநிலங்களும்,", "en": "Kedemoth also with her suburbs, and Mephaath with her suburbs:"}, {"verse": 80, "start": 708.53, "end": 717.08, "ta": "காத் கோத்திரத்திலே கீலேயாத்திலுள்ள ராமோத்தும் அதின் வெளிநிலங்களும், மக்னாயீமும் அதின் வெளிநிலங்களும்,", "en": "And out of the tribe of Gad; Ramoth in Gilead with her suburbs, and Mahanaim with her suburbs,"}, {"verse": 81, "start": 717.08, "end": 723.71, "ta": "எஸ்போனும் அதின் வெளிநிலங்களும், யாசேரும் அதின் வெளிநிலங்களும் இருந்தது.", "en": "And Heshbon with her suburbs, and Jazer with her suburbs."}]}, "7": {"chapter": 7, "duration": 504.23, "audio_url": "audio_ot/OT13_07.mp3", "total_verses": 40, "verses": [{"verse": 1, "start": 3.8, "end": 11.5, "ta": "இசக்காருடைய குமாரர், தோலா, பூவா, யசுப், சிம்ரோன் என்னும் நாலுபேர்.", "en": "Now the sons of Issachar were , Tola, and Puah, Jashub, and Shimron, four."}, {"verse": 2, "start": 11.5, "end": 38.22, "ta": "தோலாவின் குமாரர், ஊசி, ரெப்பாயா, யெரியேல், யக்மாயி, இப்சாம், சாமுவேல் என்பவர்கள்; தோலாவுக்குப் பிறந்த இவர்கள் தங்கள் பிதாக்கள் வம்சத்தலைவரும் தங்கள் சந்ததிகளிலே பராக்கிரமசாலிகளுமாயிருந்தார்கள்; தாவீதின் நாட்களில் அவர்கள் தொகை இருபதினாயிரத்து அறுநூறுபேராயிருந்தது.", "en": "And the sons of Tola; Uzzi, and Rephaiah, and Jeriel, and Jahmai, and Jibsam, and Shemuel, heads of their father’s house, to wit , of Tola: they were valiant men of might in their generations; whose number was in the days of David two and twenty thousand and six hundred."}, {"verse": 3, "start": 38.22, "end": 53.62, "ta": "ஊசியின் குமாரரில் ஒருவன் இஸ்ரகியா; இஸ்ரகியாவின் குமாரர், மிகாயேல், ஒபதியா, யோவேல், இஷியா என்பவர்கள்; இவர்கள் ஐந்துபேரும் தலைவராயிருந்தார்கள்.", "en": "And the sons of Uzzi; Izrahiah: and the sons of Izrahiah; Michael, and Obadiah, and Joel, Ishiah, five: all of them chief men."}, {"verse": 4, "start": 53.62, "end": 70.26, "ta": "அவர்கள் பிதாக்கள் வம்சத்தாரானவர்கள் சந்ததிகளில் யுத்தமனுஷரான கூட்டங்கள் முப்பத்தாறாயிரம்பேர் அவர்களோடிருந்தார்கள்; அவர்களுக்கு அநேகம் பெண்ஜாதிகளும் பிள்ளைகளும் இருந்தார்கள்.", "en": "And with them, by their generations, after the house of their fathers, were bands of soldiers for war, six and thirty thousand men: for they had many wives and sons."}, {"verse": 5, "start": 70.26, "end": 83.98, "ta": "இசக்காருடைய மற்ற எல்லா வம்சங்களிலும் அவர்களுக்குச் சகோதரரான பராக்கிரமசாலிகள் தங்கள் வம்ச அட்டவணைகளின்படியெல்லாம் எண்பத்தேழாயிரம்பேராயிருந்தார்கள்.", "en": "And their brethren among all the families of Issachar were valiant men of might, reckoned in all by their genealogies fourscore and seven thousand."}, {"verse": 6, "start": 83.98, "end": 91.14, "ta": "பென்யமீன் குமாரர், பேலா, பெகேர், யெதியாயேல் என்னும் மூன்றுபேர்.", "en": "The sons of Benjamin; Bela, and Becher, and Jediael, three."}, {"verse": 7, "start": 91.14, "end": 113.98, "ta": "பேலாவின் குமாரர், எஸ்போன், ஊசி, ஊசியேல், யெரிமோத், இரி என்பவர்கள்; இவர்கள் தங்கள் பிதாக்களின் வம்சத்தில் பராக்கிரமசாலிகளான ஐந்து தலைவராயிருந்தார்கள்; இவர்கள் வம்ச அட்டவணைக்குள்ளானவர்கள் இருபத்தீராயிரத்து முப்பத்துநாலுபேர்.", "en": "And the sons of Bela; Ezbon, and Uzzi, and Uzziel, and Jerimoth, and Iri, five; heads of the house of their fathers, mighty men of valour; and were reckoned by their genealogies twenty and two thousand and thirty and four."}, {"verse": 8, "start": 113.98, "end": 130.17, "ta": "பெகேரின் குமாரர், செமிரா, யோவாஸ், எலியேசர், எலியோனாய், உம்ரி, யெரிமோத், அபியா, ஆனதோத், அலமேத் என்பவர்கள்; இவர்கள் எல்லாரும் பெகேரின் குமாரர்.", "en": "And the sons of Becher; Zemira, and Joash, and Eliezer, and Elioenai, and Omri, and Jerimoth, and Abiah, and Anathoth, and Alameth. All these are the sons of Becher."}, {"verse": 9, "start": 130.17, "end": 141.23, "ta": "தங்கள் பிதாக்களின் வம்சத்தலைவராகிய அவர்கள் சந்ததிகளின் அட்டவணைக்குள்ளான பராக்கிரமாலிகள் இருபதினாயிரத்து இருநூறுபேர்.", "en": "And the number of them, after their genealogy by their generations, heads of the house of their fathers, mighty men of valour, was twenty thousand and two hundred."}, {"verse": 10, "start": 141.23, "end": 156.19, "ta": "யெதியாயேலின் குமாரரில் ஒருவன் பில்கான்; பில்கானின் குமாரர், ஏயூஷ், பென்யமீன், ஏகூத், கெனானா, சேத்தான், தர்ஷீஸ், அகிஷாகார் என்பவர்கள்.", "en": "The sons also of Jediael; Bilhan: and the sons of Bilhan; Jeush, and Benjamin, and Ehud, and Chenaanah, and Zethan, and Tharshish, and Ahishahar."}, {"verse": 11, "start": 156.19, "end": 173.53, "ta": "யெதியாயேலின் குமாரராகிய இவர்கள் எல்லாரும் தங்கள் பிதாக்கள் வம்சத்தாரில் தலைவராயிருந்தார்கள்; இவர்களில் யுத்தத்திற்குப் போகத்தக்க சேவகரான பராக்கிரமசாலிகள் பதினேழாயிரத்து இருநூறுபேர்.", "en": "All these the sons of Jediael, by the heads of their fathers, mighty men of valour, were seventeen thousand and two hundred soldiers , fit to go out for war and battle."}, {"verse": 12, "start": 173.53, "end": 180.88, "ta": "சுப்பீமும், உப்பீமும் ஈரின் குமாரர், ஊசிம் ஆகேரின் குமாரரில் ஒருவன்.", "en": "Shuppim also, and Huppim, the children of Ir, and Hushim, the sons of Aher."}, {"verse": 13, "start": 180.88, "end": 190.43, "ta": "நப்தலியின் குமாரரான பில்காளின் பேரன்மார், யாத்சியேல், கூனி, எத்சோ, சல்லுூம் என்பவர்கள்.", "en": "The sons of Naphtali; Jahziel, and Guni, and Jezer, and Shallum, the sons of Bilhah."}, {"verse": 14, "start": 190.43, "end": 205.66, "ta": "மனாசேயின் புத்திரரில் ஒருவன் குலஸ்திரீயினிடத்தில் பிறந்த அஸ்ரியேல்; அவன் மறுமனையாட்டியாகிய அராமிய ஸ்திரீயினிடத்தில் கீலேயாத்தின் தகப்பனாகிய மாகீர் பிறந்தான்.", "en": "The sons of Manasseh; Ashriel, whom she bare: ( but his concubine the Aramitess bare Machir the father of Gilead:"}, {"verse": 15, "start": 205.66, "end": 223.0, "ta": "மாகீர் மாக்காள் என்னும் பேருள்ள உப்பீம் சுப்பீம் என்பவர்களின் சகோதரியை விவாகம்பண்ணினான்; மனாசேயின் இரண்டாம் குமாரன் செலோப்பியாத்; செலோப்பியாத்திற்குக் குமாரத்திகளிருந்தார்கள்.", "en": "And Machir took to wife the sister of Huppim and Shuppim, whose sister’s name was Maachah;) and the name of the second was Zelophehad: and Zelophehad had daughters."}, {"verse": 16, "start": 223.0, "end": 239.28, "ta": "மாகீரின் பெண்ஜாதியாகிய மாக்காள் ஒரு குமாரனைப் பெற்று, அவனுக்குப் பேரேஸ் என்று பேரிட்டாள்; இவன் சகோதரன் பேர் சேரேஸ்; இவனுடைய குமாரர் ஊலாம், ரேகேம் என்பவர்கள்.", "en": "And Maachah the wife of Machir bare a son, and she called his name Peresh; and the name of his brother was Sheresh; and his sons were Ulam and Rakem."}, {"verse": 17, "start": 239.28, "end": 249.55, "ta": "ஊலாமின் குமாரரில் ஒருவன் பேதான்; இவர்கள் மனாசேயின் குமாரனாகிய மாகீருக்குப் பிறந்த கீலேயாத் புத்திரர்.", "en": "And the sons of Ulam; Bedan. These were the sons of Gilead, the son of Machir, the son of Manasseh."}, {"verse": 18, "start": 249.55, "end": 256.98, "ta": "இவன் சகோதரியாகிய அம்மொளெகேத் இஸ்கோதையும் அபியேசரையும் மாகலாவையும் பெற்றாள்.", "en": "And his sister Hammoleketh bare Ishod, and Abiezer, and Mahalah."}, {"verse": 19, "start": 256.98, "end": 264.5, "ta": "செமிதாவின் குமாரர், அகியான், சேகேம், லிக்கே, அனியாம் என்பவர்கள்.", "en": "And the sons of Shemida were, Ahian, and Shechem, and Likhi, and Aniam."}, {"verse": 20, "start": 264.5, "end": 279.55, "ta": "எப்பிராயீமின் குமாரரில் ஒருவன் சுத்தெலாக்; இவனுடைய குமாரன் பேரேத்; இவனுடைய குமாரன் தாகாத்; இவனுடைய குமாரன் எலாதா; இவனுடைய குமாரன் தாகாத்.", "en": "And the sons of Ephraim; Shuthelah, and Bered his son, and Tahath his son, and Eladah his son, and Tahath his son,"}, {"verse": 21, "start": 279.55, "end": 297.6, "ta": "இவனுடைய குமாரன் சாபாத்; இவனுடைய குமாரர் கத்தெலாக், எத்சேர், எலியாத்; இவர்கள் தேசத்தில் பிறந்த காத்தூராருடைய ஆடுமாடுகளைப் பிடிக்கப்போனபடியால் அவர்கள் இவர்களைக் கொன்றுபோட்டார்கள்.", "en": "And Zabad his son, and Shuthelah his son, and Ezer, and Elead, whom the men of Gath that were born in that land slew, because they came down to take away their cattle."}, {"verse": 22, "start": 297.6, "end": 308.22, "ta": "அவர்கள் தகப்பனாகிய எப்பிராயீம் அநேகநாள் துக்கங்கொண்டாடுகையில், அவன் சகோதரர் அவனுக்கு ஆறுதல் சொல்லவந்தார்கள்.", "en": "And Ephraim their father mourned many days, and his brethren came to comfort him."}, {"verse": 23, "start": 308.22, "end": 326.54, "ta": "பின்பு அவன் தன் பெண்ஜாதியினிடத்தில் பிரவேசித்ததினால், அவள் கர்ப்பந்தரித்து ஒரு குமாரனைப் பெற்றாள்; அவன், தன் குடும்பத்துக்குத் தீங்கு உண்டானதினால், இவனுக்குப் பெரீயா என்று பேரிட்டான்.", "en": "And when he went in to his wife, she conceived, and bare a son, and he called his name Beriah, because it went evil with his house."}, {"verse": 24, "start": 326.54, "end": 336.36, "ta": "இவனுடைய குமாரத்தியாகிய சேராள் கீழ்ப்புறமும் மேற்புறமுமான பெத்தோரோனையும், ஊசேன்சேராவையும் கட்டினவள்.", "en": "(And his daughter was Sherah, who built Beth-horon the nether, and the upper, and Uzzen-sherah.)"}, {"verse": 25, "start": 336.36, "end": 346.98, "ta": "அவனுடைய குமாரர், ரேப்பாக், ரேசேப் என்பவர்கள்; இவனுடைய குமாரன் தேலாக்; இவனுடைய குமாரன் தாகான்.", "en": "And Rephah was his son, also Resheph, and Telah his son, and Tahan his son,"}, {"verse": 26, "start": 346.98, "end": 355.21, "ta": "இவனுடைய குமாரன் லாதான், இவனுடைய குமாரன் அம்மியூத்; இவனுடைய குமாரன் எலிஷாமா.", "en": "Laadan his son, Ammihud his son, Elishama his son,"}, {"verse": 27, "start": 355.21, "end": 359.99, "ta": "இவனுடைய குமாரன் நூன்: இவனுடைய குமாரன் யோசுவா.", "en": "Non his son, Jehoshua his son."}, {"verse": 28, "start": 359.99, "end": 380.52, "ta": "அவர்களுடைய காணியாட்சியும், வாசஸ்தலங்களும், கிழக்கேயிருக்கிற நாரானும், மேற்கேயிருக்கிற கேசேரும் அதின் கிராமங்களும், பெத்தேலும் அதன் கிராமங்களும், சீகேமும் அதின் கிராமங்களும், காசாமட்டுக்குமுள்ள அதன் கிராமங்களும்,", "en": "And their possessions and habitations were , Beth-el and the towns thereof, and eastward Naaran, and westward Gezer, with the towns thereof; Shechem also and the towns thereof, unto Gaza and the towns thereof:"}, {"verse": 29, "start": 380.52, "end": 402.47, "ta": "மனாசே புத்திரரின் பக்கத்திலே பெத்செயானும் அதின் கிராமங்களும், தானாகும் அதின் கிராமங்களும், மெகிதோவும் அதின் கிராமங்களும், தோரும் அதின் கிராமங்களுமே; இவ்விடங்களில் இஸ்ரவேலின் குமாரனாகிய யோசேப்பின் புத்திரர் குடியிருந்தார்கள்.", "en": "And by the borders of the children of Manasseh, Beth-shean and her towns, Taanach and her towns, Megiddo and her towns, Dor and her towns. In these dwelt the children of Joseph the son of Israel."}, {"verse": 30, "start": 402.47, "end": 411.85, "ta": "ஆசேரின் குமாரர், இம்னா, இஸ்வா, இஸ்வி, பெரீயு என்பவர்கள்; இவர்கள் சகோதரி சேராள்.", "en": "The sons of Asher; Imnah, and Isuah, and Ishuai, and Beriah, and Serah their sister."}, {"verse": 31, "start": 411.85, "end": 420.52, "ta": "பெரீயாவின் குமாரர், ஏபேர், மல்கியேல் என்பவர்கள்; இவன் பிர்சாவீத்தின் தகப்பன்.", "en": "And the sons of Beriah; Heber, and Malchiel, who is the father of Birzavith."}, {"verse": 32, "start": 420.52, "end": 429.72, "ta": "ஏபேர் யப்லேத்தையும், சோமேரையும், ஒத்தாமையும், இவர்கள் சகோதரியாகிய சூகாளையும் பெற்றான்.", "en": "And Heber begat Japhlet, and Shomer, and Hotham, and Shua their sister."}, {"verse": 33, "start": 429.72, "end": 439.19, "ta": "யப்லேத்தின் குமாரர் பாராக், பிம்மால், ஆஸ்வாத் என்பவர்கள்; இவர்களே யப்லேத்தின் குமாரர்.", "en": "And the sons of Japhlet; Pasach, and Bimhal, and Ashvath. These are the children of Japhlet."}, {"verse": 34, "start": 439.19, "end": 445.39, "ta": "சோமேரின் குமாரர் அகி, ரோகா, எகூபா, ஆராம் என்பவர்கள்.", "en": "And the sons of Shamer; Ahi, and Rohgah, Jehubbah, and Aram."}, {"verse": 35, "start": 445.39, "end": 453.7, "ta": "அவன் சகோதரனாகிய ஏலேமின் குமாரர், சோபாக், இம்னா, சேலேஸ், ஆமால் என்பவர்கள்.", "en": "And the sons of his brother Helem; Zophah, and Imna, and Shelesh, and Amal."}, {"verse": 36, "start": 453.7, "end": 460.61, "ta": "சோபாக்கின் குமாரர், சூவாக், அர்னெப்பர், சூகால், பேரி, இம்ரா,", "en": "The sons of Zophah; Suah, and Harnepher, and Shual, and Beri, and Imrah,"}, {"verse": 37, "start": 460.61, "end": 467.42, "ta": "பேசேர், ஓத், சம்மா, சில்சா, இத்ரான், பேரா என்பவர்கள்.", "en": "Bezer, and Hod, and Shamma, and Shilshah, and Ithran, and Beera."}, {"verse": 38, "start": 467.42, "end": 473.44, "ta": "யெத்தேரின் குமாரர், எப்புன்னே பிஸ்பா, ஆரா என்பவர்கள்.", "en": "And the sons of Jether; Jephunneh, and Pispah, and Ara."}, {"verse": 39, "start": 473.44, "end": 480.08, "ta": "உல்லாவின் குமாரர், ஆராக், அன்னியேல், ரித்சியா என்பவர்கள்.", "en": "And the sons of Ulla; Arah, and Haniel, and Rezia."}, {"verse": 40, "start": 480.08, "end": 502.73, "ta": "ஆசேரின் புத்திரராகிய இவர்கள் எல்லாரும் தங்கள் பிதாக்களின் வம்சத்தலைவரும் தெரிந்துகொள்ளப்பட்ட பராக்கிரமசாலிகளும், பிரபுக்களின் தலைவருமாயிருந்தார்கள்; அவர்கள் வம்ச அட்டவணைகளில் யுத்தத்திற்குப் போகத்தக்க சேவகரின் இலக்கம் இருபத்தாறாயிரம்பேர்.", "en": "All these were the children of Asher, heads of their father’s house, choice and mighty men of valour, chief of the princes. And the number throughout the genealogy of them that were apt to the war and to battle was twenty and six thousand men."}]}, "8": {"chapter": 8, "duration": 318.83, "audio_url": "audio_ot/OT13_08.mp3", "total_verses": 40, "verses": [{"verse": 1, "start": 3.8, "end": 15.81, "ta": "பென்யமீன், பேலா என்னும் தன் மூத்த குமாரனையும், அஸ்பால் என்னும் இரண்டாம் குமாரனையும், அகராக் என்னும் மூன்றாம் குமாரனையும்,", "en": "Now Benjamin begat Bela his firstborn, Ashbel the second, and Aharah the third,"}, {"verse": 2, "start": 15.81, "end": 23.75, "ta": "நேகா என்னும் நாலாம் குமாரனையும், ரப்பா என்னும் ஐந்தாம் குமாரனையும் பெற்றான்.", "en": "Nohah the fourth, and Rapha the fifth."}, {"verse": 3, "start": 23.75, "end": 30.34, "ta": "பேலாவுக்கு இருந்த குமாரர் ஆதார், கேரா, அபியூத் என்பவர்கள்.", "en": "And the sons of Bela were, Addar, and Gera, and Abihud,"}, {"verse": 4, "start": 30.34, "end": 33.23, "ta": "அபிசுவா, நாமான், அகோவா,", "en": "And Abishua, and Naaman, and Ahoah,"}, {"verse": 5, "start": 33.23, "end": 39.37, "ta": "கேரா, செப்புப்பான், ஊராம் என்பவர்கள் எகூதின் குமாரர்.", "en": "And Gera, and Shephuphan, and Huram."}, {"verse": 6, "start": 39.37, "end": 52.46, "ta": "கேபாவின் குடிகளுக்கு மூப்பான தலைவராயிருந்து, இவர்களை மனாகாத்திற்கு அழைத்துக்கொண்டுபோனவர்கள், நாமான், அகியா, கேரா என்பவர்களே.", "en": "And these are the sons of Ehud: these are the heads of the fathers of the inhabitants of Geba, and they removed them to Manahath:"}, {"verse": 7, "start": 52.46, "end": 60.76, "ta": "கேரா அவர்களை அங்கே அழைத்துக்கொண்டுபோனபின்பு, ஊசாவையும், அகியூதையும் பெற்றான்.", "en": "And Naaman, and Ahiah, and Gera, he removed them, and begat Uzza, and Ahihud."}, {"verse": 8, "start": 60.76, "end": 71.96, "ta": "அவர்களை அனுப்பிவிட்டபின், சகராயீம் மோவாப் தேசத்திலே ஊகிம் பாராள் என்னும் தன் பெண்ஜாதிகளிடத்திலே பெற்ற பிள்ளைகளைத்தவிர,", "en": "And Shaharaim begat children in the country of Moab, after he had sent them away; Hushim and Baara were his wives."}, {"verse": 9, "start": 71.96, "end": 79.9, "ta": "தன் பெண்ஜாதியாகிய ஓதேசாலே யோவாபையும், சீபீயாவையும், மேசாவையும், மல்காமையும்,", "en": "And he begat of Hodesh his wife, Jobab, and Zibia, and Mesha, and Malcham,"}, {"verse": 10, "start": 79.9, "end": 90.47, "ta": "எயூசையும், சாகியாவையும், மிர்மாமவையும் பெற்றான். பிதாக்களின் தலைவரான இவர்கள் அவனுடைய குமாரர்.", "en": "And Jeuz, and Shachia, and Mirma. These were his sons, heads of the fathers."}, {"verse": 11, "start": 90.47, "end": 95.97, "ta": "ஊசிம் வழியாய் அவன் அபிதூபையும் எல்பாலையும் பெற்றான்.", "en": "And of Hushim he begat Abitub, and Elpaal."}, {"verse": 12, "start": 95.97, "end": 107.26, "ta": "எல்பாலின் குமாரர், ஏபேர், மீஷாம், சாமேத்; இவன் ஓனோவையும் லோதையும் அதின் கிராமங்களையும் உண்டாக்கினவன்.", "en": "The sons of Elpaal; Eber, and Misham, and Shamed, who built Ono, and Lod, with the towns thereof:"}, {"verse": 13, "start": 107.26, "end": 117.91, "ta": "பெரீயாவும் சேமாவும் ஆயலோன் குடிகளுடைய பிதாக்களிலே தலைவராயிருந்தார்கள்; இவர்கள் காத்தின் குடிகளை ஓட்டிவிட்டார்கள்", "en": "Beriah also, and Shema, who were heads of the fathers of the inhabitants of Aijalon, who drove away the inhabitants of Gath:"}, {"verse": 14, "start": 117.91, "end": 120.8, "ta": "அகியோ, சாஷாக், எரேமோத்,", "en": "And Ahio, Shashak, and Jeremoth,"}, {"verse": 15, "start": 120.8, "end": 123.6, "ta": "செபதியா, ஆராத், ஆதேர்,", "en": "And Zebadiah, and Arad, and Ader,"}, {"verse": 16, "start": 123.6, "end": 129.46, "ta": "காயேல், இஸ்பா, யோகா என்பவர்கள் பெரீயாவின் குமாரர்.", "en": "And Michael, and Ispah, and Joha, the sons of Beriah;"}, {"verse": 17, "start": 129.46, "end": 133.62, "ta": "செபதியா, மெசுல்லாம், இஸ்கி, ஏபேர்,", "en": "And Zebadiah, and Meshullam, and Hezeki, and Heber,"}, {"verse": 18, "start": 133.62, "end": 140.03, "ta": "இஸ்மெராயி, இஸ்லியா, யோபாப் என்பவர்கள் எல்பாலின் குமாரர்.", "en": "Ishmerai also, and Jezliah, and Jobab, the sons of Elpaal;"}, {"verse": 19, "start": 140.03, "end": 143.01, "ta": "யாக்கிம், சிக்ரி, சப்தி,", "en": "And Jakim, and Zichri, and Zabdi,"}, {"verse": 20, "start": 143.01, "end": 146.44, "ta": "எலியேனாய், சில்தாய், எலியேல்,", "en": "And Elienai, and Zilthai, and Eliel,"}, {"verse": 21, "start": 146.44, "end": 152.49, "ta": "அதாயா, பெராயா, சிம்ராத் என்பவர்கள் சிமியின் குமாரர்.", "en": "And Adaiah, and Beraiah, and Shimrath, the sons of Shimhi;"}, {"verse": 22, "start": 152.49, "end": 155.46, "ta": "இஸ்பான், ஏபேர், ஏலியேல்,", "en": "And Ishpan, and Heber, and Eliel,"}, {"verse": 23, "start": 155.46, "end": 158.35, "ta": "அப்தோன், சிக்ரி, ஆனான்,", "en": "And Abdon, and Zichri, and Hanan,"}, {"verse": 24, "start": 158.35, "end": 161.42, "ta": "அனனியா, ஏலாம், அந்தோதியா,", "en": "And Hananiah, and Elam, and Antothijah,"}, {"verse": 25, "start": 161.42, "end": 166.57, "ta": "இபிதியா, பெயேல் என்பவர்கள் ஆஷாக்கின் குமாரர்.", "en": "And Iphedeiah, and Penuel, the sons of Shashak;"}, {"verse": 26, "start": 166.57, "end": 170.09, "ta": "சம்சேராய், செகரியா, அத்தாலியா,", "en": "And Shamsherai, and Shehariah, and Athaliah,"}, {"verse": 27, "start": 170.09, "end": 176.14, "ta": "யரெஷியா, எலியா, சிக்ரி என்பவர்கள் எராகாமின் குமாரர்.", "en": "And Jaresiah, and Eliah, and Zichri, the sons of Jeroham."}, {"verse": 28, "start": 176.14, "end": 184.8, "ta": "இவர்கள் தங்கள் சந்ததிகளின் பிதாக்களிலே தலைவராயிருந்து, எருசலேமிலே குடியிருந்தார்கள்.", "en": "These were heads of the fathers, by their generations, chief men . These dwelt in Jerusalem."}, {"verse": 29, "start": 184.8, "end": 193.47, "ta": "கிபியோனிலே குடியிருந்தவன், கிபியோனின் மூப்பன்; அவன் பெண்ஜாதியின்பேர் மாக்காள்.", "en": "And at Gibeon dwelt the father of Gibeon; whose wife’s name was Maachah:"}, {"verse": 30, "start": 193.47, "end": 201.78, "ta": "அவன் மூத்த குமாரன் அப்தோன் என்பவன்; மற்றவர்கள் சூர், கீஸ், பாகால், நாதாப்,", "en": "And his firstborn son Abdon, and Zur, and Kish, and Baal, and Nadab,"}, {"verse": 31, "start": 201.78, "end": 206.11, "ta": "கேதோர், அகியோ, சேகேர் என்பவர்கள்.", "en": "And Gedor, and Ahio, and Zacher."}, {"verse": 32, "start": 206.11, "end": 218.57, "ta": "மிக்லோத் சிமியாவைப் பெற்றான்; இவர்களும் தங்கள் சகோதரரோடுங்கூட எருசலேமிலே தங்கள் சகோதரருக்குச் சமீபத்தில் குடியிருந்தார்கள்.", "en": "And Mikloth begat Shimeah. And these also dwelt with their brethren in Jerusalem, over against them."}, {"verse": 33, "start": 218.57, "end": 231.93, "ta": "நேர் கீசைப் பெற்றான்; கீஸ் சவுலைப் பெற்றான்; சவுல் யோனத்தானையும், மல்கிசூவாவையும், அபினதாபையும், எஸ்பாலையும் பெற்றான்.", "en": "And Ner begat Kish, and Kish begat Saul, and Saul begat Jonathan, and Malchi-shua, and Abinadab, and Esh-baal."}, {"verse": 34, "start": 231.93, "end": 238.43, "ta": "யோனத்தானின் குமாரன் மேரிபால்; மேரிபால் மீகாவைப் பெற்றான்.", "en": "And the son of Jonathan was Merib-baal; and Merib-baal begat Micah."}, {"verse": 35, "start": 238.43, "end": 245.74, "ta": "மீகாவின் குமாரர், பித்தோன், மேலேக், தரேயா, ஆகாஸ் என்பவர்கள்.", "en": "And the sons of Micah were , Pithon, and Melech, and Tarea, and Ahaz."}, {"verse": 36, "start": 245.74, "end": 258.2, "ta": "ஆகாஸ் யோகதாவைப் பெற்றான்; யோகதா அலமேத்தையும், அஸ்மாவேத்தையும், சிம்ரியையும் பெற்றான்; சிம்ரி மோசாவைப் பெற்றான்.", "en": "And Ahaz begat Jehoadah; and Jehoadah begat Alemeth, and Azmaveth, and Zimri; and Zimri begat Moza,"}, {"verse": 37, "start": 258.2, "end": 268.4, "ta": "மோசா பினியாவைப் பெற்றான், இவன் குமாரன் ரப்பா; இவன் குமாரன் எலியாசா; இவன் குமாரன் ஆத்சேல்.", "en": "And Moza begat Binea: Rapha was his son, Eleasah his son, Azel his son:"}, {"verse": 38, "start": 268.4, "end": 285.46, "ta": "ஆத்சேலுக்கு ஆறுகுமாரர் இருந்தார்கள்; அவர்கள் நாமங்களாவன, அஸ்ரீக்காம், பொக்குரு, இஸ்மவேல், செகரியா, ஒபதியா, ஆனான்; இவர்கள் எல்லாரும் ஆத்சேலின் குமாரர்.", "en": "And Azel had six sons, whose names are these, Azrikam, Bocheru, and Ishmael, and Sheariah, and Obadiah, and Hanan. All these were the sons of Azel."}, {"verse": 39, "start": 285.46, "end": 298.46, "ta": "அவன் சகோதரனாகிய எசேக்கின் குமாரர், ஊலாம் என்னும் மூத்தகுமாரனும், ஏகூஸ் என்னும் இரண்டாம் குமாரனும், எலிபேலேத் என்னும் மூன்றாம் குமாரனுமே", "en": "And the sons of Eshek his brother were , Ulam his firstborn, Jehush the second, and Eliphelet the third."}, {"verse": 40, "start": 298.46, "end": 317.33, "ta": "ஊலாமின் குமாரர் பராக்கிரமசாலிகளான வில்வீரராய் இருந்தார்கள்; அவர்களுக்கு அநேகம் புத்திரர் பெளத்திரர் இருந்தார்கள்; அவர்கள் தொகை நூற்றைம்பதுபேர்; இவர்கள் எல்லாரும் பென்யமீன் புத்திரர்.", "en": "And the sons of Ulam were mighty men of valour, archers, and had many sons, and sons’ sons, an hundred and fifty. All these are of the sons of Benjamin."}]}, "9": {"chapter": 9, "duration": 513.57, "audio_url": "audio_ot/OT13_09.mp3", "total_verses": 44, "verses": [{"verse": 1, "start": 3.8, "end": 25.05, "ta": "இஸ்ரவேலர் எல்லாரும் தங்கள் வம்ச வரலாற்றின்படி எண்ணப்பட்டார்கள்; இவர்கள் நாமங்கள் இஸ்ரவேல் ராஜாக்களின் புஸ்தகத்தில் எழுதியிருக்கிறது, யூதா கோத்திரத்தார் தங்கள் துரோகத்தினிமித்தம், பாபிலோனுக்குச் சிறைபிடித்துக்கொண்டுபோகப்பட்டார்கள்.", "en": "So all Israel were reckoned by genealogies; and, behold, they were written in the book of the kings of Israel and Judah, who were carried away to Babylon for their transgression."}, {"verse": 2, "start": 25.05, "end": 35.64, "ta": "தங்கள் காணியாட்சியிலும் தங்கள் பட்டணங்களிலும் முன் குடியிருந்தவர்கள் இஸ்ரவேலரும் ஆசாரியரும் லேவியரும் நிதினீமியருமே.", "en": "Now the first inhabitants that dwelt in their possessions in their cities were , the Israelites, the priests, Levites, and the Nethinims."}, {"verse": 3, "start": 35.64, "end": 47.74, "ta": "யூதா புத்திரரிலும், பென்யமீன் புத்திரரிலும், எப்பிராயீம் மனாசே என்பவர்களின் புத்திரரிலும், எருசலேமில் குடியிருந்தவர்கள் யாரென்றால்,", "en": "And in Jerusalem dwelt of the children of Judah, and of the children of Benjamin, and of the children of Ephraim, and Manasseh;"}, {"verse": 4, "start": 47.74, "end": 59.09, "ta": "யூதாவின் புத்திரனாகிய பேரேசின் சந்ததியில் பானியின் குமாரனாகிய இம்ரியின் மகனான உம்ரிΕ்குப் பிறந்த அம்மியூதிɠύ குமாரன் Ίத்தாய்.", "en": "Uthai the son of Ammihud, the son of Omri, the son of Imri, the son of Bani, of the children of Pharez the son of Judah."}, {"verse": 5, "start": 59.09, "end": 64.59, "ta": "சேலாவின͠சந்ததியில் மூத்தவனாகிய அசாயாவும், அவன் பிள்ளைகளும்,", "en": "And of the Shilonites; Asaiah the firstborn, and his sons."}, {"verse": 6, "start": 64.59, "end": 71.87, "ta": "சேராவின் சந்ததியில் யெகுவேலும், அவன் சகோதரராகிய அறுநூற்றுத்தொண்ணூறுபேருமே.", "en": "And of the sons of Zerah; Jeuel, and their brethren, six hundred and ninety."}, {"verse": 7, "start": 71.87, "end": 80.43, "ta": "பென்யமீன் புத்திரரில் அசெனூவாவின் குமாரனாகிய ஓதாவியாவுக்குப் பிறந்த மெசுல்லாமின் மகன் சல்லு.", "en": "And of the sons of Benjamin; Sallu the son of Meshullam, the son of Hodaviah, the son of Hasenuah,"}, {"verse": 8, "start": 80.43, "end": 95.07, "ta": "எரோகாமின் குமாரன் இப்னெயா; மிக்கிரியின் குமாரனாகிய ஊசியின் மகன் ஏலா; இப்னியாவின் குமாரனாகிய ரேகுவேலுக்குப் பிறந்த செபதியாவின் மகன் மெசுல்லாம் என்பவர்களும்;", "en": "And Ibneiah the son of Jeroham, and Elah the son of Uzzi, the son of Michri, and Meshullam the son of Shephathiah, the son of Reuel, the son of Ibnijah;"}, {"verse": 9, "start": 95.07, "end": 110.4, "ta": "தங்கள் சந்ததிகளின்படி இருந்த இவர்கள் சகோதரராகிய தொளாயிரத்து ஐம்பத்தாறுபேருமே; இந்த மனுஷர் எல்லாரும், தங்கள் பிதாக்களின் வம்சத்திலே பிதாக்களின் தலைவராயிருந்தார்கள்.", "en": "And their brethren, according to their generations, nine hundred and fifty and six. All these men were chief of the fathers in the house of their fathers."}, {"verse": 10, "start": 110.4, "end": 114.97, "ta": "ஆசாரியர்களில் யெதாயா, யோயாரிப், யாகின்.", "en": "And of the priests; Jedaiah, and Jehoiarib, and Jachin,"}, {"verse": 11, "start": 114.97, "end": 128.18, "ta": "அகிதூபின் குமாரனாகிய மெராயோதின் மகன் சாதோக்குக்குப் பிறந்த மெசுல்லாவின் குமாரனாகிய இல்க்கியாவின் மகன் அசரியா என்பவன் தேவாலயத்து விசாரணைக் கர்த்தன்.", "en": "And Azariah the son of Hilkiah, the son of Meshullam, the son of Zadok, the son of Meraioth, the son of Ahitub, the ruler of the house of God;"}, {"verse": 12, "start": 128.18, "end": 145.03, "ta": "மல்கியாவின் குமாரனாகிய பஸ்கூருக்குப் பிறந்த எரோகாமின் மகன் அதாயா; இம்மெரின் குமாரனாகிய மெசில்லேமித்தின் மகன் மெசுல்லாமுக்குப் பிறந்த யாசெராவின் குமாரனாகிய ஆதியேலின் மகன் மாசாய் என்பவர்களும்,", "en": "And Adaiah the son of Jeroham, the son of Pashur, the son of Malchijah, and Maasiai the son of Adiel, the son of Jahzerah, the son of Meshullam, the son of Meshillemith, the son of Immer;"}, {"verse": 13, "start": 145.03, "end": 158.24, "ta": "அவர்கள் சகோதரரும், தங்கள் பிதாக்களின் வம்சத்தலைவரான ஆயிரத்துஎழுநூற்று அறுபதுபேர் தேவாலயத்துக்கடுத்த பணிவிடைக்குத் திறமையுள்ளவர்களாயிருந்தார்கள்.", "en": "And their brethren, heads of the house of their fathers, a thousand and seven hundred and threescore; very able men for the work of the service of the house of God."}, {"verse": 14, "start": 158.24, "end": 166.62, "ta": "லேவியரில் மெராரியின் சந்ததியான அசபியாவின் குமாரனாகிய அஸ்ரீகாமுக்குப் பிறந்த அசூபின் மகன் செமாயா,", "en": "And of the Levites; Shemaiah the son of Hasshub, the son of Azrikam, the son of Hashabiah, of the sons of Merari;"}, {"verse": 15, "start": 166.62, "end": 175.17, "ta": "பக்பக்கார், ஏரேஸ், காலால், ஆசாபின் குமாரனாகிய சிக்ரிக்குப் பிறந்த மிகாவின் மகன் மத்தனியா,", "en": "And Bakbakkar, Heresh, and Galal, and Mattaniah the son of Micah, the son of Zichri, the son of Asaph;"}, {"verse": 16, "start": 175.17, "end": 189.14, "ta": "எதுத்தூனின் குமாரனாகிய காலாலுக்குப் பிறந்த செமாயாவின் மகன் ஒபதியா; நெத்தோபாத்தியரின் கிராமங்களில் குடியிருந்த எல்க்கானாவின் குமாரனாகிய ஆசாவின் மகன் பெரகியா,", "en": "And Obadiah the son of Shemaiah, the son of Galal, the son of Jeduthun, and Berechiah the son of Asa, the son of Elkanah, that dwelt in the villages of the Netophathites."}, {"verse": 17, "start": 189.14, "end": 200.99, "ta": "வாசல் காவலாளிகளாகிய சல்லுூம், அக்கூப், தல்மோன், அகிமான் என்பவர்களும், இவர்கள் சகோதரருமே; இவர்கள் தலைவன் சல்லுூம்.", "en": "And the porters were , Shallum, and Akkub, and Talmon, and Ahiman, and their brethren: Shallum was the chief;"}, {"verse": 18, "start": 200.99, "end": 208.53, "ta": "லேவிபுத்திரரின் சேனைகளில் இவர்கள் கிழக்கேயிருக்கிற ராஜாவின் வாசலைக் காவல்காத்துவந்தார்கள்", "en": "Who hitherto waited in the king’s gate eastward: they were porters in the companies of the children of Levi."}, {"verse": 19, "start": 208.53, "end": 233.85, "ta": "கோராகின் குமாரனாகிய எபியாசாபுக்குப் பிறந்த கோரேயின் மகன் சல்லுூமும், அவன் பிதாவின் வம்சத்தாராகிய அவனுடைய சகோதரருமான கோராகியர் பணிவிடைவேலையை விசாரித்து, அவர்கள் பிதாக்கள் கர்த்தருடைய பாளயத்திலே வாசஸ்தலத்திற்குப்போகிற வழியைக் காவல்காத்ததுபோல, வாசஸ்தலத்து வாசல்களைக் காத்துவந்தார்கள்.", "en": "And Shallum the son of Kore, the son of Ebiasaph, the son of Korah, and his brethren, of the house of his father, the Korahites, were over the work of the service, keepers of the gates of the tabernacle: and their fathers, being over the host of the LORD , were keepers of the entry."}, {"verse": 20, "start": 233.85, "end": 244.77, "ta": "எலெயாசாரின் குமாரனாகிய பினெகாசுடனே கர்த்தர் இருந்தபடியினால், அவன் முற்காலத்திலே அவர்கள்மேல் விசாரணைக்காரனாயிருந்தான்.", "en": "And Phinehas the son of Eleazar was the ruler over them in time past, and the LORD was with him."}, {"verse": 21, "start": 244.77, "end": 251.97, "ta": "மெசெல்மியாவின் குமாரனாகிய சகரியா ஆசரிப்புக் கூடாரவாசல் காவல்காரனாயிருந்தான்.", "en": "And Zechariah the son of Meshelemiah was porter of the door of the tabernacle of the congregation."}, {"verse": 22, "start": 251.97, "end": 275.42, "ta": "வாசல்களைக் காக்கிறதற்குத் தெரிந்துகொள்ளப்பட்ட இவர்களெல்லாரும் இருநூற்றுப் பன்னிரண்டுபேராயிருந்து, தங்கள் கிராமங்களின்படியே தங்கள் வம்சத்து அட்டவணைகளில் எழுதப்பட்டார்கள்; தாவீதும், ஞானதிருஷ்டிக்காரனாகிய சாமுவேலும், அவர்களைத் தங்கள் வேலைகளில் வைத்தார்கள்.", "en": "All these which were chosen to be porters in the gates were two hundred and twelve. These were reckoned by their genealogy in their villages, whom David and Samuel the seer did ordain in their set office."}, {"verse": 23, "start": 275.42, "end": 287.53, "ta": "அப்படியே அவர்களும், அவர்கள் குமாரரும் கர்த்தருடைய ஆலயமாகிய வாசஸ்தலத்து வாசல்களைக் காக்கிறவர்களை முறைமுறையாய் விசாரித்து வந்தார்கள்.", "en": "So they and their children had the oversight of the gates of the house of the LORD , namely , the house of the tabernacle, by wards."}, {"verse": 24, "start": 287.53, "end": 296.59, "ta": "வாசல்களைக் காக்கிறவர்கள் நாலுதிசைகளாகிய கிழக்கிலும் மேற்கிலும் வடக்கிலும் தெற்கிலும் இருந்தார்கள்.", "en": "In four quarters were the porters, toward the east, west, north, and south."}, {"verse": 25, "start": 296.59, "end": 305.9, "ta": "அவர்கள் சகோதரர் தங்கள் கிராமங்களிலிருந்து, ஏழுநாளுக்கு ஒருவிசை மாறிமாறி அவர்களோடிருக்க வருவார்கள்.", "en": "And their brethren, which were in their villages, were to come after seven days from time to time with them."}, {"verse": 26, "start": 305.9, "end": 318.35, "ta": "தேவாலயத்தின் பண்டகசாலைகள் மேலும் பொக்கிஷசாலைகள்மேலுமுள்ள விசாரணை உத்தியோகம் லேவியரான அந்த நாலு பிரதான காவலாளர்வசத்தில் ஒப்புவிக்கப்பட்டது.", "en": "For these Levites, the four chief porters, were in their set office, and were over the chambers and treasuries of the house of God."}, {"verse": 27, "start": 318.35, "end": 330.28, "ta": "காவல் அவர்களுக்கு ஒப்புவித்திருந்தபடியால் அவர்கள் தேவாலயத்தைச் சுற்றிலும் இராத்தங்கியிருந்து, காலமே கதவுகளைத் திறந்துவிடுவார்கள்.", "en": "And they lodged round about the house of God, because the charge was upon them, and the opening thereof every morning pertained to them."}, {"verse": 28, "start": 330.28, "end": 342.99, "ta": "அவர்களில் சிலரிடத்தில் ஆராதனை பணிமுட்டுகள் ஒப்புவித்திருந்தது; அவர்கள் அவைகளை எண்ணி உள்ளே கொண்டுபோய், எண்ணி வெளியே கொண்டுவருவார்கள்.", "en": "And certain of them had the charge of the ministering vessels, that they should bring them in and out by tale."}, {"verse": 29, "start": 342.99, "end": 360.26, "ta": "அவர்களில் சிலர் மற்றப் பணிமுட்டுகளின் பரிசுத்த பாத்திரங்கள் எல்லாவற்றின்மேலும், மெல்லிய மா, திராட்சரசம், எண்ணெய், சாம்பிராணி, சுகந்தவர்க்கங்களின்மேலும் விசாரணைக்காரராயிருந்தார்கள்.", "en": "Some of them also were appointed to oversee the vessels, and all the instruments of the sanctuary, and the fine flour, and the wine, and the oil, and the frankincense, and the spices."}, {"verse": 30, "start": 360.26, "end": 367.03, "ta": "ஆசாரியரின் குமாரரில் சிலர் சுகந்தவர்க்கத்தால் பரிமளதைலம் இறக்குவார்கள்.", "en": "And some of the sons of the priests made the ointment of the spices."}, {"verse": 31, "start": 367.03, "end": 378.29, "ta": "லேவியரில் கோராகியனான சல்லுூமின் மூத்த குமாரனாகிய மத்தித்தியாவுக்குப் பலகாரம் சுடுகிற வேலையின் விசாரிப்பு ஒப்புவித்திருந்தது.", "en": "And Mattithiah, one of the Levites, who was the firstborn of Shallum the Korahite, had the set office over the things that were made in the pans."}, {"verse": 32, "start": 378.29, "end": 389.13, "ta": "அவர்கள் சகோதரராகிய கோகாத்தியரின் புத்திரரில் சிலருக்கு ஓய்வுநாள் தோறும் அப்பங்களை ஆயத்தப்படுத்தும் விசாரிப்பு இருந்தது.", "en": "And other of their brethren, of the sons of the Kohathites, were over the shewbread, to prepare it every sabbath."}, {"verse": 33, "start": 389.13, "end": 404.2, "ta": "இவர்களில் லேவியருடைய பிதாக்களிள் தலைவராகிய சங்கீதக்காரர் இரவும்பகலும் தங்கள் வேலையை நடத்தவேண்டியிருந்தபடியால், மற்ற வேலைக்கு நீங்கலாய்த் தங்கள் அறைகளில் இருந்தார்கள்.", "en": "And these are the singers, chief of the fathers of the Levites, who remaining in the chambers were free: for they were employed in that work day and night."}, {"verse": 34, "start": 404.2, "end": 415.29, "ta": "லேவியரில் பிதாக்களின் தலைவராகிய இவர்கள் தங்கள் சந்ததிகளுக்குத் தலைமையானவர்கள்; இவர்கள் எருசலேமிலே குடியிருந்தார்கள்.", "en": "These chief fathers of the Levites were chief throughout their generations; these dwelt at Jerusalem."}, {"verse": 35, "start": 415.29, "end": 425.37, "ta": "கிபியோனிலே குடியிருந்தவர்கள் யாரென்றால், கிபியோனின் மூப்பனாகிய யெகியேல், இவன் பெண்ஜாதியின்பேர் மாக்காள்.", "en": "And in Gibeon dwelt the father of Gibeon, Jehiel, whose wife’s name was Maachah:"}, {"verse": 36, "start": 425.37, "end": 432.48, "ta": "அவன் மூத்த குமாரனாகிய அப்தோனும், சூர், கீஸ், பாகால், நேர், நாதாப்,", "en": "And his firstborn son Abdon, then Zur, and Kish, and Baal, and Ner, and Nadab,"}, {"verse": 37, "start": 432.48, "end": 437.81, "ta": "கேதோர், அகியோ, சகரியா, மிக்லோத் என்பவர்களுமே.", "en": "And Gedor, and Ahio, and Zechariah, and Mikloth."}, {"verse": 38, "start": 437.81, "end": 450.09, "ta": "மிக்லோத் சீமியாமைப் பெற்றான்; இவர்களும் தங்கள் சகோதரரோடுங்கூட எருசலேமிலிருக்கிற தங்கள் சகோதரருக்குச் சமீபத்தில் குடியிருந்தார்கள்.", "en": "And Mikloth begat Shimeam. And they also dwelt with their brethren at Jerusalem, over against their brethren."}, {"verse": 39, "start": 450.09, "end": 462.62, "ta": "நேர் கீசைப் பெற்றான்; கீஸ் சவுலைப் பெற்றான்; சவுல் யோனத்தானையும், மல்கிசூவாவையும், அபினதாபையும், எஸ்பாலையும் பெற்றான்.", "en": "And Ner begat Kish; and Kish begat Saul; and Saul begat Jonathan, and Malchi-shua, and Abinadab, and Esh-baal."}, {"verse": 40, "start": 462.62, "end": 468.72, "ta": "யோனத்தானின் குமாரன் மெரிபால்; மெரிபால் மீகாவைப் பெற்றான்.", "en": "And the son of Jonathan was Merib-baal: and Merib-baal begat Micah."}, {"verse": 41, "start": 468.72, "end": 475.58, "ta": "மீகாவின் குமாரர், பித்தோன், மேலேக், தரேயா, ஆகாஸ் என்பவர்கள்.", "en": "And the sons of Micah were , Pithon, and Melech, and Tahrea, and Ahaz ."}, {"verse": 42, "start": 475.58, "end": 487.35, "ta": "ஆகாஸ் யாராகைப் பெற்றான்; யாராக் அலெமேத்தையும், அஸ்மாவேத்தையும், சிம்ரியையும் பெற்றான்; சிம்ரி மோசாவைப் பெற்றான்.", "en": "And Ahaz begat Jarah; and Jarah begat Alemeth, and Azmaveth, and Zimri; and Zimri begat Moza;"}, {"verse": 43, "start": 487.35, "end": 497.34, "ta": "மோசா பினியாவைப் பெற்றான்; இவன் குமாரன் ரப்பாயா; இவன் குமாரன் எலியாசா; இவன் குமாரன் ஆத்சேல்.", "en": "And Moza begat Binea; and Rephaiah his son, Eleasah his son, Azel his son."}, {"verse": 44, "start": 497.34, "end": 512.07, "ta": "ஆத்சேலுக்கு ஆறு குமாரர் இருந்தார்கள்; அவர்கள் நாமங்களாவன, அரீக்காம், பொக்குரு, இஸ்மவேல், சேராயா, ஒபதியா, ஆனான், இவர்கள் ஆத்சேலின் குமாரர்.", "en": "And Azel had six sons, whose names are these, Azrikam, Bocheru, and Ishmael, and Sheariah, and Obadiah, and Hanan: these were the sons of Azel."}]}, "10": {"chapter": 10, "duration": 182.3, "audio_url": "audio_ot/OT13_10.mp3", "total_verses": 14, "verses": [{"verse": 1, "start": 3.8, "end": 14.88, "ta": "பெலிஸ்தர் இஸ்ரவேலரோடே யுத்தபண்ணினார்கள்; இஸ்ரவேல் பெலிஸ்தருக்கு முன்பாக முறிந்தோடி, கில்போவா மலையிலே வெட்டுண்டு விழுந்தார்கள்.", "en": "Now the Philistines fought against Israel; and the men of Israel fled from before the Philistines, and fell down slain in mount Gilboa."}, {"verse": 2, "start": 14.88, "end": 26.66, "ta": "பெலிஸ்தர் சவுலையும் அவன் குமாரரையும் நெருங்கித் தொடர்ந்து, சவுலின் குமாரராகிய யோனத்தானையும் அபினதாபையும் மல்கிசூவாவையும் வெட்டிப்போட்டார்கள்.", "en": "And the Philistines followed hard after Saul, and after his sons; and the Philistines slew Jonathan, and Abinadab, and Malchi-shua, the sons of Saul."}, {"verse": 3, "start": 26.66, "end": 37.35, "ta": "சவுலுக்கு விரோதமாய் யுத்தம் பலத்தது; வில்வீரர் அவனைக்கண்டு நெருங்கினார்கள்; அப்பொழுது சவுல் வில்வீரருக்கு மிகவும் பயப்பட்டு,", "en": "And the battle went sore against Saul, and the archers hit him, and he was wounded of the archers."}, {"verse": 4, "start": 37.35, "end": 60.36, "ta": "தன் ஆயுததாரியை நோக்கி: அந்த விருத்தசேதனம் இல்லாதவர்கள் வந்து என்னை அவமானப்படுத்தாதபடிக்கு, நீ உன் பட்டயத்தை உருவி, என்னைக் குத்திப்போடு என்றான்; அவனுடைய ஆயுததாரி மிகவும் பயப்பட்டதினால் அப்படிச்செய்யமாட்டேன் என்றான். அப்பொழுது சவுல் பட்டயத்தை நட்டு அதின்மேல் விழுந்தான்.", "en": "Then said Saul to his armourbearer, Draw thy sword, and thrust me through therewith; lest these uncircumcised come and abuse me. But his armourbearer would not; for he was sore afraid. So Saul took a sword, and fell upon it."}, {"verse": 5, "start": 60.36, "end": 68.29, "ta": "சவுல் செத்துப்போனதை அவன் ஆயுததாரி கண்டபோது, அவனும் பட்டயத்தின்மேல் விழுந்து செத்துப்போனான்.", "en": "And when his armourbearer saw that Saul was dead, he fell likewise on the sword, and died."}, {"verse": 6, "start": 68.29, "end": 76.45, "ta": "அப்படியே சவுலும், அவன் மூன்றுகுமாரரும், அவன் வீட்டு மனுஷர் அனைவரும்கூடச் செத்துப்போனார்கள்.", "en": "So Saul died, and his three sons, and all his house died together."}, {"verse": 7, "start": 76.45, "end": 93.69, "ta": "ஜனங்கள் முறிந்தோடினதையும், சவுலும் அவன் குமாரரும் செத்துப்போனதையும், பள்ளத்தாக்கிலுள்ள இஸ்ரவேலர் எல்லரும் கண்டபோது தங்கள் பட்டணங்களை விட்டு ஓடிப்போனார்கள்; அப்பொழுது பெலிஸ்தர் வந்து, அவைகளில் குடியிருந்தார்கள்", "en": "And when all the men of Israel that were in the valley saw that they fled, and that Saul and his sons were dead, then they forsook their cities, and fled: and the Philistines came and dwelt in them."}, {"verse": 8, "start": 93.69, "end": 105.69, "ta": "வெட்டுண்டவர்களின் வஸ்திரங்களை உரிந்துகொள்ளப் பெலிஸ்தர் மறுநாளில் வந்தபோது, அவர்கள் சவுலையும் அவன் குமாரரையும் கில்போவா மலையிலே விழுந்துகிடக்கக் கண்டு,", "en": "And it came to pass on the morrow, when the Philistines came to strip the slain, that they found Saul and his sons fallen in mount Gilboa."}, {"verse": 9, "start": 105.69, "end": 121.47, "ta": "அவன் வஸ்திரங்களை உரிந்து, அவன் தலையையும் அவன் ஆயுதங்களையும் எடுத்துக்கொண்டு, தங்கள் விக்கிரகங்களுக்கும் ஜனங்களுக்கும் அதைப் பிரசித்தப்படுத்தும்படி பெலிஸ்தருடைய தேசத்திலே சுற்றிலும் செய்தி அனுப்பி,", "en": "And when they had stripped him, they took his head, and his armour, and sent into the land of the Philistines round about, to carry tidings unto their idols, and to the people."}, {"verse": 10, "start": 121.47, "end": 130.01, "ta": "அவன் ஆயுதங்களைத் தங்கள் தேவர்களின் கோவிலிலே வைத்து, அவன் தலையைத் தாகோன் கோவிலிலே தூக்கிவைத்தார்கள்.", "en": "And they put his armour in the house of their gods, and fastened his head in the temple of Dagon."}, {"verse": 11, "start": 130.01, "end": 137.7, "ta": "பெலிஸ்தர் சவுலுக்குச் செய்த எல்லாவற்றையுங் கீலேயாத் தேசத்து யாபேஸ் பட்டணத்தார் யாவரும் கேட்டபோது,", "en": "And when all Jabesh-gilead heard all that the Philistines had done to Saul,"}, {"verse": 12, "start": 137.7, "end": 156.25, "ta": "பராக்கிரமசாலிகள் எல்லாரும் எழுந்துபோய், சவுலின் உடலையும் அவன் குமாரரின் உடல்களையும் எடுத்து, யாபேசுக்குக் கொண்டுவந்து, அவர்கள் எலும்புகளை யாபேசிலிருக்கிற ஒரு கர்வாலிமரத்தின்கீழ் அடக்கம்பண்ணி, ஏழுநாள் உபவாசம்பண்ணினார்கள்.", "en": "They arose, all the valiant men, and took away the body of Saul, and the bodies of his sons, and brought them to Jabesh, and buried their bones under the oak in Jabesh, and fasted seven days."}, {"verse": 13, "start": 156.25, "end": 173.1, "ta": "அப்படியே சவுல் கர்த்தருடைய வார்த்தையைக் கைக்கொள்ளாமல், கர்த்தருக்குச் செய்த தன் துரோகத்தினிமித்தமும், அவன் கர்த்தரைத் தேடாமல் அஞ்சனம் பார்க்கிறவர்களைக் கேட்கும்படிக்குத் தேடினதினிமித்தமும் செத்துப்போனான்.", "en": "So Saul died for his transgression which he committed against the LORD , even against the word of the LORD , which he kept not, and also for asking counsel of one that had a familiar spirit, to enquire of it;"}, {"verse": 14, "start": 173.1, "end": 180.8, "ta": "அதற்காக அவர் அவனைக் கொன்று, ராஜ்யபாரத்தை ஈசாயின் குமாரனாகிய தாவீது வசமாகக் திருப்பினார்.", "en": "And enquired not of the LORD : therefore he slew him, and turned the kingdom unto David the son of Jesse."}]}, "11": {"chapter": 11, "duration": 530.13, "audio_url": "audio_ot/OT13_11.mp3", "total_verses": 47, "verses": [{"verse": 1, "start": 3.8, "end": 15.46, "ta": "இஸ்ரவேலர் எல்லாரும் எப்ரோனிலிருக்கிற தாவீதினிடத்தில் கூடிவந்து: இதோ, நாங்கள் உம்முடைய எலும்பும் உம்முடைய மாம்சமுமானவர்கள்.", "en": "Then all Israel gathered themselves to David unto Hebron, saying, Behold, we are thy bone and thy flesh."}, {"verse": 2, "start": 15.46, "end": 38.86, "ta": "சவுல் இன்னும் ராஜாவாயிருக்கும்போதே, நீர் இஸ்ரவேலை நடத்திக்கொண்டுபோய் நடத்திக்கொண்டுவருவீர்; என் ஜனமாகிய இஸ்ரவேலை நீர் மேய்த்து, என் ஜனமாகிய இஸ்ரவேலின்மேல் தலைவனாயிருப்பீர் என்று உம்முடைய தேவனாகிய கர்த்தர் உமக்குச் சொல்லியும் இருக்கிறார் என்றார்கள்.", "en": "And moreover in time past, even when Saul was king, thou wast he that leddest out and broughtest in Israel: and the LORD thy God said unto thee, Thou shalt feed my people Israel, and thou shalt be ruler over my people Israel."}, {"verse": 3, "start": 38.86, "end": 63.31, "ta": "அப்படியே இஸ்ரவேலின் மூப்பரெல்லாரும் எப்ரோனிலே ராஜாவினிடத்தில் வந்தார்கள்; தாவீது எப்ரோனிலே கர்த்தருக்கு முன்பாக அவர்களோடு உடன்படிக்கை பண்ணிக்கொண்டபின்பு, கர்த்தர் சாமுவேலைக்கொண்டு சொன்ன வார்த்தையின்படியே அவர்கள் தாவீதை இஸ்ரவேலின்மேல் ராஜாவாக அபிஷேகம்பண்ணினார்கள்.", "en": "Therefore came all the elders of Israel to the king to Hebron; and David made a covenant with them in Hebron before the LORD ; and they anointed David king over Israel, according to the word of the LORD by Samuel."}, {"verse": 4, "start": 63.31, "end": 74.45, "ta": "பின்பு தாவீது இஸ்ரவேல் அனைத்தோடுங்கூட எபூசாகிய எருசலேமுக்குப் போனான்; எபூசியர் அத்தேசத்தின் குடிகளாயிருந்தார்கள்.", "en": "And David and all Israel went to Jerusalem, which is Jebus; where the Jebusites were , the inhabitants of the land."}, {"verse": 5, "start": 74.45, "end": 89.5, "ta": "அப்பொழுது எபூசின் குடிகள் தாவீதை நோக்கி: நீ இதற்குள் பிரவேசிப்பதில்லை என்றார்கள்; ஆனாலும் தாவீது சீயோன் கோட்டையைப் பிடித்தான்; அது தாவீதின் நகரமாயிற்று.", "en": "And the inhabitants of Jebus said to David, Thou shalt not come hither. Nevertheless David took the castle of Zion, which is the city of David."}, {"verse": 6, "start": 89.5, "end": 106.29, "ta": "எபூசியரை முறிய அடிக்கிறதில் எவன் முந்தினவனாயிருக்கிறானோ, அவன் தலைவனும் சேனாபதியுமாயிருப்பானென்று தாவீது சொல்லியிருந்தான்; செருயாவின் குமாரனாகிய யோவாப் முந்தி ஏறித் தலைவனானான்.", "en": "And David said, Whosoever smiteth the Jebusites first shall be chief and captain. So Joab the son of Zeruiah went first up, and was chief."}, {"verse": 7, "start": 106.29, "end": 114.21, "ta": "தாவீது அந்தக் கோட்டையில் வாசம்பண்ணினபடியினால், அது தாவீதின் நகரம் என்னப்பட்டது.", "en": "And David dwelt in the castle; therefore they called it the city of David."}, {"verse": 8, "start": 114.21, "end": 125.0, "ta": "பிற்பாடு அவன் நகரத்தை மில்லோ தொடங்கிச் சுற்றிலும் கட்டினான்; யோவாப் நகரத்தின் மற்ற இடங்களைப் பழுதுபார்த்தான்.", "en": "And he built the city round about, even from Millo round about: and Joab repaired the rest of the city."}, {"verse": 9, "start": 125.0, "end": 133.18, "ta": "தாவீது நாளுக்குநாள் விருத்தியடைந்தான்; சேனைகளுடைய கர்த்தர் அவனோடேகூட இருந்தார்.", "en": "So David waxed greater and greater: for the LORD of hosts was with him."}, {"verse": 10, "start": 133.18, "end": 151.71, "ta": "கர்த்தர் இஸ்ரவேலுக்காகச் சொன்ன வார்த்தையின்படியே, தாவீதை ராஜாவாக்கும்படி அவன் வசமாயிருந்து ராஜ்யபாரம்பண்ணுகிற அவனிடத்திலும், சகல இஸ்ரவேலரிடத்திலும், வீரதத்துவத்தைப் பாராட்டின பிரதான பராக்கிரமசாலிகளும்,", "en": "These also are the chief of the mighty men whom David had, who strengthened themselves with him in his kingdom, and with all Israel, to make him king, according to the word of the LORD concerning Israel."}, {"verse": 11, "start": 151.71, "end": 170.59, "ta": "தாவீதுக்கு இருந்த அந்தப் பராக்கிரமசாலிகளின் இலக்கமுமாவது: அக்மோனியின் குமாரனாகிய யாஷோபியாம் என்னும் சேர்வைக்காரரின் தலைவன்; இவன் முந்நூறுபேர்களின்மேல் தன் ஈட்டியை ஓங்கி அவர்களை ஒருமிக்கக்கொன்றுபோட்டான்.", "en": "And this is the number of the mighty men whom David had; Jashobeam, an Hachmonite, the chief of the captains: he lifted up his spear against three hundred slain by him at one time."}, {"verse": 12, "start": 170.59, "end": 180.69, "ta": "இவனுக்கு இரண்டாவது அகோயின் குமாரனாகிய தோதோவின் மகன் எலெயாசார்; இவன் மூன்று பராக்கிரமசாலிகளில் ஒருவன்.", "en": "And after him was Eleazar the son of Dodo, the Ahohite, who was one of the three mighties."}, {"verse": 13, "start": 180.69, "end": 195.13, "ta": "பெலிஸ்தர் பாஸ்தம்மீமிலிருக்கிற வாற்கோதுமை நிறைந்த வயல்நிலத்தில் யுத்தத்திற்குக் கூடிவந்தபோது ஜனம் பெலிஸ்தரைக் கண்டு ஓடினபோதும் இவன் தாவீதோடே அங்கே இருந்தான்.", "en": "He was with David at Pas-dammim, and there the Philistines were gathered together to battle, where was a parcel of ground full of barley; and the people fled from before the Philistines."}, {"verse": 14, "start": 195.13, "end": 208.96, "ta": "அப்பொழுது அவர்கள் அந்த நிலத்தின் நடுவிலே நின்று அதைக் காப்பாற்றிப் பெலிஸ்தரை மடங்கடித்தார்கள். அதினாலே கர்த்தர் பெரிய ரட்சிப்பை நடப்பித்தார்.", "en": "And they set themselves in the midst of that parcel, and delivered it, and slew the Philistines; and the LORD saved them by a great deliverance."}, {"verse": 15, "start": 208.96, "end": 223.58, "ta": "முப்பது தலைவரில் மூன்றுபேர் அதுல்லாம் என்னும் கன்மலைக் கெபியிலிருக்கிற தாவீதினிடத்தில் போயிருந்தார்கள்; பெலிஸ்தரின் பாளயம் ரெப்பா பள்ளத்தாக்கில் இறங்குகிறபோது,", "en": "Now three of the thirty captains went down to the rock to David, into the cave of Adullam; and the host of the Philistines encamped in the valley of Rephaim."}, {"verse": 16, "start": 223.58, "end": 232.37, "ta": "தாவீது அரணான ஒரு இடத்திலிருந்தான்; அப்பொழுது பெலிஸ்தரின் தாணையம் பெத்லகேமில் இருந்தது.", "en": "And David was then in the hold, and the Philistines’ garrison was then at Beth-lehem."}, {"verse": 17, "start": 232.37, "end": 245.33, "ta": "தாவீது பெத்லகேமின் ஒலிமுகவாசலிலிருக்கிற கிணற்றின் தண்ணீர்மேல் ஆவல்கொண்டு, என் தாகத்திற்குக் கொஞ்சம் தண்ணீர் கொண்டுவருகிறவன் யார் என்றான்.", "en": "And David longed, and said, Oh that one would give me drink of the water of the well of Beth-lehem, that is at the gate!"}, {"verse": 18, "start": 245.33, "end": 267.35, "ta": "அப்பொழுது அந்த மூன்றுபேர் பெலிஸ்தரின் பாளயத்திற்குள் துணிந்து புகுந்துபோய், பெத்லகேமின் ஒலிமுகவாசலிலிருக்கிற கிணற்றிலே தண்ணீர் மொண்டு தாவீதினிடத்தில் கொண்டுவந்தார்கள்; ஆனாலும் அவன் அதைக் குடிக்க மனதில்லாமல் அதைக் கர்த்தருக்கென்று ஊற்றிப்போட்டு:", "en": "And the three brake through the host of the Philistines, and drew water out of the well of Beth-lehem, that was by the gate, and took it , and brought it to David: but David would not drink of it, but poured it out to the LORD ,"}, {"verse": 19, "start": 267.35, "end": 290.84, "ta": "நான் இதைச் செய்யாதபடிக்கு, என் தேவன் என்னைக் காத்துக்கொள்ளக்கடவர்; தங்கள் பிராணனை எண்ணாமல் போய் அதைக் கொண்டுவந்த இந்த மனுஷரின் ரத்தத்தைக் குடிப்பேனோ என்று சொல்லி அதைக் குடிக்கமாட்டேன் என்றான். இப்படி இந்த மூன்று பராக்கிரமசாலிகளும் செய்தார்கள்.", "en": "And said, My God forbid it me, that I should do this thing: shall I drink the blood of these men that have put their lives in jeopardy? for with the jeopardy of their lives they brought it. Therefore he would not drink it. These things did these three mightiest."}, {"verse": 20, "start": 290.84, "end": 305.37, "ta": "யோவாபின் சகோதரனாகிய அபிசாய் அந்த மூன்றுபேரில் பிரதானமானவன்; அவன் தன் ஈட்டியை ஓங்கி, முந்நூறுபேரை மடங்கடித்ததினால் இந்த மூன்றுபேரில் பேர்பெற்றவனானான்.", "en": "And Abishai the brother of Joab, he was chief of the three: for lifting up his spear against three hundred, he slew them , and had a name among the three."}, {"verse": 21, "start": 305.37, "end": 319.29, "ta": "இந்த மூன்றுபேரில் அவன் மற்ற இரண்டுபேரிலும் மேன்மையுள்ளவனானதினால், அவர்களில் தலைவனானான்; ஆனாலும் அந்த முந்தின மூன்றுபேருக்கு அவன் சமானமானவனல்ல.", "en": "Of the three, he was more honourable than the two; for he was their captain: howbeit he attained not to the first three."}, {"verse": 22, "start": 319.29, "end": 343.3, "ta": "பராக்கிரமசாலியாகிய யோய்தாவின் குமாரனும், கப்சேயேல் ஊரானுமாகிய பெனாயாவும் செய்கைகளில் வல்லவனாயிருந்தான்; அவன் மோவாப் தேசத்தின் இரண்டு வலுமையான சிங்கங்களைக் கொன்றதுமல்லாமல் உறைந்த மழைபெய்த நாளில் அவன் ஒரு கெபிக்குள்ளே இறங்கிப்போய், ஒரு சிங்கத்தைக் கொன்றான்.", "en": "Benaiah the son of Jehoiada, the son of a valiant man of Kabzeel, who had done many acts; he slew two lionlike men of Moab: also he went down and slew a lion in a pit in a snowy day."}, {"verse": 23, "start": 343.3, "end": 369.06, "ta": "ஐந்துமுழ உயரமான ஒரு எகிப்தியனையும் அவன் கொன்றுபோட்டான்; அந்த எகிப்தியன் கையில் நெய்கிறவர்களின் படைமரக் கனதியான ஒரு ஈட்டி, இருக்கையில், இவன் ஒரு தடியைப் பிடித்து, அவனிடத்தில் போய், அந்த எகிப்தியன் கையிலிருந்த ஈட்டியைப் பறித்து, அவன் ஈட்டியினாலே அவனைக் கொன்றுபோட்டான்.", "en": "And he slew an Egyptian, a man of great stature, five cubits high; and in the Egyptian’s hand was a spear like a weaver’s beam; and he went down to him with a staff, and plucked the spear out of the Egyptian’s hand, and slew him with his own spear."}, {"verse": 24, "start": 369.06, "end": 379.41, "ta": "இவைகளை யோய்தாவின் குமாரனான பெனாயா செய்தபடியினால், மூன்று பராக்கிரமசாலிகளுக்குள்ளே பேர்பெற்றவனாய் இருந்தான்.", "en": "These things did Benaiah the son of Jehoiada, and had the name among the three mighties."}, {"verse": 25, "start": 379.41, "end": 394.12, "ta": "முப்பதுபேரிலும் இவன் மேன்மையுள்ளவன்; ஆனாலும் அந்த முந்தின மூன்றுபேருக்கும் இவன் சமானமானவனல்ல; அவனைத் தாவீது தன் மெய்க்காவலருக்குத் தலைவனாக வைத்தான்.", "en": "Behold, he was honourable among the thirty, but attained not to the first three: and David set him over his guard."}, {"verse": 26, "start": 394.12, "end": 404.56, "ta": "இராணுவத்திலிருந்த மற்றப் பராக்கிரமசாலிகள்: யோவாபின் தம்பி ஆசகேல், பெத்லகேம் ஊரானாகிய தோதோவின் குமாரன் எல்க்கானான்,", "en": "Also the valiant men of the armies were , Asahel the brother of Joab, Elhanan the son of Dodo of Beth-lehem,"}, {"verse": 27, "start": 404.56, "end": 408.56, "ta": "ஆரோதியனாகிய சம்மோத், பெலோனியனாகிய ஏலெஸ்,", "en": "Shammoth the Harorite, Helez the Pelonite,"}, {"verse": 28, "start": 408.56, "end": 414.48, "ta": "தெக்கோவியனாகிய இக்கேசின் குமாரன் ஈரா, ஆனதோத்தியனாகிய அபியேசர்,", "en": "Ira the son of Ikkesh the Tekoite, Abi-ezer the Antothite,"}, {"verse": 29, "start": 414.48, "end": 418.83, "ta": "ஊசாத்தியனாகிய சிபெக்காய், அகோகியனாகிய ஈலாய்,", "en": "Sibbecai the Hushathite, Ilai the Ahohite,"}, {"verse": 30, "start": 418.83, "end": 425.35, "ta": "நெத்தோபாத்தியனாகிய மகராயி, நெத்தோபாத்தியனாகிய பானாவின் குமாரன் ஏலேத்,", "en": "Maharai the Netophathite, Heled the son of Baanah the Netophathite,"}, {"verse": 31, "start": 425.35, "end": 433.44, "ta": "பென்யமீன் புத்திரரின் கிபேயா ஊரானாகிய ரிபாயின் குமாரன் இத்தாயி, பிரத்தோனியனாகிய பெனாயா,", "en": "Ithai the son of Ribai of Gibeah, that pertained to the children of Benjamin, Benaiah the Pirathonite,"}, {"verse": 32, "start": 433.44, "end": 439.19, "ta": "காகாஸ் நீரோடைத் தேசத்தானாகிய ஊராயி, அர்பாத்தியனாகிய அபியேல்,", "en": "Hurai of the brooks of Gaash, Abiel the Arbathite,"}, {"verse": 33, "start": 439.19, "end": 443.8, "ta": "பகரூமியனாகிய அஸ்மாவேத், சால்போனியனாகிய எலியாபா,", "en": "Azmaveth the Baharumite, Eliahba the Shaalbonite,"}, {"verse": 34, "start": 443.8, "end": 450.5, "ta": "கீசோனியனாகிய ஆசேமின் குமாரர் ஆராரியனாகிய சாகியின் குமாரன் யோனத்தான்.", "en": "The sons of Hashem the Gizonite, Jonathan the son of Shage the Hararite,"}, {"verse": 35, "start": 450.5, "end": 456.41, "ta": "ஆராரியனாகிய சாக்காரின் குமாரன் அகியாம், ஊரின் குமாரன் எலிபால்,", "en": "Ahiam the son of Sacar the Hararite, Eliphal the son of Ur,"}, {"verse": 36, "start": 456.41, "end": 460.76, "ta": "மெகராத்தியனாகிய ஏப்பேர், பெலோனியனாகிய அகியா,", "en": "Hepher the Mecherathite, Ahijah the Pelonite,"}, {"verse": 37, "start": 460.76, "end": 465.29, "ta": "கர்மேலியனாகிய எஸ்ரோ, எஸ்பாயின் குமாரன் நாராயி,", "en": "Hezro the Carmelite, Naarai the son of Ezbai,"}, {"verse": 38, "start": 465.29, "end": 470.42, "ta": "நாத்தானின் சகோதரன் யோவேல், அகரியின் குமாரன் மிப்கார்,", "en": "Joel the brother of Nathan, Mibhar the son of Haggeri,"}, {"verse": 39, "start": 470.42, "end": 478.51, "ta": "அம்மோனியனாகிய சேலேக், செருயாவின் குமாரனாகிய யோவாபின் ஆயுததாரியான பெரோத்தியனாகிய நாராயி,", "en": "Zelek the Ammonite, Naharai the Berothite, the armourbearer of Joab the son of Zeruiah,"}, {"verse": 40, "start": 478.51, "end": 482.34, "ta": "இத்தரியனாகிய ஈரா, இத்தரியனாகிய காரெப்,", "en": "Ira the Ithrite, Gareb the Ithrite,"}, {"verse": 41, "start": 482.34, "end": 486.69, "ta": "ஏத்தியனாகிய உரியா, அக்லாயின் குமாரன் சாபாத்,", "en": "Uriah the Hittite, Zabad the son of Ahlai,"}, {"verse": 42, "start": 486.69, "end": 496.18, "ta": "ரூபனியரின் தலைவனாகிய சீசாவின் குமாரன் அதினா என்னும் ரூபனியன்; அவனோடே முப்பதுபேர் இருந்தார்கள்.", "en": "Adina the son of Shiza the Reubenite, a captain of the Reubenites, and thirty with him,"}, {"verse": 43, "start": 496.18, "end": 500.61, "ta": "மாகாவின் குமாரன் ஆனான், மிதினியனாகிய யோசபாத்,", "en": "Hanan the son of Maachah, and Joshaphat the Mithnite,"}, {"verse": 44, "start": 500.61, "end": 508.01, "ta": "அஸ்தரேத்தியனாகிய உசியா, ஆரோவேரியனாகிய ஓத்தாமின் குமாரர் சமாவும், யேகியேலும்,", "en": "Uzzia the Ashterathite, Shama and Jehiel the sons of Hothan the Aroerite,"}, {"verse": 45, "start": 508.01, "end": 513.84, "ta": "சிம்ரியின் குமாரன் எதியாயேல், தித்சியனாகிய அவன் சகோதரன் யோகா,", "en": "Jediael the son of Shimri, and Joha his brother, the Tizite,"}, {"verse": 46, "start": 513.84, "end": 523.06, "ta": "மாகாவியரின் புத்திரன் எலியேல், எல்நாமின் குமாரர் எரிபாயும், யொசவியாவும், மோவாபியனான இத்மாவும்,", "en": "Eliel the Mahavite, and Jeribai, and Joshaviah, the sons of Elnaam, and Ithmah the Moabite,"}, {"verse": 47, "start": 523.06, "end": 528.63, "ta": "மெசோபாயா ஊராராகிய எலியேலும், ஓபேதும், யாசியேலுமே.", "en": "Eliel, and Obed, and Jasiel the Mesobaite."}]}, "12": {"chapter": 12, "duration": 496.25, "audio_url": "audio_ot/OT13_12.mp3", "total_verses": 40, "verses": [{"verse": 1, "start": 3.8, "end": 12.73, "ta": "தாவீது கீசின் குமாரனாகிய சவுலினிமித்தம் இன்னும் மறைவாயிருக்கையில், சிக்லாகிலிருக்கிற அவனிடத்திற்கு வந்து,", "en": "Now these are they that came to David to Ziklag, while he yet kept himself close because of Saul the son of Kish: and they were among the mighty men, helpers of the war."}, {"verse": 2, "start": 12.73, "end": 28.73, "ta": "யுத்தத்திற்கு ஒத்தாசை செய்த வில்வீரரும், கவண்கல் எறிகிறதற்கும் வில்லினால் அம்பு எய்கிறதற்கும் வலது இடது கைவாட்டமான பராக்கிரமசாலிகளான மற்ற மனுஷருமாவன: சவுலின் சகோதரராகிய பென்யமீன் கோத்திரத்தில்,", "en": "They were armed with bows, and could use both the right hand and the left in hurling stones and shooting arrows out of a bow, even of Saul’s brethren of Benjamin."}, {"verse": 3, "start": 28.73, "end": 42.89, "ta": "கிபேயா ஊரானாகிய சேமாவின் குமாரர் அகியேசர் என்னும் தலைவனும், யோவாசும், அஸ்மாவேத்தின் குமாரராகிய எசியேலும், பேலேத்தும், பெராக்கா, ஆனதோத்தியனான ஏகூ என்பவர்களும்,", "en": "The chief was Ahiezer, then Joash, the sons of Shemaah the Gibeathite; and Jeziel, and Pelet, the sons of Azmaveth; and Berachah, and Jehu the Antothite,"}, {"verse": 4, "start": 42.89, "end": 55.2, "ta": "முப்பதுபேரில் பராக்கிரமனும் முப்பதுபேருக்குப் பெரியவனுமான இஸ்மாயா என்னும் கிபியோனியனும், எரேமியா, யகாசியேல், யோகனான், கெதேரூரானான யோசபாத்,", "en": "And Ismaiah the Gibeonite, a mighty man among the thirty, and over the thirty; and Jeremiah, and Jahaziel, and Johanan, and Josabad the Gederathite,"}, {"verse": 5, "start": 55.2, "end": 61.07, "ta": "எலுசாயி, எரிமோத், பிகலியா, அரியா, அருப்பியனான செப்பத்தியா,", "en": "Eluzai, and Jerimoth, and Bealiah, and Shemariah, and Shephatiah the Haruphite,"}, {"verse": 6, "start": 61.07, "end": 67.82, "ta": "எல்க்கானா, எஷியா, அசாரியேல், யொவேசேர், யசொபெயாம் என்னும் கோரேகியரும்,", "en": "Elkanah, and Jesiah, and Azareel, and Joezer, and Jashobeam, the Korhites,"}, {"verse": 7, "start": 67.82, "end": 73.45, "ta": "யொவேலா, செபதியா என்னும் கேதோர் ஊரானான ஏரோகாமின் குமாரருமே.", "en": "And Joelah, and Zebadiah, the sons of Jeroham of Gedor."}, {"verse": 8, "start": 73.45, "end": 94.28, "ta": "காத்தியரில் பரிசையும் ஈட்டியும் பிடித்து, சிங்கமுகம் போன்ற முகமும், மலைகளிலிருக்கிற வெளிமான் வேகம்போன்ற வேகமுமுள்ளவர்களாயிருந்து, யுத்தசேவகரான பராக்கிரமசாலிகள் சிலரும் வனாந்தரத்திலுள்ள அரணான இடத்தில் இருக்கிற தாவீது பட்சமாய்ச் சேர்ந்தார்கள்.", "en": "And of the Gadites there separated themselves unto David into the hold to the wilderness men of might, and men of war fit for the battle, that could handle shield and buckler, whose faces were like the faces of lions, and were as swift as the roes upon the mountains;"}, {"verse": 9, "start": 94.28, "end": 102.01, "ta": "யாரென்றால், எத்சேர் என்னும் தலைவன், அவனுக்கு இரண்டாவது ஒபதியா; மூன்றாவது எலியாப்,", "en": "Ezer the first, Obadiah the second, Eliab the third,"}, {"verse": 10, "start": 102.01, "end": 105.38, "ta": "நாலாவது மிஸ்மன்னா, ஐந்தாவது எரேமியா,", "en": "Mishmannah the fourth, Jeremiah the fifth,"}, {"verse": 11, "start": 105.38, "end": 108.36, "ta": "ஆறாவது அத்தாயி, ஏழாவது எலியேல்,", "en": "Attai the sixth, Eliel the seventh,"}, {"verse": 12, "start": 108.36, "end": 111.82, "ta": "எட்டாவது யோகனான், ஒன்பதாவது எல்சபாத்,", "en": "Johanan the eighth, Elzabad the ninth,"}, {"verse": 13, "start": 111.82, "end": 115.68, "ta": "பத்தாவது எரேமியா, பதினோரவது மக்பன்னாயி;", "en": "Jeremiah the tenth, Machbanai the eleventh."}, {"verse": 14, "start": 115.68, "end": 128.15, "ta": "காத் புத்திரரான இவர்கள் இராணுவத்தலைவராயிருந்தார்கள்; அவர்களில் சிறியவன் நூறுபேருக்கும் பெரியவன் ஆயிரம்பேருக்கும் சேர்வைக்காரராயிருந்தார்கள்.", "en": "These were of the sons of Gad, captains of the host: one of the least was over an hundred, and the greatest over a thousand."}, {"verse": 15, "start": 128.15, "end": 141.18, "ta": "யோர்தான் கரைபுரண்டுபோயிருக்கிற முதலாம் மாதத்தில் அதைக் கடந்து, கிழக்கேயும் மேற்கேயும் பள்ளத்தாக்குகளில் இருக்கிற யாவரையும் துரத்திவிட்டவர்கள் இவர்களே.", "en": "These are they that went over Jordan in the first month, when it had overflown all his banks; and they put to flight all them of the valleys, both toward the east, and toward the west."}, {"verse": 16, "start": 141.18, "end": 150.75, "ta": "பின்னும் பென்யமீன் புத்திரரிலும் யூதாபுத்திரரிலும் சிலர் அரணான ஸ்தலத்தில் இருக்கிற தாவீதினிடத்தில் வந்தார்கள்.", "en": "And there came of the children of Benjamin and Judah to the hold unto David."}, {"verse": 17, "start": 150.75, "end": 180.59, "ta": "தாவீது புறப்பட்டு, அவர்களுக்கு எதிர்கொண்டுபோய், அவர்களுக்கு உத்தரவுகொடுத்து: நீங்கள் எனக்கு உதவிசெய்ய சமாதானமாய் என்னிடத்தில் வந்தீர்களானால், என் இருதயம் உங்களோடு இசைந்திருக்கும்; என் கைகளில் கொடுமை இல்லாதிருக்க, என்னை என் சத்துருக்களுக்குக் காட்டிக்கொடுக்க வந்தீர்களேயாகில், நம்முடைய பிதாக்களின் தேவன் அதைப் பார்த்துக் கண்டிப்பாராக என்றான்.", "en": "And David went out to meet them, and answered and said unto them, If ye be come peaceably unto me to help me, mine heart shall be knit unto you: but if ye be come to betray me to mine enemies, seeing there is no wrong in mine hands, the God of our fathers look thereon , and rebuke it ."}, {"verse": 18, "start": 180.59, "end": 212.44, "ta": "அப்பொழுது அதிபதிகளுக்குத் தலைவனான அமாசாயின்மேல் ஆவி இறங்கினதினால், அவன்: தாவீதே, நாங்கள் உம்முடையவர்கள்; ஈசாயின் குமாரனே உமது பட்சமாயிருப்போம்; உமக்குச் சமாதானம், சமாதானம்; உமக்கு உதவிசெய்கிறவர்களுக்கும் சமாதானம்; உம்முடைய தேவன் உமக்குத் துணை நிற்கிறார் என்றான்; அப்பொழுது தாவீது அவர்களைச் சேர்த்துக்கொண்டு, அவர்களைத் தண்டுக்குத் தலைவராக்கினான்.", "en": "Then the spirit came upon Amasai, who was chief of the captains, and he said , Thine are we , David, and on thy side, thou son of Jesse: peace, peace be unto thee, and peace be to thine helpers; for thy God helpeth thee. Then David received them, and made them captains of the band."}, {"verse": 19, "start": 212.44, "end": 238.42, "ta": "சவுலின்மேல் யுத்தம்பண்ணப்போகிற பெலிஸ்தருடனேகூடத் தாவீது வருகிறபோது, மனாசேயிலும் சிலர் அவன் பட்சமாய்ச் சேர்ந்தார்கள்; பெலிஸ்தரின் பிரபுக்கள் யோசனைபண்ணி, அவன் நம்முடைய தலைகளுக்கு மோசமாய்த் தன் ஆண்டவனாகிய சவுலின் பட்சமாய்ப் போவான் என்று அவனை அனுப்பிவிட்டார்கள்: அதனால் அவர்கள் இவர்களுக்கு உதவிசெய்யவில்லை.", "en": "And there fell some of Manasseh to David, when he came with the Philistines against Saul to battle: but they helped them not: for the lords of the Philistines upon advisement sent him away, saying, He will fall to his master Saul to the jeopardy of our heads."}, {"verse": 20, "start": 238.42, "end": 257.32, "ta": "அப்படியே அவன் சிக்லாகுக்குத் திரும்பிப்போகையில், மனாசேயில் அத்னாக், யோசபாத், எதியாவேல், மிகாயேல், யோசபாத், எலிகூ, சில்த்தாயி என்னும் மனாசே கோத்திரத்தாரின் ஆயிரத்துச் சேர்வைக்காரர் அவன் பட்சமாய் வந்தார்கள்.", "en": "As he went to Ziklag, there fell to him of Manasseh, Adnah, and Jozabad, and Jediael, and Michael, and Jozabad, and Elihu, and Zilthai, captains of the thousands that were of Manasseh."}, {"verse": 21, "start": 257.32, "end": 269.78, "ta": "அந்தத் தண்டுக்கு விரோதமாய் இவர்கள் தாவீதுக்கு உதவிசெய்தார்கள்; இவர்களெல்லாரும் பராக்கிரமசாலிகளும் இராணுவத்தில் சேர்வைக்காரருமாயிருந்தார்கள்.", "en": "And they helped David against the band of the rovers: for they were all mighty men of valour, and were captains in the host."}, {"verse": 22, "start": 269.78, "end": 281.37, "ta": "அக்காலத்திலே நாளுக்குநாள் தாவீதுக்கு உதவிசெய்யும் மனுஷர் அவனிடத்தில் வந்து சேர்ந்தபடியால், அவர்கள் தேவசேனையைப்போல மகா சேனையானார்கள்.", "en": "For at that time day by day there came to David to help him, until it was a great host, like the host of God."}, {"verse": 23, "start": 281.37, "end": 293.67, "ta": "கர்த்தருடைய வாக்கின்படியே, சவுலின் ராஜ்யபாரத்தைத் தாவீதினிடமாய்த் திருப்ப, எப்ரோனிலிருக்கிற அவனிடத்துக்கு வந்த யுத்த சன்னத்தரான தலைவரின் இலக்கமாவன:", "en": "And these are the numbers of the bands that were ready armed to the war, and came to David to Hebron, to turn the kingdom of Saul to him, according to the word of the LORD ."}, {"verse": 24, "start": 293.67, "end": 301.96, "ta": "யூதாபுத்திரரில் பரிசையும் ஈட்டியும் பிடித்து, யுத்தசன்னத்தரானவர்கள் ஆறாயிரத்து எண்ணூறுபேர்.", "en": "The children of Judah that bare shield and spear were six thousand and eight hundred, ready armed to the war."}, {"verse": 25, "start": 301.96, "end": 308.47, "ta": "சிமியோன் புத்திரரில் பராக்கிரமசாலிகளாகிய யுத்தவீரர் ஏழாயிரத்து நூறுபேர்.", "en": "Of the children of Simeon, mighty men of valour for the war, seven thousand and one hundred."}, {"verse": 26, "start": 308.47, "end": 312.49, "ta": "லேவி புத்திரரில் நாலாயிரத்து அறுநூறுபேர்.", "en": "Of the children of Levi four thousand and six hundred."}, {"verse": 27, "start": 312.49, "end": 319.97, "ta": "ஆரோன் சந்ததியாரின் அதிபதியாகிய யோயதாவும், அவனோடிருந்த மூவாயிரத்து; எழுநூறுபேரும்,", "en": "And Jehoiada was the leader of the Aaronites, and with him were three thousand and seven hundred;"}, {"verse": 28, "start": 319.97, "end": 328.26, "ta": "பராக்கிரமசாலியான சாதோக் என்னும் வாலிபனும், அவன் தகப்பன் வம்சத்தாரான இருபத்திரண்டு தலைவருமே.", "en": "And Zadok, a young man mighty of valour, and of his father’s house twenty and two captains."}, {"verse": 29, "start": 328.26, "end": 340.72, "ta": "பென்யமீன் புத்திரரான சவுலின் சகோதரரில் மூவாயிரம்பேர்; அதுவரைக்கும் அவர்களில் மிச்சமானவர்கள் சவுலின் குடும்பத்தைக் காப்பாற்றப் பார்த்தார்கள்.", "en": "And of the children of Benjamin, the kindred of Saul, three thousand: for hitherto the greatest part of them had kept the ward of the house of Saul."}, {"verse": 30, "start": 340.72, "end": 350.94, "ta": "எப்பிராயீம் புத்திரரில் தங்கள் பிதாக்களின் வம்சத்தில் பேர் பெற்ற மனுஷரான பராக்கிரமசாலிகள் இருபதினாயிரத்து எண்ணூறுபேர்.", "en": "And of the children of Ephraim twenty thousand and eight hundred, mighty men of valour, famous throughout the house of their fathers."}, {"verse": 31, "start": 350.94, "end": 361.32, "ta": "மனாசேயின் பாதிக்கோத்திரத்தில் தாவீதை ராஜாவாக்குகிறதற்கு வரும்படி, பேர்பேராகக் குறிக்கப்பட்டவர்கள் பதினெண்ணாயிரம்பேர்.", "en": "And of the half tribe of Manasseh eighteen thousand, which were expressed by name, to come and make David king."}, {"verse": 32, "start": 361.32, "end": 378.37, "ta": "இசக்கார் புத்திரரில், இஸ்ரவேலர் செய்யவேண்டியது இன்னதென்று அறிந்து காலாகாலங்களுக்குத் தகுந்த யோசனை சொல்லத்தக்க தலைவர்கள் இருநூறுபேரும், இவர்கள் வாக்குக்குச் செவிகொடுத்த இவர்களுடைய எல்லாச் சகோதரருமே.", "en": "And of the children of Issachar, which were men that had understanding of the times, to know what Israel ought to do; the heads of them were two hundred; and all their brethren were at their commandment."}, {"verse": 33, "start": 378.37, "end": 394.05, "ta": "செபுலோன் புத்திரரில் சகலவித யுத்த ஆயுதங்களாலும் யுத்தம் செய்கிறதற்கும், தங்கள் அணியைக் காத்துநிற்கிறதற்கும் பழகி, வஞ்சனைசெய்யாமல் யுத்தத்திற்குப் போகத்தக்கவர்கள் ஐம்பதினாயிரம்பேர்.", "en": "Of Zebulun, such as went forth to battle, expert in war, with all instruments of war, fifty thousand, which could keep rank: they were not of double heart."}, {"verse": 34, "start": 394.05, "end": 403.7, "ta": "நப்தலி புத்திரரில் ஆயிரம் தலைவர்கள் பரிசையும் ஈட்டியும் பிடித்த அவர்களோடேகூட இருந்தவர்கள் முப்பத்தேழாயிரம்பேர்.", "en": "And of Naphtali a thousand captains, and with them with shield and spear thirty and seven thousand."}, {"verse": 35, "start": 403.7, "end": 410.78, "ta": "தாண் புத்திரரில் யுத்தத்திற்குத் தேறினவர்கள் இருபத்து எண்ணாயிரத்து அறுநூறுபேர்.", "en": "And of the Danites expert in war twenty and eight thousand and six hundred."}, {"verse": 36, "start": 410.78, "end": 419.14, "ta": "ஆசேர் புத்திரரில் யுத்தத்திற்குத் தேறினவர்களாய் சேவகம்பண்ணப்போகத்தக்கவர்கள் நாற்பதினாயிரம்பேர்.", "en": "And of Asher, such as went forth to battle, expert in war, forty thousand."}, {"verse": 37, "start": 419.14, "end": 433.14, "ta": "யோர்தானுக்கு அக்கரையான ரூபனியரிலும், காத்தியரிலும், மனாசேயின் பாதிக்கோத்திரத்தாரிலும், யுத்தம்பண்ண சகலவித ஆயுதங்களையும் தரித்தவர்கள் நூற்றிருபதினாயிரம்பேர்.", "en": "And on the other side of Jordan, of the Reubenites, and the Gadites, and of the half tribe of Manasseh, with all manner of instruments of war for the battle, an hundred and twenty thousand."}, {"verse": 38, "start": 433.14, "end": 452.28, "ta": "தாவீதை இஸ்ரவேலின்மேல் ராஜாவாக்குகிறதற்கு, இந்த யுத்தமனுஷர் எல்லாரும் அணி அணியாய் வைக்கப்பட்டவர்களாக, உத்தம இருதயத்தோடே எப்ரோனுக்கு வந்தார்கள்; இஸ்ரவேலில் மற்ற யாவரும் தாவீதை ராஜாவாக்குகிறதற்கு ஒருமனப்பட்டிருந்தார்கள்.", "en": "All these men of war, that could keep rank, came with a perfect heart to Hebron, to make David king over all Israel: and all the rest also of Israel were of one heart to make David king."}, {"verse": 39, "start": 452.28, "end": 464.83, "ta": "அவர்கள் அங்கே தாவீதோடேகூட மூன்றுநாள் இருந்து, போஜனபானம்பண்ணினார்கள்; அவர்கள் சகோதரர் அவர்களுக்காகச் சகலத்தையும் ஆயத்தம்பண்ணியிருந்தார்கள்.", "en": "And there they were with David three days, eating and drinking: for their brethren had prepared for them."}, {"verse": 40, "start": 464.83, "end": 494.75, "ta": "இசக்கார், செபுலோன், நப்தலியின் எல்லைமட்டும் அவர்களுக்குச் சமீபமாயிருந்தவர்களும், கழுதைகள்மேலும் ஒட்டகங்கள்மேலும் கோவேறு கழுதைகள்மேலும் மாடுகள்மேலும், தின்பண்டங்களாகிய மா, அத்திப்பழ அடைகள், வற்றலான திராட்சப்பழங்கள், திராட்சரசம், எண்ணெய் ஆடுமாடுகள் ஆகிய இவைகளை வேண்டிய மட்டும் ஏற்றிக்கொண்டுவந்தார்கள்; இஸ்ரவேலிலே மகிழ்ச்சியுண்டாயிற்று.", "en": "Moreover they that were nigh them, even unto Issachar and Zebulun and Naphtali, brought bread on asses, and on camels, and on mules, and on oxen, and meat, meal, cakes of figs, and bunches of raisins, and wine, and oil, and oxen, and sheep abundantly: for there was joy in Israel."}]}, "13": {"chapter": 13, "duration": 182.54, "audio_url": "audio_ot/OT13_13.mp3", "total_verses": 14, "verses": [{"verse": 1, "start": 3.8, "end": 11.3, "ta": "தாவீது ஆயிரம்பேருக்குத் தலைவரோடும் நூறுபேருக்குத் தலைவரோடும் சகல அதிபதிகளோடும் ஆலோசனைபண்ணி,", "en": "And David consulted with the captains of thousands and hundreds, and with every leader."}, {"verse": 2, "start": 11.3, "end": 35.97, "ta": "இஸ்ரவேல் சபையையெல்லாம் நோக்கி: உங்களுக்குச் சம்மதியும் நம்முடைய தேவனாகிய கர்த்தருக்குச் சித்தமுமாயிருந்தால், இஸ்ரவேலின் தேசங்களிலெல்லாம் இருக்கிற நம்முடைய மற்றச் சகோதரரும், அவர்களோடே தங்கள் வெளிநிலங்களில் இருக்கிற ஆசாரியரும் லேவியரும் நம்மோடே கூடும்படிக்கு நாம் சீக்கிரமாய் அவர்களிடத்துக்கு ஆளனுப்பி,", "en": "And David said unto all the congregation of Israel, If it seem good unto you, and that it be of the LORD our God, let us send abroad unto our brethren every where, that are left in all the land of Israel, and with them also to the priests and Levites which are in their cities and suburbs, that they may gather themselves unto us:"}, {"verse": 3, "start": 35.97, "end": 46.03, "ta": "நமது தேவனுடைய பெட்டியைத் திரும்ப நம்மிடத்துக்குக் கொண்டுவருவோமாக; சவுலின் நாட்களில் அதைத் தேடாதேபோனோம் என்றான்.", "en": "And let us bring again the ark of our God to us: for we enquired not at it in the days of Saul."}, {"verse": 4, "start": 46.03, "end": 55.93, "ta": "இந்தக் காரியம் சகல ஜனத்தின் பார்வைக்கும் செம்மையாயிருந்தபடியால், சபையார் எல்லாரும் அப்படியே செய்வோம் என்றார்கள்.", "en": "And all the congregation said that they would do so: for the thing was right in the eyes of all the people."}, {"verse": 5, "start": 55.93, "end": 68.95, "ta": "அப்படியே தேவனுடைய பெட்டியைக் கீரியாத்யாரீமிலிருந்து கொண்டுவரும்படி, தாவீது எகிப்தைச்சேர்ந்த கோர் நதிதுவக்கி ஆமாத்தின் எல்லைமட்டுமுள்ள இஸ்ரவேலையெல்லாங்கூட்டி,", "en": "So David gathered all Israel together, from Shihor of Egypt even unto the entering of Hemath, to bring the ark of God from Kirjath-jearim."}, {"verse": 6, "start": 68.95, "end": 87.79, "ta": "கேருபீன்களின் நடுவே வாசம்பண்ணுகிற கர்த்தராகிய தேவனுடைய நாமம் தொழுதுகொள்ளப்படுகிற அவருடைய பெட்டியை யூதாவிலிருக்கிற கீரியாத்யாரீமுக்கடுத்த பாலாவிலிருந்து கொண்டுவரும்படிக்கு, அவனும் இஸ்ரவேலர் அனைவரும் அவ்விடத்திற்குப்போனார்கள்.", "en": "And David went up, and all Israel, to Baalah, that is , to Kirjath-jearim, which belonged to Judah, to bring up thence the ark of God the LORD , that dwelleth between the cherubims, whose name is called on it ."}, {"verse": 7, "start": 87.79, "end": 100.0, "ta": "அவர்கள் தேவனுடைய பெட்டியை அபினதாபின் வீட்டிலிருந்து ஒரு புதுரதத்தின்மேல் ஏற்றிக்கொண்டு வந்தார்கள்; ஊசாவும் அகியோவும் ரதத்தை நடத்தினார்கள்.", "en": "And they carried the ark of God in a new cart out of the house of Abinadab: and Uzza and Ahio drave the cart."}, {"verse": 8, "start": 100.0, "end": 115.57, "ta": "தாவீதும் சகல இஸ்ரவேலரும் தங்கள் முழுப் பலத்தோடும் தேவனுக்குமுன்பாகச் சுரமண்டலங்களையும் தம்புருகளையும் மேளங்களையும் கைத்தாளங்களையும் பூரிகைகளையும் சேவித்து மகிழ்ச்சியாய் ஆடிப்பாடினார்கள்.", "en": "And David and all Israel played before God with all their might, and with singing, and with harps, and with psalteries, and with timbrels, and with cymbals, and with trumpets."}, {"verse": 9, "start": 115.57, "end": 125.15, "ta": "அவர்கள் கீதோனின் களமட்டும்வந்தபோது, மாடுகள் இடறினபடியினால், ஊசா பெட்டியைப் பிடிக்கத் தன் கையை நீட்டினான்.", "en": "And when they came unto the threshingfloor of Chidon, Uzza put forth his hand to hold the ark; for the oxen stumbled."}, {"verse": 10, "start": 125.15, "end": 138.33, "ta": "அப்பொழுது கர்த்தர் ஊசாவின்மேல் கோபம் மூண்டவராகி, அவன் தன்கையை பெட்டியண்டைக்கு நீட்டினதினிமித்தம் அவனை அடித்தார்; அங்கே அவன் தேவசமுகத்தில் செத்தான்.", "en": "And the anger of the LORD was kindled against Uzza, and he smote him, because he put his hand to the ark: and there he died before God."}, {"verse": 11, "start": 138.33, "end": 149.66, "ta": "அப்பொழுது கர்த்தர் ஊசாவை அடித்ததினிமித்தம் தாவீது விசனப்பட்டு, அந்த ஸ்தலத்திற்கு இந்நாள்மட்டும் வழங்கிவருகிற பேரேஸ்ஊசா என்னும் பேரிட்டு,", "en": "And David was displeased, because the LORD had made a breach upon Uzza: wherefore that place is called Perez-uzza to this day."}, {"verse": 12, "start": 149.66, "end": 158.21, "ta": "அன்றையதினம் தேவனுக்குப்பயந்து: தேவனுடைய பெட்டியை நான் என்னிடத்துக்குக் கொண்டுவருவது எப்படியென்று சொல்லி,", "en": "And David was afraid of God that day, saying, How shall I bring the ark of God home to me?"}, {"verse": 13, "start": 158.21, "end": 167.79, "ta": "பெட்டியைத் தன்னிடத்தில் தாவீதின் நகரத்திலே கொண்டுவராமல், அதைக் கித்தியனாகிய ஓபேத்ஏதோமின்வீட்டிலே சேர்த்தான்.", "en": "So David brought not the ark home to himself to the city of David, but carried it aside into the house of Obed-edom the Gittite."}, {"verse": 14, "start": 167.79, "end": 181.04, "ta": "தேவனுடைய பெட்டி ஓபேத்ஏதோமின் வீட்டிலே அவனிடத்தில் மூன்றுமாதம் இருக்கையில், கர்த்தர் ஓபேத்ஏதோமின் வீட்டையும் அவனுக்கு உண்டான எல்லாவற்றையும் ஆசீர்வதித்தார்.", "en": "And the ark of God remained with the family of Obed-edom in his house three months. And the LORD blessed the house of Obed-edom, and all that he had."}]}, "14": {"chapter": 14, "duration": 191.19, "audio_url": "audio_ot/OT13_14.mp3", "total_verses": 17, "verses": [{"verse": 1, "start": 3.8, "end": 17.82, "ta": "தீருவின் ராஜாவாகிய ஈராம் தாவீதினிடத்தில் ஸ்தானாபதிகளையும், அவனுக்கு ஒரு வீட்டைக் கட்டுகிறதற்குக் கேதுருமரங்களையும், தச்சரையும், கல்தச்சரையும் அனுப்பினான்.", "en": "Now Hiram king of Tyre sent messengers to David, and timber of cedars, with masons and carpenters, to build him an house."}, {"verse": 2, "start": 17.82, "end": 32.09, "ta": "கர்த்தர் தன்னை இஸ்ரவேலின்மேல் ராஜாவாகத் திடப்படுத்தி, இஸ்ரவேலென்னும் தம்முடைய ஜனத்தினிமித்தம் தன்னுடைய ராஜ்யத்தை மிகவும் உயர்த்தினார் என்று தாவீது அறிந்துகொண்டான்.", "en": "And David perceived that the LORD had confirmed him king over Israel, for his kingdom was lifted up on high, because of his people Israel."}, {"verse": 3, "start": 32.09, "end": 41.47, "ta": "எருசலேமிலே தாவீது பின்னும் அநேக ஸ்திரீகளை விவாகம்பண்ணி, பின்னும் குமாரரையும் குமாரத்திகளையும் பெற்றான்.", "en": "And David took more wives at Jerusalem: and David begat more sons and daughters."}, {"verse": 4, "start": 41.47, "end": 49.54, "ta": "எருசலேமிலே அவனுக்குப் பிறந்த குமாரரின் நாமங்களாவன: சம்முவா, சோபாப், நாத்தான், சாலொமோன்,", "en": "Now these are the names of his children which he had in Jerusalem; Shammua, and Shobab, Nathan, and Solomon,"}, {"verse": 5, "start": 49.54, "end": 52.39, "ta": "இப்கார், எலிவா, எல்பெலேத்,", "en": "And Ibhar, and Elishua, and Elpalet,"}, {"verse": 6, "start": 52.39, "end": 55.08, "ta": "நோகா, நெப்பேக், யப்பியா,", "en": "And Nogah, and Nepheg, and Japhia,"}, {"verse": 7, "start": 55.08, "end": 59.65, "ta": "எலிஷாமா, பெலியாதா, எலிப்பெலேத் என்பவைகள்.", "en": "And Elishama, and Beeliada, and Eliphalet."}, {"verse": 8, "start": 59.65, "end": 77.18, "ta": "தாவீது சமஸ்த இஸ்ரவேலின்மேலும் ராஜாவாக அபிஷேகம்பண்ணப்பட்டதைப் பெலிஸ்தர் கேள்விப்பட்டபோது, பெலிஸ்தர் எல்லாரும் தாவீதைத் தேடும்படி வந்தார்கள்; அதை தாவீது கேட்டபோது அவர்களுக்கு விரோதமாகப் புறப்பட்டான்.", "en": "And when the Philistines heard that David was anointed king over all Israel, all the Philistines went up to seek David. And David heard of it , and went out against them."}, {"verse": 9, "start": 77.18, "end": 82.8, "ta": "பெலிஸ்தர் வந்து ரெப்பாயீம் பள்ளத்தாக்கிலே பரவியிருந்தார்கள்.", "en": "And the Philistines came and spread themselves in the valley of Rephaim."}, {"verse": 10, "start": 82.8, "end": 97.4, "ta": "பெலிஸ்தருக்கு விரோதமாகப் போகலாமா, அவர்களை என் கையில் ஒப்புக்கொடுப்பீரா என்று தாவீது தேவனைக் கேட்டபோது, கர்த்தர் போ, அவர்களை உன் கையில் ஒப்புக்கொடுப்பேன் என்றார்.", "en": "And David enquired of God, saying, Shall I go up against the Philistines? and wilt thou deliver them into mine hand? And the LORD said unto him, Go up; for I will deliver them into thine hand."}, {"verse": 11, "start": 97.4, "end": 118.11, "ta": "அவர்கள் பாகால்பிராசீமுக்கு வந்தபோது, தாவீது அங்கே அவர்களை முறியடித்து தண்ணீர்கள் உடைந்தோடுகிறதுபோல, தேவன் என் கையினால் என் சத்துருக்களை உடைந்தோடப்பண்ணினாரென்றான்; அதினிமித்தம் அந்த ஸ்தலத்திற்குப் பாகால்பிராசீம் என்னும் பேரிட்டார்கள்.", "en": "So they came up to Baal-perazim; and David smote them there. Then David said, God hath broken in upon mine enemies by mine hand like the breaking forth of waters: therefore they called the name of that place Baal-perazim."}, {"verse": 12, "start": 118.11, "end": 128.38, "ta": "அங்கே அவர்கள் தங்கள் தெய்வங்களைவிட்டு ஓடிப்போனார்கள்; தாவீது கற்பித்தபடி அவைகள் அக்கினியாலே சுட்டெரிக்கப்பட்டன.", "en": "And when they had left their gods there, David gave a commandment, and they were burned with fire."}, {"verse": 13, "start": 128.38, "end": 134.25, "ta": "பெலிஸ்தர் மறுபடியும் வந்து அந்தப் பள்ளத்தாக்கிலே இறங்கினார்கள்.", "en": "And the Philistines yet again spread themselves abroad in the valley."}, {"verse": 14, "start": 134.25, "end": 150.96, "ta": "அப்பொழுது தாவீது திரும்ப தேவனிடத்தில் விசாரித்ததற்கு, தேவன் நீ அவர்களுக்குப் பின்னாலே போகாமல், அவர்களுக்குப் பக்கமாய்ச் சுற்றி, முசுக்கட்டைச் செடிகளுக்கு எதிரேயிருந்து, அவர்கள்மேல் பாய்ந்து,", "en": "Therefore David enquired again of God; and God said unto him, Go not up after them; turn away from them, and come upon them over against the mulberry trees."}, {"verse": 15, "start": 150.96, "end": 166.86, "ta": "முசுக்கட்டைச் செடிகளின் நுனிகளிலே செல்லுகிற இரைச்சலை நீ கேட்கும்போது, யுத்தத்திற்குப் புறப்படு; பெலிஸ்தரின் பாளயத்தை முறிய அடிக்க தேவன் உனக்கு முன்னே புறப்பட்டிருப்பார் என்றார்.", "en": "And it shall be, when thou shalt hear a sound of going in the tops of the mulberry trees, that then thou shalt go out to battle: for God is gone forth before thee to smite the host of the Philistines."}, {"verse": 16, "start": 166.86, "end": 177.95, "ta": "தேவன் தனக்குக் கற்பித்தபடியே தாவீது செய்தபோது, பெலிஸ்தரின் இராணுவத்தைக் கிபியோன் துவக்கிக் காசேர்மட்டும் முறிய அடித்தார்கள்.", "en": "David therefore did as God commanded him: and they smote the host of the Philistines from Gibeon even to Gazer."}, {"verse": 17, "start": 177.95, "end": 189.69, "ta": "அப்படியே தாவீதின் கீர்த்தி சகல தேசங்களிலும் பிரசித்தமாகி, அவனுக்குப் பயப்படுகிற பயத்தைக் கர்த்தர் சகல ஜாதிகளின்மேலும் வரப்பண்ணினார்.", "en": "And the fame of David went out into all lands; and the LORD brought the fear of him upon all nations."}]}, "15": {"chapter": 15, "duration": 360.77, "audio_url": "audio_ot/OT13_15.mp3", "total_verses": 29, "verses": [{"verse": 1, "start": 3.8, "end": 15.31, "ta": "அவன் தனக்குத் தாவீதின் நகரத்தில் வீடுகளை உண்டாக்கி, தேவனுடைய பெட்டிக்கு ஒரு ஸ்தலத்தை ஆயத்தப்படுத்தி, அதற்கு ஒரு கூடாரத்தைப்போட்டான்.", "en": "And David made him houses in the city of David, and prepared a place for the ark of God, and pitched for it a tent."}, {"verse": 2, "start": 15.31, "end": 31.91, "ta": "பிற்பாடு தாவீது: லேவியர் ஒழிய, வேறொருவரும் தேவனுடைய பெட்டியை எடுக்கலாகாது; தேவனுடைய பெட்டியை எடுக்கவும், என்றைக்கும் அவருக்குப் பணிவிடைசெய்யவும், அவர்களை கர்த்தர் தெரிந்துகொண்டார் என்றான்.", "en": "Then David said, None ought to carry the ark of God but the Levites: for them hath the LORD chosen to carry the ark of God, and to minister unto him for ever."}, {"verse": 3, "start": 31.91, "end": 43.98, "ta": "அப்படி கர்த்தருடைய பெட்டிக்குத் தான் ஆயத்தப்படுத்தின அதின் ஸ்தலத்திற்கு அதைக் கொண்டுவரும்படி தாவீது இஸ்ரவேலையெல்லாம் எருசலேமிலே கூடிவரச்செய்தான்.", "en": "And David gathered all Israel together to Jerusalem, to bring up the ark of the LORD unto his place, which he had prepared for it."}, {"verse": 4, "start": 43.98, "end": 45.93, "ta": "ஆரோனின் புத்திரரையும்,", "en": "And David assembled the children of Aaron, and the Levites:"}, {"verse": 5, "start": 45.93, "end": 53.14, "ta": "லேவியராகிய கோகாத் புத்திரரில் பிரபுவாகிய ஊரியேலையும் அவன் சகோதரராகிய நூற்றிருபதுபேரையும்,", "en": "Of the sons of Kohath; Uriel the chief, and his brethren an hundred and twenty:"}, {"verse": 6, "start": 53.14, "end": 60.34, "ta": "மெராரியின் புத்திரரில் பிரபுவாகிய அசாயாவையும், அவன் சகோதரராகிய இருநூற்றிருபதுபேரையும்,", "en": "Of the sons of Merari; Asaiah the chief, and his brethren two hundred and twenty:"}, {"verse": 7, "start": 60.34, "end": 67.23, "ta": "கெர்சோன் புத்திரரில் பிரபுவாகிய யோவேலையும், அவன் சகோதரராகிய நூற்றுமுப்பதுபேரையும்,", "en": "Of the sons of Gershom; Joel the chief, and his brethren an hundred and thirty:"}, {"verse": 8, "start": 67.23, "end": 74.05, "ta": "எலிசாப்பான் புத்திரரில் பிரபுவாகிய செமாயாவையும், அவன் சகோதரராகிய இருநூறுபேரையும்,", "en": "Of the sons of Elizaphan; Shemaiah the chief, and his brethren two hundred:"}, {"verse": 9, "start": 74.05, "end": 80.55, "ta": "எப்ரோன் புத்திரரில் பிரபுவாகிய, எலியேலைம், அவன் சகோதரராகிய எண்பதுபேரையும்,", "en": "Of the sons of Hebron; Eliel the chief, and his brethren fourscore:"}, {"verse": 10, "start": 80.55, "end": 90.49, "ta": "ஊசியேல் புத்திரரில் பிரபுவாகிய அம்மினதாபையும், அவன் சகோதரராகிய நூற்றுப்பன்னிரண்டுபேரையும் தாவீது கூடிவரப்பண்ணினான்.", "en": "Of the sons of Uzziel; Amminadab the chief, and his brethren an hundred and twelve."}, {"verse": 11, "start": 90.49, "end": 103.49, "ta": "பின்பு தாவீது ஆசாரியராகிய சாதோக்கையும், அபியத்தாரையும், லேவியராகிய ஊரியேல், அசாயா, யோவேல், செமாயா, எலியேல், அம்மினதாப் என்பவர்களையும் அழைத்து,", "en": "And David called for Zadok and Abiathar the priests, and for the Levites, for Uriel, Asaiah, and Joel, Shemaiah, and Eliel, and Amminadab,"}, {"verse": 12, "start": 103.49, "end": 122.76, "ta": "அவர்களை நோக்கி: லேவியரில் நீங்கள் பிதாக்களுடைய சந்ததிகளின் தலைவர், நீங்கள் இஸ்ரவேலின் தேவனாகிய கர்த்தரின் பெட்டியை அதற்கு நான் ஆயத்தம்பண்ணின ஸ்தலத்திற்குக் கொண்டுவரும்படி, உங்களையும் உங்கள் சகோதரரையும் பரிசுத்தம்பண்ணிக்கொள்ளுங்கள்.", "en": "And said unto them, Ye are the chief of the fathers of the Levites: sanctify yourselves, both ye and your brethren, that ye may bring up the ark of the LORD God of Israel unto the place that I have prepared for it."}, {"verse": 13, "start": 122.76, "end": 135.92, "ta": "முதலில் நீங்கள் அதைச் சுமக்காதபடியினாலும், நாம் நம்முடைய தேவனாகிய கர்த்தரை நியாயமானபடியே தேடாதேபோனபடியினாலும், அவர் நமக்குள்ளே அடிவிழப்பண்ணினார் என்றான்.", "en": "For because ye did it not at the first, the LORD our God made a breach upon us, for that we sought him not after the due order."}, {"verse": 14, "start": 135.92, "end": 145.86, "ta": "அப்படியே ஆசாரியரும் லேவியரும் இஸ்ரவேலின் தேவனாகிய கர்த்தரின் பெட்டியைக் கொண்டுவரத் தங்களைச் சுத்தம்பண்ணிக்கொண்டார்கள்.", "en": "So the priests and the Levites sanctified themselves to bring up the ark of the LORD God of Israel."}, {"verse": 15, "start": 145.86, "end": 158.86, "ta": "பின்பு லேவி புத்திரர் கர்த்தருடைய வார்த்தையின்படியே, மோசே கற்பித்தபிரகாரம் தேவனுடைய பெட்டியை அதின் தண்டுகளினாலே தங்கள் தோள்மேல் எடுத்துக்கொண்டுவந்தார்கள்.", "en": "And the children of the Levites bare the ark of God upon their shoulders with the staves thereon, as Moses commanded according to the word of the LORD ."}, {"verse": 16, "start": 158.86, "end": 176.33, "ta": "தாவீது லேவியரின் பிரபுக்களை நோக்கி: நீங்கள் உங்கள் சகோதரராகிய பாடகரைத் தம்புரு சுரமண்டலம் கைத்தாளம் முதலிய கீதவாத்தியங்கள் முழங்க தங்கள் சத்தத்தை உயர்த்தி, சந்தோஷமுண்டாகப் பாடும்படி நிறுத்தவேண்டுமென்று சொன்னான்.", "en": "And David spake to the chief of the Levites to appoint their brethren to be the singers with instruments of musick, psalteries and harps and cymbals, sounding, by lifting up the voice with joy."}, {"verse": 17, "start": 176.33, "end": 190.5, "ta": "அப்படியே லேவியர் யோவேலின் குமாரனாகிய ஏமானையும், அவன் சகோதரரில் பெரகியாவின் குமாரனாகிய ஆசாப்பையும், மெராரியின் புத்திரரான தங்கள் சகோதரரில் குஷாயாவின் குமாரனாகிய ஏத்தானையும்,", "en": "So the Levites appointed Heman the son of Joel; and of his brethren, Asaph the son of Berechiah; and of the sons of Merari their brethren, Ethan the son of Kushaiah;"}, {"verse": 18, "start": 190.5, "end": 212.12, "ta": "இவர்களோடுங்கூட இரண்டாவது வரிசையாகத் தங்கள் சகோதரராகிய சகரியா, பேன், யாசியேல், செமிரமோத், யெகியேல், உன்னி, எலியாப், பெனாயா, மாசெயா, மத்தித்தியா, எலிப்பெலேகு, மிக்னேயா, ஒபேத்ஏதோம், ஏயெல் என்னும் வாசல் காவலாளரையும் நிறுத்தினார்கள்.", "en": "And with them their brethren of the second degree , Zechariah, Ben, and Jaaziel, and Shemiramoth, and Jehiel, and Unni, Eliab, and Benaiah, and Maaseiah, and Mattithiah, and Elipheleh, and Mikneiah, and Obed-edom, and Jeiel, the porters."}, {"verse": 19, "start": 212.12, "end": 220.97, "ta": "பாடகராகிய ஏமானும், ஆசாப்பும், ஏத்தானும், பஞ்சலோகக் கைத்தாளங்களைத் தொனிக்கப்பண்ணிப் பாடினார்கள்.", "en": "So the singers, Heman, Asaph, and Ethan, were appointed to sound with cymbals of brass;"}, {"verse": 20, "start": 220.97, "end": 234.12, "ta": "சகரியா, ஆசியேல், செமிரமோத், யெகியேல், உன்னி, எலியாப், மாசெயா, பெனாயா என்பவர்கள் அல்மோத் என்னும் இசையில் பாடி, தம்புருகளை வாசித்தார்கள்.", "en": "And Zechariah, and Aziel, and Shemiramoth, and Jehiel, and Unni, and Eliab, and Maaseiah, and Benaiah, with psalteries on Alamoth;"}, {"verse": 21, "start": 234.12, "end": 247.52, "ta": "மத்தித்தியா, எலிப்பெலேகு, மிக்னேயா, ஓபேத்ஏதோம், ஏயெல், அசசியா என்பவர்கள் செமனீத் என்னும் இசையில் பாடி, சுரமண்டலங்களை நேர்த்தியாய் வாசித்தார்கள்.", "en": "And Mattithiah, and Elipheleh, and Mikneiah, and Obed-edom, and Jeiel, and Azaziah, with harps on the Sheminith to excel."}, {"verse": 22, "start": 247.52, "end": 257.46, "ta": "லேவியருக்குள்ளே கெனானியா என்பவன் சங்கீதத்தலைவனாயிருந்தான்; அவன் நிபுணனானபடியால், கீதவித்தையைப் படிப்பித்தான்.", "en": "And Chenaniah, chief of the Levites, was for song: he instructed about the song, because he was skilful."}, {"verse": 23, "start": 257.46, "end": 263.57, "ta": "பெரகியாவும் எல்க்கானாவும் பெட்டிக்கு முன்பாகக் காவல்காத்துவந்தார்கள்.", "en": "And Berechiah and Elkanah were doorkeepers for the ark."}, {"verse": 24, "start": 263.57, "end": 281.74, "ta": "செபனியா, யோசபாத், நெதனெயேல், அமாசாயி, சகரியா, பெனாயா, எலியேசர் என்னும் ஆசாரியர் தேவனுடைய பெட்டிக்கு முன்பாகப் பூரிகைகளை ஊதினார்கள்; ஓபேத் ஏதோமும், எகியாவும் பெட்டிக்கு வாசல் காவலாளராயிருந்தார்கள்.", "en": "And Shebaniah, and Jehoshaphat, and Nethaneel, and Amasai, and Zechariah, and Benaiah, and Eliezer, the priests, did blow with the trumpets before the ark of God: and Obed-edom and Jehiah were doorkeepers for the ark."}, {"verse": 25, "start": 281.74, "end": 295.84, "ta": "இப்படித் தாவீதும், இஸ்ரவேலின் மூப்பரும், ஆயிரத்துச் சேர்வைக்காரரும் கர்த்தருடைய உடன்படிக்கைப் பெட்டியை ஓபேத்ஏதோமின் வீட்டிலிருந்து மகிழ்ச்சியோடே கொண்டுவரப்போனார்கள்.", "en": "So David, and the elders of Israel, and the captains over thousands, went to bring up the ark of the covenant of the LORD out of the house of Obed-edom with joy."}, {"verse": 26, "start": 295.84, "end": 308.68, "ta": "கர்த்தருடைய உடன்படிக்கைப்பெட்டியைச் சுமக்கிற லேவியருக்கு தேவன் அநுக்கிரகம்பண்ணினபடியால், அவர்கள் ஏழு காளைகளையும் ஏழு ஆட்டுக்கடாக்களையும் பலியிட்டார்கள்.", "en": "And it came to pass, when God helped the Levites that bare the ark of the covenant of the LORD , that they offered seven bullocks and seven rams."}, {"verse": 27, "start": 308.68, "end": 326.3, "ta": "தாவீதும், பெட்டியைச் சுமக்கிற சகல லேவியரும், பாடகரும், பாடகரின் வேலையை விசாரிக்கிற தலைவனாகிய கெனானியாவும், மெல்லிய புடவையான சால்வைகளைத் தரித்திருந்தார்கள்; தாவீது சணல்நூல் ஏபோத்தைத் தரித்திருந்தான்.", "en": "And David was clothed with a robe of fine linen, and all the Levites that bare the ark, and the singers, and Chenaniah the master of the song with the singers: David also had upon him an ephod of linen."}, {"verse": 28, "start": 326.3, "end": 342.9, "ta": "அப்படியே இஸ்ரவேலனைத்தும் கர்த்தருடைய உடன்படிக்கைப் பெட்டியைக் கெம்பீரத்தோடும், எக்காளங்கள் பூரிகைகள் கைத்தாளங்களின் தொனியோடும் தம்புருகளையும் சுரமண்டலங்களையும் வாசிக்கிற சத்தத்தோடும் கொண்டுவந்தார்கள்.", "en": "Thus all Israel brought up the ark of the covenant of the LORD with shouting, and with sound of the cornet, and with trumpets, and with cymbals, making a noise with psalteries and harps."}, {"verse": 29, "start": 342.9, "end": 359.27, "ta": "கர்த்தருடைய உடன்படிக்கைப்பெட்டி தாவீதின் நகரமட்டும் வந்தபோது, சவுலின் குமாரத்தியாகிய மீகாள் பலகணிவழியாய்ப் பார்த்து, தாவீதுராஜா ஆடிப்பாடி வருகிறதைக் கண்டு, அவனைத் தன் இருதயத்திலே அவமதித்தாள்.", "en": "And it came to pass, as the ark of the covenant of the LORD came to the city of David, that Michal the daughter of Saul looking out at a window saw king David dancing and playing: and she despised him in her heart."}]}, "16": {"chapter": 16, "duration": 423.53, "audio_url": "audio_ot/OT13_16.mp3", "total_verses": 43, "verses": [{"verse": 1, "start": 3.8, "end": 18.5, "ta": "அவர்கள் தேவனுடைய பெட்டியை உள்ளே கொண்டுவந்தபோது, தாவீது அதற்குப் போட்ட கூடாரத்தின் நடுவே அவர்கள் அதை வைத்து, தேவனுடைய சந்நிதியில் சர்வாங்க தகனபலிகளையும் சமாதானபலிகளையும் செலுத்தினார்கள்.", "en": "So they brought the ark of God, and set it in the midst of the tent that David had pitched for it: and they offered burnt sacrifices and peace offerings before God."}, {"verse": 2, "start": 18.5, "end": 27.91, "ta": "தாவீது சர்வாங்க தகனபலிகளையும் சமாதானபலிகளையும் செலுத்தித் தீர்ந்தபின்பு, அவன் ஜனத்தைக் கர்த்தருடைய நாமத்திலே ஆசிர்வதித்து,", "en": "And when David had made an end of offering the burnt offerings and the peace offerings, he blessed the people in the name of the LORD ."}, {"verse": 3, "start": 27.91, "end": 41.8, "ta": "புருஷர் தொடங்கி ஸ்திரீகள்மட்டும், இஸ்ரவேலராகிய அனைவருக்கும் அவரவருக்கு ஒவ்வொரு அப்பத்தையும் ஒவ்வொரு இறைச்சித் துண்டையும், ஒவ்வொருபடி திராட்சரசத்தையும் பங்கிட்டுக் கொடுத்தான்.", "en": "And he dealt to every one of Israel, both man and woman, to every one a loaf of bread, and a good piece of flesh, and a flagon of wine ."}, {"verse": 4, "start": 41.8, "end": 53.41, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தரைப் பிரஸ்தாபம்பண்ணித் துதித்துப் புகழுகிறதற்கு கர்த்தருடைய பெட்டிக்கு முன்பாகச் சேவிக்கத்தக்க லேவியரில் சிலரை நியமித்தான்.", "en": "And he appointed certain of the Levites to minister before the ark of the LORD , and to record, and to thank and praise the LORD God of Israel:"}, {"verse": 5, "start": 53.41, "end": 73.63, "ta": "அவர்களில் ஆசாப் தலைவனும், சகரியா அவனுக்கு இரண்டாவதுமாயிருந்தான்; ஏயெல், செமிரமோத், யெகியேல், மத்தித்தியா, எலியாப், பெனாயா, ஓபேத்ஏதோம், ஏயெல் என்பவர்கள் தம்புரு சுரமண்டலம் என்னும் கீதவாத்தியங்களை வாசிக்கவும், ஆசாப் கைத்தாளங்களைக் கொட்டவும்,", "en": "Asaph the chief, and next to him Zechariah, Jeiel, and Shemiramoth, and Jehiel, and Mattithiah, and Eliab, and Benaiah, and Obed-edom: and Jeiel with psalteries and with harps; but Asaph made a sound with cymbals;"}, {"verse": 6, "start": 73.63, "end": 83.92, "ta": "பெனாயா, யாகாசியேல் என்னும் ஆசாரியர் எப்போதும் தேவனுடைய உடன்படிக்கைப் பெட்டிக்கு முன்பாகப் பூரிகைகளை ஊதவும் நியமிக்கப்பட்டார்கள்.", "en": "Benaiah also and Jahaziel the priests with trumpets continually before the ark of the covenant of God."}, {"verse": 7, "start": 83.92, "end": 93.62, "ta": "அப்படி ஆரம்பித்த அந்நாளிலேதானே கர்த்தருக்குத் துதியாகப் பாடும்படி தாவீது ஆசாப்பிடத்திலும் அவன் சகோதரரிடத்திலும் கொடுத்த சங்கீதமாவது:", "en": "Then on that day David delivered first this psalm to thank the LORD into the hand of Asaph and his brethren."}, {"verse": 8, "start": 93.62, "end": 103.54, "ta": "கர்த்தரைத் துதித்து, அவருடைய நாமத்தைப் பிரஸ்தாபமாக்குங்கள்; அவருடைய செய்கைகளை ஜனங்களுக்குள்ளே பிரசித்தப்படுத்துங்கள்.", "en": "Give thanks unto the LORD , call upon his name, make known his deeds among the people."}, {"verse": 9, "start": 103.54, "end": 110.75, "ta": "அவரைப் பாடி, அவரைக் கீர்த்தனம்பண்ணி அவருடைய அதிசயங்களையெல்லாம் தியானித்துப் பேசுங்கள்.", "en": "Sing unto him, sing psalms unto him, talk ye of all his wondrous works."}, {"verse": 10, "start": 110.75, "end": 119.27, "ta": "அவருடைய பரிசுத்த நாமத்தைக்குறித்து மேன்மைபாராட்டுங்கள்; கர்த்தரைத் தேடுகிறவர்களின் இருதயம் மகிழ்வதாக.", "en": "Glory ye in his holy name: let the heart of them rejoice that seek the LORD ."}, {"verse": 11, "start": 119.27, "end": 125.96, "ta": "கர்த்தரையும் அவர் வல்லமையையும் நாடுங்கள்; அவர் சமுகத்தை நித்தமும் தேடுங்கள்.", "en": "Seek the LORD and his strength, seek his face continually."}, {"verse": 12, "start": 125.96, "end": 132.94, "ta": "அவருடைய தாசனாகிய இஸ்ரவேலின் சந்ததியே! அவரால் தெரிந்துகொள்ளப்பட்டவர்களாகிய யாக்கோபின் புத்திரரே!", "en": "Remember his marvellous works that he hath done, his wonders, and the judgments of his mouth;"}, {"verse": 13, "start": 132.94, "end": 140.88, "ta": "அவர் செய்த அதிசயங்களையும் அற்புதங்களையும், அவர் வாக்கின் நியாயத்தீர்ப்புகளையும் நினைவுகூருங்கள்.", "en": "O ye seed of Israel his servant, ye children of Jacob, his chosen ones."}, {"verse": 14, "start": 140.88, "end": 148.09, "ta": "அவரே நம்முடைய தேவனாகிய கர்த்தர்; அவருடைய நியாயத்தீர்ப்புகள் பூமியெங்கும் விளங்கும்.", "en": "He is the LORD our God; his judgments are in all the earth."}, {"verse": 15, "start": 148.09, "end": 155.29, "ta": "ஆயிரந்தலைமுறைக்கென்று அவர் கட்டளையிட்ட வாக்கையும், ஆபிரகாமோடே அவர் பண்ணின உடன்படிக்கையையும்,", "en": "Be ye mindful always of his covenant; the word which he commanded to a thousand generations;"}, {"verse": 16, "start": 155.29, "end": 160.65, "ta": "அவர் ஈசாக்குக்கு இட்ட ஆணையையும் என்றென்றைக்கும் நினைத்திருங்கள்.", "en": "Even of the covenant which he made with Abraham, and of his oath unto Isaac;"}, {"verse": 17, "start": 160.65, "end": 167.42, "ta": "அதை யாக்கோபுக்குப் பிரமாணமாகவும், இஸ்ரவேலுக்கு நித்திய உடன்படிக்கையாகவும் உறுதிப்படுத்தி:", "en": "And hath confirmed the same to Jacob for a law, and to Israel for an everlasting covenant,"}, {"verse": 18, "start": 167.42, "end": 172.56, "ta": "உங்கள் சுதந்தரபாகமாக கானான் தேசத்தை உனக்குத் தருவேன் என்றார்.", "en": "Saying, Unto thee will I give the land of Canaan, the lot of your inheritance;"}, {"verse": 19, "start": 172.56, "end": 179.32, "ta": "அக்காலத்தில் அவர்கள் கொஞ்சத்தொகைக்குட்பட்ட சொற்பஜனங்களும் பரதேசிகளுமாயிருந்தார்கள்.", "en": "When ye were but few, even a few, and strangers in it."}, {"verse": 20, "start": 179.32, "end": 187.63, "ta": "அவர்கள் ஒரு ஜனத்தை விட்டு மறு ஜனத்தண்டைக்கும், ஒரு ராஜ்யத்தை விட்டு மறு தேசத்தாரண்டைக்கும் போனார்கள்.", "en": "And when they went from nation to nation, and from one kingdom to another people;"}, {"verse": 21, "start": 187.63, "end": 194.47, "ta": "அவர்களை யொடுக்கும்படி ஒருவருக்கும் இடங்கொடாமல், அவர்கள் நிமித்தம் ராஜாக்களை கடிந்துகொண்டு:", "en": "He suffered no man to do them wrong: yea, he reproved kings for their sakes,"}, {"verse": 22, "start": 194.47, "end": 203.51, "ta": "நான் அபிஷேகம்பண்ணினவர்களை நீங்கள் தொடாமலும், என்னுடைய தீர்க்கதரிசிகளுக்குத் தீங்குசெய்யாமலும் இருங்கள் என்றார்.", "en": "Saying , Touch not mine anointed, and do my prophets no harm."}, {"verse": 23, "start": 203.51, "end": 211.67, "ta": "பூமியின் சகல குடிகளே, கர்த்தரைப்பாடி, நாளுக்குநாள் அவருடைய ரட்சிப்பைச் சுவிசேஷமாய் அறிவியுங்கள்.", "en": "Sing unto the LORD , all the earth; shew forth from day to day his salvation."}, {"verse": 24, "start": 211.67, "end": 220.41, "ta": "ஜாதிகளுக்குள்ளும் அவருடைய மகிமையையும், சகல ஜனங்களுக்குள்ளும் அவருடைய அதிசயங்களையும் விவரித்துச்சொல்லுங்கள்.", "en": "Declare his glory among the heathen; his marvellous works among all nations."}, {"verse": 25, "start": 220.41, "end": 229.16, "ta": "கர்த்தர் பெரியவரும் மிகவும் துதிக்கப்படத்தக்கவருமாயிருக்கிறார்; எல்லா தேவர்களிலும் பயப்படத்தக்கவர் அவரே.", "en": "For great is the LORD , and greatly to be praised: he also is to be feared above all gods."}, {"verse": 26, "start": 229.16, "end": 235.92, "ta": "சகல ஜனங்களுடைய தேவர்களும் விக்கிரகங்கள்தானே; கர்த்தரோ வானங்களை உண்டாக்கினவர்.", "en": "For all the gods of the people are idols: but the LORD made the heavens."}, {"verse": 27, "start": 235.92, "end": 244.15, "ta": "மகிமையும் கனமும் அவர் சமுகத்தில் இருக்கிறது; வல்லமையும் மகிழ்ச்சியும் அவர் ஸ்தலத்தில் இருக்கிறது.", "en": "Glory and honour are in his presence; strength and gladness are in his place."}, {"verse": 28, "start": 244.15, "end": 253.34, "ta": "ஜனங்களின் வம்சங்களே, கர்த்தருக்கு மகிமையையும் வல்லமையையும் செலுத்துங்கள்; கர்த்தருக்கே அதைச் செலுத்துங்கள்.", "en": "Give unto the LORD , ye kindreds of the people, give unto the LORD glory and strength."}, {"verse": 29, "start": 253.34, "end": 267.53, "ta": "கர்த்தருக்கு அவருடைய நாமத்திற்குரிய மகிமையைச் செலுத்தி, காணிக்கைகளைக் கொண்டுவந்து, அவருடைய சந்நிதியில் பிரவேசியுங்கள்; பரிசுத்த அலங்காரத்துடனே கர்த்தரைத் தொழுதுகொள்ளுங்கள்.", "en": "Give unto the LORD the glory due unto his name: bring an offering, and come before him: worship the LORD in the beauty of holiness."}, {"verse": 30, "start": 267.53, "end": 277.23, "ta": "பூலோகத்தாரே, நீங்கள் யாவரும் அவருக்கு முன்பாக நடுங்குங்கள்; அவர் பூச்சக்கரத்தை அசையாதபடிக்கு உறுதிப்படுத்துகிறவர்.", "en": "Fear before him, all the earth: the world also shall be stable, that it be not moved."}, {"verse": 31, "start": 277.23, "end": 286.12, "ta": "வானங்கள் மகிழ்ந்து, பூமி பூரிப்பதாக; கர்த்தர் ராஜரிகம்பண்ணுகிறார் என்று ஜாதிகளுக்குள்ளே சொல்லப்படுவதாக.", "en": "Let the heavens be glad, and let the earth rejoice: and let men say among the nations, The LORD reigneth."}, {"verse": 32, "start": 286.12, "end": 292.3, "ta": "சமுத்திரமும் அதின் நிறைவும் முழங்கி, நாடும் அதிலுள்ள யாவும் களிகூருவதாக.", "en": "Let the sea roar, and the fulness thereof: let the fields rejoice, and all that is therein."}, {"verse": 33, "start": 292.3, "end": 301.27, "ta": "அப்பொழுது கர்த்தருக்கு முன்பாகக் காட்டுவிருட்சங்களும் கெம்பீரிக்கும்; அவர் பூமியை நியாயந்தீர்க்க வருகிறார்.", "en": "Then shall the trees of the wood sing out at the presence of the LORD , because he cometh to judge the earth."}, {"verse": 34, "start": 301.27, "end": 307.0, "ta": "கர்த்தரைத் துதியுங்கள், அவர் நல்லவர், அவர் கிருபை என்றுமுள்ளது.", "en": "O give thanks unto the LORD ; for he is good; for his mercy endureth for ever."}, {"verse": 35, "start": 307.0, "end": 324.49, "ta": "எங்கள் ரட்சிப்பின் தேவனே, நாங்கள் உமது பரிசுத்த நாமத்தைப் போற்றி, உம்மைத் துதிக்கிறதினால் மேன்மைபாராட்டும்படிக்கு, எங்களை ரட்சித்து, எங்களைச் சேர்த்துக்கொண்டு, ஜாதிகளுக்கு எங்களை நீங்கலாக்கியருளுமென்று சொல்லுங்கள்.", "en": "And say ye, Save us, O God of our salvation, and gather us together, and deliver us from the heathen, that we may give thanks to thy holy name, and glory in thy praise."}, {"verse": 36, "start": 324.49, "end": 335.59, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தருக்கு சதாகாலங்களிலும் ஸ்தோத்திரமுண்டாவதாக, அதற்கு ஜனங்களெல்லாரும் ஆமென் என்று சொல்லிக் கர்த்தரைத் துதித்தார்கள்.", "en": "Blessed be the LORD God of Israel for ever and ever. And all the people said, Amen, and praised the LORD ."}, {"verse": 37, "start": 335.59, "end": 353.08, "ta": "பின்பு பெட்டிக்கு முன்பாக நித்தம் அன்றாடக முறையாய்ச் சேவிக்கும்படி, அவன் அங்கே கர்த்தருடைய உடன்படிக்கைப் பெட்டிக்கு முன்பாக ஆசாப்பையும், அவன் சகோதரரையும், ஓபேத்ஏதோமையும், அவர்களுடைய சகோதரராகிய அறுபத்தெட்டுப்பேரையும் வைத்து,", "en": "So he left there before the ark of the covenant of the LORD Asaph and his brethren, to minister before the ark continually, as every day’s work required:"}, {"verse": 38, "start": 353.08, "end": 359.77, "ta": "எதித்தூனின் குமாரனாகிய இந்த ஓபேத்ஏதோமையும் ஓசாவையும் வாசல்காக்கிறவர்களாக வைத்தான்.", "en": "And Obed-edom with their brethren, threescore and eight; Obed-edom also the son of Jeduthun and Hosah to be porters:"}, {"verse": 39, "start": 359.77, "end": 379.55, "ta": "கிபியோனிலுள்ள மேட்டின் மேலிருக்கிற கர்த்தருடைய வாசஸ்தலத்திற்கு முன்பாக இருக்கிற சர்வாங்க தகனபலிபீடத்தின்மேல் சர்வாங்க தகனங்களை நித்தமும், அந்திசந்தியில் கர்த்தர் இஸ்ரவேலுக்குக் கற்பித்த நியாயப்பிரமாணத்தில் எழுதியிருக்கிறபடியெல்லாம் கர்த்தருக்குச் செலுத்துவதற்காக,", "en": "And Zadok the priest, and his brethren the priests, before the tabernacle of the LORD in the high place that was at Gibeon,"}, {"verse": 40, "start": 379.55, "end": 385.35, "ta": "அங்கே அவன் ஆசாரியனாகிய சாதோக்கையும், அவன் சகோதரராகிய ஆசாரியரையும் வைத்து,", "en": "To offer burnt offerings unto the LORD upon the altar of the burnt offering continually morning and evening, and to do according to all that is written in the law of the LORD , which he commanded Israel;"}, {"verse": 41, "start": 385.35, "end": 397.63, "ta": "இவர்களோடுங்கூட ஏமானையும், எதித்தூனையும், பேர்பேராகக் குறித்துத் தெரிந்துகொள்ளப்பட்ட மற்றச் சிலரையும் கர்த்தருடைய கிருபை என்றுமுள்ளது என்று அவரைத் துதிக்கவும்,", "en": "And with them Heman and Jeduthun, and the rest that were chosen, who were expressed by name, to give thanks to the LORD , because his mercy endureth for ever;"}, {"verse": 42, "start": 397.63, "end": 412.77, "ta": "பூரிகைகளையும் கைத்தாளங்களையும் தேவனைப் பாடுகிறதற்குரிய கீதவாத்தியங்களையும் தொனிக்கச்செய்யவும் அவர்களுடன் ஏமானையும் எதித்தூனையும் வைத்து, எதித்தூனின் குமாரரை வாசல்காக்கிறவர்களாகக் கட்டளையிட்டான்.", "en": "And with them Heman and Jeduthun with trumpets and cymbals for those that should make a sound, and with musical instruments of God. And the sons of Jeduthun were porters."}, {"verse": 43, "start": 412.77, "end": 422.03, "ta": "பின்பு ஜனங்கள் எல்லாரும் அவரவர் தங்கள் வீட்டிற்குப் போனார்கள்; தாவீதும் தன் வீட்டாரை ஆசீர்வதிக்கத்திரும்பினான்.", "en": "And all the people departed every man to his house: and David returned to bless his house."}]}, "17": {"chapter": 17, "duration": 360.19, "audio_url": "audio_ot/OT13_17.mp3", "total_verses": 27, "verses": [{"verse": 1, "start": 3.8, "end": 19.8, "ta": "தாவீது தன் வீட்டிலே வாசமாயிருக்கிறபோது, அவன் தீர்க்கதரிசியாகிய நாத்தானை நோக்கி: பாரும், நான் கேதுருமரவீட்டிலே வாசம்பண்ணுகிறேன்; கர்த்தருடைய உடன்படிக்கைப் பெட்டியோ திரைகளின்கீழ் இருக்கிறது என்றான்.", "en": "Now it came to pass, as David sat in his house, that David said to Nathan the prophet, Lo, I dwell in an house of cedars, but the ark of the covenant of the LORD remaineth under curtains."}, {"verse": 2, "start": 19.8, "end": 29.6, "ta": "அப்பொழுது நாத்தான் தாவீதை நோக்கி: உம்முடைய இருதயத்தில் இருக்கிறதையெல்லாம் செய்யும்; தேவன் உம்மோடு இருக்கிறார் என்றான்.", "en": "Then Nathan said unto David, Do all that is in thine heart; for God is with thee."}, {"verse": 3, "start": 29.6, "end": 34.84, "ta": "அன்று ராத்திரியிலே, தேவனுடைய வார்த்தை நாத்தானுக்கு உண்டாகி, அவர்:", "en": "And it came to pass the same night, that the word of God came to Nathan, saying,"}, {"verse": 4, "start": 34.84, "end": 44.79, "ta": "நீ போய், என் தாசனாகிய தாவீதை நோக்கி: கர்த்தர் சொல்லுகிறது என்னவென்றால்: நான் வாசமாயிருக்க நீ எனக்கு ஆலயத்தைக் கட்டவேண்டாம்.", "en": "Go and tell David my servant, Thus saith the LORD , Thou shalt not build me an house to dwell in:"}, {"verse": 5, "start": 44.79, "end": 59.75, "ta": "நான் இஸ்ரவேலை வரப்பண்ணின நாள்முதற்கொண்டு இந்நாள்வரைக்கும் நான் ஒரு ஆலயத்திலே வாசம்பண்ணாமல், ஒரு கூடாரத்திலிருந்து மறு கூடாரத்துக்கும், ஒரு வாசஸ்தலத்திலிருந்து மறு வாசஸ்தலத்துக்கும் போனேன்.", "en": "For I have not dwelt in an house since the day that I brought up Israel unto this day; but have gone from tent to tent, and from one tabernacle to another ."}, {"verse": 6, "start": 59.75, "end": 78.77, "ta": "நான் சகல இஸ்ரவேலோடும் உலாவி வந்த எவ்விடத்திலாகிலும், நான் என் ஜனத்தை மேய்க்கக் கற்பித்த இஸ்ரவேலின் நியாயாதிபதிகளில் யாதொருவனை நோக்கி: நீங்கள் எனக்குக் கேதுருமரத்தால் செய்யப்பட்ட ஆலயத்தைக் கட்டாதிருக்கிறது என்ன என்று யாதொரு வார்த்தை சொன்னது உண்டோ?", "en": "Wheresoever I have walked with all Israel, spake I a word to any of the judges of Israel, whom I commanded to feed my people, saying, Why have ye not built me an house of cedars?"}, {"verse": 7, "start": 78.77, "end": 93.89, "ta": "இப்போதும், நீ என் தாசனாகிய தாவீதை நோக்கி: சேனைகளின் கர்த்தர் சொல்லுகிறது என்னவென்றால்: நீ என் ஜனமாகிய இஸ்ரவேலின்மேல் அதிபதியாயிருக்கும்படி, ஆடுகளின் பின்னே நடந்த உன்னை ஆட்டுமந்தையை விட்டு எடுத்து,", "en": "Now therefore thus shalt thou say unto my servant David, Thus saith the LORD of hosts, I took thee from the sheepcote, even from following the sheep, that thou shouldest be ruler over my people Israel:"}, {"verse": 8, "start": 93.89, "end": 107.23, "ta": "நீ போன இடமெல்லாம் உன்னோடே இருந்து, உன் சத்துருக்களையெல்லாம் உனக்கு முன்பாக நிர்மூலமாக்கி, பூமியிலிருக்கிற பெரியோர்களின் நாமத்திற்கு ஒத்த நாமத்தை உனக்கு உண்டாக்கினேன்.", "en": "And I have been with thee whithersoever thou hast walked, and have cut off all thine enemies from before thee, and have made thee a name like the name of the great men that are in the earth."}, {"verse": 9, "start": 107.23, "end": 131.19, "ta": "நான் என் ஜனமாகிய இஸ்ரவேலுக்கு ஒரு இடத்தையும் ஏற்படுத்தி, அவர்கள் தங்கள் ஸ்தானத்திலே குடியிருக்கவும், இனி அவர்கள் அலையாமலும், முன்போலும், நான் என் ஜனமாகிய இஸ்ரவேலின்மேல் நியாயாதிபதிகளைக் கட்டளையிட்ட நாள்முதல் நடந்ததுபோலும், நியாயக்கேட்டின் மக்களால் இனிச் சிறுமைப்படாமலும் இருக்கவும் அவர்களை நாட்டினேன்.", "en": "Also I will ordain a place for my people Israel, and will plant them, and they shall dwell in their place, and shall be moved no more; neither shall the children of wickedness waste them any more, as at the beginning,"}, {"verse": 10, "start": 131.19, "end": 141.44, "ta": "உன் சத்துருக்களையெல்லாம் கீழ்ப்படுத்தினேன். இப்போதும் கர்த்தர் உனக்கு ஒரு வீட்டைக் கட்டுவார் என்பதை உனக்கு அறிவிக்கிறேன்.", "en": "And since the time that I commanded judges to be over my people Israel. Moreover I will subdue all thine enemies. Furthermore I tell thee that the LORD will build thee an house."}, {"verse": 11, "start": 141.44, "end": 154.85, "ta": "நீ உன் பிதாக்களிடத்திலே போக, உன் நாட்கள் நிறைவேறும்போது, நான் உனக்குப்பின்பு உன் புத்திரரில் ஒருவனாகிய உன் சந்ததியை எழும்பப்பண்ணி, அவன் ராஜ்யத்தை நிலைப்படுத்துவேன்.", "en": "And it shall come to pass, when thy days be expired that thou must go to be with thy fathers, that I will raise up thy seed after thee, which shall be of thy sons; and I will establish his kingdom."}, {"verse": 12, "start": 154.85, "end": 162.3, "ta": "அவன் எனக்கு ஒரு ஆலயத்தைக் கட்டுவான்; அவன் சிங்காசனத்தை என்றைக்கும் நிலைக்கப்பண்ணுவேன்.", "en": "He shall build me an house, and I will stablish his throne for ever."}, {"verse": 13, "start": 162.3, "end": 175.2, "ta": "நான் அவனுக்குப் பிதாவாயிருப்பேன், அவன் எனக்குக் குமாரனாயிருப்பான்; உனக்கு முன் இருந்தவனை விட்டு என் கிருபையை நான் விலகப்பண்ணினதுபோல, அவனை விட்டு விலகப்பண்ணாமல்,", "en": "I will be his father, and he shall be my son: and I will not take my mercy away from him, as I took it from him that was before thee:"}, {"verse": 14, "start": 175.2, "end": 187.07, "ta": "அவனை என் ஆலயத்திலும் என் ராஜ்யத்திலும் என்றென்றைக்கும் நிலைக்கப்பண்ணுவேன்; அவனுடைய ராஜாசனம் என்றென்றைக்கும் நிலைபெற்றிருக்கும் என்று சொல் என்றார்.", "en": "But I will settle him in mine house and in my kingdom for ever: and his throne shall be established for evermore."}, {"verse": 15, "start": 187.07, "end": 194.74, "ta": "நாத்தான் இந்த எல்லா வார்த்தைகளின்படியும் இந்த எல்லாத் தரிசனத்தின்படியும் தாவீதுக்குச் சொன்னான்.", "en": "According to all these words, and according to all this vision, so did Nathan speak unto David."}, {"verse": 16, "start": 194.74, "end": 209.26, "ta": "அப்பொழுது தாவீதுராஜா உட்பிரவேசித்து, கர்த்தருடைய சமுகத்திலிருந்து: தேவனாகிய கர்த்தாவே, தேவரீர் என்னை இதுவரைக்கும் கொண்டுவந்ததற்கு நான் எம்மாத்திரம்? என் வீடும் எம்மாத்திரம்?", "en": "And David the king came and sat before the LORD , and said, Who am I, O LORD God, and what is mine house, that thou hast brought me hitherto?"}, {"verse": 17, "start": 209.26, "end": 227.98, "ta": "தேவனே, இது இன்னும் உம்முடைய பார்வைக்குக் கொஞ்சக்காரியமாயிருக்கிறது என்று தேவனான கர்த்தராயிருக்கிற நீர் உமது அடியானுடைய வீட்டைக்குறித்து வெகுதூரமாயிருக்கும் காலத்துச் செய்தியையும் சொல்லி, என்னை மகா மேன்மையான சந்ததியின் மனுஷனாகப் பார்த்தீர்.", "en": "And yet this was a small thing in thine eyes, O God; for thou hast also spoken of thy servant’s house for a great while to come, and hast regarded me according to the estate of a man of high degree, O LORD God."}, {"verse": 18, "start": 227.98, "end": 237.57, "ta": "உமது அடியானுக்கு உண்டாகும் கனத்தைப்பற்றி, தாவீது அப்புறம் உம்மோடே சொல்வது என்ன? தேவரீர் உமது அடியானை அறிவீர்.", "en": "What can David speak more to thee for the honour of thy servant? for thou knowest thy servant."}, {"verse": 19, "start": 237.57, "end": 250.76, "ta": "கர்த்தாவே, உமது அடியானின் நிமித்தமும், உமது இருதயத்தின்படியும், இந்தப் பெரிய காரியங்களையெல்லாம் அறியப்பண்ணும்படிக்கு, இந்தப் பெரிய காரியத்தையெல்லாம் செய்தீர்.", "en": "O LORD , for thy servant’s sake, and according to thine own heart, hast thou done all this greatness, in making known all these great things."}, {"verse": 20, "start": 250.76, "end": 261.08, "ta": "கர்த்தாவே, நாங்கள் எங்கள் காதுகளால் கேட்ட எல்லாவற்றின்படியும் தேவரீருக்கு நிகரானவர் இல்லை; உம்மைத்தவிர வேறே தேவனும் இல்லை.", "en": "O LORD , there is none like thee, neither is there any God beside thee, according to all that we have heard with our ears."}, {"verse": 21, "start": 261.08, "end": 281.06, "ta": "உமது ஜனமாகிய இஸ்ரவேலுக்கு நிகரான ஜனமும் உண்டோ? பூலோகத்தில் இந்த ஒரே ஜாதியை தேவனாகிய நீர் உமக்கு ஜனமாக மீட்கும்படி, பயங்கரமான பெரிய காரியங்களினால் உமக்குக் கீர்த்தியை உண்டாக்கி, நீர் எகிப்திற்கு நீங்கலாக்கி மீட்ட உமது ஜனத்திற்குமுன்பாக ஜாதிகளைத் துரத்தி,", "en": "And what one nation in the earth is like thy people Israel, whom God went to redeem to be his own people, to make thee a name of greatness and terribleness, by driving out nations from before thy people, whom thou hast redeemed out of Egypt?"}, {"verse": 22, "start": 281.06, "end": 291.01, "ta": "உமது ஜனமாகிய இஸ்ரவேலர் என்றைக்கும் உமது ஜனமாயிருப்பதற்கு அவர்களை நிலைப்படுத்தி, கர்த்தராகிய நீர்தாமே அவர்களுக்கு தேவனானீர்.", "en": "For thy people Israel didst thou make thine own people for ever; and thou, LORD , becamest their God."}, {"verse": 23, "start": 291.01, "end": 303.62, "ta": "இப்போதும் கர்த்தாவே, தேவரீர் அடியானையும் அவன் வீட்டையும் குறித்துச் சொன்ன வார்த்தை என்றென்றைக்கும் நிலைவரப்பட்டிருப்பதாக; தேவரீர் சொன்னபடியே செய்தருளும்.", "en": "Therefore now, LORD , let the thing that thou hast spoken concerning thy servant and concerning his house be established for ever, and do as thou hast said."}, {"verse": 24, "start": 303.62, "end": 321.46, "ta": "ஆம், அது நிலைவரப்பட்டிருக்கவும், இஸ்ரவேலின் தேவனாகிய சேனைகளின் கர்த்தர் இஸ்ரவேலுக்கு தேவன் என்றும் உமது அடியானாகிய தாவீதின் வீடு உமக்கு முன்பாக, திடமானதென்றும் சொல்லப்படுவதினால், உமது நாமம் என்றைக்கும் மகிமைப்படவும்கடவது.", "en": "Let it even be established, that thy name may be magnified for ever, saying, The LORD of hosts is the God of Israel, even a God to Israel: and let the house of David thy servant be established before thee."}, {"verse": 25, "start": 321.46, "end": 334.66, "ta": "உனக்கு வீடு கட்டுவேன் என்று என் தேவனாகிய நீர் உமது அடியான் செவிகேட்க வெளிப்படுத்தினீர்; ஆகையால் உமக்கு முன்பாக விண்ணப்பம்பண்ண, அடியானுக்கு மனத்தைரியம் கிடைத்தது.", "en": "For thou, O my God, hast told thy servant that thou wilt build him an house: therefore thy servant hath found in his heart to pray before thee."}, {"verse": 26, "start": 334.66, "end": 342.77, "ta": "இப்போதும் கர்த்தாவே, நீரே தேவன்; நீர் உமது அடியானைக்குறித்து இந்த நல்ல விசேஷத்தைச் சொன்னீர்.", "en": "And now, LORD , thou art God, and hast promised this goodness unto thy servant:"}, {"verse": 27, "start": 342.77, "end": 358.69, "ta": "இப்போதும் உமது அடியானின் வீடு என்றைக்கும் உமக்கு முன்பாக இருக்கும்படிக்கு, அதை ஆசிர்வதித்தருளினீர்; கர்த்தராகிய தேவரீர் அதை ஆர்வதித்தபடியினால், அது என்றைக்கும் ஆசீர்வதிக்கப்பட்டிருக்கும் என்றான்.", "en": "Now therefore let it please thee to bless the house of thy servant, that it may be before thee for ever: for thou blessest, O LORD , and it shall be blessed for ever."}]}, "18": {"chapter": 18, "duration": 216.73, "audio_url": "audio_ot/OT13_18.mp3", "total_verses": 17, "verses": [{"verse": 1, "start": 3.8, "end": 17.11, "ta": "இதற்குப்பின்பு, தாவீது பெலிஸ்தரை முறிய அடித்து, அவர்களைக் கீழ்ப்படுத்தி, காத்பட்டணத்தையும் அதின் கிராமங்களையும் பெலிஸ்தரின் கையிலிருந்து பிடித்துக்கொண்டான்.", "en": "Now after this it came to pass, that David smote the Philistines, and subdued them, and took Gath and her towns out of the hand of the Philistines."}, {"verse": 2, "start": 17.11, "end": 26.14, "ta": "அவன் மோவாபியரையும் முறியடித்ததினால், மோவாபியர் தாவீதைச் சேவித்து அவனுக்குக் காணிக்கைகளைச் செலுத்தினார்கள்.", "en": "And he smote Moab; and the Moabites became David’s servants, and brought gifts."}, {"verse": 3, "start": 26.14, "end": 37.24, "ta": "சோபாவின் ராஜாவாகிய ஆதாரேசர் ஐபிராத் நதியண்டையில் தன் இராணுவத்தை நிறுத்தப்போகிறபோது, தாவீது அவனையும் ஆமாத்தின் கிட்டே முறிய அடித்தான்.", "en": "And David smote Hadarezer king of Zobah unto Hamath, as he went to stablish his dominion by the river Euphrates."}, {"verse": 4, "start": 37.24, "end": 51.86, "ta": "அவனுக்கு இருந்த ஆயிரம் இரதங்களையும் ஆயிரம் குதிரைவீரரையும் பதினாயிரம் காலாட்களையும் பிடித்து, இரதங்களில் நூறு இரதங்களையும் வைத்துக்கொண்டு, மற்றவைகளையெல்லாம் துண்டாடிப்போட்டான்.", "en": "And David took from him a thousand chariots, and seven thousand horsemen, and twenty thousand footmen: David also houghed all the chariot horses , but reserved of them an hundred chariots."}, {"verse": 5, "start": 51.86, "end": 62.87, "ta": "சோபாவின் ராஜாவாகிய ஆதாரேசருக்கு உதவிசெய்ய தமஸ்குபட்டணத்தாராகிய சீரியர் வந்தார்கள்; தாவீது சீரியரில் இருபத்தீராயிரம்பேரை வெட்டிப்போட்டு,", "en": "And when the Syrians of Damascus came to help Hadarezer king of Zobah, David slew of the Syrians two and twenty thousand men."}, {"verse": 6, "start": 62.87, "end": 77.8, "ta": "தமஸ்குவுக்கடுத்த சீரியாவிலே தாணையங்களை வைத்தான்; சீரியர் தாவீதைச் சேவித்து அவனுக்குக் காணிக்கைகளைச் செலுத்தினார்கள்; தாவீது போன இடத்திலெல்லாம் கர்த்தர் அவனைக் காப்பாற்றினார்.", "en": "Then David put garrisons in Syria-damascus; and the Syrians became David’s servants, and brought gifts. Thus the LORD preserved David whithersoever he went."}, {"verse": 7, "start": 77.8, "end": 86.14, "ta": "ஆதாரேசரின் சேவகருக்கு இருந்த பொன் பரிசைகளைத் தாவீது எடுத்து, அவைகளை எருசலேமுக்குக் கொண்டுவந்தான்.", "en": "And David took the shields of gold that were on the servants of Hadarezer, and brought them to Jerusalem."}, {"verse": 8, "start": 86.14, "end": 103.35, "ta": "ஆதாரேசரின் பட்டணங்களாகிய திப்காத்திலும் கூனிலுமிருந்து தாவீது வெகு திரளான வெண்கலத்தையும் எடுத்துக்கொண்டுவந்தான்; அதினாலே சாலொமோன் வெண்கலக் கடல்தொட்டியையும் தூண்களையும் வெண்கலத் தட்டுமுட்டுகளையும் உண்டாக்கினான்.", "en": "Likewise from Tibhath, and from Chun, cities of Hadarezer, brought David very much brass, wherewith Solomon made the brasen sea, and the pillars, and the vessels of brass."}, {"verse": 9, "start": 103.35, "end": 112.23, "ta": "தாவீது சோபாவின் ராஜாவாகிய ஆதாரேசரின் இராணுவத்தையெல்லாம் முறிய அடித்த செய்தியை ஆமாத்தின் ராஜாவாகிய தோயூ கேட்டபோது,", "en": "Now when Tou king of Hamath heard how David had smitten all the host of Hadarezer king of Zobah;"}, {"verse": 10, "start": 112.23, "end": 137.33, "ta": "அவன் தாவீது ராஜாவின் சுகசெய்தியை விசாரிக்கவும், அவன் ஆதாரேசரோடு யுத்தம்பண்ணி, அவனை முறிய அடித்ததற்காக அவனுக்கு வினவுதல் சொல்லவும், தன் குமாரனாகிய அதோராமையும், பொன்னும் வெள்ளியும் வெண்கலமுமான சகலவிதத் தட்டுமுட்டுகளையும், அவனிடத்Τுக்கு அனுப்பினான்; ஆதாரேசர் தோயூவின்மேல் யுத்தம்பண்ணுகிறவனாயிருந்தான்.", "en": "He sent Hadoram his son to king David, to enquire of his welfare, and to congratulate him, because he had fought against Hadarezer, and smitten him; (for Hadarezer had war with Tou;) and with him all manner of vessels of gold and silver and brass."}, {"verse": 11, "start": 137.33, "end": 156.38, "ta": "அந்தத் தட்டுமுட்டுகளையும், தான் ஏதோமியர், மோவாபியர், அம்மோன் புத்திரர், பெலிஸ்தர், அமலேக்கியர் என்னும் சகல ஜாதிகளின் கையிலும் வாங்கின வெள்ளியையும், பொன்னையும்கூடத் தாவீதுராஜா கர்த்தருக்குப் பரிசுத்தமென்று நேர்ந்துகொண்டான்.", "en": "Them also king David dedicated unto the LORD , with the silver and the gold that he brought from all these nations; from Edom, and from Moab, and from the children of Ammon, and from the Philistines, and from Amalek."}, {"verse": 12, "start": 156.38, "end": 163.96, "ta": "செருயாவின் குமாரன் அபிசாயி உப்புப் பள்ளத்தாக்கிலே பதினெண்ணாயிரம் ஏதோமியரை முறிய அடித்தான்.", "en": "Moreover Abishai the son of Zeruiah slew of the Edomites in the valley of salt eighteen thousand."}, {"verse": 13, "start": 163.96, "end": 176.89, "ta": "ஆகையால் தாவீது ஏதோமிலே தாணையம் போட்டான்; ஏதோமியர் எல்லாரும் அவனைச் சேவிக்கிறவர்களானார்கள்; தாவீது போன இடத்திலெல்லாம் கர்த்தர் அவனைக் காப்பாற்றினார்.", "en": "And he put garrisons in Edom; and all the Edomites became David’s servants. Thus the LORD preserved David whithersoever he went."}, {"verse": 14, "start": 176.89, "end": 184.32, "ta": "தாவீது இஸ்ரவேலையெல்லாம் ஆண்டு, தன்னுடைய ஜனத்திற்கெல்லாம் நியாயமும் நீதியும் செய்தான்.", "en": "So David reigned over all Israel, and executed judgment and justice among all his people."}, {"verse": 15, "start": 184.32, "end": 193.27, "ta": "செருயாவின் குமாரன் யோவாப் இராணுவத்தலைவனாயிருந்தான்; ஆகிலுூதின் குமாரனாகிய யோசபாத் மந்திரியாயிருந்தான்.", "en": "And Joab the son of Zeruiah was over the host; and Jehoshaphat the son of Ahilud, recorder."}, {"verse": 16, "start": 193.27, "end": 203.45, "ta": "அகிதூபின் குமாரன் சாதோக்கும், அபியத்தாரின் குமாரன் அபிமெலேக்கும் ஆசாரியராயிருந்தார்கள்; சவிஷா சம்பிரதியாயிருந்தான்.", "en": "And Zadok the son of Ahitub, and Abimelech the son of Abiathar, were the priests; and Shavsha was scribe;"}, {"verse": 17, "start": 203.45, "end": 215.23, "ta": "யோய்தாவின் குமாரன் பெனாயா கிரேத்தியருக்கும் பிலேத்தியருக்கும் தலைவனாயிருந்தான்; தாவீதின் புத்திரர் ராஜாவினிடத்தில் பிரதானிகளாயிருந்தார்கள்.", "en": "And Benaiah the son of Jehoiada was over the Cherethites and the Pelethites; and the sons of David were chief about the king."}]}, "19": {"chapter": 19, "duration": 283.88, "audio_url": "audio_ot/OT13_19.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 11.99, "ta": "அதன்பின்பு, அம்மோன் புத்திரரின் ராஜாவாகிய நாகாஸ் மரித்து, அவன் குமாரன் அவன் ஸ்தானத்தில் ராஜாவானான்.", "en": "Now it came to pass after this, that Nahash the king of the children of Ammon died, and his son reigned in his stead."}, {"verse": 2, "start": 11.99, "end": 33.04, "ta": "அப்பொழுது தாவீது: ஆனூனின் தகப்பனாகிய நாகாஸ் எனக்குத் தயவுசெய்ததுபோல, நானும் அவன் குமாரனாகிய இவனுக்குத் தயவுசெய்வேன் என்று சொல்லி, அவன் தகப்பனுக்காக அவனுக்கு ஆறுதல்சொல்ல ஸ்தானாபதிகளை அனுப்பினான்; தாவீதின் ஊழியக்காரர் ஆனூனுக்கு ஆறுதல் சொல்ல அம்மோன் புத்திரரின் தேசத்திலே வந்தபோது,", "en": "And David said, I will shew kindness unto Hanun the son of Nahash, because his father shewed kindness to me. And David sent messengers to comfort him concerning his father. So the servants of David came into the land of the children of Ammon to Hanun, to comfort him."}, {"verse": 3, "start": 33.04, "end": 55.95, "ta": "அம்மோன் புத்திரரின் பிரபுக்கள் ஆனூனைப் பார்த்து: தாவீது ஆறுதல் சொல்லுகிறவர்களை உம்மிடத்தில் அனுப்பினது, உம்முடைய தகப்பனைக் கனம்பண்ணுகிறதாய் உமக்குத் தோன்றுகிறதோ? தேசத்தை ஆராயவும், அதைக் கவிழ்த்துப்போடவும், உளவுபார்க்கவும் அல்லவோ, அவன் ஊழியக்காரர் உம்மிடத்தில் வந்தார்கள் என்று சொன்னார்கள்.", "en": "But the princes of the children of Ammon said to Hanun, Thinkest thou that David doth honour thy father, that he hath sent comforters unto thee? are not his servants come unto thee for to search, and to overthrow, and to spy out the land?"}, {"verse": 4, "start": 55.95, "end": 71.11, "ta": "அப்பொழுது ஆனூன்: தாவீதின் ஊழியக்காரரைப் பிடித்து, அவர்கள் தாடியைச் சிரைத்து, அவர்களுடைய வஸ்திரங்களை இருப்பிடமட்டும் வைத்துவிட்டு, மற்றப் பாதியைக் கத்தரித்துப்போட்டு, அவர்களை அனுப்பிவிட்டான்.", "en": "Wherefore Hanun took David’s servants, and shaved them, and cut off their garments in the midst hard by their buttocks, and sent them away."}, {"verse": 5, "start": 71.11, "end": 90.43, "ta": "அந்த மனுஷர் வருகையில், அவர்கள் செய்தி தாவீதுக்கு அறிவிக்கப்பட்டது; அப்பொழுது அந்த மனுஷர் மிகவும் வெட்கப்பட்டபடியினால், அவர்களுக்கு எதிராக ராஜா ஆட்களை அனுப்பி: உங்கள் தாடி வளருமட்டும் நீங்கள் எரிகோவிலிருந்து பிற்பாடு வாருங்கள் என்று சொல்லச்சொன்னான்.", "en": "Then there went certain , and told David how the men were served. And he sent to meet them: for the men were greatly ashamed. And the king said, Tarry at Jericho until your beards be grown, and then return."}, {"verse": 6, "start": 90.43, "end": 108.9, "ta": "அம்மோன் புத்திரர் தாங்கள் தாவீதுக்கு அருவருப்பானதைக் கண்டபோது, ஆனூனும் அம்மோன் புத்திரரும் மெசொப்பொத்தாமியாவிலும் மாக்கா சோபா என்னும் சீரியரின் தேசத்திலுமிருந்து தங்களுக்கு இரதங்களும் குதிரைவீரரும் கூலிக்கு வரும்படி ஆயிரம்தாலந்து வெள்ளியையும் அனுப்பி,", "en": "And when the children of Ammon saw that they had made themselves odious to David, Hanun and the children of Ammon sent a thousand talents of silver to hire them chariots and horsemen out of Mesopotamia, and out of Syria-maachah, and out of Zobah."}, {"verse": 7, "start": 108.9, "end": 128.44, "ta": "முப்பத்தீராயிரம் இரதங்களையும், மாக்காவின் ராஜாவையும், அவன் ஜனத்தையும் கூலிப்படையாக அழைப்பித்தான்; இவர்கள் வந்து, மேதேபாவுக்கு முன்புறத்திலே பாளயமிறங்கினார்கள்; அம்மோன் புத்திரரும் தங்கள் பட்டணங்களிலிருந்து கூடிக்கொண்டு யுத்தம்பண்ண வந்தார்கள்.", "en": "So they hired thirty and two thousand chariots, and the king of Maachah and his people; who came and pitched before Medeba. And the children of Ammon gathered themselves together from their cities, and came to battle."}, {"verse": 8, "start": 128.44, "end": 135.04, "ta": "அதைத் தாவீது கேட்டபோது, யோவாபையும் பலசாலிகளின் இராணுவம் முழுவதையும் அனுப்பினான்.", "en": "And when David heard of it , he sent Joab, and all the host of the mighty men."}, {"verse": 9, "start": 135.04, "end": 146.25, "ta": "அம்மோன் புத்திரர் புறப்பட்டுவந்து, பட்டணத்து வாசலண்டையில் அணிவகுத்தார்கள்; வந்த ராஜாக்கள் தனித்து வெளியிலே போருக்கு ஆயத்தமாய் நின்றார்கள்.", "en": "And the children of Ammon came out, and put the battle in array before the gate of the city: and the kings that were come were by themselves in the field."}, {"verse": 10, "start": 146.25, "end": 160.47, "ta": "யுத்த இராணுவங்களின் முகப்புத் தனக்கு முன்னும் பின்னும் இருக்கிறதை யோவாப் கண்டு, அவன் இஸ்ரவேலிலே தெரிந்துகொள்ளப்பட்ட அனைவரிலும் ஒரு பங்கைப் பிரித்தெடுத்து, அதைச் சீரியருக்கு எதிராக நிறுத்தி,", "en": "Now when Joab saw that the battle was set against him before and behind, he chose out of all the choice of Israel, and put them in array against the Syrians."}, {"verse": 11, "start": 160.47, "end": 169.53, "ta": "மற்ற ஜனத்தை அம்மோன் புத்திரருக்கு எதிராகப் போருக்கு ஆயத்தப்படுத்தி, தன் சகோதரனாகிய அபிசாயிக்கு ஒப்புவித்து, அவனை நோக்கி:", "en": "And the rest of the people he delivered unto the hand of Abishai his brother, and they set themselves in array against the children of Ammon."}, {"verse": 12, "start": 169.53, "end": 180.73, "ta": "என்னைப்பார்க்கிலும் சீரியர் பலங்கொண்டால் நீ எனக்குத் துணைநில்; உன்னைப்பார்க்கிலும் அம்மோன் புத்திரர் பலங்கொண்டால் நான் உனக்குத் துணைநிற்பேன்.", "en": "And he said, If the Syrians be too strong for me, then thou shalt help me: but if the children of Ammon be too strong for thee, then I will help thee."}, {"verse": 13, "start": 180.73, "end": 193.73, "ta": "தைரியமாயிரு; நாம் நம்முடைய ஜனத்திற்காகவும், நமது தேவனுடைய பட்டணங்களுக்காகவும் திடன்கொண்டிருக்கக்கடவோம்; கர்த்தர் தமது பார்வைக்கு நலமானதைச் செய்வாராக என்றான்.", "en": "Be of good courage, and let us behave ourselves valiantly for our people, and for the cities of our God: and let the LORD do that which is good in his sight."}, {"verse": 14, "start": 193.73, "end": 203.22, "ta": "பின்பு யோவாபும் அவனோடிருந்த ஜனமும் சீரியரோடு யுத்தம்பண்ணச் சேர்ந்தார்கள்; அவர்கள் அவனுக்கு முன்பாக முறிந்தோடினார்கள்.", "en": "So Joab and the people that were with him drew nigh before the Syrians unto the battle; and they fled before him."}, {"verse": 15, "start": 203.22, "end": 217.15, "ta": "சீரியர் முறிந்தோடுகிறதை அம்மோன் புத்திரர் கண்டபோது, அவர்களும் அவன் சகோதரனாகிய அபிசாயிக்கு முன்பாக முறிந்தோடிப் பட்டணத்திற்கு உட்பட்டார்கள்; யோவாப் திரும்ப எருசலேமுக்கு வந்தான்.", "en": "And when the children of Ammon saw that the Syrians were fled, they likewise fled before Abishai his brother, and entered into the city. Then Joab came to Jerusalem."}, {"verse": 16, "start": 217.15, "end": 232.17, "ta": "தாங்கள் இஸ்ரவேலுக்கு முன்பாக முறிய அடிக்கப்பட்டதைக் கண்டபோது, அவர்கள் நதிக்கு அப்புறத்திலிருக்கிற சீரியரை வரவழைத்தார்கள்; ஆதாரேசரின் படைத்தலைவனாகிய சோப்பாக் அவர்களுக்கு முன்னாலே நடந்துபோனான்.", "en": "And when the Syrians saw that they were put to the worse before Israel, they sent messengers, and drew forth the Syrians that were beyond the river: and Shophach the captain of the host of Hadarezer went before them."}, {"verse": 17, "start": 232.17, "end": 252.86, "ta": "அது தாவீதுக்கு அறிவிக்கப்பட்டது, அவன் இஸ்ரவேலைக் கூட்டிக்கொண்டு, யோர்தானைக் கடந்து, அவர்களுக்குச் சமீபமாய் வந்தபோது, அவர்களுக்கு எதிராக இராணுவங்களை நிறுத்தினார்கள்; தாவீது சீரியருக்கு எதிராக இராணுவங்களைப் போருக்கு ஆயத்தப்படுத்தினபின் அவனோடு யுத்தம்பண்ணினார்கள்.", "en": "And it was told David; and he gathered all Israel, and passed over Jordan, and came upon them, and set the battle in array against them. So when David had put the battle in array against the Syrians, they fought with him."}, {"verse": 18, "start": 252.86, "end": 266.65, "ta": "சீரியர் இஸ்ரவேலுக்கு முன்பாக முறிந்தோடினார்கள்; தாவீது சீரியரிலே ஆயிரம் இரதங்களின் மனுஷரையும், நாற்பதினாயிரம் காலாட்களையும் கொன்று, படைத்தலைவனாகிய சோப்பாக்கையும் கொன்றான்.", "en": "But the Syrians fled before Israel; and David slew of the Syrians seven thousand men which fought in chariots, and forty thousand footmen, and killed Shophach the captain of the host."}, {"verse": 19, "start": 266.65, "end": 282.38, "ta": "தாங்கள் இஸ்ரவேலுக்கு முன்பாகமுறிய அடிக்கப்பட்டதை ஆதாரேசரின் சேவகர் கண்டபோது அவர்கள் தாவீதோடே சமாதானம்பண்ணி, அவனைச் சேவித்தார்கள்; அப்புறம் அம்மோன் புத்திரருக்கு உதவிசெய்ய சீரியர் மனதில்லாதிருந்தார்கள்.", "en": "And when the servants of Hadarezer saw that they were put to the worse before Israel, they made peace with David, and became his servants: neither would the Syrians help the children of Ammon any more."}]}, "20": {"chapter": 20, "duration": 131.32, "audio_url": "audio_ot/OT13_20.mp3", "total_verses": 8, "verses": [{"verse": 1, "start": 3.8, "end": 26.36, "ta": "மறுவருஷம், ராஜாக்கள் யுத்தத்திற்குப் புறப்படும் காலம் வந்தபோது, யோவாப் இராணுவபலத்தைக் கூட்டிக்கொண்டுபோய், அம்மோன் புத்திரரின்தேசத்தைப் பாழ்க்கடித்து ரப்பாவுக்குவந்து அதை முற்றிக்கைபோட்டான்; தாவீதோ எருசலேமில் இருந்துவிட்டான்; யோவாப் ரப்பாவை அடித்துச் சங்கரித்தான்.", "en": "And it came to pass, that after the year was expired, at the time that kings go out to battle , Joab led forth the power of the army, and wasted the country of the children of Ammon, and came and besieged Rabbah. But David tarried at Jerusalem. And Joab smote Rabbah, and destroyed it."}, {"verse": 2, "start": 26.36, "end": 45.99, "ta": "தாவீது வந்து, அவர்கள் ராஜாவுடைய தலையின்மேல் இருந்த கிரீடத்தை எடுத்துக்கொண்டான்; அது ஒரு தாலந்து நிறையும் ரத்தினங்கள் பதித்ததுமாயிருந்தது; அது தாவீதின்தலையில் வைக்கப்பட்டது; பட்டணத்திலிருந்து ஏராளமான கொள்ளையையும் கொண்டுபோனான்.", "en": "And David took the crown of their king from off his head, and found it to weigh a talent of gold, and there were precious stones in it; and it was set upon David’s head: and he brought also exceeding much spoil out of the city."}, {"verse": 3, "start": 45.99, "end": 66.16, "ta": "பின்பு அதிலிருந்த ஜனங்களை அவன் வெளியே கொண்டுபோய், அவர்களை வாள்களுக்கும், இருப்புப்பாரைகளுக்கும், கோடரிகளுக்கும் உட்படுத்தி; இப்படி அம்மோன் புத்திரரின் பட்டணங்களுக்கெல்லாம் தாவீது செய்து, எல்லா ஜனத்தோடுங்கூட எருசலேமுக்குத் திரும்பினான்.", "en": "And he brought out the people that were in it, and cut them with saws, and with harrows of iron, and with axes. Even so dealt David with all the cities of the children of Ammon. And David and all the people returned to Jerusalem."}, {"verse": 4, "start": 66.16, "end": 82.17, "ta": "அதற்குப்பின்பு கேசேரிலே பெலிஸ்தரோடு யுத்தம் உண்டாயிற்று; அப்பொழுது சாத்தியனாகிய சிபெக்காய் இராட்சத புத்திரரில் ஒருவனான சிப்பாயி என்பவனைக் கொன்றான்; அதினால் அவர்கள் வசப்படுத்தப்பட்டார்கள்.", "en": "And it came to pass after this, that there arose war at Gezer with the Philistines; at which time Sibbechai the Hushathite slew Sippai, that was of the children of the giant: and they were subdued."}, {"verse": 5, "start": 82.17, "end": 98.87, "ta": "திரும்பப் பெலிஸ்தரோடு யுத்தமுண்டாகிறபோது, யாவீரின் குமாரனாகிய எல்க்கானான் காத்தூரானாகிய கோலியாத்தின் சகோதரனான லாகேமியைக் கொன்றான்; அவன் ஈட்டித் தாங்கு நெய்கிறவர்களின் படைமரம் அவ்வளவு பெரிதாயிருந்தது.", "en": "And there was war again with the Philistines; and Elhanan the son of Jair slew Lahmi the brother of Goliath the Gittite, whose spear staff was like a weaver’s beam."}, {"verse": 6, "start": 98.87, "end": 113.11, "ta": "மறுபடியும் ஒரு யுத்தம் காத்திலே நடந்தபோது, அங்கே நெட்டையனான ஒரு மனுஷன் இருந்தான்; அவனுக்கு அவ்வாறு விரலாக இருபத்துநாலு விரல்கள் இருந்தது, அவனும் இராட்சத சந்ததியாயிருந்து,", "en": "And yet again there was war at Gath, where was a man of great stature, whose fingers and toes were four and twenty, six on each hand , and six on each foot: and he also was the son of the giant."}, {"verse": 7, "start": 113.11, "end": 121.04, "ta": "இஸ்ரவேலை நிந்தித்தான்; தாவீதின் சகோதரனாகிய சிமேயாவின் குமாரன் யோனத்தான் அவனைக் கொன்றான்.", "en": "But when he defied Israel, Jonathan the son of Shimea David’s brother slew him."}, {"verse": 8, "start": 121.04, "end": 129.82, "ta": "காத்தூரிலிருந்த இராட்சதனுக்குப் பிறந்த இவர்கள் தாவீதின் கையினாலும் அவன் சேவகரின் கையினாலும் மடிந்தார்கள்.", "en": "These were born unto the giant in Gath; and they fell by the hand of David, and by the hand of his servants."}]}, "21": {"chapter": 21, "duration": 412.58, "audio_url": "audio_ot/OT13_21.mp3", "total_verses": 30, "verses": [{"verse": 1, "start": 3.8, "end": 11.14, "ta": "சாத்தான் இஸ்ரவேலுக்கு விரோதமாய் எழும்பி, இஸ்ரவேலைத் தொகையிடுகிறதற்குத் தாவீதை ஏவிவிட்டது.", "en": "And Satan stood up against Israel, and provoked David to number Israel."}, {"verse": 2, "start": 11.14, "end": 27.94, "ta": "அப்படியே தாவீது யோவாபையும், ஜனத்தின் சேர்வைக்காரரையும் நோக்கி: நீங்கள் போய், பெயெர்செபாதொடங்கித் தாண்மட்டும் இருக்கிற இஸ்ரவேலை எண்ணி, அவர்கள் இலக்கத்தை நான் அறியும்படிக்கு, என்னிடத்தில் கொண்டுவாருங்கள் என்றான்.", "en": "And David said to Joab and to the rulers of the people, Go, number Israel from Beer-sheba even to Dan; and bring the number of them to me, that I may know it ."}, {"verse": 3, "start": 27.94, "end": 50.7, "ta": "அப்பொழுது யோவாப் கர்த்தருடைய ஜனங்கள் இப்போது இருக்கிறதைப்பார்க்கிலும் நூறத்தனையாய் அவர் வர்த்திக்கப்பண்ணுவாராக; ஆனாலும் ராஜாவாகிய என் ஆண்டவனே, அவர்களெல்லாரும் என் ஆண்டவனின் சேவகரல்லவா? என் ஆண்டவன் இதை விசாரிப்பானேன்? இஸ்ரவேலின்மேல் குற்றமுண்டாக இது நடக்கவேண்டியது என்ன என்றான்.", "en": "And Joab answered, The LORD make his people an hundred times so many more as they be: but, my lord the king, are they not all my lord’s servants? why then doth my lord require this thing? why will he be a cause of trespass to Israel?"}, {"verse": 4, "start": 50.7, "end": 61.46, "ta": "யோவாப் அப்படிச் சொல்லியும், ராஜாவின் வார்த்தை மேலிட்டபடியினால், யோவாப் புறப்பட்டு, இஸ்ரவேல் எங்கும் சுற்றித்திரிந்து எருசலேமுக்கு வந்து,", "en": "Nevertheless the king’s word prevailed against Joab. Wherefore Joab departed, and went throughout all Israel, and came to Jerusalem."}, {"verse": 5, "start": 61.46, "end": 77.68, "ta": "ஜனத்தை இலக்கம்பார்த்து, தொகையைத் தாவீதிடத்தில் கொடுத்தான்; இஸ்ரவேலிலெல்லாம் பட்டயம் உருவத்தக்கவர்கள் பதினொருலட்சம்பேரும், யூதாவில் பட்டயம் உருவத்தக்கவர்கள் நாலுலட்சத்து எழுபதினாயிரம்பேரும் இருந்தார்கள்.", "en": "And Joab gave the sum of the number of the people unto David. And all they of Israel were a thousand thousand and an hundred thousand men that drew sword: and Judah was four hundred threescore and ten thousand men that drew sword."}, {"verse": 6, "start": 77.68, "end": 89.17, "ta": "ஆனாலும் ராஜாவின் வார்த்தை யோவாபுக்கு அருவருப்பாயிருந்தபடியினால், லேவி பென்யமீன் கோத்திங்களிலுள்ளவர்களை அவர்களுடைய இலக்கத்திற்குட்பட எண்ணாதேபோனான்.", "en": "But Levi and Benjamin counted he not among them: for the king’s word was abominable to Joab."}, {"verse": 7, "start": 89.17, "end": 95.42, "ta": "இந்தக் காரியம் தேவனுடைய பார்வைக்கு ஆகாததானபடியினால் அவர் இஸ்ரவேலை வாதித்தார்.", "en": "And God was displeased with this thing; therefore he smote Israel. concerning this thing"}, {"verse": 8, "start": 95.42, "end": 109.53, "ta": "தாவீது தேவனை நோக்கி: நான் இந்தக் காரியத்தைச் செய்ததினால் மிகவும் பாவஞ்செய்தேன்; இப்போதும் உம்முடைய அடியேனின் அக்கிரமத்தை நீக்கிவிடும்; வெகு புத்தியீனமாய்ச் செய்தேன் என்றான்.", "en": "And David said unto God, I have sinned greatly, because I have done this thing: but now, I beseech thee, do away the iniquity of thy servant; for I have done very foolishly."}, {"verse": 9, "start": 109.53, "end": 114.76, "ta": "அப்பொழுது கர்த்தர், தாவீதின் ஞானதிருஷ்டிக்காரனாகிய காத்துடனே பேசி,", "en": "And the LORD spake unto Gad, David’s seer, saying,"}, {"verse": 10, "start": 114.76, "end": 129.38, "ta": "நீ தாவீதினிடத்தில் போய் மூன்று காரியங்களை உனக்கு முன்பாக வைக்கிறேன்; அவைகளில் ஒரு காரியத்தைத் தெரிந்துகொள்; அதை நான் உனக்குச்செய்வேன் என்று கர்த்தர் உரைக்கிறார் என்று சொல் என்றார்.", "en": "Go and tell David, saying, Thus saith the LORD , I offer thee three things: choose thee one of them, that I may do it unto thee."}, {"verse": 11, "start": 129.38, "end": 133.16, "ta": "அப்படியே காத் தாவீதினிடத்தில் வந்து, அவனை நோக்கி:", "en": "So Gad came to David, and said unto him, Thus saith the LORD , Choose thee"}, {"verse": 12, "start": 133.16, "end": 169.37, "ta": "மூன்று வருஷத்துப் பஞ்சமோ? அல்லது உன் பகைஞரின் பட்டயம் உன்னைப் பின்தொடர நீ உன் சத்துருக்களுக்கு முன்பாக முறிந்தோடிப்போகச் செய்யும் மூன்று மாதச் சங்காரமோ? அல்லது மூன்றுநாள் கர்த்தருடைய தூதன் இஸ்ரவேலுடைய எல்லையெங்கும் சங்காரம் உண்டாகும்படி தேசத்தில் நிற்கும் கர்த்தருடைய பட்டயமாகிய கொள்ளை நோயோ? இவைகளில் ஒன்றைத் தெரிந்துகொள் என்று கர்த்தர் உரைக்கிறார். இப்போதும் என்னை அனுப்பினவருக்கு நான் என்ன மறுஉத்தரவு கொண்டுபோகவேண்டும் என்பதை யோசித்துப்பாரும் என்றான்.", "en": "Either three years’ famine; or three months to be destroyed before thy foes, while that the sword of thine enemies overtaketh thee; or else three days the sword of the LORD , even the pestilence, in the land, and the angel of the LORD destroying throughout all the coasts of Israel. Now therefore advise thyself what word I shall bring again to him that sent me."}, {"verse": 13, "start": 169.37, "end": 184.79, "ta": "அப்பொழுது தாவீது கர்த்தரை நோக்கி: கொடிய இடுக்கணில் அகப்பட்டிருக்கிறேன்; இப்போது நான் கர்த்தருடைய கையிலே விழுவேனாக; அவருடைய இரக்கங்கள் மகா பெரியது; மனுஷர் கையிலே விழாதிருப்பேனாக என்றான்.", "en": "And David said unto Gad, I am in a great strait: let me fall now into the hand of the LORD ; for very great are his mercies: but let me not fall into the hand of man."}, {"verse": 14, "start": 184.79, "end": 193.22, "ta": "ஆகையால் கர்த்தர் இஸ்ரவேலிலே கொள்ளைநோயை வரப்பண்ணினார், அதினால் இஸ்ரவேலில் எழுபதினாயிரம்பேர் மடிந்தார்கள்.", "en": "So the LORD sent pestilence upon Israel: and there fell of Israel seventy thousand men."}, {"verse": 15, "start": 193.22, "end": 214.6, "ta": "எருசலேமையும் அழிக்க தேவன் ஒரு தூதனை அனுப்பினான்; ஆனாலும் ஒருவன் அழிக்கையில் கர்த்தர் பார்த்து, அந்தத் தீங்குக்கு மனஸ்தாபப்பட்டு, சங்கரிக்கிற தூதனை நோக்கி: போதும்; இப்போது உன் கையை நிறுத்து என்றார்; கர்த்தருடைய தூதன் எபூசியனாகிய ஒர்னானின் களத்தண்டையிலே நின்றான்.", "en": "And God sent an angel unto Jerusalem to destroy it: and as he was destroying, the LORD beheld, and he repented him of the evil, and said to the angel that destroyed, It is enough, stay now thine hand. And the angel of the LORD stood by the threshingfloor of Ornan the Jebusite."}, {"verse": 16, "start": 214.6, "end": 234.67, "ta": "தாவீது தன் கண்களை ஏறெடுத்து, பூமிக்கும் வானத்திற்கும் நடுவே நிற்கிற கர்த்தருடைய தூதன் உருவின பட்டயத்தைத் தன் கையில் பிடித்து, அதை எருசலேமின்மேல் நீட்டியிருக்கக் கண்டான்; அப்பொழுது தாவீதும் மூப்பர்களும் இரட்டுப் போர்த்துக்கொண்டு முகங்குப்புற விழுந்தார்கள்.", "en": "And David lifted up his eyes, and saw the angel of the LORD stand between the earth and the heaven, having a drawn sword in his hand stretched out over Jerusalem. Then David and the elders of Israel, who were clothed in sackcloth, fell upon their faces."}, {"verse": 17, "start": 234.67, "end": 258.3, "ta": "தாவீது தேவனை நோக்கி: ஜனத்தை எண்ணச் சொன்னவன் நான் அல்லவோ? நான்தான் பாவஞ்செய்தேன்; பொல்லாப͠Ϊு நடப்பிĠύதேன்; இந்த ஆடுகள் என்ன செய்ĠΤு? என் தேவனாகிய கர்த்தாவே, வாதிக்கும்படி உம்முடைய கரம் உம்முடைய ஜனத்திற்கு விரோதமாயிராமல், எனக்கும் என் தகப்பன் வீட்டிற்கும் விரோதமாயிருப்பதாக என்றான்.", "en": "And David said unto God, Is it not I that commanded the people to be numbered? even I it is that have sinned and done evil indeed; but as for these sheep, what have they done? let thine hand, I pray thee, O LORD my God, be on me, and on my father’s house; but not on thy people, that they should be plagued."}, {"verse": 18, "start": 258.3, "end": 272.56, "ta": "அப்பொழுது எபூசியனாகிய ஒர்னானின் களத்திலே கர்த்தருக்கு ஒரு பலிபீடத்தை உண்டாக்கும்படி, தாவீது அங்கே போகவேண்டுமென்று தாவீதுக்குச் சொல் என்று கர்த்தருடைய தூதன் காத்துக்குக் கட்டளையிட்டான்.", "en": "Then the angel of the LORD commanded Gad to say to David, that David should go up, and set up an altar unto the LORD in the threshingfloor of Ornan the Jebusite."}, {"verse": 19, "start": 272.56, "end": 278.52, "ta": "அப்படியே தாவீது கர்த்தரின் நாமத்திலே காத் சொன்ன வார்த்தையின்படியே போனான்.", "en": "And David went up at the saying of Gad, which he spake in the name of the LORD ."}, {"verse": 20, "start": 278.52, "end": 291.1, "ta": "ஒர்னான் திரும்பிப்பார்த்தான்; அவனும் அவனோடிருக்கிற அவனுடைய நாலு குமாரரும் அந்த தேவதூதனைக் கண்டு ஒளித்துக்கொண்டார்கள்; ஒர்னான் போரடித்துக்கொண்டிருந்தான்.", "en": "And Ornan turned back, and saw the angel; and his four sons with him hid themselves. Now Ornan was threshing wheat."}, {"verse": 21, "start": 291.1, "end": 302.66, "ta": "தாவீது ஒர்னானிடத்தில் வந்தபோது ஒர்னான் கவனித்துத் தாவீதைப் பார்த்து, அவன் களத்திலிருந்து புறப்பட்டுவந்து, தரைமட்டும் குனிந்து தாவீதை வணங்கினான்.", "en": "And as David came to Ornan, Ornan looked and saw David, and went out of the threshingfloor, and bowed himself to David with his face to the ground."}, {"verse": 22, "start": 302.66, "end": 318.37, "ta": "அப்பொழுது தாவீது ஒர்னானை நோக்கி: இந்தக் களத்தின் நிலத்திலே நான் கர்த்தருக்கு ஒரு பலிபீடத்தைக் கட்டும்படிக்கு அதை எனக்குக் கொடு; ஜனத்தைவிட்டு நிறுத்தப்பட, எனக்கு அதைப் பெறும் விலைக்குக் கொடு என்றான்.", "en": "Then David said to Ornan, Grant me the place of this threshingfloor, that I may build an altar therein unto the LORD : thou shalt grant it me for the full price: that the plague may be stayed from the people."}, {"verse": 23, "start": 318.37, "end": 337.56, "ta": "ஒர்னான் தாவீதை நோக்கி: ராஜாவாகிய என் ஆண்டவன் அதை வாங்கிக்கொண்டு, தம்முடைய பார்வைக்கு நலமானபடி செய்வாராக; இதோ, சர்வாங்கதகனங்களுக்கு மாடுகளும், விறகுக்குப் போரடிக்கிற உருளைகளும், போஜனபலிக்குக் கோதுமையும் ஆகிய யாவையும் கொடுக்கிறேன் என்றான்.", "en": "And Ornan said unto David, Take it to thee, and let my lord the king do that which is good in his eyes: lo, I give thee the oxen also for burnt offerings, and the threshing instruments for wood, and the wheat for the meat offering; I give it all."}, {"verse": 24, "start": 337.56, "end": 350.87, "ta": "அதற்குத் தாவீதுராஜா ஒர்னானை நோக்கி: அப்படியல்ல, நான் உன்னுடையதை இலவசமாய் வாங்கி, கர்த்தருக்குச் சர்வாங்க தகனத்தைப் பலியிடாமல், அதை பெறும் விலைக்கு வாங்குவேன் என்று சொல்லி,", "en": "And king David said to Ornan, Nay; but I will verily buy it for the full price: for I will not take that which is thine for the LORD , nor offer burnt offerings without cost."}, {"verse": 25, "start": 350.87, "end": 356.76, "ta": "தாவீது அந்த நிலத்திற்கு அறுநூறு சேக்கல் நிறைபொன்னை ஒர்னானுக்குக்குக் கொடுத்து,", "en": "So David gave to Ornan for the place six hundred shekels of gold by weight."}, {"verse": 26, "start": 356.76, "end": 375.96, "ta": "அங்கே கர்த்தருக்கு ஒரு பலிபீடத்தைக் கட்டி, சர்வாங்க தகனபலிகளையும் சமாதான பலிகளையும் செலுத்தி, கர்த்தரை நோக்கி விண்ணப்பம்பண்ணினான்; அப்பொழுது அவர் வானத்திலிருந்து சர்வாங்க தகனபலிபீடத்தின்மேல் இறங்கின அக்கினியில் அவனுக்கு மறுஉத்தரவு கொடுத்ததுமல்லாமல்,", "en": "And David built there an altar unto the LORD , and offered burnt offerings and peace offerings, and called upon the LORD ; and he answered him from heaven by fire upon the altar of burnt offering."}, {"verse": 27, "start": 375.96, "end": 383.38, "ta": "தேவதூதன் தன்னுடைய பட்டயத்தை உறையிலே திரும்பப் போடவேண்டும் என்று கர்த்தர் அவனுக்குச் சொன்னார்.", "en": "And the LORD commanded the angel; and he put up his sword again into the sheath thereof."}, {"verse": 28, "start": 383.38, "end": 392.61, "ta": "எபூசியனாகிய ஒர்னானின் களத்திலே கர்த்தர் தனக்கு உத்தரவு அருளினதைத் தாவீது அக்காலத்திலே, கண்டு அங்கேதானே பலியிட்டான்.", "en": "At that time when David saw that the LORD had answered him in the threshingfloor of Ornan the Jebusite, then he sacrificed there."}, {"verse": 29, "start": 392.61, "end": 401.92, "ta": "மோசே வனாந்தரத்தில் உண்டாக்கின கர்த்தருடைய வாசஸ்தலமும் சர்வாங்க தகனபலிபீடமும் அக்காலத்திலே கிபியோனின் மேட்டில் இருந்தது.", "en": "For the tabernacle of the LORD , which Moses made in the wilderness, and the altar of the burnt offering, were at that season in the high place at Gibeon."}, {"verse": 30, "start": 401.92, "end": 411.08, "ta": "தாவீது கர்த்தருடைய தூதனின் பட்டயத்திற்குப் பயந்திருந்தபடியால், அவன் தேவசந்நிதியில் போய் விசாரிக்கக் கூடாதிருந்தது.", "en": "But David could not go before it to enquire of God: for he was afraid because of the sword of the angel of the LORD ."}]}, "22": {"chapter": 22, "duration": 288.17, "audio_url": "audio_ot/OT13_22.mp3", "total_verses": 19, "verses": [{"verse": 1, "start": 3.8, "end": 15.39, "ta": "அப்பொழுது தாவீது: தேவனாகிய கர்த்தருடைய ஆலயம் இருக்கும் ஸ்தலம் இதுவே; இஸ்ரவேல் பலியிடும் சர்வாங்கதகனபலிபீடம் இருக்கும் ஸ்தலமும் இதுவே என்றான்.", "en": "Then David said, This is the house of the LORD God, and this is the altar of the burnt offering for Israel."}, {"verse": 2, "start": 15.39, "end": 28.54, "ta": "பின்பு தாவீது இஸ்ரவேல் தேசத்திலிருக்கிற அந்நியஜாதியாரைக் கூடிவரச்செய்து, தேவனுடைய ஆலயத்தைக் கட்டுகிறதற்கான கல்லுகளை வெட்டிப் பணிப்படுத்தும் கல்தச்சரை ஏற்படுத்தினான்.", "en": "And David commanded to gather together the strangers that were in the land of Israel; and he set masons to hew wrought stones to build the house of God."}, {"verse": 3, "start": 28.54, "end": 38.49, "ta": "தாவீது வாசல்களின் கதவுகளுக்கு வேண்டிய ஆணிகளுக்கும் கீல்களுக்கும் மிகுதியான இரும்பையும், நிறுத்து முடியாத ஏராளமான வெண்கலத்தையும்,", "en": "And David prepared iron in abundance for the nails for the doors of the gates, and for the joinings; and brass in abundance without weight;"}, {"verse": 4, "start": 38.49, "end": 48.37, "ta": "எண்ணிறந்த கேதுருமரங்களையும் சம்பாதித்தான்; சீதோனியரும் தீரியரும் தாவீதுக்குத் திரளான கேதுருமரங்களைக் கொண்டுவந்தார்கள்.", "en": "Also cedar trees in abundance: for the Zidonians and they of Tyre brought much cedar wood to David."}, {"verse": 5, "start": 48.37, "end": 73.7, "ta": "தாவீது: என் குமாரனாகிய சாலொமோன் வாலிபனும் இளைஞனுமாயிருக்கிறான்; கர்த்தருக்குக் கட்டப்படும் ஆலயம் சகல தேசங்களிலும் கீர்த்தியும் மகிமையும் உடையதாய் விளங்கும்படி மகா பெரியதாயிருக்கவேண்டும்; ஆகையால் அதற்காக வேண்டியவைகளை இப்பொழுதே சேகரம்பண்ணவேண்டும் என்று சொல்லி, தாவீது தன் மரணத்திற்கு முன்னே திரளாய்ச் சவதரித்துவைத்தான்.", "en": "And David said, Solomon my son is young and tender, and the house that is to be builded for the LORD must be exceeding magnifical, of fame and of glory throughout all countries: I will therefore now make preparation for it. So David prepared abundantly before his death."}, {"verse": 6, "start": 73.7, "end": 83.06, "ta": "அவன் தன் குமாரனாகிய சாலொமோனை அழைத்து, இஸ்ரவேலின் தேவனாகிய கர்த்தருக்கு ஆலயத்தைக் கட்டுகிறதற்காக அவனுக்கு கட்டளைகொடுத்து,", "en": "Then he called for Solomon his son, and charged him to build an house for the LORD God of Israel."}, {"verse": 7, "start": 83.06, "end": 93.09, "ta": "சாலொமோனை நோக்கி: என் குமாரனே, நான் என் தேவனாகிய கர்த்தரின் நாமத்திற்கு ஒரு ஆலயத்தைக் கட்ட என் இருதயத்தில் நினைத்திருந்தேன்.", "en": "And David said to Solomon, My son, as for me, it was in my mind to build an house unto the name of the LORD my God:"}, {"verse": 8, "start": 93.09, "end": 110.25, "ta": "ஆனாலும் கர்த்தருடைய வார்த்தை எனக்கு உண்டாகி: நீ திரளான இரத்தத்தைச் சிந்தி, பெரிய யுத்தங்களைப் பண்ணினாய்; என் நாமத்திற்கு ஆலயத்தைக் கட்டவேண்டாம்; எனக்கு முன்பாக மிகுதியான இரத்தத்தைத் தரையிலே சிந்தப்பண்ணினாய்.", "en": "But the word of the LORD came to me, saying, Thou hast shed blood abundantly, and hast made great wars: thou shalt not build an house unto my name, because thou hast shed much blood upon the earth in my sight."}, {"verse": 9, "start": 110.25, "end": 131.49, "ta": "இதோ, உனக்குப் பிறக்கப்போகிற குமாரன் அமைதியுள்ள புருஷனாயிருப்பான்; சுற்றிலுமிருக்கும் அவன் சத்துருக்களையெல்லாம் விலக்கி அவனை அமர்ந்திருக்கச் செய்வேன்; ஆகையால் அவன்பேர் சாலொமோன் என்னப்படும், அவன் நாட்களில் இஸ்ரவேலின்மேல் சமாதானத்தையும் அமரிக்கையையும் அருளுவான்.", "en": "Behold, a son shall be born to thee, who shall be a man of rest; and I will give him rest from all his enemies round about: for his name shall be Solomon, and I will give peace and quietness unto Israel in his days."}, {"verse": 10, "start": 131.49, "end": 148.21, "ta": "அவன் என் நாமத்திற்கு ஆலயத்தைக் கட்டுவான்; அவன் எனக்குக் குமாரனாயிருப்பான், நான் அவனுக்குப் பிதாவாயிருப்பேன்; இஸ்ரவேலை ஆளும் அவனுடைய ராஜாங்கத்தின் சிங்காசனத்தை என்றென்றைக்கும் நிலைப்படுத்துவேன் என்றார்.", "en": "He shall build an house for my name; and he shall be my son, and I will be his father; and I will establish the throne of his kingdom over Israel for ever."}, {"verse": 11, "start": 148.21, "end": 161.43, "ta": "இப்போதும் என் குமாரனே, நீ பாக்கியவானாயிருந்து, கர்த்தர் உன்னைக் குறித்துச் சொன்னபடியே உன் தேவனாகிய கர்த்தரின் ஆலயத்தைக் கட்டும்படி, அவர் உன்னுடனேகூட இருப்பாராக.", "en": "Now, my son, the LORD be with thee; and prosper thou, and build the house of the LORD thy God, as he hath said of thee."}, {"verse": 12, "start": 161.43, "end": 173.91, "ta": "கர்த்தர் உனக்கு ஞானத்தையும் உணர்வையும் அருளிச்செய்து, உன் தேவனாகிய கர்த்தரின் நியாயப்பிரமாணத்தைக் கைக்கொண்டு, இஸ்ரவேலை ஆளும்படி உனக்குக் கட்டளையிடுவாராக.", "en": "Only the LORD give thee wisdom and understanding, and give thee charge concerning Israel, that thou mayest keep the law of the LORD thy God."}, {"verse": 13, "start": 173.91, "end": 188.32, "ta": "கர்த்தர் இஸ்ரவேலுக்காக மோசேக்குக் கற்பித்த நியமங்களையும் நியாயங்களையும் செய்ய நீ கவனமாயிருந்தால் பாக்கியவானாயிருப்பாய்; நீ பலங்கொண்டு தைரியமாயிரு, பயப்படாமலும் கலங்காமலும் இரு.", "en": "Then shalt thou prosper, if thou takest heed to fulfil the statutes and judgments which the LORD charged Moses with concerning Israel: be strong, and of good courage; dread not, nor be dismayed."}, {"verse": 14, "start": 188.32, "end": 209.79, "ta": "இதோ, நான் என் சிறுமையிலே கர்த்தருடைய ஆலயத்திற்காக ஒரு லட்சம் தாலந்து பொன்னையும், பத்துலட்சம் தாலந்து வெள்ளியையும் நிறுத்து முடியாத திரளான வெண்கலத்தையும் இரும்பையும் சவதரித்தும், மரங்களையும் கற்களையும் சவதரித்தும் வைத்தேன், நீ இன்னும் அவைகளுக்கு அதிகமாய்ச் சவதரிப்பாய்.", "en": "Now, behold, in my trouble I have prepared for the house of the LORD an hundred thousand talents of gold, and a thousand thousand talents of silver; and of brass and iron without weight; for it is in abundance: timber also and stone have I prepared; and thou mayest add thereto."}, {"verse": 15, "start": 209.79, "end": 219.22, "ta": "வேலைசெய்யத்தக்க திரளான சிற்பாசாரிகளும், தச்சரும் கல்தச்சரும் எந்த வேலையிலும் நிபுணரானவர்களும் உன்னோடிருக்கிறார்கள்.", "en": "Moreover there are workmen with thee in abundance, hewers and workers of stone and timber, and all manner of cunning men for every manner of work."}, {"verse": 16, "start": 219.22, "end": 231.77, "ta": "பொன்னுக்கும், வெள்ளிக்கும், வெண்கலத்துக்கும், இரும்புக்கும் கணக்கில்லை; நீ எழும்பிக் காரியத்தை நடப்பி; கர்த்தர் உன்னோடே இருப்பாராக என்றான்.", "en": "Of the gold, the silver, and the brass, and the iron, there is no number. Arise therefore , and be doing, and the LORD be with thee."}, {"verse": 17, "start": 231.77, "end": 240.17, "ta": "தன் குமாரனாகிய சாலொமோனுக்கு உதவிசெய்ய, தாவீது இஸ்ரவேலின் பிரபுக்கள் அனைவருக்கும் கற்பித்துச் சொன்னது.", "en": "David also commanded all the princes of Israel to help Solomon his son, saying ,"}, {"verse": 18, "start": 240.17, "end": 259.41, "ta": "உங்கள் தேவனாகிய கர்த்தர் உங்களோடிருந்து நான்கு திசையிலும் உங்களுக்கு இளைப்பாறுதலைத் தந்தார் அல்லவா? தேசத்தின் குடிகளை என் கையில் ஒப்புக்கொடுத்தார்; கர்த்தருக்கு முன்பாகவும், அவருடைய ஜனத்திற்கு முன்பாகவும் தேசம் கீழ்ப்பட்டிருக்கிறது.", "en": "Is not the LORD your God with you? and hath he not given you rest on every side? for he hath given the inhabitants of the land into mine hand; and the land is subdued before the LORD , and before his people."}, {"verse": 19, "start": 259.41, "end": 286.67, "ta": "இப்போதும் நீங்கள் உங்கள் இருதயத்தையும், உங்கள் ஆத்துமத்தையும், உங்கள் தேவனாகிய கர்த்தரைத் தேடுகிறதற்கு நேராக்கி, கர்த்தருடைய உடன்படிக்கைப் பெட்டியையும் தேவனுடைய பரிசுத்தப் பணிமுட்டுகளையும், கர்த்தருடைய நாமத்திற்குக் கட்டப்படும் அந்த ஆலயத்திற்குள் கொண்டுபோகும்படிக்கு நீங்கள் எழும்பி, தேவனாகிய கர்த்தரின் பரிசுத்த ஸ்தலத்தைக் கட்டுங்கள் என்றான்.", "en": "Now set your heart and your soul to seek the LORD your God; arise therefore, and build ye the sanctuary of the LORD God, to bring the ark of the covenant of the LORD , and the holy vessels of God, into the house that is to be built to the name of the LORD ."}]}, "23": {"chapter": 23, "duration": 342.98, "audio_url": "audio_ot/OT13_23.mp3", "total_verses": 32, "verses": [{"verse": 1, "start": 3.8, "end": 11.87, "ta": "தாவீது கிழவனும் பூரண வயதுள்ளவனுமானபோது, தன் குமாரனாகிய சாலொமோனை இஸ்ரவேலின்மேல் ராஜாவாக்கினான்.", "en": "So when David was old and full of days, he made Solomon his son king over Israel."}, {"verse": 2, "start": 11.87, "end": 19.34, "ta": "இஸ்ரவேலின் எல்லாப் பிரபுக்களையும், ஆசாரியரையும், லேவியரையும் கூடிவரும்படி செய்தான்.", "en": "And he gathered together all the princes of Israel, with the priests and the Levites."}, {"verse": 3, "start": 19.34, "end": 30.84, "ta": "அப்பொழுது முப்பது வயதுமுதல் அதற்கு மேற்பட்ட லேவியர் பேர்பேராக எண்ணப்பட்டார்கள், தலைதலையாக எண்ணப்பட்ட அவர்களுடைய இலக்கம் முப்பத்தெண்ணாயிரம்.", "en": "Now the Levites were numbered from the age of thirty years and upward: and their number by their polls, man by man, was thirty and eight thousand."}, {"verse": 4, "start": 30.84, "end": 41.89, "ta": "அவர்களில் இருபத்துநாலாயிரம்பேர் கர்த்தருடைய ஆலயத்தின் வேலையை விசாரிக்கிறவர்களும், ஆறாயிரம்பேர் தலைவரும் மணியகாரருமாயிருக்கவேண்டும் என்றும்,", "en": "Of which, twenty and four thousand were to set forward the work of the house of the LORD ; and six thousand were officers and judges:"}, {"verse": 5, "start": 41.89, "end": 56.74, "ta": "நாலாயிரம்பேர் வாசல் காக்கிறவர்களாயிருக்கவேண்டும் என்றும், துதிசெய்கிறதற்குத் தான் பண்ணுவித்த கீதவாத்தியங்களால் நாலாயிரம்பேர் கர்த்தரைத் துதிக்கிறவர்களாயிருக்கவேண்டும் என்றும் தாவீது சொல்லி,", "en": "Moreover four thousand were porters; and four thousand praised the LORD with the instruments which I made, said David , to praise therewith ."}, {"verse": 6, "start": 56.74, "end": 64.97, "ta": "அவர்களை லேவியின் குமாரராகிய கெர்சோன், கோகாத், மெராரி என்பவர்களுடைய வகுப்புகளின்படி வகுத்தான்.", "en": "And David divided them into courses among the sons of Levi, namely , Gershon, Kohath, and Merari."}, {"verse": 7, "start": 64.97, "end": 69.69, "ta": "கெர்சோனியரில், லாதானும், சிமேயும் இருந்தார்கள்.", "en": "Of the Gershonites were , Laadan, and Shimei."}, {"verse": 8, "start": 69.69, "end": 79.44, "ta": "லாதானின் குமாரர், யெகியேல், சேத்தாம், யோவேல் என்னும் மூன்றுபேர்; இவர்களில் முந்தினவன் தலைமையாயிருந்தான்.", "en": "The sons of Laadan; the chief was Jehiel, and Zetham, and Joel, three."}, {"verse": 9, "start": 79.44, "end": 90.26, "ta": "சிமேயின் குமாரர், செலோமித், ஆசியேல், ஆரான் என்னும் மூன்றுபேர்; இவர்கள் லாதான் வம்சப் பிதாக்களில் தலைமையாயிருந்தார்கள்.", "en": "The sons of Shimei; Shelomith, and Haziel, and Haran, three. These were the chief of the fathers of Laadan."}, {"verse": 10, "start": 90.26, "end": 97.42, "ta": "யகாத், சீனா, எயூஷ், பெரீயா என்னும் நாலுபேரும் சிமேயின் குமாரராயிருந்தார்கள்.", "en": "And the sons of Shimei were , Jahath, Zina, and Jeush, and Beriah. These four were the sons of Shimei."}, {"verse": 11, "start": 97.42, "end": 113.03, "ta": "யாகாத் தலைமையாயிருந்தான்; சீனா இரண்டாம் குமாரனாயிருந்தான்; எயூஷுக்கும் பெரீயாவுக்கும் அநேகம் குமாரர் இராதபடியினால், அவர்கள் பிதாக்களின் குடும்பத்தாரில் ஒரே வம்சமாக எண்ணப்பட்டார்கள்.", "en": "And Jahath was the chief, and Zizah the second: but Jeush and Beriah had not many sons; therefore they were in one reckoning, according to their father’s house."}, {"verse": 12, "start": 113.03, "end": 119.81, "ta": "கோகாத்தின் குமாரர் அம்ராம், இத்சார், எப்ரோன், ஊசியேல் என்னும் நாலுபேர்.", "en": "The sons of Kohath; Amram, Izhar, Hebron, and Uzziel, four."}, {"verse": 13, "start": 119.81, "end": 145.41, "ta": "அம்ராமின் குமாரர், ஆரோன், மோசே என்பவர்கள்; ஆரோனும் அவன் குமாரரும் பரிசுத்தத்திற்குப் பரிசுத்தமான ஸ்தலத்தை என்றைக்கும் பரிசுத்தமாய்க் காக்கிறதற்கும், என்றைக்கும் கர்த்தருக்கு முன்பாக தூபங்காட்டுகிறதற்கும், அவருக்கு ஆராதனை செய்கிறதற்கும், அவர் நாமத்திலே ஆசீர்வாதம் கொடுக்கிறதற்கும் பிரித்துவைக்கப்பட்டார்கள்.", "en": "The sons of Amram; Aaron and Moses: and Aaron was separated, that he should sanctify the most holy things, he and his sons for ever, to burn incense before the LORD , to minister unto him, and to bless in his name for ever."}, {"verse": 14, "start": 145.41, "end": 152.72, "ta": "தேவனுடைய மனுஷனாகிய மோசேயின் குமாரரோவெனில், லேவிகோத்திரத்தாருக்குள் எண்ணப்பட்டார்கள்.", "en": "Now concerning Moses the man of God, his sons were named of the tribe of Levi."}, {"verse": 15, "start": 152.72, "end": 157.29, "ta": "மோசேயின் குமாரர், கெர்சோம், யேசர் என்பவர்கள்.", "en": "The sons of Moses were , Gershom, and Eliezer."}, {"verse": 16, "start": 157.29, "end": 161.63, "ta": "கெர்சோமின் குமாரரில் செபுவேல் தலைமையாயிருந்தான்.", "en": "Of the sons of Gershom, Shebuel was the chief."}, {"verse": 17, "start": 161.63, "end": 173.44, "ta": "எலியேசருடைய குமாரரில் ரெகபியா என்னும் அவன் குமாரன் தலைமையாயிருந்தான்: எலியேசருக்கு வேறே குமாரர் இல்லை, ரெகபியாவின் குமாரர் அநேகராயிருந்தார்கள்.", "en": "And the sons of Eliezer were , Rehabiah the chief. And Eliezer had none other sons; but the sons of Rehabiah were very many."}, {"verse": 18, "start": 173.44, "end": 177.71, "ta": "இத்சேரின் குமாரரில் செலோமித் தலைமையாயிருந்தான்.", "en": "Of the sons of Izhar; Shelomith the chief."}, {"verse": 19, "start": 177.71, "end": 187.61, "ta": "எப்ரோனின் குமாரரில் எரியா என்பவன் தலைமையாயிருந்தான்; இரண்டாவது அமரியா, மூன்றாவது யாகாசியேல் நாலாவது எக்காமியாம்.", "en": "Of the sons of Hebron; Jeriah the first, Amariah the second, Jahaziel the third, and Jekameam the fourth."}, {"verse": 20, "start": 187.61, "end": 193.93, "ta": "ஊசியேலின் குமாரரில் மீகா என்பவன் தலைமையாயிருந்தான்; இரண்டாவது இஷியா.", "en": "Of the sons of Uzziel; Michah the first, and Jesiah the second."}, {"verse": 21, "start": 193.93, "end": 202.84, "ta": "மெராரியின் குமாரர், மகேலி, மூசி என்பவர்கள்; மகேலியின் குமாரர், எலெயாசார், கீஸ் என்பவர்கள்.", "en": "The sons of Merari; Mahli, and Mushi. The sons of Mahli; Eleazar, and Kish."}, {"verse": 22, "start": 202.84, "end": 214.5, "ta": "எயொசார் மரிக்கிறபோது, அவனுக்குக் குமாரத்திகளே அல்லாமல் குமாரர் இல்லை; கீசின் குமாரராகிய இவர்களுடைய சகோதரர் இவர்களை விவாகம்பண்ணினார்கள்.", "en": "And Eleazar died, and had no sons, but daughters: and their brethren the sons of Kish took them."}, {"verse": 23, "start": 214.5, "end": 220.29, "ta": "மூசியின் குமாரர், மகலி, ஏதேர், எரேமோக் என்னும் மூன்றுபேர்.", "en": "The sons of Mushi; Mahli, and Eder, and Jeremoth, three."}, {"verse": 24, "start": 220.29, "end": 238.64, "ta": "தங்கள் பிதாக்களுடைய குடும்பங்களின்படியே, பிதாக்களில் தலைமையாயிருந்த லேவி புத்திரரின் பேர்டாப்பின்படியே, தலைதலையாக எண்ணப்பட்ட இருபது வயதுமுதல் அதற்கு மேற்பட்ட இவர்களுடைய சந்ததியார் கர்த்தருடைய ஆலயத்துப் பணிவிடையைச் செய்தார்கள்.", "en": "These were the sons of Levi after the house of their fathers; even the chief of the fathers, as they were counted by number of names by their polls, that did the work for the service of the house of the LORD , from the age of twenty years and upward."}, {"verse": 25, "start": 238.64, "end": 248.7, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தர் தமது ஜனத்தை இளைப்பாறியிருக்கப்பண்ணினார்; அவர் என்றென்றைக்கும் எருசலேமில் வாசம்பண்ணுவாரென்றும்,", "en": "For David said, The LORD God of Israel hath given rest unto his people, that they may dwell in Jerusalem for ever:"}, {"verse": 26, "start": 248.7, "end": 257.69, "ta": "இனி லேவியர் வாசஸ்தலத்தையாகிலும் அதின் ஊழியத்திற்கடுத்த அதின் பணிமுட்டுகளில் எதையாகிலும் சுமக்கத்தேவையில்லை என்றும்,", "en": "And also unto the Levites; they shall no more carry the tabernacle, nor any vessels of it for the service thereof."}, {"verse": 27, "start": 257.69, "end": 269.88, "ta": "தாவீது அவர்களைக் குறித்துச்சொன்ன கடைசி வார்த்தைகளின்படியே, லேவி புத்திரரில் தொகைக்குட்பட்டவர்கள் இருபதுவயதுமுதல் அதற்கு மேற்பட்டவர்களாயிருந்தார்கள்.", "en": "For by the last words of David the Levites were numbered from twenty years old and above:"}, {"verse": 28, "start": 269.88, "end": 286.94, "ta": "அவர்கள் ஆரோனுடைய குமாரரின் கீழ்க் கர்த்தருடைய ஆலயத்தின் ஊழியமாய் நின்று, பிராகாரங்களையும், அறைகளையும், சகல பரிசுத்த பணிமுட்டுகளின் சுத்திகரிப்பையும், தேவனுடைய ஆலயத்தின் ஆராதனைக்கடுத்த வேலையையும் விசாரிப்பதும்,", "en": "Because their office was to wait on the sons of Aaron for the service of the house of the LORD , in the courts, and in the chambers, and in the purifying of all holy things, and the work of the service of the house of God;"}, {"verse": 29, "start": 286.94, "end": 300.88, "ta": "சமுகத்தப்பங்களையும், போஜனபலிக்கு மெல்லிய மாவையும், புளிப்பில்லாத அதிரசங்களையும், சட்டிகளிலே செய்கிறதையும் சுடுகிறதையும், திட்டமான சகல நிறையையும் அளவையும் விசாரிப்பதும்,", "en": "Both for the shewbread, and for the fine flour for meat offering, and for the unleavened cakes, and for that which is baked in the pan, and for that which is fried, and for all manner of measure and size;"}, {"verse": 30, "start": 300.88, "end": 315.66, "ta": "நாள்தோறும் காலையிலும் மாலையிலும் கர்த்தரைப் போற்றித் துதித்து, ஓய்வுநாட்களிலும், அமாவாசைகளிலும், பண்டிகைகளிலும், கர்த்தருக்குச் சர்வாங்க தகனபலிகள் செலுத்தப்படுகிற சகல வேளைகளிலும்,", "en": "And to stand every morning to thank and praise the LORD , and likewise at even;"}, {"verse": 31, "start": 315.66, "end": 326.17, "ta": "இலக்கத்திற்குள்ளான அவர்கள் தங்களுக்கு நியமிக்கப்பட்டபடியே, எப்பொழுதும் அந்தப் பிரகாரமாய்ச் செய்ய, கர்த்தருக்கு முன்பாக நிற்பதும்,", "en": "And to offer all burnt sacrifices unto the LORD in the sabbaths, in the new moons, and on the set feasts, by number, according to the order commanded unto them, continually before the LORD :"}, {"verse": 32, "start": 326.17, "end": 341.48, "ta": "ஆசரிப்புக் கூடாரத்தின் காவலையும் பரிசுத்த ஸ்தலத்தின் காவலையும் தங்கள் சகோதரராகிய ஆரோனுடைய குமாரரின் காவலையும் காப்பதும், கர்த்தருடைய ஆலயத்தின் பணிவிடையைச் செய்வதும் அவர்கள் வேலையாயிருந்தது.", "en": "And that they should keep the charge of the tabernacle of the congregation, and the charge of the holy place , and the charge of the sons of Aaron their brethren, in the service of the house of the LORD ."}]}, "24": {"chapter": 24, "duration": 309.62, "audio_url": "audio_ot/OT13_24.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 13.09, "ta": "ஆரோன் புத்திரரின் வகுப்புகளாவன: ஆரோனின் குமாரர், நாதாப், அபியூ, எலெயாசார், இத்தாமார் என்பவர்கள்.", "en": "Now these are the divisions of the sons of Aaron. The sons of Aaron; Nadab, and Abihu, Eleazar, and Ithamar."}, {"verse": 2, "start": 13.09, "end": 24.28, "ta": "நாதாபும் அபியூவும் குமாரர் இல்லாமல் தங்கள் தகப்பனுக்கு முன்னே மரித்தபடியினால், எலெயாசாரும் இத்தாமாரும் ஆசாரிய ஊழியம் செய்தார்கள்.", "en": "But Nadab and Abihu died before their father, and had no children: therefore Eleazar and Ithamar executed the priest’s office."}, {"verse": 3, "start": 24.28, "end": 37.85, "ta": "தாவீது சாதோக்கைக்கொண்டு எலெயாசாரின் புத்திரரையும், அகிமெலேக்கைக்கொண்டு இத்தாமாரின் புத்திரரையும் அவர்கள் செய்யவேண்டிய ஊழியத்துக்கு முறைப்படி அவர்களை வகுத்தான்.", "en": "And David distributed them, both Zadok of the sons of Eleazar, and Ahimelech of the sons of Ithamar, according to their offices in their service."}, {"verse": 4, "start": 37.85, "end": 63.97, "ta": "அவர்களை வகுக்கிறபோது, இத்தாமாரின் புத்திரரைப்பார்க்கிலும் எலெயாசாரின் புத்திரருக்குள்ளே தலைமையானவர்கள் அதிகமானபேர் காணப்பட்டபடியினால், எலெயாசாரின் புத்திரரில் பதினாறுபேர் தங்கள் பிதாக்களுடைய குடும்பத்துக்கும், இத்தாமாரின் புத்திரரில் எட்டுப்பேர் தங்கள் பிதாக்களுடைய குடும்பத்துக்கும் தலைமையாக வைக்கப்பட்டார்கள்.", "en": "And there were more chief men found of the sons of Eleazar than of the sons of Ithamar; and thus were they divided. Among the sons of Eleazar there were sixteen chief men of the house of their fathers, and eight among the sons of Ithamar according to the house of their fathers."}, {"verse": 5, "start": 63.97, "end": 83.09, "ta": "எலெயாசாரின் புத்திரரிலும் இத்தாமாரின் புத்திரரிலும், பரிசுத்த ஸ்தலத்துக்கும், தேவனுக்கு அடுத்த காரியங்களில் பிரபுக்களாயிருக்கும்படிக்கும், இவர்களுக்கும் அவர்களுக்கும் வித்தியாசம்பண்ணாமல் சீட்டுப்போட்டு அவர்களை வகுத்தார்கள்.", "en": "Thus were they divided by lot, one sort with another; for the governors of the sanctuary, and governors of the house of God, were of the sons of Eleazar, and of the sons of Ithamar."}, {"verse": 6, "start": 83.09, "end": 112.07, "ta": "லேவியரில் சம்பிரதியாகிய செமாயா என்னும் நெதனெயேலின் குமாரன், ராஜாவுக்கும் பிரபுக்களுக்கும் ஆசாரியனாகிய சாதோக்குக்கும் அபியத்தாரின் குமாரனாகிய அகிமெலேக்குக்கும் ஆசாரியரும் லேவியருமான பிதாக்களின் தலைவருக்கும் முன்பாக அவர்கள் நாமங்களை எழுதினான்; ஒரு பிதாவின் வீட்டுச் சீட்டு எலெயாசாருக்கு விழுந்தது; பின்பு அந்தப்படியே இத்தாமாருக்கும் விழுந்தது.", "en": "And Shemaiah the son of Nethaneel the scribe, one of the Levites, wrote them before the king, and the princes, and Zadok the priest, and Ahimelech the son of Abiathar, and before the chief of the fathers of the priests and Levites: one principal household being taken for Eleazar, and one taken for Ithamar."}, {"verse": 7, "start": 112.07, "end": 118.65, "ta": "முதலாவது சீட்டு யோயாரிபின் பேர்வழிக்கும், இரண்டாவது யெதாயாவின் பேர்வழிக்கும்,", "en": "Now the first lot came forth to Jehoiarib, the second to Jedaiah,"}, {"verse": 8, "start": 118.65, "end": 124.53, "ta": "மூன்றாவது ஆரிமின் பேர்வழிக்கும், நான்காவது செயோரீமின் பேர்வழிக்கும்,", "en": "The third to Harim, the fourth to Seorim,"}, {"verse": 9, "start": 124.53, "end": 130.4, "ta": "ஐந்தாவது மல்கியாவின் பேர்வழிக்கும், ஆறாவது மியாமீனின் பேர்வழிக்கும்,", "en": "The fifth to Malchijah, the sixth to Mijamin,"}, {"verse": 10, "start": 130.4, "end": 136.2, "ta": "ஏழாவது அக்கோத்சின் பேர்வழிக்கும், எட்டாவது அபியாவின் பேர்வழிக்கும்,", "en": "The seventh to Hakkoz, the eighth to Abijah,"}, {"verse": 11, "start": 136.2, "end": 142.47, "ta": "ஒன்பதாவது யெசுவாவின் பேர்வழிக்கும், பத்தாவது செக்கனியாவின் பேர்வழிக்கும்,", "en": "The ninth to Jeshua, the tenth to Shecaniah,"}, {"verse": 12, "start": 142.47, "end": 148.98, "ta": "பதினோராவது எலியாசீபின் பேர்வழிக்கும், பன்னிரண்டாவது யாக்கீமின்பேர்வழிக்கும்,", "en": "The eleventh to Eliashib, the twelfth to Jakim,"}, {"verse": 13, "start": 148.98, "end": 155.72, "ta": "பதின்மூன்றாவது உப்பாவின் பேர்வழிக்கும், பதினான்காவது எசெபெயாபின் பேர்வழிக்கும்,", "en": "The thirteenth to Huppah, the fourteenth to Jeshebeab,"}, {"verse": 14, "start": 155.72, "end": 162.07, "ta": "பதினைந்தாவது பில்காவின் பேர்வழிக்கும், பதினாறாவது இம்மேரின் பேர்வழிக்கும்,", "en": "The fifteenth to Bilgah, the sixteenth to Immer,"}, {"verse": 15, "start": 162.07, "end": 168.18, "ta": "பதினேழாவது ஏசீரின் பேர்வழிக்கும், பதினெட்டாவது அப்சேசின் பேர்வழிக்கும்,", "en": "The seventeenth to Hezir, the eighteenth to Aphses,"}, {"verse": 16, "start": 168.18, "end": 175.25, "ta": "பத்தொன்பதாவது பெத்தகியாவின் பேர்வழிக்கும், இருபதாவது எகெசெக்கியேலின் பேர்வழிக்கும்,", "en": "The nineteenth to Pethahiah, the twentieth to Jehezekel,"}, {"verse": 17, "start": 175.25, "end": 182.07, "ta": "இருபத்தோராவது யாகினின் பேர்வழிக்கும், இருபத்திரண்டாவது காமுவேலின் பேர்வழிக்கும்,", "en": "The one and twentieth to Jachin, the two and twentieth to Gamul,"}, {"verse": 18, "start": 182.07, "end": 190.73, "ta": "இருபத்துமூன்றாவது தெலாயாவின் பேர்வழிக்கும், இருபத்துநான்காவது மாசியாவின் பேர்வழிக்கும் விழுந்தது.", "en": "The three and twentieth to Delaiah, the four and twentieth to Maaziah."}, {"verse": 19, "start": 190.73, "end": 210.01, "ta": "இஸ்ரவேலின் தேவனாகிய கர்த்தர் அவர்கள் தகப்பனாகிய ஆரோனுக்குக் கற்பித்தபடியே, அவர்கள் அவனுடைய கட்டளையின் பிரகாரம், தங்கள் முறைவரிகளில் கர்த்தருடைய ஆலயத்திற்குள் பிரவேசிக்கும் அவர்களுடைய ஊழியத்திற்காகப் பண்ணப்பட்ட வகுப்புகள் இவைகளே.", "en": "These were the orderings of them in their service to come into the house of the LORD , according to their manner, under Aaron their father, as the LORD God of Israel had commanded him."}, {"verse": 20, "start": 210.01, "end": 219.06, "ta": "லேவியின் மற்றப் புத்திரருக்குள்ளே இருக்கிற அம்ராமின் புத்திரரில் சூபவேலும், சூபவேலின் குமாரரில் எகேதியாவும்,", "en": "And the rest of the sons of Levi were these: Of the sons of Amram; Shubael: of the sons of Shubael; Jehdeiah."}, {"verse": 21, "start": 219.06, "end": 222.79, "ta": "ரெகபியாவின் குமாரரில் மூத்தவனாகிய இஷியாவும்,", "en": "Concerning Rehabiah: of the sons of Rehabiah, the first was Isshiah."}, {"verse": 22, "start": 222.79, "end": 228.11, "ta": "இத்சாரியரில் செலெமோத்தும், செலெமோத்தின் குமாரரில் யாகாத்தும்,", "en": "Of the Izharites; Shelomoth: of the sons of Shelomoth; Jahath."}, {"verse": 23, "start": 228.11, "end": 240.41, "ta": "எப்ரோனின் குமாரரில் மூத்தவனாகிய எரியாவும், இரண்டாம் குமாரனாகிய அமரியாவும், மூன்றாம் குமாரனாகிய யாகாசியேலும், நான்காம் குமாரனாகிய எக்காமியாமும்,", "en": "And the sons of Hebron; Jeriah the first , Amariah the second, Jahaziel the third, Jekameam the fourth."}, {"verse": 24, "start": 240.41, "end": 245.49, "ta": "ஊசியேலின் குமாரரில் மீகாவும், மீகாவின் குமாரரில் சாமீரும்,", "en": "Of the sons of Uzziel; Michah: of the sons of Michah; Shamir."}, {"verse": 25, "start": 245.49, "end": 250.81, "ta": "மீகாவின் சகோதரனாகிய இஷியாவும், இஷியாவின குமாரரில் சகரியாவும்,", "en": "The brother of Michah was Isshiah: of the sons of Isshiah; Zechariah."}, {"verse": 26, "start": 250.81, "end": 257.4, "ta": "மெராரியின் குமாரராகிய மகேலிமூசி என்பவர்களும், யாசியாவின் குமாரனாகிய பேனோவும்,", "en": "The sons of Merari were Mahli and Mushi: the sons of Jaaziah; Beno."}, {"verse": 27, "start": 257.4, "end": 265.02, "ta": "மெராரியின் குமாரனாகிய யாசியாவின் குமாரரான பேனோ, ரோகாம், சக்கூர், இப்ரி என்பவர்களும்,", "en": "The sons of Merari by Jaaziah; Beno, and Shoham, and Zaccur, and Ibri."}, {"verse": 28, "start": 265.02, "end": 268.99, "ta": "மகேலியின் குமாரரில் புத்திரனில்லாத எலெயாசாரும்,", "en": "Of Mahli came Eleazar, who had no sons."}, {"verse": 29, "start": 268.99, "end": 271.77, "ta": "கீசின் புத்திரரில் யெராமியேலும்,", "en": "Concerning Kish: the son of Kish was Jerahmeel."}, {"verse": 30, "start": 271.77, "end": 283.04, "ta": "மூசியின் குமாரரான மகேலி, ஏதேர் எரிமோத் என்பவர்களுமாகிய இவர்கள் தங்கள் பிதாக்களுடைய குடும்பங்களின்படியே லேவியரின் புத்திரரானவர்கள்.", "en": "The sons also of Mushi; Mahli, and Eder, and Jerimoth. These were the sons of the Levites after the house of their fathers."}, {"verse": 31, "start": 283.04, "end": 308.12, "ta": "இவர்களும் ராஜாவாகிய தாவீதுக்கும் சாதோக்குக்கும் அகிமெலேக்குக்கும் ஆசாரியரிலும் லேவியரிலும் பிதாக்களாயிருக்கிற தலைவருக்கும் முன்பாக, தங்கள் சகோதரராகிய ஆரோனின் புத்திரர் செய்ததுபோல, தங்களிலிருக்கிற பிதாக்களான தலைவருக்கும், அவர்களுடைய சிறிய சகோதரருக்கும், சரிசமானமாய்ச் சீட்டுப்போட்டுக்கொண்டார்கள்.", "en": "These likewise cast lots over against their brethren the sons of Aaron in the presence of David the king, and Zadok, and Ahimelech, and the chief of the fathers of the priests and Levites, even the principal fathers over against their younger brethren."}]}, "25": {"chapter": 25, "duration": 292.59, "audio_url": "audio_ot/OT13_25.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 27.11, "ta": "மேலும் சுரமண்டலங்களாலும் தம்புருகளாலும் கைத்தாளங்களாலும், தீர்க்கதரிசனம் சொல்லுகிற ஆசாப், ஏமான், எதுத்தூன் என்பவர்களின் குமாரரில் சிலரை, தாவீதும் தேவாலயச் சேனைகளின் பிரபுக்களும் ஊழியத்திற்கென்று பிரித்துவைத்தார்கள்; தங்கள் ஊழியத்தின் கிரியைக்குக் குறித்துவைக்கப்பட்ட மனுஷர்களின் தொகையாவது:", "en": "Moreover David and the captains of the host separated to the service of the sons of Asaph, and of Heman, and of Jeduthun, who should prophesy with harps, with psalteries, and with cymbals: and the number of the workmen according to their service was:"}, {"verse": 2, "start": 27.11, "end": 39.86, "ta": "ராஜாவுடைய கட்டளைப்பிரமாணமாய்த் தீர்க்கதரிசனம் சொல்லுகிற ஆசாப்பின் வசத்திலிருக்கிற, ஆசாப்பின் குமாரரில் சக்கூர், யோசேப்பு, நெதானியா, அஷாரேலா என்பவர்களும்,", "en": "Of the sons of Asaph; Zaccur, and Joseph, and Nethaniah, and Asarelah, the sons of Asaph under the hands of Asaph, which prophesied according to the order of the king."}, {"verse": 3, "start": 39.86, "end": 56.49, "ta": "கர்த்தரைப் போற்றித் துதித்துத் தீர்க்கதரிசனம் சொல்லுகிற தங்கள் தகப்பனாகிய எதுத்தூனின் வசத்திலே சுரமண்டலங்களை வாசிக்க, எதுத்தூனின் குமாரராகிய கெதலியா, சேரீ, எஷாயா, அஷபியா, மத்தித்தியா என்னும் ஆறுபேரும்,", "en": "Of Jeduthun: the sons of Jeduthun; Gedaliah, and Zeri, and Jeshaiah, Hashabiah, and Mattithiah, six, under the hands of their father Jeduthun, who prophesied with a harp, to give thanks and to praise the LORD ."}, {"verse": 4, "start": 56.49, "end": 78.36, "ta": "கொம்பைத் தொனிக்கப்பண்ண, தேவவிஷயத்தில் ராஜாவுக்கு ஞானதிருஷ்டிக்காரனாகிய ஏமானின் குமாரர் புக்கியா, மத்தனியா, ஊசியேல், செபுவேல், எரிமோத், அனனியா, அனானி, எலியாத்தா, கிதல்தி, ரொமந்தியேசர், யோஸ்பெகாஷா, மலோத்தி, ஒத்திர், மகாசியோத் என்பவர்களுமே.", "en": "Of Heman: the sons of Heman; Bukkiah, Mattaniah, Uzziel, Shebuel, and Jerimoth, Hananiah, Hanani, Eliathah, Giddalti, and Romamti-ezer, Joshbekashah, Mallothi, Hothir, and Mahazioth:"}, {"verse": 5, "start": 78.36, "end": 88.53, "ta": "இவர்களெல்லாரும் ஏமானின் குமாரராயிருந்தார்கள்; தேவன் ஏமானுக்குப் பதினாலு குமாரரையும் மூன்று குமாரத்திகளையும் கொடுத்தார்.", "en": "All these were the sons of Heman the king’s seer in the words of God, to lift up the horn. And God gave to Heman fourteen sons and three daughters."}, {"verse": 6, "start": 88.53, "end": 108.5, "ta": "இவர்கள் அனைவரும் ராஜாவுடைய கட்டளைப்பிரமாணமாய்க் கர்த்தருடைய ஆலயத்தில் தாளங்கள் தம்புருகள் சுரமண்டலங்களாகிய கீதவாத்தியம் வாசிக்க, தேவனுடைய ஆலயத்தின் ஊழியமாக அவரவர் தங்கள் தங்கள் தகப்பன்மாராகிய ஆசாப் எதுத்தூன், ஏமான் என்பவர்கள் வசத்தில் இருந்தார்கள்.", "en": "All these were under the hands of their father for song in the house of the LORD , with cymbals, psalteries, and harps, for the service of the house of God, according to the king’s order to Asaph, Jeduthun, and Heman."}, {"verse": 7, "start": 108.5, "end": 119.89, "ta": "கர்த்தரைப் பாடும் பாட்டுகளைக் கற்றுக்கொண்டு, நிபுணரான தங்கள் சகோதரரோடுங்கூட அவர்கள் இலக்கத்திற்கு இருநூற்றெண்பத்தெட்டுப்பேராயிருந்தார்கள்.", "en": "So the number of them, with their brethren that were instructed in the songs of the LORD , even all that were cunning, was two hundred fourscore and eight."}, {"verse": 8, "start": 119.89, "end": 129.45, "ta": "அவர்களில் சிறியவனும் பெரியவனும், ஆசானும் மாணாக்கனும், சரிசமானமாய் முறைவரிசைக்காகச் சீட்டுப்போட்டுக்கொண்டார்கள்.", "en": "And they cast lots, ward against ward , as well the small as the great, the teacher as the scholar."}, {"verse": 9, "start": 129.45, "end": 140.46, "ta": "முதலாவது சீட்டு ஆசாப் வம்சமான யோசேப்பின் பேர்வழிக்கும், இரண்டாவது கெதலியா, அவன் சகோதரர், அவன் குமாரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "Now the first lot came forth for Asaph to Joseph: the second to Gedaliah, who with his brethren and sons were twelve:"}, {"verse": 10, "start": 140.46, "end": 146.99, "ta": "மூன்றாவது சக்கூர், அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் வழிக்கும்,", "en": "The third to Zaccur, he , his sons, and his brethren, were twelve:"}, {"verse": 11, "start": 146.99, "end": 153.37, "ta": "நான்காவது இஸ்ரி, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் வழிக்கும்,", "en": "The fourth to Izri, he , his sons, and his brethren, were twelve:"}, {"verse": 12, "start": 153.37, "end": 159.97, "ta": "ஐந்தாவது நெத்தனியா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The fifth to Nethaniah, he , his sons, and his brethren, were twelve:"}, {"verse": 13, "start": 159.97, "end": 166.35, "ta": "ஆறாவது புக்கியா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The sixth to Bukkiah, he , his sons, and his brethren, were twelve:"}, {"verse": 14, "start": 166.35, "end": 172.5, "ta": "ஏழாவது எசரேலோ, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர்வழிக்கும்,", "en": "The seventh to Jesharelah, he , his sons, and his brethren, were twelve:"}, {"verse": 15, "start": 172.5, "end": 178.8, "ta": "எட்டாவது எஷாயா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The eighth to Jeshaiah, he , his sons, and his brethren, were twelve:"}, {"verse": 16, "start": 178.8, "end": 184.95, "ta": "ஒன்பதாவது மத்தனீயா, அவன் குமாரர், அவன் சகோதரர் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The ninth to Mattaniah, he , his sons, and his brethren, were twelve:"}, {"verse": 17, "start": 184.95, "end": 191.33, "ta": "பத்தாவது சிமேயா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The tenth to Shimei, he , his sons, and his brethren, were twelve:"}, {"verse": 18, "start": 191.33, "end": 198.01, "ta": "பதினோராவது அசாரியேல், அவன்குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The eleventh to Azareel, he , his sons, and his brethren, were twelve:"}, {"verse": 19, "start": 198.01, "end": 204.84, "ta": "பன்னிரண்டாவது அஷாபியா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The twelfth to Hashabiah, he , his sons, and his brethren, were twelve:"}, {"verse": 20, "start": 204.84, "end": 211.75, "ta": "பதின்மூன்றாவது சுபவேல், அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The thirteenth to Shubael, he , his sons, and his brethren, were twelve:"}, {"verse": 21, "start": 211.75, "end": 219.12, "ta": "பதினான்காவது மத்தித்தியா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The fourteenth to Mattithiah, he , his sons, and his brethren, were twelve:"}, {"verse": 22, "start": 219.12, "end": 224.89, "ta": "பதினைந்தாவது எரேமோத், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The fifteenth to Jeremoth, he , his sons, and his brethren, were twelve:"}, {"verse": 23, "start": 224.89, "end": 231.72, "ta": "பதினாறாவது அனனியா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The sixteenth to Hananiah, he , his sons, and his brethren, were twelve:"}, {"verse": 24, "start": 231.72, "end": 238.7, "ta": "பதினேழாவது யோஸ்பேக்காஷா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டு பேர்வழிக்கும்,", "en": "The seventeenth to Joshbekashah, he , his sons, and his brethren, were twelve:"}, {"verse": 25, "start": 238.7, "end": 245.61, "ta": "பதினெட்டாவது ஆனானி, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The eighteenth to Hanani, he , his sons, and his brethren, were twelve:"}, {"verse": 26, "start": 245.61, "end": 253.05, "ta": "பத்தொன்பதாவது, மலோத்தி, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The nineteenth to Mallothi, he , his sons, and his brethren, were twelve:"}, {"verse": 27, "start": 253.05, "end": 259.96, "ta": "ருபதாவது எலியாத்தா, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The twentieth to Eliathah, he , his sons, and his brethren, were twelve:"}, {"verse": 28, "start": 259.96, "end": 267.1, "ta": "இருபத்தோராவது ஒத்திர், அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The one and twentieth to Hothir, he , his sons, and his brethren, were twelve:"}, {"verse": 29, "start": 267.1, "end": 274.46, "ta": "இருபத்திரண்டாவது கிதல்தி, அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The two and twentieth to Giddalti, he , his sons, and his brethren, were twelve:"}, {"verse": 30, "start": 274.46, "end": 282.06, "ta": "இருபத்துமூன்றாவது மகாசியோத், அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும்,", "en": "The three and twentieth to Mahazioth, he , his sons, and his brethren, were twelve:"}, {"verse": 31, "start": 282.06, "end": 291.09, "ta": "இருபத்துநான்காவது ரொமந்தியேசர், அவன் குமாரர், அவன் சகோதரரென்னும் பன்னிரண்டுபேர் பேர்வழிக்கும் விழுந்தது.", "en": "The four and twentieth to Romamti-ezer, he , his sons, and his brethren, were twelve."}]}, "26": {"chapter": 26, "duration": 383.18, "audio_url": "audio_ot/OT13_26.mp3", "total_verses": 32, "verses": [{"verse": 1, "start": 3.8, "end": 12.89, "ta": "வாசல்காக்கிறவர்களின் வகுப்புகளாவன: கோராகியர் சந்ததியான ஆசாபின் புத்திரரிலே கோரேயின் குமாரன் மெஷெலேமியா என்பவன்,", "en": "Concerning the divisions of the porters: Of the Korhites was Meshelemiah the son of Kore, of the sons of Asaph."}, {"verse": 2, "start": 12.89, "end": 17.11, "ta": "மெஷெலேமியாவின் குமாரர், மூத்தவனாகிய சகரியாவும்,", "en": "And the sons of Meshelemiah were , Zechariah the firstborn, Jediael the second, Zebadiah the third, Jathniel the fourth,"}, {"verse": 3, "start": 17.11, "end": 28.43, "ta": "எதியாயேல், செபதியா, யதனியேல், ஏலாம், யோகனான், எலியோனாய் என்னும் இரண்டாம் மூன்றாம் நான்காம் ஐந்தாம் ஆறாம் ஏழாம் குமாரரும்;", "en": "Elam the fifth, Jehohanan the sixth, Elioenai the seventh."}, {"verse": 4, "start": 28.43, "end": 32.58, "ta": "ஒபேத் ஏதோமின் குமாரர், மூத்தவனாகிய செமாயாவும்,", "en": "Moreover the sons of Obed-edom were , Shemaiah the firstborn, Jehozabad the second, Joah the third, and Sacar the fourth, and Nethaneel the fifth,"}, {"verse": 5, "start": 32.58, "end": 48.92, "ta": "யோசபாத், யோவாக், சாக்கார், நெனெயேல், அம்மியேல், இசக்கார், பெயுள்தாயி என்னும் இரண்டாம் மூன்றாம் நான்காம் ஐந்தாம் ஆறாம் ஏழாம் எட்டாம் குமாரருமே, தேவன் அவனை ஆசீர்வதித்திருந்தார்.", "en": "Ammiel the sixth, Issachar the seventh, Peulthai the eighth: for God blessed him."}, {"verse": 6, "start": 48.92, "end": 59.84, "ta": "அவன் குமாரனாகிய செமாயாவுக்கும் குமாரர் பிறந்து, அவர்கள் பராக்கிரமசாலிகளாயிருந்து, தங்கள் தகப்பன் குடும்பத்தாரை ஆண்டார்கள்.", "en": "Also unto Shemaiah his son were sons born, that ruled throughout the house of their father: for they were mighty men of valour."}, {"verse": 7, "start": 59.84, "end": 71.56, "ta": "செமாயாவுக்கு இருந்த குமாரர் ஒத்னியும், பலசாலிகளாகிய ரெப்பாயேல், ஓபேத், எல்சாபாத என்னும் அவன் சகோதரரும், எலிகூவும் செமகியாவுமே.", "en": "The sons of Shemaiah; Othni, and Rephael, and Obed, Elzabad, whose brethren were strong men, Elihu, and Semachiah."}, {"verse": 8, "start": 71.56, "end": 83.2, "ta": "ஓபேத்ஏதோமின் புத்திரரும் அவர்கள் குமாரரும் அவர்கள் சகோதரருமாகிய ஊழியத்திற்குப் பலத்த பராக்கிரமசாலிகளான அவர்களெல்லாரும் அறுபத்திரண்டுபேர்.", "en": "All these of the sons of Obed-edom: they and their sons and their brethren, able men for strength for the service, were threescore and two of Obed-edom."}, {"verse": 9, "start": 83.2, "end": 89.42, "ta": "மெஷெலேமியாவின் குமாரரும் சகோதரருமான பராக்கிரமசாலிகள் பதினெட்டுப்பேர்.", "en": "And Meshelemiah had sons and brethren, strong men, eighteen."}, {"verse": 10, "start": 89.42, "end": 102.02, "ta": "மெராரியின் புத்திரரில் ஓசா என்பவனுடைய குமாரர்கள்: சிம்ரி என்னும் தலைமையானவன்; இவன் மூத்தவனாயிராவிட்டாலும் இவன் தகப்பன் இவனைத் தலைவனாக வைத்தான்.", "en": "Also Hosah, of the children of Merari, had sons; Simri the chief, (for though he was not the firstborn, yet his father made him the chief;)"}, {"verse": 11, "start": 102.02, "end": 114.37, "ta": "இல்க்கியா, தெபலியா, சகரியா என்னும் இரண்டாம், மூன்றாம் நான்காம் குமாரரானவர்கள்; ஓசாவின் குமாரரும் சகோதரரும் எல்லாம் பதின்மூன்றுபேர்.", "en": "Hilkiah the second, Tebaliah the third, Zechariah the fourth: all the sons and brethren of Hosah were thirteen."}, {"verse": 12, "start": 114.37, "end": 125.77, "ta": "காவல்காரரான தலைவரின் கீழ்த் தங்கள் சகோதரருக்கு ஒத்த முறையாய், கர்த்தருடைய ஆலயத்தில் வாசல்காக்கிறவர்களாய்ச் சேவிக்க இவர்கள் வகுக்கப்பட்டு,", "en": "Among these were the divisions of the porters, even among the chief men, having wards one against another, to minister in the house of the LORD ."}, {"verse": 13, "start": 125.77, "end": 136.14, "ta": "தங்கள் பிதாக்களின் குடும்பத்தாராகிய சிறியவர்களும் பெரியவர்களுமாய் இன்ன வாசலுக்கு இன்னாரென்று சீட்டுப்போட்டுக்கொண்டார்கள்.", "en": "And they cast lots, as well the small as the great, according to the house of their fathers, for every gate."}, {"verse": 14, "start": 136.14, "end": 151.6, "ta": "கீழ்ப்புறத்திற்குச் செலேமியாவுக்குச் சீட்டு விழுந்தது; விவேகமுள்ள யோசனைக்காரனாகிய சகரியா என்னும் அவன் குமாரனுக்குச் சீட்டுப் போட்டபோது, அவன் சீட்டு வடபுறத்திற்கென்று விழுந்தது.", "en": "And the lot eastward fell to Shelemiah. Then for Zechariah his son, a wise counsellor, they cast lots; and his lot came out northward."}, {"verse": 15, "start": 151.6, "end": 158.14, "ta": "ஓபேத்ஏதேமுக்குத் தென்புறத்திற்கும், அவன் குமாரருக்கு அசுப்பீம் வீட்டிற்கும்,", "en": "To Obed-edom southward; and to his sons the house of Asuppim."}, {"verse": 16, "start": 158.14, "end": 169.62, "ta": "சூப்பீமுக்கும், ஓசாவுக்கும் மண்போட்டு உயர்த்தப்பட்ட வழியும் காவலுக்கு எதிர்காவலும் இருக்கிற மேற்புறமான வாசலுக்கும் சீட்டு விழுந்தது.", "en": "To Shuppim and Hosah the lot came forth westward, with the gate Shallecheth, by the causeway of the going up, ward against ward."}, {"verse": 17, "start": 169.62, "end": 180.78, "ta": "கிழக்கே லேவியரான ஆறுபேரும், வடக்கே பகலிலே நாலுபேரும், தெற்கே பகலிலே நாலுபேரும், அசுப்பீம் வீட்டண்டையில் இரண்டிரண்டுபேரும்.", "en": "Eastward were six Levites, northward four a day, southward four a day, and toward Asuppim two and two."}, {"verse": 18, "start": 180.78, "end": 191.7, "ta": "வெளிப்புறமான வாசல் அண்டையில் மேற்கே இருக்கிற உயர்ந்த வழிக்கு நாலுபேரும், வெளிப்புறமான வழியிலே இரண்டுபேரும் வைக்கப்பட்டார்கள்.", "en": "At Parbar westward, four at the causeway, and two at Parbar."}, {"verse": 19, "start": 191.7, "end": 200.95, "ta": "கோராகின் புத்திரருக்குள்ளும், மெராரியின் புத்திரருக்குள்ளும், வாசல்காக்கிறவர்களின் வகுப்புகள் இவைகளே.", "en": "These are the divisions of the porters among the sons of Kore, and among the sons of Merari."}, {"verse": 20, "start": 200.95, "end": 213.07, "ta": "மற்ற லேவியரில் அகியா என்பவன் தேவனுடைய ஆலயத்துப் பொக்கிஷங்களையும், பிரதிஷ்டையாக்கப்படட பொருள்களின் பொக்கிஷங்களையும் விசாரிக்கிறவனாயிருந்தான்.", "en": "And of the Levites, Ahijah was over the treasures of the house of God, and over the treasures of the dedicated things."}, {"verse": 21, "start": 213.07, "end": 221.12, "ta": "லாதானின் குமாரர் யாரென்றால் கெர்சோனியனான அவனுடைய குமாரரில் தலைமையான பிதாக்களாயிருந்த யெகியேலியும்,", "en": "As concerning the sons of Laadan; the sons of the Gershonite Laadan, chief fathers, even of Laadan the Gershonite, were Jehieli."}, {"verse": 22, "start": 221.12, "end": 233.4, "ta": "யெகியேலியின் குமாரராகிய சேத்தாமும், அவன் சகோதரனாகிய யோவேலுமே; இவர்கள் கர்த்தருடைய ஆலயத்துப் பொக்கிஷங்களை விசாரிக்கிறவர்களாயிருந்தார்கள்.", "en": "The sons of Jehieli; Zetham, and Joel his brother, which were over the treasures of the house of the LORD ."}, {"verse": 23, "start": 233.4, "end": 244.32, "ta": "அம்ராமியரிலும், இத்சேயாரியரிலும், எப்ரோனியரிலும், ஊசியேரியரிலும், சிலர், அப்படியே விசாரிக்கிறவர்களாயிருந்தார்கள்.", "en": "Of the Amramites, and the Izharites, the Hebronites, and the Uzzielites:"}, {"verse": 24, "start": 244.32, "end": 251.34, "ta": "மோசேயின் குமாரனாகிய கெர்சோமின் சந்ததியான செபுவேல் பொக்கிஷப்பிரதானியாயிருந்தான்.", "en": "And Shebuel the son of Gershom, the son of Moses, was ruler of the treasures."}, {"verse": 25, "start": 251.34, "end": 267.2, "ta": "ஏலியேசர் மூலமாய் அவனுக்கு இருந்த சகோதரரானவர்கள், இவன் குமாரன் ரெகபியாவும், இவன் குமாரன் எஷாயாவும், இவன் குமாரன் யோராமும், இவன் குமாரன் சிக்கிரியும், இவன் குமாரன் செலோமித்துமே.", "en": "And his brethren by Eliezer; Rehabiah his son, and Jeshaiah his son, and Joram his son, and Zichri his son, and Shelomith his son."}, {"verse": 26, "start": 267.2, "end": 279.64, "ta": "ராஜாவாகிய தாவீதும், ஆயிரம்பேருக்கு அதிபதிகளும், நூறுபேருக்கு அதிகமான பிதாக்களின் தலைவரும், அதிபதிகளும் யுத்தத்தில் அகப்பட்ட கொள்ளைகளில் எடுத்து,", "en": "Which Shelomith and his brethren were over all the treasures of the dedicated things, which David the king, and the chief fathers, the captains over thousands and hundreds, and the captains of the host, had dedicated."}, {"verse": 27, "start": 279.64, "end": 293.35, "ta": "கர்த்தருடைய ஆலயத்தைப் பரிபாலிக்கும்படிக்குப் பரிசுத்தம் என்று நேர்ந்துகொண்ட பொருள்களின் பொக்கிஷங்களையெல்லாம் அந்தச் செலோமித்தும் அவனுடைய சகோதரரும் விசாரித்தார்கள்.", "en": "Out of the spoils won in battles did they dedicate to maintain the house of the LORD ."}, {"verse": 28, "start": 293.35, "end": 311.05, "ta": "ஞானதிருஷ்டிக்காரனாகிய சாமுவேலும், நேரின் குமாரனாகிய அப்னேரும், செருயாவின் குமாரராகிய யோவாபும், அவரவர் பரிசுத்தம் என்று நேர்ந்துகொண்ட அனைத்தும் செலோமித்தின் கையின்கீழும் அவன் சகோதரர் கையின்கீழும் இருந்தது.", "en": "And all that Samuel the seer, and Saul the son of Kish, and Abner the son of Ner, and Joab the son of Zeruiah, had dedicated; and whosoever had dedicated any thing, it was under the hand of Shelomith, and of his brethren."}, {"verse": 29, "start": 311.05, "end": 323.72, "ta": "இத்சேயாரியரில் கெனானியாவும் அவன் குமாரரும் தேசகாரியங்களைப் பார்க்கும்படி வைக்கப்பட்டு, இஸ்ரவேலின்மேல் விசாரிப்புக்காரரும் மணியகாரருமாயிருந்தார்கள்.", "en": "Of the Izharites, Chenaniah and his sons were for the outward business over Israel, for officers and judges."}, {"verse": 30, "start": 323.72, "end": 340.46, "ta": "எப்ரோனியரில் அசபியாவும் அவன் சகோதரருமாகிய ஆயிரத்து எழுநூறுபராக்கிரமசாலிகள் யோர்தானுக்கு இப்பாலே, மேற்கே இருக்கிற இஸ்ரவேலின் கர்த்தருடைய எல்லா ஊழியத்திற்கும் ராஜாவின் வேலைக்கும், கீழ்ப்பட்டார்கள்.", "en": "And of the Hebronites, Hashabiah and his brethren, men of valour, a thousand and seven hundred, were officers among them of Israel on this side Jordan westward in all the business of the LORD , and in the service of the king."}, {"verse": 31, "start": 340.46, "end": 359.84, "ta": "எப்ரோனியரில் எரியாவும் இருந்தான்; அவன் தன் பிதாக்களின் வம்சங்களான எப்ரோனியரில் தலைமையானவன்; தாவீது அரசாண்ட நாற்பதாம் வருஷத்திலே அவர்கள் தேடப்பட்டபோது அவர்களுக்குள்ளே கீலேயாத்தேசத்து ஏசேரிலே பராக்கிரம வீரர் காணப்பட்டார்கள்.", "en": "Among the Hebronites was Jerijah the chief, even among the Hebronites, according to the generations of his fathers. In the fortieth year of the reign of David they were sought for, and there were found among them mighty men of valour at Jazer of Gilead."}, {"verse": 32, "start": 359.84, "end": 381.68, "ta": "பலசாலிகளாகிய அவர்களுடைய சகோதரர் இரண்டாயிரத்து எழுநூறு பிரதான தலைவராயிருந்தார்கள்; அவர்களைத் தாவீது ராஜா தேவனுக்கடுத்த சகல காரியத்திற்காகவும், ராஜாவின் காரியத்கிற்காகவும், ரூபனியர்மேலும், காதியர்மேலும், மனாசேயின் பாதிக்கோத்திரத்தின்மேலும் வைத்தான்.", "en": "And his brethren, men of valour, were two thousand and seven hundred chief fathers, whom king David made rulers over the Reubenites, the Gadites, and the half tribe of Manasseh, for every matter pertaining to God, and affairs of the king."}]}, "27": {"chapter": 27, "duration": 406.37, "audio_url": "audio_ot/OT13_27.mp3", "total_verses": 34, "verses": [{"verse": 1, "start": 3.8, "end": 36.23, "ta": "தங்கள் இலக்கத்தின்படி இருக்கிற இஸ்ரவேல் புத்திரருக்கு வம்சங்களின் தலைவரும், ஆரயித்துக்குச் சேர்வைக்காரரும், நூற்றிற்குச் சேர்வைக்காரரும், இவர்களுடைய தலைவரும் வைக்கப்பட்டிருந்தார்கள்; இவர்கள் வருஷத்திலுண்டான மாதங்களிலெல்லாம் மாதத்திற்கு மாதம் ராஜாவைச் சேவிக்கிறதற்கு வகுக்கப்பட்ட வரிசைகளின்படியெல்லாம் மாறிமாறி வருவார்கள்; ஒவ்வொரு வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "Now the children of Israel after their number, to wit , the chief fathers and captains of thousands and hundreds, and their officers that served the king in any matter of the courses, which came in and went out month by month throughout all the months of the year, of every course were twenty and four thousand."}, {"verse": 2, "start": 36.23, "end": 48.0, "ta": "முதலாவது மாதத்துக்கு முதல் வகுப்பின்மேல் சப்தியேலின் குமாரன் யஷொபெயாம் இருந்தான்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "Over the first course for the first month was Jashobeam the son of Zabdiel: and in his course were twenty and four thousand."}, {"verse": 3, "start": 48.0, "end": 55.45, "ta": "அவன் பேரேசின் சந்ததியாரில் சகல சேனாபதிகளின் தலைவனாயிருந்து முதல் மாதம் விசாரித்தான்.", "en": "Of the children of Perez was the chief of all the captains of the host for the first month."}, {"verse": 4, "start": 55.45, "end": 69.14, "ta": "இரண்டாவது மாதத்தின் வகுப்பின்மேல் அகோகியனான தோதாயி இருந்தான்; அவன் வகுப்பிலே மிக்லோத் தளகர்த்தனாயிருந்தான்; அவன் வகுப்பிலே நாலாயிரம்பேர் இருந்தார்கள்.", "en": "And over the course of the second month was Dodai an Ahohite, and of his course was Mikloth also the ruler: in his course likewise were twenty and four thousand."}, {"verse": 5, "start": 69.14, "end": 80.75, "ta": "மூன்றாவது மாதத்தின் மூன்றாம் சேனாபதி யோய்தாவின் குமாரனாகிய பெனாயா என்னும் தலைமையான பிரதானி வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The third captain of the host for the third month was Benaiah the son of Jehoiada, a chief priest: and in his course were twenty and four thousand."}, {"verse": 6, "start": 80.75, "end": 94.12, "ta": "இந்தப் பெனாயா அந்த முப்பது பராக்கிரமசாலிகளில் ஒருவனும் அந்த முப்பது பேர்களின் தலைவனுமாயிருந்தான்; அவனுடைய வகுப்பை அவன் குமாரனாகிய அமிசபாத் விசாரித்தான்.", "en": "This is that Benaiah, who was mighty among the thirty, and above the thirty: and in his course was Ammizabad his son."}, {"verse": 7, "start": 94.12, "end": 108.13, "ta": "நாலாவது மாதத்தின் நாலாம் சேனாபதி யோவாபின் சகோதரனாகிய ஆசகேலும், அவனுக்குப்பின்பு அவன் குமாரன் செப்தியாவுமே; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The fourth captain for the fourth month was Asahel the brother of Joab, and Zebadiah his son after him: and in his course were twenty and four thousand."}, {"verse": 8, "start": 108.13, "end": 118.46, "ta": "ஐந்தாவது மாதத்தின் ஐந்தாம் சேனாபதி இஸ்ராகியனான சம்கூத் என்பவன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The fifth captain for the fifth month was Shamhuth the Izrahite: and in his course were twenty and four thousand."}, {"verse": 9, "start": 118.46, "end": 129.59, "ta": "ஆறாவது மாதத்தின் ஆறாம் சேனாபதி இக்கேசின் குமாரன் ஈரா என்னும் தெக்கோவியன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The sixth captain for the sixth month was Ira the son of Ikkesh the Tekoite: and in his course were twenty and four thousand."}, {"verse": 10, "start": 129.59, "end": 141.92, "ta": "ஏழாவது மாத்தின் ஏழாம் சேனாபதி எப்பிராயீம் புத்திரரில் ஒருவனாகிய ஏலேஸ் என்னும் பெலோனியன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The seventh captain for the seventh month was Helez the Pelonite, of the children of Ephraim: and in his course were twenty and four thousand."}, {"verse": 11, "start": 141.92, "end": 154.01, "ta": "எட்டாவது மாதத்தின் எட்டாம் சேனாபதி சாரியரில் ஒருவனாகிய சிபெக்காயி என்னும் ஊஷாத்தியன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The eighth captain for the eighth month was Sibbecai the Hushathite, of the Zarhites: and in his course were twenty and four thousand."}, {"verse": 12, "start": 154.01, "end": 165.54, "ta": "ஒன்பதாவது மாதத்தின் ஒன்பதாம் சேனாபதி பென்யமீனரில் அபியேசர் என்னும் ஆனதோத்தான்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The ninth captain for the ninth month was Abi-ezer the Anetothite, of the Benjamites: and in his course were twenty and four thousand."}, {"verse": 13, "start": 165.54, "end": 177.79, "ta": "பத்தாவது மாதத்தின் பத்தாம் சேனாபதி சாரியரில் ஒருவனாகிய மக்ராயி என்னும் நெத்தோபாத்தியன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The tenth captain for the tenth month was Maharai the Netophathite, of the Zarhites: and in his course were twenty and four thousand."}, {"verse": 14, "start": 177.79, "end": 190.36, "ta": "பதினோராவது மாதத்தின் பதினோராம் சேனாபதி எப்பிராயீம் புத்திரரில் பெனாயா என்னும் பிரத்தோனியன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The eleventh captain for the eleventh month was Benaiah the Pirathonite, of the children of Ephraim: and in his course were twenty and four thousand."}, {"verse": 15, "start": 190.36, "end": 203.41, "ta": "பன்னிரண்டாவது மாதத்தின் பன்னிரண்டாம் சேனாபதி ஒத்னியேல் சந்ததியான எல்தாயி என்னும் நெத்தோபாத்தியன்; அவன் வகுப்பில் இருபத்துநாலாயிரம்பேர் இருந்தார்கள்.", "en": "The twelfth captain for the twelfth month was Heldai the Netophathite, of Othniel: and in his course were twenty and four thousand."}, {"verse": 16, "start": 203.41, "end": 216.07, "ta": "இஸ்ரவேல் கோத்திரங்களுக்குத் தலைவர்கள்; ரூபனியருக்குத் தலைவன் சிக்ரியின் குமாரன் எலியேசர்; சிமியோனியருக்கு மாக்காவின் குமாரன் செப்பத்தியா.", "en": "Furthermore over the tribes of Israel: the ruler of the Reubenites was Eliezer the son of Zichri: of the Simeonites, Shephatiah the son of Maachah:"}, {"verse": 17, "start": 216.07, "end": 222.55, "ta": "லேவியருக்கு கேமுவேலின் குமாரன் அஷாபியா; ஆரோன் சந்ததிக்குச் சாதோக்.", "en": "Of the Levites, Hashabiah the son of Kemuel: of the Aaronites, Zadok:"}, {"verse": 18, "start": 222.55, "end": 230.72, "ta": "யூதாவுக்குத் தாவீதின் சகோதரரில் ஒருவனாகிய எலிகூ; இசக்காருக்கு மிகாவேலின் குமாரன் ஒம்ரி.", "en": "Of Judah, Elihu, one of the brethren of David: of Issachar, Omri the son of Michael:"}, {"verse": 19, "start": 230.72, "end": 238.4, "ta": "செபுலோனுக்கு ஒப்தியாவின் குமாரன் இஸ்மாயா; நப்தலிக்கு அஸ்ரியேலின் குமாரன் எரிமோத்.", "en": "Of Zebulun, Ishmaiah the son of Obadiah: of Naphtali, Jerimoth the son of Azriel:"}, {"verse": 20, "start": 238.4, "end": 248.57, "ta": "எப்பிராயீம் புத்திரருக்கு அசசியாவின் குமாரன் ஓசெயா; மனாசேயின் பாதிக்கோத்திரத்திற்குப் பெதாயாவின் குமாரன் யோவேல்.", "en": "Of the children of Ephraim, Hoshea the son of Azaziah: of the half tribe of Manasseh, Joel the son of Pedaiah:"}, {"verse": 21, "start": 248.57, "end": 259.14, "ta": "கிலேயாத்திலுள்ள மனாசேயின் பாதிக்கோத்திரத்திற்குச் சகரியாவின் குமாரன் இத்தோ; பென்யமீனுக்கு அப்னேரின் குமாரன் யாசியேல்.", "en": "Of the half tribe of Manasseh in Gilead, Iddo the son of Zechariah: of Benjamin, Jaasiel the son of Abner:"}, {"verse": 22, "start": 259.14, "end": 267.87, "ta": "தாணுக்கு எரோகாமின் குமாரன் அசாரியேல்; இவர்கள் இஸ்ரவேல் கோத்திரங்களுக்குத் தலைவராயிருந்தார்கள்.", "en": "Of Dan, Azareel the son of Jeroham. These were the princes of the tribes of Israel."}, {"verse": 23, "start": 267.87, "end": 283.32, "ta": "இஸ்ரவேலை வானத்தின் நட்சத்திரங்கள் அத்தனையாய்ப் பெருகப்பண்ணுவேன் என்று கர்த்தர் சொல்லியிருந்தபடியால்; தாவீது இருபது வயதுமுதல் அதற்கு கீழ்ப்பட்டவர்களின் இலக்கத்தைத்தொகையேற்றவில்லை.", "en": "But David took not the number of them from twenty years old and under: because the LORD had said he would increase Israel like to the stars of the heavens."}, {"verse": 24, "start": 283.32, "end": 298.14, "ta": "செருயாவின் குமாரன் யோவாப் எண்ணத்துவக்கியும் முடிக்காதேபோனான்; அதற்காக இஸ்ரவேலின்மேல் கடுங்கோபம் வந்தது; ஆதலால் அந்தத்தொகை தாவீது ராஜாவின் நாளாகமக்கணக்கிலே ஏறவில்லை.", "en": "Joab the son of Zeruiah began to number, but he finished not, because there fell wrath for it against Israel; neither was the number put in the account of the chronicles of king David."}, {"verse": 25, "start": 298.14, "end": 312.87, "ta": "ராஜாவுடைய பொக்கிஷங்களின்மேல் ஆதியேலின் குமாரன் அஸ்மாவேத்தும், பட்டணங்களிலும் கிராமங்களிலும் துருக்கங்களிலுமுள்ள நிலத்தின் வருமான பண்டகசாலைகளின்மேல் உசியாவின் குமாரன் யோனத்தானும்,", "en": "And over the king’s treasures was Azmaveth the son of Adiel: and over the storehouses in the fields, in the cities, and in the villages, and in the castles, was Jehonathan the son of Uzziah:"}, {"verse": 26, "start": 312.87, "end": 319.76, "ta": "நிலத்தைப் பயிரிட வயல்வெளியின் வேலைசெய்கிறவர்களின்மேல் கேலுூப்பின்குமாரன் எஸ்ரியும்,", "en": "And over them that did the work of the field for tillage of the ground was Ezri the son of Chelub:"}, {"verse": 27, "start": 319.76, "end": 331.37, "ta": "திராட்சத்தோட்டங்களின்மேல் ராமாத்தியனான சீமேயும், திராட்சத்தோட்டங்களின் வரத்தாகிய திராட்சரசம் வைக்கும் இடங்களின்மேல் சிப்மியனாகிய சப்தியும்,", "en": "And over the vineyards was Shimei the Ramathite: over the increase of the vineyards for the wine cellars was Zabdi the Shiphmite:"}, {"verse": 28, "start": 331.37, "end": 342.42, "ta": "பள்ளத்தாக்குகளிலுள்ள ஒலிவமரங்களின்மேலும் முசுக்கட்டை விருட்சங்கனின்மேலும் கெதேரியனான பால்கானானும், எண்ணெய்கிடங்குகளின்மேல் யோவாசும்,", "en": "And over the olive trees and the sycomore trees that were in the low plains was Baal-hanan the Gederite: and over the cellars of oil was Joash:"}, {"verse": 29, "start": 342.42, "end": 352.5, "ta": "சாரோனில் மேய்கிற மாடுகளின்மேல் சாரோனியனான சித்ராயும், பள்ளத்தாக்குகளிலுள்ள மாடுகளின்மேல் அத்லாயின் குமாரன் சாப்பாத்தும்,", "en": "And over the herds that fed in Sharon was Shitrai the Sharonite: and over the herds that were in the valleys was Shaphat the son of Adlai:"}, {"verse": 30, "start": 352.5, "end": 359.71, "ta": "ஒட்டகங்களின்மேல் இஸ்மவேலியனாகிய ஓபிலும், கழுதைகளின்மேல் மெரோனோத்தினாகிய எகெதியாவும்,", "en": "Over the camels also was Obil the Ishmaelite: and over the asses was Jehdeiah the Meronothite:"}, {"verse": 31, "start": 359.71, "end": 372.12, "ta": "ஆடுகளின்மேல் ஆகாரியனான யாசிசும் விசாரிப்புக்காரராயிருந்தார்கள்; இவர்களெல்லாரும் தாவீது ராஜாவின்பொருள்களுக்கு விசாரிப்புக்காரராயிருந்தார்கள்.", "en": "And over the flocks was Jaziz the Hagerite. All these were the rulers of the substance which was king David’s."}, {"verse": 32, "start": 372.12, "end": 385.73, "ta": "தாவீதின் சிறிய தகப்பனாகிய யோனத்தான் என்னும் புத்தியும் படிப்புமுள்ள மனுஷன் ஆலோசனைக்காரனாயிருந்தன்; அக்மோனியின் குமாரன் யெகியேல் ராஜாவின் குமாரரோடிருந்தான்.", "en": "Also Jonathan David’s uncle was a counsellor, a wise man, and a scribe: and Jehiel the son of Hachmoni was with the king’s sons:"}, {"verse": 33, "start": 385.73, "end": 394.22, "ta": "அகித்தோப்பேல் ராஜாவுக்கு ஆலோசனைக்காரனாயிருந்தான்; அர்கியனான ஊஷாயி ராஜாவின் தோழனாயிருந்தான்.", "en": "And Ahithophel was the king’s counsellor: and Hushai the Archite was the king’s companion:"}, {"verse": 34, "start": 394.22, "end": 404.87, "ta": "பெனாயாவின் குமாரன் யோய்தாவும் அபியத்தாரும் அகித்தோப்பேலுக் உதவியாயிருந்தார்கள்; யோவாப் ராஜாவின் படைத்தலைவனாயிருந்தான்.", "en": "And after Ahithophel was Jehoiada the son of Benaiah, and Abiathar: and the general of the king’s army was Joab."}]}, "28": {"chapter": 28, "duration": 389.76, "audio_url": "audio_ot/OT13_28.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 32.17, "ta": "கோத்திரங்களின் தலைவரும், ராஜாவைச் சேவிக்கிற வகுப்புகளின் தலைவரும், ஆயிரம்பேருக்கு அதிபதிகளும், நூறுபேருக்கு அதிபதிகளும் ராஜாவுக்கும் ராஜகுமாரருக்கும் உண்டான எல்லா ஆஸ்தியையும் மிருகஜீவன்களையும் விசாரிக்கிற தலைவருமாகிய இஸ்ரவேலின் சகல பிரபுக்களையும், பிரதானிகளையும், பலசாலிகளையும், சகல பராக்கிரமசாலிகளையும் தாவீது எருசலேமிலே கூடிவரச்செய்தான்.", "en": "And David assembled all the princes of Israel, the princes of the tribes, and the captains of the companies that ministered to the king by course, and the captains over the thousands, and captains over the hundreds, and the stewards over all the substance and possession of the king, and of his sons, with the officers, and with the mighty men, and with all the valiant men, unto Jerusalem."}, {"verse": 2, "start": 32.17, "end": 54.34, "ta": "அப்பொழுது ராஜாவாகிய தாவீது: எழுந்திருந்து காலுூன்றி நின்று: என் சகோதரரே, என் ஜனமே, நான் சொல்வதைக் கேளுங்கள்; கர்த்தருடைய உடன்படிக்கைப் பெட்டியும் நமது தேவனுடைய பாதபடியும் தங்குவதற்கு ஒரு ஆலயத்தைக் கட்ட நான் என் மனதிலே நினைத்து, கட்டுகிறதற்கு ஆயத்தமும் பண்ணினேன்.", "en": "Then David the king stood up upon his feet, and said, Hear me, my brethren, and my people: As for me , I had in mine heart to build an house of rest for the ark of the covenant of the LORD , and for the footstool of our God, and had made ready for the building:"}, {"verse": 3, "start": 54.34, "end": 64.41, "ta": "ஆனாலும் தேவன் நீ என் நாமத்திற்கு ஆலயத்தைக் கட்டவேண்டாம்; நீ யுத்த மனுஷனாயிருந்து, ரத்தத்தைச் சிந்தினாய் என்றார்.", "en": "But God said unto me, Thou shalt not build an house for my name, because thou hast been a man of war, and hast shed blood."}, {"verse": 4, "start": 64.41, "end": 92.32, "ta": "இப்போதும் இஸ்ரவேல் அனைத்தின்மேலும் என்றைக்கும் ராஜாவாயிருக்க, இஸ்ரவேலின் தேவனாகிய கர்த்தர் அவன் தகப்பனுடைய வீட்டாரில் எல்லாம் என்னைத் தெரிந்துகொண்டார்; அவர் யூதாவையும் யூதாவின் வம்சத்தில் அவன் தகப்பன் குடும்பத்தையும் தலைமையாக தெரிந்துகொண்டு, என்னை எல்லா இஸ்ரவேலின்மேலும் ராஜாவாக்க, என் தகப்பனுடைய குமாரருக்குள் என்மேல் பிரியம் வைத்தார்.", "en": "Howbeit the LORD God of Israel chose me before all the house of my father to be king over Israel for ever: for he hath chosen Judah to be the ruler; and of the house of Judah, the house of my father; and among the sons of my father he liked me to make me king over all Israel:"}, {"verse": 5, "start": 92.32, "end": 109.06, "ta": "கர்த்தர் எனக்கு அநேகம் குமாரரைத் தந்தருளினார்; ஆனாலும் இஸ்ரவேலை ஆளும் கர்த்தருடைய ராஜ்யபாரத்தின் சிங்காசனத்தின்மேல் உட்காருகிறதற்கு அவர் என்னுடைய எல்லாக் குமாரரிலும் என் குமாரனாகிய சாலொமோனைத் தெரிந்துகொண்டு,", "en": "And of all my sons, (for the LORD hath given me many sons,) he hath chosen Solomon my son to sit upon the throne of the kingdom of the LORD over Israel."}, {"verse": 6, "start": 109.06, "end": 123.71, "ta": "அவர் என்னை நோக்கி: உன் குமாரனாகிய சாலொமோனே என் ஆலயத்தையும் என் பிரகாரங்களையும் கட்டக்கடவன்; அவனை எனக்குக் குமாரனாகத் தெரிந்துகொண்டேன்; நான் அவனுக்குப் பிதாவாயிருப்பேன்.", "en": "And he said unto me, Solomon thy son, he shall build my house and my courts: for I have chosen him to be my son, and I will be his father."}, {"verse": 7, "start": 123.71, "end": 137.28, "ta": "இந்நாளில் நடக்கிறபடியே அவன் என் கற்பனைகளின்படியும் என் நியாயங்களின்படியும் செய்ய உறுதியாயிருப்பானானால், அவன் ராஜ்யபாரத்தை என்றென்றைக்கும் திடப்படுத்துவேன் என்றார்.", "en": "Moreover I will establish his kingdom for ever, if he be constant to do my commandments and my judgments, as at this day."}, {"verse": 8, "start": 137.28, "end": 166.96, "ta": "இப்போதும் நீங்கள் என்றென்றைக்கும் இந்த நல்ல தேசத்தைச் சுதந்தரமாய் அநுபவித்து, உங்களுக்குப்பிறகு அதை உங்கள் பிள்ளைகளுக்குச் சுதந்தமாய்ப் பின்வைக்கும்பொருட்டாக, நீங்கள் உங்கள் தேவனாகிய கர்த்தரின் கற்பனைகளையெல்லாம் கைக்கொண்டு விசாரியுங்கள் என்று கர்த்தரின் சபையாகிய இஸ்ரவேல் அனைத்தின் கண்களுக்குமுன்பாகவும், நமது தேவனுடைய செவிகேட்கவும் உங்களுக்குப் புத்திசொல்லுகிறேன்.", "en": "Now therefore in the sight of all Israel the congregation of the LORD , and in the audience of our God, keep and seek for all the commandments of the LORD your God: that ye may possess this good land, and leave it for an inheritance for your children after you for ever."}, {"verse": 9, "start": 166.96, "end": 191.77, "ta": "என் குமாரனாகிய சாலொமோனே, நீ என் பிதாவின் தேவனை அறிந்து, அவரை உத்தம இருதயத்தோடும் உற்சாக மனதோடும் சேவி; கர்த்தர் எல்லா இருதயங்களையும் ஆராய்ந்து, நினைவுகளின் தோற்றங்களையெல்லாம் அறிகிறார்; நீ அவரைத் தேடினால் உனக்குத் தென்படுவார்; நீ அவரை விட்டுவிட்டால் அவர் உன்னை என்றைக்கும் கைவிடுவார்.", "en": "And thou, Solomon my son, know thou the God of thy father, and serve him with a perfect heart and with a willing mind: for the LORD searcheth all hearts, and understandeth all the imaginations of the thoughts: if thou seek him, he will be found of thee; but if thou forsake him, he will cast thee off for ever."}, {"verse": 10, "start": 191.77, "end": 204.87, "ta": "இப்போதும் எச்சரிக்கையாயிரு; பரிசுத்த ஸ்தலமாக ஒரு ஆலயத்தைக்கட்டுவதற்குக் கர்த்தர் உன்னைத் தெரிந்துகொண்டார்; நீ திடன்கொண்டு அதை நடப்பி என்று சொன்னான்.", "en": "Take heed now; for the LORD hath chosen thee to build an house for the sanctuary: be strong, and do it ."}, {"verse": 11, "start": 204.87, "end": 219.44, "ta": "தாவீது தன் குமாரனாகிய சாலொமோனுக்கு மண்டபமும், அதின் அறைகளும், அதின் பொக்கிஷசாலைகளும், அதின் மேல்வீடுகளும், அதின் உள்ளறைகளும், கிருபாசன ஸ்தானம் இருக்கவேண்டிய மாதிரியையும்,", "en": "Then David gave to Solomon his son the pattern of the porch, and of the houses thereof, and of the treasuries thereof, and of the upper chambers thereof, and of the inner parlours thereof, and of the place of the mercy seat,"}, {"verse": 12, "start": 219.44, "end": 238.97, "ta": "ஆவியினால் தனக்குக் கட்டளையிடப்பட்டபடியெல்லாம் அவன் செய்யவேண்டிய கர்த்தருடைய ஆலயப்பிராகாரங்களும், தேவனுடைய ஆலயத்துப் பொக்கிஷங்களையும், பரிசுத்தமாக நேர்ந்துகொள்ளப்பட்டவைகளின் பொக்கிஷங்களையும் வைக்கும் சகல சுற்றறைகளும் இருக்கவேண்டிய மாதிரியையும்,", "en": "And the pattern of all that he had by the spirit, of the courts of the house of the LORD , and of all the chambers round about, of the treasuries of the house of God, and of the treasuries of the dedicated things:"}, {"verse": 13, "start": 238.97, "end": 254.09, "ta": "ஆசாரியரையும் லேவியரையும் வரிசைகளாக வகுக்கிறதற்கும், கர்த்தருடைய ஆலயப்பணிவிடை வேலை அனைத்திற்கும், கர்த்தருடைய ஆலயத்து வேலையின் பணிமுட்டுகள் அனைத்திற்குமுரிய கட்டளையையும் கொடுத்தான்.", "en": "Also for the courses of the priests and the Levites, and for all the work of the service of the house of the LORD , and for all the vessels of service in the house of the LORD ."}, {"verse": 14, "start": 254.09, "end": 266.88, "ta": "அவன் பற்பல வேலைக்கு வேண்டிய சகல பொற்பாத்திரங்களுக்காக நிறையின்படி பொன்னையும், பற்பல வேலைக்குவேண்டிய சகல வெள்ளிப்பாத்திரங்களுக்காக, நிறையின்படி வெள்ளியையும்,", "en": "He gave of gold by weight for things of gold, for all instruments of all manner of service; silver also for all instruments of silver by weight, for all instruments of every kind of service:"}, {"verse": 15, "start": 266.88, "end": 287.49, "ta": "பொன் விளக்குத்தண்டுகளுக்கும் அவைகளின் பொன் விளக்குகளுக்கும், ஒவ்வொரு விளக்குத்தண்டுக்கும் அதின் விளக்குகளுக்கும் நிறையின்படி வேண்டிய பொன்னையும், வெள்ளி விளக்குத்தண்டுகளில் ஒவ்வொரு விளக்குத்தண்டுக்கும் அதின் விளக்குகளுக்கும் நிறையின்படி வேண்டிய வெள்ளியையும்,", "en": "Even the weight for the candlesticks of gold, and for their lamps of gold, by weight for every candlestick, and for the lamps thereof: and for the candlesticks of silver by weight, both for the candlestick, and also for the lamps thereof, according to the use of every candlestick."}, {"verse": 16, "start": 287.49, "end": 296.95, "ta": "சமுகத்தப்பங்களை வைக்கும் ஒவ்வொரு மேஜைக்கும் நிறையின்படி வேண்டிய பொன்னையும், வெள்ளி மேைஐகளுக்கு வேண்டிய வெள்ளியையும்,", "en": "And by weight he gave gold for the tables of shewbread, for every table; and likewise silver for the tables of silver:"}, {"verse": 17, "start": 296.95, "end": 313.54, "ta": "முள்குறடுகளுக்கும் கலங்களுக்கும் தட்டுகளுக்கும் வேண்டிய பசும்பொன்னையும், பொன் கிண்ணிகளில் ஒவ்வொரு கிண்ணிக்கும் நிறையின்படி வேண்டியதையும், வெள்ளிக்கிண்ணிகளில் ஒவ்வொரு கிண்ணிக்கும் நிறையின்படி வேண்டியதையும்,", "en": "Also pure gold for the fleshhooks, and the bowls, and the cups: and for the golden basons he gave gold by weight for every bason; and likewise silver by weight for every bason of silver:"}, {"verse": 18, "start": 313.54, "end": 328.96, "ta": "தூபங்காட்டும் பீடத்திற்கு நிறையின்படி வேண்டிய புடமிடப்பட்ட பொன்னையும் கொடுத்து, செட்டைகளை விரித்துக் கர்த்தருடைய உடன்படிக்கைப்பெட்டியை மூடும் பொன் கேருபீன்களான வாகனத்தின் மாதிரியையும் கொடுத்து,", "en": "And for the altar of incense refined gold by weight; and gold for the pattern of the chariot of the cherubims, that spread out their wings , and covered the ark of the covenant of the LORD ."}, {"verse": 19, "start": 328.96, "end": 339.97, "ta": "இந்த மாதிரியின்படி சகல வேலைகளும் எனக்குத் தெரியப்படுத்த, இவையெல்லாம் கர்த்தருடைய கரத்தினால் எனக்கு எழுதிக்கொடுக்கப்பட்டது என்றான்.", "en": "All this, said David , the LORD made me understand in writing by his hand upon me, even all the works of this pattern."}, {"verse": 20, "start": 339.97, "end": 366.94, "ta": "தாவீது தன் குமாரனாகிய சாலொமோனை நோக்கி: நீ பலங்கொண்டு தைரியமாயிருந்து, இதை நடப்பி; நீ பயப்படாமலும் கலங்காமலும் இரு; தேவனாகிய கர்த்தர் என்னும் என் தேவன் உன்னோடே இருப்பார்; கர்த்தருடைய ஆலயத்தைக் கட்டுகிறதற்கடுத்த சகல கிரியைகளையும் நீ முடித்துத் தீருமட்டும், அவர் உன்னைவிட்டு விலகவுமாட்டார், உன்னைக் கைவிடவுமாட்டார்.", "en": "And David said to Solomon his son, Be strong and of good courage, and do it: fear not, nor be dismayed: for the LORD God, even my God, will be with thee; he will not fail thee, nor forsake thee, until thou hast finished all the work for the service of the house of the LORD ."}, {"verse": 21, "start": 366.94, "end": 388.26, "ta": "இதோ, தேவனுடைய ஆலயத்துவேலைக்கெல்லாம் ஆசாரியர் அவருடைய வகுப்புகள் இருக்கிறது; அந்த எல்லாக் கிரியைக்கும் சகலவித வேலையிலும் நிபுணரான மனப்பூர்வமுள்ள சகல மனுஷரும், உன் சொற்படியெல்லாம் கேட்கும் பிரபுக்களும், சகல ஜனங்களும் என்னிடத்தில் இருக்கிறார்கள் என்றான்.", "en": "And, behold, the courses of the priests and the Levites, even they shall be with thee for all the service of the house of God: and there shall be with thee for all manner of workmanship every willing skilful man, for any manner of service: also the princes and all the people will be wholly at thy commandment."}]}, "29": {"chapter": 29, "duration": 471.27, "audio_url": "audio_ot/OT13_29.mp3", "total_verses": 30, "verses": [{"verse": 1, "start": 3.8, "end": 22.4, "ta": "பின்பு தாவீதுராஜா சபையார் எல்லாரையும் நோக்கி: தேவன் தெரிந்துகொண்ட என் குமாரனாகிய சாலொமோன் இன்னும் வாலிபனும் இளைஞனுமாயிருக்கிறான்; செய்யவேண்டிய வேலையோ பெரியது; அது ஒரு மனுஷனுக்கு அல்ல, தேவனாகிய கர்த்தருக்குக் கட்டும் அரமனை.", "en": "Furthermore David the king said unto all the congregation, Solomon my son, whom alone God hath chosen, is yet young and tender, and the work is great: for the palace is not for man, but for the LORD God."}, {"verse": 2, "start": 22.4, "end": 52.79, "ta": "நான் என்னாலே இயன்றமட்டும் என் தேவனுடைய ஆலயத்துக்கென்று பொன்வேலைக்குப் பொன்னையும், வெள்ளிவேலைக்கு வெள்ளியையும், வெண்கலவேலைக்கு வெண்கலத்தையும், இரும்புவேலைக்கு இரும்பையும், மரவேலைக்கு மரத்தையும், பதிக்கப்படத்தக்க, அந்தியுள்ள கற்களையும், பலவருணக் கற்களையும், விலையேறப்பெற்ற சகலவித ரத்தினங்களையும், வெண்கற்பாளங்களையும், கோமேதக முதலிய கற்களையும் ஏராளமாகச் சவதரித்தேன்.", "en": "Now I have prepared with all my might for the house of my God the gold for things to be made of gold, and the silver for things of silver, and the brass for things of brass, the iron for things of iron, and wood for things of wood; onyx stones, and stones to be set, glistering stones, and of divers colours, and all manner of precious stones, and marble stones in abundance."}, {"verse": 3, "start": 52.79, "end": 69.49, "ta": "இன்னும் என் தேவனுடைய ஆலயத்தின்மேல் நான் வைத்திருக்கிற வாஞ்சையினால், பரிசுத்த ஆலயத்துக்காக நான் சவதரித்த அனைத்தையும் தவிர, எனக்குச் சொந்தமான பொன்னையும் வெள்ளியையும் என் தேவனுடைய ஆலயத்துக்கென்று கொடுக்கிறேன்.", "en": "Moreover, because I have set my affection to the house of my God, I have of mine own proper good, of gold and silver, which I have given to the house of my God, over and above all that I have prepared for the holy house,"}, {"verse": 4, "start": 69.49, "end": 91.26, "ta": "அறைகளின் சுவர்களை மூடுவதற்காகவும், பொன்வேலைக்குப் பொன்னும், வெள்ளிவேலைக்கு வெள்ளியும் உண்டாயிருக்கிறதற்காகவும், கம்மாளர் செய்யும்வேலை அனைத்திற்காகவும, ஓப்பீரின் தங்கமாகிய மூவாயிரம் தாலந்து தங்கத்தையும், சுத்த வெள்ளியாகிய ஏழாயிரம் தாலந்து வெள்ளியையும் கொடுக்கிறேன்.", "en": "Even three thousand talents of gold, of the gold of Ophir, and seven thousand talents of refined silver, to overlay the walls of the houses withal:"}, {"verse": 5, "start": 91.26, "end": 100.11, "ta": "இப்போதும் உங்களில் இன்றையதினம் கர்த்தருக்குத் தன் கைக்காணிக்கைகளைச் செலுத்த மனப்பூர்வமானவர்கள் யார் என்றான்.", "en": "The gold for things of gold, and the silver for things of silver, and for all manner of work to be made by the hands of artificers. And who then is willing to consecrate his service this day unto the LORD ?"}, {"verse": 6, "start": 100.11, "end": 114.77, "ta": "அப்பொழுது வம்சங்களின் பிரபுக்களும், இஸ்ரவேல் கோத்திரங்களின் பிரபுக்களும், ஆயிரம்பேருக்கு அதிபதிகளும், நூறுபேருக்கு அதிபதிகளும், ராஜாவின் வேலைக்காரராகிய பிரபுக்களும் மனப்பூர்வமாய்,", "en": "Then the chief of the fathers and princes of the tribes of Israel, and the captains of thousands and of hundreds, with the rulers of the king’s work, offered willingly,"}, {"verse": 7, "start": 114.77, "end": 131.1, "ta": "தேவனுடைய ஆலயத்து வேலைக்கு ஐயாயிரம் தாலந்து பொன்னையும், பதினாயிரம் தங்கக்காசையும், பதினாயிரம் தாலந்து வெள்ளியையும், பதினெண்ணாயிரம் தாலந்து வெண்கலத்தையும், லட்சம் தாலந்து இரும்பையும் கொடுத்தார்கள்.", "en": "And gave for the service of the house of God of gold five thousand talents and ten thousand drams, and of silver ten thousand talents, and of brass eighteen thousand talents, and one hundred thousand talents of iron."}, {"verse": 8, "start": 131.1, "end": 142.59, "ta": "யார் கையில் ரத்தினங்கள் இருந்ததோ, அவர்கள் அவைகளையும் கர்த்தருடைய ஆலயத்துப் பொக்கிஷத்திற்கென்று கெர்சோனியனான யெகியேலின் கையிலே கொடுத்தார்கள்.", "en": "And they with whom precious stones were found gave them to the treasure of the house of the LORD , by the hand of Jehiel the Gershonite."}, {"verse": 9, "start": 142.59, "end": 156.73, "ta": "இப்படி மனப்பூர்வமாய்க் கொடுத்ததற்காக ஜனங்கள் சந்தோஷப்பட்டார்கள்; உத்தம இருதயத்தோடே உற்சாகமாய்க் கர்த்தருக்குக் கொடுத்தார்கள்; தாவீது ராஜாவும் மிகவும் சந்தோஷப்பட்டான்.", "en": "Then the people rejoiced, for that they offered willingly, because with perfect heart they offered willingly to the LORD : and David the king also rejoiced with great joy."}, {"verse": 10, "start": 156.73, "end": 172.38, "ta": "ஆகையால் தாவீது சபை அனைத்தின் கண்களுக்கு முன்பாகவும் கர்த்தருக்கு ஸ்தோத்திரம் செலுத்திச் சொன்னது எங்கள் தகப்பனாகிய இஸ்ரவேலின் தேவனாகிய கர்த்தாவே, சதாகாலங்களிலும் தேவரீருக்கு ஸ்தோத்திரம் உண்டாவதாக.", "en": "Wherefore David blessed the LORD before all the congregation: and David said, Blessed be thou, LORD God of Israel our father, for ever and ever."}, {"verse": 11, "start": 172.38, "end": 191.28, "ta": "கர்த்தாவே, மாட்சிமையும் வல்லமையும் மகிமையும் ஜெயமும் மகத்துவமும் உம்முடையவைகள்; வானத்திலும் பூமியிலும் உள்ளவைகளெல்லாம் உம்முடையவைகள்; கர்த்தாவே, ராஜ்யமும் உம்முடையது; தேவரீர் எல்லாருக்கும் தலைவராய் உயர்ந்திருக்கிறீர்.", "en": "Thine, O LORD , is the greatness, and the power, and the glory, and the victory, and the majesty: for all that is in the heaven and in the earth is thine; thine is the kingdom, O LORD , and thou art exalted as head above all."}, {"verse": 12, "start": 191.28, "end": 207.45, "ta": "ஐசுவரியமும் கனமும் உம்மாலே வருகிறது; தேவரீர் எல்லாவற்றையும் ஆளுகிறவர்; உம்முடைய கரத்திலே சத்துவமும் வல்லமையும் உண்டு; எவரையும் மேன்மைப்படுத்தவும் பலப்படுத்தவும் உம்முடைய கரத்தினால் ஆகும்.", "en": "Both riches and honour come of thee, and thou reignest over all; and in thine hand is power and might; and in thine hand it is to make great, and to give strength unto all."}, {"verse": 13, "start": 207.45, "end": 216.15, "ta": "இப்போதும் எங்கள் தேவனே, நாங்கள் உமக்கு ஸ்தோத்திரம் செலுத்தி, உமது மகிமையுள்ள நாமத்தைத் துதிக்கிறோம்.", "en": "Now therefore, our God, we thank thee, and praise thy glorious name."}, {"verse": 14, "start": 216.15, "end": 231.12, "ta": "இப்படி மனப்பூர்வமாய்க் கொடுக்கும் திராணி உண்டாவதற்கு நான் எம்மாத்திரம்? என் ஜனங்கள் எம்மாத்திரம்? எல்லாம் உம்மால் உண்டானது; உமது கரத்திலே வாங்கி உமக்குக் கொடுத்தோம்.", "en": "But who am I, and what is my people, that we should be able to offer so willingly after this sort? for all things come of thee, and of thine own have we given thee."}, {"verse": 15, "start": 231.12, "end": 247.22, "ta": "உமக்கு முன்பாக நாங்கள் எங்களுடைய பிதாக்கள் எல்லாரைப்போலும் அரதேசிகளும் பரதேசிகளுமாயிருக்கிறோம்; பூமியின்மேல் எங்கள் நாட்கள் ஒரு நிழலைப்போல இருக்கிறது; நிலைத்திருப்போம் என்னும் நம்பிக்கையில்லை.", "en": "For we are strangers before thee, and sojourners, as were all our fathers: our days on the earth are as a shadow, and there is none abiding."}, {"verse": 16, "start": 247.22, "end": 263.39, "ta": "எங்கள் தேவனாகிய கர்த்தாவே, உம்முடைய பரிசுத்த நாமத்திற்கென்று உமக்கு ஒரு ஆலயத்தைக் கட்டுகிறதற்கு, நாங்கள் சவதரித்திருக்கிற இந்தப்பொருள்கள் எல்லாம் உமது கரத்திலிருந்து வந்தது; எல்லாம் உம்முடையது.", "en": "O LORD our God, all this store that we have prepared to build thee an house for thine holy name cometh of thine hand, and is all thine own."}, {"verse": 17, "start": 263.39, "end": 284.41, "ta": "என் தேவனே, நீர் இருதயத்தைச் சோதித்து, உத்தம குணத்தில் பிரியமாயிருக்கிறீர் என்பதை அறிவேன்; இவையெல்லாம் நான் உத்தம இருதயத்தோடே மனப்பூர்வமாய்க் கொடுத்தேன்; இப்பொழுது இங்கேயிருக்கிற உம்முடைய ஜனமும் உமக்கு மனப்பூர்வமாய்க் கொடுக்கிறதைக் கண்டு சந்தோஷித்தேன்.", "en": "I know also, my God, that thou triest the heart, and hast pleasure in uprightness. As for me, in the uprightness of mine heart I have willingly offered all these things: and now have I seen with joy thy people, which are present here, to offer willingly unto thee."}, {"verse": 18, "start": 284.41, "end": 300.51, "ta": "ஆபிரகாம் ஈசாக்கு இஸ்ரவேல் என்னும் எங்கள் பிதாக்களின் தேவனாகிய கர்த்தாவே, உமது ஜனத்தின் இருதயத்தில் உண்டான இந்தச் சிந்தையையும் நினைவையும் என்றைக்கும் காத்து, அவர்கள் இருதயத்தை உமக்கு நேராக்கியருளும்.", "en": "O LORD God of Abraham, Isaac, and of Israel, our fathers, keep this for ever in the imagination of the thoughts of the heart of thy people, and prepare their heart unto thee:"}, {"verse": 19, "start": 300.51, "end": 320.24, "ta": "என் குமாரனாகிய சாலொமோன் உம்முடைய கற்பனைகளையும் உம்முடைய சாட்சிகளையும் உம்முடைய கட்டளைகளையும் கைக்கொள்ளும்படிக்கும், இவைகள் எல்லாவற்றையும் செய்து, நான் ஆயத்தம்பண்ணின இந்த அரமனையைக்கட்டும்படிக்கும், அவனுக்கு உத்தம இருதயத்தைத் தந்தருளும் என்றான்.", "en": "And give unto Solomon my son a perfect heart, to keep thy commandments, thy testimonies, and thy statutes, and to do all these things , and to build the palace, for the which I have made provision."}, {"verse": 20, "start": 320.24, "end": 338.91, "ta": "அதின்பின்பு தாவீது சபை அனைத்தையும் நோக்கி: இப்போது உங்கள் தேவனாகிய கர்த்தரை ஸ்தோத்திரியுங்கள் என்றான்; அப்பொழுது சபையார் எல்லாரும் தங்கள் பிதாக்களின் தேவனாகிய கர்த்தரை ஸ்தோத்திரித்து, தலை குனிந்து கர்த்தரையும் ராஜாவையும் பணிந்துகொண்டு,", "en": "And David said to all the congregation, Now bless the LORD your God. And all the congregation blessed the LORD God of their fathers, and bowed down their heads, and worshipped the LORD , and the king."}, {"verse": 21, "start": 338.91, "end": 357.06, "ta": "கர்த்தருக்குப் பலியிட்டு, மறுநாளிலே சர்வாங்க தகனபலிகளாக ஆயிரம் காளைகளையும், ஆயிரம் ஆட்டுக்கடாக்களையும், ஆயிரம் ஆட்டுக்குட்டிகளையும், அவைகளுக்கடுத்த பானபலிகளையும் இஸ்ரவேல் அனைத்திற்காகவும் கர்த்தருக்குச் செலுத்தினார்கள்.", "en": "And they sacrificed sacrifices unto the LORD , and offered burnt offerings unto the LORD , on the morrow after that day, even a thousand bullocks, a thousand rams, and a thousand lambs, with their drink offerings, and sacrifices in abundance for all Israel:"}, {"verse": 22, "start": 357.06, "end": 374.97, "ta": "அவர்கள் அன்றையதினம் மிகுந்த சந்தோஷத்தோடு கர்த்தருக்கு முன்பாகப் போஜனபானம்பண்ணி, தாவீதின் குமாரனாகிய சாலொமோனை இரண்டாம்விசை ராஜாவாக்கி, கர்த்தருக்கு முன்பாக அவனை அதிபதியாகவும், சாதோக்கை ஆசாரியனாகவும் அபிஷேகம்பண்ணினார்கள்.", "en": "And did eat and drink before the LORD on that day with great gladness. And they made Solomon the son of David king the second time, and anointed him unto the LORD to be the chief governor, and Zadok to be priest."}, {"verse": 23, "start": 374.97, "end": 390.32, "ta": "அப்படியே சாலொமோன் தன் தகப்பனாகிய தாவீதின் ஸ்தானத்திலே, கர்த்தருடைய சிங்காசனத்தில் ராஜாவாய் வீற்றிருந்து பாக்கியசாலியாயிருந்தான்; இஸ்ரவேலர் எல்லாரும் அவனுக்குக் கீழ்ப்படிந்திருந்தார்கள்.", "en": "Then Solomon sat on the throne of the LORD as king instead of David his father, and prospered; and all Israel obeyed him."}, {"verse": 24, "start": 390.32, "end": 399.69, "ta": "சகல பிரபுக்களும் பராக்கிரமசாலிகளும் தாவீது ராஜாவினுடைய சகல குமாரருங்கூட ராஜாவாகிய சாலொமோனுக்கு அடங்கியிருந்தார்கள்.", "en": "And all the princes, and the mighty men, and all the sons likewise of king David, submitted themselves unto Solomon the king."}, {"verse": 25, "start": 399.69, "end": 413.6, "ta": "இஸ்ரவேலர் எல்லாரும் காணக் கர்த்தர் சாலொமோனை மிகவும் பெரியவனாக்கி, அவனுக்கு முன்னே இஸ்ரவேலில் ராஜாவான ஒருவனுக்கும் இல்லாதிருந்த ராஜரிக மகத்துவத்தை அவனுக்குக் கட்டளையிட்டார்.", "en": "And the LORD magnified Solomon exceedingly in the sight of all Israel, and bestowed upon him such royal majesty as had not been on any king before him in Israel."}, {"verse": 26, "start": 413.6, "end": 420.1, "ta": "இவ்விதமாய் ஈசாயின் குமாரனாகிய தாவீது இஸ்ரவேல் அனைத்துக்கும் ராஜாவாயிருந்தான்.", "en": "Thus David the son of Jesse reigned over all Israel."}, {"verse": 27, "start": 420.1, "end": 430.61, "ta": "அவன் இஸ்ரவேலை அரசாண்ட நாட்கள் நாற்பதுவருஷம்; எப்ரோனிலே ஏழுவருஷமும், எருசலேமிலே முப்பத்துமூன்று வருஷமும் ராஜாவாயிருந்தான்.", "en": "And the time that he reigned over Israel was forty years; seven years reigned he in Hebron, and thirty and three years reigned he in Jerusalem."}, {"verse": 28, "start": 430.61, "end": 441.8, "ta": "அவன் தீர்க்காயுசும் ஐசுவரியமும் மகிமையுமுள்ளவனாய் நல்ல முதிர்வயதிலே மரணமடைந்தபின், அவன் குமாரனாகிய சாலொமோன் அவன் ஸ்தானத்திலே அரசாண்டான்.", "en": "And he died in a good old age, full of days, riches, and honour: and Solomon his son reigned in his stead."}, {"verse": 29, "start": 441.8, "end": 456.54, "ta": "தாவீது ராஜாவினுடைய ஆதியோடந்தமான நடபடிகளும், அவன் அரசாண்ட விபரமும், அவனுடைய வல்லமையும், அவனுக்கும் இஸ்ரவேலுக்கும், அந்தந்த தேசங்களின் ராஜ்யங்கள் அனைத்துக்கும் நடந்த காலசம்பவங்களும்,", "en": "Now the acts of David the king, first and last, behold, they are written in the book of Samuel the seer, and in the book of Nathan the prophet, and in the book of Gad the seer,"}, {"verse": 30, "start": 456.54, "end": 469.77, "ta": "ஞானதிருஷ்டிக்காரனாகிய சாமுவேலின் பிரபந்தத்திலும், தீர்க்கதரிசியாகிய நாத்தானின் பிரபந்தத்திலும், ஞானதிருஷ்டிக்காரனாகிய காத்தின் பிரபந்தத்திலும் எழுதியிருக்கிறது.", "en": "With all his reign and his might, and the times that went over him, and over Israel, and over all the kingdoms of the countries."}]}}};
}
